    & + \gamma_5\log\widehat{\text{Rain}}(B_i,t)\times\text{ClimateType}(B_i,t)+\gamma_6\text{covid}+\gamma_7\log\text{PopDensity}(B_i,t)+\varphi(B_i,t)
    \end{aligned}
\end{equation}

