\title{Judicious Partitions in Edge-Weighted Graphs with Bounded Maximum Weighted Degree}




\newcommand{\D}{\mathcal{D}}


\begin{document}


	\date{}

	\maketitle
	\begin{abstract}
        In this paper, we investigate bounds for the following
            judicious $k$-partitioning problem: Given an edge-weighted
            graph $G$, find a $k$-partition $(V_1,V_2,\dots ,V_k)$ of
          $V(G)$
            such that the total weight of edges in the heaviest induced
            subgraph, $\max_{i=1}^k w(G[V_i])$, is minimized. In our bounds,
            we also take into account the weight $w(V_1,V_2,\dots,V_k)$ of the
            cut induced by the partition (i.e., the total weight of edges
            with endpoints in different parts) and show the existence of a
            partition satisfying tight bounds for both quantities
            simultaneously.
            We establish such tight bounds for the case $k=2$
                and, to the best of our knowledge, present the first \GG{(even for unweighted graphs)
                completely tight bound for \MA{$k=3$}. We also show that,
                in general, these results cannot be extended to \(k \geq
                4\) without introducing an additional lower-order term, and
                we propose a corresponding conjecture. Moreover, we prove
                that there always exists a \(k\)-partition satisfying  $
\max \left\{ w(G[V_i]) : i \in [k] \right\} \leq \frac{w(G)}{k^2} + \frac{k - 1}{2k^2} \Delta_w(G),
$
where \(\Delta_w(G)\) denotes the maximum weighted degree of \(G\). This bound is tight for every integer $k\geq 2$. 
}
	\end{abstract}




    \section{Introduction}
\GG{For a graph $H$, let $e(H)=|E(H)|.$ A $k$-{\em partition} $(V_1,V_2,\dots ,V_k)$ of a graph $G$ is a partition of $V(G)$ into $k$ disjoint non-empty  parts $V_i$, $i\in [k]$.}
    In a \textit{judicious partitioning problem}, the goal is to find a
    partition of the vertices of a graph which \GG{maximizes/minimizes} several quantities
    simultaneously. The systematic study of the following judicious
    partitioning problem was initiated by Bollob\'{a}s and Scott in
    \cite{BollobasScott93}: Given a graph $G$, find a $k$-partition
    \GG{$(V_1,V_2,\dots ,V_k)$ of $G$} minimizing $\max_{i=1}^k e(G[V_i])$. This
    is related to the well-studied classic Max $k$-Cut problem, which can
    be viewed as asking for a partition minimizing the sum of $e(G[V_i])$
    over $i \in [k]$ instead of the maximum. 


    An interesting problem is to determine best-possible upper bounds for
    the objective of these problem in terms of some chosen parameter of the
    input graph (e.g. number of vertices/edges, maximum degree, etc.). This
    problem has been studied extensively for both the above judicious
    partitioning problem
    \cite{BollobasScott93,BollobasScott99,BollobasScott02,BollobasScott04,BollobasScott10,XuYu09,XuYu11,AlonEtAl03}
    and the Max Cut problem
    \cite{BollobasScott02Cut,ErdosGyarfasKohayakawa97,Edwards74}.


    It was shown by Edwards \cite{Edwards74} that any graph $G$ admits a
    bipartition $(V_1,V_2)$  such that the number $ e(V_1,V_2)$ of edges between $V_1$ and $V_2$ has the following lower bound
    \begin{equation}
        \label{eq:edwards}
        e(V_1,V_2) \geq \frac{e(G)}{2} + \sqrt{\frac{e(G)}{8}+\frac{1}{64}} - \frac{1}{8}
    \end{equation}
    and this bound is tight for the complete graphs of odd order.
    Bollob\'{a}s and Scott \cite{BollobasScott99} extended this result to
    show that one can in fact find a bipartition $(V_1,V_2)$ such that both
    Edwards' bound \eqref{eq:edwards} is satisfied and
    $\max\{e(G[V_1]),e(G[V_2])\}$ is small. In particular, they showed the
    following:


    %The judicious partitioning problem for $k=2$ was first studied under
    %the name of the \textit{Bottleneck Bipartition Problem} introduced by
    %Entringer \cite{Porter92}. 


    %Answering a conjecture of
    %Erd\H{o}s, Porter \cite{Porter92} showed that any graph $G$ admits a
    %bipartition $(V_1,V_2)$ such that \[
    %    \max \{e(G[V_1]),e(G[V_2])\} \leq \frac{e(G)}{4} + \sqrt{\frac{e(G)}{8}}.
%\] 


    \begin{thm}\cite{BollobasScott99}\label{thm:BS}
        Any graph $G$ admits a bipartition \GG{$(V_1,V_2)$} such that
        \MA{both}
        \begin{itemize}
        \item[(i)]
            $ e(V_1,V_2) \geq \frac{e(G)}{2} + \sqrt{\frac{e(G)}{8}+\frac{1}{64}} - \frac{1}{8}$ and
            \item[(ii)] $
            \max\{e(G[V_1]),e(G[V_2])\} \leq \frac{e(G)}{4} + \sqrt{\frac{e(G)}{32}+
            \frac{1}{256}}-\frac{1}{16}$.
    \end{itemize}
    \end{thm}


    Note that (ii) is also tight for the complete graphs of odd order.
    Furthermore, Bollob\'{a}s and Scott \cite{BollobasScott99} partially
    extended \YZ{Part (ii) of} Theorem \ref{thm:BS} to $k > 2$ by
    showing that any graphs $G$ admits a $k$-partition  \GG{$(V_1,V_2,\dots , V_k)$} such that 
    \begin{equation}
        \label{eq:BSk}
        \max_{i\in [k]} e(G[V_i]) \leq \frac{e(G)}{k^2} +
        \frac{k-1}{2k^2}\left(\sqrt{2e(G)+\frac{1}{4}}-\frac{1}{2}\right)
    \end{equation}
    which is tight for $K_{kn+1}$ for all positive integers $n$. 


    This raises the natural question of whether one can simultaneously
    demand both \eqref{eq:BSk} and a bound analogous to Edwards' bound
    for $k > 2$ \cite[Problem 1]{BollobasScott02}. The
    following analogue to Edward's bound was obtained in
    \cite{BollobasScott02Cut}: Any graph $G$ admits a $k$-partition
    \GG{$( V_1,V_2,\dots,V_k)$} such that \GG{the total number of edges between distinct parts}
    \begin{equation}
        \label{eq:edwardsk}
        e(V_1,V_2,\dots,V_k) \geq \frac{k-1}{k}e(G) +
        \frac{k-1}{2k}\left(\sqrt{2e(G)+\frac{1}{4}} \GG{- \frac{1}{2}}\right) -
        \frac{(k-2)^2}{8k} 
    \end{equation}
    and this is tight for the complete graphs $K_{kn+1}$ for all positive
    integers $n$.\footnote{Note that \cite{BollobasScott02} contains an
    error in \eqref{eq:edwardsk} (see \cite{XuYu11} and
    \cite{WuHou22}).}


    An affirmative answer to whether one can demand both \eqref{eq:BSk} and
    \eqref{eq:edwardsk} simultaneously \GG{subject to an $O(k)$ term in \eqref{eq:edwardsk}} was given by Xu and Yu
    \cite{XuYu09,XuYu11} who showed the following:


    \begin{thm}\cite{XuYu11}\label{thm:XuYu}
        Any graph $G$ admits a $k$-partition \GG{$(V_1,V_2,\dots , V_k)$} such
        that \MA{both}
        \begin{itemize}
            \item[\MA{(i)}] $e(V_1,V_2,\dots,V_k) \geq \frac{k-1}{k}e(G) +
                \frac{k-1}{2k}\left(\sqrt{2e(G)+\frac{1}{4}}-\frac{1}{2}\right)
                -\frac{17k}{8}$ and
            \item[\MA{(ii)}] $\max_{i=1}^k e(G[V_i]) \leq \frac{e(G)}{k^2} +
                \frac{k-1}{2k^2}\left(\sqrt{2e(G)+\frac{1}{4}}-\frac{1}{2}\right)$.
        \end{itemize}
    \end{thm}


    The bound in \GG{Part (i)  of Theorem \ref{thm:XuYu} is }tight up to the $O(k)$ term
    as shown by the complete graphs $K_{nk+1}$ for positive
    integers $n$.

\GG{    To the best of our knowledge, there is only one general result for unweighted graphs of bounded maximum degree, which is as follows.


    \begin{thm}\label{thm:maxodddegree}\cite{BollobasScott04} 
For a graph $G$ of maximum odd degree $\Delta(G)$, there is a bipartition
\GG{$(V_1, V_2)$} such that \MA{both}
\begin{itemize}
 \item[(i)]   $e(V_1,V_2)\ge \frac{\Delta(G) + 1}{2\Delta(G)} e(G)$ and
 \item[(ii)] $\max\{e(G[V_1]),e(G[V_2])\}\le \frac{\Delta(G) - 1}{4\Delta(G)} e(G) + \frac{\Delta(G) - 1}{4}.$ 
 \end{itemize}
 \end{thm}


No extension of Theorem \ref{thm:maxodddegree} to $k>2$ has been obtained in the literature. 
 }


    \2


    \subsection{Our contribution}
    \setcounter{equation}{0}

    \GG{ This paper continues a line of previous papers \cite{AiGGYZ24,GerkeGYZ24,GutYeo23} which proved many results on the Maximum Weight Cut problem for undirected and directed graphs and the Maximum Weight Bisection problem for undirected 
    graphs. }  \MA{More precisely}, we study the following weighted generalization of the
    above judicious partitioning problem: Given a weighted graph
    $G=(V(G),E(G),w)$ where \GG{$w:E(G)\to \mathbb{R}_{\ge 0}$}, find a $k$-partition \GG{$(V_1,V_2,\dots ,V_k)$ of
    $G$} minimizing $\max_{i=1}^k w(G[V_i])$ where
    $w(G[V_i])$ is the total weight of edges in the induced subgraph
    $G[V_i]$.


    For a weighted graph $G$, the weighted degree of a vertex $v$ is
    defined as $w(v) = \sum_{u\in N(v)} w(v,u)$ and the maximum weighted
    degree is $\Delta_w(G) = \max_{v\in V(G)} w(v)$. Furthermore, the
    average weighted degree $d_w(G)$ is defined by 

\[
        d_w(G) = \AY{ \frac{\sum_{v \in V(G)} w(v)}{|V(G)|} = } \frac{2w(G)}{|V(G)|}.
 \]

    \MA{For disjoint non-empty subsets $X_1,X_2,\dots,X_k \subseteq V$ we denote by $w(X_1,X_2,\dots,X_k)$ the
        total weight of edges with one endpoint in $X_i$ and the other in $X_j$
