			\begin{lemma}\label{lem:balancedcut}
		Let $n$ be an integer and \YZ{$t$ be the indicator for whether $n$ is even, i.e., $t=1$ if $n$ is even and 0 otherwise}. Then, the maximum cut of $G$ has weight at least $\left(\frac{1}{2}+\frac{1}{2(n-t)}\right)w(G)$. 
	\end{lemma}
	\begin{proof}
		To see this, choose a bipartition $(X, Y)$ uniformly at random from all possible bisections (i.e., bipartition $(X,Y)$ of $G$ with $||X|-|Y||\leq 1$) of $G$. \YZ{By symmetry, observe that each pair of vertices $x, y \in V(G)$ is in different partite sets with the same probability $p=\frac{\left\lfloor \frac{n}{2} \right\rfloor\cdot \left\lceil \frac{n}{2} \right\rceil}{{n \choose 2}}$. Thus, we are done by the linearity of expectation, as $p =  \frac{n+1}{2n}$ if $n$ is odd and $p= \frac{n}{2(n-1)}$ if $n$ is even. }
		\end{proof}
