	\begin{proof}
		Let $(X, Y)$ be a maximum weight cut of $G$. Then by Lemma \ref{lem:balancedcut}, we have
		\[
		w(X, Y) \geq \AY{\frac{w(G)}{2}+\frac{w(G)}{2n} =} \frac{w(G)}{2}+\frac{d_w(G)}{4}.
		\]
		For every vertex $v \in X$, we must have $w_X(v) \leq w_Y(v)$, since otherwise moving $v$ from $X$ to $Y$ would increase the cut weight, contradicting the maximality. Similarly, for every $v \in Y$, we must have $w_Y(v) \leq w_X(v)$.

		Without loss of generality, assume that $w(G[X]) \geq w(G[Y])$. If
		\[
		w(G[X]) \leq \frac{w(G)}{4} + \frac{\Delta_w(G)}{8},
		\]
		we are done. Thus, assume instead that
		\[
		w(G[X]) > \frac{w(G)}{4} + \frac{\Delta_w(G)}{8}.
		\]

		Let $(X', Y')$ (where $X'\subseteq X$ and $Y\subseteq Y'$) be a bipartition obtained from $(X, Y)$ by recursively moving vertices from $X$ to $Y$ \AY{until} the following conditions hold:
		\begin{itemize}
			\item [(a)] $w(G[X'])>\frac{w(G)}{4}+\frac{\Delta_w(G)}{8}$;\\
			\item [(b)] There exists a vertex $v\in X'$, $w(G[X'\setminus\{v\}])\leq \frac{w(G)}{4}+\frac{\Delta_w(G)}{8}$.
		\end{itemize}

		By (a), and the fact that for all $u \in X'$, $w_{Y'}(u) \geq w_Y(u) \geq w_X(u) \geq w_{X'}(u)$, we have that
		\begin{eqnarray*}
			w(X'\setminus \{v\}, Y'\cup\{v\})&=&\sum_{u\in X'\setminus\{v\}} w_{Y'\cup \{v\}}(u)\\
			&=& (\sum_{u\in X'\setminus \{v\}} w_{Y'}(u)) + w_{X'}(v)\\
			&\geq & (\sum_{u\in X'\setminus \{v\}} w_{X'}(u)) + w_{X'}(v)\\
			&=& 2w(G[X'])\\
			&>& \frac{w(G)}{2}+\frac{\Delta_w(G)}{4}. \\
		\end{eqnarray*}

		It follows from (a) and the above inequality that
		\begin{eqnarray*}
			w(Y'\cup \{v\})&=&w(G)-w(X'\setminus \{v\}, Y'\cup\{v\})-w(G[X'])+w_{X'}(v)\\
			&<&\frac{w(G)}{4}-\frac{3\Delta_w(G)}{8}+\frac{w(v)}{2}\\
			&\leq &\frac{w(G)}{4}-\frac{3\Delta_w(G)}{8}+\frac{\Delta_w(G)}{2}\\
			&=& \frac{w(G)}{4}+\frac{\Delta_w(G)}{8}, 
		\end{eqnarray*}
		where the first inequality holds as $w_{X'}(v)\leq w_{Y'}(v)$. This together with (b) implies that 
		\[\max\{w(G[X'\setminus \{v\}]), w(G[Y'\cup \{v\}])\}\leq \frac{w(G)}{4}+\frac{\Delta_w(G)}{8}. \]
		This completes the proof since $w(X'\setminus \{v\}, Y'\cup\{v\})>\frac{w(G)}{2}+\frac{\Delta_w(G)}{4}\geq \frac{w(G)}{2}+\frac{d_w(G)}{4}$. 
	\end{proof}

	Note that both bounds (i) and (ii) are tight when $ G $ is an unweighted complete graph with an odd number of vertices. Moreover, the term $ \frac{d_w(G)}{4} $ in the first bound cannot, in general, be replaced by $ \frac{\Delta_w(G)}{4} $. In fact, as the following proposition shows, we cannot guarantee a cut of weight at least $ \frac{w(G)}{2} + c \cdot \Delta_w(G) $, even for arbitrarily small constants $ c > 0 $.

	\begin{prop}
		For any positive real number $ c > 0 $, there exists a weighted graph $ G=(V(G),E(G),w) $ such that the weight of every cut in $ G $ is less than $ \frac{w(G)}{2} + c \cdot \Delta_w(G) $.
	\end{prop} 

	\begin{proof}
		Fix any positive real number $ c \leq \frac{1}{4} $, and let $ n $ be an integer greater than $ 1/4c^2$. Construct a graph $ G $ by starting with the complete graph $ K_n $, assigning weight 1 to all its edges, and then adding a new vertex $ v $ connected to every vertex in $ K_n $ with edges of weight $ 2cn $. Note that $2cn > 1/2c\geq 2 $ as $n>1/4c^2$.

		In this construction:
		\[
		\Delta_w(G) = 2cn^2 \quad \text{and} \quad w(G) = 2cn^2 + \binom{n}{2}.
		\]

		Now consider a maximum weight cut $(X, Y)$. Suppose $ v \in X $, and let $ a $ be the number of vertices from $ K_n $ that are in $Y$, so $ 1 \leq a \leq n $. The weight of cut is now
		\[
		f(a) = a(2cn + n - a),
		\]
		which is a quadratic function in $ a $ and therefore bounded above by its maximum value $(c+\frac{1}{2})^2n^2$. Thus,
		\begin{eqnarray*}
			\frac{w(G)}{2}+c\cdot\Delta_w(G)-f(a)&\geq&\frac{w(G)}{2}+c\cdot\Delta_w(G)-(c+\frac{1}{2})^2n^2\\
			&=&cn^2+\frac{n(n-1)}{4}+2c^2n^2-c^2n^2-cn^2-\frac{n^2}{4}\\
			&=& c^2n^2-\frac{n}{4}\\
			&>& \frac{n}{4}-\frac{n}{4}=0,
		\end{eqnarray*}
		where the last inequality holds as $n>1/4c^2$, completing the proof. 
	\end{proof}

Conversely, the following proposition can be proved by considering a graph obtained by adding a sufficient number of isolated vertices to a complete graph. 

 \begin{prop}
 		For any positive real number $ c > 0$, there exists a weighted graph $ G=(V(G),E(G),w) $ such that for all cuts $(X,Y)$ of $G$, $\max\{w(G[X]),w(G[Y])\}> \frac{w(G)}{4}+c\cdot d_w(G)$. 
 \end{prop}


