				&=& \frac{4w(G)-3\theta}{3}-\frac{2-c}{3}\Delta_w(G),
			\end{array}
			\]
			which implies that $\Delta_w(G)\geq \frac{4w(G)-3\theta}{3n-3n_3+2-c}$. This completes the proof of Claim \ref{cl:lbdelta}. 
		\end{proof}

		Let $(X_1',X_2')$ be a maximum cut of $G'$. Then, the following claim holds.

		\begin{claim}\label{cl:w(x1x2x3)}
Let \YZ{$t'$ be the indicator for whether $n-n_3$ is even, i.e., $t'=1$ if $n-n_3$ is even and 0 otherwise}. Then,
\[
\begin{array}{rcl}\2
	&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\frac{d_w(G)}{3}\\\2
	&\geq& \frac{3(n-n_3-t')-5+2c}{18(n-n_3-t')}\Delta_w(G)-\frac{4n-6n_3-6t'}{9n(n-n_3-t')}w(G)+\frac{\theta}{2} \left(1- \frac{1}{n-n_3-t'} \right)\\\2
	&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)}\Delta_w(G)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2} \left(1- \frac{1}{n-n_3} \right).
\end{array}
  \]
		\end{claim}
		\begin{proof}
			As $(X_1',X_2')$ is a maximum cut of $G'$, by Lemma \ref{lem:balancedcut}, \YZ{(\ref{eq:r}), (\ref{eq:w(X_3',V-X_3')}) and (\ref{eq:G'})} we have that
			\[
					\begin{array}{rcl}\2
				&~&w(X_1',X_2',X_3')- \frac{2}{3}w(G)-\frac{d_w(G)}{3}\\\2
				& = & w(X_1',X_2') + w(X_3',V(G) \setminus X_3')-\frac{2}{3}w(G)-\frac{2w(G)}{3n}\\ \2
				& \geq & \left( \frac{w(G')}{2} + \YZ{\frac{w(G')}{2(n-n_3-t')} } \right) +  \left( \frac{4w(G)}{9} + \frac{4\Delta_w(G)}{9} - r + \theta \right) -\frac{2}{3}w(G)-\frac{2w(G)}{3n}\\ \2
				& = & \frac{w(G')}{2} + \frac{w(G')}{2(n-n_3-t')} - \frac{2w(G)}{9} -\frac{2w(G)}{3n} + \frac{4\Delta_w(G)}{9} - r + \theta \nonumber\\ \2
				&\YZ{=} & \left( \frac{4w(G)}{9} - \frac{5\Delta_w(G)}{9} + 2r - \theta \right) \cdot \left( \frac{1}{2} + \frac{1}{2(n-n_3-t')} \right) \\ \2
				&~&- \frac{2w(G)}{9} -\frac{2w(G)}{3n} + \frac{4\Delta_w(G)}{9} - r + \theta \nonumber\\  \2
					&=& \frac{3(n-n_3-t')-5}{18(n-n_3-t')}\Delta_w(G)-\frac{4n-6n_3\YZ{-6t'}}{9n(n-n_3-t')}w(G)+\frac{r}{n-n_3-t'}+\frac{\theta}{2} \left(1- \frac{1}{n-n_3-t'} \right)\\ \2
					&=& \frac{3(n-n_3-t')-5+2c}{18(n-n_3-t')}\Delta_w(G)-\frac{4n-6n_3-6t'}{9n(n-n_3-t')}w(G)+\frac{\theta}{2} \left(1- \frac{1}{n-n_3-t'} \right)\\
						&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)}\Delta_w(G)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2} \left(1- \frac{1}{n-n_3} \right),
			\end{array}
			\]
			where the last inequality can be seen from the \YZ{third equality} as $t'\geq 0$. This completes the proof of Claim \ref{cl:w(x1x2x3)}. 
		\end{proof}

		Define $i$ such that $n = 3 n_3 + i$. The following claim now holds.

		\begin{claim}\label{cl:w(x1x2x3)-2}
			\YZ{If $n_3\geq 2$, then} $w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\YZ{\frac{d_w(G)}{3}}$ is at least the following
				\[
	 \frac{(1-c)\cdot(3(n-n_3-1)(n_3+1)-2(n_3-1))}{18(n-n_3)(n_3-1)}\Delta_w(G)+\frac{12n_3^2+(11i-3)n_3+3i^2+i}{9n(n-n_3)(n_3-1)} w(G).
			\]
		\end{claim}
	    \begin{proof}
	    	By Claims \ref{cl:lbtheta2} and \ref{cl:w(x1x2x3)}, we have that
	    	\[
	    			\begin{array}{rcl}\2
	    		&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\YZ{\frac{d_w(G)}{3}} \nonumber\\ \2
	    		&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)} \Delta_w(G)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}(1-\frac{1}{n-n_3})\\ \2
	    		&=& \frac{(3(n-n_3-1)-2+2c)(n_3-1)+6(n-n_3-1)-3c(n_3+1)(n-n_3-1)}{18(n-n_3)(n_3-1)}\Delta_w(G)\nonumber\\ \2
	    		&~& + \frac{3n(n-n_3-1)-(4n-6n_3)(n_3-1)}{9n(n-n_3)(n_3-1)}w(G)\nonumber\\ \2
	    		&=& \frac{(1-c)\cdot(3(n-n_3-1)(n_3+1)-2(n_3-1))}{18(n-n_3)(n_3-1)}\Delta_w(G)+\frac{n(3n-7n_3+1)-6n_3+6n_3^2}{9n(n-n_3)(n_3-1)} w(G)\nonumber\\ \2
	    		&=& \frac{(1-c)\cdot(3(n-n_3-1)(n_3+1)-2(n_3-1))}{18(n-n_3)(n_3-1)}\Delta_w(G)+\frac{12n_3^2+(11i-3)n_3+3i^2+i}{9n(n-n_3)(n_3-1)} w(G)\nonumber,
	    	\end{array}
	    	\]
	    	which completes the proof of Claim \ref{cl:w(x1x2x3)-2}.
	    \end{proof}

		\begin{claim}\label{cl:lb3cut}
			 $w(X_1',X_2',X_3') \geq \frac{2w(G)}{3} + \frac{d_w(G)}{3}$.
		\end{claim}
		\begin{proof}
        		We now consider the follwong cases.

        			{\bf Case 1, $ i \geq 1$:} 
               By Claims \ref{cl:lbtheta}, \ref{cl:lbdelta} and \ref{cl:w(x1x2x3)}, we have the following holds, where the second inequality holds as the derivative of the function $f(x)=\frac{3(n-n_3)-5+2x}{18(n-n_3)(3n_3-2+x)}$ is given by $f'(x)=\frac{1-3i}{18(n-n_3)(3n_3-2+x)^2}$, which is negative for all real values $x\geq 0$\YZ{, and therefore} as $0\leq c<3$, $f(c)\geq f(3)$. 
               \[
               \begin{array}{rcl}\2
               		&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\frac{d_w(G)}{3}\\ \2
               	&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)}\cdot \frac{2w(G)+3\theta}{3n_3-2+c}-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2} \left(1- \frac{1}{n-n_3} \right)\\ \2
               	&\geq& \frac{3(n-n_3)+1}{9(n-n_3)}\cdot \frac{w(G)}{3n_3+1}-\frac{4n-6n_3}{9n(n-n_3)}w(G)\\ \2
               		&\geq& \frac{(3(2n_3+i)+1)(3n_3+i)-(6n_3+4i)(3n_3+1)}{9n(n-n_3)(3n_3+1)}w(G)\\ \2
               		&=& \frac{(6n_3+4i+1-i)(3n_3+i)-(6n_3+4i)(3n_3+1)}{9n(n-n_3)(3n_3+1)}w(G)\\ \2
               		&=& \frac{(6n_3+4i)(i-1)+(1-i)(3n_3+i)}{9n(n-n_3)(3n_3+1)}w(G)\\ \2 
               		&=& \frac{3(n_3+i)(i-1)}{9n(n-n_3)(3n_3+1)}w(G)\\ \2
               		&\geq& 0, 
               \end{array}
               \]
which completes the proof of Case 1. 

        	{\bf Case 2, $ i\leq -5$:} By Claims \ref{cl:lbtheta}, \ref{cl:w(x1x2x3)}, and the fact that $\Delta_w(G)\geq d_w(G)=\frac{2w(G)}{n}$, we have that
        	\[
        		\begin{array}{rcl}\2
        			&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\YZ{\frac{d_w(G)}{3}} \nonumber\\ \2
        			&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)} \Delta_w(G)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}\left(1-\frac{1}{n-n_3}\right)\\\2
        			&\geq& \frac{3(n-n_3)-5}{18(n-n_3)}\cdot\frac{2w(G)}{n} -\frac{4n-6n_3}{9n(n-n_3)}w(G)\nonumber\\\2
        			&=& \frac{3(n-n_3)-5-4n+6n_3}{9n(n-n_3)}w(G) \nonumber \\\2
        			&=& \frac{-i-5}{9n(n-n_3)}w(G) \nonumber \\\2
        			&\geq & 0, \nonumber
        		\end{array}
        		\]
        		which completes the proof of Case 2. 

        			{\bf Case 3, $ i= 0$ or $-2$:} In this case, $n-n_3$ is even. Thus, by (\ref{eq:lbforn-n3}) and Claims \ref{cl:lbtheta}, \ref{cl:lbdelta} and \ref{cl:w(x1x2x3)}, we have that
        			\[
        		\begin{array}{rcl} \2
        			&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\YZ{\frac{d_w(G)}{3}} \\ \2
        			&\geq& \frac{3(n-n_3-1)-5+2c}{18(n-n_3-1)} \Delta_w(G)-\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G)
        			+ \frac{\theta}{2} \left( 1 - \frac{1}{n-n_3-1} \right)\\ \2
        			&\geq& \frac{3(n-n_3-1)-5+2c}{9(n-n_3-1)} \cdot  \frac{w(G)}{3n_3-2+c} -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G).
        		\end{array}
        		\]


        		Now consider the function  
        		$
        		f(x) = \frac{3(n - n_3 - 1) - 5 + 2x}{9(n - n_3 - 1)(3n_3 - 2 + x)}.
        		$
        		Its derivative is given by  
        		$
        		f'(x) = \frac{4 - 3i}{9(n - n_3 - 1)(3n_3 - 2 + x)^2},
        		$
        		which is positive for all real values of \( x\geq 0 \). Therefore, since \( c \geq 0 \), it follows that \( f(c) \geq f(0) \), and thus we have:
        		\[
        		\begin{array}{rcl} \2
        			&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\YZ{\frac{d_w(G)}{3}} \\ \2
        			&\geq& \frac{3(n-n_3-1)-5}{9(n-n_3-1)} \cdot  \frac{w(G)}{3n_3-2} -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G)\\ \2
        		%	&= & \frac{3(n-n_3-1)-5}{9(n-n_3-1)} \cdot  \frac{w(G)}{3n_3-2} -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G)\\ \2
        			&= & \frac{3n^2-3nn_3-8n-12nn_3+18n_3^2+18n_3+8n-12n_3-12}{9n(n-n_3-1)(3n_3-2)}w(G) \\ \2
        			&= & \frac{n^2-5nn_3+6n_3^2+2n_3-4}{3n(n-n_3-1)(3n_3-2)}w(G) \\ \2
        			&= & \frac{(n-2n_3)^2+2n_3^2-(3n_3+i)n_3+2n_3-4}{3n(n-n_3-1)(3n_3-2)}w(G) \\ \2
        			&= & \frac{(n_3+i)^2+2n_3^2-(3n_3+i)n_3+2n_3-4}{3n(n-n_3-1)(3n_3-2)}w(G) \\ \2
        			&= & \frac{(i +2)n_3+ i^2-4}{3n(n-n_3-1)(3n_3-2)}w(G), 
        		\end{array}
        		\]
        		which is non-negative as $i\in \{0,-2\}$. This completes the proof of Case 3. 

        		{\bf Case 4, $ i= -4$:} In this case $n-n_3$ is even. Thus, by \YZ{(\ref{eq:lbforn-n3}) and} Claims \ref{cl:lbtheta}, \ref{cl:lbdelta} and \ref{cl:w(x1x2x3)}, we have that
        		\[
        		\begin{array}{rcl} \2
        			&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\YZ{\frac{d_w(G)}{3}} \\ \2
        			&\geq& \frac{3(n-n_3-1)-5+2c}{18(n-n_3-1)} \Delta_w(G)-\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G)
        			+ \frac{\theta}{2} \left( 1 - \frac{1}{n-n_3-1} \right)\\ \2
        			&\geq& \frac{3(n-n_3-1)-5+2c}{18(n-n_3-1)} \cdot   \frac{4w(G)-3\theta}{3n-3n_3+2-c} -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G)+ \frac{\theta}{2}\left( 1 - \frac{1}{n-n_3-1} \right)\\ \2
        		%	&\geq& \frac{3(n-n_3-1)-5+2c}{18(n-n_3-1)} \cdot   \frac{4w(G)-3\theta}{3n-3n_3+2-c} -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G) 
        		%	+ \frac{\theta}{2} \left(1 - \frac{1}{n-n_3-1} \right)\\ \2
        			&=&\frac{6(n-n_3-1)-10+4c}{9(n-n_3-1)(3n-3n_3+2-c)}  w(G) -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G) \\ \2
        			&~& + \frac{\theta}{2} \left( 1 - \frac{1}{n-n_3-1}-\frac{3(n-n_3-1)-5+2c}{3(n-n_3-1)(3n-3n_3+2-c)} \right)\\
        			&\geq & \frac{6(n-n_3-1)-10}{9(n-n_3-1)(3n-3n_3+2)}  w(G) -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G) \\ \2
        			&~& + \frac{\theta}{2} \left( 1 - \frac{1}{n-n_3-1}-\frac{3n-3n_3-2}{3(n-n_3-1)(3n-3n_3-1)} \right)\\ \2
        			&\geq & \frac{6(n-n_3-1)-10}{9(n-n_3-1)(3n-3n_3+2)}  w(G) -\frac{4n-6n_3-6}{9n(n-n_3-1)}w(G) + \frac{\theta}{2} \left( 1 - \frac{4}{3(n-n_3-1)} \right)\\ \2
        			&\geq & \frac{6n^2-6nn_3-16n-(4n-6n_3-6)(3n-3n_3+2)}{9n(n-n_3-1)(3n-3n_3+2)} w(G), 
        		\end{array}
        		\]
        		where the last inequality follows from \YZ{Claim \ref{cl:lbtheta} and} (\ref{eq:lbforn-n3}), and the third last inequality holds as $0\leq c< 3$. Now, we only need to show $6n^2-6nn_3-16n-(4n-6n_3-6)(3n-3n_3+2)\geq 0$. Indeed,
        		\[
        		\begin{array}{rcl} \2
        			&~&	6n^2-6nn_3-16n-(4n-6n_3-6)(3n-3n_3+2)\\ \2
        			&=&  6n^2-6nn_3-16n-12n^2+18nn_3+18n+12nn_3-18n_3^2-18n_3-8n+12n_3+12\\ \2
        			&= & -6(n-2n_3)^2+6n_3^2-6n_3-6n+12\\ \2
        			&= & -6(n_3-4)^2+6n_3^2-6n_3-6(3n_3-4)+12\\ 
        			&= & 24n_3-60. 
        		\end{array}
        		\]
        		Note that by (\ref{eq:lbforn-n3}), $n-n_3=2n_3-4\geq 3$ and therefore $n_3\geq 4$. Thus, $24n_3-60>0$, which completes the proof of Case 4.  


        		\2

        		{\bf Case 5, $ i= -1$ or $-3$:} \YZ{In this case, $n_3\geq 2$ as otherwise $n=3n_3+i\leq 3-1<3$, a contradiction. We first narrow our focus by examining the lower bound provided in Claim~\ref{cl:w(x1x2x3)-2}.}

        		As $n_3\geq 2$, according to Claim~\ref{cl:w(x1x2x3)-2}, we have:
        		\[
        		\begin{array}{rcl} \2
        			w(X_1', X_2', X_3') - \frac{2}{3}w(G) - \YZ{\frac{d_w(G)}{3}}  
        			&\geq \frac{(1 - c)\cdot \big(3(n - n_3 - 1)(n_3 + 1) - 2(n_3 - 1)\big)}{18(n - n_3)(n_3 - 1)} \Delta_w(G) \\ \2
        			&\quad + \frac{12n_3^2 + (11i - 3)n_3 + 3i^2 + i}{9n(n - n_3)(n_3 - 1)} w(G).
        		\end{array}
        		\]

        		Multiplying both sides of this inequality by \(18n(n - n_3)(n_3 - 1)\), we define:
        		\[
        		\alpha = (1 - c)\cdot n \cdot \big(3(n - n_3 - 1)(n_3 + 1) - 2(n_3 - 1)\big) \Delta_w(G) + 2\big(12n_3^2 + (11i - 3)n_3 + 3i^2 + i\big) w(G).
        		\]

        		Note that if \(\alpha \geq 0\), then it follows that
        		\[
        		w(X_1', X_2', X_3') \geq \frac{2}{3}w(G) + \YZ{\frac{d_w(G)}{3}} ,
        		\]
        		in which case the proof is complete. Therefore, we proceed under the assumption that \(\alpha < 0\). 

        	  \YZ{It is not hard to check that as $i\in \{-1,-3\}$ and $n_3\geq 2$, $12n_3^2 + (11i - 3)n_3 + 3i^2 + i\geq 0$. Thus, since \(\alpha < 0\) and the term \(3(n - n_3 - 1)(n_3 + 1) - 2(n_3 - 1)\) is clearly non-negative, $1-c<0$ and therefore $c>1$. }


        		As \YZ{$\alpha<0$} and $c>1$, the following result now holds:
        		\begin{eqnarray*}
        			\Delta_w(G)>\frac{2(12n_3^2+(11i-3)n_3+3i^2+i)}{(c-1)n(3(n-n_3-1)(n_3+1)-2(n_3-1))}w(G).
        		\end{eqnarray*}
        		Furthermore, when $i=-1$, it translate to the following.
        		\begin{eqnarray}\label{eq:i=-1}
        			\Delta_w(G)&>&\frac{4(6n_3^2-7n_3+1)}{(c-1)n(6(n_3-1)(n_3+1)-2(n_3-1))}w(G)\nonumber\\
        			&=& \frac{2(n_3-1)(6n_3-1)}{(c-1)\YZ{n}(n_3-1)(3n_3+2)} w(G)\nonumber\\
        			&=& \frac{2(6n_3-1)}{(c-1)\YZ{n}(3n_3+2)} w(G)
        		\end{eqnarray}

        			Now we consider the cases $i=-1$ and $i=-3$ seperately.

        		\noindent{\bf Subcase 5.1, $i=-3$:} By Claims \ref{cl:lbtheta}, \ref{cl:lbdelta} and \ref{cl:w(x1x2x3)}, we have that
        		\[
        		\begin{array}{rcl}\2
        			&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\frac{2}{3n}w(G) \nonumber\\ \2
        			&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)} \Delta_w(G)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}(1-\frac{1}{n-n_3})\\ \2
        			&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)} \cdot \frac{4w(G)-3\theta}{3n-3n_3+2-c}-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}(1-\frac{1}{n-n_3})\\ \2
        			&\geq& \frac{n-n_3-1}{6(n-n_3)(3n-3n_3+1)} \cdot (4w(G)-3\theta)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}(1-\frac{1}{n-n_3})\\ \2
        			&=& \frac{2n_3-4}{3(2n_3-3)(3n_3-4)}\cdot w(G) -\frac{2n_3-4}{3(2n_3-3)(3n_3-3)}w(G)\\ \2
        			&~&+\frac{\theta}{2}(1-\frac{1}{n-n_3}-\frac{n-n_3-1}{(n-n_3)(3n-3n_3+1)})\\ \2
        			&\geq & \frac{\theta}{2}(1-\frac{1}{n-n_3}-\frac{1}{3(n-n_3)})\\ \2
        			&\geq & 0,
        		\end{array}
        		\]
        		where the third inequality holds as $c>1$, and the last inequality holds as $n-n_3\geq 3$ which has been shown in (\ref{eq:lbforn-n3}). This completes the proof of Subcase 5.1. 

        		\noindent{\bf Subcase 5.2, $i=-1$:} We discuss the following two cases based on the value of $c$. As $\frac{9n_3}{3n_3+1}>2$, the following two subcases exhaust all possibilities.

        		\noindent{\bf Subcase 5.2.1, $0<c-1\leq  \frac{6n_3-1}{3n_3+1}$:} By (\ref{eq:i=-1}), we have the following holds, where the second inequality holds as $f(x)=\frac{(3(n-n_3-1)+2x)(6n_3-1)}{9n(n-n_3)(3n_3+2)x}$ is clearly decreasing when $x>0$. 
        		\[
        		\begin{array}{rcl}\2
        			\frac{3(n-n_3)-5+2c}{18(n-n_3)} \Delta_w(G)&>& 	\frac{3(n-n_3)-5+2c}{18(n-n_3)}\cdot \frac{2(6n_3-1)}{(c-1)n(3n_3+2)} w(G)\\ \2
        			&=&\frac{(3(n-n_3-1)+2(c-1))(6n_3-1)}{9n(n-n_3)(3n_3+2)(c-1)} w(G)\\ \2
        			&\geq  &\frac{(3(n-n_3-1)+2\cdot \frac{6n_3-1}{3n_3+1})(6n_3-1)}{9n(n-n_3)(3n_3+2)\cdot \frac{6n_3-1}{3n_3+1}}w(G) \\ \2
        			&=& \frac{6(n_3-1)(3n_3+1)+2\cdot (6n_3-1)}{9n(n-n_3)(3n_3+2)} w(G)\\ \2
        			&=& \frac{18n_3^2-8}{9n(n-n_3)(3n_3+2)} w(G)\\ \2
        			&=& \frac{(3n_3+2)(6n_3-4)}{9n(n-n_3)(3n_3+2)} w(G)\\ \2
        			&=& \frac{4n-6n_3}{9n(n-n_3)} w(G), 
        		\end{array}
        		\]
        		which, together with Claims \ref{cl:lbtheta} and \ref{cl:w(x1x2x3)}, implies $w(X_1',X_2',X_3')\geq \frac{2}{3}w(G)+\YZ{\frac{d_w(G)}{3}} $. This completes the proof of Subcase 5.2.1.

        		\noindent{\bf Subcase 5.2.2, $c\geq 2$:} By Claims \ref{cl:lbtheta}, \ref{cl:lbdelta} and \ref{cl:w(x1x2x3)}, we have the following holds.
        		\[
        		\begin{array}{rcl} \2
        			&~&w(X_1',X_2',X_3')-\frac{2}{3}w(G)-\frac{2}{3n}w(G) \nonumber\\ \2
        			&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)} \Delta_w(G)-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}\left(1-\frac{1}{n-n_3}\right)\\ \2
        			&\geq& \frac{3(n-n_3)-5+2c}{18(n-n_3)} \cdot \frac{4w(G)-3\theta}{3n-3n_3+2-c}-\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}\left(1-\frac{1}{n-n_3}\right)\\ \2
        			&\geq& \frac{2(3(n-n_3)-1)}{27(n-n_3)^2}w(G) -\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}\left(1-\frac{1}{n-n_3}-\frac{3(n-n_3)-1}{9(n-n_3)^2}\right)\\ \2
        			&\geq& \frac{2(3(n-n_3)-1)}{27(n-n_3)^2}w(G) -\frac{4n-6n_3}{9n(n-n_3)}w(G)+\frac{\theta}{2}\left(1-\frac{1}{n-n_3}-\frac{1}{3(n-n_3)}\right)\\ \2
        			&\geq& \frac{2}{9(n-n_3)}\left(\frac{3(n-n_3)-1}{3(n-n_3)} -\frac{2n-3n_3}{n}\right)w(G)\\ \2
        			&=& \frac{2}{9(n-n_3)}\left(\frac{6n_3-4}{6n_3-3} -\frac{6n_3-4}{6n_3-2}\right)w(G)\\ \2
        			&\geq & 0,
        		\end{array}
        		\]
        		where the second last inequality follows from (\ref{eq:lbforn-n3}). This completes the proof of Case 5 and therefore the proof of Claim \ref{cl:lb3cut}.
		\end{proof}



		\2

        Now we are ready to prove this result. If $\max\{w(G[X_1']), w(G[X_2'])\} \leq \frac{w(G)}{9}+\frac{\Delta_w(G)}{9}$ then
		we would be done by Claim \ref{cl:lb3cut}. So without loss of generality assume that $w(G[X_2']) \geq w(G[X_1'])$ and 
		$w(G[X_2']) > \frac{w(G)}{9}+\frac{\Delta_w(G)}{9}$.

		While $w(G[X_2']) > \frac{w(G)}{9}+\frac{\Delta_w(G)}{9}$ take any vertex from $X_2'$ and put it into $X_1'$.
		Let $u$ be the last vertex we transfered from $X_2'$ to $X_1'$ and let $X_1''$ and $X_2''$ denote the new $X_1'$-set and
		$X_2'$-set respectively. Let $r'$ be defined such that $w(G[X_2'']) = \frac{w(G)}{9}+\frac{\Delta_w(G)}{9} - r'$ and
		note that $r' \geq 0$ and $w_{X_2''}(u) \geq r'$. As $(X_1',X_2')$ is a maximum weighted cut in $G'$ we note that 
		for any vertex in $v \in X_2'$ we have $w_{X_1'}(v) \geq w_{X_2'}(v)$. This implies that the following holds,

		\[
		w(X_2'',X_1') \geq \sum_{v \in X_2''} w_{X_2''\cup\{u\}}(v) 
		\geq 2w(G[X_2'']) + w_{X_2''}(u) 
		\geq 2 \left( \frac{w(G)}{9}+\frac{\Delta_w(G)}{9} - r' \right) + r'.
		\]

		Furthermore as $w_{X_2''}(u) \geq r'$ we get that $w(X_2'',X_1'')\geq w(X_2'',X_1')+w_{X_2''}(u) \geq \frac{2w(G)}{9}+\frac{2\Delta_w(G)}{9}$.
		This implies the following by Claim \ref{cl:r}, Claim \ref{cl:lbtheta} and (\ref{eq:w(X_3',V-X_3')}).  

		\[
		w(X_2'',X_1'',X_3') \geq \frac{6w(G)}{9} + \frac{6\Delta_w(G)}{9} - r + \theta \geq \frac{2w(G)}{3} + \frac{2\Delta_w(G)}{3} 
		- \frac{\Delta_w(G)}{3} = \frac{2w(G)}{3} + \frac{\Delta_w(G)}{3}.
		\]

		So if $w(G[X_1'']) \leq \frac{w(G)}{9}+\frac{\Delta_w(G)}{9}$, then we would be done, as $(X_2'',X_1'',X_3')$ would be the 
		desired partition (as $\Delta_w(G) \geq d_w(G)$). Note that the following holds.

		\[
		\begin{array}{rcl} \2
			w(G[X_1'']) & = & w(G) - w(X_2'',X_1'',X_3') - w(G[X_2'']) - w(G[X_3'])  \\ \2
			& \leq & w(G) - \left( \frac{6w(G)}{9} + \frac{6\Delta_w(G)}{9} - r + \theta \right) 
			- \left( \frac{w(G)}{9}+\frac{\Delta_w(G)}{9} - r' \right)
			- \left( \frac{w(G)}{9}+\frac{\Delta_w(G)}{9} - r \right) \\ \2
			& = & \frac{w(G)}{9} - \frac{8\Delta_w(G)}{9} + 2r + r' - \theta \\
			& \leq & \frac{w(G)}{9} - \frac{8\Delta_w(G)}{9} + 2r + r'. \\
		\end{array}
		\]

		If $r' \leq \frac{\Delta_w(G)-r}{2}$, then the above implies the following, as $r \leq \frac{\Delta_w(G)}{3}$ by Claim \ref{cl:r}.

		\[
		w(G[X_1'']) \leq \frac{w(G)}{9} - \frac{8\Delta_w(G)}{9} + 2r + \frac{\Delta_w(G)-r}{2} \leq \frac{w(G)}{9} + \frac{\Delta_w(G)}{9}.
		\]

		We may therefore assume that $r' > \frac{\Delta_w(G)-r}{2}$.
		However, when we transfered $u$ from $X_2'$ to $X_1'$ we noted that $w_{X_1'}(u) \geq w_{X_2'}(u) \geq r'$,
		which implies that $w_{V(G')}(u) \geq 2r' > \Delta_w(G)-r$. So $w_{X_3'}(u) < r$.
		We will now transfer $u$ from $X_1''$ to $X_3'$ and call the new sets $X_1^*$ and $X_3^*$. Let $X_2^*=X_2''$.
		Now the following holds. 

		\begin{itemize}
			\item $w(G[X_3^*]) = \frac{w(G)}{9}+\frac{\Delta_w(G)}{9} - r + w_{X_3'}(u) < \frac{w(G)}{9}+\frac{\Delta_w(G)}{9}$.
			\item $w(G[X_2^*]) = w(G[X_2'']) = \frac{w(G)}{9}+\frac{\Delta_w(G)}{9} - r' \leq \frac{w(G)}{9}+\frac{\Delta_w(G)}{9}$. 
			\item $w(G[X_1^*]) = w(G[X_1'']) - w_{X_1''}(u) \leq w(G[X_1'']) - r' \leq \frac{w(G)}{9} - \frac{8\Delta_w(G)}{9} + 2r \leq \frac{w(G)}{9}$.
		\end{itemize}

		Furthermore the following holds as, by Claim \ref{cl:r}, $r \leq \Delta_w(G)/3$.

		\[
		\begin{array}{rcl} \2
			w(X_1^*,X_2^*,X_3^*) & = & w(X_2'',X_1'',X_3') - w_{X_3'}(u) + w_{X_1''}(u) \\ \2
			& \geq & w(X_2'',X_1'',X_3') - r + r' \\ \2
			& > & \left(\frac{2w(G)}{3} + \frac{\Delta_w(G)}{3} \right) - r + \frac{\Delta_w(G)-r}{2} \\ \2
			& = & \frac{2w(G)}{3} + \frac{\Delta_w(G)}{3} + \frac{\Delta_w(G)}{2} - \frac{3r}{2} \\
			& \geq & \frac{2w(G)}{3} + \frac{\Delta_w(G)}{3}. \\
		\end{array}
		\]
		Thus, $(X_1^*,X_2^*,X_3^*)$ is now the desired 3-partition, completing the proof.
	\end{proof}

	Theorem~\ref{thm:max32} is best possible due to the following example.  Let $G = K_{3\YZ{q}+1}$ where \YZ{$q \geq 1$} is an integer and
	let all weights be 1 (i.e. consider the unweighted case).
	That is $G$ is a complete graph of order $3q+1$. It is not difficult to see that the optimal $3$-partition, $(X_1,X_2,X_3)$, of $G$ is 
	when the minimum size of a set $X_i$ and the maximum size of a set $X_j$ differ by at most one.  That is, we may assume 
	that $|X_1| = |X_2|=q$ and $|X_3|=q+1$.  In this case $w(G[X_3]) = {q+1 \choose 2}$ and 
	$w(G)= {3q+1 \choose 2}$ and $\Delta_w(G)=3q$. the following now holds.

	\[
	\frac{w(G) + \Delta_w(G)}{9} =  \frac{3q(3q+1)/2 + 3q}{9} = \frac{q^2 + q}{2} = w(G[X_3]).
	\]

	And furthermore the following also holds as $d_w(G)=3q$ and $w(G)=\frac{3q(3q+1)}{2}$,

	\[
	w(X_1,X_2,X_3) = q^2 + q(q+1) + q(q+1) =  \frac{3q(3q+1)}{3} + \frac{3q}{3} = \frac{2w(G)}{3} + \frac{d_w(G)}{3}.
	\]


