\caption{Function $\varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau))$ for three values of $\beta = -0.4, -0.3, -0.1$ with
$\tau = 0.5,\, s \in (0, \tau],\, x_l(\tau) = 1.0,\, x_l(s) = x_l(\tau) - s,\, x(s) = x_l(\tau) + 0.1 s$.}
