\end{figure}

In what follows, we will also need the first derivative of $\varTheta_{|\nu|}(\tau, v, w, a)$ on the second argument $v$ which we further denote as $\varTheta'_{|\nu|}(\tau, v, w, a)$. From \eqref{WeberOrrTheta} and \eqref{WeberOrrKernel_def} we obtain
\begin{equation}  \label{WeberOrrThetaPrime}
\varTheta'_{|\nu|}(\tau, v, w, a) = \int_0^\infty  p\, e^{-\frac{p^2}{2}\tau} \frac{W'_{|\nu|}(p, v, a) W_{|\nu|}(p, w, a)}{V_{|\nu|}(p, a)} dp,
\end{equation}
\noindent where
\begin{alignat}{2} \label{WeberOrrKernel_defPrime}
W'_{|\nu|}(p, v, a) &= p\JnuM'(p v) \Ynu(p a) -  p\Ynu'(p v) \JnuM(p a),
\qquad& \JnuM'(x) &= J_{|\nu|-1}(x) - \frac{|\nu|}{x}\JnuM(x).
%V'_{|\nu|}(p, v) &= 2 p \left[\JnuM(p\, v) \JnuM'(p\, v) + \Ynu(p\, v) \Ynu'(p\, v) \right],
%\qquad& \Ynu'(x) &= Y_{|\nu|-1}(x) - \frac{|\nu|}{x}\Ynu(x). \nonumber
\end{alignat}

In what follows,  we need several important properties of the Weber-Orr Theta functions. First, it can be directly checked that
\begin{equation} \label{woThetaProp1}
\varTheta_{|\nu|}(\tau, v, w, v) = 0.
\end{equation}
Regarding other properties, see \cref{betam1}.


\paragraph{Solution of the problem.} Luckily, the homogeneous problem in \eqref{wEq} and, respectively, in \cref{Bess,tc0cev,bc0cev} has been solved in \cite{CarrItkinMuravey2020} (all the details and the corresponding discussion can be found in that paper). The solution reads (with $z$ being a dummy variable)
\begin{align}  \label{uBessSolHomo}
u(\tau, x, z) &=  \frac{x_l(\tau) }{x} K + x^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s)) \varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau) ) ds \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta_{|\nu|}(\tau, x, \xi, x_l(\tau) ) d\xi \Bigg\}. \nonumber
\end{align}
Note, that the Weber-Orr Theta function $\varTheta_{|\nu|}(\tau, v, w, a)$ is also a {\it periodic} solution of the Bessel equation at the semi-infinite domain $\Omega_y^\infty$.

Another, not yet defined term in \eqref{uBessSolHomo}, $\Psi(\tau, x_l(\tau))$ is the Put option Delta (the gradient of the solution) at the moving boundary $x_l(\tau)$
\begin{align} \label{lPsi}
\Psi(\tau, x_l(\tau),z) = \left. \fp{u(\tau,x,z)}{x} \right|_{x = x_l(\tau)}.
\end{align}
It can be found explicitly by differentiating both parts of \eqref{uBessSolHomo} on $x$, substituting $x \to x_l(\tau)$ and taking into account that $\varTheta_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) = 0$. This yields
\begin{align} \label{grCEV}
\Psi(\tau, x_l(\tau)) &=  - \frac{K}{x_l(\tau)} + x_l(\tau)^{-\nu} \Bigg\{ \frac{1}{2} \int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s)) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau, x_l(\tau), \xi, x_l(\tau) ) d\xi \Bigg\}. \nonumber
\end{align}
Thus, the gradient $\Psi(\tau, x_l(\tau))$ solves a LIVESK. This equation can be efficiently solved numerically, in more detail, see \cite{ItkinLiptonMuraveyBook}. To emphasize, as follows from \eqref{grCEV}, $\Psi(\tau, x_l(\tau))$ doesn't depend on $z$.

\paragraph{Adding a source term.}
Similar to \cite{ItkinMuravey2024jd}, the additional source term in \eqref{wEq} can be taken into account by using a generalized Duhamel's principle, \cite{ItkinMuravey2024jd, Itkin2024jd}. This yields
\begin{align}  \label{uBessSolInHomo}
u(\tau, x, z) &=  \frac{x_l(\tau) }{x} K + x^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s)) \varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau) ) ds \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta_{|\nu|}(\tau, x, \xi, x_l(\tau) ) d\xi \Bigg\}
+ \int_0^\tau \int_{x_l(s)}^\infty \lambda(s, \xi) \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) d\xi ds. \nonumber
\end{align}

Accordingly, instead on \eqref{uBessSolHomo} one now has the following equation for $\Psi(\tau, x_l(\tau),z)$
\begin{align} \label{grCEV1}
\Psi(\tau, x_l(\tau)) &=  - \frac{K}{x_l(\tau)} + x_l(\tau)^{-\nu} \Bigg\{ \frac{1}{2} \int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s)) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau, x_l(\tau), \xi, x_l(\tau) ) d\xi \Bigg\}
+ \int_0^\tau \int_{x_l(s)}^\infty \lambda(s, \xi) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds. \nonumber
\end{align}



\subsubsection{Solution of the full problem in \cref{PDE,tc0,bc0,bc1}} \label{secSolAsian}

Again, by using Duhamel's principle for PDEs with moving boundaries, \cite{ItkinMuravey2024jd, Itkin2024jd}, we can show that the last two terms $[\barR^*(t) + y] \fp{P}{z} - [\barR^*(t) + y] P$ in \eqref{PDE} can be added as an additional term to the source term $\lambda(\tau,x,z)$ in \eqref{wEq}. Then, with this change taken into account, \eqref{uBessSolInHomo} still holds, but with a redefined $\lambda(\tau,x,z)$.

In more detail, by making the same chain of transformations as described in \cref{homogBessel}, but now accounting for the extra terms in \eqref{PDE}, instead of \eqref{Bess} we obtain\footnote{The expressions for $B(\tau,x), C(\tau,x,z)$ are obtained by again using Proposition~\ref{prop1}, but now with all terms of the PDE in \eqref{PDE} included.}
\begin{align} \label{BessSource}
\fp{u}{\tau} &= \frac{1}{2} \sop{u}{x} + \frac{b}{x} \fp{u}{x} + C(\tau,x,z) \fp{u}{z} - B(\tau,x) u, \\
B(\tau,x) &=  \frac{1}{\sigma^2(t)}e^{- 2 \int_0^{\phi(t) } f(k) \, dk} \left[ \barR^*(t) + y(t, x) \right], \quad y(t, x) = x^{-1/\beta} \left[-\beta/F(\phi(t)) \right]^{-1/\beta}, \quad t = t(\tau), \nonumber \\
C(\tau,x,z) &=  \frac{1}{(t - t_0) \sigma^2(t)}e^{- 2 \int_0^{\phi(t) } f(k) \, dk} \left[ \barR^*(t) + y(t, x) - z\right],  \nonumber
\end{align}
\noindent with the same terminal and boundary conditions as in \eqref{tc0cev}, \eqref{bc0cev}.

To switch to the problem with homogeneous boundary and terminal conditions, as in \eqref{wEq}, we make the same change to the dependent variable as in \eqref{trHomo}, and obtain a new expression for the source term in \eqref{wEq} which is now denoted as $\Lambda(\tau,x,z)$
\begin{align} \label{newLambda}
\Lambda(\tau, x,z) &= \lamIn(\tau, x) + C(\tau,x,z) \fp{u}{z} - B(\tau,x) u, \\
\lamIn(\tau, x) &= \lambda(\tau, x) - \frac{x_l(\tau) }{x} K B(\tau,x). \nonumber
\end{align}

Accordingly, we intend to use the solution in \eqref{uBessSolInHomo} and apply the generalized Duhamel's principle. When doing so, one needs to take into account that the Green function of the problem depends on variables $(t,x,z)$ while the PDE in \eqref{BessSource} doesn't contain the second derivative in $z$ (hence, this PDE is degenerate in this variable). Since from the definition of $z$ it follows that $z \in [0,\infty]$, its two-dimensional Green's function could be represented in the form $G(t,x,z) = G^{(x)}(t,x) G^{(z)}(t,z)$. Applying the method of images \cite{Howison1995} to the semi-infinite interval yields
\begin{equation} \label{images}
G^{(z)}(t,z | T, \zeta) = \delta(z-\zeta) - \delta(z+\zeta).
\end{equation}
Thus, using this result, from \eqref{uBessSolInHomo} and the generalized Duhamel's principle, we obtain
%
\begin{align}  \label{uBessFull}
u(&\tau, x, z) =  \frac{x_l(\tau) }{x} K \\
&+ x^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s),z) \varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau) ) ds
- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta_{|\nu|}(\tau, x, \xi, x_l(\tau) ) d\xi \Bigg\} \nonumber \\
&+ \int_0^\tau \int_{x_l(s)}^\infty \Big\{ \lamIn(s, \xi) + C(s,\xi,z) u_z(s,\xi, z) - B(s,\xi) u(s,\xi, z) \Big\} \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) d\xi ds. \nonumber
\end{align}
Here, formally speaking, the gradient $\Psi(s, x_l(s),z)$ has to be a function of $z$ as well. The \eqref{uBessFull} is not a closed form solution to the problem in \cref{PDE,tc0,bc0,bc1}, but rather an integral Volterra equation of the second kind with respect to $u(\tau,x,z)$ if $z_B(\tau,x)$ and $\Psi(s, x_l(s),z)$ are known. However, e.g., $z_B(\tau,x)$ for American options is obviously not known in advance and has to be computed simultaneously with the option price. Nevertheless, by using a standard approach of the GIT method, \cite{ItkinLiptonMuraveyBook}, one may derive a couple of auxiliary equations to make this solution fully determined.

\paragraph{Solution for $\bm{z_B(\tau,x)}$.}

First, we substitute $z = z_B(\tau,x)$ into both parts of \eqref{uBessFull}. By the smooth fit principle, \cite{Kwok2022, Chiarella2009} the option value and the first derivative in $z$ are continuous at the exercise boundary (while the second derivative experiences a jump). Hence, the value of $u_z(\tau, x, z_B(\tau))$ has to be understood here as $\left. u_z(\tau, x, z)\right|_{z \to z_B(\tau,x)^+}$, i.e., as the limit of $P_z(\tau, x, z)$ in the continuation region at $z \to z_B(\tau, x)$. Accordingly, we obtain
\begin{align}  \label{uBessFull2}
K\Big( 1 &- \frac{x_l(\tau) }{x} \Big) - z_B(\tau,x) = x^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s), z_B(s,x)) \varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau) ) ds \nonumber \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta_{|\nu|}(\tau, x, \xi, x_l(\tau) ) d\xi \Bigg\}
+ \int_0^\tau \int_{x_l(s)}^\infty \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) \\
&\cdot \Big\{ \lamIn(s, \xi) - B(s,\xi) [K - z_B(s,\xi)]  - C(s,\xi,z_B(s,\xi)) \Big\} d\xi ds. \nonumber
\end{align}

In addition to $z_B(\tau,x)$, this equation  also depends on a yet unknown gradient $\Psi(\tau, x_l(\tau), z_B(\tau,x))$.
Therefore, to proceed, we  differentiate both parts of \eqref{uBessFull} by $x$ and set $x = x_l(\tau)$ to obtain
\begin{align}  \label{uBessFullPsi}
\Psi(&\tau, x_l(\tau), z) =  - \frac{K}{x_l(\tau)} + x^{-\nu}_l(\tau) \Bigg\{ - K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau,x_l(\tau), \xi, x_l(\tau) ) d\xi \\
&+ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s),z) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds  \Bigg\} \nonumber \\
&+ \int_0^\tau \int_{x_l(s)}^\infty \Big\{ \lamIn(s, \xi) + C(s,\xi,z) u_z(s,\xi, z) - B(s,\xi) u(s,\xi, z) \Big\} \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds. \nonumber
\end{align}
For the particular case $z = z_B(\tau,x)$, \eqref{uBessFullPsi} takes the form\footnote{When differentiating, we take into account \eqref{woThetaProp1}, so no derivative of $\Psi(s, x_l(s),z_B(s,x))$ on $x$ appears in the RHS of \eqref{uBessFullPsiB}.}
\begin{align}  \label{uBessFullPsiB}
\Psi(&\tau, x_l(\tau), z_B(\tau, x)) =  - \frac{K}{x_l(\tau)} + x^{-\nu}_l(\tau) \Bigg\{ - K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau,x_l(\tau), \xi, x_l(\tau) ) d\xi \\
&+ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s), z_B(s,x)) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds \Bigg\} \nonumber \\
&+ \int_0^\tau \int_{x_l(s)}^\infty \Big\{ \lamIn(s, \xi) - B(s,\xi) [K - z_B(s,\xi)]  - C(s,\xi,z_B(s,\xi))  \Big\} \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds. \nonumber
\end{align}

 The \cref{uBessFullPsiB,uBessFull2} can be solved together. Suppose we introduce a discrete grid $\mathbb{T}$ in the time $\tau$ as $\mathbb{T}: 0, \tau_1, ... \tau_N = \tau(t_0)$ which contains $N+1$ nodes (in the simplest case, the grid could be uniform). At every node $\tau_i, \ 1 \le i \le N$ the values of $\Psi(\tau_i, x_l(\tau_i), z_B(\tau,x)), z_B(\tau,x)$ can be found as follows:
 \begin{enumerate}[label=(\alph*)]
    \item Start with some initial guess for $z_B(\tau,x) = z^{(0)}_B(\tau,x)$;
    \item Substitute this guess  into \eqref{uBessFullPsiB} to obtain a LIVESK for $\Psi(\tau_i, x_l(\tau_i), z^{(0)}_B(\tau,x))$. Solve it.
    \item Substitute this solution into \eqref{uBessFull2} to obtain a nonlinear algebraic equation for $z_B(\tau,x)$. Solve it to obtain the next approximation, $z^{(1)}_B(\tau,x)$.
    \item  Go to item (b) and repeat steps (b)-(d) until convergence is reached.
 \end{enumerate}

 \paragraph{Solution for  $\bm{u(\tau, x, z)}$.}

 Since $z_B(\tau,x)$ and $\Psi(s, x_l(s),z_B(\tau,x) $ are already known from the previous step, one can replace some terms in the integrals in curly braces in \eqref{uBessFull} and \eqref{uBessFullPsi}  with their representation from \eqref{uBessFull2}. This yields
\begin{align}  \label{uBessFullNew}
\bar{u}(\tau, x, z) &=   \int_0^\tau \int_{x_l(s)}^\infty \left[  C(s,\xi,z) \bar{u}_z(s,\xi, z) + C(s,\xi,z_B(s,\xi)) - B(s,\xi)  \bar{u}(s,\xi, z) \right] \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) d\xi ds \nonumber \\
&+  \frac{1}{2} x^{-\nu} \int_{0}^\tau x_l^{\nu + 1}(s) [\Psi(s, x_l(s),z) - \Psi(s, x_l(s),z_B(s,x) ] \varTheta_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds,  \\
\bar{u}(\tau,x, z) &= u(\tau,x,z) -  (K  - z_B(\tau,x)), \qquad \bar{u}(\tau,x, z_B(\tau,x)) = 0. \nonumber
\end{align}
This equation can be solved together with \eqref{uBessFullPsi} re-written in terms of $\bar{u}(\tau, x, z)$
\begin{align}  \label{uBessFullPsiNew}
\Psi(&\tau, x_l(\tau), z) =  - \frac{K}{x_l(\tau)} + x^{-\nu}_l(\tau) \Bigg\{ - K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau,x_l(\tau), \xi, x_l(\tau) ) d\xi \\
&+ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s),z) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds  \Bigg\} \nonumber \\
&+ \int_0^\tau \int_{x_l(s)}^\infty \Big\{ \blamIn(s, \xi) + C(s,\xi,z) \bar{u}_z(s,\xi, z) - B(s,\xi) \bar{u}(s,\xi, z) \Big\} \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds, \nonumber \\
\blamIn(\tau, x) &= \lamIn(\tau, x) - B(\tau,x) [K -  z_B(\tau, x)]. \nonumber
\end{align}

To emphasize, \cref{uBessFullNew,uBessFullPsiNew} are not standard Volterra equations of the second kind (because they also contain the term $\bar{u}_z(\tau, x, z)$ under the integral in the RHS. However, since the value of $\bar{u}(\tau, x, z)$ at the exercise boundary $z_B(\tau,x)$ is already known and equal to zero, in the numerical scheme of integration we can approximate this derivative with the finite difference\footnote{This will be relaxed in \cref{finalization}, and no FD scheme would be necessary to solve this equation.}
\begin{equation} \label{discret}
\bar{u}_z(\tau_i, x, z_k) ) = \frac{1}{\Delta z} \left[ \bar{u}(\tau_i, x, z_k) - \bar{u}(\tau_i, x, z_k - \Delta z) \right] + O(\Delta z).
\end{equation}
In other words, we solve this problem by additionally introducing some discrete (e.g., uniform) grid $\mathbb{Z}: z_B(\tau, x), z_B(\tau, x) + \Delta z,\dots,z-\Delta z, z$ in the $z$ space, with $\Delta z$ being the grid step. With this approximation,\footnote{Higher order approximations in $\Delta z$ can be constructed in a similar way.} \cref{uBessFullNew,uBessFullPsiNew} becomes a system of two {\it LIVESK}, where, however, the integration is done only in $(\tau, x)$ space, so $z$ stays as a dummy variable. Once $\bar{u}(\tau_i, x, z_B(\tau_i,x) + \Delta z)$ is found, one can proceed to getting $\bar{u}(\tau_i, x, z_B(\tau_i,x) + 2\Delta z)$ in the same way, and so on until the point $z$..

By definition in \eqref{z}, the option price we need is just $u(\tau_i, x, z(t_0))$. However, due to the presence of $\bar{u}_z(\tau, x, z)$ in the RHS of \eqref{uBessFullNew}, it can be obtained only sequentially on a grid $\mathbb{Z}: z \in [z_B(\tau,x), \barR^*(t_0) + y(t_0,x) - z(t_0)]$ (assuming $z(t_0) > z_B(\tau,x)$).

The \cref{uBessFullNew,uBessFullPsiNew} can be numerically solved at the 3D grid $\mathbb{T} \bigotimes \mathbb{X} \bigotimes \mathbb{Z}$,  as follows.
\begin{enumerate}[label=(\alph*)]
    \item Start with the initial guess, $\Psi(s, x_l(s),z) = \Psi(s, x_l(s),z_B(\tau,x)$, since $\Psi(s, x_l(s),z_B(\tau,x)$ is already known.
    \item Substitute this guess  into \eqref{uBessFullNew} to obtain a LIVESK for $\bar{u}(\tau_i, x,z)$. Solve it.
    \item Substitute this solution into \eqref{uBessFullPsiNew} to obtain another LIVESK for $\Psi(s, x_l(s),z)$. Solve it to obtain the next approximation.
    \item  Go to item (b) and repeat steps (b)-(d) until convergence is reached.
\end{enumerate}

It is important that during these iterations only the source terms of these LIVESK change while the matrices of the LHS don't. Therefore, iterations don't influence the order of computational complexity $O(2 N^2 M L)$ where $L$ is the number of nodes in the $\mathbb{Z}$ grid.

Alternatively, \cref{uBessFullNew,uBessFullPsiNew} can be solved as a 2D LIVESK, see, e.g., \cite{Saeed2011} among others.

\subsubsection{Pricing Asian options in the whole region} \label{asianE}

To price Asian options with the European style payoff using the method proposed in above, one needs to take into account that the payoff function in \eqref{tc0} now doesn't vanish outside of the continuation region. In other words, instead of \eqref{tc0} we need to use the terminal condition
\begin{equation} \label{tc0E}
	P(T, y, z) = (K - z(T))^+.
\end{equation}
Accordingly, the terminal condition in \eqref{tc0cev} also changes to
\begin{equation} \label{tc0cevE}
u(0, x, z) = (K - z(T))^+.
\end{equation}
Then the problem in \eqref{wEq} also acquires a modified terminal condition
\begin{equation}
U(0,x,z) = (K - z(T))^+ - \frac{x_l(0)}{x} K.
\end{equation}
Then, with allowance for \eqref{images} and this new terminal condition, in the second term in the curly braces in \eqref{uBessFull} the multiplier $K x_l(0)$ should be replaced with
\begin{equation} \label{trE}
K x_l(0) \to K x_l(0) - x (K - z)^+.
\end{equation}
The same change should be propagated to \eqref{uBessFullPsiNew} while it doesn't affect the equations for $z_B(\tau,x)$ in \cref{uBessFull2,uBessFullPsiB}.

Finally, since for the European style Asian option there is no such a notion as the exercise boundary, integration in $z$ could be done starting from $z = \infty$ where the Put option value should vanish.

Once the price of the Asian option with the European payoff has been determined, the corresponding price of the Asian option with the American payoff style can be found as described in \cref{1mAmerican}.

\subsection{Intermediate results} \label{IntRes}

To the best of our knowledge, so far there has been no development on semi-analytical pricing of Asian options with the American style exercise, even for time-homogeneous models. In this section, by utilizing the GIT approach (proposed in \cite{CarrItkin2020jd} and described in detail in \cite{ItkinLiptonMuraveyBook}) in general, and its particular peculiarities for semi-analytical pricing of the American options, \cite{CarrItkin2020jd, ItkinMuravey2024jd, Itkin2024jd} we have shown how this can be done for these options written on the SOFR (as the underlying), where the SOFR itself follows a time-inhomogeneous CEV model.

The solution is obtained in a few steps:
\begin{enumerate}
	\item First, the system \cref{uBessFullPsiB,uBessFull2} is solved to obtain the exercise boundary $z_B(\tau, x)$. This can be done by using a discrete grid $\mathbb{T}$ in $\tau \in [0, \tau(t_0)]$ space, and also another discrete grid $\mathbb{X}$ in $x$.. Since $x \in [x_l(\tau), \infty)$, we truncate the upper boundary to some large value $x_r(\tau) < \infty$, so $x \in [x_l(\tau), x_r(\tau)]$. Then the grid is constructed as $x_l(\tau), x_1(\tau) + \Delta x, ... x_l(\tau) + M \Delta x = x_r(\tau)$ which contains $M+1$ nodes (again, in the simplest case, the grid could be uniform). The integrals in these equations are discretized by using some quadratures.

Given $z_B(\tau,x_j), \, x_j,\, 1 < j \le M$, \eqref{uBessFullPsiB} (which is a LIVESK for $\Psi(\tau, x_l(\tau),  z_B(\tau,x)_j)$ )  becomes a linear system of algebraic equations (for every $0 \le s \le \tau$) with a triangular matrix, see \cite{ItkinLiptonMuraveyBook}. The numerical complexity of this solution is $O(N^2)$. Moreover, this system is the same for every $x_j,\, 1 < j \le M$ except only the source term (the last term in the RHS of \eqref{uBessFullPsiB}). Therefore, the total complexity of the solution remains $O(N^2)$. Solving the nonlinear algebraic equations \eqref{uBessFull2} is of the complexity $O(N^2 M)$. Assuming that a typical number of iterations required for the nonlinear solver to converge is $I$, the total complexity of this step is $O(N^2 M I)$.


\item At this step, the Put option price $\bar{u}(\tau_i, x, z)$ is found, by first discretizing $\bar{u}_z(\tau_i, x, z)$ according to \eqref{discret}, and then solving the system \cref{uBessFullNew,uBessFullPsiNew}, which after discretization is a system of two LIVESK with respect to $\bar{u}(\tau_i, x, z)$ and $\Psi(\tau_i, x_l(\tau), z)$. To solve it, we need a 3D grid $\mathbb{T} \bigotimes \mathbb{X} \bigotimes \mathbb{Z}$. The numerical complexity of solving this system is $O(N^2 M L)$.

\end{enumerate}

The main difference between this result and those obtained by using the GIT method for pricing American options, \cite{ItkinMuravey2024jd, Itkin2024jd} lies in the fact, that \eqref{uBessFull2} is not an {\it explicit} representation of the option price as in \cite{ItkinMuravey2024jd, Itkin2024jd}, but rather a linear integral equation with respect to the option price. This is because of the extra term $[\barR^*(t) + y] \fp{P}{z}$ in \eqref{PDE}. From this perspective, here the term "semi-analytical" might sound a bit confusing. However, as shown \cref{simplification}, those LIVESKs can be further simplified by using the properties of the Weber-Orr Theta function at $\tau \to 0$ proved in Propositions~\ref{prop2}-\ref{prop3}. This gives to a true semi-analytical (and recurrent) solution for both the option value and the gradient when solving these LIVESKs sequentially in time. To underline, on one hand, this can be treated as an efficient numerical method of solving these equations. On the other hand, by splitting the whole time interval $s$ into the two: $s \in [0, \tau(t)] = [0, \tau^-(t)] \bigcup (\tau^-(t), \tau(t)]$ and using those properties of the Weber-Orr Theta function at the second interval, this semi-analyticity can become transparent in general.

Overall, when solving LIVESK, the numerical complexity of our method is $O(N^2 M H)$, where $H = \max(I,L)$. This can be compared with that of, e.g., a FD approach. It is worth mentioning that accurate pricing of Asian options requires a special technique due to the presence of only the first derivative in $z$ in \eqref{PDE}. In more detail, see \cite{ZvanForsythVetzal1997}. Approximating all the derivatives in \eqref{PDE} with the second order in time and space steps, the total complexity of the solution for the European Asian option is about $O(N M_1 L_1)$. Despite $M_1 \approx M$, however, $L_1 \gg H$ since the FD scheme needs all points in both continuation and exercise regions, while in our case we deal only with the continuation region. For the American-Asian option, since the exercise boundary is not explicitly known (this is in contrast to our method), one needs to additionally apply some kind of penalty method, \cite{Halluin2004, ZvanForsythVetzal1997}. This requires several iterations to maintain the required accuracy. Also, the accuracy of our method can be easily increased by using higher-order quadratures, e.g., the Simpson integration rule with the fourth order of approximation in the grid step, \cite{ItkinLiptonMuraveyBook}. This reduces the complexity of our method to $O(N^2 M^{1/2} H)$ providing the same accuracy as before, while still having $L_1 \gg H$. At the same time, for the FD scheme reaching a higher order of approximation is not easy and also increases the complexity of the numerical solution, \cite{ItkinBook}.

It is even possible to combine these two methods, meaning you can first find the exercise boundary $z_B(\tau, x)$ with the complexity $O(N^2 M I)$, and then in the continuation region solve \eqref{PDE} with the European payoff by using the FD method with the complexity $O(N M_1 L_1)$. Hence, the total complexity becomes $O(N \cdot \max(N M I,  M_1 L_1))$.

Another important advantage of the GIT is the computation of option Greeks, \cite{ItkinLiptonMuraveyBook}. The main point is that the Greeks, i.e., derivatives of the solution, can also be expressed semi-analytically by differentiating the solution (or, both parts of the corresponding LIVESK) on some parameter or independent variable of the model. This results in a new integral equation for the corresponding option Greek, which can be solved in a similar way.. In contrast, e.g., for the FD method, the Greeks can be found only by bumping the corresponding parameters. This might create various numerical issues, especially in the regions where the solution is not smooth enough (for instance, close to the exercise boundary), while for this version of the GIT method all Greeks can be calculated by re-running only the last step in the above procedure.

This is especially important for American options since, in contrast to the option value and Delta, the option Gamma and Vega experience a jump at the exercise boundary, meaning their values vanish in the exercise region,  but not in the continuation region, \cite{ItkinMuravey2024jd}. An accurate computation of this jump is always a problem for the FD methods, and they need to use a version of the penalty method to accurately resolve it, \cite{Halluin2004}.

At the end, let us mention that the solution also depends on $y_{t_0}$ such that $\barr(t_0) + R^*(t_0) + y_{t_0}$ is the instantaneous SOFR forward price at  time $t_0$. It can be found as this is described in \cref{American}. In other words, $y_{t_0} = f(t_0, \bar{y}, Q)$, where $\bar{y} = y_t|_{t = \tins}$, and $Q$ is the maturity of the corresponding ZCB, see \cref{solForward}.

\subsection{Simplifications and finalization} \label{simplification}

\subsubsection{Particular values of the CEV $\beta$} \label{betam1}

Since the CEV model covers various known models by making a particular choice of the parameter $\beta$, in this section we consider $\beta = -1$. The corresponding model is known as the Hull-White model, \cite{Hull:1990a,andersen2010interest}, which in our case has all parameters of the model to be time-dependent.

As under the Hull-White model the underlying has a Gaussian distribution, various formulae derived in the previous sections become either more transparent or significantly simplified in this case. First of all, this is true for the Weber-Orr Theta function which in the case $\beta = -1$ transforms into a combination of exponents. Accordingly, the following results hold:
\begin{proposition} \label{prop2}
For the Hull-White model ($\beta=-1$) the Weber-Orr Theta function has the following properties
\begin{align} \label{WOThetaProp}
\varTheta_{|\nu|}(\tau, v, w, a) &= \frac{1}{\sqrt{v w}} \frac{1}{\sqrt{2 \pi \tau }} \left[e^{-\frac{(v-w)^2}{2 \tau }} - e^{-\frac{(v+w - 2a)^2}{2 \tau }}\right], \\
\lim_{\tau \to 0} \varTheta_{|\nu|}(\tau, v, w, a) &= \frac{1}{\sqrt{v w}} \left[ \delta(v-w) - \delta(v + w - 2a) \right], \nonumber \\
\varTheta'_{|\nu|}(\tau, v, w, v) &= \frac{2(w-v)}{\sqrt{v w}} \frac{1}{\sqrt{ 2 \pi \tau^3}} e^{-\frac{(v-w)^2}{2 \tau }}, \quad \Re(\tau) > 0, \nonumber \\
\lim_{\tau \to 0} \varTheta'_{|\nu|}(\tau, v, w, v)  &= \frac{2}{\sqrt{v w}}\delta'(v-w),
\qquad \lim_{\tau \to 0} \lim_{v \to w} \varTheta'_{|\nu|}(\tau, v, w, v)  = 0. \nonumber
\end{align}
\noindent where $\delta(x)$ is the Dirac Delta function.

\begin{proof}[{\bf Proof}]
Since for the Hull-White model $\beta = -1$, from the definition of $\nu = 1/(2 \beta)$ given after Fig.~\ref{FigTheta} we have $\nu = -1/2$. Accordingly, the Bessel functions with index $1/2$ are expressed via trigonometric functions, or imaginary exponents, \cite{as64}. Substituting  this representation into the definition of the Weber-Orr Theta function in \eqref{thetaBess} and integrating, we obtain the first line in \eqref{WOThetaProp}.

Differentiation of this line by $v$ and substitution $ a \to v$ gives rise to the third line in \eqref{WOThetaProp}. It can also be re-written in the form
\begin{equation*}
\varTheta'_{|\nu|}(\tau, v, w, v) = \frac{2}{\sqrt{v w}} \frac{\partial }{\partial v} \left[ \frac{1}{\sqrt{2 \pi  \tau }} e^{-\frac{(v-w)^2}{2 \tau }} \right].
\end{equation*}
The expression in  square brackets is the heat kernel, \cite{Kartashov2001}. Then, the known result is that at $\tau \to 0$ the heat kernel tends to the Dirac Delta function. Based on this fact, the second and the fourth lines of \eqref{WOThetaProp} follow.
%
\end{proof}
\end{proposition}

\subsubsection{Extension for an arbitrary $\beta$}

The main question to immediately and naturally ask based on results obtained in \cref{betam1} would be whether Proposition~\ref{prop2} is also valid in the general case of an arbitrary $\beta$, i.e., whether the properties listed in  this proposition are common properties of the Weber-Orr Theta function. Proposition~\ref{prop3} provides some guidance to answer it positively.

\begin{proposition} \label{prop3}
For general $\nu = 1/(2\beta)$ with $\beta \in [-1,1]$ the second and fourth lines of proposition~\ref{prop2} still hold.

\begin{proof}[{\bf Proof}]
By definition of the Weber-Orr Theta function in \eqref{WeberOrrTheta}, at $\tau \to 0$ we have
\begin{equation}  \label{WeberOrrTau0}
\lim_{\tau \to 0} \varTheta_{|\nu|}(\tau, v, w, a) = \int_0^\infty  \frac{W_{|\nu|}(p, v, a) W_{|\nu|}(p, w, a)}{V_{|\nu|}(p, a)} p\, dp.
\end{equation}

According to Weber's integral theorem, \cite{Titchmarsh1921}, if $v > a > 0$ and $f(t)$ is of bounded variation in a neighborhood of $t = v$, then the following identity holds
\begin{align} \label{Wident}
\int_0^\infty  \frac{W_{|\nu|}(p, v, a) }{V_{|\nu|}(p, a)} p\, dp \int_a^\infty W_{|\nu|}(p, t, a) t f(t) dt =
\frac{1}{2}[ f(x+0 + f(x-0)].
\end{align}
On the other hand, it is always true, that $\varTheta_{|\nu|}(\tau, v, w, v) = 0$.

Therefore, let us set
\begin{equation*}
f(t) = \frac{1}{\sqrt{t }} [\delta(t-w) - \delta(2a - t - w)],
\end{equation*}
\noindent  where $w > a > 0$, and substituting it into \eqref{Wident}. This yields
\begin{align} \label{Wident2}
\int_0^\infty  p \frac{W_{|\nu|}(p, v, a) W_{|\nu|}(p, w, a)}{V_{|\nu|}(p, a)}  \sqrt{w} dp =
\frac{1}{\sqrt{v}}[\delta(v - w) - \delta(v + w - 2a)].
\end{align}
Here, in the RHS of \eqref{Wident} we used the oddness of the Dirac Delta function, and in the LHS - the fact that
\begin{equation*}
\int_a^\infty W_{|\nu|}(p, t, a) \sqrt{t}\,  \delta(2a - (t - w) dt = 0,
\end{equation*}
\noindent since $ w > a$. Combining \cref{WeberOrrTau0,Wident2} we obtain the second line of \eqref{WOThetaProp} for an arbitrary $\beta$. Also, we have
\begin{equation*}
\lim_{a \to v} \lim_{\tau \to 0} \varTheta_{|\nu|}(\tau, v, w, a)  =
\lim_{\tau \to 0} \lim_{a \to v} \varTheta_{|\nu|}(\tau, v, w, a) = 0,
\end{equation*}
\noindent as it should be. Note, that the function $\frac{1}{\sqrt{v}}\delta(v - w)$ is of bounded variation if $v \ne w$.

Now, the last identity in the fourth line of \eqref{WOThetaProp} follows by first, differentiating the second line by $v$ and then taking the limit $a \to v$.

\end{proof}
\end{proposition}

\subsubsection{Simplifications of  the final results} \label{finalization}

It turns out, that these simplifications not only look attractive, but also drastically affect the way the solution in the previous sub-sections could be obtained. This is related to \eqref{uBessFullPsiB} and \eqref{uBessFull2}.

Indeed, in \cref{secSolAsian} instead of a semi-analytical expression for $\Psi(\tau, x_l(\tau), z) $ we derived two LIVESK, \eqref{uBessFullPsiB} and \eqref{uBessFull2}, that should be solved numerically. But, in the first integral on $s$ in the RHS of \eqref{uBessFullPsiB}, based on Proposition~\ref{prop3}, at $ s \to \tau$ we obtain $\varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) \to 0$. Accordingly, in the second integral we have
\begin{align}
\lim_{s \to \tau} & \int_{x_l(s)}^\infty \Big\{ \lamIn(s, \xi) - B(s,\xi) [K -  z_B(s,\xi)] - C(s,\xi,z_B(s,\xi)) ]   \Big\} \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi \\
&= \int_{x_l(\tau)}^\infty \Big\{ \lamIn(\tau, \xi) - B(\tau,\xi) [K - z_B(\tau,\xi)]  - C(\tau,\xi,z_B(\tau, \xi)) ]   \Big\} \frac{2}{\sqrt{x_l(\tau) \xi}}\delta'(\xi - x_l(\tau)) d\xi = 0, \nonumber
\end{align}
Thus, all terms in the RHS of \eqref{uBessFullPsiB} corresponding to $s = \tau$ vanish. But, since \cref{uBessFullPsiB,uBessFull2} are solved sequentially in time at the grid $\mathbb{T}$, all the remaining terms under the integrals in the RHS of these equations, corresponding to $s < \tau$, are already known by the time $\tau$. And, due to the vanished kernels at $s \to \tau$, the term $\Psi(\tau, x_l(\tau), z)$ disappears from the RHS of \cref{uBessFullPsiB,uBessFullPsiB}. Thus, \cref{uBessFullPsiB,uBessFullPsiB} are no more LIVESK, but rather a recurrent in time semi-analytical solution for $z_B(\tau,x))$ and $\Psi(\tau, x_l(\tau), z_B(\tau,x))$. Same is true for \eqref{uBessFullNew,uBessFullPsiNew}.

In more detail, suppose the solution of the problem has already been found up to the point $\tau_i \in \mathbb{T}: 0, \tau_1, ... \tau_N = \tau(t_0)$, such that $1 < i < N$. For the shortness of notation let us assume up to the end of this section that $\tau = \tau_{i+1}, \tau_m = \tau_i$. With allowance for the properties of the Weber-Orr Theta function listed in Proposition~\ref{prop3}, from  \eqref{uBessFull2} we have
\begin{align}  \label{uBessFul3}
&\qquad \qquad K\Big( 1 - \frac{x_l(\tau) }{x} \Big) -  z_B(\tau,x)  - \frac{1}{2} \Delta \tau \calI(\tau) = A(\tau, x) + \frac{1}{2} \Delta \tau \calI_1(\tau_m),  \\
A(\tau,x) &=  x^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^{\tau_m} x_l^{\nu + 1}(s) \Psi(s, x_l(s), z_B(s,x)) \varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau) ) ds \nonumber \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta_{|\nu|}(\tau, x, \xi, x_l(\tau) ) d\xi \Bigg\}
+ \int_0^{\tau_m} \int_{x_l(s)}^\infty \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) \calL_B(s,\xi) d\xi ds, \nonumber \\
\calL_B(s,\xi) &= \lamIn(s, \xi)  - B(s,\xi) [K - z_B(s,\xi)] - C(s,\xi,z_B(s,\xi)),  \nonumber \\
\calI_1(\tau_m) &= \frac{1}{2} x^{-\nu} x_l^{\nu + 1}(\tau_m) \Psi(\tau_m, x_l(\tau_m), z_B(\tau_m,x)) \varTheta_{|\nu|}(\Delta \tau, x, x_l(\tau_m), x_l(\tau) ) \nonumber \\
&+ \int_{x_l(\tau_m)}^\infty \varTheta_{|\nu|}(\Delta \tau, x, \xi, x_l(\tau) ) \calL_B(\tau_m,\xi) d\xi, \qquad \Delta \tau = \tau - \tau_m, \nonumber \\
\calI(\tau) &= \int_{x_l(\tau)}^\infty  \frac{1}{\sqrt{x \xi}} \left[ \delta(x-\xi) - \delta(x + \xi - 2 x_l(\tau)) \right] \calL_B(\tau, \xi) d\xi \nonumber \\
&= \frac{1}{x} \calL_B(\tau,x) - \frac{1}{\sqrt{x x_l(\tau)}} \calL_B(\tau,2 x_l(\tau)-x) \Ind_{x = x_l(\tau)} = \frac{\Ind_{x \ne x_l(\tau)}}{x} \calL_B(\tau,x), \nonumber
\end{align}
\noindent because, based on \eqref{Corner}, $z_B(\tau, x_l(\tau)) = 0$. In \eqref{uBessFul3} we used a trapezoidal quadrature for the approximation of the integral $\int_{\tau_m}^\tau \ldots ds$, however, this can be easily relaxed.

Since $\calL_B(\tau,x)$ is linear in $z_B(\tau,x)$, \eqref{uBessFul3} can be trivially solved to get a closed form representation
\begin{align} \label{zbFinal}
z_B(\tau, x) &= \frac{K \left( 1 - \frac{x_l(\tau) }{x} \right) - A(\tau,x) - \frac{1}{2} \Delta \tau \Bigg[ \calI_1(\tau_m)
+ \frac{\Ind_{x \ne x_l(\tau)}}{x} \Big( \lamIn(\tau, x) - B(\tau,x) K - C(\tau,x,0) \Big) \Bigg]}{1 + \frac{\Ind_{x \ne x_l(\tau)}}{2 x} \Delta \tau [B(\tau,x) + Q(\tau)]}, \nonumber \\
Q(\tau) &= \frac{1}{(t - t_0) \sigma^2(t)}e^{- 2 \int_0^{\phi(t) } f(k) \, dk}, \qquad t = t(\tau).
\end{align}

Similarly, from \eqref{uBessFullPsiB} we have
\begin{align}  \label{uBessFullPsiBrec}
\Psi(&\tau, x_l(\tau), z_B(\tau, x)) =  - \frac{K}{x_l(\tau)} + x^{-\nu}_l(\tau) \Bigg\{ - K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau,x_l(\tau), \xi, x_l(\tau) ) d\xi \\
&+ \frac{1}{2}\int_{0}^{\tau_m} x_l^{\nu + 1}(s) \Psi(s, x_l(s), z_B(s,x)) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds \Bigg\} \nonumber \\
&+ \int_0^{\tau_m} \int_{x_l(s)}^\infty \calL_B(s,\xi) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds  \nonumber \\
&+ \frac{1}{2} \Delta \tau \Bigg[ \frac{1}{2} x^{-\nu}_l(\tau) x_l^{\nu + 1}(\tau_m) \Psi(\tau_m, x_l(\tau_m), z_B(\tau_m,x)) \varTheta'_{|\nu|}(\Delta \tau, x_l(\tau), x_l(\tau_m), x_l(\tau) ) \nonumber \\
&+ \int_{x_l(\tau_m)}^\infty \calL_B(\tau_m,\xi) \varTheta'_{|\nu|}(\Delta \tau, x_l(\tau), \xi, x_l(\tau) ) d\xi   \Bigg]. \nonumber
\end{align}
Thus, instead of solving a system of two LIVESK in \eqref{uBessFullNew} at every time step $\tau_i$, actually we have obtained a closed form  (recurrent) solution for $z_B(\tau,x)$ and $\Psi(\tau, x_l(\tau), z_B(\tau ,x))$.

\paragraph{The exercise boundary at $\mathbf{t=t_0}$.} It is well-known that the PDE in \eqref{PDE} has a singularity at $t=t_0$. Usually, the standard approach is to further assume that $z(t_0) = \barR^*(t_0) + y$ to resolve it. This trick works well for numerical methods that don't utilize an explicit value of the exercise boundary, but rather implicitly compare the European and intrinsic values of the option at every computational point. However, when trying to find a closed form solution for $z_B(\tau(t_0),x)$ as we do it in this paper, this immediately brings a problem.

Indeed, the standard approach simply removes the first derivative $P_z$ from the PDE at $t=t_0$, so the PDE becomes  independent of $z$, i.e., becomes one-dimensional in the space state. If we do that in \eqref{zbFinal}, it can be seen that $z_B(\tau),x)$ will experience a jump at $t \to t_0$ and tend to $z_B(\tau(t_0),x) = K$. Thus, the option price for the OTM (out of the money) options will vanish, which is unrealistic and contradicts known numerical results. Another reason for that is that the standard assumption sets $z(t_0) = \barR^*(t_0) + y$, but not $z_B(\tau(t_0),x) = \barR^*(t_0) + y$.
On the other hand, since known numerical methods utilize an implicit check for the exercise condition, such an approach could be questioned at $t \to t_0$, subject to a bigger and, to a certain extent, uncontrolled error.

Another way to resolve this problem could be as follows. One can look at the limit of \eqref{zbFinal} at $t \to t_0$.  It it is easy to check from \eqref{zbFinal} that in this case  $z_B(\tau(t_0),x) \to \barR^*(t_0) + y$. Again, this condition means that the exercise boundary experiences a jump when $t \to t_0$. But since in the continuation region $K < \barR^*(t_0) + y$, the intrinsic value of the option also becomes zero.

Thus, both of the described approaches don't resolve this problem. Therefore, in this paper we redefine the original problem by setting that $z_B(\tau(t_0),x)$ can be determined by interpolating $z_B(\tau,x)$ over time given the already computed values of $z_B(\tau_j,x), \ \tau_j \in [\tau_1 = 0,\ldots,\tau_{N-1} = \tau(t_0) - \Delta \tau]$. This assumption, despite not being justified theoretically, eliminates jumps at $t \to t_0$ and provides plausible values of the Asian-American Put option prices, see \cref{experiments}.


\paragraph{Simplification of the solution for the option price.} Closely looking at the RHS of \eqref{uBessFullNew}, one can recognize that, by using Proposition~\ref{prop3},  the first term in the limit $s \to \tau$ can also be computed explicitly to yield
\begin{align} \label{uHW}
\lim_{s \to \tau} & \int_0^\tau \int_{x_l(s)}^\infty D(s,\xi,z) \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) d\xi ds
= \frac{1}{\sqrt{x x_l(\tau)}}  \times    \\
& \int_{x_l(\tau)}^\infty D(\tau,\xi,z) \left[ \delta(x-\xi) - \delta(x + \xi - 2x_l (\tau)) \right] d\xi =  \frac{\Ind_{x \ne x_l(\tau)}}{x} D(\tau, x, z), \nonumber \\
D(s,\xi, z) &= - B(s,\xi) \bar{u}(s,\xi, z) + C(s,\xi,z) \bar{u}_z(s,\xi, z) + C(s,\xi,z_B(s,\xi)). \nonumber
\end{align}

This means that \eqref{uBessFullNew} also is not anymore a LIVESK, but rather a recurrent solution for $u(\tau,x,z)$.  Indeed, combining \eqref{uBessFullNew} and \eqref{uHW} yields
\begin{align}  \label{uBessFullNew2}
\bar{u}(\tau, x, z) &=  \calA(\tau,x,z) + \frac{\Ind_{x \ne x_l(\tau)}}{2 x}\Delta \tau D(\tau, x, z), \\
\calA(\tau,x,z) &= \int_0^{\tau_m} \int_{x_l(s)}^\infty D(s,\xi, z)  \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) d\xi ds \nonumber \\
&+  \frac{1}{2} x^{-\nu} \int_{0}^{\tau_m} x_l^{\nu + 1}(s) [\Psi(s, x_l(s),z) - \Psi(s, x_l(s),z_B(s,x) ] \varTheta_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds,  \nonumber \\
&+ \frac{1}{2} \Delta \tau \Bigg\{ \int_{x_l(\tau_m)}^\infty D(\tau_m,\xi, z) \varTheta_{|\nu|}(\Delta \tau, x, \xi, x_l(\tau) ) d\xi  \nonumber \\
&+  \frac{1}{2} x^{-\nu} x_l^{\nu + 1}(\tau_m) [\Psi(\tau_m, x_l(\tau_m),z) - \Psi(\tau_m, x_l(\tau_m),z_B(\tau_m,x)) ] \varTheta_{|\nu|}(\Delta \tau, x_l(\tau), x_l(\tau_m), x_l(\tau) ) \Bigg\},  \nonumber
\end{align}
\noindent where for $\Psi(s, x_l(s),z)$ we have from \eqref{uBessFullPsiNew}
\begin{align}  \label{uBessFullPsiRec}
\Psi(&\tau, x_l(\tau), z) =  - \frac{K}{x_l(\tau)} + x^{-\nu}_l(\tau) \Bigg\{ - K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau,x_l(\tau), \xi, x_l(\tau) ) d\xi \\
&+ \frac{1}{2}\int_{0}^{\tau_m} x_l^{\nu + 1}(s) \Psi(s, x_l(s), z) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds \Bigg\} \nonumber \\
&+ \int_0^{\tau_m} \int_{x_l(s)}^\infty \calL(s,\xi)  \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds  + \frac{1}{2} \Delta \tau \Bigg[ \frac{1}{2} x^{-\nu}_l(\tau) x_l^{\nu + 1}(\tau_m) \Psi(\tau_m, x_l(\tau_m), z) \nonumber \\
&\times  \varTheta'_{|\nu|}(\Delta \tau, x_l(\tau), x_l(\tau_m), x_l(\tau) )
+ \int_{x_l(\tau_m)}^\infty \calL(\tau_m, \xi) \varTheta'_{|\nu|}(\Delta \tau, x_l(\tau), \xi, x_l(\tau) ) d\xi   \Bigg], \nonumber \\
\calL(\tau,x) &= \lamIn(\tau,x) - B(\tau,x) \bar{u}(\tau,x, z) + C(\tau,x,z)\bar{u}_z(\tau,x, z). \nonumber
\end{align}

The \eqref{uBessFullNew2} could be treated as a linear ordinary differential equation (ODE) with the dependent variable $\bar{u}(\tau,x,z)$ and the independent variable $z$ if re-written in the form
\begin{align} \label{ODE}
\left[1 + a(x) B(\tau,x) \right] \bar{u}(\tau,x, z_j) &- a(x) \bar{u}_z(\tau,x, z_j) \left[ C(\tau,x,0) - Q(\tau) z_j \right] = \calA(\tau,x,z_j) + a(x) C(\tau,x,z_B(\tau,x)), \nonumber \\
a(x) &=  \frac{\Ind_{x \ne x_l(\tau)}}{2 x}\Delta \tau, \qquad z_j \in [z_B(\tau,x), z], \quad j=1,\ldots,N_z.
\end{align}
It can be solved subject to the boundary condition $\bar{u}(\tau,x,z_B(\tau,x)) = 0$, which follows from \eqref{bc0cev}, and the definition of $\bar{u}(\tau,x,z)$ in \eqref{uBessFullNew}. This yields
\begin{align} \label{ODEsol}
\bar{u}(\tau,x, z_j) &= - \int_{z_B(\tau,x)}^{z_j}
\left(\frac{C(\tau,x,0) - Q(\tau) k }{C(\tau,x,0) - Q(\tau) z_j }\right)^p
\frac{\calA(\tau,x,k) + a(x) C(\tau,x,z_B(\tau,x))}{C(\tau,x,0) - Q(\tau) k} dk, \qquad x \ne x_l(\tau) \nonumber \\
\bar{u}(\tau,x_l(\tau), z_j) &= \calA(\tau,x_l(\tau),z_j), \qquad p = \frac{1 + a(x) B(\tau,x)}{a(x) Q(\tau)}.
\end{align}
Note, that in case $\calA(\tau,x,z)$ doesn't depend on $z$, the integral in \eqref{ODEsol} can be taken explicitly to yield
\begin{align}
\bar{u}(\tau,x, z_j) &=  \frac{\calA(\tau,x) + a(x) C(\tau,x,z_B(\tau,x))}{ Q(\tau)} \left [ 1 - \frac{1}{p} \left(
\frac{C(\tau,x, z_B(\tau,x))}{C(\tau,x,z_j)} \right)^p \right].
\end{align}
By the definition of $a(x)$ in \eqref{ODE}, it is small and $a(x) \to 0$ when $x \to \infty$. Accordingly, the coefficient $p$
demonstrates the same behavior. Since
\begin{equation*}
\lim_{p \to 0} \frac{1}{p} (a/b)^p = - \log(a/b),
\end{equation*}
\noindent the solution in \eqref{ODEsol} is well-behaved if $C(\tau,x, z_B(\tau,x)) > C(\tau,x,z)$ at large $x$, but otherwise could become negative. Therefore, we additionally need to set
\begin{equation}
\bar{u}(\tau,x, z_j) = 0, \quad \frac{1}{p} \left( \frac{C(\tau,x, z_B(\tau,x))}{C(\tau,x,z_j)} \right)^p > 1, \quad
\textrm{or} \quad \frac{C(\tau,x, z_B(\tau,x))}{C(\tau,x,z_j)} > \log\left( p^{1/p} \right).
\end{equation}
Obviously, $\log\left( p^{1/p}\right) < 0$ since $p < 1$. But $C(\tau,x,z_j)$ can also be negative. Also, as this directly follows from \eqref{ODE}, at small $a(x)$ the solution of this ODE tends to $\bar{u}(\tau,x, z_j) = \calA(\tau,x_l(\tau),z_j)$.

The results in \eqref{ODEsol} and below show that we don't need any FD approximation of the first derivative $\bar{u}_z(\tau,x, z)$ to obtain the final solution (despite the fact that the  FD approximation of the first derivative in $z$ can alternatively be used to solve \eqref{ODE}). However, we still need to numerically compute the integrals in variables $\tau, x,z$.

Accordingly, from \eqref{ODE} we have
\begin{align} \label{ODEsolDer}
\bar{u}_z(\tau,x, z) &=  \frac{ \left[ 1 + a(x) B(\tau,x) \right] \bar{u}(\tau,x, z)  - \calA(\tau,x,z)  -  a(x) C(\tau,x,z_B(\tau,x))}{a(x) \left[ C(\tau,x,0) - Q(\tau) z \right] }.
\end{align}
However, at $a(x) \to 0$ the value of $\bar{u}_z(\tau,x, z)$ becomes undetermined. But, since $u(\tau,x,z) \to 0$ when $x \to \infty$, it is expected that in this limit $\bar{u}_z(\tau,x, z) \to -1$.

The recurrent solution in variables $z, x$ can be obtained on a grid $\mathbb{X} \bigotimes \mathbb{Z}$ using the fact, that in the RHS of \eqref{uBessFullNew2} all terms are already known at the time $\tau$ because i) the option prices $u(\tau_m,x,z) $ have been already computed at the previous time step $\tau_m < \tau$, and ii) the same is true for the gradients $\Psi(s, x_l(s), z)$ since $s \le \tau_m$. Thus, we have a true semi-analytical solution to the problem.

To emphasize,  this solution is constructed to deliver the European Put option price only in the continuation region, so the terminal condition in \eqref{tc0} has been used. That was done to achieve our ultimate goal of deriving a LIVESK for the exercise boundary. However, as shown in \cref{asianE}, by a minor modification \eqref{trE}, it can also provide the European Put option price for the entire domain.

\section{Pricing American options on futures} \label{American}

In this section we discuss how to price options on futures in the interval $t \in [S_{\mathrm{ins}}, SR_{\mathrm{start}}]$, where, in fact, they are American options written on a forward rate.

This is a much simpler problem than that discussed in \cref{Asian}. Accordingly, it can be solved by using the results already obtained in \cref{Asian} and \cite{ItkinMuravey2024jd}. Indeed, in \cite{ItkinMuravey2024jd} American options written on ZCB $F(t,y,Q)$ with the maturity $Q$, where the underlying interest rate $y$ follows the time-dependent CEV model, have already been  considered. A semi-analytical representation for the Call option price at the interval $y \in [0, y_B(t)]$, where $y_B(t)$ is the exercise boundary in the $y$ space \footnote{This boundary is uniquely translated into $F_B(t,y_B(t),Q)$ - the exercise boundary in the $F$ space.}, has also been obtained by using the GIT method. As, by definition, \cite{BM2006}, the instantaneous forward rate $f(t,Q)$ reads
\begin{equation} \label{forwardDef}
	f(t,y, Q) = - \fp{}{Q} \log F(t,y,Q),
\end{equation}
\noindent one can pick this connection and reuse the result in \cite{ItkinMuravey2024jd}. However, since here we consider an American Put option with a different continuation region $y \in [y_B(t), \infty)$, the result in \cite{ItkinMuravey2024jd} should be combined with the result of \cref{Asian}. Below, we describe this approach in more detail.

Again, we assume that the dynamics of $y_t$ is described by the CEV model as in \cref{Asian}. Using the same argument as in \cite{ItkinMuravey2024jd}, assume that the exercise boundary $y_B(t)$ is known. Then, in the continuation region, the pricing problem for the American Put $P(t,y)$ is equivalent to pricing Down-and-Out barrier option at the domain $\Omega: y \in [y_B(t), \infty) \times t \in [0,T_f]$, where $T_f$ is the maturity of this American option written on futures (in the next section we will discuss how to set $T_f$). Hence, the American Put price $P(t,y)$ in the continuation region solves the PDE\footnote{In this section $y$ refers to $y_t|_{t = \tins}$. }
\begin{equation} \label{PDEP}
\fp{P}{t} - \alpha(t) y \fp{P}{y} + \frac{1}{2} \sigma^2(t) y^{2 \beta+2}\sop{P}{y} - [\barR^*(t) + y] P = 0, \qquad(t, y) \in \mathbb{R}_+ \times [y_B(t), \infty),
\end{equation}
\noindent subject to the terminal condition
\begin{equation} \label{tchw}
	P(T_f,y) = \left(K - f(T_f, y, Q)\right)^+ = 0,
\end{equation}
\noindent the boundary condition at the moving boundary
\begin{equation} \label{bc1hw}
	P(t,y_B(t)) = K - f(t, y_B(t), Q),
\end{equation}
\noindent and the other boundary condition at $y \to \infty$. Since, based on \eqref{bc1-42}, in this limit the forward price tends to infinity, this yields
\begin{equation} \label{bc2hw}
	P(t,y)\Big|_{y \to \infty}  = 0.
\end{equation}

Further, we use Proposition~\ref{prop1} to transform this problem into the following one:
\begin{align} \label{BessAmer}
\fp{u}{\tau} &= \frac{1}{2} \sop{u}{x} + \frac{b}{x} \fp{u}{x} - B(\tau,x) u, \\
u(0, x) = 0, \qquad u(\tau, x \uparrow \infty) &= 0, \qquad u(\tau, x_B(\tau)) \equiv f^+(\tau) = K - f(\tau,x_B(\tau),Q), \nonumber
\end{align}
\noindent and then make another change of variables (similar to \eqref{trHomo})
\begin{equation} \label{trHomoAmer}
	U(\tau,x) = u(\tau, x) - \frac{x_B(\tau)}{x} f^+(\tau),
\end{equation}
\noindent that. together with Duhamel's principle, yields
\begin{align} \label{wEqF}
\fp{U}{\tau} &= \frac{1}{2} \sop{U}{x} + \frac{b}{x} \fp{U}{x} + \lambda(\tau,x) - g(\tau,x) \left[ U + \frac{x_B(\tau)}{x} f^+(\tau)\right], \\
\lambda(\tau,x) &= \frac{x_B(\tau) f^+(\tau)}{x}\left[ \frac{1 - b}{x^2} - \fp{}{\tau}\log[x_B(\tau) f^+(\tau)] \right], \qquad g(\tau,x) = B(\tau,x), \nonumber \\
U(0,x) &= - \frac{x_B(0)}{x} f^+(0), \qquad U(\tau, x \uparrow \infty) = U(\tau, x_B(\tau)) = 0. \nonumber
\end{align}

The solution of this problem has already been obtained in \cref{secSolAsian} and can be utilized here if an explicit dependence of $f(\tau, x_B(\tau),Q))$ on $x_B(\tau, Q)$ is known. Therefore, at this point, we need to return to the problem in \eqref{PDE-42}, \eqref{termZCB-42}, \eqref{bc1-42} to determine such a dependence.

Note, that the terminal condition for the continuation region in \eqref{tchw} is sufficient to determine the exercise boundary. Then, to find the European option price in the whole region (including the exercise region), a modified boundary condition
\begin{equation}
P(T_f,y) = \left(K - f(T_f, y, Q)\right)^+,
\end{equation}
\noindent should be used, similar to how this is explained in \cref{asianE}.. Accordingly, this results only in a replacement
$ x_B(0) f^+(0) \to x_B(0) f^+(0) - x \left(K - f(0, x, Q)\right)^+$, while the derived equations remain the same. Once the price of the European option has been determined, the corresponding price of the American option can be found as described in \cref{amer3Mdes}.

\subsection{An explicit representation of $f(\tau, x_B(\tau), Q)$} \label{solForward}

In the continuation region, under a risk-neutral measure $\mathbb{Q}$ by a standard argument, \cite{andersen2010interest}, the ZCB price $F(t, y, Q )$  solves a linear PDE
\begin{equation} \label{PDE-42}
\fp{F}{t} - \alpha(t) y \fp{F}{y} + \frac{1}{2} \sigma^2(t) y^{2 \beta+2} \sop{F}{y} - [\barR^*(t) + y] F= 0,
\end{equation}
\noindent subject to the terminal
\begin{equation} \label{termZCB-42}
	F(Q,y,Q)  = 1,
\end{equation}
\noindent and the boundary conditions
\begin{equation} \label{bc1-42}
	F(t,y_l(t),Q)  = 1, \qquad  F(t, y, Q)\Big|_{y \to \infty} = 0.
\end{equation}


Again, we can apply Proposition ~\ref{prop1} to this problem to transform it into the following one
\begin{align} \label{wZCB}
\fp{U}{\tau} &= \frac{1}{2} \sop{U}{x} + \frac{b}{x} \fp{U}{x} + \lambda(\tau,x) - g(\tau,x) \left[ U + \frac{x_l(\tau)}{x} \right], \\
\lambda(\tau,x) &= \frac{x_l(\tau)}{x} \frac{1 - b}{x^2} + \frac{x'_l(\tau)}{x}, \nonumber \\
U(0,x) &= 1 - \frac{x_l(0)}{x}, \qquad U(\tau, x \uparrow \infty) = U(\tau, x_l(\tau)) = 0, \qquad
U(\tau,x) = u(\tau, x) - \frac{x_l(\tau)}{x}, \nonumber
\end{align}
\noindent and $y(\tau,x)$ is defined in \eqref{BessSource}.

The solution to this problem looks similar to that in \eqref{uBessFull}
\begin{align}  \label{uFfull}
u(&\tau, x) =  1 - \frac{x_l(\tau) }{x} + \int_0^\tau \int_{x_l(s)}^\infty \left[ \lambda(s, \xi) - g(s,\xi) u(s,\xi) \right] \varTheta_{|\nu|}(\tau - s, x, \xi, x_l(\tau) ) d\xi ds \\
&+ x^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s)) \varTheta_{|\nu|}(\tau - s, x, x_l(s), x_l(\tau) ) ds - K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta_{|\nu|}(\tau, x, \xi, x_l(\tau) ) d\xi \Bigg\}. \nonumber
\end{align}

Differentiating both parts of this equation by $x$ and substituting $x = x_l(\tau)$ we obtain a LIVESK for the gradient $\Psi(\tau, x_l(\tau))$
\begin{align}  \label{uFPsi}
\Psi(\tau, x_l(\tau)) &=  (x_l(\tau))^{-\nu} \Bigg\{ \frac{1}{2}\int_{0}^\tau x_l^{\nu + 1}(s) \Psi(s, x_l(s)) \varTheta'_{|\nu|}(\tau - s, x_l(\tau), x_l(s), x_l(\tau) ) ds \\
&- K x_l(0) \int_{x_l(0)}^\infty \xi^{\nu} \varTheta'_{|\nu|}(\tau, x_l(\tau), \xi, x_l(\tau) ) d\xi \Bigg\} + \frac{1}{x_l(\tau) } \nonumber \\
&+ \int_0^\tau \int_{x_l(s)}^\infty \left[ \lambda(s, \xi) - g(s,\xi) u(s,\xi) \right] \varTheta'_{|\nu|}(\tau - s, x_l(\tau), \xi, x_l(\tau) ) d\xi ds. \nonumber
\end{align}

\cref{uFfull,uFPsi} is a system of two LIVESK for the unknown dependent variables $u(\tau, x), \Psi(\tau, x_l(\tau))$. It can be solved numerically, similar to how this is described in \cref{secSolAsian}. Finally, following the definition in \eqref{forwardDef}, this solution for the ZCB price (expressed in the variable $u(\tau,x)$) can be substituted into \eqref{forwardDef} to compute the forward price. Thus, this solution builds a map between the variables $(\tau, x)$ and $f(\tau,x,Q)$. A reasonable choice would be to set $Q > t_0$. Then, when solving \eqref{wEqF}, every time the boundary $x_B(\tau)$ is given, we can use this solution to find the corresponding $f(\tau, x_B(\tau), Q)$ and substitute it into the boundary conditions in \eqref{wEqF}.

As follows from the analysis of \cref{betam1}, for the case $\beta = -1$, which corresponds to the Hull-White model, the solution of \cref{uFfull,uFPsi} can be significantly simplified. Due to the properties of the Weber-Orr Theta function given in Proposition~\ref{prop2}, \eqref{uFPsi} becomes an explicit semi-analytical expression for $\Psi(\tau, x_l(\tau))$ since the terms in the RHS corresponding to $s \to \tau$ vanish while the terms with $s < \tau$ are already known at the time $\tau$. Similarly, \eqref{uFfull} in this case becomes an explicit semi-analytical solution for $u(\tau,x)$, for more details, see the end of \cref{betam1}.

\section{Combining two regions together}

As we have already mentioned, CME trades options on 3M and 1M SOFR futures. These options are linked to the contract month of the
future, i.e., to the beginning of the reference period (the reference quarter for options on 3M SOFR futures). The key difference to the specifications of options on 3M SOFR futures from that on 1M SOFR futures is that both the 1M SOFR futures contract and the options on it end trading on the same day, i.e., on the last business day of the contract month, while trading in options on 3M SOFR futures ends before the reference quarter begins. This difference in specifications has two major consequences, \cite{HugginsSchaller}:
\begin{enumerate}
\item Unlike options on 3M SOFR futures, options on 1M SOFR futures undergo the transmogrification into an exotic Asian option during their lives.

\item Unlike options on 3M SOFR futures, options on 1M SOFR futures provide a complete series of hedging instruments for
caps and floors.
\end{enumerate}
Also, the strike prices of options on 1M SOFR futures do not cover a very large range. and are close to ATM.

Below, we consider a pricing problem of these options in more detail using the results, obtained in the previous sections.

\subsection{Options on 1M SOFR futures} \label{1mAmerican}

Since the 1M options on SOFR futures mandatory change their type during the option life, let us consider this process in more detail. Suppose that for pricing these options we use a backward (American) Monte Carlo simulation, \cite{Jackel2002}, and move along the $i$-th path representing a certain realization of the underlying process, see Fig.~\ref{path}. The paths are generated for two areas: $t < t_0$  where the underlying is the forward price of the 1M SOFR futures, and the reference period $t \ge t_0$ where the underlying is the daily SOFR. At the point $t=t_0$ the option changes its type from being an American one at $t < t_0$ to becoming an Asian-American option at $t_0 \le t \le T$.

Therefore, when running the backward step of the American Monte Carlo method, at the path $i$ and at the point $t=t_0$ there is a choice of how to proceed. The holder can exercise the American option a $t=t_0$ to get payoff $K - f^{1m}(0;t_0,T,r)$, where $f^{1m}(0;t_0,T,r)$ is the time $t_0$ rate of the 1M future with settlement at the time $T$, which depends on $r$ - the SOFR rate at $t_0$ along the $i$-th path. Alternatively, she can continue.

\begin{figure}[!htbp]
\centering
\fbox{\includegraphics[width=0.6\textwidth]{path.eps}}
\caption{A schematic Monte Carlo approach to illustrate the pricing of options on 1M SOFR futures (here $f(r_t)$ is some function of $r_t$).}
\label{path}
\end{figure}

If we know the $t_0$-price $P(t_0, y(r), z(r))$ of the Asian-American Put option with maturity $T$ conditional on $r$ for the reference period, then the realized payoff of the option at $t=t_0$ is (see \cref{contCompound,singul})
\begin{equation} \label{combPayoff}
\Phi = \max(K - f^{1m}(0;t_0,T,r), P(t_0, y(r), z(r)), \qquad y(r) = r - \barR^*(t_0), \, z(r) = r.
\end{equation}

\subsubsection{Computing $\bm{P(t_0, y(r), z(r))}$ } \label{AmerSol}

To recap, in \cref{Asian} we have developed an approach which provides a semi-analytical solution for the exercise boundary $z_B(\tau, x)$ and the European option price $u(\tau,x,z)$ in both continuation and the entire regions. Once this is done, the solution to the American problem can also be found by using these equations since the solution is obtained recurrently in time.\footnote{Rigorously speaking, this converts the American option into the Bermudan one. However, the option price should converge to the corresponding American option value when the integration step $\Delta \tau \to 0$.} Namely, the integration \eqref{ODE} in $z$ can again start from the exercise boundary (instead of infinity as for the European options) since it is already known as well as the option value and the option Delta at this boundary. Since we integrate \cref{uBessFullNew2,uBessFullPsiRec} sequentially in time, at every step the computed value of $u(\tau,x,z_j)$ can be compared with the intrinsic value $K - z_B(\tau,x)$. This means that for pricing American options, instead of $\bar{u}(\tau,x,z_j)$ in \cref{uBessFullNew2,uBessFullPsiRec} one has to use
\begin{equation}
\bar{u} = \max(\bar{u}(\tau,x,z_j),K - z_j), \qquad \bar{u}_z = \max(\bar{u}_z(\tau,x,z_j),-1).
\end{equation}
This method is similar to pricing American options using a binomial tree method, or a simple version of the FD method (rather than a more sophisticated and accurate approach of \cite{Halluin2004}).

\subsubsection{The Put option price at $\bm{t=0}$}

Since this payoff in \eqref{combPayoff} is conditional on the value $r$ (or $y$) at the time $t = t_0$, the {\it European} option price $P_E$ at $t=0$ is given by the expectation of it over all possible realizations of the underlying process, i.e.,
\begin{align}
P_E = \EQ \left[ e^{- \int_0^{t_0} r(s) ds} \max \left(K - f^{1m}(0;t_0,T,r), P(T, y(r), z(r) \right) \, \Big| \, r_0 \right] ,
\end{align}
\noindent or, more explicitly
\begin{equation} \label{combInt}
P_E = \int_{r_l}^\infty e^{- \int_0^{t_0} r(s) ds} \max \left(K - f^{1m}(0;t_0,T,r), P(T, y(\chi), z(\chi) \right)
\Psi(0, r_0 | t_0, \chi) d\chi, \qquad r_l = \barR^*(0) + y_l(0),
\end{equation}
\noindent where $\Psi(0, r_0 | t_0, \chi)$ is the density of the underlying process. It turns out that all components of this formula under the integral can be found by using the approach described in \cref{Asian,American}. Indeed, the Asian-American option price can be found by using the method described in \cref{Asian} and also above in this Section. The density function at the interval $t \in [0,t_0]$ can be computed by using the approach described in \cref{American} if one uses the Dirac Delta function as the terminal condition and chooses $T_f = t_0$. Alternatively, one can solve the problem in \cref{American} and use the payoff in \eqref{combPayoff} instead of \eqref{tchw}. In the former case, an additional integral in \eqref{combInt} should be computed, while the problem of finding the density function is simpler due to the terminal condition being a Delta function. In the latter case, no additional integration is required. In both cases we set $Q = T$.

Now, for the American option at the interval $t \in [0, t_0]$, we need to use the second approach. To recap, again this approach is valid only in the continuation region. However, it can be extended to provide an European Put option price in the whole domain of $z$, as this was described at the end of \cref{Asian}. Once this is done, the solution to the American problem can also be found as described in \cref{AmerSol}.

As mentioned in \cite{Skov2021}, the settlement of the 1M federal funds futures is based on the same specifications and the pricing formula is, therefore, valid for both SOFR and federal funds 1M futures traded at the CME.

A more detailed analysis of the results obtained by using this formalism will be presented elsewhere.

\subsection{Options on 3M SOFR futures} \label{amer3Mdes}

The 3M futures contract is based on the daily compounded reference rate during the contract quarter
\begin{equation}
R^{3 m}(t_0, T) = \frac{1}{T-t_0} \left( \prod_{i=1}^N \left[ 1+d_i R_{d_i}\left(t_i\right)\right] - 1 \right), \qquad
i \in 1,\ldots, N, \quad t_0 \leq t_1,\ldots,t_N \leq T,
\end{equation}
\noindent where $R_{d_i}(t_i)$ denotes the realized overnight rates in the reference quarter, and $d_{t_i}$ is the amount of days to which $R_{d_i}(t_i)$ applies. It can be approximated by the continuously compounded rate as, \cite{Mercurio2018}
\begin{equation}
R^{3 m}(t_0, T) \approx \frac{1}{T-t_0}\left(e^{\int_{t_0}^T r_s d s}-1\right)
\end{equation}
As shown in \cite{Skov2021}, the accuracy of the continuous approximation is of the order of $10^{-7}$ for all open contracts. The time $t$ rate of the 3M future starting to accrue at time $t_0$ and with settlement on time $T$ (so $T-t_0 = 0.25$) is given by
\begin{equation}
f^{3 m}(t ; t_0, T) = \frac{1}{T-t_0}\left(\mathbb{E}^Q\left[e^{\int_{t_0}^T r_s d s} \mid \mathcal{F}_t\right]-1\right)
\end{equation}

Note, that if $t_0 < t$ and part of the underlying rate has already accrued, this can be accounted for by using the discrete compounding, \cite{Skov2021}
\begin{align}
f^{3 m}(t;t_0,T) &= \frac{1}{T-t_0}\left\{ \left(\prod_{i=1}^{N_0}\left[1+d_i R_{d_i}\left(t_i\right)\right]\right) \mathbb{E}^Q \left[e^{\int_t^T r_s d s} \mid \mathcal{F}_t\right] - 1 \right\}, \\
i & \in 1,\ldots,N_0, \quad t_0 \leq t_1,\ldots,t_{N_0} \leq t, \nonumber
\end{align}
\noindent where $R_{d_i}(t_i)$ denotes the $\mathcal{F}_t$-measurable realized overnight rates.

The price of an American option written on $f^{3 m}(t;t_0,T)$ with $t < t_0$ can be computed by using the approach of \cref{American} with the extension described in \cref{AmerSol}. Again, a more detailed analysis is left to be presented elsewhere.


\section{Numerical example} \label{experiments}

In this section, our approach is illustrated by a numerical example where, for simplicity, we set $\beta = -1$, hence reducing the full CEV model to the time-dependent Hull-White model. We also solve only the problem described in \cref{Asian}, assuming that the initial parameters $y, \barr(t_0), R^*(t_0)$ are given.

It could be observed, that almost all the existing literature on pricing arithmetic Asian options of the American exercise style with fixed strike uses the Black-Scholes model with fixed coefficients for the underlying stock process. Thus, to compare our results with those in, e.g., \cite{ZvanForsythVetzal1997}, we mimic their settings by choosing $\alpha(t) = \alpha, \, \sigma(t) = \sigma$, i.e., by setting parameters of the model as in Table~\ref{tab1}.

\begin{table}[!htb]
\begin{center}
\begin{tabular}{|c|c|c|c|c|c|c|c|}
\hline
$\alpha$ & $\sigma$ & $\barR(t)$ & $T$ & $y$ & $x_{max}$   \\
\hline
-0.1 & 0.2 y  & -0.01 & 0.25 & 100 & 1000 \\
\hline
\end{tabular}
\caption{Parameters of the test.}
\label{tab1}
\end{center}
\end{table}
Here, $\sigma(t)$ is the normal volatility, therefore, we multiply it by the initial spot level $y$ to approximately mimic the corresponding log-normal volatility. Also, we run the test for a set of strikes $K \in [90, 95, 100, 105, 110, 120]$. Since variables $y$ and $x$ are defined at a semi-infinite interval, when doing numerical computations, we truncate the upper limit and set it to the value $x_{max}$.

We compute the exercise boundaries for the Asian-American Put option by using the numerical scheme in \cref{finalization}. The corresponding integrals in the time $\tau \in [0,\tau_m]$ are approximated by using the Simpson quadratures on a 3D grid, which contains $N_t = 40$ nodes in $\mathbb{T}$. The integrals in $x$ and $z$ are computed by using the trapezoid rule. We take $N_x = 200$ nodes in $\mathbb{X}$, as it turns out that the further increase of $N_x$ practically doesn't affect the results. We constructed unified grids for $\mathbb{T}$ and $\mathbb{Z}$ (with $N_z = 10$), while for $\mathbb{X}$ a non-uniform gird is constructed with nodes compressed close to $y$, less compressed close to $x_l(\tau)$, and rarefied as the running $x$ tends to $x_{max}$, see, e.g., \cite{ItkinBook} among others. Thus, the accuracy of the scheme is $O(1/N^4_t)$ in time for the temporal integrals from $0$ to $\tau_m$, $O(\left[\frac{\tau - \tau_m}{T}\right]^2)$ for the last temporal interval, and $O(1/N_z)$ in $z$\footnote{This accuracy could be easily increased, if necessary, by using the one-sided finite difference of the second order when approximating the first derivative in $z$, \cite{ItkinBook}. }.

The results are obtained in Matlab using two Intel Quad-Core i7-4790 CPUs, each 3.80 Ghz. Despite the fact that our Matlab code can be naturally vectorized, we didn't do it since in this example we used a simple method that can be approved in many different ways, i.e., see \cite{ItkinMuravey2024jd} and reference therein, among others.

Since $\beta = -1$, computation of the Weber-Orr Theta function simplifies as this is described in Proposition~\ref{prop2}. The workflow of computations is presented in Fig.~\ref{Algo}.
\begin{figure}[!htb]
