       \State \emph{{\bf Initialization}: All values of $\Psi(\tau, x_l(\tau), z)$, $z_B(\tau, x)$ and $u(\tau, x,z)$ at $\tau = 0$.}
        \For { $s \in [0, \tau]$ }                  \CommentF{Main loop in $\tau$}
            \For { $x \in [x_l(s), x_{max}]$} \CommentF{Run the first internal loop in $x$}
                \State 1. Compute $z_B(\tau,x)$ from \eqref{zbFinal}
