                \For {$\xi \in [z_B(s, x), z]$}
                    \State Find $\bar{u}(\tau, x, \xi_i)$ from \eqref{uBessFullNew2}
                \EndFor
             \EndFor
        \EndFor
    \EndProcedure
\end{algorithmic}
