	\section{Existence and Uniqueness of Equilibrium}\label{Append:prop:NE}
	Let $\boldsymbol a = (a_1, ~\dots, ~ a_{\kappa})^{\prime} \in \mathbb R^{\kappa}$ be a $\kappa$-dimensional vector. For any integer $i \in [1, ~\kappa]$, let $\mathcal{R}_{\boldsymbol a}(a_i)$ denote the rank of the component $a_i$ within the vector $\boldsymbol a$. Specifically, $\mathcal{R}_{\boldsymbol a}(a_i) = 1$ if $a_i$ is the largest component of $\boldsymbol a$, $\mathcal{R}_{\boldsymbol a}(a_i) = 2$ if $a_i$ is the second largest, and so on, up to $\mathcal{R}_{\boldsymbol a}(a_i) = \kappa$ if $a_i$ is the smallest component of $\boldsymbol a$. In the case of ties, any tied component may be arbitrarily chosen as the larger rank, as this does not affect the quantiles of $\boldsymbol a$.

	The following lemma will be used in the remainder of this section.

	\begin{lemma}\label{lemmaRank}
		For any $\kappa$-dimensional  vectors $\boldsymbol a = (a_1, ~\dots, ~ a_{\kappa})^{\prime}$ and $\tilde{\boldsymbol a} = (\tilde a_1, ~\dots, ~ \tilde a_{\kappa})^{\prime}$, if  for some indices $i$ and $j$, $\mathcal{R}_{\boldsymbol a}(a_i) = \mathcal{R}_{\tilde{\boldsymbol a}}(\tilde a_j)$, there then exists an index $m$ such that $\lvert a_i - \tilde a_j\rvert \leq \lvert a_m - \tilde a_m \rvert$.
	\end{lemma}

	\begin{proof}
		I distinguish the following configurations: Case 1: $a_i \leq a_j$ and $\tilde a_j \leq \tilde a_i$; Case 2: $a_i \leq a_j$ and $\tilde a_i \leq \tilde a_j$; Case 3: $a_j \leq a_i$ and $\tilde a_i \leq \tilde a_j$; and Case 4: $a_j \leq a_i$ and $\tilde a_j \leq \tilde a_i$. I can ignore Cases 3 and 4, as they reduce to Cases 1 and 2, respectively, when $i$ and $j$ are switched.

		\medskip
		\noindent \underline{Case 1}: $a_i \leq a_j$ and $\tilde a_j \leq \tilde a_i$. This case implies that $a_i - \tilde a_j \leq a_j - \tilde a_j$ and $a_i - \tilde a_j \geq a_i - \tilde a_i$. Thus, $ a_i - \tilde a_i \leq a_i - \tilde a_j \leq a_i - \tilde a_j$ which means that $\lvert a_i - \tilde a_j \rvert \leq \max \{\lvert a_i - \tilde a_i \rvert, ~ \lvert a_j - \tilde a_j \rvert\}$. Consequently, there exists $m \in \{i, j\}$ such that $\lvert a_i - \tilde a_j\rvert \leq \lvert a_m - \tilde a_m \rvert$.


		\medskip
		\noindent \underline{Case 2}: $a_i \leq a_j$ and $\tilde a_i \leq \tilde a_j$. If $a_i = a_j$, then $a_i - \tilde a_j = a_j - \tilde a_j$. Thus, one can choose $m = j$. Similarly, if $\tilde a_i = \tilde a_j$, then $a_i - \tilde a_j = a_i - \tilde a_i$, and one can choose $m = i$. 

		Now, assume that $a_i \ne a_j$ and $\tilde a_i \ne \tilde a_j$; that is, $a_i < a_j$ and $\tilde a_i < \tilde a_j$. %It follows that $\boldsymbol a$ and $\tilde{\boldsymbol a}$ must have more than two components. Otherwise, $\boldsymbol a = (a_i, ~ a_j)^{\prime}$ and $\tilde{\boldsymbol a}  = (\tilde a_i, ~ \tilde a_j)^{\prime}$, then the conditions $a_i < a_j$ and $\tilde a_i < \tilde a_j$ would imply that $\mathcal{R}_{\boldsymbol a}(a_i) = 2$ and $\mathcal{R}_{\tilde{\boldsymbol a}}(a_j) = 1$, which would contradict the assumption that  $\mathcal{R}_{\boldsymbol a}(a_i) = \mathcal{R}_{\tilde{\boldsymbol a}}(a_j)$. Therefore, $\boldsymbol a$ and $\tilde{\boldsymbol a}$ must have at least three components. Specifically, since $a_i < a_j$ and $\tilde a_i < \tilde a_j$, 
		The only way for the condition $\mathcal{R}_{\boldsymbol a}(a_i) = \mathcal{R}_{\tilde{\boldsymbol a}}(a_j)$ to hold is that there exists an index $s$ such that:
		\begin{equation}\label{eq:us}
			a_s \leq a_i < a_j \quad \text{and} \quad 
			\tilde a_i < \tilde a_j \leq \tilde a_s.
		\end{equation}


		\noindent The existence of such an index $s$ is necessary because the condition $\mathcal{R}_{\boldsymbol a}(a_i) = \mathcal{R}_{\tilde{\boldsymbol a}}(a_j)$ involves the following two requirements: (1) the number of components in $\boldsymbol a$ that are greater than or equal to $a_i$ must be equal to the number of components in $\tilde{\boldsymbol a}$ that are greater than or equal to $\tilde a_j$; (2) the number of components in $\boldsymbol a$ that are less than or equal to $a_i$ must be equal to the number of components in $\tilde{\boldsymbol a}$ that are less than or equal to $\tilde a_j$. 
		It follows from \eqref{eq:us} that $a_s - \tilde a_s \leq a_i - \tilde a_j \leq a_j - \tilde a_j$. Thus, $\lvert a_i - \tilde a_j \rvert \leq \max \{\lvert a_j - \tilde a_j \rvert, ~ \lvert a_s - \tilde a_s \rvert\}$. Consequently, there exists $m \in \{j, s\}$ such that $\lvert a_i - \tilde a_j\rvert \leq \lvert a_m - \tilde a_m \rvert$. This completes the proof of the lemma.\end{proof}

	\paragraph{Proof of Proposition \ref{prop:NE}}
	The best response function is given by:
	$$BR_i(\mathbf y_{-i}) = (1 - \sum_{\tau \in \mathcal{T}} \lambda_{\tau,2})\alpha_i + \sum_{\tau \in \mathcal{T}}(\lambda_{\tau,1} + \lambda_{\tau,2})q_{i,\tau}(\mathbf y_{-i}).$$
	Let $BR$ be the mapping from $\mathbb R^n$ into itself, defined by $BR(\mathbf y) = (BR_1(\mathbf y_{-1}), ~\dots, \break BR_n(\mathbf y_{-n}))^{\prime}$. To establish the existence and uniqueness of the Nash equilibrium, it is sufficient to demonstrate that $BR$ has a unique fixed point. The challenge here is that $BR$ is not differentiable; therefore, I cannot show that its Jacobian has a norm less than one.

	Let $\mathbf y$  and $\tilde{\mathbf y}$ be two vectors of outcomes in $\mathbb R^n$. Let $\lVert . \rVert_{\infty}$ denote the infinity norm.\footnote{For any $\mathbf a = (a_1, ~\dots, ~ a_n)^{\prime} \in \mathbb R^n$, the infinity norm of $\mathbf a$ is defined as $\displaystyle \lVert \mathbf a \rVert_{\infty} = \max_{i} \lvert a_i \rvert$.}
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\lVert BR(\mathbf y) - BR(\tilde{\mathbf y}) \rVert_{\infty} &= \max_i \lvert BR_i(\mathbf y_{-i}) - BR_i(\tilde{\mathbf y}_{-i}) \rvert,\nonumber \\
		\lVert BR(\mathbf y) - BR(\tilde{\mathbf y}) \rVert_{\infty} & \textstyle \leq \sum_{\tau \in \mathcal{T}}\left\{\lvert \lambda_{\tau,1} + \lambda_{\tau,2}\rvert  \max_i  \lvert q_{i,\tau}(\mathbf y_{-i}) - q_{i,\tau}(\tilde{\mathbf y}_{-i}) \rvert\right\} \label{eq:BRy}
	\end{align}  
	\endgroup


	By Equation \eqref{eq:defqtaui1}, $q_{\tau,i}(\mathbf y_{-i}) = (1 - \omega_i)y_{i,(\pi_i)}  + \omega_iy_{i,(\pi_i+1)}$  and $q_{\tau,i}(\tilde{\mathbf y}_{-i}) = (1 - \omega_i)\tilde y_{i,(\pi_i)}  + \omega_i\tilde y_{i,(\pi_i+1)}$. Note that the weight $\omega_i$ and the index $\pi_i$ are the same for both $\mathbf y$  and $\tilde{\mathbf y}$ because $\omega_i$ and $\pi_i$ depend only on the network (particularly the degrees) and $\tau$.\footnote{The weight $\omega_i$ and the index $\pi_i$ do not depend on $\mathbf y$  and $\tilde{\mathbf y}$ because $q_{\tau,i}$ is an unweighted quantile. I generalize Proposition \ref{prop:NE} to the case of weighted networks in Online Appendix \ref{OA:WeightedNet}.} Thus,
	\begin{equation}\label{ineq:qtau}
		\lvert q_{i,\tau}(\mathbf y_{-i}) - q_{i,\tau}(\tilde{\mathbf y}_{-i}) \rvert \leq(1 - \omega_i)\lvert y_{i,(\pi_i)} -  \tilde y_{i,(\pi_i)} \rvert + \omega_i\lvert y_{i,(\pi_i+1)} - \tilde y_{i,(\pi_i+1)}\rvert.
	\end{equation}

	Since $\mathcal{R}_{\mathbf y}(y_{i,(\pi_i)}) = \mathcal{R}_{\tilde{\mathbf y}}(\tilde y_{i,(\pi_i)}) = \pi_i$, Lemma \ref{lemmaRank} implies that there exists an index $m$ such that $\lvert y_{i,(\pi_i)} -  \tilde y_{i,(\pi_i)} \rvert \leq \lvert y_{m} -  \tilde y_{m}\rvert$. Thus,  $\lvert y_{i,(\pi_i)} -  \tilde y_{i,(\pi_i)} \rvert \leq \lVert \mathbf y -  \tilde{\mathbf y}\rVert_{\infty}$. Similarly, since $\mathcal{R}_{\mathbf y}(y_{i,(\pi_i + 1)}) = \mathcal{R}_{\tilde{\mathbf y}}(\tilde y_{i,(\pi_i + 1)}) = \pi_i + 1$, there exists an index $p$, such that $\lvert y_{i,(\pi_i + 1)} -  \tilde y_{i,(\pi_i + 1)} \rvert \leq \lvert y_{p} -  \tilde y_{p}\rvert$, which implies  $\lvert y_{i,(\pi_i + 1)} -  \tilde y_{i,(\pi_i + 1)} \rvert \leq \lVert \mathbf y -  \tilde{\mathbf y}\rVert_{\infty}$. Therefore, \eqref{ineq:qtau} leads to:
	\begin{equation}\label{ineq:qtau2}
		\lvert q_{i,\tau}(\mathbf y_{-i}) - q_{i,\tau}(\tilde{\mathbf y}_{-i}) \rvert \leq\lVert \mathbf y -  \tilde{\mathbf y}\rVert_{\infty}.
	\end{equation}

	By substituting \eqref{ineq:qtau2} into \eqref{eq:BRy}, I obtain $\lVert BR(\mathbf y) - BR(\tilde{\mathbf y}) \rVert_{\infty}  \textstyle \leq  \sum_{\tau \in \mathcal{T}}\lvert \lambda_{\tau,1} + \lambda_{\tau,2}\rvert  \lVert \mathbf y -  \tilde{\mathbf y}\rVert_{\infty}$. Since $\sum_{\tau \in \mathcal{T}}\lvert \lambda_{\tau,1} + \lambda_{\tau,2}\rvert < 1$, this means that $BR$ is a contraction. By the contraction mapping theorem, it has a unique fixed point. As a result, the game has a unique Nash equilibrium.

	%\section{Identification of Model Parameters}\label{Append:prop:ident}
	%Given that $\tilde{\boldsymbol{\beta}}_1 = (1 - \lambda_2)\boldsymbol{\beta}_1$, the identification of both $\boldsymbol{\beta}_1$ and $\tilde{\boldsymbol{\beta}}_1$ implies that $\lambda_{2}$ is identified. Similarly, $\boldsymbol{\beta}_2$ is identified from the condition $\tilde{\boldsymbol{\beta}}_2 = (1 - \sum_{\tau} \lambda_{\tau,2})\boldsymbol{\beta}_2$, as both $\tilde{\boldsymbol{\beta}}_2$ and $\sum_{\tau} \lambda_{\tau,2}$ are identified.

