	\section{Proof of Proposition \ref{prop:encompassing}}\label{Append:encompassing}
	The GMM estimator $\hat{\boldsymbol{\psi}}_b$ is given by
	\begin{equation}\label{eq:psihat}
		\hat{\boldsymbol{\psi}}_b = \hat{\mathbf{H}}_b^{-1} \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \mathbf{y}^{niso},
	\end{equation}
	where $\hat{\mathbf{H}}_b = \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \hat{\mathbf{V}}_b^{niso}$. To determine $\plim_{\mathcal{T}_a} \hat{\boldsymbol{\psi}}_b$, I assume that the data are generated according to the model with quantile set $\mathcal{T}_a$. In this case, the true data-generating process is $\mathbf{y}^{niso} = \mathbf{V}_a^{niso} \boldsymbol{\psi}_a + \boldsymbol{\varepsilon}_a^{niso}$, with $\boldsymbol{\varepsilon}_a^{niso} = \boldsymbol{\varepsilon}^{niso}$. Consequently, both $\mathbf{Z}_a^{niso}$ and $\mathbf{Z}_b^{niso}$ are exogenous with respect to $\boldsymbol{\varepsilon}_a^{niso}$. Substituting the expression for $\mathbf{y}^{niso}$ into Equation~\eqref{eq:psihat} yields:
	$$
	\hat{\boldsymbol{\psi}}_b = \hat{\mathbf{H}}_b^{-1} \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \mathbf{V}_a^{niso} \boldsymbol{\psi}_a + \hat{\mathbf{H}}_b^{-1} \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \boldsymbol{\varepsilon}_a^{niso}.
	$$


	The second term on the right-hand side is asymptotically zero because $\mathbf Z_b^{niso}$ is exogenous with respect to $\boldsymbol{\varepsilon}_a^{niso}$. Indeed, this term can be written as:
	$$
	\left(\frac{\hat{\mathbf{V}}_b^{niso\prime} \mathbf Z_b^{niso}}{S} \mathbf W_b^{niso} \frac{\mathbf Z_b^{niso\prime} \hat{\mathbf{V}}_b^{niso}}{S}\right)^{-1} \frac{\hat{\mathbf{V}}_b^{niso\prime} \mathbf Z_b^{niso}}{S} \mathbf W_b^{niso} \frac{\mathbf Z_b^{niso\prime} \boldsymbol{\varepsilon}^{niso}_a}{S},
	$$
	where $\dfrac{\mathbf Z_b^{niso\prime} \boldsymbol{\varepsilon}^{niso}_a}{S}$ is asymptotically zero by exogeneity of $\mathbf Z_b^{niso}$. Therefore,
	\begin{equation}\label{eq:plimapsi}
		\plim_{\mathcal{T}_a} \hat{\boldsymbol{\psi}}_b = \plim \left(\hat{\mathbf H}^{-1}_b\, \hat{\mathbf{V}}_b^{niso\prime} \mathbf Z_b^{niso} \mathbf W_b^{niso}\mathbf Z_b^{niso\prime} \mathbf V_a^{niso} \boldsymbol{\psi}_a\right).
	\end{equation}


	As $\boldsymbol\delta_{a,b} = \plim \hat{\boldsymbol{\psi}}_b - \plim_{\mathcal{T}_a} \hat{\boldsymbol{\psi}}_b$, Equations~\eqref{eq:psihat} and~\eqref{eq:plimapsi} imply that:
	\begingroup
	\allowdisplaybreaks
	\begin{align*}
		\boldsymbol\delta_{a,b}& = \plim \left(\hat{\mathbf H}^{-1}_b\, \hat{\mathbf{V}}_b^{niso\prime} \mathbf Z_b^{niso} \mathbf W_b^{niso}\mathbf Z_b^{niso\prime}(\mathbf y^{niso} - \mathbf V_a^{niso} \boldsymbol \psi_a)\right),\\
		\boldsymbol\delta_{a,b} &= \plim \hat{\mathbf H}^{-1}_b\, \hat{\mathbf{V}}_b^{niso\prime} \mathbf Z_b^{niso} \mathbf W_b^{niso}\mathbf Z_b^{niso\prime}\boldsymbol{\varepsilon}^{niso}_a.
	\end{align*}
	\endgroup

	\noindent As $\hat{\boldsymbol{\varepsilon}}_a^{niso}$ is a consistent estimator of $\boldsymbol{\varepsilon}^{niso}_a$ component by component, the previous equation suggests that $\boldsymbol{\delta}_{a,b}$ can be estimated by $\hat{\mathbf{H}}_b^{-1} \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso}$. However, componentwise consistency of $\hat{\boldsymbol{\varepsilon}}_a^{niso}$ is not sufficient to justify the substitution of $\boldsymbol{\varepsilon}^{niso}_a$ with $\hat{\boldsymbol{\varepsilon}}_a^{niso}$ in this expression. It is also necessary to ensure that $\dfrac{\mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso}}{S}$ consistently estimates $\dfrac{\mathbf{Z}_b^{niso\prime} \boldsymbol{\varepsilon}^{niso}_a)}{S}$. I therefore introduce the following weak conditions.

	\begin{assumption}\label{ass:encompassing}The parameters $\boldsymbol{\beta}_1$ and $\boldsymbol{\psi}_a$ lie in compact spaces. Additionally, the variables $\boldsymbol{x}_{s,i}$ and $y_{s,i}$ are uniformly bounded in probability.
	\end{assumption}

	\noindent Under Assumption~\ref{ass:encompassing}, the derivatives of $(\mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso})/S$ with respect to $\hat{\boldsymbol{\beta}}_1$ and $\hat{\boldsymbol{\psi}}_a$ are bounded in probability, implying that $\plim (\mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso})/S = \plim (\mathbf{Z}_b^{niso\prime} \boldsymbol{\varepsilon}_a^{niso})/S$.\footnote{This follows from the mean value theorem, which implies that $(\mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso})/S - (\mathbf{Z}_b^{niso\prime} \boldsymbol{\varepsilon}_a^{niso})/S$ is proportional to $\lVert \hat{\boldsymbol{\beta}}_1 - \boldsymbol{\beta}_1 \rVert + \lVert \hat{\boldsymbol{\psi}}_a - \boldsymbol{\psi}_a \rVert$.} As a result, $\hat{\boldsymbol{\delta}}_{a,b} = \hat{\mathbf{H}}_b^{-1} \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso}$ is a consistent estimator of $\boldsymbol{\delta}_{a,b}$. The asymptotic distribution of $\sqrt{S}\, (\hat{\boldsymbol{\delta}}_{a,b} - \boldsymbol{\delta}_{a,b})$ is presented in Online Appendix~\ref{OA:other:encompassing}.


