	\section{Microeconomic Foundations with Weighted Networks}\label{OA:WeightedNet}
	In this section, I demonstrate the existence and uniqueness of equilibrium and discuss instrumental variables for quantile peer outcomes in the context of weighted networks. The network is represented by an adjacency matrix $\mathbf{G} = [g_{ij}]$ of dimension $n \times n$, where $g_{ij}$ is a nonnegative variable (not necessarily binary) that measures the intensity of the outgoing link from agent $i$ to agent $j$.

	\subsection{Sample Weighted Quantiles}\label{OA:QWeightedNet}
	Since the network is weighted, I replace the sample quantile in Equation \eqref{eq:defqtaui} with a sample weighted quantile, where the weight of $y_{j}$ is $g_{ij}$. The definition of the sample quantile in Appendix \ref{Append:sampleQ} %\citepoa{hyndman1996sampleoa} 
	can be generalized to sample weighted quantiles. 

	Let $g_{i,(1)}$, \dots, $g_{i,(d_i)}$ be the weights corresponding to $y_{i,(1)}$, \dots, $y_{i,(d_i)}$, respectively, and define $G_{i,l} = \sum_{k = 1}^{l} g_{i,(k)}$. Let $\hat{k}$ be the largest integer such that $\dfrac{G_{i,\hat k}}{G_{i,d_i}}  \leq \tau$. The weighted sample quantile is given by formula \eqref{eq:defqtaui1} but with different weight $\omega_i$ and index $\pi_i$:
	$$q_{\tau,i}(\mathbf y_{-i}) = (1 - \omega_i)y_{i,(\pi_i)}  + \omega_iy_{i,(\pi_i+1)}, \text{ where }$$$$
	\pi_i = \left\lfloor \hat k + 1 - \tau + (\tau G_{i,d_i} - G_{i,\hat k})/g_{i,(\hat k + 1)}\right\rfloor \text{ and } $$$$
	\omega_i = \hat k + 1- \tau + (\tau G_{i,d_i} - G_{i,\hat k})/g_{i,(\hat k + 1)} - \pi_i.$$
	The higher the intensity of the outgoing link from $i$ to $\hat k + 1$, the greater the weight of $y_{i,(\hat k + 1)}$. The weight $\omega_i$ and the index $\pi_i$ depend on $\mathbf y_{-i}$.



	\subsection{Existence and Uniqueness of Equilibrium with Weighted Networks}\label{OA:NEWeightedNet}
	To establish the existence and uniqueness of the Nash equilibrium with weighted networks, I first present the following lemma.
	\begin{lemma}\label{lemmaQuant}
		For any outcomes $\mathbf y = (y_1, ~\dots, ~ y_n)^{\prime}$ and $\tilde{\mathbf y} = (\tilde y_1, ~\dots, ~ \tilde y_{n})^{\prime}$ and a quantile level $\tau \in [0, ~1]$, 
		we have $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq \lVert \mathbf y - \tilde{\mathbf y} \rVert_{\infty}$.
	\end{lemma}
	\begin{proof}
		Following the notation in Section \ref{OA:QWeightedNet}, we have $q_{\tau,i}(\mathbf y_{-i}) = (1 - \omega_i)y_{i,(\pi_i)}  + \omega_iy_{i,(\pi_i+1)}$ and $q_{\tau,i}(\tilde{\mathbf y}_{-i}) = (1 - \tilde\omega_i)\tilde y_{i,(\tilde\pi_i)}  + \tilde\omega_i\tilde y_{i,(\tilde\pi_i+1)}$, where $\tilde\omega_i$ and $\tilde\pi_i$ are the weight and index for $\tilde{\mathbf y}_{-i}$. I first consider the case where $\pi_i \ne \tilde\pi_i$ and then the case where $\pi_i = \tilde\pi_i$.


		\medskip
		\noindent \underline{Case 1}: $\pi_i \ne \tilde\pi_i$. If $y_{i,(\pi_i)}$ and $\tilde y_{i,(\tilde\pi_i)}$ do not have the same rank within $\mathbf y_{-i}$ and $\tilde{\mathbf y}_{-i}$, respectively, then there exist indices $s$ and $p$ such that $y_{s} \leq y_{i,(\pi_i)} \leq y_{i,(\pi_i + 1)} \leq y_{p}$ and $\tilde y_{p} \leq \tilde y_{i,(\tilde\pi_i)} \leq \tilde y_{i,(\tilde\pi_i+1)} \leq \tilde y_{s}$. Thus, $y_{s} \leq q_{\tau,i}(\mathbf y_{-i}) \leq y_{p}$ and $\tilde y_{p} \leq q_{\tau,i}(\tilde{\mathbf y}_{-i}) \leq \tilde y_{s}$. Therefore, $y_{s} - \tilde y_{s} \leq q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \leq y_{p} - \tilde y_{p}$, which implies that there exists an index $m\in\{s, p\}$ such that $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq \lvert y_{m} - \tilde y_{m} \rvert$. Consequently, $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq \lVert \mathbf y - \tilde{\mathbf y} \rVert_{\infty}$.

		\medskip
		\noindent \underline{Case 2}: $\pi_i = \tilde\pi_i$. If, in addition, $\omega_i = \tilde \omega_i$, then $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq (1 - \omega_i)\lvert y_{i,(\pi_i)} - \tilde y_{i,(\pi_i)}\rvert + \omega_i\lvert y_{i,(\pi_i + 1)} - \tilde y_{i,(\pi_i + 1)}\rvert $. By Lemma \ref{lemmaRank}, there exist indices $s$ and $p$, such that  $\lvert y_{i,(\pi_i)} - \tilde y_{i,(\pi_i)}\rvert \leq \lvert y_{s} - \tilde y_s \rvert$ and $\lvert y_{i,(\pi_i + 1)} - \tilde y_{i,(\pi_i + 1)}\rvert \leq \lvert y_{p} - \tilde y_p \rvert$. Therefore, $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq \lVert \mathbf y - \tilde{\mathbf y} \rVert_{\infty}$.

		Assume now that $\omega_i \ne \tilde \omega_i$. The only way this can hold while $\pi_i = \tilde\pi_i$ is if $\mathbf y_{-i}$ and $\tilde{\mathbf y}_{-i}$ are sorted differently, such that there exist indices $s$ and $p$ with $y_{s} \leq y_{i,(\pi_i)} \leq y_{i,(\pi_i + 1)} \leq y_{p}$ and $\tilde y_{p} \leq \tilde y_{i,(\tilde\pi_i)} \leq \tilde y_{i,(\tilde\pi_i+1)} \leq \tilde y_{s}$. Indeed, the condition $\omega_i \ne \tilde \omega_i$ requires that the sum of the weights of the $\pi_i$ (or, respectively, $\pi_i + 1$) smallest elements of $\mathbf y_{-i}$ be different from the sum of the weights of the $\pi_i$ (or, respectively, $\pi_i + 1$) smallest elements of $\tilde{\mathbf y}_{-i}$. As in Case 1, if $y_{s} \leq y_{i,(\pi_i)} \leq y_{i,(\pi_i + 1)} \leq y_{p}$ and $\tilde y_{p} \leq \tilde y_{i,(\tilde\pi_i)} \leq \tilde y_{i,(\tilde\pi_i+1)} \leq \tilde y_{s}$, then $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq \lVert \mathbf y - \tilde{\mathbf y} \rVert_{\infty}$. This completes the proof of the lemma.\end{proof}

	Using  Lemma \ref{lemmaQuant}, I establish the existence and uniqueness of equilibrium.

	\begin{proposition}\label{prop:NEWeight} Assume that the network is weighted and that the utility function of each individual $i\in\mathcal{N}$ is given \eqref{eq:utility}, with $\sum_{\tau \in \mathcal{T}}\lvert \lambda_{\tau} \rvert < 1$. Then, there exists a unique Nash equilibrium $\mathbf y^{\ast} = (y_1^{\ast}, ~\dots,   y_n^{\ast})^{\prime}$ such that $y_i^{\ast} = BR_i(\mathbf{y}^{\ast}_{-i})$ for all $i$.
	\end{proposition}

	\begin{proof}
		Let $BR$ be the mapping from $\mathbb R^n$ into itself, defined by $BR(\mathbf y) = (BR_1(\mathbf y_{-1}), ~\dots, \break BR_n(\mathbf y_{-n}))^{\prime}$. As in Appendix \ref{Append:prop:NE}, it is sufficient to demonstrate that $BR$ has a unique fixed point.   We have 
		\begingroup
		\allowdisplaybreaks
		\begin{align*}
			\lVert BR(\mathbf y) - BR(\tilde{\mathbf y}) \rVert_{\infty} &= \max_i \lvert BR_i(\mathbf y_{-i}) - BR_i(\tilde{\mathbf y}_{-i}) \rvert,\nonumber \\
			\lVert BR(\mathbf y) - BR(\tilde{\mathbf y}) \rVert_{\infty} & \textstyle \leq \sum_{\tau \in \mathcal{T}}\left\{\lvert \lambda_{\tau,1} + \lambda_{\tau,2}\rvert  \max_i  \lvert q_{i,\tau}(\mathbf y_{-i}) - q_{i,\tau}(\tilde{\mathbf y}_{-i}) \rvert\right\} 
		\end{align*}  
		\endgroup
		By Lemma \ref{lemmaQuant}, $\lvert q_{\tau,i}(\mathbf y_{-i}) - q_{\tau,i}(\tilde{\mathbf y}_{-i}) \rvert \leq \lVert \mathbf y - \tilde{\mathbf y} \rVert_{\infty}$, which implies that \break $\lVert BR(\mathbf y) - BR(\tilde{\mathbf y}) \rVert_{\infty}  \textstyle \leq  \sum_{\tau \in \mathcal{T}}\lvert \lambda_{\tau,1} + \lambda_{\tau,2}\rvert  \lVert \mathbf y -  \tilde{\mathbf y}\rVert_{\infty}$. Since $\sum_{\tau \in \mathcal{T}}\lvert \lambda_{\tau,1} + \lambda_{\tau,2}\rvert < 1$, it follows that $BR$ is a contraction. By the contraction mapping theorem, it has a unique fixed point. As a result, the game has a unique Nash equilibrium.
	\end{proof}

	\section{Supplementary Results on the Econometric Model} \label{OA:other}
	For notational ease, I assume throughout this section that Equations~\eqref{eq:model:iso} and~\eqref{eq:model:niso} are expressed in deviations from the group mean, so that the fixed effect terms are eliminated. I use the superscript $iso$ to denote variables corresponding to isolated agents, and the superscript $niso$ for variables corresponding to non-isolated agents.

	\subsection{Limiting Distribution of the Parameter Estimator}
	\label{OA:other:limit}

	Estimation proceeds in two stages. The first stage is an ordinary least-squares (OLS) regression based on the equation:
	$$
	\mathbf{y}^{iso} = \mathbf{X}^{iso} \boldsymbol{\beta}_1 + \boldsymbol{\varepsilon}^{iso},
	$$
	where $\mathbf{y}^{iso}$ is the vector of $y_{s,i}^{iso}$, $\mathbf{X}^{iso}$ is the matrix whose rows are $\boldsymbol{x}_{s,i}^{iso}$, and $\boldsymbol{\varepsilon}^{iso}$ is the vector of $\varepsilon_{s,i}^{iso}$. Let $\hat{\boldsymbol{\beta}}_1$ denote the OLS estimator of $\boldsymbol{\beta}_1$.

	The second stage is a generalized method of moments (GMM) estimation based on the equation:
	$$
	\mathbf{y}^{niso} = \mathbf{V}^{niso} \boldsymbol{\psi} + \boldsymbol{\varepsilon}^{niso},
	$$
	where $\mathbf{y}^{niso}$ is the vector of $y_{s,i}^{niso}$, and $\mathbf{V}^{niso}$ is the matrix whose row corresponding to agent $i$ in subnetwork $s$ is $(q_{s,i,\tau_1}^{niso},~\dots,~q_{s,i,\tau_{d_t}}^{niso},~\boldsymbol{x}_{s,i}^{niso\prime} \boldsymbol{\beta}_1,~\bar{\boldsymbol{x}}_{s,i}^{niso\prime})$. The parameter vector is $\boldsymbol{\psi} = (\lambda_{\tau_1},~\dots,~\lambda_{\tau_{d_t}},~1 - \lambda_2,~\tilde{\boldsymbol{\beta}}_2)^{\prime}$, and $\boldsymbol{\varepsilon}^{niso}$ is the vector of $\varepsilon_{s,i}^{niso}$. 

	The matrix $\mathbf{V}^{niso}$ depends on the unknown parameter $\boldsymbol{\beta}_1$. The GMM estimation is carried out by replacing $\boldsymbol{\beta}_1$ with its OLS estimator $\hat{\boldsymbol{\beta}}_1$. Let $\hat{\mathbf{V}}^{niso}$ denote the matrix obtained by substituting $\hat{\boldsymbol{\beta}}_1$ for $\boldsymbol{\beta}_1$ in $\mathbf{V}^{niso}$, and let $\hat{\boldsymbol{\psi}}$ denote the resulting GMM estimator of $\boldsymbol{\psi}$.

	The first-order conditions from the OLS and GMM steps imply:
	\begingroup
	\allowdisplaybreaks
	\begin{align}\label{eq:foc}
		\begin{split}
			&\mathbf{X}^{iso\prime} \mathbf{X}^{iso} (\hat{\boldsymbol{\beta}}_1 - \boldsymbol{\beta}_1) = \mathbf{X}^{iso\prime} \boldsymbol{\varepsilon}^{iso}, \\
			&\hat{\mathbf{V}}^{niso\prime} \mathbf{Z}^{niso} \mathbf{W}^{niso} \mathbf{Z}^{niso\prime} (\hat{\mathbf{V}}^{niso} \hat{\boldsymbol{\psi}} - \mathbf{V}^{niso} \boldsymbol{\psi}) = \hat{\mathbf{V}}^{niso\prime} \mathbf{Z}^{niso} \mathbf{W}^{niso} \mathbf{Z}^{niso\prime} \boldsymbol{\varepsilon}^{niso},
		\end{split}
	\end{align}
	\endgroup
	where $\mathbf{Z}^{niso}$ is the instrument matrix and $\mathbf{W}^{niso}$ is the GMM weighting matrix.



	Let $\boldsymbol{\Gamma} = (\boldsymbol{\beta}_1^{\prime}, ~ \boldsymbol{\psi}^{\prime})^{\prime}$ be the full parameter vector and $\hat{\boldsymbol{\Gamma}} = (\hat{\boldsymbol{\beta}}_1^{\prime}, ~ \hat{\boldsymbol{\psi}}^{\prime})^{\prime}$ its estimator. By applying the mean value theorem to $\hat{\mathbf{V}}^{niso} \hat{\boldsymbol{\psi}} - \mathbf{V}^{niso} \boldsymbol{\psi}$, with respect to $\hat{\boldsymbol{\Gamma}}$, \eqref{eq:foc} implies:
	$$
	\underbrace{\begin{pmatrix}
			\mathbf{I}_{d_1} & \mathbf{0} \\
			\mathbf{0} & \hat{\mathbf{V}}^{niso\prime} \mathbf{Z}^{niso} \mathbf{W}^{niso}
	\end{pmatrix}}_{\mathbb{B}}
	\underbrace{\begin{pmatrix}
			\mathbf{X}^{iso\prime} \mathbf{X}^{iso} & \mathbf{0} \\
			(1 - \lambda_2) \mathbf{Z}^{niso\prime} \mathbf{X}^{niso} & \mathbf{Z}^{niso\prime} \mathbf{V}^{niso}
	\end{pmatrix}}_{\mathbb{F}}
	(\hat{\boldsymbol{\Gamma}} - \boldsymbol{\Gamma}) = \mathbb{B} \boldsymbol{u},
	$$
	where $\mathbf{I}_{d_1}$ is the $d_1 \times d_1$ identity matrix, and
	$$
	\boldsymbol{u} = \begin{pmatrix}
		\mathbf{X}^{iso\prime} \boldsymbol{\varepsilon}^{iso} \\
		\mathbf{Z}^{niso\prime} \boldsymbol{\varepsilon}^{niso}
	\end{pmatrix}.
	$$



	By applying a standard central limit theorem to $\boldsymbol{u} / \sqrt{S}$, it follows that $\sqrt{S}(\hat{\boldsymbol{\Gamma}} - \boldsymbol{\Gamma})$ is asymptotically normally distributed with mean zero and asymptotic variance
	$$
	\left( \frac{\mathbb{B}}{S}\, \frac{\mathbb{F}}{S} \right)^{-1}
	\frac{\mathbb{B}}{S} \, \mathbb{V}ar(\boldsymbol{u}/\sqrt{S})
	\frac{\mathbb{B}^\prime}{S} \,
	\left( \frac{\mathbb{F}^\prime}{S} \,\frac{\mathbb{B}^\prime}{S} \right)^{-1},
	$$
	where $\mathbb{V}ar \left( \boldsymbol{u} / \sqrt{S} \right)$ denotes the asymptotic variance of $\boldsymbol{u} / \sqrt{S}$, which can be easily estimated as is the case in standard GMM procedures. 

	The asymptotic variance of the structural parameters can then be obtained from the asymptotic variance of $\sqrt{S}(\hat{\boldsymbol{\Gamma}} - \boldsymbol{\Gamma})$ using the Delta method.

	\subsection{\texorpdfstring{Asymptotic Distribution of $\sqrt{S}\, (\hat{\boldsymbol{\delta}}_{a,b} - \boldsymbol{\delta}_{a,b})$}{Asymptotic Distribution of sqrt(S)(delta_ab hat - delta_ab)}}
	\label{OA:other:encompassing}
	The estimator $\hat{\boldsymbol{\delta}}_{a,b}$ is given by
	\begin{equation}\label{eq:delta}
		\hat{\boldsymbol{\delta}}_{a,b} = \hat{\mathbf{H}}_b^{-1} \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \hat{\boldsymbol{\varepsilon}}_a^{niso},
	\end{equation}
	where $\hat{\mathbf{H}}_b = \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \hat{\mathbf{V}}_b^{niso}$. Given that $\hat{\boldsymbol{\varepsilon}}_a^{niso} = \mathbf y^{niso} - \hat{\mathbf V}_a^{niso} \hat{\boldsymbol{\psi}}_a$ and the representation of $\mathbf y^{niso}$ under $\mathcal{T}_a$ is $\mathbf y^{niso} = \mathbf V_a^{niso} \boldsymbol{\psi}_a + \boldsymbol{\varepsilon}_a^{niso}$, it follows that $\hat{\boldsymbol{\varepsilon}}_a^{niso} = \mathbf V_a^{niso} \boldsymbol{\psi}_a - \hat{\mathbf V}_a^{niso} \hat{\boldsymbol{\psi}}_a + \boldsymbol{\varepsilon}_a^{niso}$. Substituting $\hat{\boldsymbol{\varepsilon}}_a^{niso}$ into \eqref{eq:delta} and rearranging terms yields
	\begin{align}
		&\hat{\mathbf{H}}_b\hat{\boldsymbol{\delta}}_{a,b} = \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} (\mathbf V_a^{niso} \boldsymbol{\psi}_a - \hat{\mathbf V}_a^{niso} \hat{\boldsymbol{\psi}}_a + \boldsymbol{\varepsilon}_a^{niso}),\nonumber\\
		& \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime}(\hat{\mathbf V}_b^{niso}\hat{\boldsymbol{\delta}}_{a,b}  + \hat{\mathbf V}_a^{niso} \hat{\boldsymbol{\psi}}_a - \mathbf V_a^{niso} \boldsymbol{\psi}_a) = \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso} \mathbf{Z}_b^{niso\prime} \boldsymbol{\varepsilon}_a^{niso},\nonumber\\
		\begin{split}& \mathbb B^{\ast}_{b} \mathbf{Z}_b^{niso\prime}(\hat{\mathbf V}_b^{niso}\hat{\boldsymbol{\delta}}_{a,b} - \mathbf V_b^{niso}\boldsymbol{\delta}_{a,b}  + \hat{\mathbf V}_a^{niso} \hat{\boldsymbol{\psi}}_a - \mathbf V_a^{niso} \boldsymbol{\psi}_a) = \\ & 
			\quad\quad\quad\quad \mathbb B^{\ast}_{b} \mathbf{Z}_b^{niso\prime} (\boldsymbol{\varepsilon}_a^{niso} - \mathbf V_b^{niso}\boldsymbol{\delta}_{a,b}),
		\end{split} \label{eq:ortho:delta}
	\end{align}
	where $\mathbb{B}^{\ast}_{b} = \hat{\mathbf{V}}_b^{niso\prime} \mathbf{Z}_b^{niso} \mathbf{W}_b^{niso}$. Equation~\eqref{eq:ortho:delta} is the orthogonality condition for $\hat{\boldsymbol{\delta}}_{a,b}$. This equation depends on the estimators $\hat{\boldsymbol{\beta}}_1$ and $\hat{\boldsymbol{\psi}}_a$. The orthogonality conditions for these estimators follow from Equation~\eqref{eq:foc}:
	\begin{align}\label{eq:ortho:psia}
		\begin{split}
			&\mathbf{X}^{iso\prime} \mathbf{X}^{iso} (\hat{\boldsymbol{\beta}}_1 - \boldsymbol{\beta}_1) = \mathbf{X}^{iso\prime} \boldsymbol{\varepsilon}^{iso}, \\
			&\mathbb B^{\ast}_{a} \mathbf{Z}^{niso\prime}_a (\hat{\mathbf{V}}^{niso}_a \hat{\boldsymbol{\psi}}_a - \mathbf{V}^{niso}_a \boldsymbol{\psi}_a) = \mathbb B^{\ast}_{a} \mathbf{Z}^{niso\prime}_a \boldsymbol{\varepsilon}^{niso}_a,
		\end{split}
	\end{align}
	where $\mathbb B^{\ast}_{a} = \hat{\mathbf{V}}_a^{niso\prime} \mathbf{Z}_a^{niso} \mathbf{W}_a^{niso}$. Let $\boldsymbol{\Gamma}^{\ast} = (\boldsymbol{\beta}_1^{\prime}, ~ \boldsymbol{\psi}^{\prime}_a, ~\boldsymbol{\delta}_{a,b})^{\prime}$ be the full parameter vector, and let $\hat{\boldsymbol{\Gamma}}^{\ast} = (\hat{\boldsymbol{\beta}}_1^{\prime}, ~ \hat{\boldsymbol{\psi}}_a^{\prime}, ~\hat{\boldsymbol{\delta}}_{a,b})^{\prime}$ be its estimator. By applying the mean value theorem to $\hat{\mathbf V}_b^{niso}\hat{\boldsymbol{\delta}}_{a,b} - \mathbf V_b^{niso}\boldsymbol{\delta}_{a,b}$ and $\hat{\mathbf V}_a^{niso} \hat{\boldsymbol{\psi}}_a - \mathbf V_a^{niso} \boldsymbol{\psi}_a$ with respect to $\hat{\boldsymbol{\Gamma}}^{\ast}$ \eqref{eq:ortho:delta} and \eqref{eq:ortho:psia} imply:
	$$
	\underbrace{\begin{pmatrix}
			\mathbf{I}_{d_1} & \mathbf{0} & \mathbf{0} \\
			\mathbf{0} & \mathbb B^{\ast}_{a} & \mathbf{0} \\
			\mathbf{0} & \mathbf{0} & \mathbb B^{\ast}_{b}
	\end{pmatrix}}_{\mathbb{B}^{\ast}}
	\underbrace{\begin{pmatrix}
			\mathbf{X}^{iso\prime} \mathbf{X}^{iso} & \mathbf{0} & \mathbf{0} \\
			(1 - \lambda_{2,a}) \mathbb{F}^{\ast}_{a1} & \mathbb{F}^{\ast}_{a2} & \mathbf{0} \\
			(1 - \lambda_{2,a} + \delta_{a,b,1})\mathbb{F}^{\ast}_{b1} & \mathbb{F}^{\ast}_{b2} & \mathbb{F}^{\ast}_{b3}\end{pmatrix}}_{\mathbb{F}^{\ast}}
	(\hat{\boldsymbol{\Gamma}}^{\ast} - \boldsymbol{\Gamma}^{\ast}) = \mathbb{B}^{\ast} \boldsymbol{u}^{\ast},
	$$
	where $\mathbb{F}^{\ast}_{a1} = \mathbf{Z}^{niso\prime}_a \mathbf{X}^{niso}$, $\mathbb{F}^{\ast}_{a2} = \mathbf{Z}^{niso\prime}_a \mathbf{V}^{niso}_a$, $\mathbb{F}^{\ast}_{b1} = \mathbf{Z}^{niso\prime}_b \mathbf{X}^{niso}$, $\mathbb{F}^{\ast}_{b2} = \mathbf{Z}^{niso\prime}_b \mathbf{V}^{niso}_a$ and $\mathbb{F}^{\ast}_{b3} = \mathbf{Z}^{niso\prime}_b \mathbf{V}^{niso}_b$. The terms $1 - \lambda_{2,a}$ and $\delta_{a,b,1}$ are the coefficients associated with $\boldsymbol{x}_{s,i}^{\prime} \boldsymbol{\beta}_1$ in $\boldsymbol{\psi}_a$ and $\boldsymbol{\delta}_{a,b}$, respectively. The vector $\boldsymbol{u}^{\ast}$ is given by
	$$
	\boldsymbol{u}^{\ast} = \begin{pmatrix}
		\mathbf{X}^{iso\prime} \boldsymbol{\varepsilon}^{iso} \\
		\mathbf{Z}^{niso\prime}_a \boldsymbol{\varepsilon}^{niso}_a \\
		\mathbf{Z}^{niso\prime}_b (\boldsymbol{\varepsilon}_a^{niso} - \mathbf V_b^{niso}\boldsymbol{\delta}_{a,b})
	\end{pmatrix}.
	$$

	By applying a standard central limit theorem to $\boldsymbol{u}^{\ast} / \sqrt{S}$, it follows that the asymptotic variance of $\sqrt{S} (\hat{\boldsymbol{\Gamma}}^{\ast} - \boldsymbol{\Gamma}^{\ast})$ is
	$$
	\left( \frac{\mathbb{B^{\ast}}}{S}\, \frac{\mathbb{F}^{\ast}}{S} \right)^{-1}
	\frac{\mathbb{B}^{\ast}}{S} \, \mathbb{V}ar(\boldsymbol{u}^{\ast}/\sqrt{S})
	\frac{\mathbb{B}^{\ast\prime}}{S} \,
	\left( \frac{\mathbb{F}^{\ast\prime}}{S} \,\frac{\mathbb{B}^{\ast\prime}}{S} \right)^{-1},
	$$
	where $\mathbb{V}ar(\boldsymbol{u}^{\ast} / \sqrt{S})$ denotes the asymptotic variance of $\boldsymbol{u}^{\ast} / \sqrt{S}$. From this result, the asymptotic variance of $\sqrt{S} (\hat{\boldsymbol{\delta}}_{a,b} - \boldsymbol{\delta}_{a,b})$ can be directly obtained, as it is to a subvector of $\sqrt{S} (\hat{\boldsymbol{\Gamma}}^{\ast} - \boldsymbol{\Gamma}^{\ast})$.




	\subsection{Variance of \texorpdfstring{$\sqrt{S}(\hat{\boldsymbol{\psi}}_1 - \hat{\boldsymbol{\psi}}_2)$}{the Parameter Difference}}
	\label{OA:other:variance}
	As $\mathbf{Z}_1$ is valid, $\hat{\boldsymbol{\psi}}_1$ converges in probability to $\boldsymbol{\psi}$. Let $\boldsymbol{\psi}^{\dagger}$ denote the probability limit of $\hat{\boldsymbol{\psi}}_2$, which may differ from $\boldsymbol{\psi}$ if $\mathbf{Z}_1$ is endogenous. Let $\boldsymbol{\Gamma}^{\dagger} = (\boldsymbol{\beta}_1^{\prime}, ~ \boldsymbol{\psi}^{\prime}, ~\boldsymbol{\psi}^{\dagger\prime})^{\prime}$ denote the full parameter vector, and let $\hat{\boldsymbol{\Gamma}}^{\dagger} = (\hat{\boldsymbol{\beta}}_1^{\prime}, ~ \hat{\boldsymbol{\psi}}_1^{\prime}, ~\hat{\boldsymbol{\psi}}_2^{\prime})^{\prime}$ be its consistent estimator.


	The orthogonality conditions for $\hat{\boldsymbol{\beta}}_1$, $\hat{\boldsymbol{\psi}}_1$, and $\hat{\boldsymbol{\psi}}_2$ follow from~\eqref{eq:foc}. Applying the mean value theorem to the resulting equations with respect to $\hat{\boldsymbol{\Gamma}}^{\dagger}$ yields:
	$$
	\underbrace{\begin{pmatrix}
			\mathbf{I}_{d_1} & \mathbf{0} & \mathbf{0} \\
			\mathbf{0} & \mathbb B^{\dagger}_{2} & \mathbf{0} \\
			\mathbf{0} & \mathbf{0} & \mathbb B^{\dagger}_{3}
	\end{pmatrix}}_{\mathbb{B}^{\dagger}}
	\underbrace{\begin{pmatrix}
			\mathbf{X}^{iso\prime} \mathbf{X}^{iso} & \mathbf{0} & \mathbf{0} \\
			(1 - \lambda_{2,1}) \mathbb{F}^{\dagger}_{21} & \mathbb{F}^{\dagger}_{22} & \mathbf{0} \\
			(1 - \lambda_{2,2})\mathbb{F}^{\dagger}_{31} & \mathbf{0} & \mathbb{F}^{\dagger}_{33}\end{pmatrix}}_{\mathbb{F}^{\dagger}}
	(\hat{\boldsymbol{\Gamma}}^{\dagger} - \boldsymbol{\Gamma}^{\dagger}) = \mathbb{B}^{\dagger} \boldsymbol{u}^{\dagger},
	$$
	where $\mathbb{B}^{\dagger}_{k} = \hat{\mathbf{V}}^{niso\prime} \mathbf{Z}^{niso}_k \mathbf{W}^{niso}_k$, $\mathbb{F}^{\dagger}_{k1} = \mathbf{Z}^{niso\prime}_k \mathbf{X}^{niso}$, and $\mathbb{F}^{\dagger}_{kk} = \mathbf{Z}^{niso\prime}_k \mathbf{V}^{niso}$ for all $k \in \{1, 2\}$. The matrix $\mathbf{W}^{niso}_k$ is the GMM weighting matrix corresponding to $\mathbf{Z}^{niso}_k$, and $1 - \lambda_{2,k}$ is the coefficient associated with $\boldsymbol{x}_{s,i}^{\prime} \boldsymbol{\beta}_1$ in $\boldsymbol{\psi}_k$. The vector $\boldsymbol{u}^{\dagger}$ is given by
	$$\boldsymbol{u}^{\dagger} = \left(\mathbf{X}^{iso\prime} \boldsymbol{\varepsilon}^{iso},  ~\mathbf{Z}^{niso\prime}_1 \boldsymbol{\varepsilon}^{niso}, ~\mathbf{Z}^{niso\prime}_2 \boldsymbol{\varepsilon}^{niso}\right)\prime$$

	Applying a standard central limit theorem to $\boldsymbol{u}^{\dagger} / \sqrt{S}$, it follows that the asymptotic variance of $\sqrt{S} (\hat{\boldsymbol{\Gamma}}^{\dagger} - \boldsymbol{\Gamma}^{\dagger})$ is
	$$
	\left( \frac{\mathbb{B^{\dagger}}}{S}\, \frac{\mathbb{F}^{\dagger}}{S} \right)^{-1}
	\frac{\mathbb{B}^{\dagger}}{S} \, \mathbb{V}ar(\boldsymbol{u}^{\dagger}/\sqrt{S})
	\frac{\mathbb{B}^{\dagger\prime}}{S} \,
	\left( \frac{\mathbb{F}^{\dagger\prime}}{S} \,\frac{\mathbb{B}^{\dagger\prime}}{S} \right)^{-1},
	$$
	where $\mathbb{V}ar(\boldsymbol{u}^{\dagger} / \sqrt{S})$ denotes the asymptotic variance of $\boldsymbol{u}^{\dagger} / \sqrt{S}$. From this expression, the variance of $\sqrt{S} (\hat{\boldsymbol{\psi}}_1 - \hat{\boldsymbol{\psi}}_2)$ can be consistently estimated using the Delta method.


