\section{Background}

\subsection{The Burnside ring and its Zariski spectrum}
We recall the work of A.~Dress \cite{Dress1969,dress:1971} on the spectrum of the Burnside ring on a finite group.

\begin{definition} \label{defn:burnside ring}
    The \textit{Burnside ring} of a finite group $G$ is the Grothendieck group completion of the semi-ring of finite $G$-sets, denoted $A(G)$. That is, $A(G)$ is the ring of formal differences of isomorphism classes of finite $G$-sets, with addition given by disjoint union and multiplication given by Cartesian product.
\end{definition}

Let $H$ be a subgroup of $G$, and let $X$ be a finite $G$-set. In \cite{Dress1969}, Dress shows that the
\textit{mark of $H$ on $X$}
\begin{equation}\label{eqn:mark}
    \begin{aligned}
        \varphi_G^H\colon A(G) & \rightarrow \ZZ   \\
        X                      & \mapsto \abs{X^H}
    \end{aligned}
\end{equation}
is a ring homomorphism for all $H\leq G$. Here $X^H$ denotes the $H$-fixed points of $X$.  

Results of Burnside imply that the map $\varphi_G\colon A(G) \rightarrow \prod_{H\leq G} \ZZ$ given by \begin{equation}\label{eqn:phiG}
    \varphi_G = \prod_{H\leq G} \varphi_G^H
\end{equation} 
is an injective ring homomorphism \cite[Lemma 1]{Dress1969}.

\begin{definition}\label{def:phi}
    Let $p$ be a prime or zero. Let $\varphi_{G, p}^H\colon A(G) \rightarrow \ZZ/p\ZZ$ denote the composition of $\varphi_G^H$ and the usual quotient map $\ZZ \rightarrow \ZZ/p\ZZ$.
\end{definition}

By analyzing the induced map
\[
	\varphi_G^*: \Spec\bigg(\prod_{H \leq G} \mathbb{Z}\bigg) \to \Spec(A(G)),
\]
Dress proved the following.

\begin{theorem}[{\cite[\S 5]{dress:1971}}] \label{thm:spec burn ring}
    The Zariski spectrum of the Burnside ring is $$\Spec(A(G)) = \big\{\!\ker\varphi_{G, p}^H\mid H\leq G, ~p \text{ a prime or zero}\big\}.$$
\end{theorem}

Dress also proves some containment results, which we now recall, following \cite[Theorem 3.6]{balmer/sanders:2017}. We first need a definition. 

\begin{definition}\label{defn:OpH}
    For any subgroup $H \leq G$ and $p$ prime, the \textit{$p$-residual subgroup} of $H$ in $G$ is the unique normal $p$-perfect subgroup $O^p(H)$ such that the quotient $H/O^p(H)$ is a $p$-group. That is,
    \[
        O^p(H) = \bigcap I,
    \]
    where the intersection is over all $I\trianglelefteq H$ such that $|H:I| = p^n$ for some $n\in\NN$.
\end{definition}

We discuss these subgroups further after the following result. Recall that we write ${}^g\!H$ and $H^g$ for $gHg^{-1}$ and $g^{-1}Hg$, respectively.

\begin{theorem}\label{thm:dress containment}
    Let $H,K\leq G$ and $p,q$ be primes. Then
    \begin{enumerate}
        \item[(i)] $\ker(\varphi_{G,0}^H)\subseteq \ker(\varphi_{G,0}^{K})$ if and only if $\ker(\varphi_{G,0}^H)= \ker(\varphi_{G,0}^{K})$ if and only if $H=K^g$ for some $g\in G$;
        \item[(ii)] $\ker(\varphi_{G,p}^H)\subseteq \ker(\varphi_{G,q}^{K})$ implies $p=q$ and $\ker(\varphi_{G,p}^H)= \ker(\varphi_{G,p}^{K})$;
        \item[(iii)] $\ker(\varphi_{G,0}^H)\subseteq \ker(\varphi_{G,p}^{K})$ if and only if $\ker(\varphi_{G,p}^H)= \ker(\varphi_{G,p}^{K})$ if and only if $O^p(H) = {}^g(O^p(K))$ for some $g\in G$;
        \item[(iv)] $\ker(\varphi_{G,0}^H)\subset \ker(\varphi_{G,p}^{H})$ and $\ker(\varphi_{G,p}^H)\not\subseteq \ker(\varphi_{G,0}^{K})$.
    \end{enumerate}
\end{theorem}

\begin{remark}\label{rmk:OpH from sylows}
    One characterization of $O^p(H)$ is as the subgroup generated by all the Sylow $q$-subgroups of $H$ for $q\neq p$. Note that this implies that if $H\preccurlyeq_G K$ then $O^p(H)\preccurlyeq_G O^p(K)$.
\end{remark}
\begin{example}\label{example: Op for p-groups}
    If $G$ is a $p$-group then $O^p(G)=e$ and $O^q(G) =G$ for all $q\neq p$.  
\end{example}
\begin{example}\label{example: Oq for for not q groups}
    If $p$ is any prime which does not divide $|G|$ then $O^p(G)=G$.
\end{example}
\begin{example}
    If $G$ is a non-abelian simple group then $O^p(G)=G$ for all $p$.
\end{example}
\begin{example}\label{example: O of Dpn}
    Let $G=D_{p^n}$ be the dihedral group with $2p^n$ elements for some prime $p>2$ and $n\geq 1$. The only normal subgroups of $D_{p^n}$ are $C_{p^k}$ for $1\leq k\leq n$.  Thus the only non-trivial quotient of $D_{p^n}$ with order a prime power is $C_2 = D_{p^n}/C_{p^n}$.  Thus $O^2(D_{p^n}) = C_{p^n}$ and $O^q(D_{p^n})=D_{p^n}$ for all $q>2$. 
\end{example}
\begin{example}\label{example: O of A4}
    Let $G=A_4$ be the alternating group with $12$ elements.  The only non-trivial normal subgroup of $A_4$ is the Klein $4$-group $K_4$.  Since $A_4/K_4\cong C_3$ we have $O^3(A_4) = K_4$ while $O^q(A_4) = A_4$ for $q\neq 3$. 
\end{example}

\subsection{The Burnside Tambara functor}
\label{SubSec: The Burnside Tambara Functor} 
A $G$-Tambara functor $T$ \cite{tambara:1993} is a collection of commutative rings $T(G/H)$, one for each subgroup $H \leq G$, together with structure maps 
\begin{align*}
    \res_K^H \colon T(G/H) &\longrightarrow T(G/K), \\
    \tr_K^H \colon T(G/K) &\longrightarrow T(G/H), \\
    \nm^H_K \colon T(G/K) &\longrightarrow T(G/H), \\
    \conj_{g,H}: T(G/H) &\longrightarrow T(G/\,{}^g\!H)
\end{align*}
called the \emph{restriction}, \emph{transfer}, \emph{norm}, and \emph{conjugation} maps, respectively, for $K \leq H \leq G$ and $g \in G$. When the subgroups are clear from context, we drop the decorations. This definition can be extended to all finite $G$-sets by setting $T(X) := \bigsqcup_{i \in I} T(G/H_i)$ where $X \cong \bigsqcup_{i \in I} G/H_i$; in this formulation, each map of finite $G$-sets $f: X \to Y$ induces maps $f^*$, $f_+$, and $f_\times$ between $T(X)$ and $T(Y)$. There are many axioms these maps must satisfy; see \cite{strickland:2012} for a survey of Tambara functors. 

Each of the aforementioned structure maps satisfies certain properties: the conjugation maps are ring isomorphisms, the restriction maps are ring homomorphisms, the transfer maps are additive (homomorphisms of underlying additive groups), and the norms are multiplicative (homomorphisms of underlying multiplicative monoids). It is also notable that there are group actions which naturally arise on each level of a Tambara functor, namely the \emph{Weyl group} $W_GH = N_G(H)/H$ acts on $T(G/H)$ via the conjugation maps $\conj_{g,H}$ for $g\in N_G(H)$.

In this work, we focus on the following Tambara functor:

\begin{definition}\label{defn:burnside tamb functor}
The \emph{Burnside $G$-Tambara functor}, denoted $\burn_G$, is defined by $\burn_G(G/H)=A(H)$ for each $H \leq G$. For subgroups $K\leq H\leq G$, an element $g\in G$, an $H$-set $Y\in \burn_G(G/H)$, and a $K$-set $X\in\burn_G(G/K)$, we define the Tambara structure maps by linearly extending the following maps: \begin{align*}
    \res_{K}^{H}\colon \burn_G(G/H)&\longrightarrow \burn_G(G/K)\\
    Y &\longmapsto Y\text{ with restricted $K$-action,}\\
    \tr_{K}^{H}\colon \burn_G(G/K)&\longrightarrow \burn_G(G/H)\\
    X &\longmapsto H\times_K X,\\
    \nm_{K}^{H}\colon \burn_G(G/K)&\longrightarrow \burn_G(G/H)\\
    X &\longmapsto {\rm Map}_K(H,X),\\
    \conj_{g,H}\colon \burn_G(G/H)&\longrightarrow \burn_G(G/\,{}^g\!H)\\
    X &\longmapsto {}^g\!X,
\end{align*}
where ${}^g\!X$ has underlying set $X$ and ${^{g}\!H}$-action $(ghg^{-1})\cdot x = hx$.
\end{definition}

\subsection{Tambara ideals, spectra, and going up}

The theory of Tambara ideals mirrors the theory of ideals of commutative rings. 

An ideal $\I$ of a $G$-Tambara functor $T$ is a levelwise collection of ideals $\I(G/H) \subseteq T(G/H)$ (one for each subgroup of $G$) which is closed under all of the Tambara structure maps; see \cite[Def. 2.1]{nakaoka:2012} for a precise definition. 

The definition below is used to make sense of prime ideals in Tambara functors. 

\begin{definition}
    \label{def:Q}
    Let $T$ be a $G$-Tambara functor, $\I$ an ideal of $T$, and $H_1, H_2\leq G$. Let $a \in T(G/H_1)$ and $b \in T(G/H_2)$. Define the proposition $Q(\I, a, b)$ by
    \begin{enumerate}
        \item[(*)] The relation
              \[
              	\Big(\nm_{{}^{g_{\scalebox{0.6}{\tiny 1}}}\!K_1}^{L}\circ \conj_{g_1, K_1}\circ \res_{K_1}^{H_1}(a)\Big)
                  \cdot\left(\nm_{{}^{g_{\scalebox{0.6}{\tiny 2}}}\!K_2}^{L} \circ \conj_{g_2, K_2} \circ \res_{K_2}^{H_2}(b)\right) \in \I(G/L)\]
              holds for all $L, K_1, K_2 \leq G$ and $g_1, g_2 \in G$ such that $L \geq {}^{g_1}\!K_1, ~L \geq {}^{g_2}\!K_2, ~K_1\leq H_1,$ and $K_2\leq H_2$.
    \end{enumerate}
\end{definition}

Nakaoka proves that the following definition of prime ideals coincides with other possible definitions \cite[Proposition 4.2]{nakaoka:2014}. We use this definition because it is more practical to check.

\begin{definition}
    An ideal $\mathfrak{p}$ of a Tambara functor $T$ is \emph{prime} if
    \begin{enumerate}[(a)]
        \item $\mathfrak{p} \neq T$ (equivalently, for all $H \leq G$, $1 \notin \mathfrak{p}(G/H)$);
        \item Fix any two subgroups $H, H' \leq G$ and elements $a \in T(G/H)$, and $b \in T(G/H')$. If $Q(\mathfrak{p},a,b)$ holds then $a \in \mathfrak{p}(G/H)$ or $b \in \mathfrak{p}(G/H')$.
    \end{enumerate}
\end{definition}


The \emph{spectrum} of a Tambara functor $T$, denoted $\Spec(T)$, is the collection of all prime ideals, equipped with an analogue of the Zariski topology; see \cite[Section 4.2]{nakaoka:2012}. If $T$ is a Noetherian Tambara functor (e.g., if $T$ is levelwise Noetherian), then the topology on $\Spec(T)$ is completely determined by the poset structure on the set of prime ideals by \cite[Theorem A]{CMQSV:24}. As the Burnside Tambara functor is levelwise finitely generated, and therefore Noetherian, the topology on $\Spec(\burn_G)$ is determined by the poset structure on the collection of prime ideals. 


\subsection{The spectrum over cyclic groups}

Nakaoka calculated $\Spec(\burn_G)$ for $G$ a cyclic $p$-group in \cite{nakaoka:2012, nakaoka:2014}. In \cite{CalleGinnett:23}, the first author and Ginnett extended Nakaoka's computation to all cyclic groups using  Dress's computations of the spectrum of the Burnside ring in \cite{dress:1971}. 


\begin{definition}\label{def:the_ideals}
    Let $G$ be a finite group and $\burn_G$ the Burnside $G$-Tambara functor. Let $K$ be a subgroup of $G$ and $p$ a prime or zero. For each $H\leq G$ define
    $$\fr{p}_{K, p}(G/H) = \bigcap_{\substack{I \leq H \\ I \preccurlyeq_G K}} \ker(\varphi_{H, p}^I)$$
    where $\varphi^I_{H,p}$ is as in \cref{def:phi} and $I \preccurlyeq_G K$ means $I$ is subconjugate to $K$ in $G$.
\end{definition}

For any finite group $G$, the first author and Ginnett showed that $\mathfrak{p}_{K,p}$ is a prime ideal of $\burn_G$ for all $K \leq G$ and $p$ a prime or zero. When $G$ is abelian, they classified pairwise containments between these ideals (\cite[Theorem 1.1]{CalleGinnett:23}). Moreover, when $G$ is cyclic, they showed in \cite{CalleGinnett:23} that these are \emph{all} of the prime ideals (\emph{op. cit.}).
% loc cit means ``in the place cited" and you use it if you're citing the same theorem/prop/lemma in the same paper. \textit{ibid} is interchangable with loc cit. But op cit means ``in the work cited" and you use it if you're citing the same paper but a different theorem/lemma/whatever.
We show that the primes $\mathfrak{p}_{K,p}$ are \textit{all} of the prime ideals of $\burn_G$ for any finite $G$, and determine all pairwise containments between them in \cref{thm:containment all}.

\subsection{The Ghost of the Burnside Tambara Functor}

The results of \cite{CalleGinnett:23} are proved using a construction called the \textit{ghost of the Burnside Tambara functor}. This construction is inspired by the \textit{ghost ring} of the Burnside ring
\begin{equation}
\label{eq:table of marks}
	\tilde A(G) := \Big( \prod_{K \leq G} \ZZ \Big)^G,
\end{equation}
the sub-ring of $G$-fixed points where the $G$-action permutes the coordinates according to the conjugation action of $G$ on its subgroups. This is also known as the \emph{table of marks} of $G$. It is straightforward to verify that the marks homomorphism \eqref{eqn:phiG} factors through $\tilde{A}(G)$.  

\begin{remark}\label{remark: A tilde presentation}
    We could have instead taken the product over \emph{conjugacy classes} of subgroups to obtain the ring $\prod_{[K]} \mathbb{Z}$, which is isomorphic as a ring to $\tilde{A}(G)$. We use the presentation \eqref{eq:table of marks} to eliminate the need to choose representatives of conjugacy classes in many arguments.
\end{remark}

\begin{notation}\label{notation: ideals of A tilde}
    The ideals of $\tilde{A}(G)$ are precisely the sets $\prod_{K \leq G} n_K \ZZ$ where $(n_K)_{K \leq G}$ is an indexed collection of natural numbers such that $n_{K_1} = n_{K_2}$ whenever $K_1 \conjugate{G} K_2$. We often denote such an ideal simply as the tuple of integers $(n_K)_{K \leq G}$ for brevity.
\end{notation}

Just as the Burnside rings of the subgroups of $G$ assemble into a Tambara functor $\burn_G$, the ghost rings $\tilde{A}(H)$ also assemble into a Tambara functor. 

\begin{definition}\label{cor:structure map fmlas}\label{def:ghost} 
    The \textit{ghost of the Burnside Tambara functor}, denoted $\burnghost$, is defined by $\burnghost(G/H) := \widetilde{A}(H)$. For $H \leq K \leq G$, let $a \in \burnghost(G/H)$, $b \in\burnghost(G/K)$, and $g\in G$. The restriction, transfer, norm, and conjugation maps in $\burnghost$ are given by
    \begin{align*}
        \res_{H}^{K}(b)_L & = b_L                         \\
        \tr_{H}^{K}(a)_I  & = \sum_{\substack{[k] \in K/H       \\ I^k\leq H}}a_{I^k}\\
        \nm_{H}^{K}(a)_I  & = \prod_{[g] \in I\setminus K/H}
        a_{I^g \cap H}                             \\
        \conj_{g, H}(a)_J & = a_{J^{g}}
    \end{align*}
    \noindent for $L \leq H, I \leq K,$ and $J \leq H^g$.

\end{definition}
\begin{remark}
    One can check that $\ghost(\uA_G)$ is isomorphic, as a Green functor, to the \emph{twin construction} considered by Thevenaz in \cite{Thev:88}. While Thevenaz's construction is defined for arbitrary Green functors, it does not take into account norm structures and it is not clear how to incorporate this data into the twin in general. 
\end{remark}

There is also a natural comparison map from $\uA_G$ to $\burnghost$.

\begin{definition}\label{def:ghostmap}
The \emph{ghost map} 
$$\ghostmap: \uA_G \to \burnghost$$
is defined by setting $\ghostmap(G/H) = \varphi_H$, where $\varphi_H$ is as in \eqref{eqn:phiG}. 
\end{definition}

As mentioned in \Cref{remark:ghost vs ghost}, when $G = C_p$ these constructions coincide (up to isomorphism) with the object $\ghost(\uA_{C_p})$ and the morphism $\chi$ as defined in \cite{CMQSV:24}.

\begin{remark}
    The ghost Tambara functor defined above is the same as in \cite[Definition 3.3]{calle/ginnett:2019}; however, the argument given there that $\burnghost$ is a Tambara functor is incorrect. We note that this gap does not affect any of the results of \cite{calle/ginnett:2019}, as the arguments there primarily consider $\burnghost \cap \chi(\burn_G)$, which is indeed a Tambara functor (isomorphic to $\burn_G$) because $\varphi_H$ is injective for all $H\leq G$. Although the proof in \cite{calle/ginnett:2019} contains a gap, $\burnghost$ is nevertheless a Tambara functor (and $\ghostmap$ is a map of Tambara functors), as we show in \Cref{SS:burnghost}.
\end{remark}

\section{Tambara Structure of the Ghost}
\label{SS:burnghost}

We prove that the ghost $\ghost(\uA_G)$ is indeed a Tambara functor. 

\begin{theorem}\label{ghost is TF}
    For any finite group $G$, the structure maps of \cref{def:ghost} satisfy all the necessary relations to be structure maps of a Tambara functor.  In particular, $\burnghost$ is a Tambara functor.
\end{theorem}
\begin{proof}
    By induction, we may assume that the claim is true for any proper subgroup $H<G$. The base case, $\tilde{A}(e) \cong \ZZ$, is trivial. Thus we assume that all the necessary formulas which do not involve the group $G$ are satisfied, since these relations are the same as those in the ghost for some maximal proper subgroup of $G$. 

    Functoriality of restrictions follows from their definition, while functoriality of transfers and norms follows from \cref{proposition:transfer associative,proposition:norm associative}, respectively. The double coset formulas for transfer and norm are \cref{proposition: transfer double coset formula,proposition: norm double coset formula}, respectively. Frobenius reciprocity is checked in \cref{proposition Frobenius reciprocity} and Tambara reciprocity is shown in \Cref{proposition: Tamb Rec}.
    \end{proof}

With \cref{ghost is TF} in hand, we can prove the following important fact.

\begin{proposition}\label{prop:ghost is map}
    The ghost map $\ghostmap\colon \burn_G\to \burnghost$ is a morphism of Tambara functors.
\end{proposition}\begin{proof}
    Since the Burnside Tambara functor is initial in the category of Tambara functors, there is a unique map $\Psi_G \colon \burn_G\to \burnghost$ of Tambara functors, which we show coincides with the ghost map. We prove the claim at level $G/G$, but all the other levels follow similarly. For all $H\leq G$, we have
    \[
    \Psi_G(G/H) = \Psi_G(\tr_H^G(H/H)) = \tr_H^G(\Psi_H(H/H)) = \tr_H^G(1),
    \]
    since $\Psi$ commutes with transfers and is a levelwise ring map.  Using the formulas in \cref{def:ghost}, we see that for any $I\leq G$ 
    \[
    \tr^G_H(1)_I 
    = 
    \sum_{{\gamma\in G/H, ~~I^{\gamma}\leq H}} 1 
    = 
    \abs{(G/H)^I} 
    = 
    \varphi_G^I(G/H),
    \]
    where the second equality uses the bijections
    \[
        (G/H)^I\leftrightarrow \mathrm{Set}^G(G/I,G/H)\leftrightarrow \{\gamma\in G/H\mid I^{\gamma}\leq H\}.
    \]
    Thus $\Psi_G(G/H)  = \ghostmap_G(G/H)$ for every $H\leq G$. Extending linearly, $\Psi_G = \chi_G$ on all of $\burn_G(G/G)$. 
\end{proof}

\subsection*{Proof of \cref{ghost is TF}}

We begin with four preliminary observations about finite $G$-sets. 

\begin{lemma}[{cf.\ \cite[proof of Lemma 2.18]{CCM}}]\label{lemma: size of fixed points of orbits}
    Let $G$ be a finite group with subgroups $H\leq K\leq G$ and $J\leq G$.  There is a bijection
    \[
        (G/H)^K\cong \coprod_{[x]\in (G/K)^J} (K/H)^{J^x}.
    \]
\end{lemma}

\begin{lemma}\label{lemma: restriction of K/H}
    For any subgroups $H,L\leq K$ there is a bijection
    \[
        \Phi\colon \coprod\limits_{[\gamma]\in L\backslash K/H} L/(L\cap {}^\gamma\!H)\to K/H
    \]
    given explicitly by sending $[\ell]\in L/(L\cap {}^\gamma\!H)$ to $[\ell\gamma]\in K/H$. This bijection is $L$-equivariant with respect to the left action of $L$ on the source and the target.
\end{lemma}
\begin{proof}
	As an $L$-set, $K/H$ is isomorphic to $K \times_H (H/H)$. The result then follows from the Mackey double coset formula. 
\end{proof}

If $J\leq L$ is any subgroup, the map $\Phi$ is a $J$-equivariant bijection.  Taking orbits by the left $J$-action yields the following corollary.

\begin{corollary}\label{corollary: norm double coset formula corollary}
    For any $H,L\leq K$ and $J\leq L$ the map $\Phi$ induces a bijection
    \[
        \coprod\limits_{[\gamma]\in L\backslash K/H} J\backslash L/(L\cap {}^\gamma\!H)\to J\backslash K/H.
    \]
\end{corollary}

We need one final lemma.  Suppose that $H,L\leq K$, and $J\leq L$ is a subgroup such that there is a $k\in K$ with $J^k\subset H$. Note that the set of all $k$ such that $J^k\subset H$ is closed under the right $H$-action and let $B\subset K/H$ denote the the orbits of this set under this action.  Our goal is to describe the preimage of $B$ under $\Phi$.

For any $\gamma\in L\backslash K/H$, let 
\[
    A_{\gamma} = \{[\ell]\in L/(L \cap {}^\gamma\!H) \mid J^{\ell \gamma}\subset H \}.
\]
By definition, for any $[\ell]\in A_{\gamma}$ we have $\Phi([\ell]) = [\ell\gamma]\in B$.
\begin{lemma}\label{lemma: transfer double coset formula lemma}
    For any $H,L\leq K$ and $J\leq K$ such that there exists $k\in K$ with $J^k\subset H$, if $\Phi$ is the map from \cref{lemma: restriction of K/H}, then
    \[
        \Phi^{-1}(B) =  \coprod\limits_{\gamma\in L\backslash K/H} A_{\gamma},
    \]
    where $B$ and $A_{\gamma}$ are as in the previous two paragraphs.
\end{lemma}
\begin{proof}
    We have already observed that 
    \[
        \coprod\limits_{\gamma\in L\backslash K/H} A_{\gamma}\subset \Phi^{-1}(B),
    \]
     so it suffices to show that for any $kH\in B$, there is a $\gamma\in L\backslash K/H$ and an $[\ell]\in A_{\gamma}$ so that $\Phi([\ell]) = (\ell\gamma)H = kH$.  By definition of double cosets, there must be a $\gamma \in L\backslash K/H$ and an $\ell\in L$ so that $(\ell\gamma) H = kH$, so it remains to check that $[\ell]\in L/(L\cap {}^\gamma\!H)$ is actually in $A_{\gamma}$. That is we need to check that $J^{\ell \gamma}\leq H$. Since $(\ell\gamma) H = kH$ there must be an $h\in H$ such that $\ell\gamma = kh$, hence we have 
     \[
        J^{\ell\gamma} = J^{kh} \leq H^h = H
     \]
     where inclusion $ J^{kh} \leq H^h$ uses the fact that $kH\in B$.
\end{proof}

We are now prepared to show that $\burnghost$ is a Tambara functor. We begin with the functoriality of transfers and norms.

\begin{proposition}[Functoriality of Transfer]\label{proposition:transfer associative}
For any $H \leq L \leq K$ and $\vec{a} \in \burnghost(G/H) = \big(\prod_{I\leq H}\mathbb{Z}\big)^H$, we have $\tr_L^K \tr_H^L(\vec{a}) = \tr_H^K(\vec{a}).$
\end{proposition}

\begin{proof}
Recall that the $J$ component of $\tr_L^K(\vec b)$ for some $J \leq K$ is:
\[
	\tr_L^K(\vec{b})_J 
		= \sum_{\substack{
					[k] \in K/L \\
					J^k \leq L
				}}
				b_{J^k}.
\]
If $\vec b = \tr_H^L(\vec{a})$, then this becomes:
\[
	\tr_L^K(\tr_H^L(\vec{a}))_J 
		= \sum_{\substack{
					[k] \in K/L \\
					J^k \leq L	
			}}
			\tr_H^L(\vec a)_{J^k}
		= \sum_{\substack{
					[k] \in K/L \\
					J^k \leq L	
			}}
			\sum_{\substack{
					[\ell] \in L/H \\
					(J^k)^\ell \leq H
				}} 
				a_{(J^k)^\ell}.
\]
Letting $m = k\ell$, this simplifies to
\[
	\tr_L^K(\tr_H^L(\vec{a}))_J 
		= \sum_{\substack{
					[m] \in K/H\\
					J^m \leq H
				}}
				a_{J^m},
\]
which is exactly $\tr_H^L(\vec{a})$, as desired. 
\end{proof}

\begin{proposition}[Functoriality of Norm]\label{proposition:norm associative}
For any $H \leq L \leq K$ and $\vec{a} \in \burnghost(G/H) = \big(\prod_{I\leq H}\mathbb{Z}\big)^H$ we have $\nm_L^K \nm_H^L(\vec{a}) = \nm_H^K(\vec{a}).$
\end{proposition}

\begin{proof}
We have
\begin{align*}
    \nm_H^K(\vec{a})_J
     &=  \prod_{[g] \in J \backslash K/H} a_{J^g \cap H} \quad 
    =  \prod_{[g] \in \bigsqcup_{[m] \in J \backslash K / L} (J^m \cap L) \backslash L / H} a_{J^g \cap H} \\
    &=  \prod_{[m] \in J \backslash K/L} \prod_{[g] \in (J^m \cap L) \backslash L / H} a_{J^{mg} \cap H} 
\end{align*}
and
\begin{align*}
    \nm_L^K \nm_H^L(\vec{a})_J 
    &= \nm_L^K \left( \left( \prod_{[g] \in I \backslash L / H} a_{I^g \cap H} \right)_{I \leq L} \right)_J \\
    &=  \prod_{[m] \in J \backslash K/L} \left( \prod_{[g] \in I \backslash L/H} a_{I^g \cap H} \right)_{J^m \cap L} \\
    &=  \prod_{[m] \in J \backslash K/L} \left( \prod_{[g] \in (J^m \cap L) \backslash L/H} a_{(J^m \cap L)^g \cap H} \right)  \\
    &=  \prod_{[m] \in J \backslash K/ L} \prod_{[g] \in (J^m \cap L) \backslash L/H} a_{J^{mg} \cap L^g \cap H}  \\
    &=  \prod_{[m] \in J \backslash K/ L} \prod_{[g] \in (J^m \cap L) \backslash L/H} a_{J^{mg} \cap H} . \qedhere
\end{align*}
\end{proof}

We now check the double coset formulas.

\begin{proposition}[Additive Double-Coset Formula]\label{proposition: transfer double coset formula}
    For any $H,L\leq K$ and $\vec{a}\in \burnghost(G/H) = \big(\prod_{I\leq H}\mathbb{Z}\big)^H$ we have
    \[
        \res^K_L\tr^K_H(\vec{a}) = \sum\limits_{\gamma\in L\backslash K/H} \tr^L_{L\cap {}^\gamma\!H} \res^{{}^\gamma\!H}_{L\cap {}^\gamma\!H} c_{\gamma}(\vec{a}).
    \]
\end{proposition}
\begin{proof}
    It suffices to check that the claim is true on the component of any subgroup $J\leq L$.  The $J$-th component of the left hand side is given by
    \[
    (\res^K_L\tr^K_H(\vec{a}))_J = \tr^K_H(\vec{a})_J  = \sum_{\substack{[k] \in K/H       \\ J^k\leq H}} a_{J^k} = \sum_{[k]\in B} a_{J^k},
    \]
    while the $J$-th component of the right hand side is given by
    \begin{align*}
         \sum\limits_{\gamma\in L\backslash K/H} (\tr^L_{L\cap {}^\gamma\!H} \res^{{}^\gamma\!H}_{L\cap {}^\gamma\!H} c_{\gamma}(\vec{a}))_J  & =  \sum\limits_{\gamma\in L\backslash K/H}\ \sum_{\substack{[\ell] \in L/(L\cap ^{\gamma}H)       \\ J^{\ell}\leq ^{\gamma}H}} a_{J^{\ell\gamma}}\\
         & = \sum\limits_{\gamma\in L\backslash K/H}\ \sum\limits_{[\ell]\in A_{\gamma}}\ \, a_{J^{\ell\gamma}}.
    \end{align*}
    These two sums are equal by \cref{lemma: transfer double coset formula lemma}. \end{proof}

\begin{proposition}[Multiplicative Double-Coset Formula]\label{proposition: norm double coset formula}
    For any $H,L\leq K$ and $\vec{a}\in \burnghost(G/H) = \big(\prod_{I\leq H}\mathbb{Z}\big)^H$ we have
    \[
        \res^K_L\nm^K_H(\vec{a}) = \prod\limits_{\gamma\in L\backslash K/H} \nm^L_{L\cap {}^\gamma\!H} \res^{{}^\gamma\!H}_{L\cap {}^\gamma\!H} c_{\gamma}(\vec{a}).
    \]
\end{proposition}
\begin{proof}
     It suffices to check that the claim is true on the component of any subgroup $J\leq L$.  The $J$-th component of the left hand side is given by
    \[
    (\res^K_L\nm^K_H(\vec{a}))_J = \nm^K_H(\vec{a})_J  =  \prod_{[k]\in J\cap K/H} a_{J^k\cap H},
    \]
    while the $J$-th component of the right hand side is given by
    \begin{align*}
         \prod\limits_{\gamma\in L\backslash K/H} (\nm^L_{L\cap {}^\gamma\!H} \res^{{}^\gamma\!H}_{L\cap {}^\gamma\!H} c_{\gamma}(\vec{a}))_J  & =  \prod\limits_{\gamma\in L\backslash K/H} \ \prod\limits_{[\ell]\in J\backslash L/(L\cap ^{\gamma H})} a_{(J^g\cap L\cap ^{\gamma}H)^{\gamma}} \\
         &= \prod\limits_{\gamma\in L\backslash K/H}\  \prod\limits_{[\ell]\in J\backslash L/(L\cap ^{\gamma H})}a_{J^{\ell \gamma}\cap H}.
    \end{align*}
    These two products are equal by \cref{corollary: norm double coset formula corollary}.
\end{proof}

We now check that compatibility of the transfers and multiplicative structure.  First we check Frobenius reciprocity.
\begin{proposition}[Frobenius Reciprocity]\label{proposition Frobenius reciprocity}
    Let $H\leq K\leq G$ be a chain of subgroups.  For any $\vec{a}\in \ghost(\uA_{G})(G/H)$ and $\vec{b}\in \ghost(\uA_G)(G/K)$ we have 
    \[
        \tr^K_H(\vec{a})\cdot \vec{b} 
        =
        \tr^K_H(\vec{a}\cdot \res^K_H(\vec{b})) 
        \quad \mathrm{and} \quad  
         \vec{b} \cdot \tr^K_H(\vec{a})
        =
        \tr^K_H( \res^K_H(\vec{b})\cdot \vec{a}) 
    \]
\end{proposition}
\begin{proof}
    We check the left relation; the right one follows by commutativity.  It suffices to check that the equation in the statement holds componentwise.  For any subgroup $I\leq K$ we have 
    \[
        \left(\tr^K_H(\vec{a})\cdot \vec{b}\right)_I 
        = 
        \tr^K_H(\vec{a})_I\cdot \vec{b}_I 
        =
        \sum_{\substack{[k] \in K/H       \\ I^k\leq H}}\vec a_{I^k} \cdot \vec b_I 
        =
        \sum_{\substack{[k] \in K/H       \\ I^k\leq H}}\vec{a}_{I^k} \cdot \vec{b}_{I^k} 
        =
        \left(\tr^K_H(\vec{a}\cdot \res^K_H(\vec{b}))\right)_I
    \]
    where the last equality uses the fact that $\vec{b}_{I^k} = \vec{b}_I$ for any $k\in K$ since $\vec{b}\in \ghost(\uA_G)(G/K)$. 
\end{proof}

Finally we check the most difficult relation, Tambara reciprocity, which relates norms and transfers.  In this proof, we use the TNR formulation of Tambara functors from \cite[Sec. 2]{tambara:1993} and adopt the following notation:  if $f\colon X\to Y$ is an equivariant function between finite $G$-sets, we write $f^*$, $f_{\times}$, and $f_+$ for restriction, norm, and transfer along $f$ in the ghost. In this notation, Tambara reciprocity refers to \cite[Definition 2.1(v)]{tambara:1993}. 

\begin{proposition}[Tambara Reciprocity]\label{proposition: Tamb Rec}

For any proper subgroup $K < G$ and equivariant functions $t\colon A\to G/K$, and $n\colon G/K\to G/G$ that there is an equality of operations
\begin{equation}\label{equation: exponential equation}
        n_{\times}t_{+} = b_+p_{\times}e^*
    \end{equation}
where $b$, $p$ and $e$ fit into an exponential diagram
    % https://q.uiver.app/#q=WzAsNSxbMCwxLCJBIl0sWzEsMSwiRy9LIl0sWzIsMSwiRy9HIl0sWzEsMCwiRSJdLFsyLDAsIkYiXSxbMCwxLCJ0IiwyXSxbMSwyLCJuIiwyXSxbMywwLCJlIiwyXSxbNCwyLCJiIl0sWzMsNCwicCJdXQ==
\[\begin{tikzcd}
	& E & F \\
	A & {G/K} & {G/G.}
	\arrow["p", from=1-2, to=1-3]
	\arrow["e"', from=1-2, to=2-1]
	\arrow["b", from=1-3, to=2-3]
	\arrow["t"', from=2-1, to=2-2]
	\arrow["n"', from=2-2, to=2-3]
\end{tikzcd}.\]
\end{proposition}


\begin{proof}
Generally, this problem is unwieldy because the exponential diagrams can be difficult to get a handle on.  In this case, we can exploit the fact that it suffices to check that the desired formula holds component-wise in the ghost.  That is, it suffices to check that the formula holds after projecting to the component of $\burnghost(G/G)$  which corresponds to every subgroup $H\leq G$. 

First, suppose that $H< G$ is a proper subgroup.  Write $r\colon G/H\to G/G$ for the collapse map.  Since the restrictions in the ghost are given by projections, we see that the formula \eqref{equation: exponential equation} holds on the $H$-component if and only if the equation holds after composition with $r^*$.  That is, it suffices to prove 
\begin{equation}\label{equation: exponential equation 2}
    r^*n_{\times}t_{+} = r^*b_+p_{\times}e^*.
\end{equation}
Consider the diagram
% https://q.uiver.app/#
\[
\begin{tikzcd}
	&& C \\
	& E & F & B \\
	A & {G/K} & {G/G} \\
	J & I && {G/H} \\
	& D && L
	\arrow["d"', from=1-3, to=2-2]
	\arrow["{(P)}"{description}, draw=none, from=1-3, to=2-3]
	\arrow["c", from=1-3, to=2-4]
	\arrow["p", from=2-2, to=2-3]
	\arrow["e"', from=2-2, to=3-1]
	\arrow["{(E)}"{description}, draw=none, from=2-2, to=3-3]
	\arrow[""{name=0, anchor=center, inner sep=0}, "b"', from=2-3, to=3-3]
	\arrow["m", from=2-4, to=2-3]
	\arrow[""{name=1, anchor=center, inner sep=0}, "a", from=2-4, to=4-4]
	\arrow["t", from=3-1, to=3-2]
	\arrow[""{name=2, anchor=center, inner sep=0}, "n", from=3-2, to=3-3]
	\arrow["{(P)}"{description}, draw=none, from=3-2, to=4-1]
	\arrow["h", from=4-1, to=3-1]
	\arrow["q"', from=4-1, to=4-2]
	\arrow["g"', from=4-2, to=3-2]
	\arrow[""{name=3, anchor=center, inner sep=0}, "f"', from=4-2, to=4-4]
	\arrow["r"', from=4-4, to=3-3]
	\arrow["j", from=5-2, to=4-1]
	\arrow[""{name=4, anchor=center, inner sep=0}, "k"', from=5-2, to=5-4]
	\arrow["\ell", from=5-4, to=4-4]
	\arrow["{(P)}"{description}, draw=none, from=0, to=1]
	\arrow["{(P)}"{description}, draw=none, from=2, to=3]
	\arrow["{(E)}"{description}, draw=none, from=3, to=4]
\end{tikzcd}
\]
where each polygon is labeled by $(P)$ or $(E)$ corresponding to whether it is a pullback or an exponential diagram in finite $G$-sets.  

The outer maps of the diagram between $A$ and $G/H$ represent two different ways to resolve 
\[
    A \xrightarrow{t} G/K \xrightarrow{n} G/G\xleftarrow{r} G/H
\]
into a TNR morphism in the polynomial category: either $A \xleftarrow{hj} D \xrightarrow{k} L \xrightarrow{\ell} G/H$ or $A \xleftarrow{ed} C \xrightarrow{c} B \xrightarrow{a} G/H$.
Since composition is well-defined in the polynomial category, these two spans are isomorphic hence there are equivariant bijections
\[
    C\leftrightarrow D,\quad B\leftrightarrow L
\]
and through these bijections we can identify 
\[
    hj = ed, \quad k=c, \, \, \, \, \text{and} \quad \ell=a.
\]
Now, since $I$ and $J$ have equivariant maps to $G/K$ and $K$ is proper, neither of these $G$-sets has a fixed point.  In particular, we obtain the formula
\[
    \ell_{+}k_{\times}j^* = f_{\times}q_+
\]
by our inductive hypothesis that the ghost is a Tambara functor for all proper subgroups of $G$.  Using this, and the fact that we have already established the double coset formulas, we have
\begin{align*}
    r^*n_{\times}t_{+}  = f_{\times} g^*t_{+}   = f_{\times}q_+h^* 
     = \ell_+k_{\times}j^*h^*   = a_+c_{\times}d^*e^*
     = a_+m^*p_{\times}e^* = r^*b_+p_{\times}e^*
\end{align*}
establishing the formula \eqref{equation: exponential equation 2} for all proper subgroups $H<G$.

Finally, we need to check that exponential relations hold for the $G$-component.  It suffices, in this case, to establish the result for the two cases $A= G/L$ for $L<K$ a proper subgroup, and for $A= G/K\amalg G/K$ and $t$ the fold map.  In the case $A = G/L$, the left hand side of \eqref{equation: exponential equation} is always zero, since $\nm^G_K(\vec{a})_G = a_K$ and $\tr^K_L(\vec{b})_K=0$.  By \cite[Theorem 2.8]{mazur:2019}, the right hand side is a sum of proper transfers and hence will also have zero in the $G$-component, thus establishing \eqref{equation: exponential equation} when $A = G/L$.  When $A= G/K\amalg G/K$ we are interested in the formula for $\nm^G_{K}(\vec{a}+\vec{b})$.  The $G$-component is given by $a_K+b_K$.  By \cite[Theorem 2.4(2)]{mazur:2019}, the right hand side is given by $\nm^G_{K}(\vec{a})+\nm^G_K(\vec{b})+T$ where $T$ is a term which is a sum of proper transfers.  In particular, the $G$-component of $T$ is zero, and so the $G$-component of the two sides of \eqref{equation: exponential equation} agree when $A = G/K\amalg G/K$.
\end{proof}

\section{Computing the Spectrum of the Burnside Functor}

Inspired by the definition of the ideals $\K_{H,p}$ from \cite[Section 3]{CalleGinnett:23}, we introduce a family of ideals in $\burnghost$. First, recall that a non-empty set of subgroups of $G$ is called a \emph{family of subgroups} if it is closed under conjugation and taking subgroups.

\begin{definition}\label{defn:PFp}
    Let $\sr{F}$ be a family of subgroups of $G$ and $p$ a prime or $0$. Recalling our \Cref{notation: ideals of A tilde} for ideals of $\tilde{A}$, define $\P_{\sr F, p}\subseteq \burnghost$ by\[
    \P_{\sr F, p}(G/H) = ( \delta_{\sr{F}, p}(I))_{I\leq H}
    \] where\[
    \delta_{\sr{F}, p}(I) = \left\{\begin{array}{cc}
        p & I\in \sr{F}, \\
        1 & I\not\in \sr{F}.
    \end{array}\right.
    \]
\end{definition}

Using the explicit formulas from \cref{def:ghost}, one can show that $\P_{\sr{F}, p}$ is always an ideal of $\burnghost$, i.e. that it is closed under the structure maps. As a special case, we consider the family $\sr{F} = \{I\preccurlyeq_G H\}$ for some fixed $H\leq G$, in which case we write $\P_{\sr{F}, p} = \P_{H,p}$ and similarly $\delta_{\sr{F},p} = \delta_{H,p}$; note that $\P_{H,p}$ only depends on the conjugacy class of $H$ in $G$.

\begin{theorem}\label{thm:prime iff subgp fam}
    The ideal $\P_{\sr{F}, p}$ is prime if and only if $\P_{\sr{F}, p}= \P_{H,p}$ for some $H\leq G$.
\end{theorem}
\begin{proof}
    The ``if'' direction holds by the proof of \cite[Theorem 3.8]{CalleGinnett:23}; although the ideals considered there are $\ghostmap^*\P_{H,p}$, rather than $\P_{H,p}$, the proof in fact establishes that the ideals $\P_{H,p}$ are prime (the intersection with the image of the ghost map only occurs in the final step). 

    We show the other implication holds via the contrapositive. Suppose that $\P=\P_{\sr{F},p}$ for a family $\sr{F}$ which is not of the form $\{I\preccurlyeq_G H\}$ for some $C\leq G$. This means there is some $N,N'\in \sr{F}$ so that for any $L\leq G$ with $N,N'\preccurlyeq_G L$, then $L\not\in \sr{F}$. Consider the elements $a\in \burnghost(G/N)$ and $b\in \burnghost(G/N')$ given by\[
    a_I = \left\{\begin{array}{cc}
         0 & I<N, \\
         1 & I=N,
    \end{array}\right. \quad  \text{ and } \quad b_J = \left\{\begin{array}{cc}
         0 & J<N', \\
         1 & J=N',
    \end{array}\right.
    \] and observe that $a,b \not\in \P$. We show $Q(\P, a,b)$ holds and hence $\P = \P_{\sr{F},p}$ is not prime. Let $K\leq N$, $K' \leq N'$, $g,g'\in G$, and $K^g, K'^{g'}\leq L$ and consider the generalized product \begin{align*}
          &\Big(\nm_{K^g}^{L}\circ \conj_{g, K}\circ \res_{K}^{N}(a)\Big)
                  \cdot\left(\nm_{K'^{g'}}^{L} \circ \conj_{g', K'} \circ \res_{K'}^{N'}(b)\right)\\
                  &= \nm_{K^g}^{L}\Big((a_{I^{g^{-1}}})_{I\leq K^g}\Big)
                  \cdot \nm_{K'^{g'}}^{L}\left((b_{I^{g'^{-1}}})_{I\leq K'^{g'}}\right)\\
                  &= \left(\left(\prod_{\gamma \in J\setminus L/K^g} a_{J^{\gamma g^{-1}}\cap K}\right)\cdot \left(\prod_{\gamma' \in J\setminus L/K'^{g'}} b_{J^{\gamma' g'^{-1}}\cap K'}\right)\right)_{J\leq L}.
    \end{align*} We want to show that this element is in $\P(G/L) = (p_J)_{J\leq L}$. The $J^{th}$ component of this element is 0 unless $J^{\gamma g^{-1}}\cap K =N$ and $J^{\gamma' g'^{-1}}\cap K' = N'$ for all $\gamma, \gamma'$. This means we must have $K=N$ and $K'=N'$, and moreover $N,N'\preccurlyeq_G J$, which then implies that $J\not\in \sr{F}$ and so $1\in (p_J) = \ZZ$, as desired.
\end{proof}

We prove the main theorem (\Cref{thm:containment all}) by showing that if $\P$ is a prime ideal over $p$, then $\P = \P_{\sr{F}, p}$ for some family $\sr{F}$. \cref{thm:prime iff subgp fam} then implies that there is some $H\leq G$ so that $\P = \P_{H,p}$. Before doing so, we observe some containment rules.

\begin{proposition}\label{prop:ghost containments}
    For any finite group $G$, subgroups $H,K\leq G$, and $p,q$ prime, there are containments:\begin{enumerate}
        \item[(i)] $\P_{H,0}\subseteq \P_{K,0}$ if and only if $K\preccurlyeq_G H$,
        \item[(ii)] $\P_{H,0}\subseteq \P_{H,p}$ and $\P_{H, p}\not\subseteq \P_{K,0}$, and
        \item[(iii)] $\P_{H,p}\subseteq \P_{K,q}$ if any only if $p=q$ and $K\preccurlyeq_G H$. 
    \end{enumerate}
\end{proposition}\begin{proof}
    The claims are all straightforward to check; we include a proof of the ``only if'' direction of (iii) to indicate the general strategy. Suppose $\P_{H,p}\subseteq \P_{K,p}$. Then at level $G$, we have 
	\[
		\big( \delta_{H,p}(I) \big)_{I \leq G} \subseteq \big( \delta_{K,p}(I) \big)_{I \leq G}
	\]
where $\delta_{H,p}(I)$ is $p$ if $I\preccurlyeq_G H$ and $1$ otherwise. Then $\delta_{K,p}(K) = p$ so $\delta_{H,p}(K)=p$ as well and hence $K\preccurlyeq_G H$.
\end{proof}

We now argue that every prime ideal in $\burnghost$ is of the form $\P_{K,p}$ for some $K\leq G$ and $p \in \ZZ$ either a prime or $0$. Suppose $\P\in \Spec(\burnghost)$ is a prime ideal over $p$, meaning $\P(G/e) = (p)$ for some $p$ prime or $0$. Then $\P$ is a levelwise ideal, so we may write
\[
	\P(G/H) = (\n{I}{H})_{I\leq H}
\] 
for $H\leq G$, $\n{I}{H} \in \ZZ$.  

\begin{lemma}\label{lem:componentwise prime}
    For all $I\leq H\leq G$, the ideal $(\n{I}{H})\subseteq \ZZ$ is prime or the entire ring.
\end{lemma}
\begin{proof}
     Let $\alpha, \beta\in \ZZ$ so that $\alpha\cdot \beta \in (\n{I_0}{H})$ for some subgroup $I_0 \leq H$ and consider the elements $a, b\in \burnghost(G/H)$ given by \[
    a_I = \left\{\begin{array}{cc}
        \alpha & I \conjugate{H} I_0, \\
        0 & \text{ else},
    \end{array}\right. \quad \text{ and } \quad b_I = \left\{\begin{array}{cc}
        \beta & I \conjugate{H} I_0, \\
        0 & \text{ else},
    \end{array}\right.
    \] where $\conjugate{H}$ denotes conjugacy in $H$. We want to show that $\alpha$ or $\beta$ is in $(\n{I_0}{H})$, or equivalently, that $a$ or $b$ is in $\P(G/H)$. We do so by showing that $Q(\P, a, b)$ is true, which then implies the desired result as $\P$ is prime.

    Let $K, K'\leq H$ and $K^g,K'^{g'}\leq L$ for $g,g'\in G$. We want to show that the generalized product\[
    \left(\left(\prod_{\gamma \in J\setminus L/K^g} a_{J^{\gamma g^{-1}}\cap K}\right)\cdot \left(\prod_{\gamma' \in J\setminus L/K'^{g'}} b_{J^{\gamma' g'^{-1}}\cap K'}\right)\right)_{J\leq L}
    \] is in $\P(G/L)$. The $J^{th}$-component of this product is $0$ (and hence in the ideal) except in the case that $I_0 \preccurlyeq_H K,K'$ and $J^{\gamma g^{-1}}\cap K \conjugate{H} J^{\gamma' g'^{-1}}\cap K \conjugate{H} I_0$ for all $\gamma, \gamma'$. In this case, it suffices to show that\[
    \alpha^{\abs{J\setminus L/K^g}}\cdot \beta^{\abs{J\setminus L/K'^{g'}}} \in \P(G/L)_J = (n_{J\leq L}).
    \]

    Without loss of generality suppose that $\abs{J\setminus L/K^g}\leq \abs{J\setminus L/K'^{g'}}$. By assumption, the product $a\cdot b$ is in $\P(G/H)$ and so, since $\P$ is closed under the Tambara structure maps, the element
    \[
        \nm_{K^g}^L  \conj_{g, K}  \res_K^H(a\cdot b)
    \] 
    is in $\P(G/L)$. The $J^{th}$-component of this element is \[\prod_{\gamma \in J\setminus L / K^g} (a\cdot b)_{J^{\gamma g^{-1}}\cap K} = (\alpha\cdot \beta)^{\abs{J\setminus L/K^g}}\] and so $\alpha^{\abs{J\setminus L/K^g}}\cdot \beta^{\abs{J\setminus L/K^g}}\in (\n{J}{L})$ and the claim follows.
\end{proof}

\begin{proposition}\label{prop:value indep of lvl}
    For all $I\leq H\leq G$, the value of $\n{I}{H}$ does not depend on $H$, i.e. $\n{I}{H} = \n{I}{G}$.
 \end{proposition}
 The proof is broken up into three lemmas.

\begin{lemma}
    For any prime ideal $\P$, write $\P(G/K) = (\n{I}{K})_{I\leq K}$ as above. For any subgroup $H\leq G$, the following are equivalent:
    \begin{enumerate}[(a)]
        \item $\n{H}{G}=1$,
        \item $\n{H}{K}=1$ for all $H\leq K\leq G$,
        \item $\n{H}{H}=1$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    The implication $(b)\implies (c)$ is immediate.  The implication $(a)\implies (b)$ follows at once from the fact that the restriction map in the ghost is projection.  Thus it suffices to prove $(c)\implies (a)$.

    Let us abbreviate $N = N_GH$. We first show that $\n{H}{N}=1$.  To see this, let $\alpha \in \P(G/H)$ be the element with components
    \[
        \alpha_{I,H} = \begin{cases}
            1 & I=H,\\
            0 & \mathrm{else}.
        \end{cases}
    \]
    Taking the norm we have
    \[
        \nm_H^{N}(\alpha)_{H,N} = \prod\limits_{[g]\in H\backslash N/H} \alpha_{H,H} = 1
    \]
    and thus $1\in (\n{H}{N})$ so $\n{H}{N}=1$.  Let $\alpha'\in \P(G/N)$ be the element with components
    \[ 
        \alpha'_{I,N} = \begin{cases}
            1 & I \conjugate{N} H,\\
            0 & \mathrm{else}.
        \end{cases}
    \]
    which must be in $\P(G/N)$ since $\n{H}{N}=1$.  Taking the transfer we have 
    \[
    \tr^G_N(\alpha')_{H,G} = \sum_{\substack{\gamma\in G/N\\H^\gamma \leq N}} \alpha'_{H^{\gamma}, N}. 
    \]
    Let $X = \{\gamma\in G/N\mid H^{\gamma} \conjugate{N} H\}$.  Since $\alpha'_{H^{\gamma},N}=0$ unless $\gamma\in X$ we have 
    \[
        \tr^G_N(\alpha')_{H\leq G} = \sum_{\gamma\in X}\alpha_{H^{\gamma},N} = |X|.
    \]
    We claim that $X$ has precisely one element, namely the class of $\gamma = e$, and thus $\tr^G_N(\alpha')_{H, G}=1$ and $\n{H}{G}=1$.  To see this, suppose that $x\in X$ and note that there must be a $y\in N$ such that $H^{xy}=H$.  But then $xy\in N_GH=N$ and hence $x\in N$, so $xN =eN$ as claimed.
\end{proof}
\begin{lemma}
    For any prime ideal $\P$, write $\P(G/K) = (\n{I}{K})_{I\leq K}$ as above. For any subgroup $H\leq G$, the following are equivalent:
    \begin{enumerate}[(a)]
        \item $\n{H}{G}=0$,
        \item $\n{H}{K}=0$ for all $H\leq K\leq G$,
        \item $\n{H}{H}=0$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    The implication $(b)\implies (c)$ is trivial, the implication $(c)\implies (a)$ is immediate from the fact that restriction is given by projection.  Thus it remains to prove $(a)\implies (b)$.  Suppose there is a $K\leq G$ with $\n{H}{K} \neq 0$.  Since restriction is projection it follows that $n = \n{H}{H}> 0$.  Consider the element $\alpha\in \P(G/H)$ with components
    \[
        \alpha_{I, H} = \begin{cases}
            n & I=H,\\
            0 & \mathrm{else}.
        \end{cases}
    \]
    It is immediate from the definitions that $\tr^G_H(\alpha)_{H\leq G}>0$.  Since $\tr^G_H(\alpha)_{H\leq G}\in (\n{H}{G})$ we have $\n{H}{G} \neq 0$.  The implication $(a)\implies (b)$ follows by contrapositive.\end{proof}

\begin{lemma}
    Let $p$ be a prime number. For any prime ideal $\P(G/K) = (\n{I}{K})_{I\leq K}$ and any subgroup $H\leq G$ the following are equivalent:
    \begin{enumerate}[(a)]
        \item $\n{H}{G}=p$,
        \item $\n{H}{K}=p$ for all $H\leq K\leq G$,
        \item $\n{H}{H}=p$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Since $\P$ is prime we know $\n{H}{G}$ and $\n{H}{H}$ are prime numbers, $0$, or $1$.  By the previous two lemmas, we know that if either or these numbers is $0$ or $1$ then all three of the possibilites in the statement of the lemma are impossible. So without loss of generality we assume that $\n{H}{G}$ and $\n{H}{H}$ are both primes numbers, though not necessarily the same ones.

    The implication $(b)\implies (c)$ is trivial, the implication $(c)\implies (a)$ follows from the fact that restriction is a projection which implies that $\n{H}{G}\in (\n{H}{H}) = (p)$. Since $\n{H}{G}$ is prime we see that $\n{H}{G}=p$.

    To prove that $(a)\implies (b)$, suppose that $\n{H}{G}=p$. There is some $K\leq G$ with $\n{H}{K}\neq p$.  Since restriction is projection we have $\n{H}{G}=p\in(\n{H}{K})$ which implies that $(\n{H}{K})$ is either $1$ or $p$.  If $\n{H}{K}=1$ then restriction implies $\n{H}{H}=1$, but we have already seen that this would imply $\n{H}{G}=1$ which is a contradiction.  Thus $(\n{H}{K})=p$ and $(a)\implies (b)$.
\end{proof}


We may therefore write $\P(G/H) = (p_I)_{I\leq H}$ where $p_I$ is $0$, $1$, or prime.

\begin{lemma}
    \label{lemma: families from primes}
    If $\P$ is a prime ideal over $p$, then $\sr{F}(\P) := \{I\leq G\mid p_I\neq 1\}$ is a nonempty family of subgroups.
\end{lemma}
\begin{proof}
    For $H\leq K$, the $K$-component of $\nm_H^K((n_I)_{I\leq H})$ is $\prod_{K\setminus K/H} n_{K\cap H} = n_H$. This implies $n_H\in (n_K)$, and hence if $n_K\neq 1$, we must have $n_H\neq 1$.
\end{proof}

\begin{remark}
    The exact same argument shows that $\sr{F}_0 := \{I\leq H\mid n_I=0\}$ is a family of subgroups. This will only be relevant for $\P$ a prime ideal over $0$.
\end{remark}

Recall from \Cref{defn:PFp} that for a family of subgroups $\sr{F}$, we consider the ideal $\P_{\sr{F},p}(G/H) = (p_I)_{I \leq H}$ where $p_I$ is $p$ if $I \in \sr{F}$ and $1$ else.

\begin{corollary}\label{prime over p}
    If $\P$ is a prime ideal over $p\neq 0$, and $\sr{F}(\P)$ is as in \cref{lemma: families from primes},  then $\P=\P_{\sr{F}(\P),p}$.
\end{corollary}
\begin{proof}
    By assumption, $p_e=p\neq 0$. Taking the norm 
    \[
    	\nm_e^G(p_e) = \bigg(\prod_{\gamma\in I\setminus G/e} p_{I^{\gamma}\cap e}\bigg)_{I\leq G} = \big(p^{\abs{G:I}}\big)_{I\leq G}
    \] shows $p^{\abs{G:I}}\in (p_I)$ for all $I\leq G$. Thus $p_I$ is either $1$ or $p$, so $\P$ is as claimed.
\end{proof}

\begin{proposition}\label{prime over zero}
    If $\P$ is a prime ideal over $0$, then $\sr{F}(\P) = \sr{F}_0$ and $\P = \P_{\sr{F}(\P), 0}$.
\end{proposition}
\begin{proof}
    Suppose for contradiction that the containment $\sr{F}_0\subseteq \sr{F}(\P)$ is proper. Define \[
    n = \prod_{H\in \sr{F}\setminus \sr{F}_0} p_H
    \] and choose any $\hat I\in \sr{F}_0$ maximal, i.e. with the property that if $\hat I\preccurlyeq_G H$ then $H\not\in \sr{F}_0$. Consider the element $a\in \burnghost(G/\hat I)$ given by\[
    a_I = \left\{\begin{array}{cc}
        n &  I = \hat I,\\
        0 & \text{else},
    \end{array}\right.
    \] and observe $a\not\in \P$. We show that $Q(\P, a,a)$ holds, contradicting the fact that $\P$ is prime, and consequently we may conclude that $\sr{F}_0 = \sr{F}$. It follows immediately that $\P = \P_{\sr{F}, 0}$.

    Let $K, K'\leq H$, $g,g'\in G$, and $K^g, K'^{g'}\leq L$. We want to show that the generalized product\[
    \left(\left(\prod_{\gamma \in J\setminus L/K^g} a_{J^{\gamma g^{-1}}\cap K}\right)\cdot \left(\prod_{\gamma' \in J\setminus L/K'^{g'}} a_{J^{\gamma' g'^{-1}}\cap K'}\right)\right)_{J\leq L}
    \] is in $\P(G/L)$. The $J^{th}$-component of this product is $0$ (and hence in the ideal) except in the case that $\hat I \preccurlyeq_H K,K'$ and $J^{\gamma g^{-1}}\cap K \conjugate{H} J^{\gamma' g'^{-1}}\cap K \conjugate{H} \hat I$ for all $\gamma, \gamma'$. In this case, $\hat I\preccurlyeq_G J$ and the generalized product is $n^{\abs{J\setminus L/K^g}+\abs{J\setminus L/ K'^{g'}}}$. But then $J\not\in \sr{F}_0$ by our choice of $\hat I$, and so $n\in (p_J)$ by the definition of $n$.
\end{proof}

\begin{corollary}
    For any finite group $G$,\[
    \Spec(\burn_G) = \{\fr{p}_{H,p}\mid H\leq G, p \text{ prime or } 0\}.    \]
\end{corollary}

\begin{proof}
    We have shown that the prime ideals of $\burnghost$ are precisely the $\P_{H,p}$. Since the ghost map is a levelwise integral extension, by \cite[Corollary 5.7]{CMQSV:24}, the ghost map induces a surjection on $\Spec$, which is precisely the assignment $\P_{H,p}\mapsto \fr{p}_{H,p}$.
\end{proof}

In \cite[Theorem 3.9]{CalleGinnett:23}, the authors established containment rules for the $\fr{p}_{H,p}$ when $G$ is abelian. We can extend these containment rules to apply to any finite group using \cref{prop:ghost containments}.

\begin{theorem}\label{thm:containment all}
    Let $H,K\leq G$ and $p,q$ be prime. Then
    \begin{enumerate}
    \item[(i)] $\fr{p}_{H, 0}\subseteq \fr{p}_{K, 0}$ if and only if $K \preccurlyeq_G H$,
    \item[(ii)] $\fr{p}_{H, 0}\subset \fr{p}_{H, p}$ and $\fr{p}_{H, p}\not\subseteq \fr{p}_{K, 0}$,
    \item[(iii)] $\fr{p}_{H, p}\subseteq \fr{p}_{K, q}$ if and only if $p = q$ and $O^p(K)\preccurlyeq_G O^p(H)$,
\end{enumerate} where $O^p(H)$ is the $p$-residual subgroup as in \cref{defn:OpH}.
\end{theorem}
\begin{proof}
Since the ghost map is injective, it suffices to prove the analogous claims about the $\K_{L, p}$. Recall that $\K_{L,p}$ is defined to be the intersection of $\P_{L,p}$ with the image of the ghost map, \[\K_{L,p}(G/H) = \big(\delta_{L,p}(I)\big)_{I \leq H} \cap \ghost(\burn_G(G/H)), \]  where $\delta_{L,p}(I)$ is $p$ if $I\preccurlyeq_G L$ and $1$ otherwise.

The ``if'' direction of (i) is immediate from \cref{prop:ghost containments}. For the ``only if,'' we show the contrapositive. Suppose $K\not\preccurlyeq_G H$, so the element $a\in \burnghost(G/K)$ given by\[
a_I = \left\{\begin{array}{cc}
    1 & I = K, \\
     0 & \text{else},
\end{array}\right.
\] is in $\P_{H,0}(G/K)$ but not in $\P_{K,0}(G/K)$. Since the ghost map has finite cokernel \cite[Proposition 1.2.3]{tomDieck}, there is some $n \gg 0$ so that $n\cdot a$ is in the image of $\ghost(G/K): A(K)\to \burnghost(G/K)$. This means that $n\cdot a\in \K_{H,0}(G/K)$ but not in $\K_{K,0}(G/K)$, so then $\K_{H,0}\not\subseteq \K_{K,0}$ as desired.

The first part of (ii) is also immediate from \cref{prop:ghost containments}. For the second part, we observe (as in the proof of the same claim in \cite{CalleGinnett:23}) that we may consider the $G$-set $X=p[G/G]$, as $\abs{X^I}\in (p)$ for all $I\leq G$ but $\abs{X^I}\neq 0$ for any $I\leq G$. 

For (iii), we claim it suffices to show that $\K_{H,p} = \K_{O^p(H), p}$ for all $H\leq G$. Given this, the ``if'' direction becomes immediate and the ``only if'' direction proceeds as in (i). The only extra claim we need is that we may find $n$ such that $p\nmid n$, which follows from the fact that $p\nmid \abs{O^p(K)}$ and the order of the cokernel is only divisible by primes which also divide $\abs{G}$ (c.f. \cite[Proposition 1.2.3]{tomDieck}).

To see that $\K_{H,p} = \K_{O^p(H), p}$, we first observe that the $\subseteq$ containment is immediate. For $\supseteq$, suppose we have $X\in A(G)$ so that $\abs{X^I}\in (p)$ for all $I\preccurlyeq_G O^p(H)$. We want to show that $\abs{X^J}\in (p)$ for all $J\preccurlyeq_G H$, but $\abs{X^J} \equiv_p \abs{X^{O^p(J)}}$ (c.f. \cite[Remark 2.18] {CalleGinnett:23}). Hence it suffices observe that if $J\preccurlyeq_G H$, then $O^p(J)\preccurlyeq_G O^p(H)$, which is \cref{rmk:OpH from sylows}.
\end{proof}

\begin{corollary}
    If $G$ is a $p$-group then $\mf{p}_{H,p} = \mf{p}_{K,p}$ for all $H,K\leq G$.  For $q\neq p$ we have $\mf{p}_{H,q} = \mf{p}_{K,q}$ if and only if $H$ and $K$ are conjugate.
\end{corollary}
\begin{proof}
    It is immediate from (iii) above that $\mf{p}_{H,p} = \mf{p}_{K,p}$ if and only if $O^p(H)$ and  $O^p(K)$ are conjugate. For the first claim, since $H$ and $K$ are both $p$-groups both of the $p$-residual subgroups are the trivial group, hence are equal.  For the second claim, note that we have $O^q(A)=A$ for all subgroups $A\leq G$.
\end{proof}

The Krull dimension of a Tambara functor is defined similarly to the Krull dimension of a commutative ring \cite[Def. 8.1]{CMQSV:24}. The results above imply that the Krull dimension of $\burn_G$ is always one more than the length of the longest chain in the poset of conjugacy classes of subgroups of $G$; the zero ideal $\mf{p}_{e,0}$ is contained in every other prime $\mf{p}_{H,p}$ and accounts for the plus one.

\begin{proposition}
    For any finite group $G$, there is a continuous bijection
    \[\Spec(A(G)) \to \Spec(\uA_G),\]
   but $\Spec(A(G))$ and $\Spec(\uA_G)$ are not homeomorphic unless $G$ is the trivial group.
\end{proposition}
\begin{proof}
    We have established that
    \[\ker \varphi_{G,p}^H \mapsto \mf{p}_{H,p} : \Spec(A(G)) \to \Spec(\uA_G)\]
    is a bijection. By \Cref{thm:containment all} and \Cref{thm:dress containment}, this is a morphism of posets. Since $A(G)$ is a Noetherian ring and $\uA_G$ is a Noetherian Tambara functor, this function is continuous by \cite[Theorem 2.24]{CMQSV:24}.

    To see that $\Spec(A(G))$ and $\Spec(\uA_G)$ are not homeomorphic unless $G$ is trivial, let $q$ be any prime number not dividing the order of $G$ and suppose $G \neq e$. Then we have proper containments
    \[\mf{p}_{e,0} \subset \mf{p}_{G,0} \subset \mf{p}_{G,q},\]
    demonstrating that the Krull dimension of $\Spec(\uA_G)$ is at least $2$. On the other hand, the Krull dimension of $\Spec(A(G))$ is $1$.
\end{proof}

\section{Examples}\label{section:examples}

In this section we give explicit descriptions of $\Spec(\uA_G)$ for various groups $G$.  We focus on non-abelian groups since these are examples which have not previously appeared in the literature.  To describe these spaces, we note that there is a poset map $\Spec(\uA_G)\to \Spec(\mathbb{Z})$ given by $\mf{p}_{H,p}\mapsto (p)$ for $p$ a prime or $0$.  We describe the poset $\Spec(\uA_G)$ by describing the fiber of this map over every prime $(p)$.  Property (iii) from \cref{thm:containment all} implies there are no containments between prime ideals which live in fibers over distinct primes, and property (ii) describes possible containments between the fiber over $(0)$ and the fibers over primes.

Note that if a prime $p$ does not divide the order of a group $G$ then for every subgroup $H\leq G$ we have $O^p(H) = H$ and thus condition (iii) in \cref{thm:containment all} becomes $\mf{p}_{H,p}\subset \mf{p}_{K,p}$ if and only if $K\preccurlyeq_G H$.  Thus, at any generic prime $p$ the fiber is simply the opposite of the subconjugacy poset, i.e.\ the poset obtained by taking orbits of the subgroup poset by the conjugation action.  

In all our examples we begin by displaying the subconjugacy poset, and then  display the poset corresponding to primes which do divide the group order. If $x,y$ are elements of a poset $P$ we write $x\to y$ to indicate that $x\leq y$.

\begin{example}
    Let $G = D_{p^n}$ be the dihedral group of order $2p^n$ where $p\neq 2$ is a prime.
    The fiber over a generic prime $q\neq 2,p$ is the opposite of the subconjugacy poset:
\[\begin{tikzcd}
	{\mf{p}_{D_1,q}} & {\mf{p}_{D_p,q}} & \dots & {\mf{p}_{D_{p^{n-1}},q}} & {\mf{p}_{D_{p^n},q}} \\
	{\mf{p}_{e,q}} & {\mf{p}_{C_{p},q}} & \dots & {\mf{p}_{C_{p^{n-1}},q}} & {\mf{p}_{C_{p^n},q}} .
	\arrow[to=1-1, from=1-2]
	\arrow[to=1-2, from=1-3]
	\arrow[to=1-3, from=1-4]
	\arrow[to=1-4, from=1-5]
	\arrow[to=2-1, from=1-1]
	\arrow[to=2-1, from=2-2]
	\arrow[to=2-2, from=1-2]
	\arrow[to=2-2, from=2-3]
	\arrow[to=2-3, from=1-3]
	\arrow[to=2-3, from=2-4]
	\arrow[to=2-4, from=1-4]
	\arrow[to=2-4, from=2-5]
	\arrow[to=2-5, from=1-5]
\end{tikzcd}\]
The fiber over $q=2$ is controlled by the computations of $O^2$ of subgroups of $D_{p^n}$.  Since $C_{p^k}$ is a $p$-group, and $p\neq 2$, we have $O^2(C_{p^k}) = C_{p^k}$ for all $k$.  On the other hand we have, by \Cref{example: O of Dpn}, that $O^2(D_{p^k}) = C_{p^k}$ as well so the fiber over $q=2$ is a line
\[\begin{tikzcd}
	{\mf{p}_{e,2}} & {\mf{p}_{C_{p},2}} & \dots & {\mf{p}_{C_{p^{n-1}},2}} & {\mf{p}_{C_{p^n},2}} 
	\arrow[to=1-1, from=1-2]
	\arrow[to=1-2, from=1-3]
	\arrow[to=1-3, from=1-4]
	\arrow[to=1-4, from=1-5]
\end{tikzcd}.\]
For the fiber over $q=p$ we have that $O^p(C_{p^k})=e$ and $P^p(D_{p^k}) = D_{p^k}$ for all $k$.  Thus the fiber over $q=p$ is 
\[\begin{tikzcd}
	{\mf{p}_{e,p}} & {\mf{p}_{D_1,p}} & {\mf{p}_{D_{p},p}} & \dots & {\mf{p}_{D_{p^{n-1}},p}} & {\mf{p}_{D_{p^n},p}}
	\arrow[to=1-1, from=1-2]
	\arrow[to=1-2, from=1-3]
	\arrow[to=1-3, from=1-4]
	\arrow[to=1-4, from=1-5]
	\arrow[to=1-5, from=1-6]
\end{tikzcd}.\]
Note that while the fibers over $q=2$ and $q=p$ are both lines, the lengths of these lines differ by one.
\end{example}

\begin{example}
    Let $G = Q_8$.  The fiber over a generic prime $p\neq 2$ is the opposite of the subgroup lattice:
\[\begin{tikzcd}
	& {\mf{p}_{Q_8,p}} \\
	{\mf{p}_{C_4,p}} & {\mf{p}_{C_4,p}} & {\mf{p}_{C_4,p}} \\
	& {\mf{p}_{C_2,p}} \\
	& {\mf{p}_{e,p}}.
	\arrow[to=2-1, from=1-2]
	\arrow[to=2-2, from=1-2]
	\arrow[to=2-3, from=1-2]
	\arrow[to=3-2, from=2-1]
	\arrow[to=3-2, from=2-2]
	\arrow[to=3-2, from=2-3]
	\arrow[to=4-2, from=3-2]
\end{tikzcd}\]
Since $G$ is a $2$-group the fiber over $p=2$ is a single point. Completely analogous arguments handle the generalized quaternion case $G = Q_{4n}$ for all $n \in \mathbb{N}$. 
\end{example}

\begin{example}
    Let $G = A_4$ be the alternating group with $12$ elements. The fiber over a generic prime $q\neq 2,3$ is the opposite of the subconjugacy poset
\[\begin{tikzcd}
	& {\mf{p}_{A_4,q}} \\
	{\mf{p}_{K_4,q}} && {\mf{p}_{C_3,q}} \\
	{\mf{p}_{C_2,q}} \\
	& {\mf{p}_{e,q}}.
