    \end{center}
    \caption{The metric graph $G_6$, where $G$ is a $3 \times 3$ cube in $\Z^2$}

\end{figure}


The following result, obtained in \cite{NW} and \cite{AHPS}, shows that the correlation function on a rescaled sequence of the XY model on metric graphs converges to that of the Villain model.

\begin{theorem}
Let $G$ be a finite graph, $\beta>0$ and $n\in\N$, let $\beta_n = n\beta$ and $G_n$ be the metric graph obtained by $G$. Then we have 
    \begin{equation*}
      \lim_{n\to \infty}  \langle \cos \theta_x \cos \theta_y \rangle_{\mathrm{XY},\beta_n,G_n}
      =  \langle \cos \theta_x \cos \theta_y \rangle_{ \mathrm{Vil}, \beta,G}.
    \end{equation*}
    Likewise,
     \begin{equation*}
      \lim_{n\to \infty}  \langle \sin \theta_x \sin \theta_y \rangle_{\mathrm{XY}, \beta_n,G_n}
      =  \langle \sin \theta_x \sin \theta_y \rangle_{ \mathrm{Vil}, \beta,G}.
    \end{equation*}
\end{theorem}

Combined with Theorem \ref{t.dunlopnewman}, and the Ginibre inequality which gives the infinite volume limit of the Villain model, we obtain the corresponding Dunlop-Newman inequality for the Villain model in the thermodynamic limit. 
\begin{theorem}[Dunlop-Newman inequality for Villain model]
    For any $\beta>0$, we have
    \begin{multline*}
        \langle \sin \theta_x \sin \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}}^2
        \leq \\
       \left( \langle \cos \theta_x \cos \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}} - \langle \cos \theta_x \rangle_{\mu_{\mathrm{Vil}, \beta}} \langle \cos \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}} \right)
        \left( \langle \cos \theta_x \cos \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}} + \langle \cos \theta_x \rangle_{\mu_{\mathrm{Vil}, \beta}} \langle \cos \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}} \right).
    \end{multline*}
\end{theorem}
Together with the asymptotics of the transversal correlation $\langle \sin \theta_x \sin \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}}$ obtained in \eqref{e.2ptfirstfirst}, we obtain the desired lower bound 
\begin{equation*}
    \langle \cos \theta_x \cos \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}} - \langle \cos \theta_x \rangle_{\mu_{\mathrm{Vil}, \beta}} \langle \cos \theta_y \rangle_{\mu_{\mathrm{Vil}, \beta}}
    \ge
    \frac{c}{|x-y|^{2(d-2)}}.
\end{equation*}





\appendix

\section{Notation} \label{app.notation}

In this appendix, we show that the random variables introduced  Sections~\ref{sec:sec3.1} and~\ref{sec:sec3.2} are well-defined random variables (N.B. This is not necessarily obvious due to the sum over the charges $q \in \mathcal{Q}$). Specifically, we prove that:
\begin{itemize}
    \item The random variable $U_x$ is well-defined in $L^2(\Omega \, ; \, \R)$. While we will not prove it to minimise the technicality of this section, we note that the argument written below can be refined so as to show that the random variable $\exp (8U_x)$ is integrable (N.B. In fact one can show that the random variable $\exp ( p_\beta U_x)$ for a large exponent $p_\beta$ which depends on $\beta$, and tends to infinity as $\beta \to \infty$, is integrable).
    \item The sum over the charges in the definitions of the five other random variables (introduced in~\eqref{eq:def3.5}) converge absolutely for any value of $\varphi \in \Omega$. This implies that these random variables are well-defined (and in fact are bounded uniformly over $\varphi \in \Omega$).
\end{itemize}
Throughout this section, we will make use of the results of Appendix~\ref{App.sumonlattice} (specifically, the upper bound~\eqref{eq:truineqB1}).


\subsection{Showing that $U_{x}$ is a well-defined random variable in $L^2(\Omega \, ; \, \R)$.}

Given a large integer $L \in \N$, let us denote by
\begin{equation*}
    \mathcal{Q}_L := \left\{ q \in \mathcal{Q} \, : \, \supp q \subseteq  \Lambda_L\right\}.
\end{equation*}
We then let $U_L$ be the random variable
\begin{equation*}
     U_L(\varphi) := \sum_{q \in \mathcal{Q}_L} z(\beta , q)  \sin \left(2\pi(\di^* \varphi , n_q)\right)  \sin \left(2\pi(\nabla G_x , n_q)\right) \in \R.
\end{equation*}
Let us note that the sum on the right-hand side of the previous display is absolutely convergent for any realisation of the field $\varphi \in \Omega$ and that this is in fact a smooth function (depending on finitely many coordinates) of $\varphi \in \Omega$ (due to the same argument as in the proof of Lemma~\ref{lemma.lemma2.5}). We will then show the inequality
\begin{equation*} 
    \left\| U_{2L} - U_L \right\|_{L^2(\Omega \, ; \, \R)} \leq \frac{C}{L}.
\end{equation*}
This result implies that, for any pair of integers $k , l \in \N$ with $l \leq k$,
\begin{equation*}
    \left\| U_{2^k} - U_{2^l} \right\|_{L^2(\Omega \, ; \, \R)} \leq \frac{C}{2^l}.
\end{equation*}
The sequence of random variables $\left( U_{2^k} \right)_{k \in \N}$ is thus Cauchy in $L^2(\Omega \, ; \, \R)$; it thus converges in this space (and in fact almost surely) toward a random variable. This limiting random variable is our definition for $U_x$.

Applying the Helffer-Sj\"{o}strand representation formula (noting that $U_L$ is a smooth function of $\varphi$), we have that 
\begin{align*}
    \mathrm{Var}_{\mu_{\beta}} \left[ U_{2L} - U_L \right] & = \sum_{x \in \Zd} \left\langle \partial_x \left( U_{2L} - U_L \right)(\varphi) \cdot \mathcal{G}(x , \varphi) \right\rangle_{\mu_\beta} \\
    & = 2 \pi \sum_{q \in \mathcal{Q}_{2L} \setminus \mathcal{Q}_L} z(\beta , q)  \sin \left(2\pi(\nabla G , n_q)\right)  \left\langle \cos \left(2\pi(\di^* \varphi , n_q)\right)  \left( \sum_{x \in \Zd} \mathcal{G}(x, \varphi) \cdot q(x) \right) \right\rangle_{\mu_\beta} \\
    & = 2 \pi \sum_{q \in \mathcal{Q}_{2L} \setminus \mathcal{Q}_L} z(\beta , q)  \sin \left(2\pi(\nabla G , n_q)\right)  \left\langle \cos \left(2\pi(\di^* \varphi , n_q)\right)  \left(  \mathcal{G}(\cdot, \varphi) , q \right) \right\rangle_{\mu_\beta} \\
    & = 2 \pi \sum_{q \in \mathcal{Q}_{2L} \setminus \mathcal{Q}_L} z(\beta , q)  \sin \left(2\pi(\nabla G , n_q)\right)  \left\langle \cos \left(2\pi(\di^* \varphi , n_q)\right)  \left(  \di^* \mathcal{G}(\cdot, \varphi) , n_q \right) \right\rangle_{\mu_\beta}
\end{align*}
where 
\begin{align*}
    \mathcal{L} \mathcal{G}(x , \varphi) & =  \partial_x (U_{2L} - U_L) = 2 \pi \sum_{q \in \mathcal{Q}} z(\beta , q)  \sin \left(2\pi(\nabla G , n_q)\right) \cos \left(2\pi(\di^* \varphi , n_q)\right) q(x) \in \R^{d \choose 2}.
\end{align*}
Using the definition of the Green's matrix for the Helffer-Sj\"{o}strand equation, we have the identity
\begin{equation*}
    \mathcal{G}(x , \varphi) = 2 \pi \sum_{q \in \mathcal{Q}} z(\beta , q)  \sin \left(2\pi(\nabla G , n_q)\right)  (\di^*_2 \mathcal{G}_{\mathbf{f}_q}(x , \varphi; \cdot), n_q) \hspace{3mm} \mbox{with} \hspace{3mm} \mathbf{f}_q(\varphi) = \cos \left(2\pi(\di^* \varphi , n_q)\right).
\end{equation*}
This leads to the upper bound (which is uniform over $x \in \Zd$)
\begin{equation*}
    \left\| \di^* \mathcal{G}(x , \cdot) \right\|_{L^2(\Omega \, ; \, \R)} \leq \sum_{z \in \Lambda_{2L} \setminus \Lambda_L} \frac{C}{|z|_+^{d-1}} \frac{\left(\ln |x - z|_+\right)^{d+2}}{|x-z|_+^{d}} \leq \frac{C \left(\ln L \right)^{d+2}}{L^{d-1}}.
\end{equation*}
Combining the previous inequality with the Cauchy-Schwarz inequality and the same argument as in the proof of Lemma~\ref{lemma.lemma2.5}, we deduce that (denoting by $C_q$ a constant which may grow polynomially fast in $\left\| q \right\|_1$)
\begin{align*}
    \mathrm{Var}_{\mu_{\beta}} \left[ U_{2L} - U_L \right] \leq C \sum_{q \in \mathcal{Q}_{2L} \setminus \mathcal{Q}_L} |z(\beta,q)| \left| (\nabla G , n_q) \right|  \left| \left\langle \left( \di^* \mathcal{G}(\cdot, \varphi) , n_q \right) \right\rangle_{\mu_\beta} \right| & \leq  \sum_{q \in \mathcal{Q}_{2L} \setminus \mathcal{Q}_L} |z(\beta,q)| \frac{C_q}{L^{d-1}}  \frac{C_q (\ln L)^{d+2}}{L^{d-1}}  \\
    & \leq \frac{(\ln L)^{d+2}}{L^{2d-2}} \underset{\leq C L^d}{\underbrace{\sum_{q \in \mathcal{Q}_{2L} \setminus \mathcal{Q}_L} z(\beta,q) C_q}} \\
    & \leq \frac{C (\ln L)^{d+2}}{L^{d-2}}.
\end{align*}


\subsection{Estimating the $L^\infty(\Omega \, ; \, \R)$-norm of $U_{\cos , x}$}
Using the upper bounds $\left| \cos (a) \right| \leq 1$, $1 - \cos (a) \leq a^2/2$ for $a \in \R$, the observation $2d - 2 > d$ (since $d \geq 3$) and the same argument as in Lemma~\ref{lemma.lemma2.5}, we may write: for any $x \in \Zd$ and any $\varphi \in \Omega$,
\begin{align*}
    \left|  U_{\cos , x}(\varphi) \right|  \leq \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left|\cos \left(2\pi(\di^* \varphi , n_q)\right)\right|  \left| \cos \left(2\pi(\nabla G , n_q)\right) - 1 \right| \leq C \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left| (\nabla G , n_q) \right|^2
    & \leq   \sum_{q \in \mathcal{Q}} |z(\beta , q)| \frac{C_q}{|z_q|_+^{2d-2}} \\
    & \leq C \sum_{z \in \Zd} \frac{1}{|z|_+^{2d-2}} \\
    & \leq C.
\end{align*}

\subsection{Estimating the $L^\infty(\Omega \, ; \, \R)$-norm of $U_{\sin \cos , x}$}
Using the upper bounds $\left| \cos (a) \right| \leq 1$, $\left| \sin (a) \right| \leq |a|$, $1 - \cos (a) \leq a^2/2$ for $a \in \R$ and the same argument as in Lemma~\ref{lemma.lemma2.5}, we may write: for any $x \in \Zd$ and any $\varphi \in \Omega$,
\begin{align*}
    \left|  U_{\sin \cos , x}(\varphi) \right| & \leq \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left|\cos \left(2\pi(\di^* \varphi , n_q)\right)\right| \left| \sin \left(2\pi(\nabla G_x , n_q)\right) \right|  \left| \cos \left(2\pi(\nabla G , n_q)\right) - 1 \right| \\
    & \leq C \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left| (\nabla G_x , n_q) \right| \left| (\nabla G , n_q) \right|^2 \\
    & \leq  C \sum_{q \in \mathcal{Q}} |z(\beta , q)|\frac{C_q}{|x - z_q|_+^{d-1} |z_q|_+^{2d-2}} \\
    & \leq C \sum_{z \in \Zd} \frac{1}{|x - z|_+^{d-1}|z|_+^{2d-2}} \\
    & \leq \frac{C}{|x|_+^{d-1}}.
\end{align*}

\subsection{Estimating the $L^\infty(\Omega \, ; \, \R)$-norm of $U_{\cos \sin , x}$}
Using the same computation as for the term $U_{\cos \sin}$, we have that: for any $x \in \Zd$ and any $\varphi \in \Omega$,
\begin{align*}
    \left|  U_{\cos \sin , x}(\varphi) \right|  \leq C \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left| (\nabla G_x , n_q) \right|^2 \left| (\nabla G , n_q) \right| \leq  C \sum_{q \in \mathcal{Q}} |z(\beta , q)|\frac{C_q}{|x - z_q|_+^{2d-2} |z_q|_+^{d-1}}
    & \leq C \sum_{z \in \Zd} \frac{1}{|x - z|_+^{2d-2}|z|_+^{d-1}} \\
    & \leq \frac{C}{|x|_+^{d-1}}.
\end{align*}

\subsection{Estimating the $L^\infty(\Omega \, ; \, \R)$-norm of $U_{\cos \cos , x}$}
Using the upper bounds $\left| \cos (a) \right| \leq 1$ and $1 - \cos (a) \leq a^2/2$ for $a \in \R$, we may write: for any $x \in \Zd$ and any $\varphi \in \Omega$,
\begin{align*}
    \left|  U_{\cos \cos , x} (\varphi) \right|  \leq C \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left| (\nabla G_x , n_q) \right|^2 \left| (\nabla G , n_q) \right|^2
     \leq  C \sum_{q \in \mathcal{Q}} |z(\beta , q)|\frac{C_q}{|x - z_q|_+^{2d-2} |z_q|_+^{2d-2}}
    & \leq C \sum_{z \in \Zd} \frac{1}{|x - z|_+^{2d-2}|z|_+^{2d-2}} \\
    & \leq \frac{C}{|x|_+^{2d-2}}.
\end{align*}

\subsection{Estimating the $L^\infty(\Omega \, ; \, \R)$-norm and the variance of $U_{\sin \sin , x}$}
Using the upper bound $\left| \sin (a) \right| \leq |a|$ for $a \in \R$, we may write: for any $x \in \Zd$ and any $\varphi \in \Omega$,
\begin{align*}
    \left|  U_{\sin \sin , x} (\varphi) \right|  \leq C \sum_{q \in \mathcal{Q}} |z(\beta , q)| \left| (\nabla G_x , n_q) \right| \left| (\nabla G , n_q) \right| \leq  C \sum_{q \in \mathcal{Q}} |z(\beta , q)|\frac{C_q}{|x - z_q|_+^{d-1} |z_q|_+^{d-1}}
    & \leq C \sum_{z \in \Zd} \frac{1}{|x - z|_+^{d-1}|z|_+^{d-1}} \\
    & \leq \frac{C}{|x|_+^{d-2}}.
\end{align*}
The variance of the random variable $U_{\sin \sin , x}$ is more technical to estimate. We first collect the identity, for each $y \in \Zd$,
\begin{equation*}
  \partial_y U_{\sin \sin , x} (\varphi) = - \sum_{q \in \mathcal{Q}}2\pi z(\beta , q) \sin \left(2\pi(\di^* \varphi , n_q)\right) \sin \left(2\pi(\nabla G , q)\right) \sin \left( 2\pi(\nabla G_x , q)\right) q(y) \in \R^{d \choose 2}.
\end{equation*}
By applying the Helffer-Sj\"{o}strand representation formula, we have the identity
\begin{align*}
     \mathrm{Var}_{\mu_\beta} \left[ U_{\sin \sin , x} \right] & = \sum_{y \in \Zd} \left\langle \partial_y U_{\sin \sin , x} (\varphi)  \cdot \mathcal{G}(y , \varphi) \right\rangle_{\mu_\beta} \\
     & = 2\pi \sum_{q \in \mathcal{Q}}  z(\beta , q)  \sin \left( 2\pi(\nabla G , n_q)\right) \sin \left( 2\pi(\nabla G_x , q) \right)\left\langle  \sin \left( 2\pi(\di^*\varphi , n_q) \right) \left( \di^* \mathcal{G}(\cdot , \phi) , n_q \right) \right\rangle_{\mu_\beta}
\end{align*}
with
\begin{equation*}
    \mathcal{L} \mathcal{G}(z , \varphi) = 2 \pi \sum_{q \in \mathcal{Q}} z(\beta , q) \sin\left( 2\pi(\di^* \varphi , q) \right) \sin \left(2\pi(\nabla G , n_q) \right) \sin \left(2\pi(\nabla G_x , n_q)\right) q(z).
\end{equation*}
This function can be decomposed using the Green's matrix as follows
\begin{equation*}
     \mathcal{G}(z , \varphi) = 2 \pi \sum_{q \in \mathcal{Q}} z(\beta , q)  \sin \left(2\pi(\nabla G , n_q) \right) \sin \left(2\pi(\nabla G_x , n_q)\right) \left( \di^*_2 \mathcal{G}_{\mathbf{f}_q}(z , \varphi , \cdot ) ,  n_q \right)
\end{equation*}
with $\mathbf{f}_q(\varphi) = \sin\left( 2\pi(\di^* \varphi , q) \right)$. By Lemma~\ref{lemma.lemma2.5} and Proposition~\ref{prop.prop4.11chap4}, this leads to the upper bound
\begin{equation*}
    \left\| \di^* \mathcal{G} (z , \cdot) \right\|_{L^2 \left( \Omega \, ; \, \R^{d} \right)} \leq \sum_{z' \in \Zd} \frac{C}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{(\ln |z - z'|_+)^{d+2}}{|z' - z|_+^{d}}.
\end{equation*}
We thus obtain, using Lemma~\ref{lemma.lemma2.5} again together with the inequality~\eqref{ineqB4} of Appendix~\ref{App.sumonlattice}
\begin{equation*}
    \mathrm{Var}_{\mu_\beta} \left[ U_{\sin \sin , x} \right]  \leq C \sum_{z , z' \in \Zd} \frac{1}{|z|_+^{d-1} |z - x|_+^{d-1}}  \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{(\ln |z - z'|_+)^{d+2}}{|z - z'|_+^{d}}  \leq \frac{C}{|x|^{2d-2}_+}.
\end{equation*}

\section{Annealed regularity estimates for the heat kernel} \label{app.CZreg}


This section contains the proof of the inequalities~\eqref{eq:decaygradheat} and~\eqref{eq:decaygradgradheat} of Proposition~\ref{prop.prop4.11chap4HK}. The result is restated below.

\begin{proposition}[$L^p$-annealed regularity] \label{prop:Lpannealedreg}
    For any exponent $p \in (1 , \infty),$ there exists an inverse temperature $\beta_1 := \beta_1(p , d) < \infty$ such that for any $\beta \geq \beta_1$ and any pair of vertices $x , y \in \Zd$,
    \begin{equation*}
        \left\| \di^*_1 P^{\cdot}(t , x  , y ) \right\|_{L^p\left(\Omega \, ; \, \R^{d \times {d \choose 2}} \right)} +  \left\| \di^*_2 P^{\cdot}(t , x  , y ) \right\|_{L^p\left(\Omega \, ; \, \R^{{d \choose 2} \times d} \right)} \leq \frac{C (\ln t_+)^{(d+2)}}{t^{\frac d2 + \frac{1}{2}}} \exp \left( - \frac{|x-y|}{C\sqrt{t_+}} \right)
    \end{equation*}
    and
    \begin{equation*}
        \left\| \di^*_1 \di^*_2 P^{\cdot}(t , x  , y ) \right\|_{L^p\left(\Omega \, ; \, \R^{d \times d } \right)} \leq \frac{C (\ln t_+)^{(d+2)}}{t^{\frac d2 + 1}} \exp \left( - \frac{|x-y|}{C\sqrt{t_+}} \right).
    \end{equation*}
\end{proposition}

\begin{remark}
Let us make two remarks about the previous statement:
\begin{itemize}
    \item More generally, the result holds for the gradients and mixed derivative of the heat kernel (instead on the codifferentials and mixed codifferential).
    \item To prove Theorem~\ref{th:mainth}, we need to choose the inverse temperature $\beta$ sufficiently large so that this result holds with the exponent $p = 8$.
    \item Since the Langevin dynamic is reversible, it is equivalent to prove the result for the dynamic or the time-reversed dynamic (and we will only prove it in the first case).
\end{itemize}
\end{remark}

The proof of Proposition~\ref{prop:Lpannealedreg} is divided into three parts. Section~\ref{sectprelimappB} is a preliminary section that introduces additional notation and auxiliary results. Section~\ref{sec:CZsec} contains the analytical core of the argument: exploiting the fact that the elliptic operator $\mathcal{L}_{\mathrm{spat}}^{\varphi\cdot}$ has small ellipticity contrast, we establish accurate estimates on the $L^p$-norm of the gradient of the heat kernel, for some exponent $p \in (1 , \infty)$ that tends to infinity as $\beta \to \infty$. This part of the argument is deterministic and relies on an adaptation of Calderón–Zygmund regularity theory. Finally, Section~\ref{sec:DDannealedregsec} introduces probabilistic elements: combining the regularity results from Section~\ref{sec:CZsec} with the stationarity of the Langevin dynamics—following the approach of Delmotte and Deuschel~\cite{DD05}—we complete the proof of Proposition~\ref{prop:Lpannealedreg}.

\subsection{Preliminaries} \label{sectprelimappB}

\subsubsection{Notation} 
Given an integer $L \in \N$ and $(t , x) \in (0 , \infty) \times \Zd$, we denote by $Q_L$ and $Q_L(t , x)$ the parabolic cylinders
\begin{equation*}
    Q_L := (- L^2 , 0) \times \Lambda_L \hspace{5mm} \mbox{and} \hspace{5mm} Q_L(t , x) = ( t - L^2 , t) \times ( x + \Lambda_L).
\end{equation*} 
We introduce the (discrete) parabolic boundary of $Q_L(t , x)$ according to
$$\partial_{\mathrm{par}} Q_L(t , x) := \left( \left\{ t - L^2 \right\} \times (x + \Lambda_L) \right) \cup \left( (t - L^2 , t) \times \partial (x + \Lambda_L)  \right)$$ 
Given a function $f : Q_L(t , x) \to \R$ and an exponent $p \in [1 , \infty)$, we introduce its average $L^p$-norm and $L^\infty$-norm according to the formulae
\begin{equation*}
    \left\| f \right\|_{\underline{L}^p(Q_L(t , x))}^p := \frac{1}{L^2} \int_{t - L^2}^t \frac{1}{\left| \Lambda_L \right|} \sum_{y \in (x + \Lambda_L)} \left| f(s , y) \right|^p \, ds \hspace{3mm} \mbox{and} \hspace{3mm} \left\| f \right\|_{L^\infty(Q_L(t , x))} := \sup_{(s , y) \in Q_L(t , x)} \left| f(s , y) \right|.
\end{equation*}
We next introduce the notation: for $C_0 \in (1 , \infty)$, $t \in (0 , \infty)$ and $x \in \Zd$, we let
    \begin{equation*}
        \Phi_{C_0} (t , x) := \frac{1}{t_+^{d/2}} \exp \left( - \frac{|x|}{C_0 \sqrt{t_+}} \right).
    \end{equation*}
Let us note that there exists a constant $C < \infty$ depending only on $C_0$ such that, for any $t \in (0 , \infty)$
\begin{equation} \label{ineq:almostprobab}
        \sum_{x \in \Zd} \Phi_{C_0} (t , x) \leq C.
\end{equation}

\subsubsection{Two preliminary results}

In this section, we collect two preliminary results which will be used in the proof of Proposition~\ref{prop:Lpannealedreg}. The first one is an optimal $L^2$-estimate for discrete gradient of the heat kernel.

\begin{proposition}[$L^2$-regularity estimate for the heat kernel] \label{prop:Caccioppoli}
    There exists a constant $C := C(d , \beta) < \infty$ such that for any $(t , x) \in (0 , \infty)$ and any realisation of the Langevin dynamic $(\varphi_t)_{t \geq 0}$,
    \begin{equation*}
        \left\| \nabla P^{\cdot}(\cdot , \cdot , 0) \right\|_{\underline{L}^2(Q_{\sqrt{t}/2}(t , x))} \leq \frac{C}{t_+^{\frac{d}{4} + \frac12}}\exp \left( - \frac{|x|}{C \sqrt{t_+} }\right).
    \end{equation*}
\end{proposition}

\begin{remark}
This estimate is obtained by combining the Caccioppoli inequality (see~\cite[Chapter 5, Section 1]{DW} but the argument is the standard one) and the upper bound on the heat kernel stated in Proposition~\ref{prop.prop4.11chap4HK}.
\end{remark}


The second result is a general statement asserting that if an $L^2$ function can be well-approximated on all scales by a bounded function, then it necessarily lies in some $L^p$-space, with a corresponding quantitative bound on its $L^p$-norm.

\begin{proposition} \label{prop:CalderonZygmundLpestimate}
For each $p \in  (2, \infty)$ and $A \geq 1$, there exists $\delta_0(p, A, d) > 0$
and $C(p, A, d) < \infty$ such that the following holds for every $\delta \in (0, \delta_0]$. Let $f : [0 , \infty) \times \Zd \to \R$ and a constant $K \in (0, \infty)$ be such that, for any $(s , y) \in [0 , \infty) \times \Zd$ and any $r \in \N$ such that $8r^2 \leq s$, there exists a function $f_{(s , y) , r} :  Q_r(s , y) \to \R $ satisfying
\begin{equation*}
     \left\| f - f_{(s , y) , r} \right\|_{\underline{L}^2\left( Q_r(s , y) \right)}  \leq \delta \left\| f \right\|_{\underline{L}^2\left( Q_{2r}(s , y) \right)} + K
\end{equation*}
and 
\begin{equation*}
    \left\|  f_{(s , y) , r} \right\|_{L^\infty \left( Q_r(s , y) \right)} \leq A \left\| f \right\|_{\underline{L}^2\left( Q_{2r}(s , y) \right)}.
\end{equation*}
Then for any $(t , x) \in (0 , \infty) \times \Zd$ and any $R \in \N$ with $8R^2 \leq t$,
\begin{equation*}
    \left\| f \right\|_{\underline{L}^p(Q_{R}(t , x))} \leq C  \left\| f \right\|_{\underline{L}^2(Q_{2R}(t , x))} + CK.
\end{equation*}
\end{proposition}

\begin{remark}
The proof of this result (in the continuous setting and for functions depending only on the spatial variable) can be found in~\cite[Lemma 7.2]{AKM} (by considering the function $g$ there to be the constant function equal to $K$). The extension to the discrete and parabolic setting (considered above) is mostly notational (and omitted here to reduce the technical complexity of this appendix).
\end{remark}

\subsection{Proof of the Calder\'on-Zygmund regularity} \label{sec:CZsec}

In this section, we establish a Calderón–Zygmund-type regularity estimate for the heat kernel $P^{\varphi_\cdot}$. Specifically, we derive an almost optimal bound on its $L^p$-norm for some exponent $p \in (1 , \infty)$, which depends on $\beta$ and tends to infinity as $\beta \to \infty$. At a high level, we rely on the observation that, when $\beta$ is large, the elliptic operator $\mathcal{L}_{\mathrm{spat}}^{\varphi_\cdot}$ has a small ellipticity contrast. This implies that the heat kernel is well-approximated in $L^2$ on every scale scales by a solution to a heat equation with strong regularity properties. This allows us to apply Proposition~\ref{prop:CalderonZygmundLpestimate} and obtain an (almost) sharp estimate on the $L^p$-norm of the heat kernel. We mention that the suboptimal logarithmic correction appears in this step of the proof and is caused by the infinite range of the elliptic operator $\mathcal{L}_{\mathrm{spat}}^{\varphi_\cdot}$.


\begin{proposition}[Calder\'{o}n-Zygmund regularity for the heat kernel] \label{prop:CalderonZygmund}
For any exponent $p \in (1 , \infty),$ there exists an inverse temperature $\beta_1 := \beta_1(p , d) < \infty$ such that for any $\beta \geq \beta_1$, there exists a constant $C := C(d , \beta , p) < \infty$ such that for any $t \in (0, \infty)$, and any realisation of the Langevin dynamic $(\varphi_t)_{t \geq 0}$, one has the inequality
\begin{equation*}
    \int_{t/4}^{t} \sum_{y \in \Zd} \left| \nabla P^{\varphi_\cdot} (s , y , 0 )  \right|^p e^{\frac{|y|}{C \sqrt{t_+}}} \, ds \leq C (\ln t_+)^{\frac{p(d+2)}{2}} t_+^{\frac{d+2}{2}  - \frac{p}{2} - \frac{pd}{2}}.
\end{equation*}
\end{proposition}

\begin{proof}[Proof of Proposition~\ref{prop:CalderonZygmund}]
We fix a realisation of the Langevin dynamic $(\varphi_t)_{t \geq 0}$ (N.B. this argument is deterministic and works for any realisation of the dynamic) and split the proof into several steps:
\begin{itemize}
\item \textbf{Step 1.} We use that the operator $\mathcal{L}^{\varphi}_{\mathrm{spat}}$ is a perturbation of the Laplacian to prove that the heat kernel $P^{\varphi_\cdot}$ is well-approximated by a solution $\bar u$ of the heat equation:
\begin{equation} \label{eq:caloricheateq}
\partial_t \bar u - \frac{1}{2\beta} \Delta \bar u = 0.
\end{equation}
More specifically, we prove the following result:
for each $\delta > 0$, there exists an inverse temperature $\beta_1(d , \delta)$ such that for each $\beta \geq \beta_1$, each $r \in \N$ and each $(t , x) \in (0 , \infty) \times \Zd$ with $8r^2 \leq t$, there exists a function $\bar u$ which solves the heat equation~\eqref{eq:caloricheateq} in the parabolic cylinder $Q_{2r}(t , x)$ and satisfies
\begin{equation} \label{ineq:wellapproxcalderon}
    \left\| \nabla P^{\varphi_\cdot} - \nabla \bar u \right\|_{\underline{L}^2 (Q_r(t , x))} \leq \delta \left\| \nabla P^{\varphi_\cdot} \right\|_{\underline{L}^2(Q_{2r}(t , x)) } + e^{- c \left( \ln \beta \right) r} \exp \left( - \frac{|x|}{C \sqrt{t_+}}\right)
\end{equation}
together with the estimate
\begin{equation} \label{eq:Sh95616}
   \left\| \nabla \bar u \right\|_{L^\infty(Q_r(t , x))} \leq C \left\| \nabla P^{\varphi_\cdot} \right\|_{\underline{L}^2(Q_{2r}(t , x))}.
\end{equation}
\item \textbf{Step 2.} We apply Proposition~\ref{prop:CalderonZygmundLpestimate} and the $L^2$-regularity estimate for the heat kernel (Proposition~\ref{prop:Caccioppoli}) to deduce that: for any exponent $p \geq 1$, there exists an inverse temperature $\beta_1 := \beta_1(p , d) < \infty$ such that for any $\beta \geq \beta_1$, any $t \in (0, \infty)$,
\begin{equation} \label{eq:mainresulstep2CZ}
    \left\| \nabla P^{\varphi_\cdot} (\cdot , \cdot , 0)  \right\|_{\underline{L}^p(Q_{\sqrt{t}/4} (t , x))} \leq  \frac{C(\ln t_+)^{\frac{d+2}{2}}}{t_+^{\frac{1}{2} + \frac{d}{2}}}  \exp \left( - \frac{|x|}{C \sqrt{t_+}}\right).
\end{equation}
\item \textbf{Step 3.} We post-process the result of Step 2 to obtain the estimate: there exists a constant $C_0 := C_0(d , \beta,p) < \infty$ such that
\begin{equation*}
    \int_{t/4}^{t} \sum_{y \in \Zd} \left| \nabla P^{\varphi_\cdot} (s , y , 0 )  \right|^p e^{\frac{|y|}{C_0 \sqrt{t_+}}} \, ds \leq C_0 (\ln t_+)^{\frac{p(d+2)}{2}} t_+^{\frac{d+2}{2}  - \frac{p}{2}- \frac{pd}{2}}.
\end{equation*}
\end{itemize}

\textit{Step 1.} Let us fix $(t , x) \in (0 , \infty) \times \Zd$ and $r \in \N$ such that $8r^2 \leq t$. For any index $i , j \in \left\{1 , \ldots, {d \choose 2} \right\}$, we then let $\bar u_{i j} : Q_{2r}(t , x) \to \R$ be the solution of the parabolic equation
\begin{equation} \label{eq:defbaruheat}
    \left\{ \begin{aligned}
    \partial_t \bar u_{i j} - \frac{1}{2\beta}\Delta \bar u_{i j} & = 0 &~~\mbox{in} ~~& Q_{2r}(t , x), \\
    \bar u_{i j} & = P_{i j}^{\varphi_\cdot} \left( \cdot , \cdot , 0\right) &~~\mbox{in} ~~&  \partial_{\mathrm{par}} Q_{2r}(t , x),
    \end{aligned} \right.
\end{equation}
and set $u := \left( u_{ij} \right)_{1 \leq i , j \leq {d \choose 2}}$. An energy estimate for the solutions of the heat equation implies the upper bound
\begin{equation*}
    \left\| \nabla \bar u \right\|_{L^2 \left( Q_{2r}(t , x) \right)} \leq C \left\| \nabla P^{\varphi_\cdot} (\cdot , \cdot , 0) \right\|_{L^2 \left( Q_{2r}(t , x) \right)}.
\end{equation*}
Additionally, as a solution of the heat equation, the function $\bar u $ possesses good regularity properties, in particular we have the $L^\infty$-$L^2$ estimate on the gradient of $\bar u$
\begin{equation*}
    \left\| \nabla \bar u \right\|_{L^\infty \left( Q_{r}(t , x) \right)} \leq C \left\| \nabla \bar u \right\|_{\underline{L}^2 \left( Q_{2r}(t , x) \right)} \leq C \left\| \nabla P^{\varphi_\cdot} (\cdot , \cdot , 0) \right\|_{\underline{L}^2 \left( Q_{2r}(t , x) \right)}.
\end{equation*}
We then note that the function $w := P - u$ solves the parabolic systems of equations
\begin{equation*}
    \left\{ \begin{aligned}
    \partial_t w - \frac{1}{2\beta} \Delta w & = \frac{1}{2\beta} \Delta P^{\varphi_\cdot}(\cdot , \cdot , 0) - \mathcal{L}^{\varphi_\cdot}_{\mathrm{spat}} P^{\varphi_\cdot}(\cdot , \cdot , 0) &~~\mbox{in} ~~& Q_{2r}(t , x), \\
    w & = 0  &~~\mbox{in} ~~&  \partial_{\mathrm{par}} Q_{2r}(t , x).
    \end{aligned} \right.
\end{equation*}
We may then use an energy estimate for the heat equation and use that the operator
$$
\mathcal{L}^{\varphi_\cdot}_{\mathrm{spat}} P^{\varphi_\cdot}(\cdot , \cdot , 0) - \frac{1}{2\beta} \Delta P^{\varphi_\cdot}(\cdot , \cdot , 0) =  \sum_{n \geq 1} \frac{1}{2\beta} \frac{1}{\beta^{n/2}} \Delta^{n+1} P^{\varphi_\cdot} + \sum_{q \in \mathcal{Q}} \mathbf{a}_q(\varphi_\cdot) (P^{\varphi_\cdot} (\cdot , \cdot , 0) , q) q
$$
is a small perturbation of $\frac{1}{2\beta} \Delta$ (since $\beta \gg 1$) to conclude that (N.B. in the following identity we extend the function $w$ to $(t-4r^2 , t) \times \Zd$ by setting $w(s , y) = 0$ for $y \in \Zd \setminus (x + \Lambda_{2r})$)
\begin{multline*}
    \sum_{y \in \Zd} w(t , y)^2 + \frac{1}{2\beta} \left\| \nabla w \right\|_{L^2(Q_{2r}(t , x))}^2 \\ 
    = \int_{t - 4r^2}^t   \sum_{n \geq 1} \frac{1}{2\beta} \frac{1}{\beta^{n/2}} ( \Delta^{n+1} P^{\varphi_\cdot}(s , \cdot) , w(s , \cdot)) + \sum_{q \in \mathcal{Q}} \mathbf{a}_q(\varphi_s) (P^{\varphi_\cdot}(s , \cdot) , q) (w(s , \cdot) , q) \, ds.
\end{multline*}
By performing integrations by parts (and using the identity~\eqref{identity:dandd*}), we see that the right-hand side is a linear function of the gradient of $w$. By applying the Cauchy-Schwarz inequality together with a computation similar to the one performed in the proof of Lemma~\ref{lemma.lemma2.5}, we obtain the inequality
\begin{equation*}
     \frac{1}{2\beta} \left\| \nabla w \right\|_{L^2(Q_{2r}(t , x))}^2 \leq \frac{C}{\beta \sqrt{\beta }} \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{L^2(Q_{2r}(t , x))}^2 + \frac{1}{\beta} \int_{t - 4r^2}^t \sum_{y \in \Zd \setminus (x + \Lambda_{2r})} e^{-c \left( \ln \beta \right) |x - y|} \left| \nabla P^{\varphi_\cdot}(s , y , 0) \right|^2 \, ds.
\end{equation*}
We then simplify the second term on the right-hand side: by using the definition of the discrete gradient (which implies the inequality $\left| \nabla P^{\varphi_\cdot}(s , y , 0) \right| \leq \sum_{y' \sim y} \left| P^{\varphi_\cdot}(s , y' , 0) \right| + \left| P^{\varphi_\cdot}(s , y , 0) \right|$) together with the upper bound on the heat kernel stated in Proposition~\ref{prop.prop4.11chap4HK}, we deduce that
\begin{align*}
    \int_{t - 4r^2}^t \sum_{y \in \Zd \setminus (x + \Lambda_{2r})} e^{-c \left( \ln \beta \right) |x - y|} \left| \nabla P^{\varphi_\cdot}(s , y , 0) \right|^2 \, ds & \leq C  \int_{t - 4r^2}^t \sum_{y \in \Zd \setminus (x + \Lambda_{2r})} e^{-c \left( \ln \beta \right) |x - y|} \left| P^{\varphi_\cdot}(s , y , 0) \right|^2 \, ds \\
    & \leq  C \int_{t - 4r^2}^t \sum_{y \in \Zd \setminus (x + \Lambda_{2r})} e^{-c \left( \ln \beta \right) |x - y|}  s_+^{- d} \exp \left( - \frac{|y|}{C \sqrt{s_+}} \right) \, ds.
\end{align*}
Using the assumption $8r^2 \leq t$, we have $s \geq t/2$ for any time $s$ in the interval of integration $(t - 4r^2 , t)$. Combining this observation with the (trivial) upper bound $s_+ \geq 1$, we thus deduce that
\begin{align*}
    \int_{t - 4r^2}^t \sum_{y \in \Zd \setminus (x + \Lambda_{2r})} e^{-c \left( \ln \beta \right) |x - y|} \left| \nabla P^{\varphi_\cdot}(s , y , 0) \right|^2 \, ds & \leq C \exp \left( - \frac{|x|}{C \sqrt{t_+}} \right)  \underset{\leq e^{- c (\ln \beta) r}}{\underbrace{\left( \int_{t - 4r^2}^t \sum_{y \in \Zd \setminus (x + \Lambda_{2r})} e^{-c \left( \ln \beta \right) |x - y|} \right)}} \\
    & \leq C  e^{-c (\ln \beta) r} \exp \left( - \frac{|x|}{C \sqrt{t_+}} \right).
\end{align*}
A combination of the three previous inequalities implies that
\begin{equation*}
    \left\| \nabla w \right\|_{L^2(Q_{2r}(t , x))}^2 \leq \frac{C}{\sqrt{\beta }} \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{L^2(Q_{2r}(t , x))}^2 + C  e^{-c (\ln \beta) r} \exp \left( - \frac{|x|}{C \sqrt{t_+}} \right).
\end{equation*}
For any $\delta \in (0 , 1)$, we may thus select the inverse temperature $\beta \in (1 , \infty)$ sufficiently large so that $C /\sqrt{\beta} \leq \delta^2$. This implies
\begin{equation*}
    \left\| \nabla w \right\|_{L^2(Q_{2r}(t , x))}^2 \leq \delta^2 \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{L^2(Q_{2r}(t , x))}^2 + C e^{-c (\ln \beta) r}  \exp \left( - \frac{|x|}{C \sqrt{t_+}} \right).
\end{equation*}
We then divide by the volume of the parabolic cylinder $Q_{2r}(t , x)$ and take the square-root on both sides of this inequality (and use $\sqrt{a + b} \leq \sqrt{a} + \sqrt{b}$ for $a , b \geq 0$) to complete the proof of Step 1.

\medskip

\textit{Step 2.} Let us fix an exponent $p \in (1 , \infty)$, let $\delta_0$ be the parameter associated with the exponent $p$ given by Proposition~\ref{prop:Lpannealedreg}. We then select an inverse temperature $\beta$ sufficiently large so that the inequality~\eqref{ineq:wellapproxcalderon} holds with $\delta = \delta_0$. In order to treat the error term coming from the infinite range of the elliptic operator (i.e., the second term on the right-hand side of~\eqref{ineq:wellapproxcalderon}), we introduce a coarsening of the heat kernel on a scale of size $(\ln t_+)$. To be more precise, we fix a time $t \in (1 , \infty)$, a vertex $x \in \Zd$ and partition the parabolic cylinder $Q_{\sqrt{t}/2} (t , x)$ into cylinders of size (approximately) $(\ln \, t_+)$ and denote this partition by $\mathcal{P}$, e.g.,
\begin{equation*}
    \mathcal{P} := \left\{ Q_{ \lfloor \ln t_+ \rfloor}(s' , y') \hspace{1mm} : \hspace{1mm} (s' , y') \in \left( \lfloor \ln t_+ \rfloor^2 \N \times \lfloor \ln t_+ \rfloor \Zd \right) \cap Q_{\sqrt{t}/2} (t , x) \right\}.
\end{equation*}
We then let $f$ be the real-valued function defined on $Q_{\sqrt{t}/2} (t , x)$ which is constant equal to the average $L^2$ norm of the heat kernel $P^{\varphi_\cdot}$ on the cylinders of $\mathcal{P}$, i.e.,
\begin{equation*}
    f(s, y) = \left\| \nabla P^{\varphi_\cdot} (\cdot , \cdot , 0)\right\|_{\underline{L}^2\left( Q\right)} \hspace{3mm} \mbox{for} \hspace{3mm} (s , y) \in Q \hspace{2mm} \mbox{with} \hspace{2mm} Q \in \mathcal{P}.
\end{equation*}
We next show that the function $f$ satisfies the assumptions of Proposition~\ref{prop:CalderonZygmundLpestimate}. Specifically, we fix $(s , y) \in [0 , \infty) \times \Zd$, $r \in \N$ such that $8r^2 \leq s$, set
\begin{equation} \label{eq:defofK}
    K:= e^{-c (\ln \beta) (\ln t_+)} \exp \left( - \frac{|y|}{C \sqrt{t_+}} \right).
\end{equation}
Let us note that, when $\beta$ is large, the first term in the definition of $K$ decays like a polynomial in $t$ with a large exponent and is thus smaller than all the other quantities we wish to estimate. We then distinguish two cases.

\medskip

 \textit{\underline{Case 1:}} For $r \geq \ln t_+$, then we set 
    $$f_{(s , y) , r}(s', y') := \left\| \nabla \bar u \right\|_{\underline{L}^2 \left(Q_{\lfloor \ln t_+ \rfloor}(s'' , y'')\right)} \hspace{3mm} \mbox{for} \hspace{3mm}  (s' , y') \in Q_{\lfloor \ln t_+ \rfloor}(s'' , y'') \in \mathcal{P},$$
    where $\bar u$ is the function introduced in Step 1 (see~\eqref{eq:defbaruheat}). By~\eqref{ineq:wellapproxcalderon} (and the triangle inequality), we have the inequality
    \begin{align*}
        \left\| f - f_{(s , y) , r} \right\|_{\underline{L}^2\left( Q_r(s , y) \right)}  \leq \delta \left\| f \right\|_{\underline{L}^2\left( Q_{2r}(s , y) \right)} + C e^{-c (\ln \beta) r}  \exp \left( - \frac{|y|}{C \sqrt{t_+}} \right)  \leq \delta \left\| f \right\|_{\underline{L}^2\left( Q_{2r}(s , y) \right)} + K,
    \end{align*}
    and by~\eqref{eq:Sh95616}, we have the inequality
    \begin{equation*}
        \left\|  f_{(s , y) , r} \right\|_{L^\infty \left( Q_r(s , y) \right)} \leq C \left\| f \right\|_{\underline{L}^2\left( Q_{2r}(s , y) \right)}.
    \end{equation*}
    The assumptions of Proposition~\ref{prop:CalderonZygmundLpestimate} is thus verified in that case.

    \smallskip

\textit{\underline{Case 2:}} For $r \leq \ln t_+$, we note that, since the functions $f$ is constant on the parabolic cylinders of the partition $\mathcal{P}$ and we are considering here scales which are smaller than the one of the partition $\mathcal{P}$, the function $f$ is (by construction) regular on these small scales and satisfies
    \begin{equation*}
        \left\|  f \right\|_{L^\infty \left( Q_r(s , y) \right)} \leq C \left\| f \right\|_{\underline{L}^2\left( Q_{2r}(s , y) \right)}.
    \end{equation*}
We may thus set $ f_{(s , y) , r} := f$ to verify the assumptions of Proposition~\ref{prop:CalderonZygmundLpestimate}.
\medskip
We may thus apply Proposition~\ref{prop:CalderonZygmundLpestimate} (with $R = \sqrt{t} / 4$) to deduce that, for any exponent $p \in (1 , \infty)$ if the inverse temperature $\beta$ is chosen sufficiently large,
\begin{equation} \label{ineq:SH1201}
    \left\| f \right\|_{\underline{L}^p(Q_{\sqrt{t}/4}(t , x))} \leq C  \left\| f \right\|_{\underline{L}^2(Q_{\sqrt{t}/2}(t , x))} + CK.
\end{equation}
We finally remove the coarsening on both sides of this inequality. For the left-hand side, we have by the definition of the function $f$ and by Proposition~\ref{prop:Caccioppoli}
\begin{equation} \label{eq:ineqB8Sh}
    \left\| f \right\|_{\underline{L}^2(Q_{\sqrt{t}/2}(t , x))}  \leq \left\| \nabla P^{\varphi_\cdot} \right\|_{\underline{L}^2(Q_{\sqrt{t}/2}(t , x))} \leq \frac{C}{t_+^{\frac{d}{2} + \frac{1}{2}}} \exp \left( - \frac{|x|}{C \sqrt{t_+} }\right).
\end{equation}
For the left-hand side of the inequality~\eqref{ineq:SH1201}, we first note that, by using the upper bound~\eqref{eq:PisLipschitz} on the derivative in time of the heat kernel and the Sobolev injection $H^1 \hookrightarrow L^\infty$ in dimension $1$, we have, for any $(s , y) \in Q_{\sqrt{t}/4}(t , x)$,
\begin{align*}
    \left| \nabla P^{\varphi_\cdot}(s , y , 0) \right|^2 & \leq C \int_{s-1}^s \left| \nabla P^{\varphi_\cdot}(s' , y, 0) \right|^2 \, ds' + C \int_{s-1}^s \sum_{z \in \Zd} e^{- c (\ln \beta) |z - y|} \left| \nabla P^{\varphi_\cdot}(s' , z, 0) \right|^2 \, ds' \\
    & \leq C  \int_{s-1}^s \sum_{z \in \Zd} e^{- c (\ln \beta) |z - y|} \left| \nabla P^{\varphi_\cdot}(s' , z, 0) \right|^2 \, ds'.
\end{align*}
We next split the right-hand side into two terms which can be estimated separately (and recall that the constant $K$ was introduced in~\eqref{eq:defofK})
\begin{align*}
    \left| \nabla P^{\varphi_\cdot}(s , y , 0) \right|^2 & \leq C  \int_{s-1}^s \sum_{z \in y + \Lambda_{\lfloor \ln t_+ \rfloor}} \underset{\leq 1}{\underbrace{e^{- c (\ln \beta) |z - y|}}} \left| \nabla P^{\varphi_\cdot}(s' , z, 0) \right|^2 \, ds' \\
    & \qquad + C \underset{\leq C K}{\underbrace{\int_{s-1}^s \sum_{z \in \Zd \setminus (y + \Lambda_{\lfloor \ln t_+ \rfloor})} e^{- c (\ln \beta) |z - y|} \left| \nabla P^{\varphi_\cdot}(s' , z, 0) \right|^2 \, ds'}} \\
    & \leq C  \int_{s-1}^s \sum_{z \in y + \Lambda_{\lfloor \ln t_+ \rfloor}}  \left| \nabla P^{\varphi_\cdot}(s' , z, 0) \right|^2 \, ds' + C K.
\end{align*}
We then increase the interval of integration to write
\begin{align*}
    \left| \nabla P^{\varphi_\cdot}(s , y , 0) \right|^2 & \leq C \int_{s-\lfloor \ln t_+ \rfloor^2}^s \sum_{z \in y + \Lambda_{\lfloor \ln t_+ \rfloor}}  \left| \nabla P^{\varphi_\cdot}(s' , z, 0) \right|^2 \, ds' + C K \\
    & = C \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot, 0)  \right\|_{L^2(Q_{\lfloor \ln t_+ \rfloor}(s , y))}^2 + C K\\
    & \leq C \left( \ln t_+ \right)^{d+2} \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{\underline{L}^2(Q_{\lfloor \ln t_+ \rfloor}(s , y))}^2 + C K.
\end{align*}
From this inequality, we may deduce that
\begin{equation*}
    \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{\underline{L}^p(Q_{\sqrt{t}/4}(t , x))} \leq C (\ln t_+)^{\frac{d+2}{2}} \left\| f \right\|_{\underline{L}^p(Q_{\sqrt{t}/4}(t , x))}+ C K .
\end{equation*}
Combining the previous inequality with~\eqref{ineq:SH1201} and~\eqref{eq:ineqB8Sh}, we deduce that
\begin{equation*}
    \left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{\underline{L}^p(Q_{\sqrt{t}/4}(t , x))} \leq \frac{C(\ln t_+)^{\frac{d+2}{2}}}{t_+^{\frac{1}{2} + \frac{d}{2}}} \exp \left( - \frac{|x|}{C \sqrt{t_+} }\right) + CK.
\end{equation*}
We finally note that, if the inverse temperature $\beta$ is chosen sufficiently large, then the constant $K$ is smaller than the first term on the left-hand side, and we have obtained
\begin{equation*}
\left\| \nabla P^{\varphi_\cdot}(\cdot , \cdot , 0) \right\|_{\underline{L}^p(Q_{\sqrt{t}/4}(t , x))} \leq \frac{C(\ln t_+)^{\frac{d+2}{2}}}{t_+^{\frac{1}{2} + \frac{d}{2}}} \exp \left( - \frac{|x|}{C \sqrt{t_+} }\right).
\end{equation*}


\medskip


\textit{Step 3.} In this step, we post-process the result of Step 2. Specifically, we set $C_1 := 2C$ where $C$ is the constant on the right-hand side of~\eqref{eq:mainresulstep2CZ}. We then partition the space $(t/4 , t) \times \Zd$ by setting (N.B. we assume below for simplicity that $\sqrt{t}/4$ is an integer)
\begin{equation*}
    \mathcal{Z} :=\left( \frac{t}{16}  \N \cap \left[ \frac t4 , t \right] \right) \times \frac{\sqrt{t}}{4}  \Zd  ~~\mbox{and}~~ \mathcal{P}_1 := \left\{ Q_{\sqrt{t}/4} (s , y) \, : \, (s , y) \in \mathcal{Z} \right\}.
\end{equation*}
We then estimate
\begin{align*}
     \int_{t/4}^{t} \sum_{y \in \Zd} \left| \nabla P^{\varphi_\cdot} (s , y , 0 )  \right|^p e^{\frac{|y|}{C_1 \sqrt{t_+}}} \, ds & \leq C \sum_{(s , y) \in \mathcal{Z}} \left\| \nabla P^{\varphi_\cdot} (\cdot , \cdot , 0 )  \right\|_{L^p \left( Q_{\sqrt{t}/4} (s , y) \right)}^p e^{\frac{|y|}{C_1 \sqrt{t_+}}} \\
     & \leq C  t_+^{\frac{d+2}{2}} \sum_{(s , y) \in  \mathcal{Z}} \left\| \nabla P^{\varphi_\cdot} (\cdot , \cdot , 0 )  \right\|_{\underline{L}^p \left( Q_{\sqrt{t}/4} (s , y) \right)}^p e^{\frac{|y|}{C_1 \sqrt{t_+}}} \\
     & \leq  C  t_+^{\frac{d+2}{2}} \sum_{(s , y) \in  \mathcal{Z}}\frac{(\ln t_+)^{\frac{p(d+2)}{2}}}{t_+^{\frac{p}{2} + \frac{pd}{2}}}  \exp \left( - \frac{|y|}{C \sqrt{t_+}} + \frac{|y|}{C_1 \sqrt{t_+}} \right).
\end{align*}
Using the definition $C_1 := 2C$, we eventually obtain
\begin{align*}
    \int_{t/4}^{t} \sum_{y \in \Zd} \left| \nabla P^{\varphi_\cdot} (s , y , 0 )  \right|^p e^{\frac{|x|}{C_1 \sqrt{t_+}}} \, ds & \leq  C  t_+^{\frac{d+2}{2}} \frac{(\ln t_+)^{\frac{p(d+2)}{2}}}{t_+^{\frac{p}{2} + \frac{pd}{2}}}  \underset{\leq C}{\underbrace{\sum_{(s , y) \in \mathcal{Z}} \exp \left( - \frac{|x|}{2C \sqrt{t_+}}  \right)}} \\
    & \leq C  (\ln t_+)^{\frac{p(d+2)}{2}} t_+^{\frac{d+2}{2}  - \frac{p}{2} - \frac{pd}{2}}.
\end{align*}
\end{proof}



\subsection{Proof of the $L^p$-annealed regularity} \label{sec:DDannealedregsec}

We complete in this section the proof of Proposition~\ref{prop:Lpannealedreg} by combining the Calder\'{o}n-Zygmund regularity estimate proved in the previous section with the techniques of Delmotte and Deuschel~\cite{DD05} (which rely on the space and time stationarity of the Langevin dynamic).

\begin{proof}[Proof of Proposition~\ref{prop:Lpannealedreg}]
We first prove the result with the mixed codifferential (which is the most challenging case) and then point out how the argument can be adapted to obtain the proof with only one codifferential.

Given $s \geq 0$ and a realisation $(\varphi_t)_{t \geq 0}$ of the Langevin dynamic, let us denote by
        \begin{equation*}
        \left\{ \begin{aligned}
        \partial_t P^{\varphi_\cdot} (\cdot , \cdot ;s ,  y) + \mathcal{L}_{\mathrm{spat}}^{\varphi_\cdot}  P^{\varphi_\cdot}(\cdot , \cdot ; s , y) & =0 ~\mbox{in}~ (0 , \infty) \times \Zd , \\
        P^{\varphi_\cdot} \left(s,\cdot ; s ,  y \right) & = \delta_{y} ~\mbox{in}~ \Zd.
        \end{aligned}
        \right.
    \end{equation*}
From this definition, we may write the identity, for any $t , s \in (0 , \infty)$ with $s \leq t$,
\begin{equation*}
     \di^*_1 \di^*_2 P^{\varphi_\cdot} (t , x ;  0) = \sum_{y \in \Zd} \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \di^*_2 P^{\varphi_\cdot} (s , y ;  0).
\end{equation*}
We let $C_1 <\infty$ be a large constant which is allowed to depend on $d , \beta$ and $p$ and whose specific value will be selected below. From this identity, the Cauchy-Schwarz inequality and the inequality $ab \leq a^2 + b^2$, we deduce that, for any $s \in (0, t)$,
\begin{align} \label{eq:convpropheatkernel}
    \left| \di^*_1 \di^*_2 P^{\varphi_\cdot} (t , x ;  0) \right| e^{|x|/\left(C_1 \sqrt{t_+}\right)} & \leq \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right| \left| \di^*_2 P^{\varphi_\cdot} (s , y ;  0) \right| e^{|x|/\left( C_1 \sqrt{t_+}\right)}
    \\
    & \leq \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|e^{|x-y|/\left(C_1 \sqrt{t_+}\right)}  \left| \di^*_2 P^{\varphi_\cdot} (s , y ;  0) \right| e^{|y|/\left(C_1 \sqrt{t_+}\right)} \notag \\
    & \leq \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^2 e^{2|x-y|/\left(C_1 \sqrt{t_+}\right)} + \sum_{y \in \Zd} \left| \di^*_2 P^{\varphi_\cdot} (s , y ;  0) \right|^2 e^{2|y|/\left(C_1 \sqrt{t_+}\right)}. \notag
\end{align}
We next use the Jensen inequality (and noting that a constant $C$ appears on the second line because the sum on the left-hand side of~\eqref{ineq:almostprobab} is not necessarily equal to $1$) to deduce that
\begin{align*} 
   \left(  \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^2 e^{2|x-y|/\left(C_1 \sqrt{t_+}\right)} \right)^p & =   \left(  \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^2 e^{2|x-y|/\left(C_1 \sqrt{t_+}\right)}  \Phi_{C_1}(t , x - y)^{-1} \Phi_{C_1}(t , x- y) \right)^p \\
   & \leq C \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^{2p} e^{2p|x-y|/\left(C_1 \sqrt{t_+}\right)} \Phi_{C_1}(t , x - y)^{-p} \Phi_{C_1}(t , x- y) \notag \\
   & \leq C\sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^{2p} \Phi_{C_2}(t , x- y)^{1-p}, \notag
\end{align*}
where we set $C_2 := C_1 / (1 + 2p/(p-1))$ in order to absorb the exponential factor. In the rest of the proof, we denote by $\E$ the expectation with respect to the stationary Langevin dynamic, i.e., $\E \left[ \cdot \right] := \langle \E_\varphi \left[ \cdot \right]\rangle_{\mu_\beta}$. Taking the expectation on the right-hand side and using the space and time stationarity of the dynamic, we deduce that
\begin{equation*}
    \E \left[ \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^{2p} \right] =   \E \left[ \left| \di^*_1 P^{\varphi_\cdot} (t - s , x - y ; 0, 0) \right|^{2p}  \right] .
\end{equation*}
By combining the two previous inequalities, we deduce that
\begin{align} \label{eq:111612}
    \E \left[ \left(  \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^2 e^{2|x-y|/\left(C_1 \sqrt{t_+}\right)} \right)^p \right] & \leq C \sum_{y \in \Zd} \E \left[ \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^{2p} \right] \Phi_{C_2}(t , y)^{1-p} \\
    &  \leq C \sum_{y \in \Zd} \E \left[ \left| \di^*_1 P^{\varphi_\cdot} (t - s , x - y ; 0, 0) \right|^{2p} \right] \Phi_{C_2}(t , x - y)^{1-p} \notag \\
    & = C \sum_{y \in \Zd} \E \left[ \left| \di^*_1 P^{\varphi_\cdot} (t - s , y ; 0) \right|^{2p} \right] \Phi_{C_2}(t , y)^{1-p} \notag \\
    & =C \E \left[ \sum_{y \in \Zd}  \left| \di^*_1 P^{\varphi_\cdot} (t - s , y ; 0) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \right]. \notag
\end{align}
A similar computation shows that
\begin{equation*} 
    \E \left[ \left( \sum_{y \in \Zd} \left| \di^*_2 P^{\varphi_\cdot} (s , y ;  0) \right|^2 e^{2|y|/\left(C_1 \sqrt{t_+}\right)} \right)^p \right] \leq C \E \left[  \sum_{y \in \Zd} \left| \di^*_2 P^{\varphi_\cdot} (s , 0 ; y) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \right].
\end{equation*}
We then use Remark~\ref{rem:reversinghtetime} together with the time reversibility of the Langevin dynamic to deduce that, for any $y \in \Zd$,
\begin{equation*}
    \E \left[ \left| \di^*_2 P^{\varphi_\cdot} (s , 0 ; y) \right|^{2p} \right] = \E \left[  \left| \di^*_1 P^{\varphi_\cdot} (s , y ; 0) \right|^{2p} \right].
\end{equation*}
Consequently
\begin{equation} \label{eq:111712}
    \E \left[ \left( \sum_{y \in \Zd} \left| \di^*_2 P^{\varphi_\cdot} (s , y ;  0) \right|^2 e^{2|y|/\left(C_1 \sqrt{t_+}\right)} \right)^p \right] \leq C \E \left[  \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (s , y ; 0) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \right].
\end{equation}
Combining the identity~\eqref{eq:convpropheatkernel} with the inequalities~\eqref{eq:111612} and~\eqref{eq:111712}, we deduce that, for any $s \in (0 , t)$,
\begin{multline*}
    \E \left[ \left| \di^*_1 \di^*_2 P^{\varphi_\cdot} (t , x ;  0) \right|  \right] e^{|x|/\left(C_1 \sqrt{t_+}\right)} \\
    \leq C \E \left[ \sum_{y \in \Zd}  \left| \di^*_1 P^{\varphi_\cdot} (t - s , y ; 0) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \right] +  C \E \left[ \sum_{y \in \Zd}  \left| \di^*_1 P^{\varphi_\cdot} (s , y ; 0) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \right].
\end{multline*}
Since the time $s \in (0,t)$ is a free parameter, we may integrate over $s \in \left( \frac{t}{4}, \frac{3t}{4} \right)$ to deduce that
\begin{equation*}
    \E \left[ \left| \di^*_1 \di^*_2 P^{\varphi_\cdot} (t , x ;  0) \right|^p \right] e^{|x|/\left(C_1 \sqrt{t_+}\right)} \leq C \E \left[ t^{-1}\int_{t/4}^{3t/4} \sum_{y \in \Zd}  \left| \di^*_1 P^{\varphi_\cdot} (s , y ; 0) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \, ds \right].
\end{equation*}
Selecting the inverse temperature $\beta$ sufficiently large so that the Calder\'{o}n-Zygmund regularity (Proposition~\ref{prop:CalderonZygmund}) holds with the exponent $2p$ (and selecting the constant $C_1$, and thus $C_2$, sufficiently large depending on $d , \beta, p$), we deduce that
\begin{align*}
     \E \left[ t^{-1} \int_{t/4}^{3t/4} \sum_{y \in \Zd}  \left| \di^*_1 P^{\varphi_\cdot} (s , y ; 0) \right|^{2p} \Phi_{C_2}(t , y)^{1-p} \, ds \right] & = \E \left[ t^{-1 - \frac{(1-p)d}{2}} \int_{t/4}^{3t/4} \sum_{y \in \Zd}  \left| \di^*_1 P^{\varphi_\cdot} (s , y ; 0) \right|^{2p}  e^{\frac{(p-1)|y|}{C_2 \sqrt{t_+}}} \, ds \right] \\
     & \leq C \E \left[ t^{-1 -\frac{(1-p)d}{2}} \int_{t/4}^{3t/4} \sum_{y \in \Zd}  \left| \nabla P^{\varphi_\cdot} (s , y ; 0) \right|^{2p}  e^{\frac{(p-1)|y|}{C_2 \sqrt{t_+}}} \, ds \right] \\
     & \leq  \frac{C (\ln t_+)^{p(d+2)}}{t^{p(1 + \frac{d}{2})}}
\end{align*}
(N.B. in the second inequality, we used the first item of Remark~\ref{rem:remark25} to deduce that the norm of the codifferential is smaller than the norm of the gradient). Combining the two previous inequalities, we obtain
\begin{equation*}
    \left\| \di^*_1 \di^*_2 P^{\varphi_\cdot} (t , x ;  0)  \right\|_{L^p (\Omega \, ; \, \R^{d \times d})}^p =  \E \left[ \left| \di^*_1 \di^*_2 P^{\varphi_\cdot} (t , x ;  0) \right|^p \right] \leq  \frac{C (\ln t_+)^{p(d+2)}}{t^{p(1 + \frac{d}{2})}} \exp \left( - \frac{|x|}{C_1 \sqrt{t_+}} \right)
\end{equation*}
and thus completes the proof of Proposition~\ref{prop:Lpannealedreg} in the case of the mixed codifferential of the heat kernel.

In the case where there is only one codifferential (we will only treat the case when the codifferential is applied to the first variable), we start similarly by writing the identity, for any $t , s \in (0 , \infty)$ with $s \leq t$,
\begin{equation*}
     \di^*_1 P^{\varphi_\cdot} (t , x ;  0) = \sum_{y \in \Zd} \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) P^{\varphi_\cdot} (s , y ;  0).
\end{equation*}
We then deduce that, for any $s \in (0, t)$,
\begin{align} \label{eq:convpropheatkernel}
    \left| \di^*_1 P^{\varphi_\cdot} (t , x ;  0) \right| e^{|x|/\left(C_1 \sqrt{t_+}\right)} & \leq \sum_{y \in \Zd} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|e^{|x-y|/\left(C_1 \sqrt{t_+}\right)}  \left| P^{\varphi_\cdot} (s , y ;  0) \right| e^{|y|/\left(C_1 \sqrt{t_+}\right)} \notag \\
    & \leq \sum_{y \in \Zd} \sqrt{t_+} \left| \di^*_1 P^{\varphi_\cdot} (t , x ; s, y) \right|^2 e^{2|x-y|/\left(C_1 \sqrt{t_+}\right)} + \sum_{y \in \Zd} \frac{1}{\sqrt{t_+}} \left| P^{\varphi_\cdot} (s , y ;  0) \right|^2 e^{2|y|/\left(C_1 \sqrt{t_+}\right)}. \notag
\end{align}
The first term on the right-hand side can be treated using the same argument as in the case of the mixed codifferential, and the second term can be estimated using Proposition~\ref{prop.prop4.11chap4HK} (which holds for any realisation of the Langevin dynamic).
\end{proof}

\section{Sums on the lattice} \label{App.sumonlattice}

In this appendix, we provide upper bounds for sum of polynomially decaying functions on the lattice which are frequently used in the proofs above.


\begin{proposition} \label{prop:appCdiscretesum}
    For any exponents $\alpha, \gamma, a, c \in [0, \infty)$ with $\alpha + \delta > d$, there exists a constant $C := C(d, \alpha, \gamma, a, b) < \infty$, such that, for any $x \in \Zd$,
    \begin{equation} \label{eq:truineqB1}
\sum_{y \in \Zd} \frac{( \ln |y-x|_+ )^{a}}{|y - x|_+^{\alpha}}  \frac{( \ln |y|_+ )^{c}}{|y|_+^{\gamma}}
\le
\left\{ \begin{aligned}
\frac{C( \ln |x|_+ )^{a + c} }{|x|_+^{\alpha + \gamma - d}} & \hspace{3mm} \mbox{if}~& \alpha, \delta \in (0,d),\\
\frac{C ( \ln |x|_+ )^{a + c + 1}}{|x|_+^{\alpha}} &\hspace{3mm} \mbox{if}~& \alpha \in (0,d] ~\mbox{and}~ \gamma = d,\\
 \frac{ \left( \ln |x|_+ \right)^{a}}{|x|_+^{\alpha}} &\hspace{3mm} \mbox{if}~& \gamma > d ~\mbox{and} ~ \alpha < \gamma  \\
\end{aligned} \right.
\end{equation}
and
\begin{equation} \label{ineqB4}
     \sum_{z , z' \in \Zd} \frac{1}{|z|_+^{d-1} |z - x|_+^{d-1}}  \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{(\ln |z - z'|)^a}{|z - z'|_+^{d}}  \leq \frac{C}{|x|^{2d-2}_+}.
\end{equation}
There exists a constant $C := C(d, a , c) < \infty$ such that, for any $y_1 , y_2 \in \Zd$,
        \begin{equation}
\label{e.sumlattice1}
    \sum_{z \in \Zd} \frac{\left( \ln \left( |y_1-z|_+ + |y_2 - z|_+ \right) \right)^a}{|y_1-z|_+^{2d+1} + |y_2 - z|_+^{2d+1}}  \frac{\left( \ln \left( |z|_+  \right) \right)^c}{|z|^{d-1}_+} \leq \frac{C \left( \ln \left( |y_1|_+ + |y_2|_+ \right) \right)^{a + c} }{|y_1|_+^{d-1} + |y_2|_+^{d-1}}  \frac{1}{|y_1-y_2|^{d+1}_+}.
\end{equation}
\end{proposition}

The proof of this proposition is split into 4 different proofs.

\begin{proof}[Proof of the inequality~\eqref{eq:truineqB1}]
The inequality~\eqref{eq:truineqB1} can be established using standard arguments; we refer the reader to~\cite[Appendix C]{DW} for a complete proof (among other possible references). We note that not all possible cases for the exponents are treated here. A change of variables $y \mapsto x-y$ interchanges the roles of $\alpha$ and $\delta$, thereby covering several additional cases. The remaining cases, namely those with $\alpha = \delta$ and $\alpha , \delta \geq d$, can be handled similarly with little additional effort. However, these are not required for the purposes of this article.
\end{proof}

\begin{proof}[Proof of the inequality~\eqref{ineqB4}]
To simplify the presentation of the argument, we only present the proof in the case $a = 0$. For the inequality~\eqref{ineqB4}, we will first prove the upper bound, for any $x , z \in \Zd$,
\begin{equation} \label{intermediateB2}
    \sum_{z' \in \Zd} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}}  \leq  \frac{C}{|x|_+^{d-1}} \frac{\ln |z|_+ }{\left| z \right|_+^{d-1}} +  \frac{C}{|x|_+^{d-1}} \frac{\ln |x - z|_+}{|x - z|_+^{d-1}} + \frac{C}{|x|^{2d-2}_+}.
\end{equation}
This inequality is shown by considering two different cases.

\textbf{Case I:} $|z|_+ \leq \frac{|x|_+}{10}$. In that case, we partition the space into two regions
\begin{equation*}
    \left\{ z' \in \Zd \, : \, \left| z' \right| \leq \frac{|x|_+}{2} \right\} ~~\mbox{and}~~ \left\{ z' \in \Zd \, : \, \left| z' \right| > \frac{|x|_+}{2} \right\}.
\end{equation*}
In the first region, we may use the inequality $|z' - x|_+ \geq |x|_+ / 2$ and the inequality~\eqref{eq:truineqB1} to write
\begin{align*}
    \sum_{\substack{z' \in \Zd \\ |z'|_+ \leq |x|_+ / 2 }} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} & \leq \frac{C}{|x|_+^{d-1}} \sum_{\substack{z' \in \Zd \\ |z'|_+ \leq |x|_+ / 2 }} \frac{1}{|z'|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} \\
    & \leq \frac{C}{|x|_+^{d-1}} \sum_{z' \in \Zd } \frac{1}{|z'|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} \\
    & \leq \frac{C}{|x|_+^{d-1}} \frac{ \ln |z|_+ }{\left| z \right|_+^{d-1}}.
\end{align*}
In the second region, we use the inequality $|z' - z|_+ \geq |x|_+/4$ and the inequality~\eqref{eq:truineqB1} to write
\begin{align*}
    \sum_{\substack{z' \in \Zd \\ |z'|_+ \geq |x|_+ / 2 }} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} & \leq \frac{C}{|x|_+^{d}} \sum_{\substack{z' \in \Zd \\ |z'|_+ \geq |x|_+ / 2 }} \frac{1}{|z'|_+^{d-1}} \frac{1}{|x - z'|_+^{d-1}} \\
    & \leq \frac{C}{|x|_+^{d}} \sum_{z' \in \Zd} \frac{1}{|z'|_+^{d-1}} \frac{1}{|x - z'|_+^{d-1}} \\
    & \leq \frac{C}{|x|_+^{2d-2}}.
\end{align*}
A combination of the two previous inequalities implies that
\begin{equation} \label{resultstep1B2}
    \sum_{z' \in \Zd} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} \leq \frac{C}{|x|_+^{d-1}} \frac{\ln |z|_+}{\left| z \right|_+^{d-1}} + \frac{C}{|x|^{2d-2}_+}.
\end{equation}

\textbf{Case II:} $|z|_+ \geq \frac{|x|_+}{10}$. In this case, we similarly split the space into two regions
\begin{equation*}
     \left\{ z' \in \Zd \, : \, \left| z' \right| \leq \frac{|x|_+}{20} \right\} ~~\mbox{and}~~ \left\{ z' \in \Zd \, : \, \left| z' \right| > \frac{|x|_+}{20} \right\}.
\end{equation*}
In the first region, we use that $|z' - z|_+ \geq c |x|_+$ and $|z' - x|_+ \geq c |x|_+$ (for some explicit $c > 0$) to deduce that
\begin{align*}
    \sum_{\substack{z' \in \Zd \\ |z'|_+ \leq |x|_+ / 20 }} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} & \leq \frac{C}{|x|_+^{2d-1}} \sum_{\substack{z' \in \Zd \\ |z'|_+ \leq |x|_+ / 20 }} \frac{1}{|z'|_+^{d-1}} \\
    & \leq \frac{C}{|x|_+^{2d-2}}.
\end{align*}
In the second region, we use the inequality~\eqref{eq:truineqB1} to write
\begin{align*}
    \sum_{\substack{z' \in \Zd \\ |z'|_+ \geq |x|_+ / 20 }} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} & \leq \frac{C}{|x|_+^{d-1}} \sum_{\substack{z' \in \Zd \\ |z'|_+ \geq |x|_+ / 20 }} \frac{1}{|z'-x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} \\
    & \leq \frac{C}{|x|_+^{d-1}} \sum_{z' \in \Zd} \frac{1}{|z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} \\
    & \leq \frac{C}{|x|_+^{d-1}} \frac{ \ln |x - z|_+}{|x - z|_+^{d-1}}.
\end{align*}
A combination of the two previous inequalities implies that
\begin{equation*}
    \sum_{z' \in \Zd} \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} \leq \frac{C}{|x|_+^{2d-2}} + \frac{C}{|x|_+^{d-1}} \frac{\ln |x - z|_+}{|x - z|_+^{d-1}}.
\end{equation*}
Combining this inequality with~\eqref{resultstep1B2} completes the proof of~\eqref{intermediateB2}.

There only remains to show that the inequality~\eqref{intermediateB2} implies~\eqref{ineqB4}. To this end, we make use of~\eqref{eq:truineqB1}, the inequality $\ln |z|_+ \leq C |z|_+^{1/2}$ and the inequality $2d - 2 -1/2 > d$ (since $d \geq 3$) to write
\begin{align*}
    \sum_{z , z' \in \Zd} \frac{1}{|z|_+^{d-1} |z - x|_+^{d-1}}  \frac{1}{|z'|_+^{d-1} |z' - x|_+^{d-1}} \frac{1}{|z - z'|_+^{d}} & \leq \frac{C}{|x|^{d-1}_+}\sum_{z \in \Zd} \frac{\ln |z|_+}{|z|_+^{2d-2} |z - x|_+^{d-1}}  + \frac{C}{|x|^{d-1}_+}\sum_{z \in \Zd} \frac{\ln |x - z|_+}{|z|_+^{d-1} |z - x|_+^{2d-2}} \\
    & \quad + \frac{C}{|x|^{2d-2}_+} \sum_{z \in \Zd} \frac{1}{|z|_+^{d-1} |z - x|_+^{d-1}} \\
    & \leq \frac{C}{|x|_+^{2d-2}}.
\end{align*}
The proof of the inequality~\eqref{ineqB4} is complete.
\end{proof}

\begin{proof}[Proof of the inequality~\eqref{e.sumlattice1}]
Once again, in order to simplify the presentation of the argument, we only present the proof in the case $a = c = 0$. We first use the parallelogram law to write
\begin{align*}
    |y_1-z|_+^{2d+1} + |y_2 - z|_+^{2d+1} \geq c \left( |y_1-z|_+^{2} + |y_2 - z|_+^{2} \right)^{\frac{2d+1}{2}}
    & \geq c \left( |y_1- y_2|_+^{2} + \left|\frac{y_2 + y_1}{2} - z\right|_+^{2} \right)^{\frac{2d+1}{2}} \\
    & \geq c \left( |y_1- y_2|_+^{2d+1} + \left|\frac{y_2 + y_1}{2} -  z\right|_+^{2d+1} \right).
\end{align*}
Setting $x = y_1- y_2$ and $y = \frac{y_2 + y_1}{2}$, we see that (by the parallelogram law and a similar computation)
\begin{equation*}
   |x|_+^{2d+1} + |y|_+^{2d+1} \geq c \left( |y_1|_+^{2d+1} + |y_2|_+^{2d+1}  \right).
\end{equation*}
From the two previous inequalities, we see that~\eqref{e.sumlattice1} is equivalent to the following inequality
\begin{equation} \label{eq:ineqB2}
    \sum_{z \in \Zd} \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \frac{C}{|x|_+^{d-1} + |y|_+^{d-1}}  \frac{1}{|x|^{d+1}_+}.
\end{equation}
The rest of the argument is devoted to the proof of this inequality, and we discuss two cases.

\medskip

\textbf{Case I:} $|y|>2|x|$. In this case, the inequality~\eqref{eq:ineqB2} can be restated as follows
\begin{equation*}
    \sum_{z \in \Zd} \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \frac{C}{|y|_+^{d-1}}  \frac{1}{|x|^{d+1}_+}.
\end{equation*}
We will prove this inequality by splitting the space into the four regions (see Figure~\ref{fig:4regions})
\begin{equation*}
    \left\{ z \in \Zd \, : \, |y - z| \leq |x| \right\}, ~~  \left\{ z \in \Zd \, : \, |x| < |y - z| \leq \frac{|y|}{2} \right\}~~\mbox{and}~~ \left\{ z \in \Zd \, : \,  |z| \leq \frac{|y|}{2}  \right\}
\end{equation*}
and
\begin{equation*}
    \left\{ z \in \Zd \, : \,  \frac{|y|}{2} < |y - z| ~\mbox{and}~ \frac{|y|}{2} < |z|  \right\}.
\end{equation*}

\begin{figure}
    \centering
    \includegraphics[scale=0.6]{4regions.png}
    \caption{The four regions used in the proof of the inequality~\eqref{e.sumlattice1}.}
    \label{fig:4regions}
\end{figure}

\medskip

\textit{Step 1: the first region.} We may use the inequalities
\begin{equation*}
    |x|_+^{2d+1} + |y - z|_+^{2d+1} \geq |x|_+^{2d+1} \hspace{5mm} \mbox{and} \hspace{5mm} |z|_+ \geq \frac{|y|_+}{2}
\end{equation*}
to obtain
\begin{equation*}
    \sum_{z \in \Zd \, : \, |y - z| < |x| } \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \sum_{z \in \Zd \, : \, |y - z| < |x| } \frac{C}{|x|_+^{2d+1}} \frac{1}{|y|^{d-1}} \leq \frac{C}{|x|_+^{d+1}} \frac{1}{|y|_+^{d-1}},
\end{equation*}
where in the last inequality we used that the cardinality of the set $\{ z \in \Zd \, : \, |y - z| \leq |x| \}$ is of order $|x|^d_+$.

\medskip

\textit{Step 2: the second region.} We use the inequalities
\begin{equation*}
    |x|_+^{2d+1} + |y - z|_+^{2d+1} \geq |y - z|_+^{2d+1} \hspace{5mm} \mbox{and} \hspace{5mm} |z|_+ \geq \frac{|y|_+}{2}
\end{equation*}
to obtain that
\begin{align*}
    \sum_{z \in \Zd \, : \, |x| < |y - z| \leq \frac{|y|}{2}  } \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} & \leq \sum_{z \in \Zd \, : \,  |x| < |y - z| \leq \frac{|y|}{2} } \frac{1}{|y-z|_+^{2d+1}} \frac{1}{|y|_+^{d-1}} \\
    & \leq \frac{C}{|y|_+^{d-1}} \sum_{z \in \Zd \, : \,  |x| < |z| \leq \frac{|y|}{2} } \frac{1}{|z|_+^{2d+1}} \\
    & \leq \frac{C}{|y|_+^{d-1}} \sum_{z \in \Zd \, : \,  |x| < |z| } \frac{1}{|z|_+^{2d+1}}  \\
    & \leq \frac{C}{|y|_+^{d-1}} \frac{1}{|x|_+^{d+1}}.
\end{align*}

\medskip

\textit{Step 3: the third region.}  In this case, we note that there exists $c>0$ such that
\begin{equation*}
    |x|_+^{2d+1} + |y - z|_+^{2d+1} \geq c |y|_+^{2d+1}
\end{equation*}
and use it to deduce that
\begin{align*}
    \sum_{z \in \Zd \, : \, |z| < \frac{|y|}{2} } \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \frac{C}{|y|_+^{2d+1}} \sum_{z \in \Zd \, : \,  |z| < \frac{|y|}{2} } \frac{C}{|z|_+^{d-1}} \leq \frac{C}{|y|_+^{2d}} \leq  \frac{C}{|y|_+^{d-1}} \frac{1}{|x|_+^{d+1}}.
\end{align*}

\medskip

\textit{Step 4: the fourth region.} In this case, we use the inequality, for some constant $c > 0$,
\begin{equation*}
     |x|_+^{2d+1} + |y - z|_+^{2d+1} \geq c |z|_+^{2d+1}
\end{equation*}
to deduce that
\begin{align*}
    \sum_{z \in \Zd \, : \,  \frac{|y|}{2} < |y - z| ~\mbox{and}~ \frac{|y|}{2} < |z|} \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \sum_{z \in \Zd \, : \,  \frac{|y|}{2} < |y - z| ~\mbox{and}~ \frac{|y|}{2} < |z|} \frac{C}{|z|_+^{3d}} & \leq \sum_{z \in \Zd \, : \, \frac{|y|}{2} < |z|}  \frac{C}{|z|_+^{3d}} \\
    & \leq \frac{C}{|y|_+^{2d}} \\
    & \leq \frac{C}{|y|_+^{d-1}}  \frac{1}{|x|^{d+1}_+}.
\end{align*}


\medskip

\textbf{Case II:} $|y|\le 2|x|$. In this case, the inequality~\eqref{eq:ineqB2} can be restated as follows
\begin{equation*}
    \sum_{z \in \Zd} \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \frac{C}{|x|_+^{2d}}.
\end{equation*}
Similarly, we split the sum into two regions:
\begin{equation*}
    \left\{ z \in \Zd \, : \, |z| \leq |x| \right\} \hspace{5mm} \mbox{and} \hspace{5mm} \left\{ z \in \Zd \, : \, |z| > |x| \right\}.
\end{equation*}

\medskip

\textit{Step 1: the first region.} We use the inequality
\begin{equation*}
    |x|_+^{2d + 1} + |y - z|_+^{2d + 1} \geq |x|_+^{2d + 1} 
\end{equation*}
to deduce that
\begin{equation*}
    \sum_{z \in \Zd \, : \, |z| \leq |x| } \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \frac{1}{|x|_+^{2d+1}} \sum_{z \in \Zd \, : \, |z| \leq |x| }  \frac{1}{|z|^{d-1}_+} \leq \frac{C}{|x|_+^{2d}}.
\end{equation*}

\medskip

\textit{Step 2: the second region.} We use the inequality
\begin{equation*}
    |x|_+^{2d + 1} + |y - z|_+^{2d + 1} \geq c |z|_+^{2d + 1} 
\end{equation*}
to deduce that
\begin{equation*}
    \sum_{z \in \Zd \, : \, |z| \geq |x| } \frac{1}{|x|_+^{2d+1} + |y - z|_+^{2d+1}}  \frac{1}{|z|^{d-1}_+} \leq \sum_{z \in \Zd \, : \, |z| \geq |x| }  \frac{C}{|z|^{3d}_+} \leq \frac{C}{|x|_+^{2d}}.
\end{equation*}
\end{proof}

