\title{1-D  Schr\"odinger operator on a star graph with nondefinite weight function}

\author{Edison Leguizam\'on, Carsten Trunk, Mitsuru Wilson and Monika Winklmeier}

\begin{document}

\maketitle

\begin{abstract}
On a star graph $G$ with  $n = n_+ + n_-$ edges of unit length, we study the operator 
$-\frac{\rd^2}{\rd x^2}$ on $n_+$ and 
$\frac{\rd^2}{\rd x^2}$ on $n_-$ edges 
equipped with Dirichlet boundary conditions at the outer vertices and a Kirchhoff condition at the central vertex.
We study the spectral properties of the corresponding indefinite Kirchhoff Laplacian on $G$ and we show that it is similar to a selfadjoint operator in the Hilbert space $L^2(G)$ and that its eigenfunctions form a Riesz basis. 
Furthermore, we give a complete description of the point spectrum.
\end{abstract}

\section{Introduction}
\noindent
The study of differential operators on metric graphs has gained significant attention over the past few decades. Much of the literature has focused on selfadjoint Schr\"{o}dinger operators (see \cite{BerkolaikoKuchment, BEH08, K24}). The present work is motivated by the growing interest in spectral theory on network structures and by the fresh relevance of non-selfadjoint operators in quantum mechanics (see, e.g.,\ \cite{HKS15}). There have been recent attempts to formulate “quasi-Hermitian quantum mechanics”, where physical observables are represented by non-selfadjoint operators $T$ satisfying the quasi-selfadjointness relation
\begin{equation*}
	T^* = \Theta T \Theta^{-1}
\end{equation*}
for a bounded, boundedly invertible operator $\Theta$ (see, e.g., \cite{SGH92}). That is, $T$ is similar to a selfadjoint operator. In \cite{CurgusNajman1995}, B.~{\'C}urgus and B.~Najman considered the operator $\frac{\rd^2}{\rd x^2}$ on $\R^-$ and $-\frac{\rd^2}{\rd x^2}$ on $\R^+$ on the Sobolev space $H^2(\R)$. This operator serves as one of the pioneering examples of a simple differential operator which is not selfadjoint in the standard $L^2$-space over $\R$ but is nevertheless spectrally well understood as it is similar to a selfadjoint operator in a Hilbert space. We refer to \cite{CurgusLanger1989} for a broader class of such differential operators and to \cite{F24} for an overview. The present paper can be viewed as a generalization of these results to graphs.
Specifically, we study the spectral properties of the indefinite Kirchhoff Laplacian on the graph. 
\smallskip


Let $G$ be a star graph with $n$ edges $I_1,\, \dots,\, I_n$, each of unit length, and all joined at the central vertex $0$. 
We will work in the space of square integrable functions on $G$ given by
\begin{equation}
\label{eq:hilbert_graph}
	L^2(G) := \bigoplus_{j=1}^n L^2(I_j) = 
    \bigoplus_{j=1}^n L^2((0,1)). 
\end{equation}
%
For a function $f\in L^2(G)$ we set $f_j := f|_{I_j}$ and we write $f = (f_1,\, \dots,\, f_n)$.

Our goal is to investigate the spectral properties of the indefinite Kirchhoff Laplacian $\AKone$ on the star graph $G$ with Dirichlet conditions at the outer vertices and a Kirchhoff condition at the central vertex in $L^2(G)$.

Let us denote 
\begin{equation}
   \label{eq:hilbert_graph.dirichlet}
   \widehat H^1_D(G) := \{ f\in L^2(G) : 
   f_j\in H^1(I_j) \text{ for all } j \text{ and }
   f_1(1) = \cdots = f_n(1) = 0 \}.
\end{equation}

The corresponding operator $\AKone$ is then defined as
\begin{align}
\label{DerAuserwaehlte}
   (\AKone f)_j = 
   \begin{cases}
      -f_j''\quad &\text{if }\ 1 \le j \le n_+,\\
      f_j''\quad &\text{if }\  n_+ + 1 \le j \le n,
   \end{cases}
\end{align}
on the domain
\begin{align}
   \mD(B) = \left\{ f\in \widehat H_D^1(G)\ : \
   f_j\in H^2(I_j) \text{ for all } j \text{ and }
   f_1(0) = \dots = f_n(0), ~ \sum_{j=1}^n f_j'(0) = 0
\right\}.
\end{align}

\medskip
{\bf Notations.}
By $\mathbb{C}$ we denote the set of complex numbers and by $\mathbb{R}$ the set of real numbers. Here $\mathbb N = \{1, 2, 3, \dots\}$ stands for the natural non-zero numbers and $\mathbb Z$ the integers. All operators are closed densely defined linear operators. For such an operator $T$, we use the common notation $\rho(T)$, $\sigma(T)$, $\pointspec(T)$, $\ran T$ and $\mD(T)$ for its resolvent set, spectrum, point spectrum, range and domain, respectively. 
Moreover, $H^1((0,1))$ stands for the first Sobolev space, that is, the subset of all functions $f\in L^2((0,1))$ such that $f$ has a first weak derivative and $f$ and $f'$ have a finite $L^2$-norm. 
Note that any $f\in H^1((0,1))$ is continuous in $(0,1)$ with a continuous extension to the endpoints $0$ and $1$.
Analogously, $H^2((0,1))$ stands for the second Sobolev space which is the subset of all functions $f\in H^1((0,1))$ such that $f'\in H^1((0,1))$. 
By $H^1_0((0,1))$ we denote all functions $f\in H^1((0,1))$ with $f(0)=f(1)=0$ and by $\mathcal C_0^\infty((0,1))$ the space of all infinitely often differentiable functions on the interval $[0,1]$ with compact support in $(0,1)$.

