\section{Various convergence analysis of the discrete splitting algorithm}\label{sec: convergence of splitting algorithm to SLE} The natural regularity of SLE dynamics renders us sufficient tools to reveal the convergence of the splitting algorithm in various topologies. Specially, we will show the splitting $\widetilde{Z}(iy_N)$ converges to the random Loewner curve, respectively, in sup-norm and $L^p$ locally on $[0,T]$ in high probability.


%-----------------------------------------
\subsection{Local sup-norm convergence in probability.}
    We first look at the sup-norm convergence of the splitting algorithm. An increasing sequence $\phi:\mathbb{N}_+\to\mathbb{R}_+$ is called subpower if $\lim_{N\nearrow\infty}N^{-\nu}\phi(N)=0$ for all $\nu>0$. The proof of Theorem \ref{thm: sup-norm convergence} relies on the following propositions.

    %prop: estimate event B1
    \begin{proposition}\label{prop: estimate event B1}
        \normalfont
        Let $0<\beta<1$. There exists a subpower sequence $(\phi_N)_{N\geq1}$ such that if $\abs{\mathcal{D}_N}\leq 1/N$ and if we write the event
        \[
            \mathcal{B}^{(1)}_N\coloneqq\big\{\normy{\eta-\sum_{k<N}\eta_{t_k}\mathbbm{1}_{[t_k,t_k+h_k)} }_T\leq \tfrac{2\phi(N^{1/2})}{(1-\beta)N^{(1-\beta)/2}} \big\},
        \]
        where $\phi(N^{1/2})\coloneqq\phi_k$ for $k\leq N^{1/2}<k+1$, then $1-\mathbb{P}(\mathcal{B}^{(1)}_N)\leq C N^{-c}$ for some constants $c,C>0$.
    \end{proposition}
    \begin{proof}
        When there is no confusion, we write $t_k\coloneqq t_k(t)$. It is clear that if we replace all $\eta$'s in $\mathcal{B}^{(1)}_N$ by $\gamma$, its probability stays the same. Invoking \cite[Theorem 3.4.2]{Lawler/Limic} according to Ref. \cite{Lawler/Limic} , we find constants $C,C^\prime>0$ such that
        \begin{equation}\label{eqn: event 1 for B1}
            \mathbb{P}\big(\text{osc}( (\sqrt{\kappa}B_t)_{t\in[0,T]},1/N) \leq C\sqrt{\log N/N} \big) \geq 1- C^\prime N^{-2}.
        \end{equation}
        In light of \cite[Eqn. (21)]{Tran} we can find constants $c,c^\prime,C^{\prime\prime}>0$ and $1<\beta<1$ such that
        \begin{equation}\label{eqn: event 2 for B1}
            \mathbb{P} \big(|\partial_z\Tilde{g}^{-1}_t(iy)|\leq cy^{-\beta},\;\forall~t\in[0,1],~y\in[0,1/N^{1/2}]\big)\geq 1- C^{\prime\prime}N^{-c^\prime}.
        \end{equation}
        By \cite[Lemma 2.5]{Tran}, there exists a subpower sequence $(\phi_N)_{N\geq1}$ such that on the intersection of the two events in (\ref{eqn: event 1 for B1}) and (\ref{eqn: event 2 for B1}), we have
        \[
            \phi(N^{1/2})^{-1}\abs{\gamma_{t}-\gamma_{t_k}} \leq 2\int_0^{1/N^{1/2}} |\partial_z\Tilde{g}_t^{-1}(ir)|\,dr \leq \frac{2}{1-\beta}N^{2/(1-\beta)}
        \]
        with $0<\beta<1$. Hence, the complement of $\mathcal{B}^{(1)}_N$ shrinks polynomially and the assertion is verified.
    \end{proof}

    %prop: estimate event B2
    \begin{proposition}\label{prop: estimate event B2}
        \normalfont
        Let $0<\delta<1$ and $\ell_N\coloneqq N^{(1-\delta)/4}$. If we write the event
        \[
            \mathcal{B}^{(2)}_N\coloneqq\big\{ \normy{Z(iy_N)-\eta}_T\leq N^{-(1-\delta)/4} \big\},
        \]
        then there exists a decreasing sequence $\epsilon_N\to0+$ such that $1-\mathbb{P}(\mathcal{B}^{(2)}_N)\leq\epsilon_N$.
    \end{proposition}
    \begin{proof}
        Following \cite[Lemma 6.7]{Foster/Lyons/Margarint}, we find some $0<\delta<1$ such that $\sup_{0\leq t\leq T}\abs{Z_t(iy_N)-\eta_t}\leq C(\omega)y_N^{1-\delta}$, $\mathbb{P}$-a.s. for some $C(\omega)>0$. Here, this $C(\omega)$ is taken to be the minimal random positive number that admits this inequality for all $N\in\mathbb{N}_+$. Whence we have $\{C(\omega)\leq\ell_N\}\subseteq\mathcal{B}^{(2)}_N$; And by choosing $\epsilon_N\coloneqq\mathbb{P}(C(\omega)\geq\ell_N)$, the assertion is verified in light that $\ell_N\nearrow\infty$ monotonically.
    \end{proof}

    On $\mathcal{B}^{(1)}_N\cap\mathcal{B}^{(2)}_N$, there are $\sup_{0\leq t\leq T}\abs{\eta_t-\eta_{t_k(t)}}\leq \frac{2\phi(N^{1/2})}{(1-\beta)N^{(1-\beta)/2}}$ and $\sup_{0\leq t\leq T}\abs{Z_t(iy_N)-\eta_t}\leq N^{-(1-\delta)/4}$. Combing those two upper-bounds, one observes 
    \begin{equation}
        \normy{Z(iy_N)-\sum_{k<N}Z_{t_k}(iy_N)\mathbbm{1}_{[t_k,t_k+h_k)}}_T\leq\frac{2}{N^{(1-\delta)/4}} + \frac{2\phi(N^{1/2})}{(1-\beta)N^{(1-\beta)/2}},\qquad\forall~N\geq1.
    \end{equation}
    Inspecting Definition \ref{def: N-V splitting algorithm} in the context of (\ref{eqn: SDE of Z_t}), we observe that $\widetilde{Z}_{t_{k+1}}^2+2h_k = ((\widetilde{Z}_{t_k}^2-2h_k)^{1/2}+\sqrt{\kappa}B_{t_k,t_k+h_k})^2$ for each $ k<N$. Whence the Loewner evolution $\widetilde{Z}_{t_k}\mapsto\widetilde{Z}_{t_k+h_k}$ consists of two reversed Loewner flows with an intermediate parallel translation.\par
    In light of \cite[Section 2.]{Kager/Nienhuis/Kadanoff}, a constant force $t\mapsto A$ drives the Loewner chain $g_t(z)=A+( (z-A)^2 + 4t )^{1/2}$ on $[0,T]$ with its reversal $h_T(z) = A + ( (z-A)^2-4T )^{1/2}$ at time $T$. If we use $\iota^\prime_{k,1}$ and $\iota^{\prime\prime}_{k,2}$ for the reverse Loewner flows for the constant force $t\mapsto0$ on $[t_k,t_k+h_k/2]$ and respectively the constant force given by the corresponding value of the Brownian path at the final moment of $[t_k+h_k/2,t_{k+1}]$; And $\iota_{k,2}:t\mapsto t+\sqrt{\kappa}B_{t_k,t_k+h_k}$. Then $\widetilde{Z}_{t_k+h_k}(iy_N)=\iota^{\prime\prime}_{k,1}\circ\iota_{k,2}\iota^\prime_{k,1}\widetilde{Z}_{t_k}(iy_N)$ for each $k<N$.

    %prop: estimate event B3
    \begin{proposition}\label{prop: estimate event B3}
        \normalfont
        If further $\abs{\mathcal{D}_N}\leq(4N+1)^{-3}$ and if we write the perturbation event
        \[
            \mathcal{B}^{(3)}_N\coloneqq\big\{ \normy{ \sum_{k<N}\big( Z_{t_k}(iy_N) - \widetilde{Z}_{t_k}(iy_N) \big)\mathbbm{1}_{[t_k,t_k+h_k)} }_T \leq (4N+1)^{-1/2} \big\},
        \]
        then $1-\mathbb{P}(\mathcal{B}^{(3)}_N)\leq Ce^{-cN}$ for some constants $c,C>0$.
    \end{proposition}
    \begin{proof}
        Define the càdlàg driving force $\Tilde{\lambda}_t\coloneqq \sum_{k<N} \sqrt{\kappa}B_{t_k} \mathbbm{1}_{[t_k-h_k/2,t_k+h_k/2)}(t) $ on $[0,T]$. Viewed as a coarse interpolation to the trace $\sqrt{\kappa}B[0,T]$, $(\Tilde{\lambda}_t)_{t\in[0,T]}$ initiates the Loewner flow $(\widetilde{Z}^\dagger_t(iy_N))_{t\in[0,T]}$ with the form
        \begin{equation}\label{eqn: SDE of cadlag Z tilde}
            \widetilde{Z}^\dagger_t(iy_N) = \Tilde{h}_t(iy_N)-\Tilde{\lambda}_t,\qquad\text{with}\quad \partial_t \Tilde{h}_t(z) = \frac{-2}{\Tilde{h}_t(z)- (\Tilde{\lambda}_{T-t}-\Tilde{\lambda}_T) },\qquad\forall~t\in[0,T].
        \end{equation}
        The above observation compels us to estimate
        \begin{equation}\label{eqn: difference between Z and Z tilde}
            \big| Z_t(iy_N) - \widetilde{Z}^\dagger_t(iy_N) \big| \leq \big| h_t(iy_N) - \Tilde{h}_t(iy_N) \big| + \sup_{0\leq t\leq T}\big| \sqrt{\kappa}B_t - \Tilde{\lambda}_t \big|.
        \end{equation}
        To this end, we write $H_t\coloneqq h_t(iy_N) - \Tilde{h}_t(iy_N)$ for all $t\in[0,T]$. Invoking (\ref{eqn: SDE of Z_t}) and (\ref{eqn: SDE of cadlag Z tilde}), we get
        \[
            \frac{d}{dt}H_t - H_t\zeta(t) = \big(\sqrt{\kappa}B_t - (\Tilde{\lambda}_{T-t}-\Tilde{\lambda}_T) \big)\zeta(t),\quad \zeta(t)\coloneqq \big( h_t(iy_N) - \sqrt{\kappa}(B_{T-t}-B_T) \big)^{-1} \big( \Tilde{h}_t(iy_N) - (\Tilde{\lambda}_{T-t}-\Tilde{\lambda}_T) \big)^{-1}.
        \]
        If we integrate the above differential, we get
        \[
            H_t u(t) = H_0 - \int_0^t (\sqrt{\kappa}B_{T-s}-\Tilde{\lambda}_{T-s}+\Tilde{\lambda}_T-\sqrt{\kappa}B_T) u(s)\zeta(s)\,ds,\qquad\text{with}\quad u(t)\coloneqq e^{-\int_0^t \zeta(s)\,ds },\qquad H_0=0.
        \]
        Henceforth, we obtain
        \begin{equation*}\begin{aligned}
            &\big| h_t(iy_N) - \Tilde{h}_t(iy_N) \big| \leq \int_0^t | \sqrt{\kappa}B_{T-s}-\Tilde{\lambda}_{T-s}+\Tilde{\lambda}_T-\sqrt{\kappa}B_T | e^{\int_s^t\Re\zeta(\tau)\,d\tau}|\zeta(s)|\,ds\\
            &\qquad\leq \sup_{0\leq\tau\leq T} |\sqrt{\kappa}B_{\tau}-\Tilde{\lambda}_{\tau}| \int_0^t e^{\int_s^t\Re\zeta(r)\,dr}|\zeta(s)|\,ds \leq \sup_{0\leq\tau\leq T} |\sqrt{\kappa}B_{\tau}-\Tilde{\lambda}_{\tau}| \big( e^{\int_s^t|\zeta(r)|\,dr}-1 \big),
        \end{aligned}\end{equation*}
        where the last inequality is due to \cite[Lemma 2.3, Eqn. (2.12)]{Viklund/Rohde/Wong}. Furthermore, \cite[Eqn. (2.12)]{Viklund/Rohde/Wong} yields $\int_0^t\abs{\zeta(s)}\,ds$ is less than or equal to $\frac{1}{2}\log N(4+y_N^2)$. Thus, looking back to (\ref{eqn: difference between Z and Z tilde}), we have 
        \begin{equation}\label{eqn: further difference}
            \big|Z_t(iy_N)-\widetilde{Z}^\dagger_t(iy_N)\big| \leq N^{1/2}(4+y_N^2)^{1/2} \sup_{0\leq t\leq T} |\sqrt{\kappa}B_t-\Tilde{\lambda}_t| \leq (4N+1)^{1/2} \sup_{0\leq t\leq T} |\sqrt{\kappa}B_t-\Tilde{\lambda}_t|.
        \end{equation}
        Now notice that $\normx{\sqrt{\kappa}B -\Tilde{\lambda} }_T\leq \sup_{0\leq k<N}\normx{\sqrt{\kappa}B_{t_k+\vdot}}_{h_k}$ and that by \cite[Corollary 2.2]{Boukai} we have $\mathbb{P}(S_t\leq x)=2\Phi(t^{-1/2}x)$ where $S_t\coloneqq\sup_{0\leq s\leq t}B_s$ and $\Phi\sim\mathcal{N}(0,1)$ is the cumulant function of a standard Gaussian. Via reflection principle,
        \[
            \mathbb{P}\big( \normx{\sqrt{\kappa}B}_{h_k}\geq (4N+1)^{-1} \big) \leq 2\mathbb{P}\big( S_{h_k}\geq \kappa^{-1/2}(4N+1)^{-1} \big)\leq 2(2/\pi)^{1/2}\exp\big( -\tfrac{1}{2\kappa}h_k^{-1}(4N+1)^{-2} \big).
        \]
        Now that we have chosen $\abs{\mathcal{D}_N}\leq(4N+1)^{-3}$, then on the event $\{\normx{\sqrt{\kappa}B-\Tilde{\lambda}}_T\geq(4N+1)^{-1}\}$, we know $\normx{\sqrt{\kappa}B_{t_k+\vdot}}_{h_k/2}\geq(4N+1)^{-1}$ for some $0\leq k<N$. Hence,
        \[
            \mathbb{P}\big(\normx{\sqrt{\kappa}B-\Tilde{\lambda}}_T\geq(4N+1)^{-1}\big)\leq \sum_{k<N} \mathbb{P}\big(\normx{\sqrt{\kappa}B_{t_k+\vdot}}_{h_k/2}\geq(4N+1)^{-1}\big) \leq 2T(4N+1)^3 e^{-(4N+1)/2\kappa}.
        \]
        Observe that on the complement event of $\{\normx{\sqrt{\kappa}B-\Tilde{\lambda}}_T\geq(4N+1)^{-1}\}$, in light of (\ref{eqn: further difference}), we get $\normx{Z(iy_N)-\widetilde{Z}^\dagger(iy_N)}_T\leq(4N+1)^{-1/2}$ with the probability of this occurrence at least $1 - 2T(4N+1)^3 e^{-(4N+1)/2\kappa}$. Since the splitting output $(\widetilde{Z}_t(iy_N))_{t\in[0,T]}$ coincides with the trace $\widetilde{Z}^\dagger(iy_N)$ at each $t_k\in\mathcal{D}_N$, the assertion is then verified.
    \end{proof}

    Following the Definition \ref{def: N-V splitting algorithm} in the context of SLE, at each $N$th step we could compute $\widetilde{Z}^{(0)}_t=\text{exp}((t-t_k)L_0/2)\widetilde{Z}_{t_k}=(\widetilde{Z}_{t_k}^2-2(t-t_k))^{1/2}$, $\widetilde{Z}_t^{(1)}=\text{exp}(B_{t_k,t}L_1)=(\widetilde{Z}_{t_k}^2-2h_k)^{1/2}+B_{t_k,t}$ and $\widetilde{Z}_t^{(2)}=\text{exp}((t-t_k)L_0/2)\widetilde{Z}^{(1)}_{t_{k+1}}=((\widetilde{Z}^{(1)}_{t_{k+1}})^2-2(t-t_k))^{1/2}$ for any $t_k\leq t<t_k+h_k$ and $0\leq k<N$. Written out in integral form, we get
    \begin{equation}\begin{aligned}\label{eqn: exact from of difference}
        &\widetilde{Z}_t(iy_N)-\widetilde{Z}_{t_k(t)}(iy_N) = \frac{1}{2} \int_{t_k(t)}^t L_0(\widetilde{Z}_s^{(2)}) \,ds + \int_{t_k(t)}^t L_1(\widetilde{Z}_s^{(1)}) \,dB_s +\ frac{1}{2} \int_{t_k(t)}^t L_0(\widetilde{Z}_s^{(0)}) \,ds,\\
        &\qquad = \int_{t_k}^t \sqrt{\kappa} \,dB_s - \int_{t_k}^t \big((\widetilde{Z}_{t_{k}})^2-2(s-t_k)\big)^{-1/2}\,ds - \int_{t_k}^t \big(\big(\widetilde{Z}_{t_{k+1}}^{(1)}\big)^2-2(s-t_k)\big)^{-1/2}\,ds,\qquad\forall~t\in[0,T],
    \end{aligned}\end{equation}
    and can be further expanded if we replace $\widetilde{Z}^{(1)}_{t_{k+1}}$ in terms of $\widetilde{Z}_{t_k}$. This exact form of difference then leads us to the following result.

    %prop: estimate event B4
    \begin{proposition}\label{prop: estimate event B4}
        \normalfont
        Let $\kappa\neq0$ and $\abs{\mathcal{D}_N}\leq(4N+1)^{-3}$. If we write the event
        \[
            \mathcal{B}^{(4)}_N\coloneqq\big\{ \normy{\widetilde{Z}(iy_N)-\sum_{k<N} \widetilde{Z}_{t_k}(iy_N)\mathbbm{1}_{[t_k,t_k+h_k)}}_T \leq 2N^{-1/2}+4N^{-1/4} \big\},
        \]
        then $1-\mathbb{P}(\mathcal{B}^{(4)}_N)\leq Ce^{-cN^{1/2}}$ for some constants $c,C>0$.
    \end{proposition}
    \begin{proof}
        A general result $\Im z\leq\Im (z^2-A)^{1/2}$, $\Im z=\Im z+A$ for all $z\in\mathbb{H}$ and $A\in\mathbb{P}$ follows from \cite[Section 6.1]{Foster/Lyons/Margarint}. Thus, from (\ref{eqn: exact from of difference}) we have
        \[
            \big| \widetilde{Z}_t(iy_N) - \widetilde{Z}_{t_k}(iy_N) \big| \leq |\sqrt{\kappa}B_{t_k,t}| + \frac{2h_k}{\Im \widetilde{Z}_{t_k}(iy_N)} \leq |\sqrt{\kappa}B_{t_k,t}| + 2y_N^{-1}h_k,
        \]
        where the last inequality is due to \cite[Lemma 4.9]{Kemppainen}, which says that the map $t\in[0,T]\mapsto\Im \widetilde{Z}_t(iy_N)$ is increasing. In light of \cite[Corollary 2.2]{Boukai}, we get
        \[
            \mathbb{P}\big( \normx{\sqrt{\kappa}B}_{h_k}\geq N^{-1/4} \big) \leq 2\mathbb{P}\big( S_{h_k}\geq\kappa^{-1/2}N^{-1/4} \big) \leq 2(2/\pi)^{1/2}\exp\big(\tfrac{1}{2\kappa}h_k^{-1}N^{-1/2}\big),\qquad\forall~N\geq1,
        \]
        by the reflection principle. Since $\abs{\mathcal{D}_N}\leq (4N+1)^{-3}$, the assertion then follows.
    \end{proof}
    \begin{proof}[Proof of Theorem \ref{thm: sup-norm convergence}.]
        Combining Propositions \ref{prop: estimate event B1}, \ref{prop: estimate event B2}, \ref{prop: estimate event B3}, \ref{prop: estimate event B4} and on the event $\mathcal{B}^{(1)}_N \cap \mathcal{B}^{(2)}_N \cap \mathcal{B}^{(3)}_N \cap \mathcal{B}^{(4)}_N$, with
        \[
            \varphi_1(N)\coloneqq 3N^{-(1-\delta)/4} + 2(1-\beta)^{-1}\phi(N^{1/2})N^{-(1-\beta)/2} + (4N+1)^{-1/2} + 2N^{-1/2} + 4N^{-1/4},
        \]
        given $\abs{\mathcal{D}_N}\leq(4N+1)^{-3}$, we have
        \begin{equation*}\begin{aligned}
            &\normy{\eta-\widetilde{Z}(iy_N)}_T \leq \normy{\eta-Z(iy_N)}_T + \normy{Z(iy_N)-\sum_{k<N}Z_{t_k}(iy_N)\mathbbm{1}_{[t_k,t_k+h_k)}}_T\\
            &\qquad+ \normy{\sum_{k<N} \big(Z_{t_k}(iy_N)-\widetilde{Z}_{t_k}(iy_N)\big)\mathbbm{1}_{[t_k,t_k+h_k)} }_T + \normy{\sum_{k<N} \widetilde{Z}_{t_k}(iy_N)\mathbbm{1}_{[t_k,t_k+h_k)} - \widetilde{Z}(iy_N) }_T \leq \varphi_1(N).
        \end{aligned}\end{equation*}
        Choose $\varphi_2(N)\coloneqq \epsilon_N + CN^{-c} + C^\prime e^{-c^\prime N^{1/2}}$ for suitable constants $c,c^\prime,C,C^\prime>0$ determined in Propositions \ref{prop: estimate event B1}, \ref{prop: estimate event B2}, \ref{prop: estimate event B3}, \ref{prop: estimate event B4}. We then have $1-\mathbb{P}(\mathcal{B}^{(1)}_N \cap \mathcal{B}^{(2)}_N \cap \mathcal{B}^{(3)}_N \cap \mathcal{B}^{(4)}_N)\leq\varphi_2(N)\to0+$ as the step $N$ advances, verifying the claim.
    \end{proof}







