\subsection{Insights on a version of $L^p$-norm convergence.}
    Our next journey is to view the splitting algorithm through the lens of another metric perspective, namely, the $L^p$-norm topology. The proof of Theorem \ref{thm: sup-norm convergence} relies on the following propositions.

    %prop: estimate event A1
    \begin{proposition}\label{prop: estimate A1}
        \normalfont
        We can find an event $\mathcal{A}^{(1)}_N$ and two decreasing sequences $\Tilde{\psi}^{(1)}_N\to0+$, $\Hat{\psi}^{(1)}_N\to0+$ as $N\to\infty$ so that
        \[
            \mathbb{E}\bigg[\int_0^T \big|\eta_t -Z_t(iy_N)\big|^p\,dt\vdot I_{\mathcal{A}_N^{(1)}}\bigg]\leq\Tilde{\psi}^{(1)}_N\qquad\text{with}\quad\mathbb{P}(\mathcal{A}_N^{(1)})\geq1-\Hat{\psi}^{(1)}_N.
        \]
    \end{proposition}

    \begin{proof}
        By \cite[Lemma 6.7]{Foster/Lyons/Margarint} we find $0<\delta<1$ with $\sup_{0\leq t\leq T}|\eta_t-Z_t(iy_N)|\leq C(\omega)N^{-(1-\delta)/2}$, $\mathbb{P}$-a.s. Take the event $\mathcal{A}^{(1)}_N\coloneqq\{C(\omega)\leq N^{(1-\delta)/4} \}$. Then $\Hat{\psi}^{(1)}_N\coloneqq\mathbb{P}(C(\omega)\geq N^{(1-\delta)/4} )\to0+$ and 
        \[
            \mathbb{E}\big[\int_0^T|\eta_t-Z_t(iy_N)|^p\,dt\vdot I_{\mathcal{A}^{(1)}_N}\big] \leq \mathbb{E}\big[ \normx{\eta-Z(iy_N)}_T^p,\, \mathcal{A}^{(1)}_N \big] \leq N^{-p(1-\delta)/4} \coloneqq\Tilde{\psi}^{(1)}_N\to0.
        \]
        And the assertion is verified.
    \end{proof}

    %prop: estimate event A2
    \begin{proposition}\label{prop: estimate A2}
        \normalfont
        We can find an event $\mathcal{A}^{(2)}_N$ and two decreasing sequences $\Tilde{\psi}^{(2)}_N\to0+$, $\Hat{\psi}^{(2)}_N\to0+$ as $N\to\infty$ so that
        \[
            \mathbb{E} \bigg[ \int_0^T \big| Z_t(iy_N) -Z_{t_k(t)}(iy_N)\big|^{p}\,dt \vdot I_{\mathcal{A}_N^{(2)}} \bigg] \leq \Tilde{\psi}^{(2)}_N\qquad\text{with}\quad\mathbb{P}(\mathcal{A}_N^{(2)})\geq1-\Hat{\psi}^{(2)}_N.
        \]
    \end{proposition}
    \begin{proof}
        Invoking \cite[Propositions 3.2, 4.8]{Viklund/Lawler} according to Ref. \cite{Viklund/Lawler} , we can find $0<\beta<1$ with $\sup_{0\leq t\leq T}|\eta_t-\eta_{t_k(t)}|\leq C^\prime(\omega)N^{-(1-\beta)/2}$, $\mathbb{P}$-a.s. It follows from \cite[Lemma 6.7]{Foster/Lyons/Margarint} that $\sup_{0\leq t\leq T}|Z_t(iy_N)-Z_{t_k(t)}(iy_N)|\leq2C(\omega)N^{-(1-\delta)/2}+C^\prime(\omega)N^{-(1-\beta)/2}$. Now we take $\mathcal{A}^{(2)}_N\coloneqq\mathcal{A}^{(1)}_N\cap\{C^\prime(\omega)\leq N^{(1-\beta)/4}\}$. Then $\Hat{\psi}^{(2)}_N\coloneqq\Hat{\psi}^{(1)}_N+\mathbb{P}(C^\prime(\omega)\geq N^{(1-\beta)/4})\to0+$ monotonically and
        \begin{equation*}\begin{aligned}
            &\mathbb{E} \big[ \int_0^T|Z_t(iy_N)-Z_{t_k(t)}(iy_N)|^{p}\,dt \vdot I_{\mathcal{A}_N^{(2)}} \big] \leq \mathbb{E} \big[ \normx{Z(iy_N) - \sum_{k<N} Z_{t_k}(iy_N)\mathbbm{1}_{[t_k,t_k+h_k)} }_{T}^{p},\, \mathcal{A}_n^{(2)} \big]\\ 
            &\qquad \leq 2^{2p-1} N^{-p(1-\delta)/4} + 2^{p-1} N^{-p(1-\beta)/4} \coloneqq\Tilde{\psi}^{(2)}_N\to0.
        \end{aligned}\end{equation*}
        And the assertion is verified.            
    \end{proof}

    %prop: estimate event A3
    \begin{proposition}\label{prop: estimate A3}
        \normalfont
        If $\abs{\mathcal{D}_N}\leq(4N+1)^{-3}$, we can find an event $\mathcal{A}^{(3)}_N$ and two decreasing sequences $\Tilde{\psi}^{(3)}_N\to0+$ and $\Hat{\psi}^{(3)}_N\to0+$ as $N\to\infty$ so that
        \[
            \mathbb{E} \bigg[ \int_0^T \big| Z_{t_k(t)}(iy_N)-\widetilde{Z}_{t_k(t)}(iy_N)\big|^p\,dt\vdot I_{\mathcal{A}_N^{(3)}} \bigg] \leq \Tilde{\psi}^{(3)}_N\qquad\text{with}\quad\mathbb{P}(\mathcal{A}_N^{(3)})\geq1-\Hat{\psi}^{(3)}_N.
        \]
    \end{proposition}
    \begin{proof}
        Invoking Proposition $\ref{prop: estimate event B3}$ and taking $\mathcal{A}^{(3)}_N\coloneqq\mathcal{B}^{(3)}_N$, we can choose $\Hat{\psi}^{(3)}_N\coloneqq2e^{-\kappa^{-1}(4N+1)}\to0+$. Furthermore,
        \begin{equation*}\begin{aligned}
            &\mathbb{E} \big[ \int_0^T |Z_{t_k(t)}(iy_N)-\widetilde{Z}_{t_k(t)}(iy_N)|^p\,dt\vdot I_{\mathcal{A}_n^{(3)}}\big] \leq \mathbb{E} \big[ \normx{\sum_{k<N} (Z_{t_k}(iy_N)-\widetilde{Z}_{t_k}(iy_N))\mathbbm{1}_{[t_k,t_k+h_k)} }_T^p,\, \mathcal{A}_N^{(3)} \big]\\
            &\qquad \leq (4N+1)^{-p/2} \coloneqq\Tilde{\psi}^{(3)}_N\to0.
        \end{aligned}\end{equation*}
        And the assertion is verified.
    \end{proof}

    To analyse the difference $|\widetilde{Z}_{t_k(t)}-\widetilde{Z}_t|$ for $t_k\leq t<t_k+h_k$, we need some famous results \cite[Section 6.5]{Folland} on the interpolation between Lebesgue function spaces. For any $1<p<r<q$ and $f\in L^p[0,T]\cap L^q[0,T]$, we have $f\in L^r$ with $\normx{f}_{L^r}^{1/p-1/q}\leq \normx{f}_{L^p}^{1/r-1/q}\normx{f}_{L^q}^{1/r-1/q}$. On the other hand, we can express the supremum Brownian motion via Gamma functions \cite[Corollary 2.2]{Boukai} as $\mathbb{E}[\sup_{0\leq s\leq t}\abs{B_s}^{2k}]=\pi^{-1/2}(2t)^{k}\Gamma(k+1/2)$ for all $t\in\mathbb{R}_+$ and $k\geq1$.

    %prop: estimate event A4
    \begin{proposition}\label{prop: estimate A4}
        \normalfont
        If $\abs{\mathcal{D}_N}\leq N^{-1}$, we can find a decreasing sequence $\Tilde{\psi}^{(4)}_N\to0+$ as $N\to\infty$ so that
        \[
            \mathbb{E} \bigg[ \int_0^T \big| \widetilde{Z}_{t_k(t)}(iy_N) -\widetilde{Z}_t(iy_N)\big|^p\,dt \bigg] \leq \Tilde{\psi}^{(4)}_N,\qquad\forall~N\geq1.
        \]
    \end{proposition}
    \begin{proof}
        From Proposition \ref{prop: estimate event B4} we know $|\widetilde{Z}_{t_k}-\widetilde{Z}_t|^p\leq 2|\sqrt{\kappa}B_{t_k,t}|^p+2^{p+1}N^{-p/2}$, $\mathbb{P}$-a.s. Since $p\geq2$, there exists $\ell\geq1$ such that $2\ell\leq p<2(\ell+1)$. Notice also that $t-t_k\leq h_k\leq 1/N$ for each $0\leq k<N$. Then,
        \[
            \mathbb{E}\big[ \sup_{k<N} \normx{\sqrt{\kappa}B_{t_k+\vdot}}_{h_k}^{2\ell} \big] \leq \pi^{-1/2}(2\kappa/N)^{\ell}\Gamma(\ell+1/2),\qquad\forall~\ell\geq1.
        \]
        Hence in light of the Lebesgue interpolation relation, we get
        \begin{equation*}\begin{aligned}
            &\mathbb{E}\big[ \sup_{k<N} \normx{\sqrt{\kappa}B_{t_k+\vdot}}^p_{h_k} \big] \leq \mathbb{E}\big[ \sup_{k<N} \normx{\sqrt{\kappa}B_{t_k+\vdot}}^{2\ell}_{h_k} \big]^{\ell+1-p/2} \mathbb{E}\big[ \sup_{k<N} \normx{\sqrt{\kappa}B_{t_k+\vdot}}^{2(\ell+1)}_{h_k} \big]^{\ell(\ell+1-p/2)/(\ell+1)}\\ 
            &\qquad\leq CN^{-\ell(\ell+1-p/2)}\coloneqq\Tilde{\psi}^{(4)}_N\to0.
        \end{aligned}\end{equation*}
        And the assertion then follows.
    \end{proof}

    \begin{proof}[Proof of Theorem \ref{thm: Lp-norm convergence}.]
        Combining Propositions \ref{prop: estimate A1}, \ref{prop: estimate A2}, \ref{prop: estimate A3}, \ref{prop: estimate A4} and on the event $\mathcal{A}_N\coloneqq \mathcal{A}^{(1)}_N\cap\mathcal{A}^{(2)}_N\cap\mathcal{A}^{(3)}_N$ with $\psi_1(N)\coloneqq (\Tilde{\psi}^{(1)}_N)^{1/p} + (\Tilde{\psi}^{(2)}_N)^{1/p} + (\Tilde{\psi}^{(3)}_N)^{1/p} + (\Tilde{\psi}^{(4)}_N)^{1/p}$, given $\abs{\mathcal{D}_N}\leq(4N+1)^{-3}$ we have
        \begin{equation*}\begin{aligned}                        
        &\mathbb{E} \big[\int_0^T |\eta_t-\widetilde{Z}_t(iy_N)|^p\,dt\vdot I_{\mathcal{A}_N}\big]^{1/p} \leq \mathbb{E}\big[ \int_0^T |\eta_t -Z_t(iy_N)|^{p}\,dt\vdot I_{\mathcal{A}_N^{(1)}}\big]^{1/p} + \mathbb{E}\big[ \int_0^T|Z_t(iy_N)-Z_{t_k}(iy_N)|^{p}\,dt \vdot I_{\mathcal{A}_N^{(2)}} \big]^{1/p}\\ 
        &\qquad+ \mathbb{E}\big[\int_0^T|Z_{t_k}(iy_N)-\widetilde{Z}_{t_k}(iy_N)|^p\,dt\vdot I_{\mathcal{A}_N^{(3)}}\big]^{1/p} + \mathbb{E}\big[\int_0^T|\widetilde{Z}_{t_k}(iy_N)-\widetilde{Z}_t(iy_N)|^p\,dt\big]^{1/p} \leq  \psi_1(N)^{1/p}\to0,
    \end{aligned}\end{equation*}
    where $1-\mathbb{P}(\mathcal{A}_N)\leq\psi_2(N)\coloneqq\Hat{\psi}^{(1)}_N+\Hat{\psi}^{(2)}_N+\Hat{\psi}^{(3)}_N\to0+$. And the assertion is then verified.
    \end{proof}



