\section{Fokker-Planck equation in Hermite polynomial basis \label{app}}

Since it will frequently arise,  we note the orthogonality relation
\begin{eqnarray}
\int_{-\infty}^\infty \frac{\mathcal{H}_m(x)}{\sqrt{\sigma^m m!}} \frac{\mathcal{H}_n(x)}{\sqrt{\sigma^n n!}} \frac{e^{-x^2/2\sigma}}{\sqrt{2 \pi \sigma}} dx
&=& \delta_{n,m}.
\end{eqnarray}
We start with the normalisation condition that $\int_{-\infty}^\infty dD \Tr\{\rho_t(D)\}=1$.  Using the orthogonality relation, we can write this as,
\begin{eqnarray}
\int_{-\infty}^\infty dD \, \Tr\{\rho_t(D)\} &=& \sum_{n=0}^{N-1} \Tr(M_n) \int_{-\infty}^\infty dD  \frac{\mathcal{H}_n(D)}{\sqrt{\sigma^n n!}} \frac{e^{-D^2/2\sigma}}{\sqrt{2 \pi \sigma}} \\
&=& \sum_{n=0}^{N-1} \Tr(M_n) \delta_{n,0} \\
&=& \Tr(M_0).
\end{eqnarray}
So the normalization condition simplifies to $\Tr(M_0)=1$, where $\int dD \rho_t(D) = \sum_n M_n \delta_{n,0}=M_0$ describes the state of the system when ignorant of the measurement outcome.

We now move on to the main equation.  Our strategy will be to insert our ansatz for the state, Eq. \eqref{ansatz} into the Eq. \eqref{FP_eq} and compute each term by applying $\int_{-\infty}^\infty dD \,\mathcal{H}_m(D)/\sqrt{\sigma^m m!}$ and utilizing the orthogonality relation (this is often indicated by an arrow $\rightarrow$).  

We start with the time derivative which only acts on the $M_n$ matrices leading to $\sum_{n=0}^{N-1} \dot{M}_n  \delta_{n,m}=\dot{M}_m$.  Next,  we will consider the first term on the right hand side of Eq.  \eqref{FP_eq}.  This is the outcome dependent Lindblad operator $\mathcal{L}(D)$.  This gives
\begin{eqnarray}
\sum_{n=0}^{N-1}   \int_{-\infty}^\infty dD \frac{\mathcal{H}_m(D)}{\sqrt{\sigma^m m!}}  \frac{\mathcal{H}_n(D)}{\sqrt{\sigma^n n!}} \frac{e^{-D^2/2\sigma}}{\sqrt{2 \pi \sigma}} \mathcal{L}(D)  M_n . \label{feed_term}
\end{eqnarray}
We write this in full generality as $\mathcal{L}(D)=\mathcal{L}_0+ \sum_p f_p(D) \mathcal{L}_p$. Altogether then Eq. \eqref{feed_term} simplifies to $\mathcal{L}_0 M_m + \sum_{n=0}^{N-1}  \sum_p \alpha_{n,m,p} \mathcal{L}_p M_n$ where
\begin{eqnarray}
\alpha_{n,m,p}(t)= \int_{-\infty}^\infty dD \frac{\mathcal{H}_m(D)}{\sqrt{\sigma^m m!}}  \frac{\mathcal{H}_n(D)}{\sqrt{\sigma^n n!}} \frac{e^{-D^2/2\sigma}}{\sqrt{2 \pi \sigma}}  f_p(D).
\end{eqnarray}

Moving on to the measurement back action term,  it simplifies as $-\frac{\lambda}{2}\sum_{n=0}^{N-1} \left[A,\left[A,M_n\right] \right] \delta_{n,m}=-\frac{\lambda}{2}\left[A,\left[A,M_m\right]\right]$ where  $[\cdot,\cdot]$ is the commutator. The second last term in Eq. \eqref{FP_eq} (describing the overall drift) is given by
\begin{eqnarray}
-\gamma \partial_D \mathcal{C}_{A-D} \rho_t(D)/2 &=& -\frac{\gamma}{2} \partial_D \{A-D,\rho_t(D)\} \\
&=& -\frac{\gamma}{2} \left[\{-1,\rho_t(D)\} + \{A-D,  \partial_D \rho_t(D)\} \right],
\end{eqnarray}
where we write the identity as $1$.  In order to evaluate $\partial_D \rho_t(D)$,  we note that
\begin{eqnarray}
\partial_D \left[ \mathcal{H}_n(D) e^{-D^2/2\sigma} \right]= -e^{-D^2/2\sigma} \sigma^{-1} \mathcal{H}_{n+1}(D).
\end{eqnarray}
Inserting the ansatz Eq.\eqref{ansatz} and applying $\int_{-\infty}^\infty dD \,\mathcal{H}_m(D)/\sqrt{\sigma^m m!}$ the drift term can be evaluated in separate parts as,
\begin{eqnarray}
\{-1,\rho_t(D)\}  &\rightarrow& \sum_n \{-1,M_n\} \delta_{n,m} \\
&=& \{-1,M_m\} \\
&=& - 2 M_m,
\end{eqnarray}
and
\begin{eqnarray}
\{A,  \partial_D \rho_t(D)\} &\rightarrow& -\sigma^{-1} \sum_n  \{A, M_n \} \delta_{n+1,m} \sqrt{(n+1)\sigma} \\
&=& -\sqrt{\frac{m}{\sigma}} \{A, M_{m-1} \}.
\end{eqnarray}
For the final part,  we will exploit the shift rule that $x \mathcal{H}_n(x)= \mathcal{H}_{n+1}(x)+ n \sigma \mathcal{H}_{n-1}(x)$. The last part is then
\begin{eqnarray}
\{-D,  \partial_D \rho_t(D)\} &=& - 2 D \, \partial_D \rho_t(D) \\
&=&  2 D \sigma^{-1} \sum_n M_n \frac{\mathcal{H}_{n+1}(D)}{\sqrt{\sigma^n n!}} \frac{e^{-D^2/2\sigma}}{\sqrt{2 \pi \sigma}} \\
&= &  2  \sigma^{-1} \sum_n M_n \frac{1}{\sqrt{\sigma^n n!}} \frac{e^{-D^2/2\sigma}}{\sqrt{2 \pi \sigma}} \left[\mathcal{H}_{n+2}(D)+ (n+1)\sigma \mathcal{H}_n(D) \right] \\
&\rightarrow & 2  \sigma^{-1} \sum_n M_n \left[ \delta_{n+2,m} \sqrt{(n+2)(n+1)} \sigma+(n+1)\sigma \delta_{n,m} \right] \\
&=& 2   \left[ \sqrt{m(m-1)} M_{m-2} + (m+1) M_m \right].
\end{eqnarray}

Finally,  then we tackle the very last term in Eq. \eqref{FP_eq},  which can be thought of as a diffusion.  It can then be expressed as
\begin{eqnarray}
\frac{\gamma^2}{8 \lambda} \partial_D^2 \rho_t(D) &\rightarrow& \frac{\gamma^2}{8 \lambda} \frac{1}{\sigma^2} \sum_n M_n \delta_{n+2,m} \sqrt{(n+2)(n+1)} \sigma \\
&=& \frac{\gamma^2}{8 \lambda} \frac{\sqrt{m(m-1)}}{\sigma} M_{m-2} \\
&=& \gamma \sqrt{m(m-1)} M_{m-2}.
\end{eqnarray}

In complete summary,  the equation can then be written as the coupled differential equation
\begin{eqnarray}
\dot{M}_m = \mathcal{L}_0 M_m + \sum_{n=0}^{N-1}  \sum_p \alpha_{n,m,p} \mathcal{L}_p M_n -\frac{\lambda}{2}\left[A,\left[A,M_m\right]\right] -\frac{\gamma}{2} \left[ 2 m M_m-\sqrt{\frac{m}{\sigma}}   \{A,M_{m-1}\}  \right],
\end{eqnarray}
for each $m$ with the normalization condition $\Tr(M_0)=1$.  Note that $M_{-1}=0$.

\section{Matrix coefficients for polynomial feedback \label{app0}}
We wish to compute the coefficients $\alpha_{n,m,p}$ for a polynomial feedback function $f_p(D)=D^p$. This can be computed by noting that $\alpha_{n,m,0}=\delta_{n,m}$ and the recursive relation for this case
\begin{eqnarray}
    \alpha_{n,m,p} &=& \sqrt{\sigma (m+1)} \alpha_{n,m+1,p-1} + \sqrt{\sigma m} \alpha_{n,m-1,p-1}.
\end{eqnarray}
For example, the quadratic case is
\begin{eqnarray}
    \alpha_{n,m,2} &=& \sigma \sqrt{(m+1) (n+1)} \delta_{m+1,n+1} + \sigma \sqrt{n(m+1)} \delta_{m+1,n-1}+  \sigma \sqrt{m(n+1)} \delta_{n+1,m-1} + \sigma \sqrt{n m}  \delta_{n-1,m-1}.
\end{eqnarray}

\section{Informational quantities \label{app2}}

In the following, we outline some useful informational quantities that can be computed from the joint state.

\subsection{Mutual information between system and detector}
We consider the mutual information between the system and detector.  This can be expressed as
\begin{eqnarray}
\mathcal{I} = S \left[\int dD \rho_t(D) \right] + S \left[ \Tr\{\rho_t(D)\} \right]- S \left[ \rho_t(D) \right],
\end{eqnarray}
where $S \left[ \cdot \right]$ is either the von-Neumann or Shannon entropy depending on the input.  We simplify each term separately.  The first part is simply
\begin{eqnarray}
S \left[\int dD \rho_t(D) \right] &=& S[M_0] \\
&=& - \Tr M_0 \ln M_0.
\end{eqnarray}
The second term can be expanded as
\begin{eqnarray}
S \left[ \Tr\{\rho_t(D)\} \right] &=& S[P(D)] \\
&=& - \int dD P(D) \ln P(D).
\end{eqnarray}
The final term is then
\begin{eqnarray}
S \left[ \rho_t(D) \right] &=&- \int dD \, \Tr \left\{\rho_t(D) \ln \rho_t(D) \right\} .
\end{eqnarray}

By defining the density matrix given the outcome $D$ as $\tilde{\rho}_t(D)=\rho_t(D)/P(D)$ one can show that the mutual information is equivalent to
\begin{eqnarray}
    \mathcal{I}=-\int dD \, S\left[ \tilde{\rho}_t(D) \right] P(D)+S[M_0].
\end{eqnarray}
For a Hilbert space of dimension $R$, the maximum of this mutual information is then $\ln R$.

\subsection{Correlation}
If an observable has a spectral decomposition $B=\sum_n b_n \ketbra{b_n}{b_n}$, then there is a joint probability distribution $P(b_n,D)=\bra{b_n} \rho(D) \ket{b_n}$. One can then ask about the covariance of this distribution.

The expected measurement outcome is given by
\begin{eqnarray}
    \avg{D} &=& \int dD D P(D) \\
    &=&\sqrt{\sigma} c_1.
\end{eqnarray}
Similarly we have that for $B$, the unconditional expectation is
\begin{eqnarray}
    \avg{B} &=& \tr (M_0 B).
\end{eqnarray}
We define the covariance as
\begin{eqnarray}
    \rm{cov}(B) &=& \tr \int dD B D \rho(D) - \avg{D} \cdot \avg{B} \\
    &=& \sqrt{\sigma} \tr(M_1 B) - \sqrt{\sigma} c_1 \tr (M_0 B) \\
    &=& \sqrt{\sigma} \left[ \tr(M_1 B) -  \tr(M_1) \tr (M_0 B) \right].
\end{eqnarray}
This follows from the identity
\begin{eqnarray}
    \int dD D \frac{\mathcal{H}_n(D)}{\sqrt{\sigma^n n!}} \frac{e^{-D^2/2\sigma}}{\sqrt{2 \pi \sigma}} &=& J_n(1) \\
    &=& \sqrt{\sigma (n+1)} \delta_{n+1,0} + \sqrt{n \sigma} \delta_{n-1,0} \\
    &=&  \sqrt{n \sigma} \delta_{n-1,0},
\end{eqnarray}
since $n \geq 0$. Note that $\rm{Cov}(B)$ is identically zero if $M_1=0$, which is the case for a product state between system and detector. 

\section{Two time correlation of filtered output current \label{app3}}
We want to compute $\avg{D(t)D(s)}$, which is explicitly given by
\begin{eqnarray}
    \avg{D(t)D(s)} = \int_{-\infty}^t \int_{-\infty}^s dt_2 dt_1 \gamma^2 e^{-\gamma (t-t_2+s-t_1)} \avg{z(t_1) z(t_2)}.
\end{eqnarray}
The expression for the term inside the integral is given in steady state by \cite{Landi2024},
\begin{eqnarray}
    \avg{z(t)z(t+t')} &=&  \frac{1}{4 \lambda} \delta(t') + \frac{1}{4} \Tr \left[\mathcal{C}_A e^{\Lambda t'} \mathcal{C}_A M_0\right] \\
    &=&  \frac{1}{4 \lambda} \delta(t') + \Tr(A M_0)^2 + \frac{1}{2}\sum_{j \neq 0} e^{\eta_j t'} \Tr(A x_j) \Tr(y_j^\dagger \{A,M_0\}),
\end{eqnarray}
where we have used the spectral decomposition of $\Lambda$ and assumed no feedback. The end result is
\begin{eqnarray}
    \avg{D(t+\tau)D(t)} &=& \gamma^2 \int_{-\infty}^{t+\tau} \int_{-\infty}^t dt_2 dt_1 e^{-\gamma (2t+\tau-t_2-t_1)} \left\{ \frac{1}{4 \lambda} \delta(t_2-t_1) + \Tr(A M_0)^2 + \frac{1}{2}\sum_{j \neq 0} e^{\eta_j |t_2-t_1|} \Tr(A x_j) \Tr(y_j^\dagger \{A,M_0\}) \right\} \\
   &=& \sigma e^{-\gamma \tau} + \Tr(A M_0)^2 + \frac{1}{2} \sum_{j \neq 0}  \frac{\gamma  \left(\gamma  e^{\tau  \eta
   _j}+e^{-\gamma  \tau } \eta _j\right)}{\gamma
   ^2-\eta _j^2} \Tr(A x_j) \Tr(y_j^\dagger \{A,M_0\}).
\end{eqnarray}
The $\tau=0$ case matches the result from the methods in the main text. Since the average filtered detector outcome in steady state is $\avg{D}=\Tr(A M_0)$, we can write our final result as
\begin{eqnarray}
C(\tau) &=& \avg{D(t+\tau)D(t)}-\avg{D(t)}^2\\
     &=&\sigma e^{-\gamma \tau} + \frac{1}{2} \sum_{j \neq 0}  \frac{\gamma  \left(\gamma  e^{\tau  \eta
   _j}+e^{-\gamma  \tau } \eta _j\right)}{\gamma
   ^2-\eta _j^2} \Tr(A x_j) \Tr(y_j^\dagger \{A,M_0\}).
\end{eqnarray}

