\section{Strength criteria, Mohr's representation of the stress, and  intrinsic curves}
\label{sec:strength}
The mathematical and phenomenological properties of the energy of the phase-field model defined by the energy functional~\eqref{eq:phase-field-energy} strongly depends on the choice of the strength criteria $\K_0$. 
This section revisits classical isotropic strength criteria and introduces a complementary characterization of stress states that are compatible with displacement jumps.
To this end, we draw upon and extend tools from the theory of Limit Analysis~\cite{DruPra52,Sal83}, including the representation of stress tensors via Mohr's circles and the description of material strength through their envelopes, referred to as intrinsic domains.  

\subsection{Mohr's circles and their envelopes}
\label{sec:Mohr}
The material of this sub-section is classical within the field of strength of materials, but we are not aware of a self-contained reference that presents them in a form accessible to a mathematically oriented audience.
For this reason, we provide a formal presentation of the key notions of the fundamental properties that will be used throughout the remainder of the paper.


\subsubsection{Mohr's representation of the stress vector }
% \BB{Mohr representation or Mohr's representation?}
Let $\sig$ be a stress tensor, $\n\in\mathbb{S}^2$ be a unit vector, and $\sig\n\in\mathbb{R}^3$ be the associated stress vector.
We can write
\begin{equation}
    \label{decomp}
    \sig\n = \Sigma\, \n + \mathbf{T},
\end{equation}
with $\Sigma = \sig\n\cdot \n $ and $\mathbf{T} \in \n^\perp := \left\{ \mathbf{v} \in \mathbb{R}^3; \n \cdot \mathbf{v} = 0\right\}$.
Let $(\mathbf{i},\mathbf{j})$ be an orthonormal basis of $\n^\perp$, and $T_1,T_2$ be the components of $\T$ in this basis.
We have that  
\[
    \|\T\|^2 = T_1^2+T_2^2,\qquad    \|\sig\n\|^2 = \Sigma^2 + \|\T\|^2.
\]


\begin{remark}[Parallel transport of the tangential components of the stress vector]
The orthonormal basis $(\mathbf{i},\mathbf{j})$ is of course not unique, and therefore neither are $T_1$ and $T_2$.
Consider however a unit vector $\n$ on the sphere $\mathbb S^2$ and an orthogonal basis $(\mathbf{i},\mathbf{j})$ of its tangent space plane.
Given any unit vector $\n^*$, we can use a parallel transport to build an orthonormal basis $(\mathbf{i}^*,\mathbf{j})^*$ of its tangent space, which allows us to compare the components $\Sigma, T_1,T_2$ of the stress vector $\sig \n$ when $\sig$ or $\n$ vary.
Up to the definition of a single reference basis $(\mathbf{i},\mathbf{j})$, we can therefore represent $\sig\n $ in terms of the triplet $(\Sigma, T_1, T_2)$ and $\T$ in terms of $(T_1,T_2)$.
We refer to these characterizations as their Mohr's representation.
Note in particular that $(\Sigma, T_1, T_2)$ depends linearly on $\sig$. 
\end{remark}

Let $\{\sigma_1,\sigma_2,\sigma_3\}$ be the eigenvalues of $\sig$ and 
$\{\mathbf{e}_1,\mathbf{e}_2,\mathbf{e}_3\}$ the corresponding eigenvectors, which form an orthonormal basis of $\mathbb{R}^3$. 
Here and henceforth, we use roman numbering to denote eigenvalues and matching eigenvectors ordered so that 
($\sigI\geq\sigII\geq\sigIII$).

By~\eqref{decomp}, we have that
\[
    \left\|\sig \n -\left(\frac{\sigI+\sigIII}{2}\right)\n\right\|^2 = \left| (\sig \n) \cdot \n - \left(\frac{\sigI+\sigIII}{2}\right)\right|^2 + \|\T\|^2.
\]
Writing then 
\[
    \n=n_\mathrm{I}\,\mathbf{e}_\mathrm{I}+n_{\mathrm{II}}\,\mathbf{e}_\mathrm{II}+n_\mathrm{III}\,\mathbf{e}_\mathrm{III},
\]
we have that 
\[
    \sig \n = \sigI n_\mathrm{I}\,\mathbf{e}_\mathrm{I}+ \sigII n_{\mathrm{II}}\,\mathbf{e}_\mathrm{II}+\sigIII n_\mathrm{III}\,\mathbf{e}_\mathrm{III},
\]
from which we derive that 
\[
    \left\|\sig \n -\left(\frac{\sigI+\sigIII}{2}\right)\n\right\|^2 = \left(\frac{\sigI-\sigIII}{2}\right)^2 \left(n_\mathrm{I}^2+n_\mathrm{II}^2\right)+\left(\sigII- \left(\frac{\sigI+\sigIII}{2}\right)^2\right)n_\mathrm{III}^2. 
\]
Noticing that $\left|\sigII - \left(\frac{\sigI+\sigII}{2}\right) \right| \le \left|\frac{\sigI-\sigIII}{2}\right|$, we obtain that 
\begin{equation}
    \label{MajMohr}
    \left(\Sigma-\frac{\sigI+\sigIII}{2}\right)^2+T_1^2+T_2^2\le \left(\frac{\sigI-\sigIII}{2}\right)^2.
\end{equation}
This proves that in its Mohr representation, the stress vector $\sig\n$ belongs to the sphere of radius $\frac{\sigI-\sigIII}{2}$ centered at $\left(\frac{\sigI+\sigIII}{2},0,0\right)$. 
% The projection of this sphere on the plane $\Sigma,T$ is the \emph{outer Mohr's circle}. 

Consider a vector $\n$ in the plane $(\mathbf{e}_\mathrm{III}, \mathbf{e}_\mathrm{I})$ and let $\theta$ be the angle between $\n$ and $\mathbf{e}_\mathrm{III}$ (\emph{i.e.} the polar angle of $\n$ in the basis $\mathbf{e}_\mathrm{III},\mathbf{e}_\mathrm{I}$ is $-\theta$)
\[
    \n = \cos \theta \mathbf{e}_\mathrm{I} - \sin \theta \mathbf{e}_\mathrm{III},
\]
and let 
\[
    \t = \sin \theta \,\mathbf{e}_\mathrm{I} + \cos \theta\, \mathbf{e}_\mathrm{III}
\]
be a unit vector orthogonal to $\n$ in the same plane, see Figure~\ref{fig:F-Angle}-left.
Then
\[
    \sig\n = \sigI\cos \theta \mathbf{e}_\mathrm{I} -\sigIII\sin \theta \mathbf{e}_\mathrm{III}
\]
is also in the plane $(\mathbf{e}_\mathrm{III}, \mathbf{e}_\mathrm{I})$.
If for $\theta=0$ (\emph{i.e.} $\n = \mathbf{e}_\mathrm{I}$), we chose $\mathbf{i} = \mathbf{e}_\mathrm{III}$ and $\mathbf{j} = \mathbf{e}_\mathrm{II}$ and use the parallel transport of this basis for all $\theta$, the Mohr representation of $\sig\n$ is of the form $(\Sigma,T_1,0)$, \emph{i.e.} $T_2 = 0$.
The decomposition~\eqref{decomp} gives then
\begin{equation}
    \label{eq:GCMohr}
    \Sigma=\frac{\sigIII+\sigI}2+\frac{\sigI-\sigIII}2\cos 2\theta,\quad T_1=\frac{\sigI-\sigIII}2\sin 2\theta.
\end{equation}
Similar constructions with $\sig\n$ in the plane $(\mathbf{e}_\mathrm{I}, \mathbf{e}_\mathrm{II})$ and $(\mathbf{e}_\mathrm{II}, \mathbf{e}_\mathrm{III})$ give respectively the two inner Mohr's circles.
Note that these are not relevant in this work so that in all that follows, we will refer to the outer Mohr's circle as \emph{the} Mohr's circle.



