    \centering
    \includegraphics[width=2.in]{F-Mohr-ref.pdf} 
    \includegraphics[width=3.in]{F-Mohr.pdf} 
    \caption{Left: Orientation of reference system $\boldsymbol{t}-\boldsymbol{n}$ and definition of the angle $\theta$. Right: Mohr's representation in the section $T_2=0$ of the space $(\Sigma,T_1,T_2)$  showing the section of the intrinsic domain $\mathcal K_0$ and   a Mohr's circle tangent to  its boundary. The stress vector $\sig \n$ corresponding to the point of contact between the circle and $\partial\mathcal K_0$ determines also the orientation  $\theta$ of the normal and the direction of displacement jump $\mathbf{d}$, which must be in the normal cone of $\mathcal K_0$ at  $\sig \n$.}
    \label{fig:F-Angle}
