\subsubsection{Intrinsic domain for an isotropic strength criterion}
\label{sec:intrinsic-curve}
Suppose that $\mathbf{0} \in \mathring{\K}_0$ and that $\K_0$ is bounded in at least in one direction.
For any unit vector $\n \in \mathbb{S}^2$, we define
\begin{equation}
    \label{eq:defcalK0}
    \mathcal{K}_0(\n) := \left\{\sig\n;\ \sig \in \K_0 \right\}.
\end{equation}
As the image of a convex set by a linear application, $\mathcal{K}_0(\n)$ itself is convex.
Using~\eqref{eq:GCMohr}, we also see that $\mathcal{K}_0(\n)$ is contained in the union of the spheres of center $C=((\sigI+\sigIII)/2,0,0)$ and radius $R=(\sigI-\sigIII)/2$.


When $\K_0$ is \emph{isotropic}, \emph{i.e.}
\begin{equation}
    \label{eq:defIsotropy}
    \Q^T\sig\Q \in \K_0\  \forall \sig \in \K_0,\ \Q \in SO(3),
\end{equation}
where $SO(3)$ is the group of rotations in $\mathbb{R}^3$, it is possible to fully describe $\mathcal{K}_0(\n)$ in terms of the outer Mohr's circle.

We begin by establishing the following property :
\begin{proposition}
    \label{prop:Kappa0n}
  Let $\K_0$ be a closed convex isotropic subset of $\mathbb{M}^3_s$ containing $\mathbf{0}$.
  Then $\mathcal K_0(\n)$ in $\mathbb R^3$ is a surface of revolution around the axis $(\Sigma,T_1,T_2)=(1,0,0)$ and is independent of $\n$. 
  We refer to it as the \emph{intrinsic domain} of admissible stress vectors.
\end{proposition}

\begin{proof}
    Let us first show that for a fixed $\n$, $\mathcal K_0(\n)$ is a surface of revolution around the axis $(\Sigma,T_1,T_2)=(1,0,0)$. 
    Since $\sig = \mathbf 0 \in \K_0$, we have $(0,0,0) \in \mathcal K_0(\n)$. Let $\mathcal I(\n)$ be the intersection of $\mathcal K_0(\n)$ with the axis $(1,0,0)$. 
    Let us take $\Sigma \in \mathcal I(\n)$; then there exists $\sig \in \K_0$ such that $\sig\n \cdot \n = \Sigma$. 
    By isotropy, all tensors $\sig^* = \Q\sig\Q^T$ with $\Q \in \Orth3$ leaving $\n$ invariant, \emph{i.e.}, $\Q\n = \n$, also belong to $\K_0$, and hence $\sig^*\n$ belongs to $\mathcal K_0(\n)$. Moreover, $\sig^*\n \cdot \n = \Sigma$, and defining $\T^* := \sig^*\n - \Sigma\,\n = \Q\T$, where $\T = \sig\n - \Sigma\,\n$, we find $\norm{\T^*} = \norm{\T}$. By varying $\Q$, we generate all vectors $\T^*$ orthogonal to $\n$ having the same norm as $\T$. Consequently, for fixed $\Sigma$, all triplets $(\Sigma, T_1, T_2)$ with the same norm belong to $\mathcal K_0(\n)$, which is the desired property.

    Let us introduce
    $$\overline T_\n(\Sigma) = \sup_{(\Sigma, T_1, T_2) \in \mathcal K_0(\n)} \sqrt{T_1^2 + T_2^2}$$
    which, for a given admissible normal stress, gives the maximum possible norm of the tangential stress. To show that $\mathcal K_0(\n)$ is independent of $\n$, it suffices to show that both $\mathcal I(\n)$ and $\overline T_\n$ are independent of $\n$.
    \begin{itemize}
        \item \emph{ $\mathcal I(\n)$ is independent of $\n$.} Let $\n \in \mathbb S^2$, $\Sigma \in \mathcal I(\n)$, $\Q \in \Orth3$, and $\n^* = \Q\n$. Then there exists $\sig \in \K_0$ such that $\sig\n \cdot \n = \Sigma$, and hence $\sig^* = \Q\sig\Q^T \in \K_0$ and $\sig^*\n^* \cdot \n^* = \Sigma$, so that $\Sigma \in \mathcal I(\n^*)$. Therefore, $\mathcal I(\n) \subset \mathcal I(\n^*)$. Reversing the roles of $\n$ and $\n^*$ gives the reverse inclusion and thus equality. Since $\n$ and $\n^*$ can be chosen arbitrarily in $\mathbb S^2$, $\mathcal I(\n)$ is independent of $\n$. We now denote this interval simply as $\mathcal I$.

        \item \emph{ $\overline T_\n$ is independent of $\n$.} Let $\n \in \mathbb S^2$, $\Sigma \in \mathcal I$, $\Q \in \Orth3$, and $\n^* = \Q\n$. Then there exists $\sig \in \K_0$ such that $\sig\n \cdot \n = \Sigma$. Furthermore, the tangential stress $\T = \sig\n - \Sigma\,\n$ satisfies $\norm{\T} \le \overline T_\n(\Sigma)$. Then $\sig^* = \Q\sig\Q^T \in \K_0$, $\sig^*\n^* \cdot \n^* = \Sigma$, and $\T^* := \sig^*\n^* - \Sigma\,\n^* = \Q\T$. Since $\norm{\T} = \norm{\T^*} \le \overline T_{\n^*}(\Sigma)$, we have $\overline T_\n(\Sigma) \le \overline T_{\n^*}(\Sigma)$. Reversing the roles of $\n$ and $\n^*$ gives the reverse inequality, hence equality. Since $\Sigma$ is arbitrary in $\mathcal I$, the invariance property is established.
    \end{itemize}
\end{proof}

In all that follows, we will focus on isotropic strength domains, which can be described in the following way.

\begin{definition}[Intrinsic domain]
    \label{def:intrinsic}
Let $\K_0 \subset \mathbb{M}^3_s$ be an isotropic strength domain containing $\mathbf{0}$.
The \emph{intrinsic domain} associated to $\K_0$ is
\begin{equation}
    \label{eq:domint}
    \mathcal{K}_0 := \left\{(\Sigma,T_1,T_2) \in \mathbb{R}^3:\ \Sigma\in\mathcal I,\ \sqrt{T_1^2+T_2^2} \le \overline{T}(\Sigma)\right\}.
\end{equation}
\end{definition}

The following fundamental property, illustrated in~Figure~\ref{fig:F-Angle}-right establishes the link between Mohr's circles and intrinsic domains:
\begin{proposition}
The meridian section $\mathcal {S}_0$ of $\mathcal{K}_0$ associated with the isotropic strength criterion $\K_0$ (see Figure~\ref{fig:F-Angle}) is the envelope of all Mohr's circles that are compatible with the strength criterion, \emph{i.e.} all circles in the Mohr's plane $(\Sigma,T_1,0)$ defined by the equation
$$\left(\Sigma-\frac{\sigI+\sigIII}{2}\right)^2+T_1^2=\frac{(\sigI-\sigIII)^2}{4},
$$
where $(\sigI,\sigIII)$ are the maximum and minimum principal stresses  of some stress tensor $\sig \in \K_0$.
\end{proposition}

In the statement of the property, the word {\it circle} can be replaced by {\it disk}, since, by convexity, if the circle is contained in $\mathcal S_0$, then the entire disk is as well.


\begin{proof}
Let $\sigI \ge \sigIII$ be the extreme principal stresses of some $\sig \in \K_0$ with associated principal directions $\mathbf e_\mathrm{I}$ and $\mathbf e_\mathrm{III}$. 
Choosing $\n$ in the plane $(\mathbf e_\mathrm{III}, \mathbf e_\mathrm{I})$, the stress vector $\sig\n$ traces the corresponding Mohr's circle when $\n$ varies in that plane.

We first show that this circle lies in a meridian plane of $\mathcal K_0$, which depends on the chosen basis $(\mathbf i, \mathbf j)$ of the tangent plane to the unit sphere at $\mathbf e_\mathrm{I}$, and on the principal directions $(\mathbf e_\mathrm{I}, \mathbf e_\mathrm{III})$. When $\theta = 0$, the direction of the tangential stress is $\t = \mathbf e_\mathrm{III}$, whose components in the tangent plane to the sphere at $\mathbf e_\mathrm{I}$ are $(\mathbf i \cdot \mathbf e_\mathrm{III}, \mathbf j \cdot \mathbf e_\mathrm{III})$.
As $\theta$ varies, the vector $\n$ moves along the unit sphere, rotating around $\mathbf e_\mathrm{II}$ since it remains in the plane $(\mathbf e_\mathrm{III}, \mathbf e_\mathrm{I})$. 
Because of the parallel transport of  $(\mathbf i, \mathbf j)$, $\t$ remains orthogonal to both $\n$ and $\mathbf e_\mathrm{II}$, and its components in the transported basis remain unchanged. Thus, the  Mohr's circle lies in the meridional plane generated by $(1,0,0)$ and $(0, \mathbf i \cdot \mathbf e_\mathrm{III}, \mathbf j \cdot \mathbf e_\mathrm{III})$.

By applying an orthogonal transformation $\Q$ fixing $\mathbf e_\mathrm{I}$ and mapping $\mathbf e_\mathrm{III}$ to $\mathbf i$, we can align the circle with the plane $T_2 = 0$. Hence, $\mathcal S_0$ contains all Mohr's circles associated with $\K_0$. Therefore, the intrinsic section contains all major Mohr's circles compatible with $\K_0$. 

Finally, by~\eqref{MajMohr}, no point in $\mathcal S_0$ can lie outside the envelope of these circles. Therefore, $\mathcal S_0$ is precisely their envelope.
\end{proof}

In the following, the support function of the convex set $\mathcal K_0$ will play a key role. By definition, this is the function $\H_{\mathcal K_0}$ defined on $\mathbb{R}^3$ and given by  
\begin{equation}\label{PiK}
\H_{\mathcal K_0}(\Delta,D_1,D_2): = 
\sup_{(\Sigma,T_1,T_2) \in \mathcal K_0} \{\Sigma\Delta + T_1D_1 + T_2D_2\},
\end{equation}  
where the triplet $(\Delta,D_1,D_2)$ can be interpreted as the component of the vector $\mathbf d = \Delta\,\n + \mathbf D$ in the same base used for the stress vector $\sig\n$, such that
$\sig\n \cdot \mathbf{d}=\Sigma\Delta + T_1D_1 + T_2D_2$.
We can also use the support function of $\K_0$ to express $\H_{\mathcal K_0}(\Delta,D_1,D_2)$. Indeed, since for any given $\n$, the set $\sig\n$ describes $\mathcal K_0$ when $\sig$ describes $\K_0$, we obtain  
\[
\H_{\mathcal K_0}(\Delta,D_1,D_2) = \H_{\K_0}(\n \odot \mathbf d).
\]  
In practice, this requires knowledge of $\n$, whereas the definition~\eqref{PiK} is intrinsic to the convex set $\mathcal K_0$ in $\mathbb{R}^3$.

\begin{remark}
    One could redefine the intrinsic domain by including the non-interpenetration condition. This would involve taking the envelope of Mohr's half-circles obtained by restricting $\Sigma$ with $\Sigma \geq (\sigIII + \sigI)/2$. Consequently, a different intrinsic curve would result. However, we will not do this here. We will consider applications where the non-interpenetration condition will be automatically satisfied. 
\end{remark}
% \CM{Add remark to say that non-isotropic is also possible but more complex?}
\subsection{Characterization of stress states compatible with the jump condition in terms of the Mohr's envelope $\mathcal{K}_0$}
In the case of isotropic strength criteria, the Mohr's representation and intrinsic sections allow for the following characterization of stress states admitting displacement jumps.


\begin{proposition}[Stress states compatible with displacement jumps]
    \label{prop:intrinsiccurvejump}
    Let $\K_0$ be convex and isotropic, $\sig \in \partial \K_0$ and $\boldsymbol{\nu} \in \mathrm{N}_{\K_0}(\sig)$.
    Suppose that there exists $\n \in \mathbb{S}^2$ and $\mathbf{d} \not = \mathbf{0}$ such that $\boldsymbol{\nu} = \n \odot \mathbf{d}$. Then, $\sig \n \in \partial \mathcal{K}_0$.
    Conversely, if there exists $\n \in \mathbb{S}^2$ such that $\sig \n \in \partial \mathcal{K}_0$, then for any  $\mathbf{d} \in \mathrm{N}_{\mathcal{K}_0}(\sig\n)$ with $\mathbf{d} \not =\mathbf{0}$, $\n \odot  \mathbf{d} \in \mathrm{N}_{\K_0}(\sig)$.
\end{proposition}
\begin{proof}
    Let $\sig \in\partial \K_0$ and $\boldsymbol{\nu} \in \mathrm{N}_{\K_0}(\sig)$. 
    Suppose that there exists a unit vector $\n$ and a non-zero vector $\mathbf{d}$ such that $\boldsymbol{\nu} =\n \odot \mathbf{d}$.
    Since $\sig \in \partial \K_0$, we have that for all $\sig^* \in \K_0$, 
    \[
        \sig \cdot \boldsymbol{\nu} \ge \sig^* \cdot \boldsymbol{\nu},
    \]
    and using the identity $\sig \cdot \n \odot \mathbf{d} = \sig \n \cdot \mathbf{d}$, we get that 
    \[
        \sig \n \cdot \mathbf{d} \ge \sig^* \n \cdot \mathbf{d},
    \]
    so that $\mathbf{d} \in \mathrm{N}_{\mathcal{K}_0}(\sig\n)$.
    Since $\mathbf{d} \not = \mathbf{0}$, by definition of the normal cone, we must then have that $\sig \n \in \partial \mathcal{K}_0$

    Conversely, suppose now that $\sig \n \in \partial \mathcal{K}_0$ and let $\mathbf{d} \in \mathrm{N}_{\mathcal{K}_0}(\sig\n)$. 
    For any $\sig^* \in \K_0$, we then have
    \[
        \sig \n \cdot \mathbf{d} \ge \sig^* \n \cdot \mathbf{d},
    \]
    so that 
    \[
        \sig \n \odot \mathbf{d} \ge \sig^* \n \odot \mathbf{d},
    \]  
    and $\n \odot \mathbf{d} \in \mathrm{N}_{\K_0}(\sig)$.

\end{proof}

As a direct consequence of the preceding proposition, we obtain the following characterization of stress states that allow displacement discontinuities.


\begin{proposition}
For an isotropic strength domain $\K_0$, displacement jumps are only possible for stress tensors $\sig \in \partial \K_0$ such that there exists a normal $\n \in \mathbb{S}^2$ for which $\sig\n \in \partial \mathcal{K}_0$.
This excludes all stress tensors $\sig$ whose largest associated Mohr's circle is entirely within the intrinsic domain.  
For those whose largest Mohr's circle is tangent to the intrinsic curve, displacement jump can only occur on the facet whose normal orientation $\n$ with respect to the extreme principal directions corresponds to the angle $\theta$ given by the point of tangency of Mohr's circle with the intrinsic curve (see Figures~\ref{fig:F-Angle}).  
Furthermore, for the non-penetration condition $\mathbf d\cdot\n \geq 0$ to be satisfied, the outward normal $\mathbf d \equiv (\Delta, D_1,D_2)$ to the intrinsic domain $\mathcal{K}_0$ must have its normal component $\Delta \geq 0$, which restricts the angle $\theta$ to the interval $[- \pi/4, \pi/4]$.
\end{proposition}

We illustrate the proposition above with the classical example of the von Mises and Tresca strength criteria.

\begin{example}
    The classical von Mises and Tresca strength criteria are defined by the following strength domains:
    \begin{align*}
            \text{von Mises}: 
            \mathbb{K}_0= &\left\{ \sig\in\mathbb M^3_s :\dfrac{\Vert\sig^D\Vert}{\sqrt{2}}=\sqrt{\dfrac{1}{6}}{\sqrt{(\sigI-\sigII)^2+(\sigII-\sigIII)^2+(\sigI-\sigIII)^2}}\leq\tau_c
            \right\},\\
            \text{Tresca}: 
            \mathbb{K}_0=&\left\{ \sig\in\mathbb M^3_s :\dfrac{\sigI-\sigIII}{2}\leq\tau_c
            \right\}.
    \end{align*}

    In the space of the (unordered) principal stresses $(\sigma_1,\sigma_2,\sigma_3)$, both criteria define cylinders with axis along the line $\sigma_1 = \sigma_2 = \sigma_3$. Figure~\ref{fig:VMvsTresca}-left shows their cross-section in the plane $\sigma_3 = 0$. The corresponding intrinsic domain $\mathcal{K}_0$ in Mohr's space $(\Sigma, T_1, T_2)$ is the envelope of the Mohr's circles associated with all admissible stress states. The Mohr's circle corresponding to a generic state with ordered principal stresses $(\sigI, \sigII, \sigIII)$ has its center on the axis $T_1 = T_2 = 0$ with $\Sigma = (\sigI + \sigIII)/2$ and its radius is $R = (\sigI - \sigIII)/2$. The Tresca criterion, which does not depend on the intermediate stress $\sigII$, directly gives the maximum radius $R = \tau_c$, regardless of the center's position. For the von Mises criterion, given the maximum and minimum principal stresses $\sigI$ and $\sigIII$, the largest Mohr's circle radius is obtained when $\sigII = (\sigI + \sigIII)/2$, giving the same maximum radius $R = (\sigI - \sigIII)/2 = \tau_c$. Therefore, the intrinsic domain $\mathcal{K}_0$ for both criteria is the same and corresponds to the cylinder $\sqrt{T_1^2 + T_2^2} \leq \tau_c$, whose cross-section for $T_2 = 0$ is the gray region bounded by the thick black lines in Figure~\ref{fig:VMvsTresca}-right.

For uniaxial traction, \emph{e.g.} $\sigma_2 = \sigma_3 = 0$, the stress state with maximum principal stress $\sigma_1$ corresponds to $\sqrt{3}\tau_c\, \mathbf{e}_1 \otimes \mathbf{e}_1$ for the von Mises criterion, and to $2\tau_c\, \mathbf{e}_1 \otimes \mathbf{e}_1$ for the Tresca criterion; see the green and blue dots in Figure~\ref{fig:VMvsTresca}-left, respectively. The green and blue circles in Figure~\ref{fig:VMvsTresca}-right represent the corresponding Mohr's circles in the cross-section $T_2 = 0$ of the Mohr's space $(\Sigma,T_1,T_2)$. % representing the stress vector $\sig\n\equiv$ in the intrinsic coordinates $(\Sigma,T_1,T_2)$. 
The blue circle, associated with the Tresca criterion, is tangent to the intrinsic domain. Using the notation of Figure~\ref{fig:F-Angle}, this implies that, under uniaxial traction, the Tresca criterion admits displacement jumps along planes with normal direction $\theta = \pm\pi/4$. In contrast, the green circle corresponding to the von Mises criterion has radius $\sqrt{3}/2$ and lies strictly inside $\mathcal{K}_0$. This indicates that the von Mises criterion does not admit displacement jumps under uniaxial traction. 

The magenta cross in Figure~\ref{fig:VMvsTresca}-left and the dashed magenta circle in Figure~\ref{fig:VMvsTresca}-right represent the stress state of maximum admissible intensity under pure shear, which is identical for both the von Mises and Tresca criteria. In this case, the Mohr's circle is tangent to the intrinsic domain, and both criteria admit displacement jumps along directions $\theta = \pm\pi/4$.

\end{example} 

