The  support functions of the strength domain $\K_0$ and the intrinsic domain $\mathcal{K}_0$ are given by~\cite{Sal83}:
\begin{eqnarray}
    \notag
\H_{\K_0}(\p)&=&
\begin{cases}
    \tau_c\,\cot{\varphi}\,\mathrm{tr}(\p)
    & \text{ if } \mathrm{tr}(\p)\geq \left(\vert{p_1}\vert+\vert{p_2}\vert+\vert{p_3}\vert\right)\sin{\varphi},\\
    +\infty&\text{ otherwise,}
\end{cases}\\
    \mathrm{H}_{\mathcal{K}_0}(\Delta,D_1,D_2) &=& 
    \begin{cases}
        \tau_c\,\cot{\varphi}\,\Delta
        & \text{ if } \Delta\geq \sqrt{\Delta^2+D_1^2+D_2^2}\sin{\varphi},\\
        +\infty&\text{ otherwise}.
    \end{cases}
\label{eq:MC-K0-supportfunction}
\end{eqnarray}

\begin{remark}
The Mohr-Coulomb criterion is usually used to model soils and rocks behavior in conjunction with limit analysis theories to bound the solution for ridig-perfectly-plastic problems with test functions including displacement jumps~\cite{Sal83,Salencon1993CISM,CHEN75}. 
\end{remark}

\begin{remark}
In this Section, we present expressions for the support functions of the several classical strength domains $\mathbb{K}_0$, without detailing their generally non-trivial computation. These expressions are available in standard texts on Limit Analysis~\cite{Sal83,Salencon1993CISM,CHEN75}. The derivation relies on the following key result: for a given symmetric matrix $\p$ with ordered eigenvalues $(\pI,\pII,\pIII)$, the following equality holds
\begin{equation}
\max_{\sig\in\mathbb M(\sigI,\sigII,\sigIII)} \sig\cdot\p = \sigI\pI + \sigII\pII + \sigIII\pIII,
\label{eq:suptensors}
\end{equation}
where $\mathbb {M}(\sigI,\sigII,\sigIII)$ denotes the set of all symmetric matrices whose ordered eigenvalues are $(\sigI,\sigII,\sigIII)$.
Given this, the determination of the support function reduces to the tedious solution of relative simple convex optimization problems in three dimensions, see \emph{e.g.}~\cite[Section 3.6]{CHEN75}. The proof of the above identity, a subtle algebraic result given for granted in the cited texts, was communicated to us by Patrick Ballard~\cite{Ballard25}, and relies on  Cauchy's interlace theorem, see also~\cite[Theorem~4.3.53, p.~255]{HornJohnson}.  Given the support function for the strength domain in  the stress space $\mathbb{K}_0$, the support function for $\mathcal{K}_0$ is  found by replacing $\p$ with $\mathbf{d}\odot\mathbf{n}$.
\end{remark}


Notable limit cases or variants of the Mohr-Coulomb criterion include the following:
\begin{itemize}
    \item \emph{Tresca criterion (maximal shear)}. It bounds the tangential component of the stress vector only, by imposing $\| \T\| \leq \overline{T}(\Sigma)=\tau_c$. It gives:
        \begin{align*}
        \K_0 & = \left\{\sig\in\mathbb M^3_s: \sigI-\sigIII\leq 2\tau_c \right\},\\
        \mathcal {K}_0 & =\left\{(\Sigma,T_1,T_2)\in\mathbb R^3: \sqrt{T_1^2+T_2^2}\le\tau_c\right\},\\
        \H_{\K_0}(\p) & =
            \begin{cases}
                \tau_c\left(\vert{p_1}\vert+\vert{p_2}\vert+\vert{p_3}\vert\right)  & \text{ if } \mathrm{tr}(\p)= 0\\
                +\infty  & \text{ otherwise,}
            \end{cases}\\
            \H_{\mathcal{K}_0}(\Delta,D_1,D_2) &=
            \begin{cases}
                \tau_c\,\sqrt{\Delta^2+D_1^2+D_2^2} & \text{ if } \Delta= 0\\
                +\infty & \text{ otherwise.}
            \end{cases}
        \end{align*}

\item \emph{Rankine criterion (maximal tension)}. It bounds the maximum normal component of the stress vector by imposing  $\Sigma\leq\sigma_c$. It gives:
    \begin{align*}
        K_0 & = \left\{ \sig\in\mathbb M^3_s: \sigI\leq \sigma_c \right\},\\
        \mathcal K_0 & =\left\{(\Sigma,T_1,T_2)\in\mathbb R^3: \Sigma<\sigma_c\right\}\cup\{\sigma_c,0,0\},\\
        \H_{\K_0}(\p) & =
            \begin{cases}  
                \sigma_c\,\mathrm{tr}(\p) & \text{ if } \mathrm{tr}(\p)\geq 0,\\
                +\infty & \text{ otherwise,}
            \end{cases}\\
        \H_{\mathcal{K}_0}(\Delta,D_1,D_2) & =
            \begin{cases}
                \sigma_c\,\sqrt{\Delta^2+D_1^2+D_2^2} & \text{ if } \Delta\geq 0,\\
                +\infty & \text{ otherwise.}
            \end{cases}
    \end{align*}

\item \emph{Tresca with a tension cut-off}. It is a combination of the two criteria above, obtained when imposing $\Sigma\leq\sigma_c$ and $\norm{\T}\leq\tau_c$:
    \begin{align*}
        \K_0 & = \left\{ \sig\in\mathbb M^3_s: \sup\{\sigI-\sigIII-2\tau_c,\sigI-\sigma_c\}\leq 0 \right\},\\
        \mathcal K_0 & = \left\{ (\Sigma,T_1,T_2)\in\mathbb R^3: \Sigma\le \sigma_c, {(\Sigma-\sigma_c+\tau_c)^+}^2+T_1^2+T_2^2\le\tau_c^2 \right\},\\
        \H_{\K_0}(\p) & =
            \begin{cases}
                \tau_c\left(\vert{p_1}\vert+\vert{p_2}\vert+\vert{p_3}\vert-\mathrm{tr}(\p)\right)+\sigma_c\mathrm{tr}(\p) & \text{ if } \mathrm{tr}(\p)\geq 0,\\
                +\infty&\text{otherwise,}
            \end{cases}\\
    \H_{\mathcal{K}_0}(\Delta,D_1,D_2) & =
        \begin{cases}
            \tau_c\,(\sqrt{\Delta^2+D_1^2+D_2^2}-\Delta)+\sigma_c\,\Delta & \text{ if } \Delta\geq ,0\\
            +\infty & \text{ otherwise,}
    \end{cases}
    \end{align*}
    where $(\cdot)^+=\sup(\cdot,0)$.
\end{itemize}

\begin{remark}
All the criteria above define the admissible stress only in terms of the maximum and minimum eigenvalues $\sigI$ and $\sigIII$.
This implies that for all the stress states $\sig\in\partial\mathbb{K}_0$ there exist a normal $\n$ such that  $\sig\n\in\partial\mathcal{K}_0$. Hence, because of Proposition~\ref{prop:intrinsiccurvejump}, all the point $\partial\K_0$ have a normal compatible with a displacement jump.
\end{remark}
\subsubsection{Drucker-Prager family}
\label{sec:Mohr-DP}
The Drucker-Prager criterion~\cite{DruPra52} is defined in terms of the norm of the spherical and the deviatoric parts of the stress tensor $\sig$. The strength stress $\K_0$ domain is defined as
\begin{equation}
    \label{eq:DP}
    \K_0=
    \left\{
        \sig\in\mathbb M^3_s: \frac{\norm{\sig^D}}{\sqrt{2}}\le 3 k\left(\sigma_c-\frac{\mathrm{tr}(\sig)}{3}\right)
    \right\}\mbox{\quad with\quad} 0< k<\frac{1}{2\sqrt3}, \quad\sigma_c>0.
\end{equation}
$\K_0$ is a cone pointed at $\sigma_c\, \mathbf I$, where $\sigma_c$ and $\tau_c=3k\,\sigma_c$  are the maximum allowable stress in uniaxial traction and pure shear, see Figure~\ref{fig:MC-domains}.
The support function is computed by using the decomposition in the spherical and deviatoric parts, which gives
\begin{equation}
    \label{piDP}
    \H_{\K_0}(\mathbf p)=
    \begin{cases}
        \sigma_c\text{tr}(\mathbf p)&\mbox{if } \text{tr}(\mathbf p)\ge3k \sqrt2\norm{\mathbf p^D},\\
        +\infty&\mbox{ otherwise.}
    \end{cases}
\end{equation}
Being formulated in terms of the invariants of the stress tensor, the criterion is isotropic.  
The intrinsic domain can be computed using Mohr's circle representation.  
Given the maximum and minimum principal stresses, $\sigI$ and $\sigIII$, we express the intermediate principal stress as  $\sigII = \chi \sigIII + (1 - \chi) \sigI$, with
$\chi \in [0,1]$.
 Plugging this expression into~\eqref{eq:DP} written in terms of the eigenvalues, one finds that  $\sig\in\partial \K_0$ when 
$f_k(\chi)R=3\sqrt{3}k(\sigma_c-C)$ 
with $f_k(\chi)=2\sqrt{1-\chi+\chi^2}+(1-2\chi)\sqrt{3}\, k,$
where $C=(\sigI+\sigIII)/2$ is the center of the Mohr's circle and $R=(\sigI-\sigIII)/2$ its radius.
Given the center, the maximum radius is found when $\chi$, \emph{i.e.}~$\sigII$, minimizes $f_k(\chi)$. This gives $\chi_k=(1+\sin\varphi_k)/2$, with $\sin\varphi_k={3k}/{\sqrt{1-3k^2}}$. The maximum radius as a function of the position of the center is 
$
R=\sin\varphi_k(\sigma_c-C)$ with $C\le\sigma_c$.
The straight lines $T=\pm\tan\varphi_k(\sigma_c-\Sigma)$ are tangent to all the  these circles. They represent the intrinsic curve and the intrinsic domain is
 \begin{equation*}
    % \label{KDP}
    \mathcal K_0=\left\{(\Sigma,T_1,T_2)\in\mathbb R^3:\Sigma\le\sigma_c, \sqrt{T_1^2+T_2^2}\le(\sigma_c-\Sigma)\tan\varphi_k\right\}\mbox{\quad with\quad} \varphi_k=\arcsin\frac{3 k}{\sqrt{1-3k^2}}.
\end{equation*}
Recalling that $\sigma_c = \tau_c\,\cot{\varphi}$, the intrinsic domain associated with the Drucker-Prager criterion coincides with that of the Mohr-Coulomb criterion when the parameter $k$ is chosen as
$
k = {\sin \varphi}/{\sqrt{3(3 + \sin^2 \varphi)}}.
$
As a result, its support function coincides with that of the Mohr-Coulomb model given in~\eqref{eq:MC-K0-supportfunction}, up to a suitable renaming of variables.

The limit cases of the Drucker-Prager criterion analogue to the Tresca and Rankine criterion introduced for the Mohr-Coulomb criterion are the following:
\begin{itemize}
    \item \emph{von Mises criterion}. It bounds the deviatoric part of the stress tensor only. It gives:
    \begin{align*}
        \K_0 & = \left\{ \sig\in\mathbb M^3_s: \frac{\Vert\sig^D\Vert}{\sqrt{2}}\leq \tau_c \right\},\\
        \mathcal K_0 & = \left\{(\Sigma,T_1,T_2)\in\mathbb R^3: \sqrt{T_1^2+T_2^2}\le\tau_c\right\},\\
        \H_{\K_0}(\p) & =
            \begin{cases}
                \tau_c\sqrt{2}\,\Vert\p\Vert & \text{ if } \mathrm{tr}(\p)= 0,\\
                +\infty & \text{ otherwise,}
            \end{cases}\\
        \H_{\mathcal{K}_0}(\Delta,D_1,D_2) & =
            \begin{cases}
                \tau_c\,\sqrt{\Delta^2+D_1^2+D_2^2} & \text{ if } \Delta = 0,\\
                +\infty & \text{ otherwise.}
        \end{cases}
    \end{align*}


\item \emph{Maximum average stress criterion}. It bounds the
trace of the stress tensor. It gives:
    \begin{align*}
        \K_0 & = \left\{ \sig\in\mathbb M^3_s: \frac{\mathrm{tr}(\sig)}{3}\leq \sigma_c \right\},\\
        \H_{\K_0}(\p) & =
            \begin{cases}  
                \sigma_c\,\mathrm{tr}(\p) & \text{ if } \mathrm{tr}(\p)\geq 0,\\
                +\infty & \text{ otherwise.}
            \end{cases}
    \end{align*}
    The intrinsic domain in this case is the whole space: $\mathcal{K}_0 = \mathbb{R}^3$. 

\end{itemize}
It is also possible to define a tension cut-off on the von Mises criterion, as done for Tresca's, but this is not reported here explicitly.

\begin{remark}
    \label{rem:jumpcompatibility}
    The intrinsic domain of the Drucker-Prager and the Mohr-Coulomb criteria coincide. 
 However, differently from Mohr-Coulomb criterion, only the points on $\partial\K_0$ with  
 $\sigII=(\sigI+\sigIII)/2-\sin\varphi_k(\sigI-\sigIII)/2$ can give a stress vector on the boundary of the intrinsic section. Only for these stress states the normal to $\partial \K_0$ is compatible with a displacement jump.
 Similarly, the Tresca and the von Mises criteria have the same intrinsic domain, but the normal to the von Mises strength domain is compatible with a displacement jump if and only $\sigII=(\sigI+\sigIII)/2$, while  all normal to the boundary of the  Tresca domain are jump-compatible.
 \end{remark}

 \begin{remark}
    When $k = 1/(2\sqrt{3})$, then $\varphi_k = \pi/2$ and the intrinsic domain coincides with the half-space $\Sigma\leq\sigma_c$. If $k > 1/(2\sqrt{3})$, all points in the $(\Sigma, T)$-plane are covered by Mohr'ss circles and the intrinsic domain becomes all of $\mathbb{R}^3$, with no intrinsic curve. Thus, displacement jumps are not possible in this case.
    \end{remark}


