\midrule
% 错误类型
\begin{tabular}[c]{@{}c@{}}Reason Error\end{tabular}   & \begin{tabular}[c]{@{}l@{}} Errors that occur in the logical reasoning process while using knowledge \\ concepts to solve the problem step by step.  \\
\end{tabular} \\
\midrule

\begin{tabular}[c]{@{}c@{}}Visual Perception Error\end{tabular}   & \begin{tabular}[c]{@{}l@{}} Errors in visual perception, where the model incorrectly identifies shapes \\ or numbers in an image. \\
\end{tabular} \\
\midrule

\begin{tabular}[c]{@{}c@{}}Knowledge Error\end{tabular}   & \begin{tabular}[c]{@{}l@{}} For a specific knowledge concept, the model is unclear or confused about \\ it, or it misuses another knowledge concept to solve the problem. \\
