\section{Pre-Tukey relation}

In this section, we introduce the pre-Tukey relation, which weakens the Tukey relation and works well without $\AC$.
First we recall the original Tukey relation.

\begin{definition}
  Let $(D, \leq_D)$ and $(E, \leq_E)$ be directed sets.
  A function $f \colon D\rightarrow E$ is a \textit{Tukey map} if $f$ maps unbounded sets in $(D, \leq_D)$ into unbounded sets in $(E, \leq_E)$.
  A function $f \colon D\rightarrow E$ is a \textit{convergent map} if $f$ maps cofinal sets in $(D, \leq_D)$ into cofinal sets in $(E, \leq_E)$.

  We say that $(D,\leq_D)$ is \textit{Tukey reducible} to $(E, \leq_E)$ if there is a Tukey map from $(D,\leq_D)$ to $(E, \leq_E)$, and we write $(D, \leq_D) \preceq_T (E,\leq_E)$.
  Let $(D, \leq_D) \equiv_T (E, \leq_E)$ if $(D, \leq_D) \preceq_T (E, \leq_E)$ and $(E, \leq_E) \preceq_T (D, \leq_D)$.
\end{definition}

$\equiv_T$ is an equivalence relation between directed sets.
An equivalence class of $\equiv_T$ is called a \emph{cofinal type}.

$f \colon D\rightarrow E$ is Tukey if and only if
\[
  \forall e\in E\  \exists d\in D\  \forall d'\in D \ 
    (f(d')\leq_E e \Rightarrow d'\leq_D d) \, ,
\]
and $f$ is convergent if and only if 
\[
  \forall e\in E\  \exists d\in D\  \forall d'\in D \ 
    (d\leq_D d' \Rightarrow e\leq_E f(d')) \, .
\]

The following are basic facts on the Tukey reducibility.

\begin{comment}
\begin{definition}
  Let $(D, \leq_D)$ and $(E, \leq_E)$ be directed sets.
  A map $f \colon D \rightarrow E$ is an \textit{embedding} if $d \leq_D d ' \Leftrightarrow f(d)\leq_E f(d')$ holds for all $d, d' \in D$.
  An embedding $f \colon D\rightarrow E$ is \textit{cofinal} if for any $e\in E$ there is $d\in D$ such that $e\leq_E f(d)$.
  We say that $(D, \leq_D)$ is \textit{cofinally embeddable} into $(E, \leq_E)$ if there is a cofinal embedding $f \colon D\rightarrow E$.
\end{definition}
\end{comment}

\begin{fact}[\cite{tukey1940convergence}] \label{converse}
  Assume $\AC$.
  Let $(D, \leq_D)$ and $(E, \leq_E)$ be directed sets.
  $\left(D, \leq_D \right) \preceq_T (E, \leq_E)$ if and only if there is a convergent map from $(D, \leq_D)$ to $(E, \leq_E)$.
\end{fact}

\begin{fact}[\cite{tukey1940convergence}] \label{cof_embedding}
  Assume $\AC$.
  Let $(D, \leq_D)$ and $(E, \leq_E)$ be directed sets.
  Then $(D, \leq_D) \equiv_T (E, \leq_E)$ if and only if there is a directed set $(P, \leq_P)$ into which both $(D, \leq_D)$ and $(E, \leq_E)$ are cofinally embeddable.
\end{fact}

We introduce a generalization of Tukey relation, which we call pre-Tukey relation.
\begin{definition}\label{completion}
  Let $(D, \leq_D)$ be a directed set.
  $(D, \leq_D)^*$ is the directed set of all non-empty $\leq_D$-upward closed subsets of $D$ ordered by reverse inclusion. 
\end{definition}

We note that $(D, \leq_D)^*$ is a completion of $(D, \leq_D)$. 
In fact, $(D, \leq_D)^*$ is a  directed set in which every bounded subset has a least upper bound, and 
a map $d \mapsto \{d'\in D\mid d'\geq_D d\}$ is a cofinal embedding from $(D, \leq_D)$ to $(D, \leq_D)^*$.

\begin{definition}\label{Tukey_completion}
  Let $(D, \leq_D)$ and $(E, \leq_E)$ be directed sets.
  We define $(D, \leq_D)\preceq_{pT} (E, \leq_E)$ if $(D, \leq_D) \preceq_T (E, \leq_E)^*$.
  We call this relation $\preceq_{pT}$ \textit{pre-Tukey relation}.
  We write $\ordD \equiv_{pT} \ordE$ if $\ordD \preceq_{pT} \ordE$ and $\ordE \preceq_{pT} \ordD$.
\end{definition}

It is easy to see that $\preceq_{pT}$ is a pre-ordering, and $\equiv_{pT}$ is an equivalence relation. In the rest of this section, we study basics on the pre-Tukey relation.

The pre-Tukey relation is characterized by the existence of maps that generalize Tukey maps and convergent maps.

\begin{definition}
  Let $\ordD$ and $\ordE$ be directed sets.
  \begin{enumerate}
      \item A \textit{pre-Tukey map} from $\ordD$ to $\ordE$ is a map $\pi \colon D \rightarrow \mcalP(E)$ such that $\pi (d) \neq \emptyset$ for any $d \in D$, and
      \[
      \forall e\in E\  \exists d\in D\  \forall d'\in D \ 
      (\pi(d')\cap e\downarrow_E \neq \emptyset \Rightarrow d' \leq_D d) \, .
      \]
      \item A \textit{pre-convergent map} from $\ordD$ to $\ordE$ is a map $\sigma \colon D \rightarrow \mcalP(E)$ such that $\sigma (d) \neq \emptyset$ for any $d \in D$, and
      \[
      \forall e \in E\  \exists d\in D\  \forall d'\in D\ 
      (d \leq_{D} d' \Rightarrow \sigma(d')\subseteq e \uparrow_{E}) \, .
      \]
  \end{enumerate}
\end{definition}

\begin{lemma}\label{Tukey_map}
  The following are equivalent for directed sets $\ordD$ and $\ordE$.
  \begin{enumerate}
    \item $\ordD \preceq_{pT} \ordE$.
    \item There is a pre-Tukey map from $\ordD$ to $\ordE$.
    \item There is a pre-convergent map from $\ordE$ to $\ordD$.
  \end{enumerate}
\end{lemma}

\begin{proof}
  $(1)\Rightarrow (2) \colon $
  Suppose $\pi \colon D \rightarrow E^*$ is a Tukey map, where $E^*$ is the set of all non-empty $\leq_E$-upwards closed sets.
  For each $e \in E$, if $d \in D$ witnesses that $\pi \colon D \rightarrow E^*$ is Tukey for $e \uparrow_{\leq_E} \in E^*$, then $d$ witnesses that $\pi \colon D \rightarrow \mcalP(E)$ is pre-Tukey for $e$.

  $(2)\Rightarrow (1) \colon $
  Suppose $\pi \colon D\rightarrow \mcalP(E)$ is a pre-Tukey map.
  Define $f \colon D\rightarrow E^*$ by letting $f(d)$ be the $\leq_E$-upward closure of $\pi(d)$.
  Then it is easy to check that $f$ is a Tukey map from $\ordD$ to $\ordE^*$.

  $(2)\Rightarrow (3) \colon $
  Suppose $\pi \colon D\rightarrow \mcalP(E)$ is a pre-Tukey map.
  Define $\sigma \colon E\rightarrow \mcalP(D)$ by 
  \[
    \sigma(e)=\{d\in D\mid \forall d'\in D\  
    (\pi(d')\cap e\downarrow_{\leq_E} \neq \emptyset \Rightarrow d'\leq_D d)\} \, .
  \]
  Since $\pi$ is a pre-Tukey map, $\sigma(e)$ is non-empty for any $e\in E$.
  It is easy to check that each $e \in \pi(d)$ witnesses that $\sigma$ is a pre-convergent map for each $d \in D$.

  $(3)\Rightarrow (2) \colon $
  Suppose $\sigma \colon E\rightarrow \mcalP(D)$ is a pre-convergent map.
  Define $\pi \colon D\rightarrow \mcalP(E)$ by
  \[
    \pi(d)=\{e\in E\mid \forall e'\in E\ 
    (e\leq_{E} e' \Rightarrow \sigma(e')\subseteq d\uparrow_{\leq_D})\} \ .
  \]
 Since $\sigma$ is a pre-convergent map, $\pi(d)$ is non-empty for any $d\in D$.
 It is easy to check that each $d \in \sigma (e)$ witnesses that $\pi$ is a pre-Tukey map for each $e \in E$.
\end{proof}

For a pre-Tukey map $\pi$ from $\ordD$ to $\ordE$, let $\pi' \colon D \rightarrow \mcalP (E)$ be a function such that $\pi ' (d)$ is the $\leq_E$-upward closure of $\pi (d)$.
Then $\pi'$ is also a pre-Tukey map.
The same holds for pre-convergent maps.

Next we observe the relationships between Tukey (convergent) maps and pre-Tukey (pre-convergent) maps.

\begin{lemma}\label{Tukey_imply_preTukey}
  Let $\ordD$ and $\ordE$ be directed sets.
  For $f \colon D\rightarrow E$ define $\pi_f \colon D\rightarrow \mcalP(E)$ by $\pi_f (d)=f(d) \uparrow_{\leq_E}$.
  \begin{enumerate}
    \item If $f$ is a Tukey map, then $\pi_f$ is a pre-Tukey map.
    \item If $f$ is a convergent map, then $\pi_f$ is a pre-convergent map.
  \end{enumerate}
\end{lemma}
\begin{proof}
  Suppose $f$ is a Tukey map.
  To show that $\pi_f$ is pre-Tukey, let $e\in E$.
  Then there is $d\in D$ such that if $f(d')\leq_E e$ then $d'\leq_D d$.
  We show that $d$ witnesses that $\pi_f$ is pre-Tukey for $e$.
  Suppose $\pi_f (d') \cap e \downarrow_{\leq_E} \neq\emptyset$.
  Then $e \in \pi_f (d')$, and so $f(d') \leq_E e$.
  Thus $d' \leq_D d$.

  Suppose $f$ is a convergent map.
  To show that $\pi_f$ is pre-convergent, let $e\in E$.
  Then there is $d\in D$ such that $e \leq_E f(d')$ for any $d' \geq_D d$.
  Then $\pi_f(d')\subseteq e\uparrow_{E}$ for any $d' \geq_D d$.
\end{proof}

\begin{lemma}\label{preTukey_imply_Tukey}
  Let $\ordD$ and $\ordE$ be directed sets and $\pi \colon D \rightarrow \mcalP(E)$.
  Suppose that $f \colon D\rightarrow E$, and $f(d)\in \pi(d)$ for each $d\in D$.
  \begin{enumerate}
   \item If $\pi$ is a pre-Tukey map, then $f$ is a Tukey map.
   \item If $\pi$ is a pre-convergent map, then $f$ is a convergent map.
  \end{enumerate}
\end{lemma}
\begin{proof}
 Suppose $\pi$ is a pre-Tukey map and let $e\in E$.
 We can take $d\in D$ such that if $\pi(d')\cap e\downarrow_{\leq_E}\neq \emptyset$ then $d'\leq_D d$.
 If $f(d') \leq_E e$, then $f(d')\in \pi (d') \cap e\downarrow_{\leq_E}$, and so $d'\leq_D d$.
 Thus $f$ is a Tukey map.

 Suppose that $\pi$ is a pre-convergent map and let $e\in E$. 
 We can take $d\in D$ such that if $d\leq_D d'$ then $\pi(d')\subseteq e\uparrow_{\leq_E}$.
 Since $f(d') \in \pi (d')$, if $d\leq_D d'$ then $e\leq_E f(d')$.
 Thus $f$ is a convergent map.
\end{proof}

Next, we prove the analog of Fact \ref{cof_embedding}.

\begin{theorem}
  Let $\ordD$ and $\ordE$ be directed sets.
  $\ordD \equiv_{pT} \ordE$ if and only if there is a directed set $\ordP$ into which both $\ordD$ and $\ordE$ are cofinally embeddable.
\end{theorem}

\begin{proof}
  Assume that there is a directed set $\ordP$ into which both $\ordD$ and $\ordE$ is cofinally embeddable.
  We may assume that $D$ and $E$ are subsets of $P$.
  By symmetry, it suffices to construct a pre-Tukey map from $D$ to $E$.
  Define $\pi \colon D\rightarrow \mcalP(E)$ by
  $\pi(d)=\{e\in E\mid d\leq_P e\}$.
  We show that $\pi$ is pre-Tukey.
  Suppose $e\in E$, then there is $d\in D$ with $e\leq_P d$.
  If $\pi(d')\cap e\downarrow_{\leq_E} \neq\emptyset$
  then $d'\leq_P e$, and thus $d'\leq_D d$.

  Conversely, assume that $\ordD \equiv_{pT} \ordE$. We may assume $D \cap E = \emptyset$.
  Let $\pi_0 \colon D\rightarrow \mcalP(E)$ and 
  $\pi_1 \colon E\rightarrow \mcalP(D)$ be pre-Tukey maps.
  We may assume that each value of $\pi_0$ and $\pi_1$ is upward closed.
  Define $\sigma_0 \colon E\rightarrow \mcalP(D)$ and $\sigma_1 \colon D\rightarrow \mcalP(E)$ by
  \begin{eqnarray*}
    \sigma_0(e)=\{d\in D\mid \forall d'\in D \ 
    (\pi_0 (d')\cap e\downarrow_E \neq\emptyset \Rightarrow d'\leq_D d)\} \, , \\
    \sigma_1(d)=\{e\in E\mid \forall e'\in E \ 
    (\pi_1 (e')\cap d\downarrow_D \neq\emptyset \Rightarrow e'\leq_E e)\} \, .
  \end{eqnarray*}
  Note that $\sigma_0$ and $\sigma_1$ are pre-convergent maps and that $\sigma_0 (e)$ and $\sigma_1 (d)$ are upward closed in $D$ and $E$, respectively.

  Define $\pi \colon D\rightarrow \mcalP(E)$ by $\pi(d)=\pi_0 (d)\cap \sigma_1(d)$ and $\sigma \colon E\rightarrow \mcalP(D)$ by $\sigma(e)=\pi_1 (e)\cap \sigma_0(e)$.
  Since $\ordE$ is directed, and $\pi_0 (d) , \sigma_1 (d)$ are $\leq_E$-upward closed, we have $\pi (d) \neq \emptyset$. Similarly, $\sigma (e) \neq \emptyset$.

  By the construction of $\sigma_0$ and $\sigma_1$, and the fact that $\sigma(e)\subseteq \sigma_0 (e)$ and $\pi(d)\subseteq \sigma_1(d)$, we have the following for all $d\in D$ and $e\in E:$
  \begin{enumerate}
    \item $\pi(d)\cap e\downarrow _{E}\neq \emptyset
    \Rightarrow \sigma(e)\subseteq d\uparrow_{D}\ ;$
    \item $\sigma(e)\cap d\downarrow _{D}\neq \emptyset
    \Rightarrow \pi(d)\subseteq e\uparrow_{E}$\ .
  \end{enumerate}
  Let $P = D \cup E$, and define an ordering $\leq_P$ on $P$ as follows.
  \begin{itemize}
    \item $\leq_P \cap \ (D\times D)= \ \leq_D\ ;$
    \item $\leq_P \cap \ (E\times E)= \ \leq_E\ ;$
    \item For $d\in D$ and $e\in E$,
    $d\leq_P e \Leftrightarrow \exists d'\geq_D d\ (e\in \pi(d'))\ ;$
    \item  For $d\in D$ and $e\in E$, 
    $e\leq_P d \Leftrightarrow \exists e'\geq_E e\ (d\in \sigma(e'))$\ .
  \end{itemize}
  It suffices to prove that $\leq_P$ is transitive, and both $D$ and $E$ are cofinal in $\ordP$.

  For the transitivity of $\leq_P$, we only show that if $d_0\leq_P e\leq_P d_1$ then $d_0\leq_P d_1$ for all $d_0, d_1 \in D$ and $e\in E$.
  The proofs of the other cases are easy or similar to this case.
  We take $d'\geq_D d_0$ such that $e\in \pi(d')$ and $e'\geq_E e$ such that $d_1\in \sigma(e')$.
  Then $e\in \pi(d')\cap e'\downarrow_{\leq_E}$, so $\sigma(e')\subseteq d'\uparrow_{\leq_D}$ by (1).
  Thus $d_0 \leq_D d'\leq_D d_1$, and so $d_0 \leq_P d_1$.

  We show that $D$ and $E$ are cofinal in $\ordP$.
  To prove that $D$ is cofinal, suppose $e \in E$.
  Since $\sigma (e) \neq \emptyset$, we can take $d \in \sigma (e)$.
  Then $e \leq_P d \in D$ by the definition of $\leq_P$.
  Similarly $E$ is cofinal in $\ordP$.
\end{proof}

We note that the pre-Tukey relation and the Tukey relation need not coincide without $\AC$.

Let $\mathrm{WO}$ be the set of all $x \in {}^\omega \omega$, which codes a well-ordering of $\omega$ in the usual way.
For each $x \in \mathrm{WO}$ let $o(x)$ be the order-type of the well-ordering coded by $x$.
For $x,y \in \mathrm{WO}$ we write $x \trianglelefteq y$ if either $o(x) < o(y)$, or $o(x) = o(y)$ and $x \leq_\mathrm{lex} y$, where $\leq_\mathrm{lex}$ is the lexicographic ordering on $\omega^\omega$.
Then $\trianglelefteq$ is a linear ordering on $\mathrm{WO}$.

Assume that there is no injection from $\omega_1$ to $\omega^\omega$.
If there is a Tukey map from $(\omega_1, \leq)$ to $(\WO, \trianglelefteq)$ then we can construct an injection from $\omega_1$ to $\omega^\omega$. Thus $(\omega_1, \leq)\npreceq_T (\mathrm{WO}, \trianglelefteq).$
On the other hand, $\pi \colon \omega_1 \to \mathcal{P}( \mathrm{WO} )$ defined by
\[
\pi ( \xi ) = \{ x \in \mathrm{WO} \mid o(x) = \xi \}
\]
is a pre-Tukey and pre-convergent map. So 
$( \omega_1 , \leq ) \equiv_{pT} ( \mathrm{WO} , \trianglelefteq )$.


\section{Pre-Tukey relation among $\sigma$-directed sets}
In this section, we investigate the pre-Tukey relations between 
\begin{center}
$\left( \omega^\omega, \leq^* \right), 
\left( \mcalM, \subseteq \right), 
\left(\mcalN, \subseteq \right), 
\left(\omega_1, \leq\right)$, 
$([\omega^\omega]^\omega, \subseteq)$.
\end{center}

We consider these directed sets under an assumption on sets of reals, which holds in the Solovay model and in $L(\mathbb{R})$ satisfying $\AD$.
%We now introduce some definitions and facts necessary to describe the assumption.

\begin{comment}
\begin{definition}
  Let $S$ be a set of ordinals.
  We define
  \begin{center}
    $M[S] = \bigcup_{\alpha\in\Ord} L(V^M_\alpha \cup \{S\})$.
