\begin{definition}[Woodin]
  $X \subseteq \omega^\omega$ is $\infty$-\textit{Borel} if there exist a set $S$ of ordinals and a formula $\varphi$ such that 
  \begin{center}
    $x\in X \Leftrightarrow
    L[S][x]\models \varphi(S,x)$
  \end{center}
  for all $x\in \omega^\omega$.
  We call this pair $(S, \varphi)$ a \textit{Solovay code for} $X$.
\end{definition}

\begin{definition}
  Let $(\star)$ denote the following statements:
  \begin{enumerate}
    \item $\omega_1$ is inaccessible in $L[S]$ for any set $S$ of ordinals.
    \item Every subset of $\omega^\omega$ is $\infty$-Borel. 
  \end{enumerate}
\end{definition}

For an inaccessible cardinal $\kappa$ and a $\collkappa$-generic filter $G$ over $V$, 
we let
$\VRVG = \mathrm{HOD}^{V[G]}_{V\cup \mbbR^{V[G]}}$, the collection of hereditarily ordinal defiable sets in $V[G]$ with parameters from $V\cup \mbbR^{V[G]}$.
We call $\VRVG$ the Solovay model for $\kappa$.
\begin{fact}\label{fact_Solovay_LR}
  \begin{enumerate}
    \item Assume $\AC$ in $V$. Let $\kappa$ be an inaccessible cardinal and let $G$ be a $\collkappa$-generic filter over $V$.
    Then $(\star)$ holds in $\VRVG$.
    \item If $\LR\models \AD$ then $\LR\models (\star)$.
  \end{enumerate}
\end{fact}

\begin{proof}
  $(1)$ : We work in $V[G]$.
  Suppose that $\lambda$ is an ordinal and $S \subseteq \lambda$.
  By the homogeneity of $\collkappa$, there are $v\in V$, $r \in \omega^\omega$ and a formula $\varphi$ such that 
  \begin{center}
    $\alpha \in S \Leftrightarrow V[r] \models 1_{\collkappa} \Vdash_{\collkappa} \varphi (v, r, \alpha)$
  \end{center}
  for all $ \alpha < \lambda$.
  Then $S \in V[r]$, so $L[S] \subseteq V[r]$.
  Since $\kappa=\omega_1$ is inaccessible in $V[r]$,
  $\omega_1$ is inaccessible in $L[S]$.

  We suppose that $X \subseteq \omega^\omega$ and show that $X$ is $\infty$-Borel.
  By the reflection principle, there are $v \in V$, $r \in \omega^\omega$, a formula $\psi$ and an ordinal $\gamma$
  such that
\[
x \in X \ \Leftrightarrow \ 
V_{\gamma}^{V[G]} \models \psi (r,v,x) \, .
\]
for all $x\in\omega^\omega$.
Since $\AC$ holds in $V$, we can take a set $S'$ of ordinals such that ${V_\gamma}^{V[G]} = {V_\gamma}^{L[S'][G]}$. Then

\begin{align*}
  x \in X
  &\Leftrightarrow L[S'][G]\models `` V_\gamma \models \psi (r, v, x) ''\\
  & \Leftrightarrow L[S'][r][x]\models 1_{\collkappa} \Vdash_{\collkappa} `` V_\gamma \models \psi (r, v, x) ''\ .
\end{align*}

Let $S$ be a set of ordinals coding $S', r, v, \kappa$ and $\gamma$ such that $L[S] = L[S'][r]$.
Let $\varphi(S, x)$ be the formula stating that
\begin{center} 
$1_{\collkappa} \Vdash_{\collkappa} `` V_\gamma \models \psi (r, v, x) ''$.
\end{center}
Then $(S, \varphi)$ is a Solovay code for $X$.

  $(2)$ : See \cite{woodin2010axiom} for a proof of that every subset of $\omega^\omega$ is $\infty$-Borel. 
  For every set $S$ of ordinals with $S \in \LR$, 
  $(\omega^\omega)^{L[S]}$ is a  well-orderable subset of $\omega^\omega$ in $\LR$.
  Thus by the perfect set property in $\LR$,
  $(2^\omega)^{L[S]}$ is countable in $\LR$.
  Then it follows that $\omega_1$ is strong limit in $L[S]$.

  Now we assume $\ZF+\DC$, thus $\LR$ satisfies $\ZF+\DC$.
  In particular, $\omega_1$ is a regular cardinal in $\LR$.
  For each set $S$ of ordinals with $S\in \LR$, since $L[S] \subseteq \LR$, $\omega_1$ is a regular cardinal in $L[S]$.
  Hence, $\omega_1$ is inaccessible in $L[S]$.
\end{proof}

