 In the rest of this subsection, we prove that $( \mcalM , \subseteq ) \not\preceq_{pT} ( \omega^\omega , \leq^* )$ under the assumption $(\star)$.
 We need some preliminaries.
 Recall that for an inner model $W$, 
 $C^W$ denotes the set of all Cohen reals over $W$.

 \begin{lemma}\label{Cohen_cofinal}
  Assume ($\star$).
   Let $x \in \omega^\omega$ and $B \subseteq 2^\omega$ be a comeager set.
   Suppose that $(S, \varphi)$ is a Solovay code for $B$.
   Then $C^{L[S]} \subseteq B$.
 \end{lemma}

 \begin{proof}
   For a contradiction, we assume that $C^{L[S]} \not\subseteq B$ and take $c \in C^{L[S]} \setminus B$.
   Since $c$ is a Cohen real over $L[S]$, we can take a $\mbbC$-generic filter $g$ over $L[S]$ such that $c = \dot{c}[g]$, where $\dot{c}$ is the canonical $\mbbC$-name for a generic real.
   We note that
   \begin{align*}
     c \notin B 
     &\Leftrightarrow L[S][c]\models \lnot \varphi(S,c)\\
     &\Leftrightarrow \exists p\in g\ ( L[S]\models  p\Vdash_{\mbbC} \lnot \varphi(S,\dot{c})).
   \end{align*}

   Take such $p \in g$, and let $X$ be the collection of $\dot{c}[h]$ for all $\mbbC$-generic filter $h$ over $L[S]$ with $p \in h$.
   Then $X \cap B = \emptyset$, and thus $X$ is meager.
   However, $X$ is comeager in a non-meager set $\{y \in 2^\omega \mid p\subseteq y\}$
   since $(2^\omega)^{L[S]}$ is countable.
   Thus $X$ is non-meager.
   This is a contradiction.
 \end{proof}

 Let $\hat{\mcalM}$ be the comeager filter over $2^\omega$.

 \begin{lemma}\label{Cohen_cofinal_M}
  Assume ($\star$).
  Then $\{C^{L[x]}\mid x\in\omega^\omega\}$ is cofinal in $(\hat{\mcalM}, \supseteq)$.
 \end{lemma}

 \begin{proof}
  Suppose $X\in \hat{\mcalM}$. We can take a Borel comeager set $Y\subseteq X$ and a Borel code $a\in\omega^\omega$ of $Y$.
  By the absoluteness of Borel codes between models of $\ZF+\DC$, there is a formula $\varphi$ such that $( a, \varphi )$ is a Solovay code for $Y$.
  By Lemma \ref{Cohen_cofinal}, $C^{L[a]} \subseteq Y$.
 \end{proof}

 \begin{lemma}\label{d_cofM_equiv}
  Assume ($\star$).
  Suppose that for any set $S$ of ordinals,
