 \begin{theorem}
   Assume $(\star)$.
   Then $(\mcalM, \subseteq) \npreceq_{pT} (\omega^\omega, \leq^*)$.
 \end{theorem}

 \begin{proof}
  Suppose $S$ is a set of ordinals.
  By Lemma \ref{d_cofM_equiv}, it suffices to find $x \in \omega^\omega$ such that for all $y \in \omega^\omega$ there is $z \in \omega^\omega$ with $y \leq^* z$ and $C^{L[S][z]} \not\subseteq C^{L[S][x]}$.

   We can take $x \in \omega^\omega$ such that $( 2^{2^\omega} )^{L[S]}$ is countable in $L[S][x]$.
   Suppose $y \in \omega^\omega$.
   We find $z \geq^* y$ with $C^{L[S][z]} \not\subseteq C^{L[S][x]}$.
   In $L[S][x]$, by Lemma \ref{Laver_generic}, we can take an $\mbbL^{L[S]}$-generic condition $T \in \mbbL^{L[S][x]}$ over $L[S]$.
   Note that $T$ is an $\mbbL^{L[S]}$-generic condition over $L[S]$ in $V$, too.
   Moreover, again by Lemma \ref{Laver_generic}, take an $\mbbL^{L[S][x]}$-generic condition $T' \in \mbbL$ over $L[S][x]$ with $T' \subseteq T$.
   Since $T'$ is infinitely branching above its stem, we can take $z \in [T']$ with $y \leq^* z$.
   We show that $C^{L[S][z]} \not\subseteq C^{L[S][x]}$.
   Note that $z$ is a Laver real over both of $L[S]$ and $L[S][x]$.

   In $L[S][z]$ let $\Gamma$ be the collection of Borel codes of meager subsets of $2^\omega$.
   Note that $( 2^\omega )^{L[S][z]} \leq ( 2^{2^\omega} )^{L[S]}$ since $z$ is a Laver real over $L[S]$.
   So $\Gamma$ is countable in $L[S][x][z]$.
   Then $B = \bigcup_{c\in \Gamma} B_c^{L[S][x][z]}$ is meager in $L[S][x][z]$, where $B^{L[S][x][z]}_c$ is the Borel meager set coded by $c$ in $L[S][x][z]$.
   So we can take $w\in (\omega^\omega)^{L[S][x][z]} \setminus B$.
   Then $w \in C^{L[S][z]}$.
   On the other hand, $w$ is in $L[S][x][z]$, a Laver extension of $L[S][x]$.
   Thus $w \notin C^{L[S][x]}$ by Fact \ref{fact:Laver_basic} (2).
 \end{proof}
 \subsection{($\mcalM, \subseteq$) v.s. ($\mcalN, \subseteq$)}

 In this subsection, we prove the pre-Tukey relations 
 $\meagerideal \preceq_{pT} \nullideal$ and 
 $\nullideal \npreceq_{pT} \meagerideal$ under $(\star)$.

 In $\ZFC$ we can construct a Tukey map from 
 $\meagerideal$ to $\nullideal$.
 The construction can be found in the proof of  Theorem 2.3.1 in \cite{bartoszynski1995set}.
 In the construction, Fact \ref{ZFC_meager_null} below is proved in $\ZF+\DC$.
 To construct a Tukey map using Fact \ref{ZFC_meager_null}, it is necessary to choose a countable sequence of nowhere dense sets corresponding to each meager set.
 On the other hand, by considering the collection of all such sequences, we can define a pre-Tukey map in $\ZF+\DC$, without using $\AC$.

\begin{fact}\label{ZFC_meager_null}
  Let $\cNWD$ be the set of all closed nowhere dense subsets of $2^\omega$ and let $\mathrm{OPEN}$ be the set of all open subsets of $2^\omega$.
  Then there are functions 
  $\varphi \colon {\cNWD}^\omega \rightarrow \mcalN$ and $\tilde{\varphi} \colon \mathrm{OPEN}^\omega \rightarrow \mcalM$ such that
  \begin{center}
    $\varphi (\langle F_n \mid n<\omega \rangle) \subseteq \bigcap_{n<\omega} G_n 
    \Rightarrow \bigcup_{n<\omega} F_n \subseteq \tilde{\varphi}(\langle G_n \mid n<\omega \rangle)$
  \end{center}
  for any $\langle F_n \mid n<\omega \rangle \in \cNWD^\omega$ and any 
  $\langle G_n \mid n<\omega \rangle \in \mathrm{OPEN}^\omega$ with $\bigcap_{n<\omega} G_n \in \mcalN$.
\begin{comment}
 There are functions $\varphi \colon \mcalM\times {}^\omega(\mcalP(2^\omega))\rightarrow \mcalN$ and
  $\tilde{\varphi} \colon \mcalN\times {}^\omega(\mcalP(2^\omega)) \rightarrow \mcalM$ such that
 \begin{center}
   $\varphi(F, \overline{F})\subseteq G\Rightarrow F\leq^* \tilde{\varphi}(G, \overline{G})$
 \end{center} 
 whenever $F\in \mcalM$ is $F_\sigma$-set, 
 $\overline{F}=\langle F_n\mid n\in \omega \rangle$
 is a countable sequence of closed nowhere dense sets with 
 $F=\bigcup_{n\in\omega} F_n$,
 $G\in \mcalN$ is $G_\delta$-set and $\overline{G}=\langle G_n\mid n\in \omega \rangle$
 is a countable sequence of open sets with
 $G=\bigcap_{n\in\omega} G_n$,
\end{comment}
\end{fact}

\begin{theorem}
$(\mcalM, \subseteq)\preceq_{pT} (\mcalN, \subseteq)$. 
\end{theorem}

\begin{proof}
 Let $\mcalM_\sigma$ be the set of all $F_\sigma$ meager subsets of $2^\omega$.
 Since $\mcalM_\sigma$ is cofinal in $\meagerideal$,
 it suffices to show that 
 $( \mcalM_\sigma, \subseteq ) \preceq_{pT} \nullideal$.
 Fix functions 
  $\varphi \colon {\cNWD}^\omega \rightarrow \mcalN$ and $\tilde{\varphi} \colon \mathrm{OPEN}^\omega \rightarrow \mcalM$ as in Fact \ref{ZFC_meager_null}.
  We define
  $\pi \colon M_\sigma \rightarrow \mcalP(\mcalN)$ by 
  \begin{center}
  $\pi(Z)=\{\varphi(\langle Z_n \mid n<\omega \rangle) \mid \langle Z_n \mid n<\omega \rangle \in \cNWD^\omega \land Z=\bigcup_{n<\omega} Z_n \}.$
  \end{center}
  We show that $\pi$ is a pre-Tukey map.
  Suppose $X \in \mcalN$ and find $Y \in M_\sigma$ such that if $\pi(Z) \cap X\downarrow_{\subseteq}$ is non-empty then $Z \subseteq Y$, for any $Z \in \mcalM_\sigma$.
  We take $\langle G_n \mid n<\omega \rangle \in \mathrm{OPEN}^\omega$ such that $X \subseteq \bigcap_{n<\omega} G_n \in \mcalN$.
  We can take $Y \in M_\sigma$ such that $\tilde{\varphi}(\langle G_n \mid n<\omega \rangle) \subseteq Y$.
  By Fact \ref{ZFC_meager_null}, $Y$ is as desired.
\end{proof}

Next, we show $(\mcalN, \subseteq)\npreceq_{pT} (\mcalM, \subseteq)$ under the assumption $(\star)$.
To prove this,
we note the fact that the two-step iteration of Cohen forcing and Hechler forcing adds a meager set covering all meager sets coded in the ground model.

 The Hechler forcing notion $(\mbbD, \leq_\mbbD)$ is defined as follows:
 \begin{center}
 $\mbbD=\{(s,f)\mid s\in\omega^{<\omega}$, $f\in\omega^\omega$ and $s\subseteq f\}$,
 \end{center}
 and $(t,g)\leq_{\mbbD} (s,f)$ if $t\supseteq s$, $g(n)\geq f(n)$ for all $n\in\omega$ 
 and $t(i)\geq f(i)$ for all $i\in |t|\setminus |s|$.

