   $M\subseteq M_{f,x}=\{y\in 2^\omega\mid \forall^{\infty}n 
   \ (x\restrict I_n \neq y\restrict I_n)\}$,
 \end{center}
 where $I_n =[f(n), f(n+1))$.
\end{lemma}

\begin{lemma}\label{dominating}
 Let $V\subseteq W$ be models of $\ZFC$.
 If there is a dominating real $f\in\omega^\omega$ over $V$ in $W$,
 then there is a real $\tilde{f}\in\omega^\omega$ in $W$
 such that for all strictly increasing $g\in \omega^\omega$ in $V$
 for all but finitely many $n\in\omega$
