\begin{lemma}\label{Cohen_Hechler}
Assume $\AC$ in $V$.
 Suppose that $y\in\omega^\omega$ and
 $z\in \omega^\omega$ is a Cohen-Hechler real over $V[y]$.
 Then $C^{V[z]} \subseteq C^{V[y]}$.
\end{lemma}

\begin{proof}
 Let $(c,d)\in 2^\omega\times \omega^\omega$ be the pair of the Cohen real over $V[y]$ and the Hechler real over $V[y][c]$ coded by $z$.
 Since $z$ is Cohen-Hechler real over $V$,
 by Fact \ref{covering_meager} there is a meager set $X$ coded in $V[z]$ which covers all meager sets coded in $V$.
 Since $z$ is Cohen-Hechler over $V[y]$, $X$ covers all meager sets coded in $V[y]$ too.
 If $r$ is Cohen over $V[z]$ then $r\notin X$,
 so $r$ is not contained by any meager set coded in $V[y]$.
 Thus $r$ is Cohen over $V[y]$.
\end{proof}

We can show the following lemmas in the same way as the proof of 
Lemma \ref{Cohen_cofinal} and Lemma \ref{d_cofM_equiv}.
Let $\hat{\mcalN}$ be the conull filter over $2^\omega$.

\begin{lemma}\label{random_cofinal}
  Assume ($\star$).
   Let $x \in \omega^\omega$ and $B \subseteq 2^\omega$ be a conull set.
   Suppose that $(S, \varphi)$ is a Solovay code for $B$.
   Then $R^{L[S]} \subseteq B$.
 \end{lemma}


 \begin{lemma}\label{random_cofinal_M}
  Assume ($\star$).
  Then $\{R^{L[x]}\mid x\in\omega^\omega\}$ is cofinal in $(\hat{\mcalN}, \supseteq)$.
 \end{lemma}

\begin{lemma}\label{cofM_cofN_equiv}
 Assume $(\star)$.
 Suppose that for any set $S$  of ordinals,
  %such that  $\omega_1$ is inaccessible in $L[S]$,
 there exists $x\in\omega^\omega$ such that for every $y\in\omega^\omega$ 
 there exists $z\in\omega^\omega$ with $C^{L[z]}\subseteq C^{L[y]}$ and $R^{L[S][z]}\nsubseteq R^{L[S][x]}$.
 Then $(\mcalN, \subseteq)\npreceq_{pT} (\mcalM, \subseteq)$.
\end{lemma}

\begin{proof}
  To prove the contrapositive, assume that $(\mcalN, \subseteq)\preceq_{pT}(\mcalM, \subseteq)$.
  By Lemma \ref{Cohen_cofinal_M} we obtain a pre-convergent map $\sigma$
  from $(\{C^{L[x]}\mid x\in\omega^\omega\}, \supseteq)$ to $(\hat{\mcalN}, \supseteq)$.
  We define $f(C^{L[x]})=\bigcup \sigma(C^{L[x]})$ for each $x\in\omega^\omega$, 
  then $f$ is a convergent map from $(\{C^{L[x]}\mid x\in\omega^\omega\}, \supseteq)$ to $(\hat{\mcalN}, \supseteq)$.
  By $(\star)$ we can take 
   a set $S$ of ordinals and formula $\varphi$ such that 
   \begin{center}
    $u\in f(C^{L[v]}) \Leftrightarrow L[S][u][v]\models \varphi(S,u,v)$
   \end{center}
   for all $u,v\in \omega^\omega$.

   We suppose $x\in\omega^\omega$ and find $y\in\omega^\omega$ such that for every $z\in\omega^\omega$ if $C^{L[z]}\subseteq C^{L[y]}$ then  $R^{L[S][z]} \subseteq R^{L[S][x]}$.
   Since $f$ is convergent and $R^{L[S][x]} \in \hat{\mcalN}$,
   there is $y\in \omega^\omega$ such that 
   $f(C^{L[z]}) \subseteq R^{L[S][x]}$ for any $z\in\omega^\omega$ with $C^{L[z]} \subseteq C^{L[y]}$.
   By Lemma \ref{random_cofinal}, $R^{L[S][z]} \subseteq f(C^{L[z]})$.
   Thus if $C^{L[z]} \subseteq C^{L[y]}$ then 
   $R^{L[S][z]}\subseteq R^{L[S, x]}$.
\end{proof}

\begin{theorem}
 Assume $(\star)$. Then $(\mcalN, \subseteq) \npreceq_{pT} (\mcalM, \subseteq)$.
\end{theorem}

\begin{proof}
  Suppose $S$ is a set of ordinals.
 By Lemma \ref{cofM_cofN_equiv}, it suffices to find
 $x\in \omega^\omega$ such that for all $y\in \omega^\omega$ there is $z\in \omega^\omega$ with $C^{L[z]} \subseteq C^{L[y]}$ and $R^{L[S][z]} \nsubseteq R^{L[S][x]}$.

  We can take $x\in\omega^\omega$ such that $(2^{2^\omega})^{L[S]}$ is countable in $L[S][x]$.
  We suppose $y\in\omega^\omega$ and find $z\in\omega^\omega$ such that $C^{L[z]} \subseteq C^{L[y]}$ and $R^{L[S][z]} \nsubseteq R^{L[S][x]}$.
   Let $(c,d)$ be a $\mathbb{C}\ast\dot{\mathbb{D}}$-generic real over $L[S][x][y]$,
   and let $z\in\omega^\omega$ be a Cohen-Hechler real coding $(c,d)$.
   Note that $z$ is Cohen-Hechler over $L[y]$ too.
   In particular $C^{L[z]} \subseteq C^{L[y]}$ by Lemma \ref{Cohen_Hechler}.
   We show that $R^{L[S][z]} \nsubseteq R^{L[S][x]}$.

   In $L[S][z]$ let $\Gamma$ be the collection of Borel codes of null subsets of $2^\omega$.
   Since $\CD$ is c.c.c, $(2^\omega)^{L[S][z]}$ is countable in $L[S][x][z]$.
   Thus $\Gamma$ is countable in $L[S][x][z]$, so $B=\bigcup_{c\in\Gamma} B_c^{L[S][x][z]}$ is null in $L[S][x][z]$.
   Hence we can take $w\in (\omega^\omega)^{L[S][x][z]}\setminus B$. Then $w$ is random over $L[S][z]$.

   On the other hand, $w$ is in $L[S][x][z]$, a $\CD$ extension of $L[S][x]$.
   Since $\CD$ is $\sigma$-centered and  $\sigma$-centered forcing does not add
   random reals, $w$ is not random over $L[S][x]$.
\end{proof}

 \subsection{$(\omega_1 , \leq)$}
 In this subsection, we show that $\dominating \npreceq_{pT} \omegaone$ and $\omegaone \npreceq_{pT} \nullideal$.
 From these results and the results in the previous subsections, it follows that 
 $\omegaone \npreceq_{pT} (D, \leq_D)$ and $(D, \leq_D) \npreceq_{pT} \omegaone$ for any $(D, \leq_D)= \dominating, \meagerideal, \nullideal$.
 \begin{theorem}
  Assume $(\star)$.
  Then $\dominating \npreceq_{pT} \omegaone$.
 \end{theorem}

 \begin{proof}
  For $f, g\in \omega^\omega$, we write $f <^* g$ if $f(n) < g(n)$ for all but finitely many $n\in\omega$.
  Since $(\omega^\omega, <^*)$ is Tukey reducible to $\dominating$ and $\omegaone^*$ is isomorphic to $\omegaone$,
  it suffices to show that 
  $(\omega^\omega, <^*) \npreceq_{T} \omegaone$.
  We suppose $f$ is a function from $\omega^\omega$ to $\omega_1$ and show that $f$ is not a Tukey map.
  Let
  \begin{center}
     $X_f=\{(x,z)\in\omega^\omega\times \omega^\omega \mid 
     z \in \WO \land f(x)=o(z)\}$.
  \end{center}
  By $(\star)$ we can take a set $S$ of ordinals  and a formula $\varphi$ such that
  \begin{center}
    $(x,z) \in X_f \Leftrightarrow
    L[S][x][z] \models \varphi(S, x, z)$.
  \end{center}
  Let $c\in\omega^\omega$ be a Cohen real over $L[S]$ and let $\alpha = f(c)$.
  We show that for all $x\in\omega^\omega$ there exists $y\in\omega^\omega$ such that $f(y)=\alpha$ and $y \nless^* x$.

  Suppose $x\in\omega^\omega$.
  Let $\dot{z}$ be a $\collalpha$-name for a real and let $h$ be a $\collalpha$-generic filter over $L[S][x]$ such that $\dot{z}[h] \in \WO$ and $o(\dot{z}[h])=\alpha$.
  Then $\varphi(S, c, \dot{z}[h])$ holds in $L[S, c, \dot{z}[h]]$.
  We can take $p\in\mbbC$ and $q\in \collalpha$ such that 
  \begin{center}
    $L[S] \models p \Vdash_{\mbbC} q \Vdash_{\collalpha} \varphi (S, \dot{c}, \dot{z})$
  \end{center}
  where $\dot{c}$ is the canonical $\mbbC$-name for a generic real.
  We take a $\mbbC$-generic filter $g$ over $L[S][x]$ with $p \in g$ and let $y=\dot{c}_g$.
  We take a $\collalpha$-generic filter $h'$ over $L[S][x][y]$ with $q \in h'$ and
  let $z' = \dot{z}[h']$. Then $\varphi(S, y, z')$ holds in $L[S][y][z']$. Thus $f(y)=\alpha$.
  Since $y$ is a Cohen real over $L[S][x]$ and each Cohen real takes the same value infinitely often as any real in the ground model, 
  $y \nless^* x$ holds.
 \end{proof}

 Next, to prove $\omegaone \npreceq_{pT} \nullideal$
 we review basics on the amoeba forcing, a forcing which adds a null set covering all null sets coded in the ground model.

 The amoeba forcing notion is 
 \begin{center}
  $\mbbA=\{U \subseteq 2^\omega \mid U$ is open and $\mu(U)<1/2\}$
 \end{center}
 ordered by reverse inclusion.
 \begin{fact}\label{fact_amoeba_covering}
  Assume $\AC$ in $V$.
  Let $G$ be an $\mbbA$-generic filter over $V$.
  Then $G$ induces a Borel code of $G_\delta$ null set which covers all null sets coded in $V$.
  In particular, $R^{V[G]} \subseteq R^V$.
 \end{fact}
 Suppose  $W$ is an inner model of $\ZFC$.
 $a\in\omega^\omega$ is called an \textit{amoeba real} over $W$ if $a$ is a Borel code of a null set as in Fact \ref{fact_amoeba_covering} induced by an $\mbbA$-generic filter over $W$.
 Just as the meager ideal corresponds to Cohen forcing and the null ideal corresponds to random forcing, there is a $\sigma$-ideal associated with  amoeba forcing. 
 See 3.4.B in \cite{bartoszynski1995set} for the definition of the ideal and basics.
 From this characterization, we can obtain the following.
 \begin{fact}\label{fact_amoeba_generic}
  Suppose $W \subseteq V$ are transitive models of $\ZFC$.
  Let $G$ be an $\mbbA$-generic filter over $V$ and
  let $a\in\omega^\omega$ be an amoeba real induced by $G$. 
  Then there is an $\mbbA$-generic filter $G'$ over $W$ such that
  \begin{enumerate}
    \item $G'$ also induces $a$. Thus $a$ is an amoeba real also over $W$.
    \item For any $p \in \mbbA^W$ there is $q \in \mbbA^V$ such that $p \in G'$ if and only if $q\in G$.
  \end{enumerate}
 \end{fact}

 \begin{theorem}
    Assume $(\star)$.
    Then $\omegaone \npreceq_{pT} \nullideal$.
 \end{theorem}
 \begin{proof}
  If there is a pre-convergent map from $\nullideal$ to $\omegaone$ then we can easily construct a convergent map from $(\{R^{L[x]} \mid x\in \omega^\omega\}, \supseteq)$ to $(\omega_1, \leq)$.
  Thus we suppose $f$ is a function from $\{R^{L[x]} \mid x\in \omega^\omega\}$ to $\omega_1$
  and show that $f$ is not convergent.
  %We may assume that if $R^{L[y]}\subseteq R^{L[x]}$ then $f(R^{L[x]}) \leq f(R^{L[y]})$.
  Let
  \begin{center}
     $X_f=\{(x,z)\in\omega^\omega \times \omega^\omega \mid 
     z \in \WO \land f(R^{L[x]})=o(z)\}$.
  \end{center}
  By $(\star)$ we can take a set $S$ of ordinals and a formula $\varphi$ such that
  \begin{center}
    $(x,z) \in X_f \Leftrightarrow
    L[S][x][z] \models \varphi(S, x, z)$.
  \end{center}
  Let $a\in\omega^\omega$ is an amoeba real over $L[S]$ and suppose that $f(R^{L[a]})=\alpha$.
  We show that for all $x\in\omega^\omega$ there exists $y\in\omega^\omega$ such that $R^{L[y]}\subseteq R^{L[x]}$ and $f(R^{L[y]})=\alpha$.

  Suppose $x\in\omega^\omega$.
  Let $\dot{z}$ be $\collalpha$-name for a real and let $h$ be a $\collalpha$-generic filter over $L[S][x]$ such that $\dot{z}[h] \in \WO$ and $o(\dot{z}[h])=\alpha$. Let $z=\dot{z}[h]$.
  Then $\varphi(S, a, z)$ holds in $L[S, a, z]$.
  We can take $p\in\mbbA^{L[S]}$ and $q\in \collalpha$ such that
  \begin{center}
    $L[S] \models p\Vdash_{\mbbA} q\Vdash_{\collalpha} \varphi(S, \dot{a}, \dot{z})$
  \end{center}
  where $\dot{a}$ is the canonical $\mbbA$-name for a generic real.
  We take an $\mbbA^{L[S][x]}$-generic filter $g$ over $L[S][x]$ with $p \in g$ and let $y=\dot{a}[g]$.
  We take a $\collalpha$-generic filter $h'$ over $L[S][x][y]$ with $q \in h'$
  and let $z'=\dot{z}[h']$.
  Then $\varphi(S, y, z')$ holds in $L[S][y][z']$. Thus $f(R^{L[y]})=\alpha$.
  By Fact \ref{fact_amoeba_covering}, \ref{fact_amoeba_generic} and that $y$ is an amoeba real over $L[S][x]$, 
  $R^{L[y]}\subseteq R^{L[x]}$ holds.
 \end{proof}

 \subsection{$([\omega^\omega]^\omega, \subseteq)$}

 First, we show that $([\omega^\omega]^\omega, \subseteq)$ is pre-Tukey equivalent to the  constructibility degree on reals under the assumption $(\star)$.

 We define an order $\leq_L$ on $\omega^\omega$ by
 \begin{center}
    $x\leq_L y \Leftrightarrow x\in L[y]$.
 \end{center}
 \begin{lemma}\label{L-relation}
  Assume $(\star)$.
  Then $(\omega^\omega, \leq_L)\equiv_{pT} ([\omega^\omega]^\omega, \subseteq)$.
 \end{lemma}
 \begin{proof}
  We define $f \colon \omega^\omega \rightarrow [\omega^\omega]^\omega$  by $f(x)=(\omega^\omega)^{L[x]}$. 
  For $X\in [\omega^\omega]^\omega$ we can take $r_X \in\omega^\omega$ which codes a bijection from $\omega$ to $X$.
  We can show straightforwardly that for each $X \in [\omega^\omega]^\omega$, $r_X$ witnesses that $f$ is Tukey and convergent.
 \end{proof}

 The following facts are standard results in forcing theory. 
 These proofs can be found in Lemma 15.43 in \cite{jech2006set} and Theorem A.0.9 in \cite{larson2004stationary}.

 \begin{fact}\label{fact:immediate}
  Assume $\AC$ in $V$.
  Let $B$ be a complete Boolean algebra and 
  let $G$ be a $B$-generic filter over $V$.
  If $M$ is a model of $\ZFC$ such that $V \subseteq M \subseteq V[G]$, then there exists a complete subalgebra $D\subseteq B$ such that $M=V[D\cap G]$.
 \end{fact}

 \begin{fact}\label{fact:collapse_assorb}
  Assume $\AC$ in $V$.
  Let $\mbbP$ be a forcing notion with $\mbbP \in V_\alpha$
  and let $g$ be a $\mbbP$-generic filter over $V$.
  Suppose $G$ is a $\collapse{2^\alpha}$-generic filter over $V$.
  Then there is a $\collapse{2^\alpha}$-generic filter $H\in V[G]$ over $V[g]$ such that
  $V[G]=V[g][H]$.
 \end{fact}

 \begin{lemma}\label{lemma:countable_subset}
  Assume $(\star)$.
  Suppose $(\omega^\omega, \sqsubseteq)$ is  $\sigma$-directed.
  Then $(\omega^\omega, \sqsubseteq) \preceq_{pT} ([\omega^\omega]^\omega, \subseteq)$.
 \end{lemma}
 \begin{proof}
  We define $\pi \colon [\omega^\omega]^\omega \rightarrow \mcalP(\omega^\omega)$ By
  \begin{center}
    $\pi(X)=\{x\in\omega^\omega \mid \forall y\in X \  
    (y \sqsubseteq x)\}$.
  \end{center}
  For $x\in\omega^\omega$, each $X\in[\omega^\omega]^\omega$ with $x\in X$ witnesses that $\pi$ is pre-convergent.
 \end{proof}

 \begin{theorem}
  Assume $(\star)$.
  \begin{enumerate}
    \item $(\mcalN, \subseteq)\preceq_{pT} ([\omega^\omega]^\omega, \subseteq)$.
    \item $(\omega_1, \leq) \preceq_{pT} ([\omega^\omega]^\omega, \subseteq)$.
    \item $([\omega^\omega]^\omega, \subseteq) \npreceq_{pT} (\mcalN, \subseteq)$.
  \end{enumerate}
 \end{theorem}
 \begin{proof}
  Using Lemma \ref{lemma:countable_subset},
  $(1)$ follows from Lemma \ref{random_cofinal_M} and $(2)$ follows from $\omegaone \equiv_{pT} (\WO, \trianglelefteq)$.
\begin{comment}
  $(1) \colon $ We define $f \colon \omega^\omega \rightarrow \hat{\mcalN}$ by 
  $f(x) = R^{L[x]}$.
  It is easy to check that $f$ is a convergent map from $(\omega^\omega, \leq_L)$ to $(\{R^{L[x]}\mid x\in\omega^\omega\}, \supseteq)$.
  By Lemma \ref{random_cofinal_M}, it follows that $\nullideal \preceq_{pT} (\omega^\omega, \leq_L)$.

  $(2)$ : We define $\pi \colon \omega_1 \rightarrow \mcalP(\omega^\omega)$ by 
  \begin{center}
    $\pi(\alpha)=\{x \in \omega^\omega
    \mid x\in\WO \land o(x)=\alpha\}$.
  \end{center}
  We show that $\pi$ is a pre-Tukey map from $(\omega_1, \leq)$ to $(\omega^\omega, \leq_L)$.
  Suppose $x\in\omega^\omega$ and let $\alpha = \omega_1^{L[x]}$.
  Suppose $\beta<\omega_1$ and we show that 
  if $\pi(\beta) \cap x\downarrow_{\leq_L}$ is non-empty then $\beta < \alpha$.
  If $y \in \pi(\beta) \cap x\downarrow_{\leq_L}$
  then $y\in\WO$, $o(y)=\beta$ and $y \in L[x]$.
  Thus $\beta$ is countable in $L[x]$, so $\beta<\alpha$.
\end{comment}

  $(3) \colon $
  By Lemma \ref{random_cofinal_M} and \ref{L-relation}, it suffices to show that there is no pre-convergent map from 
  $(\{R^{L[x]} \mid x \in \omega^\omega\}, \supseteq)$ to $(\omega^\omega, \leq_L)$.
  Suppose $\pi$ is a function from 
  $\{R^{L[x]} \mid  x\in\omega^\omega\}$ to
  $\mcalP(\omega^\omega)$.
  Let
  \begin{center}
    $X=\{ (z,r)\in\omega^\omega\times \omega^\omega
    \mid r\in\WO \land
    \exists w \in \pi(R^{L[z]})(o(r)$ is uncountable in $L[w])\}$.
  \end{center}
  We take a set $S$ of ordinals and a formula $\varphi$ such that
  \begin{center}
    $(z, r)\in X \Leftrightarrow
    L[S][z][r] \models \varphi(S,z,r)$.
  \end{center}
  Let $z'\in\omega^\omega$ be an amoeba real over $L[S]$ and take 
  $w' \in \pi(R^{L[z']})$.
  Let $\alpha=\omega_1^{L[w']}$.
  Note that if $r\in \WO$ and $o(r)=\alpha$ then $(z', r) \in X$.

  Let $\delta$ be an ordinal such that $(2^{2^\alpha})^{L[S]} < \delta <\omega_1$.
  Let $\psi(S,z)$ denote the formula 
  \begin{center}
    $\forall r\in \WO (o(r)=\alpha \Rightarrow 
    L[S][z][r]\models \varphi(S, z, r))$.
  \end{center}
  Then by the homogeneity of $\collapse{\delta}$ it follows that
  \begin{center}
    $L[S][z']\models 1_{\collapse{\delta}} \Vdash_{\collapse{\delta}} 
    \psi(S, z', r)$.
  \end{center}
  Thus we can take $p\in\mbbA^{L[S]}$ such that 
  \begin{center}
    $L[S]\models p \Vdash_{\mbbA^{L[S]}} 1_{\collapse{\delta}} \Vdash_{\collapse{\delta}} 
    \psi(S, z', r)$.
  \end{center}
  Let $\dot{x}$ be a $\collapse{\alpha}$-name for a real and 
  let $g$ be a $\collapse{\alpha}$-generic filter over $L[S]$ such that $\dot{x}[g] \in \WO$ and $o(\dot{x}[g])=\alpha$.
  Let $x=\dot{x}[g]$.
  Suppose $y\in\omega^\omega$.
  To show that $\pi$ is not pre-convergent, we find $z,w \in \omega^\omega$ such that $R^{L[z]}\subseteq R^{L[y]}$, $w\in\pi(R^{L[y]})$ and $x \notin L[w]$.

  Let $h$ be an $\mbbA$-generic filter over $L[S][x][y]$ with $p\in h$ and let $z\in\omega^\omega$ be an amoeba real over $L[S][x][y]$ induced by $h$.
