\subsubsection{Additional discussions of conditions}
\label{append:conditions}

In this section, we provide additional examples and discussions for the technical conditions in Theorem \ref{thm_2}. More specifically, we first provide a number of common used sieve basis functions and the corresponding bounds for the relevant quantities in \eqref{eq_basicquantity} with these basis functions. Next, we provide a number of locally stationary time series that can be written in the form of \eqref{model_1}, and as such the condition in (\ref{eq_errorprecisionbound}) is satisfied. Finally, we provide a number of examples under which the conditions in (\ref{eq_boundoneboundtwo}) and (\ref{eq_assumtiondasdsadasdads}) are satisfied. In general, these conditions are mild and hold for many commonly encountered examples.

\begin{example}[Examples of commonly used sieve basis functions]
\label{exam_1}
We present several examples of commonly used basis functions $\{\alpha_\ell(t)\}$ used in \eqref{eq_secondapproximation}, along with the corresponding bounds for the relevant quantities in \eqref{eq_basicquantity} for these basis functions. All these examples can be implemented using the $\mathsf{R}$ package $\mathsf{Sie2nts}$.

The first example is the set of normalized Legendre polynomials \citep{bell2004special}. The Legendre polynomial of degree $\kappa \in \mathbb{N}$ defined on $[-1,1]$ can be obtained using Rodrigue's formula, 
\begin{equation*}
P_\kappa(t) = \frac{1}{2^\kappa \kappa!} \frac{\mathrm{d}^\kappa}{\mathrm{d}t^\kappa} (t^2 - 1)^n, \quad -1 \leq t \leq 1.
\end{equation*}
In our implementation, we obtain the Legendre polynomials by mapping $[-1,1]$ to $[0,1]$ and then normalizing them. For these polynomials, it is straightforward to verify that for the quantities in \eqref{eq_basicquantity}, we have that $\xi_c = \cO(1)$ and $\zeta_c = \cO(c)$.  

The second example is the set of normalized trigonometric functions, which are given by $\left\{ 1, \sqrt{2} \cos(2 \kappa \pi t), \sqrt{2} \sin(2 \kappa \pi t), \ldots \right\}, \kappa \in \mathbb{N}$. For  (\ref{eq_basicquantity}), we have that $\xi_c = \cO(1)$ and $\zeta_c = \cO(\sqrt{c})$ \citep{chen2007large}. 


The third example is the Daubechies wavelet basis \citep{daubechies1992ten}. The Daubechies scaling (father) wavelet function of order $\kappa \in \mathbb{N}$ is a square-integrable function on $\mathbb{R}$, with support on the interval $[0, 2 \kappa - 1]$, and satisfies the recursion equation as,
\begin{equation*}
\varphi(t) = \sqrt{2} \sum_{k=0}^{2\mathsf{\kappa}-1} h_k \varphi(2t - k), \quad \int_{\mathbb{R}} \varphi(t) \, \mathrm{d}t = 1, \quad \int_{\mathbb{R}} \varphi(2t - k)\, \varphi(2t - k') \, \mathrm{d}t = 0,
\end{equation*}
for $k \neq k', k, k' = 0, \ldots, 2\kappa - 1$, where $h_0, h_1, \ldots, h_{2\mathsf{N}-1} \in \mathbb{R}$ are the filter (low-pass) coefficients. For (\ref{eq_basicquantity}), we have that  $\xi_c = \cO(\sqrt{c})$ and $\zeta_c = \cO(\sqrt{c})$. 
\end{example}


\begin{example}[Examples of locally stationary time series satisfying \eqref{model_1}]
\label{exam_2}
We present two examples of locally stationary time series, which encompasses many commonly used models in the literature, that satisfy \eqref{model_1}. For each example, we also illustrate how the physical dependence measure defined in Definition \ref{defn_physcialdependence} can be computed.

The first example is the locally stationary linear process \citep{dahlhaus2019towards,WZ1}. For i.i.d.\ random variables $\{\epsilon_i\}$ and smooth functions $a_j(\cdot)$, $j = 0, 1, \ldots$, defined on $[0, 1]$, consider the linear process,
\begin{equation*}
G(t, \mathcal{F}_i) = \sum_{j = 0}^\infty a_j(t) \epsilon_{i-j}. 
\end{equation*} 
Such a form includes many commonly used models, for instance, time-varying AR, MA, and ARCH models \citep[][Example 2.13]{ding2023autoregressive}. For this process, the physical dependence measure $\delta(j, q)$ in Definition \ref{defn_physcialdependence} satisfies that $\delta(j, q) = \cO\big(\sup_{t \in [0,1]} |a_j(t)|\big)$ \citep{WZ1}.

The second example is a general class of locally stationary nonlinear time series \citep{dahlhaus2019towards,DZ1,WZ1}. For i.i.d.\ random variables ${\epsilon_i}$ and some measurable function $R$, consider the nonlinear process, 
\begin{equation*} 
G\left(t, \mathcal{F}_i\right) = R\big( t, G\left(t, \mathcal{F}_{i-1}\right), \epsilon_i \big).
\end{equation*} 
Such a form includes many commonly used locally stationary nonlinear processes, for instance, the nonlinear time-varying threshold autoregressive model \citep[][Section 2.1]{DZ1}. For this process, the physical dependence measure $\delta(j, q)$ in Definition \ref{defn_physcialdependence} satisfies that $\delta(j, q) = \cO(\chi^j)$ when $\chi < 1$, where 
\begin{equation*} 
\chi = \sup{t \in [0,1]} \sup_{x \neq x'} \frac{\|R(t, x, \epsilon_0) - R(t, x', \epsilon_0)\|_q}{|x - x'|}, 
\end{equation*} 
{for some $x_0$ such that $\sup_{t \in [0,1]} \left| R\left(t, x_0, \epsilon_i \right) \right|_q < \infty$.} 
\end{example}


\begin{example}[Examples of locally stationary time series satisfying (\ref{eq_boundoneboundtwo}) and (\ref{eq_assumtiondasdsadasdads})]
\label{exam_3} 
We present two examples of locally stationary time series that satisfy the conditions in (\ref{eq_boundoneboundtwo}) and (\ref{eq_assumtiondasdsadasdads}). 

The first example includes two classes of time-varying MA(1) models given by 
\begin{eqnarray*}
x_i & = & a_1(i/n_1) \epsilon_{i-1} + \epsilon_i, \;\; \textrm { for } i = 1, \ldots, n_1, \\
y_{i'} & = & a_2(i'/n_2) \eta_{i'-1} + \eta_{i'}, \;\; \textrm { for } i' = 1, \ldots, n_2, 
\end{eqnarray*}
where $a_1(\cdot)$ and $a_2(\cdot)$ are smooth functions, and ${\epsilon_i}$ and $\eta_{i'}$ are i.i.d.\ standard Gaussian random variables. For the two classes of time series, it is straightforward to see that the autocovariance function in (\ref{eqn_covij}) can be written as, 
\begin{eqnarray*}
\gamma_g(t, h) = 
\begin{cases}
a_g^2(t) + 1, & h = 0, \\
a_g(t), & h = 1, \\
0, & h \ge 2,
\end{cases}
\ \ g=1,2, 
\end{eqnarray*}
when $h \geq 0$. Consequently, we see that, for $g=1,2$, when the lag $j \asymp b_g^{a_g}$ with $0<a_g \leq 1$, Theorem \ref{thm_1} implies that, when $\sup_{t_1, t_2}|a_g(t_1)-a_g(t_2)| \gg n_g^{-C_g}$ for some large positive constants $C_1$ and $C_2$, we have $D_g^*(j) \asymp \sup_{t_1, t_2}|a_g(t_1)-a_g(t_2)|$. Together with Theorem \ref{thm_2}, we see that our proposed algorithm is to achieve a consistent classification performance if, for some large constant $C$, $\sup_{t_1, t_2}|a_1(t_1)-a_1(t_2)| > C \sup_{t_1, t_2}|a_2(t_1)-a_2(t_2)|$, or vice versa.

The second example includes two classes of time-varying AR(1) models given by 
\begin{eqnarray*}
x_i & = & a_1(i/n_1)x_{i-1} + \epsilon_i, \;\; \textrm { for } i = 1, \ldots, n_1, \\
y_{i'} & = & a_2(i'/n_2) y_{i'-1} + \eta_{i'}, \;\; \textrm { for } i' = 1, \ldots, n_2,
\end{eqnarray*}
where $a_1(\cdot)$ and $a_2(\cdot)$ are smooth functions satisfying that $\sup_{t \in [0,1]} |a_1(t)| < 1$ and $\sup_{t \in [0,1]} |a_2(t)| < 1$, and ${\epsilon_i}$ and ${\eta_{i'}}$ are i.i.d.\ standard Gaussian random variables. Following \cite{zhou2013inference}, the autocovariance functions for $h \geq 0$ satisfy that,
\begin{align*}
\gamma_g(t, h) = \frac{a_g^h(t)}{1 - a_g^2(t)} + \mathrm{O}(\log^2(n_g)/n_g), \ g=1,2. 
\end{align*}
Denote $\psi_g(t) = a_g(t)/[\{1-a_g^2(t)\}\{1-a_g(t)\}]$. Then, for $g=1,2$, when the lag $j \asymp b_g^{a_g}$ with $0<a_g \leq 1$, Theorem \ref{thm_1} implies that, when $\sup_{t_1, t_2}|\psi_g(t_1)-\psi_g(t_2)| \gg n_g^{-C_g}$ for some large positive constants $C_1$ and $C_2$, we have $D_g^*(j) \asymp \sup_{t_1, t_2}|\psi_g(t_1)-\psi_g(t_2)| \asymp \sup_{t_1, t_2}|a_g(t_1)-a_g(t_2)|$. Together with Theorem \ref{thm_2}, we see that our proposed algorithm is to achieve a consistent classification performance if, for some large constant $C$, $\sup_{t_1, t_2}|a_1(t_1)-a_1(t_2)| > C \sup_{t_1, t_2}|a_2(t_1)-a_2(t_2)|$, or vice versa.
\end{example}





