\subsection{Proofs}
\label{append:proofs}

In this section, we provide the technical proofs of the main results presented in Section \ref{sec:theory}. 

We first summarize some important results from the literature. According to Lemma 2.6 of \cite{DZ1}, under Assumption \ref{assu_basicassumption}, for the autocovariance function, we have,
\begin{equation}\label{eq_autocovcontrol}
\sup_t|\gamma(t,j)|=\cO(j^{-\tau}), \ j \geq 1. 
\end{equation} 
Moreover, according to the proof of Theorem 2.4 of \cite{ding2023autoregressive}, for $b>0$ and the $b \times b$ matrix $\Gamma^b(t)=(\Gamma^b_{\ell_1 \ell_2}(t)) \in \mathbb{R}^{b \times b}$ whose entries are defined as in (\ref{eq_gammaentries}) with $j=b,$ we have that, for its inverse matrix $\Omega^b(t)=(\Gamma^b(t))^{-1}$ in (\ref{eq_precision})
\begin{equation}\label{eq_inversebound}
\sup_t|\Omega^b_{\ell_1 \ell_2}(t)|=\cO\left( (b/\log b)^{-\tau+1}+ \mathbb{I}(|\ell_1-\ell_2|<b/\log b) r^{|\ell_1-\ell_2| \log b/b} \right),
\end{equation}
where $0<r<1$ is some universal constant. 



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Proof of Theorem \ref{thm_1}}
\label{append:proofthm1}

For part (a), given $b>0$, for (\ref{eq_firstapproximation}), write $\boldsymbol{\phi}(t) = (\phi_{1}(t), \ldots, \phi_{b}(t))^\top \in \mathbb{R}^b$. Recall that $\Omega^b(t) = (\Gamma^b(t))^{-1}$ in (\ref{eq_precision}). By Theorem 2.11 of \cite{ding2023autoregressive}, we have that  
\begin{equation}\label{yule}
\boldsymbol{\phi}(t) = \Omega^b(t) \bm{\nu}^b(t),
\end{equation} 
where $\boldsymbol{\nu}^b(t)=(\nu^b_1(t), \ldots, \nu^b_b(t))^\top \in \mathbb{R}^b$, with $\nu^b_\ell(t)=\gamma(t,\ell), 1 \leq \ell \leq b.$ By Assumption \ref{assu_basicassumption}, (\ref{yule}) is well defined for all $b$. Therefore, part (a) of the theorem comes directly from (\ref{yule}). 

For part (b), the first result, using (\ref{yule}), for $1 \leq j \leq b$, we have
\begin{align}\label{eq_basicdecomposition}
\phi_j(t_1)-\phi_j(t_2)& =\left[\Omega^b(t_1) \bm{\nu}^b(t_1)-\Omega^b(t_1) \bm{\nu}^b(t_2) \right]^\top \bm{e}_j+\left[\Omega^b(t_1) \bm{\nu}^b(t_2)-\Omega^b(t_2) \bm{\nu}^b(t_2)\right]^\top \bm{e}_j \nonumber \\
&:=P_1 + P_2.
\end{align} 
From (\ref{eq_basicdecomposition}), we have that
\begin{equation*}
|\phi_j(t_1)-\phi_j(t_2)| \leq |P_1| + |P_2|.
\end{equation*} 

For $P_1,$ by definition, we have that 
\begin{equation*}
P_1=\sum_{j'=1}^b (\gamma(t_1,j')-\gamma(t_2,j')) \Omega^b_{j'j}(t_1).
\end{equation*}
By the definition (\ref{eq_wjkdefinition}) and the bound in (\ref{eq_inversebound}), we see from triangle inequality that 
\begin{equation*}
\sup_{t_1, t_2 \in [0,1]}|P_1|=\cO\left( \sum_{j'=1}^b w_j(j') \sup_{t_1, t_2 \in [0,1]} |\gamma(t_1, j')-\gamma(t_2,j')| \right).
\end{equation*}

For $P_2,$ we have that
\begin{equation*}
P_2=\sum_{j'=1}^b  \gamma(t_2,j')(\Omega^b_{j'j}(t_1)-\Omega^b_{j'j}(t_2)). 
\end{equation*}
Together with (\ref{eq_autocovcontrol}), we have that 
\begin{equation}\label{eq_P2RESULS}
\sup_{t_1, t_2 \in [0,1]}|P_2|=\cO\left( \sum_{j'=1}^b (j')^{-\tau} \sup_{t_1, t_2 \in [0,1]} |\Omega^b_{j'j}(t_1)-\Omega^b_{j'j}(t_2)| \right).
\end{equation}
This leads to the first result of part (b). 

For part (b), the second result, when $b$ is large, we have that
\begin{align*}
\sum_{j'=1}^b (j')^{-\tau} r^{|j'-j| \log b/b} & =\sum_{j'=1}^{j-1} (j')^{-\tau} r^{(j-j') \log b/b}+\sum_{j'=j}^b (j')^{-\tau} r^{(j'-j) \log b/b} \\
& =\sum_{j'=1}^{j-1} (j')^{-\tau} r^{(j-j') \log b/b}+\cO\left(j^{-\tau+1} \right). 
\end{align*}
Since $j \asymp b^{a}, 0<a\leq 1,$ we have that 
\begin{equation*}
\sum_{j'=1}^{j-1} (j')^{-\tau} r^{(j-j') \log b/b}=\cO \left(\sum_{j'=1}^{j-1} r^{(j-j') \log j/j} \right).
\end{equation*}
Following a similar discussion of (D.8) in \cite{ding2023autoregressive}, we have that 
\begin{equation*}
\sum_{j'=1}^{j-1} r^{(j-j') \log j/j}=\cO\left( j^{-\tau+1}\right). 
\end{equation*}
Combining the above results with (\ref{eq_inversebound}) and (\ref{eq_P2RESULS}) leads to the second result of part (b). 

For part (c), using (\ref{eq_basicdecomposition}), we have that 
\begin{equation*}
D^*(j) \geq  | P_1 |-|P_2|.
\end{equation*} 
Then the rest of the proof comes from the second result of part (b). 

Together, this completes the proof of Theorem \ref{thm_1}. 
\eop



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Proof of Theorem \ref{thm_2}}
\label{append:proofthm2}

For notional simplicity, denote $\phi_{j,1}(t), 1 \leq j \leq b_1$, and $\phi_{j,2}(t), 1 \leq j \leq b_2$, as the smooth AR approximation coefficient functions for the two classes of time series,  respectively. By Theorem 2.11 of \cite{ding2023autoregressive}, under Assumption \ref{assu_mainmainmain}, we have that $\phi_{j,g}(t)\in C^{d_g}([0, 1])$, $1 \le j \le b_g$, $g=1,2$. 

For part (a), without loss of generality, we focus our proof for $D_1$. Denote
\begin{equation*}
\phi_{j,1,c_1}=\sum_{\ell=1}^{c_1} a_{j\ell,1} \alpha_\ell(t).  
\end{equation*}
Let $\widehat{\phi}_{j,1}(t)$ be the sample estimator as in (\ref{eq_phihat}). By triangle inequality, we have 
\begin{equation*}
\sup_j\|\phi_{j,1}(t)-\widehat{\phi}_{j,1}\| \leq \sup_j |\phi_{j,1}-\phi_{j,1,c_1}(t)| + \sup_j \|\phi_{j,1,c_1}(t)-\widehat{\phi}_{j,1}(t)\|.
\end{equation*} 
Note that $\sup_j |\phi_{j,1}-\phi_{j,1,c_1}(t)|$ can be bounded using (\ref{eq_secondapproximation}), in that 
\begin{equation*}
\sup_j |\phi_{j,1}-\phi_{j,1,c_1}(t)|=\cO\left(c_1^{-d_1} \right).
\end{equation*}
Meanwhile, for $\sup_j \|\phi_{j,1,c_1}(t)-\widehat{\phi}_{j,1}(t)\|$, by (\ref{eq_third_ols}) and OLS, using (\ref{eq_phihat}) and $\bm{\beta} \in \mathbb{R}^{b_1c_1}$ collecting all $\{a_{j\ell,1}\}$, we have that 
\begin{equation*}
\phi_{j,1,c_1}(t)-\widehat{\phi}_{j,1}(t)=\left(\bm{\beta}-\widehat{\bm{\beta}} \right)^\top \mathbf{B}_j(t). 
\end{equation*} 
Consequently, by the definition (\ref{eq_basicquantity}), we have that 
\begin{equation}\label{eq_deodeodeodoeodeoeo}
\sup_j \|\phi_{j,1,c_1}(t)-\widehat{\phi}_{j,1}(t) \| \leq \| \bm{\beta}-\widehat{\bm{\beta}} \| \zeta_{c_1}. 
 \end{equation}
Thus it suffices to bound $\bm{\beta}-\widehat{\bm{\beta}}$. 

Toward that end, we have that  
 \begin{equation*}
 \bm{\beta}-\widehat{\bm{\beta}}=(n_1^{-1}Y^\top Y)^{-1} \frac{Y^\top \bm{\epsilon}}{n_1},
 \end{equation*}
where $\bm{\epsilon}=(\epsilon_{b_1+1} + \tilde{e}, \ldots, \epsilon_{n_1} + \tilde{e})$ with $\tilde{e}$ representing the error term in (\ref{eq_third_ols}). Following a similar idea of \cite{ding2024partial}, we have that 
\begin{equation*}
\left\| \frac{1}{n_1} Y^\top Y- \int_0^{1} \Gamma^{b_1}(t) \otimes \left( \bm{\alpha}(t) \bm{\alpha}(t)^\top \right)  \right\|=\cO\left(b_1c_1 \left(\frac{\xi_{c_1}^2}{\sqrt{n_1}}+\frac{\xi_{c_1}^2 n_1^{\frac{2}{\tau_1+1}}}{n_1} \right) \right),
\end{equation*} 
where $\Gamma^{b_1}(t) \in \mathbb{R}^{b_1 \times b_1}$ is defined as in (\ref{eq_gammaentries}), $\bm{\alpha}(t) \in \mathbb{R}^{c_1}$ collects the basis functions, and $\otimes$ is the Kronecker product. By assumption (\ref{eq_errorprecisionbound}) and Lemma A.1 of \cite{ding2024partial}, we obtain that
\begin{equation*}
\left\| (n_1^{-1}Y^\top Y)^{-1} \right\|=\cO_{\mathbb{P}}(1).
\end{equation*} 
Finally, following a similar discussion in \cite{ding2024partial}, we have that 
\begin{equation*}
\left\| \frac{Y^\top \bm{\epsilon}}{n_1} \right\|=\cO_{\mathbb{P}}\left( \xi_{c_1} \left(1+\frac{b_1^2}{n_1}+b_1 c_1^{-d_1} \right) \sqrt{\frac{b_1c_1}{n_1}} \right). 
\end{equation*} 
Combining the above bounds, we obtain that
\begin{equation*}
\|\bm{\beta}-\widehat{\bm{\beta}} \|=\cO_{\mathbb{P}} \left(\xi_{c_1} \left(1+\frac{b_1^2}{n_1}+b_1 c_1^{-d_1} \right) \sqrt{\frac{b_1c_1}{n_1}}\right). 
\end{equation*}
Combining this with (\ref{eq_deodeodeodoeodeoeo}) leads to part (a). 

For part (b), without loss of generality, suppose that $g_1=1$ and $g_2=2$. By part (a) of this theorem, part (c) of Theorem \ref{thm_1}, and by assumption (\ref{eq_boundoneboundtwo}), we have that, for some constant $c>0$,
\begin{equation*}
S_1>c \sup_{\max\{b_1-b_1^*+1, b_1^*\} \leq j \leq b_1} \sup_{t_1, t_2 \in [0,1]}\left|\sum_{j'=1}^b w_j(j')(\gamma_1(t_1,j')-\gamma_1(t_2,j')) \right| \left(1+\co_{\mathbb{P}}(1) \right). 
\end{equation*}
On the other hand, by part (a) of this theorem, part (b) of Theorem \ref{thm_1}, and assumptions (\ref{eq_boundoneboundtwo}) and (\ref{eq_assumtiondasdsadasdads}), we have that 
\begin{equation*}
S_2 \leq C^{-1}  \sup_{\max\{b_1-b_1^*+1, b_1^*\} \leq j \leq b_1} \sup_{t_1, t_2 \in [0,1]}\left|\sum_{j'=1}^b w_j(j')(\gamma_1(t_1,j')-\gamma_1(t_2,j')) \right| \left(1+\co_{\mathbb{P}}(1) \right).
\end{equation*}
Since the constant $C$ in (\ref{eq_assumtiondasdsadasdads}) is sufficiently large, we therefore have,  
\begin{equation*}
\mathbb{P}(S_1>S_2)=1+\co(1). 
\end{equation*}

This completes the proof of Theorem \ref{thm_2}. 
\eop



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Proof of Corollary \ref{cor_1}}
\label{append:proofcor1}

Since our algorithm does not rely on the number of time series $N_1, N_2$ and $N_3$, in what follows, without loss of generality, we suppose $N_1=N_2=N_3=1$. Denote $S_g^*$ as in (\ref{eq_featurefinaldefinition}) by replacing $D_g(j)$ with $D_g^*(j)$ in (\ref{eq_populationfeatures}). Following the proof of Theorem \ref{thm_2}, under assumption (\ref{eq_assumtiondasdsadasdads}), and without loss of generality, suppose $g_1=1$ and $g_2=2$, we have that 
\begin{equation}\label{eq_consitency}
S_g=S^*_g(1+\co(1)), \ g=1,2, \ S_1^*-S_2^*=(S_1-S_2)(1+\co(1)), \ \text{and} \ S_1^*>S_2^*. 
\end{equation} 
Let $S_3$ and $S_3^*$ denote the associated quantities with the testing data $\bm{z}$. Theoretically, for any threshold $\vartheta \in [S_2^*, S_1^*]$, $\mathbf{z}$ is from class 1 if $S^*_3 \geq \vartheta$, and from class 2 otherwise. Moreover, by part (a) of Theorem \ref{thm_2} and (\ref{eq_consitency}), with a high probability, Algorithm \ref{algo_1} is to assign $\bm{z}$ correctly to class 1 if $\vartheta \in [S_2, S_1]$ and $S_3 \geq \vartheta$.

Finally, based on our choice in (\ref{com_C}), we have that, with a high probability and when the time series are sufficiently long,
\begin{equation*} 
{C}_1 < S_2 < S_1 < {C}_2. 
\end{equation*}
Consequently, when $M$ is sufficiently large, some of the grid points in $\vartheta_i$ would, with a high probability, fall within the interval $[S_2, S_1]$. Moreover, the procedure described in Section \ref{subsec:classify} would select one of these thresholds that yields the best practical performance and again, with a high probability, assigns $\bm{z}$ to the correct class. 

This completes the proof of Corollary \ref{cor_1}.
\eop


