	\section{Equality of symplectic transvections and isometeries}

	Let $R$ be a ring. The pair $(P, \lrinn{}{})$ is called a symplectic $R$-module, if $P$ is a projective $R$-module and $\lrinn{}{}$ a non-degenerate alternating bilinear form on $P$. The form `$\psi_n$' defined in Section \ref{s2} gives the standard (non-degenerate alternating) form on the free $R$-module $R^{2n}$. We call $(P,\lrinn{}{})$ the free symplectic $R$-module, if $P$ is free with the standard form. We only consider finitely generated modules in this section.

	Given two symplectic $R$-modules $(P, \lrinn{}{}_1)$ and $(Q, \lrinn{}{}_2)$ one may define a non-degenerate alternating bilinear form on $P \oplus Q$ given by
	$$\lrinn{p_1+q_1}{p_2+q_2} := \lrinn{p_1}{p_2}_1 + \lrinn{q_1}{q_2}_2.$$
	This combination of symplectic modules is denoted as $(P \perp Q, \lrinn{}{})$. We prefer to omit the distinguishing subscripts on the inner products, whenever the distinction between the inner products is clear from the context.

	Consider a symplectic $R$-module $(P, \lrinn{}{})$ and $\m \in \Max(R)$. One may define a corresponding local symplectic $R_{\m}$-module by  $(P_{\m}, \lrinn{}{}_{\m}),$ where
	$$ \Lrinn{\frac{p}{s}}{\frac{q}{s'}}_{\m}:= \frac{1}{ss'}\lrinn{p}{q},$$
	for $p, q \in P$ and $s, s' \in R \smallsetminus \m$.

	An isomorphism $\theta: (P, \lrinn{}{}) \rightarrow (Q, \lrinn{}{})$  of symplectic $R$-modules is a form preserving $R$-isomorphism between $P$ and $Q,$ \textit{i.e.,} $\theta: P \rightarrow Q$ is an isomorphism of $R$-modules satisfying:
	$$\langle p_1, p_2 \rangle = \langle \theta(p_1), \theta(p_2) \rangle,$$
	for $p_1, p_2 \in P$. These form preserving automorphisms of $(P,\lrinn{}{})$ are denoted by ${\Sp}(P)$. Following the definitions of Bass, we define the elementary transvections on $P \perp R^2,$ denoted by $\Etrans_{\Sp}(P \perp R^2)$, as the subgroup of $\Sp(P \perp R^2)$ generated by the automorphisms $\Delta_q$ and $\Gamma_q$:
	\begin{eqnarray*}
		\Delta_q:& ( p,a,b) ~\mapsto~(p+bq, a-\lrinn{p}{q}+b, b),\\
		\Gamma_q:& (p,a,b)~\mapsto~(p + aq, a, b+\lrinn{p}{q}-a),
	\end{eqnarray*}
	where $p, q \in P$ and $a,b \in R$. On fixing $q \in P,$ define $\phi_q \in {\Hom}_R(P,R)$ as $\phi_q(p) = \lrinn{p}{q},$ for $p \in P$.

	\begin{remark}\label{r2}
		Let $M$ be a monoid and $(P, \phi)$ a symplectic $R[M]$-module such that $P \simeq R[M]^{2k}$ for some $k>0$. Then by  (\cite{Lam-MR2235330}, Theorem 5.8) we have
		$$(P, \phi) \simeq (P, \psi_k),$$
		as symplectic $R[M]$-modules.
	\end{remark}

	\begin{proposition}\label{p4}
		Let $R$ be a regular ring of dimension d with ${\KK}_1{\Sp}(R)=0$ and $A=R[X_1, \ldots, X_m, Y_1^{\pm{1}}, \ldots, Y_{n}^{\pm{1}}]$. Let $P$ be a symplectic $A$-module of rank $2k,$ where $k \geq \max\{2, d+1\}$. Then
		$${\Etrans}_{\Sp}(P \perp A^{2}) = {\Sp}(P \perp A^2).$$
	\end{proposition}

	\begin{proof}
		%SK_1(A)=0 or use P is extended
		From Corollary \ref{cktheorysp} we have the following:
		\begin{enumerate}
			\item ${\Sp}_{2l}(A) = {\ESp}_{2l}(A)$ for $l\geq d+2$,
			\item 	$P$ is stably free, $i.e.,$ $P \perp A^{2t} \simeq A^{2k+2t},$ for some $t\geq0$.
		\end{enumerate}


		\noindent If $t=0,$ we are done by (\cite{BBR-MR2578513}, Lemma 2.20). Let $\alpha \in {\Sp}(P \perp A^2)$. Then
		\begin{align*}
			\hspace{3cm}\alpha \perp {\I}_{2t-2} &\in {\Sp}(P \perp A^{2t})\\
			&= {\Sp}_{2(k+t)}(A)\\
			&= \Ep_{2(k+t)}(A) \hspace{2cm}\\
			&= {\Etrans}_{\Sp}(P \perp A^{2t})  \hspace{1cm} (\text{By (\cite{BBR-MR2578513}, Lemma 2.20})
		\end{align*}

		\noindent From the Stabilization Theorem in \cite{Kop-MR497932}, the natural map  $\Phi_{\Sp(l^+)}: \frac{{\Sp}(P \perp R^2)}{{\Etrans}_{\Sp}(P \perp R^2)} \rightarrow  \frac{{\Sp}(P \oplus R^{2l})}{{\Etrans}_{\Sp}(P \perp R^{2l})}$ is an isomorphism for all $l \geq 1$. Thus  $\alpha \in {\Etrans}_{\Sp}(P \perp R^{2}).$ 
	\end{proof}

	On application of local-global theorem for transvection group, the results of Section \ref{s3} can be extended to prove Theorem \ref{t6}:	

	\begin{proof}[\textbf{Proof of Theorem \ref{t6}}]
		Let $A=R[L]$ and $\alpha \in {\Sp}(P \perp A^2)$. By Proposition \ref{p4} and descending into the interior (as in Theorem \ref{t1}), we can assume $L$ is a finite rank positive normal $c$-divisible monoid with $\phi(L)$ closed polytope. 

		Let $\m \in \max(R)$. Since $R$ is regular, by Corollary 1.4 of \cite{Swan-andersonMR1144038} and Remark \ref{r2}, $P_{\m}$ is a free symplectic $A_{\m}$-module. On application of Theorem \ref{t3},
		$$\alpha_{\m} \in  {\Sp}(A_{\m}^{2k+2}) = {\Sp}_{2k+2}(A_{\m}) =  {\ESp}_{2k+2}(A_{m}).$$
		\noindent Therefore, there exists $r \in R \smallsetminus \m,$ such that $\alpha_{r} \in \Ep_{2k+2}(A_r)$. Since $R$ has a finite cover, we may choose $r_i \in R$ such that $(r_1, \ldots, r_k) =1$ and $\alpha_{r_i} \in \Ep_{2k+2}(A_{r_i})$ for $1 \leq i \leq k$. Choose an affine $L$-submonoid $L'$ such that $\alpha \in {\Sp}_{2k+2}(R[L'])$ satisfying $\alpha_{r_i} \in \Ep_{2k+2}(R_{r_i}[L'])$ for all $i$ and $P$ is a symplectic $R[L']$-module. By Proposition 1.7 and 1.15 of \cite{Gubeladze-ClassicalMR1079964} there exist a simplex $\Delta$ enveloping $\phi(L)$ such that
		$$L' \subset L \subset \mathbb{Q}_+ \otimes \Delta(L) \simeq \mathbb{Q}_+^{r'}.$$

		\noindent Here $R[L']$ has an inherited positive $\pz{r'}$-grading with $R[L']_0=R$. From (\cite{BBR-MR2578513}, Lemma 2.20), 
		$$\alpha_{\m} = (\alpha_{r})_{\m}\in  {\ESp}_{2k+2}(R_{\m}[L']) = {\Etrans_{\Sp}(P_{\m})}.$$
		Since ${\KK}_1{\Sp}(R)=0,$ we may assume  $\alpha \in {\Sp}(R[L'], R[L']_+)$. By (\cite{Rab-man}, Theorem 5.4) we have the required.
	\end{proof}

	Using Theorem \ref{t7}, we show the corresponding result for transvections:

	\begin{theorem}\label{t8}
		Let  $R$ be a regular ring of dimension $d,$ ${\KK}_1{\Sp}(R)=0$ and $L$ be a c-divisible monoid, where $c > 1$.  Let $P$ be a symplectic module of rank $2k$. Then ${\Etrans}(P \perp R[L]^2) = {\Sp}(P \perp R[L]^2)$, if
		\begin{enumerate}[(i)]
			\item $d \leq 1,$ ${\ESp}_{4}(R) = {\Sp}_{4}(R)$  and $k \geq 1$.
			\item R is a geometrically regular ring containing a field and $2k \geq \max\{1, d-1\}$. 
		\end{enumerate}
	\end{theorem}
