	\section{Auxiliary results}

	In the hypothesis of Theorem \ref{t1}, we had to enforce the condition $${\ESp}_{2k}(R[X_1, \ldots, X_m, Y_1^{\pm{1}}, \ldots, Y_n^{\pm{1}}]) = {\Sp}_{2k}(R[X_1, \ldots, X_m, Y_1^{\pm{1}}, \ldots, Y_n^{\pm{1}}])$$ for $R \in \mathcal{R}_k$. In order to remedy this, we define a much general class of ring $\mathcal{R}'_n,$ which automatically satisfies this requirement. It can be shown that the conclusion of Theorem \ref{t1} also holds for rings in $\mathcal{R}'_n$.  We say $R \in \mathcal{R}'_n,$ if
	\begin{enumerate}[(i)]
		\item ${\ESp}_{2n}(R) = {\Sp}_{2n}(R)$ and

		\item If there exist finite rings  $R=R_1, R_2 \ldots, R_k=R'$ for $k>1,$ such that for $1 < i \leq k$,

		$R_i$ is either $R_{i-1}(X)$ or ${(R_{i-1})}_{\m}$ where $\m \in \Max(R_{i-1})$
		Then  ${\ESp}_{2n}(R') = {\Sp}_{2n}(R')$.
	\end{enumerate}

	\noindent Then we have the following interesting result:

	\begin{proposition}\label{l7}
		Let $R \in \mathcal{R}'_n$ and $s, t \geq 0$. Then 
		$${\Sp}_{2n}(R[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_s^{\pm{1}}]) = {{\ESp}_{2n}}(R[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_s^{\pm{1}}]).$$
	\end{proposition}

	\begin{proof}
		Let $s=0$. Then we need to show the equality  
		$${\Sp}_{2n}(R[X_1, \ldots, X_t]) = {{\ESp}_{2n}}(R[X_1, \ldots, X_t]).$$ 
		Let $\beta \in {\Sp}_{2n}(R[X_1, \ldots, X_t])$ and $R' = R(X_1, \ldots, X_{t-1})$. Since $R' \in \mathcal{R}_n,$ $\beta \in \Ep_{2n}(R'(X_t)) \cap {\Sp}_{2n}(R'[X_t])$. There exists a monic polynomial $f \in R'[X_t],$ such that $\beta_f \in \Ep_{2n}(R'[X_t]_f)$. By Theorem 3.10 of \cite{Kop-MR497932}, $\beta \in \Ep_{2n}(R'[X_t])$.


		Let $R''=R[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_{s-1}^{\pm{1}}]$ and $S_1 (~S_2, \text{ resp.})$ be the multiplicative subset of $R''[Y_s, Y_s^{-1}]$, consisting of all monics in $Y_s (~Y_s^{-1}, \text{ resp.})$. For the case of Laurent polynomial rings, observe that for $\alpha \in {\Sp}_{2n}(R[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_s^{\pm{1}}])$ we have
		$$\alpha \in {\Sp}_{2n}(R(Y_s)[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_{s-1}^{\pm{1}}]. $$
		Since $R(Y_s) \in \mathcal{R}_n,$ thus by induction on $s+t$ we may conclude 
		$$\alpha \in {\ESp}_{2n}(R(Y_s)[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_{s-1}^{\pm{1}}]) \subseteq {\ESp}_{2n}(S_1^{-1}R''[Y_s, Y_s^{-1}]).$$
		Similarly we may show $\alpha \in {\ESp}_{2n}(R(Y_s^{-1})[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_{s-1}^{\pm{1}}]) \subseteq {\ESp}_{2n}(S_2^{-1}R''[Y_s, Y_s^{-1}]).$
		By Lemma 4.1 of \cite{Kop-MR497932}, we may conclude and say $\alpha \in {\ESp}_{2n}(R[X_1, \ldots, X_t, Y_1^{\pm{1}}, \ldots, Y_{s-1}^{\pm{1}}][Y_s, Y_s^{-1}]).$
	\end{proof}

	\noindent Using the above proposition, the reader may show that Theorem \ref{t1} holds for rings in $\mathcal{R}'_n$ as well.

	\begin{theorem}\label{t5}
		Let  $R \in \mathcal{R}'_n$ for some $n$ and $L$ be a c-divisible monoid, where $c > 1$. Then $${\ESp}_{2n}(R[L]) = {\Sp}_{2n}(R[L]).$$ 
	\end{theorem}

	We may similarly obtain the below from Theorem \ref{t5}:


	\begin{theorem}
		Let $R \in \mathcal{R}'_t$ and $L$ be a $c$-divisible monoid. Let $P$ be a symplectic $R[L]$-module extended from $R$. If $rank(P)=2t-2,$ then
		$${\Sp}(P \perp R[L]^2) =  {\Etrans}_{\Sp}(P \perp R[L]^2).$$
	\end{theorem}

