The following observations from \cite{cvitanic2009optimal} and \cite{cvitanic2018dynamic} is important for our later proof. 
\begin{proposition}\label{prop L}
Assume $w\in C^{3, 2}(\mathbb{R}\times \mathbb{R} \times [0, T])$ and $L_y<0<L_x$, then along the solution path $\left\{ \left(x^*(s), y^*(s)\right) \right\}_{t\leq s \leq T}$, the function $L$
 is a constant, i.e., 
\[
L\left(x^*(s), y^*(s), s\right) = L(x, y, t), \quad \forall s \in [t, T].
\]
Moreover, at time $T$ we have 
\begin{equation}
L(x, y, T)=w(x, y, T)+cw_y(x, y, T) = U_P\left(x-U_A^{-1}(y)\right)-c U_P^{\prime}\left(x-U_A^{-1}(y)\right) (U_A^{-1})^{\prime}(y).
\label{eq L^T}
\end{equation}
\end{proposition}
\begin{remark}\label{rmk 2d sur}
This proposition implies that $\left(x^*(s), y^*(s), s\right)$ evolves on a 2-dimensional surface, which is characterized by $L(x, y, s) = const$.  
Later after we prove the equivalence, we see that $y^*(s) = v^*(x^*(s), s)$, and it is no astonishing that $\bigg(x^*(s), v^*\big(x^*(s), s\big), s\bigg)$ is two-dimensional. 

Denote by $\mathcal{S}(l): = \bigg\{(x, y, t) \in \mathbb{R}^2 \times [0, T]\bigg| L(x, y, t) = l  \bigg\}$ for any constant $l \in \mathbb{R}$. Then we see $\cup_{l \in \mathbb{R}} \mathcal{S}(l) = \mathbb{R}^2 \times [0, T]$, $\mathcal{S}(l_1)\cap \mathcal{S}(l_2) = \emptyset$, $\forall l_1\neq l_2$. Moreover, given Proposition \ref{prop L}, $\mathcal{S}(l)$ is non-empty if and only if $l$ is in the image of function $L(x, y, T) = U_P\left(x-U_A^{-1}(y)\right)-\frac{c U_P^{\prime}\left(x-U_A^{-1}(y)\right)}{U_A^{\prime}\left(U_A^{-1}(y)\right)}$, which is a open set and denoted as $\mathcal{L}$. 
\end{remark}




\subsection{ Equivalence between $u(x, y, t)$ and $w(x, y, t)$} \label{sec equi uw}
Since $(x^C(s), y^C(s))$ in \eqref{dyn_x_c} and \eqref{dyn_y_c} always satisfy \eqref{auxilliary}, we see that intuitively $w(x, y, t)$ should be larger than the principal's value function $u(x, y, t)$. However, actually they are the same, as proved in the Theorem \ref{thm equi}. 

\cite{cvitanic2018dynamic} also prove a similar result in the language of stochastic processes. In contrast, our proof is mainly based on PDE.  

\begin{theorem}\label{thm equi}
%\qsj{Suppose $\{\lambda^C(s)\}_{t\leq s \leq T} \in \mathcal{A}_{x, y, t}$ for any $x\in \mathbb{R}$,  }
Suppose $w(x, y, t) \in C^{3, 2} (\mathbb{R}\times\mathbb{R} \times [0, T])$, $\{\lambda^*(s)\}_{t\leq s \leq T} \in \mathcal{A}(x, y, t)$ and $L_y(x, y, t)<0< L_x(x, y, t)$, $\forall (x, y) \in \mathbb{R}^2, \ t \in [0, T]$, then $u(x, y, t) = w(x, y, t)$.
\end{theorem}
In this theorem, we require $L_y(x, y, t)<0<L_x(x, y, t)$ to guarantee the transformation  \eqref{operator_w}. %Intuitively, this monotonicity in $x$ and $y$ is consistent to Remark \ref{rmk 2d sur} that different surfaces a disjoint. 

%The optimal contract will be determined by the following proposition.
We then determine the optimal contract. Given $x_t = x, y_t = y$, we can define $l = L(x, y, t)$, therefore, from Proposition \ref{prop L}, we have
\begin{align}
l = L\left(x^*(T), y^*(T), T\right) =  U_P\left(x^*(T)-U_A^{-1}(y^*(T))\right)-c U_P^{\prime}\left(x^*(T)-U_A^{-1}(y^*(T))\right) (U_A^{-1})^{\prime}(y^*(T)),
\end{align}
By noticing the relation between $x^*(T), y^*(T)$ and $x^C(T), y^C(T)$, we expect $$x^*(T) = x^{C^*}(T), y^*(T)=y^{C^*}(T) $$
for the optimal contract $C^*$, and thus $U_A^{-1}(y^*(T)) = U_A^{-1}(y^{C^*}(T)) = C^*(x^{C^*}(T)) =C^*(x^*(T)). $
Thus, for any constant $l$, the optimal contract $C^*(x; l)$ satisfies
\begin{align}
l = & U_P\big(x-C^*(x)\big)-c U_P^{\prime}\big(x-C^*(x)\big) (U_A^{-1})^{\prime}\big( U_A(C^*(x))\big)\\
= &U_P\big(x-C^*(x)\big)-c \frac{U_P^{\prime}\big(x-C^*(x)\big)}{U_A^{\prime} ( C^*(x) )}. \label{equ C*0}
\end{align}

