\section{Proof of Proposition \ref{prop L}}
\begin{proof}
% Proof can be derived by substituting $\sigma$ with $\sigma(x)$ in the proof of Proposition 5.4 from Cvitanic (2017). \qsj{(Did they write the proof for general $\sigma$?) }
From \eqref{equ defi L}, we have
\begin{align*}
    d L(x^*(s), y^*(s), s) = d w(x^*(s), y^*(s), s) + c d w_y(x^*(s), y^*(s), s), \quad \forall s \in [t,T]
\end{align*}

On the one hand, by applying Ito's formula under the optimal control $\lambda^*$, we obtain
    \begin{align*}
    dw(x^*(s), y^*(s), s) &= w_{s} ds + w_{x} dx^*(s) + w_{y} dy^*(s) + \frac{1}{2} w_{xx} \langle dx^*(s)\rangle^2  + \frac{1}{2} w_{yy} \langle dy^*(s)\rangle^2 + w_{xy}\langle dx^*(s), dy^*(s)\rangle\\
    &= w_{s} ds + w_{x} \big(\sigma(x^*(s)) \lambda^* d s+\sigma(x^*(s)) d B_s\big) + w_{y} \big(\frac{c}{2} (\lambda^*)^2 ds+c \lambda^* dB_s\big)\\
    & \quad + \frac{\sigma(x^*(s))^2}{2} w_{xx} ds + \frac{(c \lambda^*)^2}{2} w_{yy} ds + w_{xy} \sigma\big(x^*(s)\big) c \lambda^* ds\\
    &= \bigg( w_{s} + \frac{\sigma(x^*(s))^2}{2} w_{xx} + \frac{(c \lambda^*)^2}{2} w_{yy} + \sigma(x^*(s)) \lambda^* w_{x} + \frac{c}{2} (\lambda^*)^2 w_{y} + \sigma(x^*(s)) c \lambda^* w_{xy}\bigg) ds\\
    &\quad + \big( \sigma(x^*(s)) w_{x} + c \lambda^* w_{y}\big)dB_{s}\\
    &= \big( \sigma(x^*(s)) w_{x} + c \lambda^* w_{y}\big)dB_{s},
    \end{align*}
where the last equality follows from PDE \eqref{equ w visco}.

On the other hand, we have
 \begin{align*}
    dw_y(x^*(s), y^*(s), s) &= w_{ys} ds + w_{yx} dx^*(s) + w_{yy} dy^*(s) + \frac{1}{2} w_{yxx} \langle dx^*(s)\rangle^2 + \frac{1}{2} w_{yyy} \langle dy^*(s)\rangle^2 + w_{xyy}\langle dx^*(s), dy^*(s)\rangle\\
    &= w_{ys} ds + w_{yx} \big(\sigma(x^*(s)) \lambda^* d s+\sigma(x^*(s)) d B_s\big) + w_{yy} \big(\frac{c}{2} (\lambda^*)^2 ds+c \lambda^* dB_s\big)\\
    & \quad + \frac{\sigma(x^*(s))^2}{2} w_{yxx} ds + \frac{(c \lambda^*)^2}{2} w_{yyy} ds + w_{xyy} \sigma\big(x^*(s)\big) c \lambda^* ds\\
    &= \bigg( w_{ys} + \frac{\sigma(x^*(s))^2}{2} w_{yxx} + \frac{(c \lambda^*)^2}{2} w_{yyy} + \sigma(x^*(s)) \lambda^* w_{yx} + \frac{c}{2} (\lambda^*)^2 w_{yy} + \sigma(x^*(s)) c \lambda^* w_{xyy}\bigg) ds\\
    &\quad + \big( \sigma(x^*(s)) w_{yx} + c \lambda^* w_{yy}\big)dB_{s}\\
    &= \big( \sigma(x^*(s)) w_{yx} + c \lambda^* w_{yy}\big)dB_{s},
    \end{align*}
where the last equality follows from taking $\frac{\partial}{\partial y}$ on both side of \eqref{equ w visco}.

Finally, by \eqref{def alpha_star} we have
\begin{align*}
    d L(x^*(s), y^*(s), s) &= d w(x^*(s), y^*(s), s) + c d w_y(x^*(s), y^*(s), s) \\
    &= \big(\sigma(x^*(s)) w_{x} + c \lambda^* w_{y} + c\sigma(x^*(s)) w_{yx} + c^2 \lambda^* w_{yy}\big)dB_{s}\\
    &= 0.
\end{align*}
Therefore, $$L(x^*(s), y^*(s), s) = L(x, y, t), \quad \forall s \in [t, T].$$
The terminal condition follows immediately, as we observe that $w(x, y, T) = U_P \big( x - U_A^{-1}(y) \big)$.
\end{proof}
