\subsection{Proof of Theorem 1: ReLU State Vector Representation}
\label{proof_theorem_1}
We define the $n$-dimensional state vector $s_t$ such that
\[
(s_t)_i = 
\begin{cases}
1, & \text{if } q_i \text{ is active at time } t, \\
0, & \text{otherwise}.
\end{cases}
\]
Given a fixed input symbol $x_t \in \Sigma$, let $T^{x_t} \in \{0,1\}^{n \times n}$ be the transition matrix where
\[
T^{x_t}_{ij} = 
\begin{cases}
1, & \text{if } q_j \in \delta(q_i, x_t), \\
0, & \text{otherwise}.
\end{cases}
\]

The matrix-vector product $T^{x_t} s_t$ produces a vector $v \in \mathbf{Z}_{\ge 0}^n$ where
\[
v_j = \sum_{i=1}^n T^{x_t}_{ji} (s_t)_i.
\]
This entry is non-zero if and only if there exists at least one state $q_i$ that was active at time $t$ such that $q_j \in \delta(q_i, x_t)$.

To recover the correct binary activation pattern for $s_{t+1}$, we apply the ReLU activation:
\[
(s_{t+1})_j = \mathrm{ReLU}(v_j) =
\begin{cases}
v_j, & \text{if } v_j > 0, \\
0, & \text{otherwise}.
\end{cases}
\]

Now, observe that since $v_j \in \mathbf{Z}_{\ge 0}$ and $s_t \in \{0,1\}^n$, $v_j > 0$ if and only if $q_j$ is reachable from some active $q_i$ via $x_t$, i.e., $q_j \in \delta(q_i, x_t)$ for some $i$ with $(s_t)_i = 1$. Therefore, $(s_{t+1})_j = v_j > 0$ if and only if $q_j$ is in the new active set of states.

Finally, we apply a binary thresholding if needed (e.g., $\mathbf{1}(v_j > 0)$), but this is optional since the magnitude of $v_j$ does not affect the semantics — only its positivity matters. Thus, ReLU suffices.

\subsection{Proof of Lemma 1: Parallel Path Tracking}
\label{proof_lemma_1}
Let $s_t \in \{0,1\}^{n}$ be the state vector at time $t$, where $(s_t)_i = 1$ if state $q_i$ is active. Let $T^{x_t} \in \{0,1\}^{n \times n}$ be the transition matrix for input symbol $x_t$ as defined in Theorem \hyperref[theorem_1]{1}. Then the matrix-vector product yields:
\[
v_j = \sum_{i=1}^n T^{x_t}_{ji} (s_t)_i.
\]
If any $i$ satisfies both $(s_t)_i = 1$ and $T^{x_t}_{ji} = 1$, then $v_j \geq 1$, and $\mathrm{ReLU}(v_j) = v_j > 0$. Otherwise, $v_j = 0$. Thus, $s_{t+1} = \mathrm{ReLU}(T^{x_t} s_t)$ encodes all $q_j$ such that there exists a valid transition from some active $q_i$ to $q_j$ under $x_t$.

Hence, all nondeterministic paths are captured in parallel by the activations of the next state vector.

\subsection{Proof of Theorem 2: Subset Construction via ReLU Composition}
\label{proof_theorem_2}
We proceed inductively. Let the initial state vector $s_0 \in \{0,1\}^n$ be a one-hot encoding of $q_0$ or the $\epsilon$-closure thereof. Let $T^{x_i}$ be the transition matrix for symbol $x_i$.

\textbf{Base Case ($t=1$):}
\[
s_1 = \mathrm{ReLU}(T^{x_1} s_0)
\]
correctly computes all states reachable by one transition.

\textbf{Inductive Step:}
Assume $s_{t-1}$ encodes the DFA subset corresponding to the set of NFA states reachable by $x_1, \dots, x_{t-1}$. Then
\[
s_t = \mathrm{ReLU}(T^{x_t} s_{t-1})
\]
computes the union of all $q_j \in \delta(q_i, x_t)$ for each active $q_i \in s_{t-1}$.

Because ReLU preserves positive activations and the transition matrices are deterministic, the vector $s_t$ will encode the correct set of NFA states reachable after $t$ steps. Thus, repeated composition of ReLU updates realizes subset construction deterministically.


\subsection{Proof of Lemma 2: ReLU Closure under \texorpdfstring{$\epsilon$}{epsilon}-Transitions}
\label{proof_lemma_2}
Let $s^{(0)} \in \{0,1\}^n$ be the binary vector representing the initially active states at time $t$. Define
\[
s^{(k+1)} = \mathrm{ReLU}(T^{\epsilon} s^{(k)}), \quad k \ge 0.
\]

\textbf{Step 1 (Monotonicity):}  
Each application of $T^\epsilon$ followed by ReLU adds new states to the active set (or leaves it unchanged), since
\[
(s^{(k+1)})_j = \max\left(0, \sum_{i=1}^n T^\epsilon_{ji} (s^{(k)})_i \right) \ge (s^{(k)})_j.
\]
Thus, the sequence $\{s^{(k)}\}$ is monotonic: $s^{(k)} \le s^{(k+1)}$ (element-wise).

\textbf{Step 2 (Finite Convergence):}  
Since each state is either 0 or 1 in the binary vector and there are $n$ total states, the monotonic sequence $\{s^{(k)}\}$ can change at most $n$ times before reaching a fixed point.

\textbf{Step 3 (Correctness):}  
At convergence, $s^{(K)}$ includes all states reachable from the original set via a chain of $\epsilon$-transitions. Any such state is reachable via a finite path of length at most $n$, and will be activated through repeated matrix application. Conversely, no unreachable states will be activated because $T^\epsilon$ is binary and has no negative entries or spurious transitions.

% \textbf{Conclusion:}  
Therefore, $s^{(K)}$ represents the $\epsilon$-closure of $s_t$, and $K \le n$.


\subsection{Proof of Theorem 3: ReLU Networks Simulate \texorpdfstring{$\epsilon$}{epsilon}-NFA Acceptors}
\label{proof_theorem_3}
We define a 3-layer ReLU network composed of:

\textbf{Layer 1 (Initialization and $\epsilon$-Closure):}  
Let $s_0 \in \{0,1\}^n$ be the one-hot vector for $q_0$, the start state. Compute the initial state vector $s_0^\epsilon$ by iterating:
\[
s_0^\epsilon = \epsilon\text{-closure}(s_0) = \mathrm{ReLU}\left(T^\epsilon \mathrm{ReLU}(\cdots \mathrm{ReLU}(T^\epsilon s_0) \cdots )\right),
\]
until convergence in at most $n$ steps, as shown in Lemma~\hyperref[lemma_2]{2}. This can be unrolled and embedded into the first ReLU layer with fixed weights and skip connections.

\textbf{Layer 2 (Per-Symbol Transitions and Closures):}  
For each $x_t \in x$, compute:
\[
s_{t}' = \mathrm{ReLU}(T^{x_t} s_{t-1}),
\quad
s_t = \epsilon\text{-closure}(s_{t}') = \mathrm{ReLU}\left(T^\epsilon \mathrm{ReLU}(\cdots \mathrm{ReLU}(T^\epsilon s_{t}') \cdots )\right),
\]
using again a finite unrolled series of ReLU layers. The second functional layer computes these recurrently over the input string.

\textbf{Layer 3 (Acceptance Check):}  
Let $f \in \{0,1\}^n$ be the binary indicator vector for the accepting states $F$. Define the final output as:
\[
y = \sigma(f^\top s_T),
\]
where $\sigma(z) = \mathbf{1}[z > 0]$ is a hard threshold (or a smooth approximation such as a sigmoid during training). This detects whether any accepting state is active at the end.

% \textbf{Conclusion:}  
All three layers are constructed via matrix-vector operations and ReLU activations. Each transformation is deterministic and mimics the transition and closure operations of $\mathcal{A}$. Thus, the ReLU network accepts the input iff $\mathcal{A}$ accepts it.


\subsection{Proof of Corollary 1: ReLU Acceptors are NFA-Complete}
\label{proof_corollary_1}
Let $\mathcal{A} = (Q, \Sigma \cup \{\epsilon\}, \delta, q_0, F)$ be an arbitrary NFA. By Theorem~\hyperref[theorem_3]{3}, we construct a 3-layer ReLU network with the following components:

\begin{itemize}
    \item Layer 1: Computes the $\epsilon$-closure of the start state $q_0$, resulting in the initial state vector $s_0^\epsilon$.
    \item Layer 2: For any input string $x = x_1 x_2 \dots x_T$, the network performs $T$ sequential transition updates followed by $\epsilon$-closures, using unrolled matrix multiplications and ReLU.
    \item Layer 3: Checks if any state in $F$ is active using an inner product with the final state vector $s_T$.
\end{itemize}

The full network requires:
- Width: $\mathcal{O}(n)$ neurons to encode all NFA states.
- Depth: $\mathcal{O}(T + 2n)$, accounting for input transitions and $\epsilon$-closures.
- Fixed weights and ReLU activations — no learned parameters are necessary for this constructive equivalence.

Because every regular language is defined by some NFA $\mathcal{A}$, and $\mathcal{A}$ can be encoded by such a ReLU network, the class of ReLU networks is NFA-complete with respect to language recognition.


\subsection{Proof of Lemma 3: Gradient Flow Preserves NFA Semantics}
\label{proof_lemma_3}
Let us denote the ReLU network $f_\theta$ as a composition of layers simulating the NFA's transitions. Each layer corresponds to a symbol in the input string and applies a transformation based on the transition matrix $T^{x_t}$ for symbol $x_t \in \Sigma$.

Assume that the initial network parameters $\theta_0$ are set such that $f_{\theta_0}$ exactly simulates $\mathcal{A}$, as established in Theorem~\hyperref[theorem_3]{3}. During training, the parameters are updated via gradient descent:

\[
\theta_{k+1} = \theta_k - \eta \nabla_\theta \mathcal{L}(\theta_k),
\]

where $\eta$ is the learning rate.

Suppose that during training, the updates to $\theta$ are constrained to preserve the sparsity pattern of the transition matrices $T^{x_t}$, meaning that the positions of non-zero entries remain fixed, and only their values are adjusted. This constraint ensures that the structural representation of the NFA's transitions is maintained.

Under these conditions, for any input string $x = x_1 x_2 \dots x_T$, the network's computation proceeds through the sequence of layers corresponding to each $x_t$, applying the ReLU-activated transition matrices. Since the structure of these matrices remains consistent with the NFA's transition function $\delta$, and the network is trained to match the NFA's acceptances on $\mathcal{D}$, the network's behavior aligns with that of $\mathcal{A}$ on $\mathcal{D}$.

Furthermore, because the structural constraints prevent the introduction of transitions not present in $\delta$, and the training data $\mathcal{D}$ encompasses representative examples from $L(\mathcal{A})$, the network generalizes this behavior to all inputs in $\Sigma^*$, preserving the NFA's semantics.


\subsection{Proof of Theorem 4: Learnability of NFA via Supervised ReLU Networks}
\label{proof_theorem_4}
Let $f_\theta$ be a ReLU network initialized with weights $\theta_0$ structured as follows:
- Each input symbol $x \in \Sigma$ corresponds to a transition matrix $T^x$ embedded into a sparse linear layer.
- The initial activation vector $s_0$ encodes the start state $q_0$.
- The final classification is computed as $\hat{y} = \sigma(f^\top s_T)$, where $f \in \{0,1\}^n$ is the indicator of accepting states.

Training proceeds via gradient descent:
\[
\theta_{k+1} = \theta_k - \eta \nabla_\theta \mathcal{L}(f_\theta(x^{(i)}), y^{(i)}),
\]
with binary cross-entropy loss. Assume:
1. The loss is minimized to zero on $\mathcal{D}$.
2. Weight updates maintain the zero-patterns of $\theta_0$ (structure-preserving).

Then, for each $x^{(i)}$, the activations $s_T$ must be aligned with the correct DFA subset constructed by $\mathcal{A}$, or else $\hat{y} \neq y^{(i)}$. Because the loss is minimized, this condition holds for all $(x^{(i)}, y^{(i)})$ in the training set.

Now, consider any unseen $x \in \Sigma^*$:
- Since $f_\theta$ retains the transition structure of $\mathcal{A}$ and weights have only been refined (not added arbitrarily), it generalizes to $x$ exactly as $\mathcal{A}$ would.

Thus, $f_\theta$ simulates the NFA $\mathcal{A}$ exactly after training.


\subsection{Proof of Theorem 5: Equivalence of ReLU Networks and NFA Recognizers}
\label{proof_theorem_5}
\textbf{(Forward Direction)}  
Given a regular language $\mathcal{L}$, let $\mathcal{A} = (Q, \Sigma, \delta, q_0, F)$ be an NFA recognizing $\mathcal{L}$ with $n = |Q|$ states. By Theorem~\hyperref[theorem_3]{3}, we construct a feedforward ReLU network $f_\theta$ that:
\begin{itemize}[itemsep=0pt, topsep=0pt]
    \item Encodes state activations with $n$ ReLU neurons,
    \item Applies $\epsilon$-closures via repeated matrix multiplication and ReLU (Lemma~\hyperref[lemma_2]{2}),
    \item Computes transitions via ReLU-layered matrix products (Theorem~\hyperref[theorem_2]{2}),
    \item Outputs $1$ if any accepting state is active.
\end{itemize}

The network simulates the behavior of $\mathcal{A}$ exactly on any $x \in \Sigma^*$, so $f_\theta(x) = 1$ if and only if $x \in \mathcal{L}$.

\textbf{(Reverse Direction)}  
Let $f_\theta$ be a ReLU network constructed with:
\begin{itemize}[itemsep=0pt, topsep=0pt]
    \item An input-dependent sequence of symbol-conditioned transition matrices $\{T^{x_i}\}$,
    \item ReLU-activated state vectors $s_t = \mathrm{ReLU}(T^{x_t} s_{t-1})$,
    \item An acceptance condition based on overlap with an indicator vector $f$ for accepting states.
\end{itemize}

Construct an NFA $\mathcal{A}' = (Q, \Sigma, \delta', q_0, F')$ where:
\begin{itemize}[itemsep=0pt, topsep=0pt]
    \item$Q = \{q_1, \dots, q_n\}$ corresponds to neurons in $f_\theta$,
    \item $\delta'(q_i, x) = \{q_j : T^{x}_{ji} > 0\}$,
    \item $F'$ contains all $q_j$ for which $f_j = 1$,
    \item $q_0$ is the initial state corresponding to $s_0$.
\end{itemize}

Since $f_\theta$ deterministically applies these transitions and accepts iff an output neuron indexed by $F'$ is activated, the language recognized by $f_\theta$ matches that of $\mathcal{A}'$.

\textbf{Conclusion:}  
This establishes a bijective, symbolic correspondence between finite-state NFA recognizers and ReLU networks simulating them via feedforward computation.

