\section{Additional details regarding computational experiments}
\label{sec:supp_details_computational_exp}

\subsection{Pseudocode for the SnS algorithm}

Here we present the pseudo-code (Algorithm \ref{alg:SnS_algorithm}) for the \texttt{SnS} algorithm. We used library implementations for the \texttt{CMA-ES} gradient-free optimizer \cite{hansen2019pycma} and the Pareto front computation \cite{DEAP_JMLR2012}. Importantly, we introduce the following \texttt{should\_stop} criteria for our experiments.

Optimizations were terminated by either reaching a maximum iteration limit ($500$) or satisfying an early stopping rule derived from the target unit's response statistics to a large dataset of natural images  (i.e., the full ImageNet train set, $n \approx
 1.2$ million). In particular, given the vastness of the dataset, we assumed that the activation elicited by the most effective image in the natural dataset ($a^\ell_{\mathrm{max\_nat}}$) represented a conservative threshold for an image to be considered \emph{invariant}. On the other hand, the activation from the least effective image ($a^\ell_{\mathrm{min\_nat}}$) represents a non-response level, functioning as a threshold for an image to be considered \emph{adversarial}. 
Therefore, when searching for adversarial images, termination was reached when a large fraction (i.e., $\geq 90\%$) of the current population of images elicited activations at or below $a^\ell_{\mathrm{min\_nat}}$, thus leading to a non-responsive status. Conversely, when looking for invariant images after initialization from random noise, it was terminated when a large fraction (i.e., $\geq 90\%$) of the population of images yielded activations equal or above $a^\ell_{\mathrm{max\_nat}}$, thus reaching the desired high-activation regime. 

\begin{algorithm}[h]
\caption{SnS gradient-free optimization algorithm}\label{alg:SnS_algorithm}
\begin{algorithmic}
\Require $\phi$ \Comment{Target network}
\Require $\psi$ \Comment{Image generator}
\Require $T \ge 0$ \Comment{Maximum number of iterations}
\Require $\kappa, \ell \in \left\{0, 1, \dots, \mathtt{depth}(\phi)\right\}$
\Require $\bm{x}_\mathrm{ref} \in \mathbb{R}^{C \times H \times W}$ \Comment{Common choice is $\bm{x}_\mathrm{ref} = \bm{x}_\star$}
\State $t \gets 0$
\State $\mathbf{a}_\mathrm{ref}^{\kappa, \ell} \gets \Gamma \left( \bm{x}_\mathrm{ref}, \phi^{\kappa, \ell} \right)$
\State $\bm{\xi}_0 \gets \mathcal{N}\left(0, \sigma_{\text{init}}\right)$
\While{$t \le T$ and !\texttt{early\_stop}}
    \State $\bm{x}_t = \psi \left(\bm{\xi}_t\right)$ \Comment{Compute new candidate stimuli}
    \State $\mathbf{a}^{\kappa, \ell} = \Gamma \left( \bm{x}_t, \phi^{\kappa, \ell} \right)$ \Comment{Measure activations in target layers $\kappa, \ell$}
    \State$\mathcal{L}_\mathrm{stretch}^\kappa \gets - \parallel  \mathbf{a}^\kappa - \mathbf{a}_\mathrm{ref}^\kappa \parallel$
    \State $\mathcal{L}_\mathrm{squeeze}^\ell \gets + \parallel  \mathbf{a}^\ell - \mathbf{a}_\mathrm{ref}^\ell \parallel$
    \State $\mathcal{P} \gets \mathtt{compute\_pareto\_front} \left( \bm{\xi}_t, \mathcal{L}_\mathrm{stretch}^\kappa, \mathcal{L}_\mathrm{squeeze}^\ell \right)$
    \State $\bm{\xi}_{t+1} \gets \mathtt{evolve} \left( \mathcal{P}, \bm{\xi}_t \right)$ \Comment{Evolution strategy CMA-ES optimization}
    \State $t \gets t + 1$
    \State $\mathtt{early\_stop} \gets \mathtt{should\_stop} \left( \mathbf{a}^\kappa, \mathbf{a}^\ell \right)$
\EndWhile
\end{algorithmic}
\end{algorithm}

\subsection{Experimental Hyperparameters}

The generative model $\psi$ is instantiated as a pretrained deep neural network variant, specifically the \texttt{fc7} configuration from \cite{dosovitskiy2016generating}.

 The CMA-ES optimizer is configured with the following hyperparameters:

\begin{itemize}
  \item \textbf{Initial Step Size} ($\sigma_0$): 1.0
  \item \textbf{Population Size}: 50
\end{itemize}

The initial step size $\sigma_0$ determines the covariance of the sampling distribution at the onset of optimization, effectively controlling the exploration radius in the latent space.

The population size specifies the number of candidate solutions (i.e. codes) evaluated per iteration. 

Initial codes were randomly sampled from a Gaussian distribution $\mathcal{N}(0, \sigma_{\text{init}})$. 
The initial standard deviation, $\sigma_{\text{init}}$, was set to $\sqrt{0.01 \times \mathbb{E}[|\bm{\xi}_{\text{ref}}|]}$, where $\mathbb{E}[|\bm{\xi}_{\text{ref}}|]$ is the mean absolute value of the reference code. 
For invariance experiments benchmarked against natural images, where direct reference codes were unavailable, initial codes were drawn from a standard normal distribution ($\mathcal{N}(0, 1)$).

\subsection{Optmization Convergence}
\begin{figure}[tb]
    \centering
    \includegraphics[width=\textwidth]{Images_supp/Figure_S1.png}
    \caption{\textbf{SnS images fall into functionally relevant activation regimes}.
    Distributions of readout target unit activations (normalized by peak natural stimulus response) for SnS-generated images: invariant (stretched at pixel, mid-, high-levels) and adversarial (pixel-space). Each distribution pulls together all optimizations performed in that specific condition (n = 77 target neurons x 10 random seeds = 770 experiments per condition). Comparison with natural image activations (same/different category) confirms that SnS invariant images elicit strong target responses, while adversarial examples achieve significant suppression.}
    \label{fig:supp_convergence}
\end{figure}
Although some optimizations terminated at maximum iterations (adversarial: 97.92\% (robust), 93.12\% (standard); invariant: 63.38\%, 35.71\%, 21.30\% (robust: \texttt{low\_level, mid\_level, high\_level}); 86.75\%, 32.60\%, 5.84\% (standard: \texttt{low\_level, mid\_level, high\_level}))  , final populations consistently reached functionally relevant activation regimes. Most invariant images achieved activations within the top 0.1\% of natural image responses, being comparable or more extreme than the readout activation of images of the same category encoded by the readout target unit (Fig.~\ref{fig:supp_convergence}).
Adversarial examples drove activations to the lowest $1^{st}$ percentile of the natural images, thus significantly suppressing target unit activation w.r.t. average activation with a natural image.
