    \fmfright{o1}
    \fmf{phantom}{i1,v1}
    \fmf{phantom}{v4,o1}
    \fmf{plain,left,tension=0.3}{v1,v2,v1}
    \fmf{dashes, tension=0.3}{v2,v3}
    \fmf{plain,left,tension=0.3}{v3,v4,v3}
\end{fmfgraph*}}
\end{fmffile}
= 0
\end{equation}
\begin{equation}
