	& + 
	32 T^2 \bar{\lambda}^4\big) \bigg) \bigg) + e^{2i (X (\lambda + 2 \bar{\lambda}) + 2 T (\lambda^2 + 2 \bar{\lambda}^2))} \bigg( 
	3 + 4 X^4 (\lambda - \bar{\lambda})^4 + 1024 T^4 \lambda^2 (\lambda - \bar{\lambda})^4 \bar{\lambda}^2  \nonumber \\
