\caption{Three types of trajectories in the homogeneous magnetic field in $\R^3$. The gray lines represent the magnetic field. } \label{helikoid}
}
\end{figure}


We have not found the system \eqref{Rn} to be studied before  in the literature.
A lack of interest in this system seems curious, because it is quite natural and  simple.  Without loss of generality,
by taking a suitable orthonormal basis $[\mathbf e_1,\dots,\mathbf e_n]$ of $\R^n$,  we can assume that
the magnetic form \eqref{polje} takes the form
\begin{equation}\label{polje*}
\mathbf F=s(\kappa_{12} d\gamma_1\wedge d\gamma_2+\kappa_{34} d\gamma_3\wedge d\gamma_4 +\dots +\kappa_{2[n/2]-1,2[n/2]}d\gamma_{2[n/2]-1}\wedge d\gamma_{2[n/2]}).
\end{equation}

 If $n$ is even, the system \eqref{Rn} decouples on $k=n/2$ magnetic systems
\begin{align}
\label{res1} &{\dot\gamma}_{2i-1}=\frac{1}{m}p_{2i-1},\qquad\qquad {\dot p}_{2i-1}=\frac{s}{m}\kappa_{2i-1,2i} p_{2i},\\
\label{res2} &{\dot\gamma}_{2i} =\frac{1}{m}p_{2i},\qquad\qquad\qquad  {\dot p}_{2i}=-\frac{s}{m}\kappa_{2i-1,2i} p_{2i-1}.
\end{align}
 They are Hamiltonian equations in $\R^4(\gamma_{2i-1},\gamma_{2i},p_{2i-1},p_{2i})$ with respect to the twisted symplectic forms
\[
\Omega_{2i-1,2i}+\mathbf F_{2i-1,2i}=dp_{2i-1}\wedge g\gamma_{2i-1}+ dp_{2i}\wedge d\gamma_{2i}+s\kappa_{2i-1,2i} d\gamma_{2i-1}\wedge d\gamma_{2i}
\]
and the Hamiltonians
\[
H_{2i-1,2i}=\frac{1}{2m}(p_{2i-1}^2+p_{2i}^2).
\]

If $n=2k+1$ is odd, along with the $k$ systems listed above, there is  an additional  system of one degree of freedom on $\R^2(\gamma_n,p_n)$ with the standard symplectic form and the Hamiltonian 
\[
H_n=\frac{1}{2m}p_n^2,
\]
which generates a uniform motion:
\[
\dot\gamma_n=\frac{1}{m}p_n,\qquad\qquad {\dot p}_n=0.
\]

The systems  \eqref{res1}, \eqref{res2} can be easily integrated in terms of linear and trigonometric functions. The projection of the trajectories to $\R^2(\gamma_{2i-1},\gamma_{2i})$-planes are straight lines for $\kappa_{2i-1,2i}= 0$, or circles
\begin{align*}
& \gamma_{2i-1}(t)=r_{2i-1,2i}\cos(\omega_{2i-1,2i}t+\varphi_{2i-1,2i})+c_{2i-1}, \\
&\gamma_{2i}(t)=r_{2i-1,2i}\cos(\omega_{2i-1,2i}t+\varphi_{2i-1,2i})+c_{2i}, \qquad \omega_{2i-1,2i}=-\frac{s\kappa_{2i-1,2i}}{m}
\end{align*}
of the Larmor radii
\[
r_{2i-1,2i}=\frac{\sqrt{p^2_{2i-1}+p^2_{2i}}}{\vert s\kappa_{2i-1,2i}\vert}=\frac{m\sqrt{{\dot\gamma}^2_{2i-1}+{\dot\gamma}^2_{2i}}}{\vert s\kappa_{2i-1,2i}\vert},
\]
for $\kappa_{2i-1,2i}\ne 0$. Here $c_{2i-1}, c_{2i}, \varphi_{2i-1,2i}$ are the integration constants that depend on  the initial conditions. The period of rotation in the $\R^2(\gamma_{2i-1},\gamma_{2i})$-plane does not depend on the velocity:
\[
T_{2i-1,2i}=\frac{2\pi}{\vert \omega_{2i-1,2i}\vert}=\frac{2\pi m}{\vert s\kappa_{2i-1,2i}\vert}.
\]

In order to describe the first integrals of motion, we pass to the Lagrangian description. According to \eqref{AG}, we can take a Lagrangian with a term linear in velocities
\[
L_1^\Gamma(\gamma,\dot\gamma)=\frac{m}{2}\langle \dot\gamma,\dot\gamma\rangle+\frac{s}{2}\sum_{i=1}^{[n/2]} \kappa_{2i-1,2i}\big( (\gamma_{2i-1}+\Gamma_{2i-1})\dot\gamma_{2i}-(\gamma_{2i}+\Gamma_{2i})\dot\gamma_{2i-1}\big).
\]

The Lagrangian $L_1^\Gamma$ has the following Noether symmetries
\begin{equation}\label{simetrije}
\xi_i^{\Gamma_{2i-1},\Gamma_{2i}}=(\gamma_{2i-1}+\Gamma_{2i-1})\frac{\partial}{\partial \gamma_{2i}}-(\gamma_{2i}+\Gamma_{2i})\frac{\partial}{\partial \gamma_{2i-1}},
\end{equation}
modulo the gauge terms
\[
-\frac{d}{dt}s \frac{\kappa_{2i-1,2i}}{2}\big( (\gamma_{2i-1}+\Gamma_{2i-1})^2+(\gamma_{2i}+\Gamma_{2i})^2\big),\qquad i=1,\dots,[n/2].
\]

The corresponding gauge Noether first integrals of motion are  (e.g., see \cite{CS1981}):
\[
\langle \frac{\partial L_1^\Gamma}{\partial \dot\gamma},\xi_i^{\Gamma_{2i-1},\Gamma_{2i}}\rangle+s \frac{\kappa_{2i-1,2i}}{2}\big( (\gamma_{2i-1}+\Gamma_{2i-1})^2+(\gamma_{2i}+\Gamma_{2i})^2\big), \qquad i=1,\dots,[n/2].
\]
In the Hamiltonian description, they take the form
\[
\Phi_{2i-1,2i}^{\Gamma_{2i-1},\Gamma_{2i}}=(\gamma_{2i-1}+\Gamma_{2i-1})p_{2i}-(\gamma_{2i}+\Gamma_{2i}) p_{2i-1}+ s \frac{\kappa_{2i-1,2i}}{2}\big( (\gamma_{2i-1}+\Gamma_{2i-1})^2+(\gamma_{2i}+\Gamma_{2i})^2\big).
\]

Among the first integrals of motion $H_{2i-1,2i}, \Phi_{2i-1,2i}^{\Gamma_{2i-1},\Gamma_{2i}}$, there are three independent ones on
\[
(\R^4(\gamma_{2i-1},\gamma_{2i},p_{2i-1},p_{2i}),\Omega_{2i-1,2i}+\mathbf F_{2i-1,2i}).
\]

The systems \eqref{res1}, \eqref{res2}  are integrable in  non-commutative sense (see \cite{N, MF}). If $\kappa_{2i-1,2i}=0$, the trajectories
in $\R^4(\gamma_{2i-1},\gamma_{2i},p_{2i-1},p_{2i})$ are straight lines. Otherwise,  all the trajectories, outside $p_{2i-1}=p_{2i}=0$, are periodic with the period $T_{2i-1,2i}$. These systems are thus \emph{super-integrable}. As a result we have the following statement:

\begin{thm}\label{ocigledna}
For every $n\in \mathbb N$, the magnetic flows \eqref{Rn} are integrable in the  noncommutative sense.
Let $\kappa_{2i-1,2i}\ne 0$, $i=1,\dots,[n/2]$.
For even $n$, generic motions are quasi-periodic over $n/2$-dimensional isotropic tori $\mathbb T^{n/2}$, while for odd $n$, generic motions are quasi-periodic over isotropic cylinders $\mathbb T^{[n/2]}\times\R$.
\end{thm}

\begin{rem} For even $n$,
in the case when all $\vert\kappa_{2i-1,2i}\vert\ne 0$ are proportional:
\begin{equation*}
m_1\vert\kappa_{1,2}\vert^{-1}=\dots=m_{n/2}\vert\kappa_{n-1,n}\vert^{-1}, \qquad m_i\in\mathbb N,
\end{equation*}
such that the common divisor of $m_i$ is 1,
all the trajectories are closed with the same period
\[
T=\frac{m_1{2\pi m}}{{\vert s\kappa_{1,2}\vert}}=\dots=\frac{m_{n/2}{2\pi m}}{{\vert s\kappa_{n-1,n}\vert}}.
\]
\end{rem}

\section{Restrictions to  unit spheres}

In this section we consider  motion of a material point of mass $m$ and charge $-s$ restricted to the unit sphere $S^{n-1}\subset\R^n$ placed in a homogeneous magnetic field \eqref{polje}.
We work in redundant coordinates and consider the phase space $T^*S^{n-1}$ as a submanifold of $\mathbb{R}^{2n}(\gamma,p)$ given by the equations
\[
\phi_1=\langle\gamma,\gamma\rangle=1, \qquad \phi_2=\langle p,\gamma\rangle=0,
\]
and endowed with the twisted symplectic form $\omega+\mathbf f$, $\omega=\Omega\vert_{T^*S^{n-1}}$, $\mathbf f=\mathbf F\vert_{T^*S^{n-1}}$.
It is convenient to use the Dirac magnetic Poisson brackets on
\[
\R^{2n}_*=\{(\gamma,p)\in \mathbb{R}^{2n}\, \vert\, \phi_1\ne 0\}
\]
defined by (see e.g. \cite{AKN}):
\begin{equation}\label{eq:Dirac}
\{F, G\}_d =\{F, G\}^\kappa -\frac{\{F,\phi_1 \}^\kappa\{G,\phi_2\}^\kappa- \{F,\phi_2\}^\kappa
\{G,\phi_1\}^\kappa }{ \{\phi_1, \phi_2 \}^\kappa },
\end{equation}
where $\{\cdot, \cdot\}^\kappa$ are
the magnetic Poisson brackets on $\mathbb{R}^{2n}(\gamma,p)$ with respect to the twisted symplectic form $\Omega+\mathbf F$:
\[
\{F,G\}^\kappa=\sum_{i}\big(\frac{\partial
F}{\partial\gamma_i} \frac{\partial G}{\partial
p_i}-\frac{\partial F}{\partial p_i}\frac{\partial
G}{\partial\gamma_i}\big)+s\sum_{i,j} \kappa_{ij}\frac{\partial
F}{\partial p_i} \frac{\partial G}{\partial p_j}.
\]

The constraint functions  $\phi_1$ and $\phi_2$ are Casimir functions of the Dirac brackets \eqref{eq:Dirac}. The symplectic leaf
$\phi_1=1$, $\phi_2=0$ within $(\mathbb{R}^{2n}_*(\gamma,p), \{\cdot,\cdot\}_d)$ coincides with $(T^*S^{n-1},\omega+\mathbf f)$.

Let us consider the Hamiltonian flow on the Poisson manifold $(\mathbb{R}^{2n}_*(\gamma,p), \{\cdot,\cdot\}_d)$ defined by the Hamiltonian \eqref{HAM}:
\begin{align*}
\dot\gamma_i=& \{\gamma_i,H\}_d= \frac{1}{m} p_i-\frac{1}{m}\frac{\langle p,\gamma\rangle}{\langle \gamma,\gamma\rangle} \gamma_i,\\
\dot p_i   =&  \{p_i,H\}_d=\frac{s}{m}\langle \kappa p,\mathbf e_i\rangle+
\frac{{s}\langle p,\kappa\gamma \rangle-\langle p,p\rangle}{m\langle \gamma,\gamma\rangle }\gamma_i+\frac{1}{m}\frac{\langle p,\gamma\rangle}{\langle \gamma,\gamma\rangle} p_i -\frac{s}{m}\frac{\langle p,\gamma\rangle}{\langle \gamma,\gamma\rangle}\langle \kappa\gamma,\mathbf e_i\rangle.
\end{align*}

On the cotangent bundle $T^*S^{n-1}\subset \R^{2n}_*$ the equations of motion simplify to
\begin{equation}\label{magGF}
\dot\gamma= \frac{1}{m} p,\qquad
\dot p  =\frac{s}{m}\kappa p+\mu\gamma, \qquad \mu=\frac{1}{m}\big({s}\langle p,\kappa\gamma \rangle-\langle p,p\rangle\big).
\end{equation}
%and represent the equations of a motion of material point on a unit sphere placed in the homogeneous magnetic field.
The function $\mu$ is the Lagrange multiplier and $\mu \gamma$ is the reaction force of the holonomic constraint $\phi_1=1$.

From now on, we consider a basis $[\mathbf e_1,\dots,\mathbf e_n]$ of $\R^n$ in which the magnetic form $\mathbf F$ takes the form \eqref{polje*}.
Thus, the system \eqref{magGF} becomes
\begin{align}
\label{eq1} &{\dot\gamma}_{2i-1}=\frac{1}{m}p_{2i-1},\qquad {\dot p}_{2i-1}=\frac{s}{m}\kappa_{2i-1,2i} p_{2i}+\mu\gamma_{2i-1},\\
\label{eq2} &{\dot\gamma}_{2i} =\frac{1}{m}p_{2i},\qquad\qquad  {\dot p}_{2i}=-\frac{s}{m}\kappa_{2i-1,2i} p_{2i-1}+\mu\gamma_{2i}, \qquad i=1,\dots,[n/2],
\end{align}
for $n$ even,
and, for $n$  odd, there is an additional equation:
\begin{equation}\label{eq3}
\dot\gamma_n=\frac{1}{m}p_n,\qquad\qquad {\dot p}_n=\mu\gamma_n.
\end{equation}

We can always perform a change of the basis with the permutations $\mathbf e_{2i-1} \longleftrightarrow \mathbf e_{2i}$ such that all parameters
$\kappa_{2i-1,2i}$ have the same sign, say
\begin{equation}\label{pozitivni}
\kappa_{2i-1,2i}\ge 0, \qquad i=1,\dots,[n/2].
\end{equation}
From now, on we assume that the inequalities \eqref{pozitivni} hold.

Note that the gauge Noether symmetries \eqref{simetrije} are tangent to the sphere $S^{n-1}$ for $\Gamma=0$,
leading to the following statement.

\begin{lem}\label{lema1}
The functions
\[
\Phi_{2i-1,2i}=\Phi_{2i-1,2i}^{0,0}=\gamma_{2i-1}p_{2i}-\gamma_{2i}p_{2i-1}+ s \frac{\kappa_{2i-1,2i}}{2}\big( \gamma_{2i-1}^2+\gamma_{2i}^2\big).
\]
are first integrals of motion of the magnetic flows \eqref{eq1} and \eqref{eq2} for even $n$ and   \eqref{eq1},  \eqref{eq2}, and   \eqref{eq3} for odd $n$. The first integrals of motion
Poisson commute: %with respect to the Dirac magnetic brackets \eqref{eq:Dirac}:
\[
\{\Phi_{2i-1,2i},\Phi_{2j-1,2j}\}_d=0, \qquad i,j=1,\dots,[n/2]
\]
on the Poisson manifold $(\mathbb{R}^{2n}_*(\gamma,p), \{\cdot,\cdot\}_d)$.
\end{lem}


We thus get the following theorem (see \cite{DGJ2023}):

\begin{thm}\label{stara}
 Assume $\kappa_{12}\ne 0$. The magnetic  flows \eqref{magGF} are completely integrable on $S^2$ and $S^3$, corresponding to $n=3$ and $n=4$ respectively.
\end{thm}

\begin{rem}
Although the systems  \eqref{magGF} are quite natural and for $n=3$  well-known (see e.g.  \cite{S2002}), until recently a general form of the system \eqref{magGF} was not studied. In \cite{DGJ2023}, we derived equations \eqref{magGF} as the reduced equation of a gyroscopic nonholonomic Chaplygin system of a ball rolling over a sphere. The considered nonholonomic problem is a generalization of the Demchenko integrable system where the inertia operator of the system ball + gyroscope is proportional to the identity operator (see \cite{DGJ2020}). In \cite{DGJ2023}, we also
performed explicit integrations of the equations of motion \eqref{magGF} of the systems on $S^2$ and $S^3$, corresponding to $n=3$ and $n=4$ respectively, in elliptic functions. To aline the notation from this paper
with  \cite{DGJ2023}, one should set
\[
m={\tau}/{\varepsilon^2}, \qquad  s=1/{\varepsilon^2} \qquad   (s/m=1/\tau).
\]
\end{rem}

\begin{rem}
For even $n$, the one-form
\[
\mathbf a=\frac{s}{2}\sum_{i=1}^{n/2} \kappa_{2i-1,2i}(\gamma_{2i-1}d\gamma_{2i}-\gamma_{2i}d\gamma_{2i-1})\vert_{S^{n-1}}
\]
is a contact form on the sphere $S^{n-1}$ (see e.g. \cite{JJ2015}).
In the case when
\begin{equation}\label{jednakost}
\kappa_{12}=\kappa_{34}=\dots=\kappa_{n-1,n},
\end{equation}
the contact form $\mathbf a$ is proportional
to the \emph{standard contact form} on $S^{n-1}$. The magnetic geodesics on the standard contact sphere $S^{n-1}$ endowed with a metric deformed in the direction of the appropriate Reeb field were studied in \cite{DIMN2015}. For $n=4$, this system represents a magnetic flow on the Berger sphere \cite{IM2024}.
\end{rem}




In addition to the first integrals of motion $\Phi_{2i-1,2i}$, we construct  the following one.

\begin{lem}\label{lema2}
The function $J$ given by
\begin{align*}
J=& \frac{s^2}{m^2}\sum_{i=1}^{[n/2]}\kappa_{2i-1,2i}^2 (p_{2i-1}^2+p_{2i}^2)-\mu^2, \\
\mu=& \frac{s}{m}\sum_{i=1}^{[n/2]}\kappa_{2i-1,2i}(p_{2i-1}\gamma_{2i}-p_{2i}\gamma_{2i-1})-2H.
\end{align*}
is the first integral of motion of the magnetic flows  \eqref{eq1} and \eqref{eq2} for even $n$ and   \eqref{eq1},  \eqref{eq2}, and   \eqref{eq3} for odd $n$ on $T^*S^{n-1}$.
\end{lem}

\begin{proof}
We have $\dot H=0$ for $\phi_1=1$, $\phi_2=0$. Thus,
\begin{align*}
\dot J=& 2\frac{s^2}{m^2}\sum_{i=1}^{[n/2]}\kappa_{2i-1,2i}^2 \big(p_{2i-1}(\frac{s}{m}\kappa_{2i-1,2i} p_{2i}+\mu\gamma_{2i-1})
 +p_{2i}(-\frac{s}{m}\kappa_{2i-1,2i} p_{2i-1}+\mu\gamma_{2i})\big)\\
 &-2\mu\frac{s}{m}\sum_{i=1}^{[n/2]}\kappa_{2i-1,2i}\frac{d}{dt}\big(\gamma_{2i}p_{2i-1}-\gamma_{2i-1}p_{2i}\big)\\
 =&2\frac{s^2}{m^2}\sum_{i=1}^{[n/2]}\kappa_{2i-1,2i}^2 \big(\mu p_{2i-1}\gamma_{2i-1}+\mu p_{2i}\gamma_{2i})\big)+2\mu\frac{s}{m}\sum_{i=1}^{[n/2]}\kappa_{2i-1,2i}\frac{d}{dt}\big(\gamma_{2i-1}p_{2i}-\gamma_{2i}p_{2i-1}\big)
\end{align*}
On the other hand, by using the Noether first integrals $\Phi_{2i-1,2i}$, we get the identities
\[
\frac{d}{dt}\big(\gamma_{2i-1}p_{2i}-\gamma_{2i}p_{2i-1}\big)=- \frac{s\kappa_{{2i-1,2i}}}{m}\big( \gamma_{2i-1}p_{2i-1}+\gamma_{2i}p_{2i}\big), \qquad i=1,\dots,[n/2].
\]
Therefore, $\dot J=0$ for $\phi_1=1$, $\phi_2=0$.
\end{proof}

The proofs of the following two lemmas contain long calculations and we will omit them.

\begin{lem}\label{lema3}
The following commuting relations among the first integrals $J$, $ \Phi_{2i-1,2i}$, $ i=1,\dots,[n/2]$, take place:
\begin{align*}
\{J,\Phi_{2i-1,2i}\}_d=0, \qquad i=1,\dots,[n/2]
\end{align*}
on the Poisson manifold $(\mathbb{R}^{2n}_*(\gamma,p), \{\cdot,\cdot\}_d)$.
\end{lem}

%Let us consider the case when  parameters $\kappa_{2i-1,2i}$ are different \textbf{(da li je taj uslov potreban?)}. Then we have:

\begin{lem}\label{lema4}
The functions $H$, $J$, $\Phi_{2i-1,2i}$, $i=1,\dots,[n/2]$ are functionally independent on $T^*S^{n-1}$ for $n\ge 5$ for all odd $n$ and all $\kappa$ and if  $n$ is even and $\kappa$ does not satisfy
$\kappa_{12}=\kappa_{34}=\dots=\kappa_{n-1,n}$.
\end{lem}

Let us  comment on the case when $n$ is even and the identity \eqref{jednakost} is satisfied.
Then the Lagrange multiplier $\mu$ is a first integral of motion,
\[
\mu= \frac{s\kappa_{12}}{m}\sum_{i=1}^{n/2}(p_{2i-1}\gamma_{2i}-p_{2i}\gamma_{2i-1})-2H=
\frac{s^2}{2m}\kappa^2_{12}-\frac{s}{m}\kappa_{12}\sum_{i=1}^{n/2}\Phi_{2i-1,2i}-2H,
\]
and
\begin{align*}
J=2\frac{s^2}{m}\kappa_{1,2}^2 H-\mu^2.
\end{align*}

It is  convenient to rewrite
the equations of motion \eqref{eq1} and \eqref{eq2} in a complex notation. Let us set
\[
z_i=\gamma_{2i-1}+\sqrt{-1}\gamma_i, \qquad w_i=p_{2i-1}+\sqrt{-1} p_{2i}, \qquad i=1,\dots,[n/2].
\]
Then the equations \eqref{eq1} and \eqref{eq2} take the form:
\begin{align}
\label{com1} \dot z_i=\frac{1}{m} w_i, \qquad \dot w_i=-\sqrt{-1}\frac{s\kappa_{2i-1,2i}}{m} w_i+\mu z_i, \qquad i=1,\dots,[n/2].
\end{align}

Thus,  the $SO(2)^{[n/2]}$--symmetry of the equations \eqref{eq1} and \eqref{eq2}
can be naturally considered as  the $U(1)^{[n/2]}$--symmetry of the equations \eqref{com1}.
If some of the parameters $\kappa_{2i-1,2i}$ are equal, then  there exists an additional $U(2)$--symmetry of the system, leading to the following first integrals of motion:

\begin{lem}\label{lema5}
If $\kappa_{2i-1,2i}=\kappa_{2j-1,2j}$, $i<j$, then the following functions
\begin{align*}
\Psi_{2i-1, 2i; 2j-1,2j}^1=&(\gamma_{2i}p_{2j-1}-\gamma_{2j-1}p_{2i})-(\gamma_{2i-1}p_{2j}-\gamma_{2j}p_{2i-1})\\
&-s\kappa_{2i-1,2i}(\gamma_{2i-1}\gamma_{2j-1}+\gamma_{2i}\gamma_{2j})\\
\Psi_{2i-1, 2i; 2j-1,2j}^2=&(\gamma_{2i-1}p_{2j-1}-\gamma_{2j-1}p_{2i-1})+(\gamma_{2i}p_{2j}-\gamma_{2j}p_{2i})\\
&-s\kappa_{2i-1,2i}(\gamma_{2i-1}\gamma_{2j}-\gamma_{2i}\gamma_{2j-1})
\end{align*}
are the first integrals of motion of the magnetic geodesic flow on $T^*S^{n-1}$. Moreover, the polynomials
\[
\Phi_{2i-1,2i},\, \Phi_{2j-1,2j},\, \Psi_{2i-1, 2i; 2j-1,2j}^1, \, \Psi_{2i-1, 2i; 2j-1,2j}^2
\]
generate the following four-dimensional Lie algebra
\begin{align*}
&\{\Phi_{2i-1,2i},\Phi_{2j-1,2j}\}_d=0,\\
&\{\Phi_{2i-1,2i}, \Psi_{2i-1, 2i; 2j-1,2j}^1\}_d=-\Psi_{2i-1, 2i; 2j-1,2j}^2,\\
&\{\Phi_{2j-1,2j}, \Psi_{2i-1, 2i; 2j-1,2j}^1\}_d=\Psi_{2i-1, 2i; 2j-1,2j}^2,\\
&\{\Phi_{2i-1,2i}, \Psi_{2i-1, 2i; 2j-1,2j}^2\}_d= \Psi_{2i-1, 2i; 2j-1,2j}^1,\\
&\{\Phi_{2j-1,2j}, \Psi_{2i-1, 2i; 2j-1,2j}^2\}_d=- \Psi_{2i-1, 2i; 2j-1,2j}^1,\\
&\{\Psi_{2i-1, 2i; 2j-1,2j}^1, \Psi_{2i-1, 2i; 2j-1,2j}^2\}_d=2\Phi_{2j-1,2j}-2\Phi_{2i-1,2i}.
\end{align*}
on the Poisson manifold $(\mathbb{R}^{2n}_*(\gamma,p), \{\cdot,\cdot\}_d)$. The Lie algebra is isomorphic to the reductive Lie algebra $\mathrm{so}(3)\oplus \mathbb{R}\cong \mathrm{u}(2)$.
\end{lem}
\begin{proof} The preservation of the polynomials $\Psi_{2i-1, 2i; 2j-1,2j}^1$, $\Psi_{2i-1, 2i; 2j-1,2j}^2$ along the magnetic flow \eqref{eq1}, \eqref{eq2} (and \eqref{eq3} for odd $n$) on $T^*S^{n-1}$ and a verification of the  Dirac-Poisson brackets follow by direct calculations.

Further, the function $e_0=\Phi_{2i-1,2i}+\Phi_{2j-1,2j}$ commutes with all the fisrt integrals. Let us set
\[
e_1=-\frac12\Psi_{2i-1, 2i; 2j-1,2j}^1,\quad e_2=-\frac12\Psi_{2i-1, 2i; 2j-1,2j}^2,\quad e_3=\frac{1}{2}(\Phi_{2j-1,2j}-\Phi_{2i-1,2i}).
\]
The Dirac-Poisson bracket   becomes
\[
\{e_1,e_2\}_d=e_3,\quad \{e_2,e_3\}_d=e_1,\quad \{e_3,e_1\}_d=e_2,\quad \{e_0,e_i\}_d=0,\quad i=1,2,3,
\]
which is the standard Lie bracket on $\mathrm{so}(3)\oplus \mathbb{R}\cong \mathrm{u}(2)$.
\end{proof}

Now we can state the main result of the paper.  Assume $\kappa_{12}\ne 0$.

\begin{thm}\label{glavna}
The magnetic geodesic flows are Liouville integrable on $T^*S^4$ and $T^*S^5$, corresponding to $n=5$ and $n=6$ respecively, for any $\kappa$. Moreover:

{\rm (i)} If $n=5$ and $\kappa_{12}=\kappa_{34}$, then the magnetic system \eqref{eq1}, \eqref{eq2},  and \eqref{eq3}  is integrable in the non-commutative sense: generic
motions are quasi-periodic over $3$-dimensional invariant
isotropic submanifolds.

{\rm (ii)} If $n=6$ and $\kappa_{12}=\kappa_{34}\ne\kappa_{56}$, then  the magnetic system \eqref{eq1} and  \eqref{eq2}  is integrable in the non-commutative sense:
generic motions are quasi-periodic over
$4$-dimensional invariant isotropic submanifolds.

{\rm (iii)} If $n=6$ and $\kappa_{12}=\kappa_{34}=\kappa_{56}$,  then  the magnetic system \eqref{eq1} and  \eqref{eq2}  is integrable in the non-commutative sense:
generic motions are quasi-periodic over
$3$-dimensional invariant isotropic submanifolds.

{\rm (iv)}  For  $n=5$, $\kappa_{34}=0$ and for $n=6$, $\kappa_{34}=\kappa_{56}=0$, the magnetic  systems %\eqref{eq1} and  \eqref{eq2}
 are integrable in the non-commutative sense:
generic motions are quasi-periodic over
$3$-dimensional invariant isotropic submanifolds.
\end{thm}

\begin{proof}
If $\kappa_{12}\ne \kappa_{34}$ for $n=5$ or $\kappa_{12}\ne\kappa_{34}\ne\kappa_{56}$ for $n=6$, the systems are  Liouville integrabile, according to Lemmas \ref{lema1}, \ref{lema2}, \ref{lema3}, \ref{lema4}.

Let $n=5$ and $\kappa_{12}=\kappa_{34}$. The system is Liouville integrable as well. However,
there are following additional first integrals:
\begin{align*}
&\Psi_{12;34}^1=(\gamma_{2}p_3-\gamma_{3}p_2)-(\gamma_{1}p_4-\gamma_{4}p_1) -s\kappa_{12}(\gamma_1\gamma_3+\gamma_2\gamma_4),\\
&\Psi_{12;34}^2=(\gamma_{1}p_3-\gamma_{3}p_1)+(\gamma_{2}p_4-\gamma_{4}p_2) -s\kappa_{12}(\gamma_1\gamma_4-\gamma_2\gamma_3).
\end{align*}
Let $\mathcal F$ be the algebra of first integrals generated by $H,J,\Phi_{12},\Phi_{34}, \Psi_{12;34}^1, \Psi_{12;34}^2$.
By a  direct verification, we prove that the  first integrals $H,J,\Phi_{12},\Phi_{34}, \Psi_{12;34}^1$ are functionally independent. Thus, $\ddim \mathcal F=5$ (see \cite{BJ2003}). On the other hand, the functions
\[
H, \, J, \, \Phi_{12}+ \Phi_{34}
\]
Poisson commute with all the first integrals. Thus, $\dind\mathcal F=3$, $\ddim\mathcal F+\dind\mathcal F=\dim T^*S^4$,
and the system is completely integrable in the non-commutative sense with $3$-dimensional isotropic tori generated by the Hamiltonian
vector fields of $H$, $J$, and $\Phi_{12}+ \Phi_{34}$ (see \cite{N, BJ2003}).

Let $n=6$ and $\kappa_{12}=\kappa_{34}\ne \kappa_{56}$. Again,  the Liouville integrability follows from Lemmas \ref{lema1}, \ref{lema2}, \ref{lema3}, \ref{lema4}.
According to Lemma \ref{lema5}, there are the following additional first integrals $\Psi_{12;34}^1$ and $\Psi_{12;34}^2$.
By a direct verification, we prove that the first integrals $H,J,\Phi_{12},\Phi_{34},\Phi_{56},\Psi_{12;34}^1$ are functionally independent.
The system is completely integrable in the non-commutative sense with $4$-dimensional isotropic tori, generated by the Hamiltonian
vector fields of $H$, $J$, $\Phi_{56}$, and $\Phi_{12}+ \Phi_{34}$.

Finally, let $n=6$ and $\kappa_{12}=\kappa_{34}=\kappa_{56}$.
Let $\mathcal F$ be the algebra of first integrals generated by
\[
H, \, \Phi_{12}, \, \Phi_{34}, \, \Phi_{56}, \, \Psi^1_{12;34}, \, \Psi^1_{12;56}, \, \Psi^1_{34;56}, \Psi^2_{12;34}, \, \Psi^2_{12;56}, \, \Psi^2_{34;56}.
\]
The functions $H, \Phi_{12}, \Phi_{34}, \Phi_{56}, \Psi^1_{12;34}, \Psi^1_{12;56},  \Psi^1_{34;56}$
are functionally independent.  On the other hand,
\[
H, \, \Phi_{12} + \Phi_{34} + \Phi_{56}, \, I
\]
commute with all first integrals, where
\begin{align*}
I=&2(\Phi_{12})^2+2(\Phi_{34})^2+2(\Phi_{56})^2\\
 &+(\Psi^1_{12;34})^2+(\Psi^2_{12;34})^2+(\Psi^1_{12;56})^2+(\Psi^2_{12;56})^2+(\Psi^1_{34;56})^2+(\Psi^2_{34;56})^2.
\end{align*}

Therefore, $\ddim\mathcal F+\dind\mathcal F=7+3=\ddim T^*S^5$ and the
system is completely integrable in the non-commutative sense with $3$-dimensional isotropic tori.
Note that the first integrals $\Phi_{12}, \, \Phi_{34}, \, \Phi_{56}, \, \Psi^1_{12;34}, \, \Psi^1_{12;56}, \, \Psi^1_{34;56}, \Psi^2_{12;34}, \, \Psi^2_{12;56}, \, \Psi^2_{34;56}$ form a Lie algebra isomorphic to $\mathrm{u}(3)$, which is related to the  $U(3)$-symmetry of the system \eqref{com1}.

The system is Liouville integrable as well: $3$-dimensional isotropic tori can be non-uniquely organized
into $5$-dimensional Lagrangian tori, the level sets of the commuting first integrals (see \cite{BJ2003}). For example, one can take the following commuting first integrals
$H, \, \Phi_{12}, \, \Phi_{34}, \, \Phi_{56}, \, I$.

The cases when $n=5$, $\kappa_{34}=0$ and $n=6$, $\kappa_{34}=\kappa_{56}=0$ are considered in Theorem \ref{integrabilni} below.
Note that item (iii) also follows from item (i) of Theorem \ref{integrabilni2}.
\end{proof}

\begin{rem}
The first integral of motion $J+4H^2$ is a polynomial of the degree $3$ in momenta. Therefore, in Theorem \ref{glavna} the integrability is acomplished by means of  polynomial first integrals of the degrees $1$, $2$, and $3$ in momenta.
\end{rem}

\begin{rem}
For $n=4$ and $\kappa_{12}=\kappa_{34}$, the  motion is qualitatively similar to the case $\kappa_{12}\ne\kappa_{34}$ (see \cite{DGJ2023}, Figures $2$, $3$, and $4$).
Namely, in this case, the first integrals $\Psi^1_{12;34}$ and $\Psi^2_{12;34}$ functionally depend on the first integrals $H, \, \Phi_{12}, \, \Phi_{34}$ and a
non-commutative integrability is not present here.
\end{rem}

\section{Reduction to the integrable cases with $n\le 6$}

For $n\ge 7$, by reduction to the cases with $n\le 6$, we derive the following three statements.

Similarly to Theorem 8.2 in \cite{DGJ2023}, we have:
% in the simplest case when only one parameter (or two parameters) $\kappa_{2i-1,2i}$ is different from zero, the system is
%$SO(2)\times SO(n-2)$-symmetric ($SO(2)\times SO(n-4)$ and we have:

\begin{thm}\label{integrabilni}
{\rm(i) $U(1)\times SO(n-2)$--symmetry.} Let $n\ge 5$. For $\kappa_{12}\ne 0$, $\kappa_{2i-1,2i}=0$, $i>1$ the magnetic geodesic flows  on  the sphere $S^{n-1}$ are completely integrable in noncommutative sense. Generic invariant manifolds are $3$-dimensional isotropic tori, the common level sets of $H$, $J$, $\Phi_{12}$, and the $SO(n-2)$--Noether first integrals
\[
\Phi_{ij}=\gamma_{i}p_{j}-\gamma_{j}p_{i}, \qquad 3\le i<j\le n.
\]
The magnetic flows are also Liouville integrable. One set of commuting first integrals consists of  $H$, $J$, $\Phi_{12}$, $\Phi_{34}$ and:
\begin{equation}\label{so(n-2)}
I_k=\sum_{3 \le i<j \le 4+k} (\Phi_{ij})^2, \qquad k=1,\dots, n-4.
\end{equation}

{\rm (ii) $U(2)\times SO(n-4)$--symmetry.} Let $n\ge 7$. For $\kappa_{12}=\kappa_{34} \ne 0$, $\kappa_{2i-1,2i}=0$, $i>2$ the magnetic geodesic flows  on  the sphere $S^{n-1}$ are completely integrable in the noncommutative sense. Generic invariant manifolds are $4$-dimensional isotropic tori, the common level sets of $H$, $J$,
$\Phi_{12}$, $\Phi_{34}$, $\Psi_{12;34}^1$, $\Psi_{12;34}^2$ and the $SO(n-4)$-Noether first integrals
\begin{align}\label{SO(n-4)}
\Phi_{ij}=\gamma_{i}p_{j}-\gamma_{j}p_{i}, \qquad 5\le i<j\le n.
\end{align}

{\rm (iii) $U(1)\times U(1)\times SO(n-4)$--symmetry.} Let $n\ge 7$. For $\kappa_{12}\ne \kappa_{34} \ne 0$, $\kappa_{2i-1,2i}=0$, $i>2$ the magnetic geodesic flow  on  the sphere $S^{n-1}$ is completely integrable in the noncommutative sense. Generic invariant manifolds are $5$-dimensional isotropic tori, the common level sets of $H$, $J$, $\Phi_{12}$, $\Phi_{34}$ and the $SO(n-4)$--Noether first integrals \eqref{SO(n-4)}.

In items {\rm (ii)} and {\rm (iii)} the magnetic flows are also Liouville integrable by means of commuting first integrals $H$, $J$, $\Phi_{12}$, $\Phi_{34}$, $\Phi_{56}$,
and:
\begin{align*}\label{so(n-4)}
I_k=\sum_{5 \le i<j \le 6+k} (\Phi_{ij})^2, \qquad k=1,\dots, n-6.
\end{align*}
\end{thm}

\begin{proof}[Sketch of the proof] The essence of item (i) of Theorem \ref{integrabilni} is that for every trajectory $(\gamma(t),p(t))$ of the system, there exists a matrix $R\in SO(n-2)$ such that the trajectory
\[
\tilde\gamma(t)^T=\diag(1,1,R)\cdot \gamma(t)^T,\qquad \tilde p(t)^T=\diag(1,1,R)\cdot p(t)^T
\]
belongs to the invariant space
\[
\{(\gamma,p)\in\R^{2n}\, \vert\, \phi_1=1, \, \phi_2=0, \, \gamma_5=\dots=\gamma_n=0, \, p_5=\dots= p_n=0\}\subset T^* S^{n-1}
\]
diffeomorphic to $T^*S^3$ (see Theorem 8.2 in \cite{DGJ2023}). Therefore, the problem reduces to the problem of integrability of the magnetic system on $T^*S^3$ with $\kappa_{12}\ne 0$, $\kappa_{34}=0$ described in Theorem \ref{stara}.

The Poisson commuting integrals \eqref{so(n-2)} are related to the filtration of Lie algebras: $\mathrm{so}(2)<\mathrm{so}(3)<\dots<\mathrm{so}(n-2)$ (see e.g. \cite{JSV2023}).

The items (ii) and (iii) follow by a similar $SO(n-4)$--reduction to $T^*S^5$ and Theorem \ref{glavna}.
\end{proof}

Following the same line of reasoning we come to the following statement.
%In what follows we use the natural inclusion $U(r)\subset SO(2r)$ related to the
%complex notation we already used above.

\begin{prop}\label{redukcija}
 Given $r\le [n/2]$, assume that
$
\kappa_{1,2}=\kappa_{3,4}=\dots=\kappa_{2r-1,2r}\ne 0.
$
Then:

{\rm (i)} The systems \eqref{com1} for $n$ even and the systems \eqref{com1}  and \eqref{eq3} for $n$  odd,  are $U(r)$--invariant, where the matrices $R$ from $U(r)$ act on  the first $r$ complex variables:
\[
(z_1,\dots,z_r)^T \longmapsto R\cdot (z_1,\dots,z_r)^T, \qquad  (w_1,\dots,w_r)^T \longmapsto R\cdot (w_1,\dots,w_r)^T
\]
 The corresponding first integrals $\Phi_{2i-1,2i}$, $\Psi_{2i-1,2i;2j-1,2j}^1$, $\Psi_{2i-1,2i;2j-1,2j}^2$, $1\le i \le r$, $i<j\le r$ form a Lie algebra
isomorphic to  $\mathrm{u}(r)$.

{\rm (ii)} In the real notation, for every trajectory $(\gamma(t),p(t))$ of the systems  \eqref{eq1} and  \eqref{eq2} for $n$ even and the systems
\eqref{eq1},  \eqref{eq2} and \eqref{eq3} for $n$ odd, there exists a matrix $R\in U(r)\subset SO(2r)$ such that the trajectory
\[
\tilde\gamma(t)^T=\diag(R,1,\dots,1)\cdot \gamma(t)^T, \qquad \tilde p(t)^T=\diag(R,1,\dots,1)\cdot p(t)^T
\]
belongs to the invariant space
\[
\{(\gamma,p)\in\R^{2n}\, \vert\, \phi_1=1, \, \phi_2=0, \, \gamma_1=\dots=\gamma_{2r-4}=0, \, p_1=\dots= p_{2r-4}=0\}\subset T^* S^{n-1}
\]
diffeomorphic to $T^*S^{n-2r+3}$.
\end{prop}

By combining Theorem \ref{glavna} and Proposition \ref{redukcija} we obtain

\begin{thm}\label{integrabilni2}
 Given $r\le [n/2]$, assume that
$\kappa_{12}=\kappa_{34}=\dots=\kappa_{2r-1,2r}\ne 0$. Then the following systems are integrable by means of  first integrals $H$, $J$,
$\Phi_{2k-1,2k}$, $k=1,\dots,[n/2]$, $\Psi_{2i-1,2i;2j-1,2j}^1$, $\Psi_{2i-1,2i;2j-1,2j}^2$, $1\le i \le r$, $i<j\le r$:

{\rm (i)}  When $n=2r$, the magnetic systems \eqref{eq1} and \eqref{eq2}  are integrable in the non-commutative sense: generic
motions are quasi-periodic over $3$-dimensional invariant isotropic submanifolds.

{\rm (ii)}  When $n=2r+1$,  the magnetic systems \eqref{eq1}, \eqref{eq2}, and \eqref{eq3}   are integrable in the non-commutative sense:
generic motions are quasi-periodic over $3$-dimensional invariant isotropic submanifolds.

{\rm (iii)}  When $n=2r+2$ and $\kappa_{12}\ne\kappa_{n-1,n}$,  the magnetic systems \eqref{eq1} and \eqref{eq2}   are integrable in the non-commutative sense: generic motions are quasi-periodic over $4$-dimensional invariant isotropic submanifolds.

The above systems are also Liouville integrable. One set of their commuting first integrals consists of
$H$, $J$, $\Phi_{2k-1,2k}$, $k=1,\dots,[n/2]$ and
\begin{equation}\label{komutativni}
I_k=\sum_{1 \le i < j \le k} (\Psi^1_{2i-1,2i;2j-1,2j})^2+(\Psi^2_{2i-1,2i;2j-1,2j})^2, \quad k=2,\dots,r.
\end{equation}
\end{thm}




Note that commuting first integrals are not unique (see \cite{BJ2003}) and the first integrals \eqref{komutativni} are related to the  filtration of Lie algebras $\mathrm{u}(1)<\mathrm{u}(2)<\dots<\mathrm{u}(n)$
(see e.g. \cite{JSV2023}).

\begin{rem}
Item (i) of Theorem \ref{integrabilni2} and item (ii) of Proposition \ref{redukcija} are in agreement with the
result of \cite{DIMN2015} for the standard contact sphere where  $n$ is even and $\kappa_{12}=\kappa_{34}=\dots=\kappa_{n-1,n}$.
There, it is proved that for every magnetic geodesic line $\gamma(t)$ on the standard contact sphere $S^{2r-1}$, there exists
a totally geodesic 3-sphere $S^3_{0}\subset S^{2r-1}$, such that $\gamma(t)$ is the magnetic geodesic line on $S^3_0$ endowed with the
standard contact structure.
\end{rem}



Finally,  there is a
 $U(r)\times SO(n-2r)$--symmetry
that allows a  reduction to $T^*S^5$. By combining
Theorems \ref{integrabilni} and \ref{integrabilni2}, we get:

\begin{thm}\label{integrabilni3}
 Given $r<[n/2]$, assume that
\[
\kappa_{12}=\dots=\kappa_{2r-1,2r}\ne 0,  \qquad \kappa_{2r+1,2r+2}=\dots=\kappa_{2[n/2]-1,2[n/2]}=0.
\]
Then the magnetic systems \eqref{eq1}, \eqref{eq2} for $n$ even and the magnetic  systems   \eqref{eq1}, \eqref{eq2} and \eqref{eq3} for $n$  odd, are integrable in the non-commutative sense by means of  first integrals $H$, $J$,
$\Phi_{2k-1,2k}$, $k=1,\dots,r$, $\Psi_{2i-1,2i;2j-1,2j}^1$, $\Psi_{2i-1,2i;2j-1,2j}^2$, $1\le i \le r$, $i<j\le r$ and
\[
\Phi_{ij}=\gamma_{i}p_{j}-\gamma_{j}p_{i}, \qquad 2r+1\le i<j\le n.
\]
Generic motions are quasi-periodic over $4$-dimensional invariant isotropic submanifolds.
The systems  are also Liouville integrable. One set of their commuting first integrals consists of
$H$, $J$, $\Phi_{2k-1,2k}$, $k=1,\dots,r$ and
\begin{align*}
& I_k=\sum_{1 \le i < j \le k} (\Psi^1_{2i-1,2i;2j-1,2j})^2+(\Psi^2_{2i-1,2i;2j-1,2j})^2, \quad k=2,\dots,r,\\
& I_{r+k}=\sum_{2r+1 \le i<j \le 2r+2+k} (\Phi_{ij})^2, \qquad k=1,\dots, n-2r-2.
\end{align*}
\end{thm}


The following classical mechanical problem is well-known:  motion of a material point of mass $m$ in $\R^n$ under the influence of the potential force field with a quadratic potential
\[
V(\gamma)=\frac12\big(a_1 \gamma_1^2+\dots+a_n\gamma_n^2\big).
\]
While the system of uncoupled harmonic oscillators is trivially integrable, the restriction of the problem to the sphere $S^{n-1}$ leads to one of the most interesting finite-dimensional  integrable systems  - the \emph{Neumann system} (see e.g. \cite{M}). The above considerations suggest  a similar situation in the case of the considered magnetic flows. There is an obvious integrability in $\R^n$, as shown in Theorem \ref{ocigledna}, while the integrability  of the system restricyed to the sphere $S^{n-1}$ is highly non-trivial.

\begin{con}\label{hipoteza}
Motion of a material point of mass $m$  and charge $-s$ on the  sphere $S^{n-1}$ placed in a constant homogeneous magnetic field $\mathbf F$ is completely integrable in the Liouville or in the noncommutative sense for any $n$ and $\kappa$.
\end{con}

\begin{rem}
It is of interest to consider magnetic geodesic flows for  more general metrics on the spheres $S^{n-1}$.
For example, there is a well-known Volterra--Zhukovskii integrable case of motion of a rigid body with a gyroscope around a fixed point \cite{Vol, Zh}.
By lifting the rigid body metric with respect to the two-covering $S^3\to SO(3)$, we obtain an integrable magnetic geodesic flow for any left-invariant metric on $S^3$.
Next, one can apply left $SO(2)$-magnetic reduction (see \cite{KNP2005}) to get a suitable integrable magnetic flow on the sphere $S^2$.
Let us note that there is a difference between the nonholonomic gyroscopic reduction \cite{DGJ2023, GMD2024} and the Hamiltonian magnetic reduction \cite{KNP2005}.
\end{rem}

