\section{Rigidity and pinning}
\label{sec:pin}

\subsection*{Proof of Proposition \ref{prop: pinned rigid}}
Suppose that $(G,\p)$ is pinned rigid and that the affine 
span of $\p$ is $\ell$-dimensional.  By hypothesis, there is an 
(unpinned) neighborhood $U$ of $\p$ such that, if $\q\in U$ 
is in $\ell$-pinned position, and $\q$ is equivalent to $\p$,  then 
$\q = \p$. 

When (an unpinned) $\q$ is near enough to $\p$, its first $\ell$ vertices
will be affinely independent. 
Thus $\q$ can be moved into  
$\ell$-pinned position with a rotation that is near to the identity. 
Thus this $\ell$-pinned configuration will be near to $\q$ and thus to $\p$.
Therefore 
we can find a 
smaller neighborhood 
$V\subseteq U$ of $\p$ with the property that any $\q\in V$
is congruent to a $\ell$-pinned configuration in $U$. 

Now suppose that $\q\in V$ and that $(G,\q)$ is equivalent to $(G,\p)$.
Because $\q\in V$, there is an isometry $T$ so that 
$T\q$
is in $\ell$-pinned position and $T\q\in U$.
Since $(G,\q)$ is equivalent to $(G,\p)$, so is 
$(G,T\q)$.  It now follows 
from the assumed pinned rigidity
that $T\q = \p$; i.e., $\q$ is 
congruent to $\p$.  The neighborhood $V$ certifies that $(G,\p)$ is (unpinned) rigid.

For the other direction, suppose that $(G,\p)$ is (unpinned) rigid with a $\ell$-dimensional span. Since rigidity is unaffected
by isometry, we may
WLOG assume that $\p$  is  pinned.
Let $U$ be a neighborhood of $\p$ such that, 
when $\q\in U$ and $(G,\q)$ is equivalent to $\p$,
then $\q$ is congruent to $\p$.
Using Lemma \ref{lem: pinning},
we find a neighborhood $W\subseteq U$ 
so that no other $\ell$-pinned configuration in $W$ is congruent to $\p$.
Now suppose that $\q\in W$ is a 
$\ell$-pinned configuration 
such that $(G,\q)$ is equivalent to $(G,\p)$. 
Because $\q \in U$, and $(G,\q)$ is equivalent 
to $(G,\p)$, $\q$ is congruent to $\p$.
Since $\q$ is in $W$, we have $\q = \p$.  This 
certifies that $(G,\p)$ is pinned rigid.
\hfill $\qed$.




\begin{lemma}\label{lem: pinning}
Let $\p$ be a  pinned configuration with 
$\ell$-dimensional affine span.  Then 
there is a neighborhood of $\p$ that does not contain any other 
$\ell$-pinned configuration of $n$ points that is congruent to $\p$.
\end{lemma}
\begin{proof}
Let 
$\q$ be a $\ell$-pinned configuration congruent to $\p$, 
and let $T$ be  an isometry so that $\q = T\p$.
If $\p_i = \q_i$ for all 
$1\le i\le \ell+1$, then $T$ is the identity on the affine 
span of $\p$, and hence on $\p$. 
Thus $\p = \q$.
To finish the proof, we find a neighborhood $U$ of $\p$ such that,
if $\q\in U$ is a $\ell$-pinned configuration that is 
congruent to $\p$, then $\q_i = \p_i$ for all 
$1\le i\le \ell+1$.  This we do by induction on $i$.

Let $U_1$ be any neighborhood of $\p$.  Let $\q\in U_1$ 
be in $\ell$-pinned position and congruent to $\p$.
Since 
$\p$ and $\q$ are in $\ell$-pinned position, certainly $\p_1 = \q_1$ (they 
are both the origin).  This establishes the base of the induction. 

Suppose now, for some 
$1 < j < \ell+1$, we have a neighborhood $U_j$ of 
$\p$, so that, if $\q\in U_j$ is $\ell$-pinned and 
congruent to $\p$, we have 
$\q_i = \p_i$ for $1 \le i \le j$.  We will show that that there is a neighborhood 
$U_{j+1}\subseteq U_j$ of $\p$ such that, if $\q\in U_{j+1}$
is in $\ell$-pinned position and congruent to $\p$, then 
$\q_{j+1} = \p_{j+1}$.  To this end, let $\x$ be a 
point in the linear span of $e_1, \ldots, e_j$ such that, 
for each $1\le i\le j$, $|\p_i - \x| = |\p_i - \p_{j+1}|$.
Because $\p$ is non-degenerate and $j \le \ell+1$, the $\p_i$ 
are affinely independent.  It now follows that either $\x = \p_{j+1}$
or $\x$ is the reflection (in the linear space spanned by the first $j$ 
coordinate vectors) through the affine span of the $\p_i$ 
(which is simply the linear space spanned by the first $j-1$ 
coordinate vectors). Since there is a positive distance between $\p_{j+1}$
and its reflection, shrinking $U_{j}$ sufficiently to remove this 
ambiguity closes the induction.

We stop at $U_{\ell+1}$, which proves the
lemma.
\end{proof}

\subsection*{Proof of Proposition \ref{prop: jk-flex change pinning}}


The main technical issue of the proof this this proposition is dealing with the
the $j$-active property of a $(j,k)$ flex.


\begin{definition}
An (unpinned)  trajectory $\p(t)$ 
is \defn{$k$-trivial}  if it agrees through $k$th order with
$T(t)\p(0)$
where $T(t)$ is an analytic
trajectory of isometries
and with $T(0)=I$.
\end{definition}


\begin{definition}
Let $(G,\p)$ be an unpinned framework.
Let $j,k$ be integers $\ge 1$.
An unpinned
trajectory $\p(t)$ is an unpinned \defn{$(j,k)$-flex} if
$\p(t)$ is $(j-1)$-trivial, but not $j$-trivial,
and $\m(\p(t))$ is $k$-vanishing.
\end{definition}
\begin{remark}
This is fundamentally the same as the definition of
Stachel~\cite{stachel,narwal}, since from 
{\cite[Lemma 4.2.1]{pss}}, the leading $k$ derivatives
of a $k$-trivial trajectory
can be always zeroed out under an appropriate analytic 
trajectory of isometries.
\end{remark}



\begin{lemma}
\label{lem:isoTraj}
Let $\p$ be a non-degenerate unpinned configuration with affine span of
dimension $\ell$,
and let $\p(t)$ be an unpinned analytic trajectory
starting from $\p$.
Then there is an analytic trajectory of isometries 
$T(t)$,
for $t\in[0,\eps)$ for some $\eps$,
so that $\q(t) := T(t)  \p(t)$
is an $\ell$-pinned trajectory.
\end{lemma}
\begin{proof}
First consider the case in which $\p(0)$ has full affine span; fix an 
$\eps > 0$ such that, for $t\in [0,\eps)$, $\p(t)$ has 
full affine span.  For simplicity, 
assume, for the moment, that $\p(t)_1$ remains at the origin throughout the motion.  
With these assumptions, for each $t$, we compute, using Gram--Schmidt, a linear isometry 
$T(t)$ such that $T(t)\p(t)$ is pinned and that the $i-1$st coordinate of 
$(T(t)\p(t))_i$ is positive, for $2\le i\le d+1$.

Here are the details of the construction.  Fix $t$.  Put $\p(t)_2, \ldots, \p(t)_{\ell+1}$
in the columns of a $d\times d$ matrix $P$.  The Gram--Schmidt process produces an 
orthogonal matrix $Q$ such that $P = QR$ with $R$ upper triangular.  Since 
$\p(t)$ has full affine span, there are 
only 
finitely many choices for $Q$ (determined 
by the signs of the diagonal entries of $R$).  For consistency, we 
\emph{choose} these to be positive.  The desired $T(t)$ such that $T(t)\p(t)$ is $d$-pinned 
is defined by $Q^{-1}$.
In particular $Q^{-1}P=R$
which has 
a triangular structure.

All the steps in Gram--Schmidt are deterministic and analytic 
in $\p(t)$ (they are Euclidean norms, dot products, and vector space 
operations).  Hence $T(t)$ is analytic in $t$.  We proved that $T(t)\p(t)$
is $d$-pinned above, so this case is complete.

To deal with the general case, in which $\ell < d$, we fix a set of 
vectors $\x_{\ell+2}, \ldots, \x_{d+1}$ so that the collection 
$\p(0)_1, \ldots, \p(0)_{\ell+1}, \x_{\ell+2}, \ldots, \x_{d+1}$ is affinely 
independent.  Since affine independence is an open condition, 
we can find an $\eps > 0$ so that, for all 
$t\in [0,\eps)$, the collection $\p(t)_1, \ldots, \p(t)_{\ell+1}, \x_{\ell+2}, \ldots, \x_{d+1}$
is affinely independent.  The construction is the same as before, except we use the $\x_i$ 
instead of $\p(t)_i$ with $\ell + 2 \le i \le d+1$ when we run Gram--Schmidt.  Then 
the output is $\ell$-pinned.

Finally, we deal with the case in which $\p(t)$ has a translational component 
by applying the previous argument to the analytic trajectory $\q(t)_i = \p(t)_i - \p(0)_1$,
which does have its first point fixed.  If $T(t)$ is the analytic  path of isometries 
we get from the previous argument applied to $\q(t)$, we can define an analytic path of isometries $S(t)$ 
by the formula:
\[
    S(t)\x = T(t)(\x - \p(0)_1) + \p(0)_1.
\]
This path $S(t)$ satisfies the conclusion of the lemma.
\end{proof}



\begin{lemma}
\label{lem:transfer}
If an unpinned trajectory  $\p(t)$ is k-trivial and $T$ is an isometry, then $T\p(t)$ is k-trivial.
\end{lemma}
\begin{proof}
From the triviality assumption, 
we have $\p(t)$ in agreement
through order $k$ with some
$\bar{T}(t)\p(0)$, where $\bar{T}(t)$
is an analytic trajectory of isometries.
Computation shows that $T\p(t)$ is in agreement
through order $k$ with 
$T\bar{T}(t) T^{-1} (T\p(0))$, and 
 $T\bar{T}(t) T^{-1}$ is an analytic trajectory of isometries that is $I$
at $t=0$.
\end{proof}
We also have:
\begin{lemma}[{\cite[Lemma 4.2.3]{pss}}]
\label{lem:ktrivTran}
Let $T(t)$ be an analytic trajectory of isometries. Assume $T(0)=I$.
Suppose an unpinned trajectory
$\p(t)$ is k-trivial. 
Then $T(t)\p(t)$ is k-trivial.
\end{lemma}

Combining the two previous
lemmas, we get
\begin{lemma}
\label{lem:ktrivTran2}
Let $T(t)$ be an analytic trajectory of isometries.
Suppose an unpinned trajectory
$\p(t)$ is k-trivial. 
Then $T(t)\p(t)$ is k-trivial.
\end{lemma}


\begin{lemma}
\label{lem:trivPinZerohigher}
Suppose that $\p$ has an 
$\ell$ dimensional affine span
and is pinned.
If a trajectory $\p(t)$ is $\ell$-pinned and
$k$-trivial  then it is $k$-vanishing.
\end{lemma}
\begin{proof}
Suppose that $\p(t)$ is not
$k$-vanishing and is $k$-trivial. 
So $\p(t)$ is $j$-active for 
some $j\le k$ 
Then from~\cite[Lemma 4.2.2]{pss}, 
$\p(0)+\p^{(j)}(t)$ is $1$-trivial.
As discussed in \cite[p. 171, inter alia]{pss}, 
for a $1$-trivial flex, there is a $d\times d$ 
skew-symmetric $A$ and a vector $\b\in \RR^d$ such that, for all $i$
\ba
\p^{(j)}_i = A \p_i(0) + \b.
\ea
Now we use pinning to show that $\b = 0$ and that 
all the pinned vertices are in the kernel of $A$.
This will show that $\p(t)$ is not $j$-active, leading to 
a contradiction.  

That $\b = 0$ follows from the fact that $\p(t)_1$
must remain at the origin for all $t$.  Suppose 
now that the affine span of $\p(0)$ is $\ell$-dimensional.
Because $\p(0)$ is pinned, for $2\le i\le \ell+1$, 
$\p(t)_i$ lies in the span of $e_1, \ldots, e_{i-1}$
and the same thing must be true at any order, so in particular, 
for $\p^{(j)}$.

We now show, by induction%
\footnote{The reader can also quickly convince themselves 
by an example.}%
%
, that the first $\ell$ columns of $A$
are zero.  For the base case, observe that $\p^{(j)}_2$ is a 
multiple of $e_1$, so the above discussion implies that 
$A\p^{(j)}_2 = \alpha e_1$ for some $\alpha$.  Since $A$ is 
skew-symmetric, its diagonal entries are zero, from which 
we conclude that $\alpha = 0$; i.e., that the first 
column (and thus also first row) 
of $A$ is zero.  For the inductive step, we assume 
the statement for $i-1$.  We know that $\p^{(j)}_i$
is in the span of $e_1, \ldots, e_{i-1}$ and that 
$A\p^{(j)}_i$ is as well.  By the IH, and skew -symmetry of $A$, we get that $A\p^{(j)}_i = \alpha e_{i-1}$, since the 
first $i-2$ entries of the $(i-1)$st column of $A$ are known 
to be zero.  Because $A$ has zeros on the diagonal, we conclude
that $\alpha = 0$, which closes the induction.
\end{proof}
\begin{remark}
A skew-symmetric $d\times d$ matrix that is zero on its first $d-1$ columns is 
necessarily the zero matrix, so the process in the proof above can stop 
early when $\ell = d$.
\end{remark}

\begin{proof}[Proof of Proposition \ref{prop: jk-flex 
change pinning}]
Let $\p$ be a configuration with affine span 
of dimension $\ell$.
Let $(G,\p)$ an unpinned framework with a $(j,k)$ flex $\p(t)$; 
i.e., $\p(t)$ is $(j-1)$-trivial, $\p(t)$ is not $j$-trivial, and $\m(\p(t))$ 
is $k$-vanishing.  By Lemma \ref{lem:isoTraj}, there is an analytic 
trajectory of isometries $T(t)$ such that $\q(t) := T(t)\p(t)$
is an analytic $\ell$-pinned trajectory.  From Lemma \ref{lem:ktrivTran2} (applied to 
$T(t)$), we conclude that $\q(t)$ is $(j-1)$-trivial.  Applying 
Lemma \ref{lem:ktrivTran2} to $T^{-1}(t)$ (which is also analytic),
we get that $\q(t)$ is not $j$-trivial. 
By Lemma \ref{lem:trivPinZerohigher}, because $\q(t)$ is $(j-1)$-trivial 
and $\q(t)$ is 
$\ell$ pinned, it is $(j-1)$-vanishing.
Because $\q(t)$ is not $j$-trivial, it
is not $j$-vanishing. Thus it is $j$-active.
Because $\m(\p(t)) = \m(T\p(t)) = \m(\q(t))$,
the derivatives are the same at all orders, so we get that $\m(\q(t))$ is $k$-vanishing.
In summary, $\q(t)$ is a pinned $(j,k)$ flex.

For the other direction, let $\p$ be a pinned configuration with an $\ell$ dimensional 
affine span.  Let $\p(t)$ be an $\ell$-pinned $(j,k)$ flex.
Let $(G,\q)$ be a framework that is congruent to $\p$.  There 
is an isometry $T$ so that $\q = T\p$.  
We define $\q(t) := T\p(t)$.
This is an analytic trajectory starting at $\q$.  We will show that 
$\q(t)$ is an unpinned $(j,k)$ flex.
As before, since $\m$ is invariant to 
isometries, $\m(\q(t))$ is $k$-vanishing because $\m(\p(t))$ is.  Because 
$T$ is affine and $\p(t)$ is $(j-1)$-vanishing, $\q(t)$ is also $(j-1)$-vanishing, 
which, in particular implies it is $(j-1)$-trivial.  By Lemma \ref{lem:transfer},
if $\q(t)$ was $j$-trivial, then $\p(t)$ would also be $j$-trivial and then, by 
Lemma \ref{lem:trivPinZerohigher} $j$-vanishing.  Since $\p(t)$ is 
not $j$-vanishing, 
we reach a contradiction and
thus  conclude that $\q(t)$ is not $j$-trivial.
\end{proof}

