\begin{claim}
Let $u \in V(T)$ be a parent of a vertex $v \in V(T)$ and $t \in \mathbb{Z}_{\geq0}$. The following three statements are equivalent.

\begin{enumerate}
    \item The vertex $v$ is weakly $t$-stable.
    %\item For every odd $k > 0$, if $\xi_{t+j}(u) = \xi_{t}(v)$ for every odd $k \geq j > 0$ then $\xi_{t+k+1}(v) = \xi_{t}(v)$.
    \item For the vector $\tilde\xi^*_0:\, V(T)\to\{-1,1\}$ such that $\tilde\xi^*_0|_{V(T_v)} = \xi_t|_{V(T_v)}$ and $\tilde\xi^*_0(\{V(T)\setminus V(T_v)\}) = \{\xi_t(v)\}$, the vertex $v$ is $0$-stable w.r.t. $\tilde\xi^*_0$.
    \item For every odd $k > 0$ and $\hat\xi_0:\, V(T)\to\{-1,1\}$ such that $\hat\xi_0|_{V(T_v)} = \xi_t|_{V(T_v)}$ and $\hat\xi_{j}(u) = \hat\xi_{0}(v)$ for every odd $j \in \{1, 3, \ldots, k\}$, it holds that $\hat\xi_{k+1}(v) = \hat\xi_{0}(v)$.
\end{enumerate}
\label{cl:equivalent_weak_definitions}
\end{claim}

\begin{proof}

$(1 \implies 2)$ Let $\tilde\xi$ be any vector from the definition of weak $t$-stability. Let us note that for every $w \in V(T)$, if $\tilde\xi_0(w) = \xi_t(v)$ then $\tilde\xi_0^*(w) = \xi_t(v)$. So, by induction on $k$, we get that for every $k \in \mathbb{Z}_{\geq 0}$, if $\tilde\xi_k(w) = \xi_t(v)$, then $\tilde\xi_k^*(w) = \xi_t(v)$. Hence, if $v$ is 0-stable w.r.t. $\tilde\xi_0$, then it is also 0-stable w.r.t. $\tilde\xi_0^*$.

$(2 \implies 3)$ Fix an odd $k > 0$, a vector $\hat\xi_0$ from the third definition of weak stability, and the vector $\tilde\xi_0^*$ from the second definition. Let us note that $u$ is 1-stable w.r.t. $\tilde\xi^*_0$ with $\tilde\xi_1^*(u)=\tilde\xi^*_0(v)=\xi_t(v)$ since its child $v$ is 0-stable and all vertices outside $V(T_v)$ have initial opinion $\tilde\xi^*_0(v)$. So, for every odd $j \in \{1, 3, \ldots, k\}$, 
$$
\hat\xi_{j}(u) = \hat\xi_0(v)=\xi_t(v)=\tilde\xi_1^*(u)=\tilde\xi^*_{j}(u).
$$
Therefore, for every $i \in \{0, 1, \ldots k\}$ and for every vertex $w \in V(T_v)$ such that $d_T(w, v)$ has the same parity as $i$, $\hat\xi_i(w)=\tilde\xi^*_i(w)$. Indeed, for $i=0$, this is clearly true since $\tilde\xi_0^*|_{V(T_v)}=\hat\xi_0|_{V(T_v)}$. Assuming that $\hat\xi_{i-1}(w)=\tilde\xi^*_{i-1}(w)$ for every vertex $w \in V(T_v)$ such that $d_T(w, v)$ has the same parity as $i-1$, we immediately get that $\hat\xi_{i}(w)=\tilde\xi^*_{i}(w)$ for every vertex $w \in V(T_v)$ such that $w\neq v$ and $d_T(w, v)$ has the same parity as $i$. Moreover, if $i$ is odd, then we do not have to consider the vertex $w=v$ at time $i$. If $i$ is even, then $\hat\xi_{i}(v)=\tilde\xi^*_{i}(v)$, since opinions in these two processes coincide for children of $v$ at time $i-1$, and the parent $u$ has equal opinions $\hat\xi_{i-1}(u)=\tilde\xi^*_{i-1}(u)$ as we have just proved as $i-1$ is odd.
%has the same opinion at time step $i$ in majority dynamics starting with both $\hat\xi_0$ and $\tilde\xi^*_0$.
% The above-mentioned follows from induction on $i$.
 So, indeed, $\hat\xi_{k+1}(v) = \tilde\xi^*_{k+1}(v) =\tilde\xi^*_0(v) = \hat\xi_0(v)$.

$(3 \implies 1)$ Let us note that $u$ is 1-stable w.r.t. the vector $\tilde\xi^*_0$ introduced in the second definition of weak stability with $\tilde\xi^*_1(u)=\tilde\xi^*_0(v)$, since $u$ has degree 3 and all vertices outside $V(T_v)$ have initial opinion $\tilde\xi^*_0(v)$. So, the vector $\tilde\xi^*_0$ satisfies conditions in the third definition of weak stability, thus we set $\hat\xi_0 := \tilde\xi^*_0$. We know that $\hat\xi_{k+1}(v)=\hat\xi_0(v)$ for all odd $k$, that is $v$ is 0-stable w.r.t. $\hat\xi_0$. Hence, $\tilde\xi_0:=\hat\xi_0$ witnesses the weak $t$-stability of $v$.
%Weak $t$-stability of $v$ follows from the substitution $\tilde\xi := \tilde\xi^*$.

\end{proof}

\begin{claim}

Let $u \in V(T)$ be a parent of a weakly $t_1$-stable vertex $v \in V(T)$ for $t_1 \in \mathbb{Z}_{\geq0}$. Let $t_2 > t_1$ have the same parity as $t_1$. For every time step $t \in \{t_1+1, t_1+3, \ldots t_2-1\}$ let $\xi_{t}(u) = \xi_{t_1}(v)$. Then, $\xi_{t_2}(v) = \xi_{t_1}(v)$.

\label{cl:maintain_weak_value}

\end{claim}

\begin{proof}
Let us apply the third equivalent definition from Claim~\ref{cl:equivalent_weak_definitions} with $\hat{\xi}_0 := \xi_{t_1}$ and $k := t_2-t_1 - 1$. Then, 
$\hat{\xi}_t = \xi_{t_1 + t}$ for any $t > 0$. 
So, $\hat\xi_{j}(u) = \hat\xi_{0}(v)$ for every odd $j \in \{1, 3, \ldots, k\}$. 
So it holds that $\hat\xi_{k+1}(v) = \hat\xi_{0}(v)$. 
Hence, $\xi_{t_2}(v) = \hat{\xi}_{k+1}(v) = \hat{\xi}_0(v) = \xi_{t_1}(v)$, as needed.

\end{proof}

