\end{proof}

Let us say that a non-leaf vertex $v \in V(T)$, $v \neq R$, is {\it 1-close to stability} if the following property holds. Let $\tilde\xi_0:\, V(T)\to\{-1,1\}$  be
such that $\tilde\xi_0|_{V(T_v)} = \xi_0|_{V(T_v)}$ and $\tilde\xi_t(v) \neq \tilde\xi_0(v)$ for some even $t>0$. Then $v$ is weakly $t$-stable w.r.t. $\tilde\xi_t$, where $t$ is the first even moment when $\tilde\xi_t(v) \neq \tilde\xi_0(v)$.

%{\color{red}We also need to show several properties of being 1-close to stability (Claim~\ref{cl:one_far_stabilization} and Claim~\ref{cl:weak_calculations}), in order to prove Lemma~\ref{lm:binary_upper}.}

\begin{claim}
Let $t \in 2\mathbb{Z}_{\geq 0}$, $d \in 2\mathbb{Z}_{> 0}$, even $\ell \in [d]$, and a path $P=v_0 v_1 \ldots v_d$ in $T$ be such that 
\begin{itemize}
    %\item $R\notin V(P)$;
    \item $T_{v_0} \cap T_{v_d} = \varnothing$ (i.e. the path is not monotone);
    \item $\xi_t(v_i) = \xi_t(v_0)$ for every even $i \in [\ell-2]$;
    \item $\xi_t(v_i) = \xi_t(v_d)$ for every even $i \in [d-2] \setminus [\ell-2]$;
    \item $\xi_s(v_0) = \xi_0(v_0) \neq \xi_0(v_d) = \xi_s(v_d)$ for every even $s \in [t]$;
    \item $v_0$ and $v_d$ are weakly $0$-stable;
    \item $v_0$ and $v_d$ are 1-close to stability.
\end{itemize}
Then, for every even $t'\geq t$ and every even $i \in \{2,\ldots,d-2\}$, $\xi_{t'}(v_i) \in \{\xi_{t'}(v_{i-2}),\xi_{t'}(v_{i+2})\}$. In addition, for every even $t'\geq t$, $v_d$ is either weakly $t'$-stable or $t'$-stable.
\label{cl:one_far_stabilization}
\end{claim}

