%$$
%where
$$
 q_3^1:=\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{\text{all vertices of $U_i$ are weakly 0-stable}\}),
$$
$$
 q_3^2:=\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{\text{exactly one vertex of $U_i$ is not weakly 0-stable}\}).
$$
In what follows, we prove bounds on $q_3^2$ and $q_3^3$ separately.




%We assume that $\mathcal{E}_1(P)$ holds and every vertex from $U_i$ is 1-close to stability. Let $q_3^2$ be the probability of this event intersected with the event that all vertices of $U_i$ are weakly 0-stable. Let $q_3^3$ be the probability of the same event but intersected with the event that exactly one vertex of $U_i$ is not weakly 0-stable. We will consider two disjoint sub-cases defining $q_3^2$ and $q_3^3$.

We start from $q_3^2$. Claim~\ref{cl:12_from_11} gives us that, for every $u \in U_i$ and every even $t \leq i-2$, $\xi_t(u) = 1$. In particular, $\xi_0(u) = \xi_2(u)$. The strategy of the remaining proof is as follows: We assume that the event $\xi_0(w_i)=\xi_0(u_{i+1})=\xi_0(w_{i+2})=1$ holds deterministically. Then, for every $u \in U_i$, we introduce an event that implies $\xi_0(u) \neq \xi_2(u)$ and such that all these three events (corresponding to $w_i,u_{i+1},w_{i+2}$) are independent of each other and of initial opinions of all vertices from $U_i\cup\{v_i,v_{i+2}\}$. %\gz{Should we also note that the events are described by initial opinions of $A_i$? Since the opinions of vertices outside $A_i$ can take any value.}
%let us give a lower bound on the probability that $u$ changes its opinion at time step $2$. This bounds will be described by the initial opinions of the grandchildren of $u$. Hence, by Remark~\ref{rm:independancy_general}, the bounds will be independent with each other and the event $\{\xi_0(w_i) = \xi_0(u_{i+1}) = \xi_0(w_{i+2}) = 1\}$. 
For $u\in\{w_i,w_{i+2}\}$, this is the event that all four grandchildren of $u$ have initial opinion -1. Probability of this event equals $1/16$. For $u=u_{i+1}$, the desired event is that $u$ has a child with both children having initial opinion $-1$ (this event has probability $7/16$). Indeed, since $\xi_0(v_i) = \xi_0(v_{i+2}) = -1$, we have that $\xi_1(v_{i+1}) = -1$, and thus, for $u=u_{i+1}$, in order to change its opinion to $-1$ at time 2, it is sufficient to have one child that has opinion $-1$ at time~1. Due to Remark~\ref{rm:independancy_general}, the introduced ``lower bound events'' are independent, and thus
%Vertices $w_i$ and $w_{i+2}$ change their opinion at time step $2$ if each of their grandchildren have opinion $-1$. (The probability is $1/16$). Next, $\xi_1(v_{i+1}) = -1$, since $\xi_0(v_i) = \xi_0(v_{i+2}) = -1$. So, $u_{i+1}$ changes opinion at time step $2$ if and only if it has a child $u$ such that both of the children of $u$  have initial opinion $-1$. (The probability is $7/16$). Therefore,
\begin{align}  
q_3^1 &\leq \mathbb{P}^*\left(\bigwedge_{u\in U_i}\{\xi_0(u)=1\}\wedge \bigwedge_{u\in U_i}\{\xi_0(u) \neq \xi_2(u)\}\right)\notag\\
&\leq\mathbb{P}\left(\bigwedge_{u\in U_i}\{\xi_0(u)=1\}\right)\left(1-\frac{1}{16}\right)^2\left(1-\frac{7}{16}\right)\notag\\
&=\frac{1}{8} \cdot \left(\frac{15}{16}\right)^2 \cdot \frac{9}{16} < 0.0618.
\label{eq:q-second_case_1}
\end{align}


Next, let us give an upper bound on $q_3^3$. Let $u \in U_i$ be the unique vertex that is not weakly 0-stable.
Let us prove that, in order to satisfy $\mathcal{E}_1(P)$, the following properties must hold:
\begin{itemize}
    \item[B1] the two vertices from $U_i\setminus\{u\}$ have initial opinion $1$;
    \item[B2] $\xi_t(u) = 1$ for some deterministic (that does not depend on $\xi_0\in\mathcal{E}_1(P)$) time step $t := t(u,i) \in \{i-2,i\}$.
\end{itemize}

B1 follows from~\eqref{eq:proposition_E_1_contradiction_claim14} and the fact that 
Claim~\ref{cl:weak_stabilization} and Claim~\ref{cl:one_far_stabilization} are applicable to the path between the two vertices from $U_i\setminus\{u\}$ and time moment $t=0$. Indeed, if both initial opinions are~$-1$, then the considered path clearly satisfies the requirements of Claim~\ref{cl:weak_stabilization}. If the initial opinions are different, then the only non-trivial case that may interfere the requirements of Claim~\ref{cl:one_far_stabilization} is when $u=u_{i+1}$ and the path between the remaining two vertices from $U_i$ has seven vertices. However, since we assumed that $\xi_0(v_i)=\xi_0(v_{i+2})$, the initial opinions of $w_i,v_i,v_{i+2},w_{i+2}$ along the path change only once, as required.
B2 is an instant corollary of $\mathcal{E}_1(P)$ --- actually, $t$ is either $i-2$ or $i$ depending on the choice of $u\in U_i$. Due to Claim~\ref{cl:strong_calculations}, the probability that $u \text{ is not weakly }0\text{-stable and B2 holds}$ can be bounded from above by the probability of an event that only depends on $\xi_0|_{V(T_u)}$ which is, in turn, at most $0.038$. Hence, by Remark~\ref{rm:independancy_general} the latter event is independent from the event B1. So,
\begin{equation}
q_3^2 \leq 3 \cdot \mathbb{P}(\{u \text{ is not weakly }0\text{-stable}\}\wedge \text{B1} \wedge \text{B2}) < 3 \cdot 0.038 \cdot \frac 1 4 = 0.0285.
\label{eq:q-second_case_2}
\end{equation}
Finally, due to~\eqref{eq:q-second_case_1}~and~\label{eq:q-second_case_2},
\begin{equation}
 q_3=q_3^1+q_3^2<0.0618+0.0285=0.0903.
\label{eq:q-second_case}
\end{equation}

\paragraph{Consider the last case $\xi_0(v_i) \neq \xi_0(v_{i+2})$.} Here, we actually have two ways of giving initial opinions to $v_i$ and $v_{i+2}$ but we plan to prove the same upper on $q_3$ in those cases. % Let every vertex from $U_i$ be 1-close to stability and there be at most one vertex $u \in U_i$ which is not weakly 0-stable. For this event, there are actually two ways to choose the initial opinions of $v_i$ and $v_{i+2}$ but we want to give the same upper bound for them. So, 
%Let $q_3^4$ denote the maximum of the probabilities $q_3$ of the event $\mathcal{E}_2(P)$ among the case $\xi_0(v_i) = -1$, $\xi_0(v_{i+2}) = 1$ and the case $\xi_0(v_i) = 1$, $\xi_0(v_{i+2}) = -1$.

Let us prove that if every $u\in U_i$ is weakly 0-stable, then $\mathcal{E}_1(P)$ does not hold. Indeed, since $\xi_0(v_i) \neq \xi_0(v_{i+2})$, there is an index $j \in \{i, i+2\}$ such that $\xi_0(u_{i+1}) = \xi_0(v_j)$. Then we can apply either Claim~\ref{cl:weak_stabilization} or Claim~\ref{cl:one_far_stabilization} to the path between $u_{i+1}$ and $w_j$ at time step 0, getting a contradiction with~\eqref{eq:proposition_E_1_contradiction_claim14}. Indeed, both $u_{i+1}$ and $w_j$ are weakly 0-stable. So, since $\xi_0(u_{i+1}) = \xi_0(v_j)$, if $\xi_0(u_{i+1}) = \xi_0(w_j)$ then Claim~\ref{cl:weak_stabilization} applies and if $\xi_0(u_{i+1}) \neq \xi_0(w_j)$ then Claim~\ref{cl:one_far_stabilization} applies.

Therefore, if $\mathcal{E}_2(P)$ holds, then there is a single vertex from $U_i$ which is not weakly 0-stable; denote this vertex by $u$. % Below we will consider three possible cases based on the choice of $u$. In this cases we will give an upper bound on the probability by the initial opinion of the vertices outside $V(T_u)$. In addition,
 Due to $\mathcal{E}_1(P)$, there exists a deterministic (that does not depend on $\xi_0\in\mathcal{E}_1(P)$) time step $t := t(u,i) \in \{i-2,i\}$ such that $\xi_t(u) = 1$. Due to Claim~\ref{cl:strong_calculations}, the probability of the latter event jointly with the event that $u$ is not weakly 0-stable can be bounded from above by the probability of an event that only depends on $\xi_0|_{V(T_u)}$ which is, in turn, at most $0.038$. We further consider separately three cases, depending on the particular choice of $u$.


% the probability that $u \text{ is not weakly }0\text{-stable and } \xi_t(u) = 1$ can be bounded from above by the probability of an event that only depends on $\xi_0|_{V(T_u)}$ which is, in turn, at most $0.038$. Hence, by Remark~\ref{rm:independancy_general} our final upper bound on $q_3^4$ will be $0.038$ multiplied by the sum of the bound for three cases given below.

\paragraph{1) $u=w_{i+2}$.} %If $w_{i}$ and $u_{i+1}$ are weakly 0-stable, then we can prove
We have $\xi_0(w_{i}) = \xi_0(u_{i+1}) \neq \xi_0(v_i)$ due to~\eqref{eq:proposition_E_1_contradiction_claim14} by applying Claim~\ref{cl:weak_stabilization} or Claim~\ref{cl:one_far_stabilization} at time step 0 to the path between $w_i$ and $u_{i+1}$. Indeed, both $u_{i+1}$ and $w_i$ are weakly 0-stable. So, if $\xi_0(u_{i+1}) = \xi_0(w_i) = \xi_0(v_i)$ then Claim~\ref{cl:weak_stabilization} applies and if $\xi_0(u_{i+1}) \neq \xi_0(w)$ then Claim~\ref{cl:one_far_stabilization} applies. So, $q_3\leq 0.038\cdot\frac{1}{4}$. Moreover, if $\xi_0(v_i) = 1$, we can improve this bound: since $\xi_0(w_i)=\xi_0(u_{i+1})=-1$, the event $\mathcal{E}_1(P)$ implies that both $w_i$ and $u_{i+1}$ are not strongly 0-stable. So, in this case, $\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{u=w_{i+2}\})\leq 0.038\cdot\frac{1}{4}(1-p_{\mathrm{s}}(0))^2$. We get
\begin{equation}
\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{u=w_{i+2}\})\leq 0.038\cdot\frac{1}{4}\left(\1_{\xi_0(v_i) =- 1}+(1-p_{\mathrm{s}}(0))^2\cdot \1_{\xi_0(v_i) = 1}\right).
\label{eq:q_3_1}
\end{equation}


\paragraph{2) $u=w_{i}$.} Since $w_{i+2}$ and $u_{i+1}$ are weakly 0-stable, in the same way as in the case 1), we get $\xi_0(w_{i+2}) = \xi_0(u_{i+1}) \neq \xi_0(v_{i+2})$. So, here we get that $\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{u=w_{i+2}\})\leq\frac{1}{4}$ as well. In a similar way, by distinguishing between $\xi_0(v_{i+2}) = -1$ and $\xi_0(v_{i+2}) = 1$, we get
\begin{equation}
\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{u=w_{i}\})\leq 0.038\cdot\frac{1}{4}\left(\1_{\xi_0(v_{i+2}) =- 1}+(1-p_{\mathrm{s}}(0))^2\cdot \1_{\xi_0(v_{i+2}) = 1}\right).
\label{eq:q_3_2}
\end{equation}
%In addition, in the same way we also can give a stronger upper bound $1/4(1-p_{\mathrm{s}}(0))^2$ if $\xi_0(v_{i+2}) = 1$.

%Let us note that, since one of $v_i$ and $v_{i+2}$ has an initial opinion $1$, we can give the stronger upper bound in either case~{$\mathbf{1}$} or case~{$\mathbf{2}$}. In other words, the sum of the probabilities of this two cases has an upper bound of $1/4 + 1/4(1-p_{\mathrm{s}}(0))^2$.

\paragraph{3) $u=u_{i+1}$.} Then $w_i$ and $w_{i+2}$ are weakly 0-stable. If $\xi_0(w_{i}) = \xi_0(v_{i})$ and $\xi_0(w_{i+2}) = \xi_0(v_{i+2})$, then $\mathcal{E}_1(P)$ does not hold due to~\eqref{eq:proposition_E_1_contradiction_claim14} and Claim~\ref{cl:one_far_stabilization} applied to the path between $w_{i}$ and $w_{i+2}$ at time moment 0. Indeed, the initial opinion changes just once in the sequence $w_i, v_{i}, v_{i+2}, w_{i+2}$ and $w_i$ and $w_{i+2}$ are weakly 0-stable. Therefore, $\xi_0|_{\{w_i,w_{i+2}\}}$ has three possible initial values, excluding $(\xi_0(v_i),\xi_0(v_{i+2}))$; the latter vector has a single $-1$. Note that $\mathcal{E}_1(P)$ implies the following: if $w \in \{w_i, w_{i+2}\}$ has initial opinion $-1$ then it is not strongly 0-stable. Summing up, we get 
\begin{equation}
\mathbb{P}^*(\mathcal{E}_2(P)\wedge\{u=u_{i+1}\})\leq 0.038\cdot\frac{1}{4}\left(1 + (1-p_{\mathrm{s}}(0)) + (1-p_{\mathrm{s}}(0))^2\right).
\label{eq:q_3_3}
\end{equation}

The bounds~\eqref{eq:q_3_1},~\eqref{eq:q_3_2},~and~\eqref{eq:q_3_3} imply
\begin{equation}
q_3 \leq 0.038 \cdot \left(\frac 1 4 + \frac 1 4 (1-p_{\mathrm{s}}(0))^2 + \frac 1 4 (1 + (1-p_{\mathrm{s}}(0)) + (1-p_{\mathrm{s}}(0))^2)\right) \stackrel{\text{Claim}~\ref{cl:binary_calculations}}< 0.0285.
\label{eq:q-third_case}
\end{equation}

Finally, bounds~\eqref{eq:q-first_case},~\eqref{eq:q-second_case},~and~\eqref{eq:q-third_case} conclude the proof Lemma~\ref{lm:binary_upper}:
\begin{itemize}
\item if $\xi_0(v_i)=1$ and $\xi_0(v_{i+2})=1$, then $k_+=2$, $k_-=0$, and 
$$
\mathbb{P}^*(\mathcal{E}_1(P))<0.0117+q_3\leq 0.0117 + 0.0055<0.02=2p_+=q(i)
$$ 
due to~\eqref{eq:q-first_case};
\item if $\xi_0(v_i)=-1$ and $\xi_0(v_{i+2})=-1$, then $k_+=0$, $k_-=2$, and 
$$
\mathbb{P}^*(\mathcal{E}_1(P))<0.0117+q_3\leq 0.0117 + 0.0903<0.1026=2p_-=q(i)
$$ 
due to~\eqref{eq:q-second_case};  
\item if $\xi_0(v_i)\neq\xi_0(v_{i+2})$, then $k_+=k_-=1$, and 
$$
\mathbb{P}^*(\mathcal{E}_1(P))<0.0117+q_3\leq 0.0117 + 0.0285 = 0.0402< 2\sqrt{p_-p_+}=q(i)
$$ 
due to~\eqref{eq:q-third_case}.
\end{itemize}


