\begin{lemma}

There exists $c_->0$ such that for any even $k>2$, any $R$-rooted perfect $k$-ary tree $T$ of height $h$, and uniformly random $\xi_0\in\{-1,1\}^{V(T)}$, whp there is at least one not $\lfloor c_- \cdot \sqrt{h \ln{k}}/k\rfloor$-stationary vertex.
\label{lm:k_ary_lower}   
\end{lemma}

\begin{proof}
Let $d$ be the smallest even number bigger than $\lfloor c_- \cdot \sqrt{h \ln{k}}/k\rfloor + 2$. We will choose the value of the constant $c_-$ at the end of the proof. 

Let $R^* \in V(T)$ be at distance $d$
from a leaf, define $T^* := T_{R^*}$. First, we will define a class $\mathcal{F}$ of functions $\xi_0^*: V(T^*) \rightarrow \{-1, 1\}$ such that for each initial opinion $\xi_0^*$ on $V(T^*)$ from $\mathcal{F}$ there exists not $(d-3)$-stable for every extension of $\xi_0^*$ to the entire $V(T)$. Secondly, we will show that this class is so large that whp, for a uniformly random $\xi_0\in\{-1,1\}^{V(T)}$, there exists $R^*$ as above so that $\xi_0|_{V(T^*)}\in\mathcal{F}$  leading to the fact that % for at least one vertex $v \in V(T)$ at distance $d-1$ from leaves $\xi_0|_{T_v} \in \mathcal{F}$. So, 
$\tau\geq$ $d-2$ whp. The latter immediately implies the statement of Lemma~\ref{lm:k_ary_lower} due to the definition of $d$.

\paragraph{Definition of the desired set $\mathcal{F}$.}

The following requirements on $\xi_0^*$ define the set $\mathcal{F}$. There exists a path $v_2v_3\ldots v_{d}$ with $v_d := R^*$ such that for any extension $\xi_0$ to the entire $V(T)$

\begin{itemize}

\item[A1] for every even $t\in[d]$, $\xi_0(v_t) = 1$ holds;

\item[A2] for every $t \in \{3, \ldots, d\}$, all children of $v_t$, other than $v_{t-1}$, are $(\leq t-1)$-stable;

\item[A3] for every $t \in \{3, \ldots, d-1\}$, the number of children $u$ of $v_t$ such that $\xi_{t-1}(u) = -1$ and $u\neq v_{t-1}$ equals $k/2$;

\item[A4] for every child $u$ of $v_d$, other than $v_{d-1}$, $\xi_{d-1}(u) = 1$ holds;

\item[A5] all grandchildren of $v_2$ are leaves with initial opinion $-1$.

\end{itemize}

Let $\xi_0^*\in\mathcal{F}$ and let $\xi_0$ be an extension of $\xi_0^*$ to the entire $V(T)$.
Let us show that the vertex $v_{d-1}$ is not $(d-3)$-stable w.r.t. $\xi_0$. In order to prove that, it is sufficient to show that for every $s \in \{2, \ldots d-1\}$ 
\begin{itemize}
    \item $\xi_s(v_s) = -1$;
    \item $\xi_{s}(v_{i}) = 1$, for every $i \in [d]\setminus[s]$ with the same parity as $s$.
\end{itemize}
Let us prove the latter statement by induction. First, by A2 and A4, $v_d$ has at least $k - 1$ children with opinion $1$ at every odd time step less than $d$. So, $\xi_0(v_d) = \xi_2(v_d) = \ldots = \xi_d(v_d) = 1$. Next, let us note that all children of $v_2$ have opinion $-1$ at time $1$, so $\xi_2(v_2) = -1$.
We will further rely on the following fact: For every time step $t \in [d-1]$ and every $i \in \{\max\{t,3\}, \ldots, d-1\}$ with the same parity as $t$, 
\begin{equation}
\text{
$\xi_t(v_i)=-1$ if and only if either $\xi_{t-1}(v_{i-1}) = -1$ or $\xi_{t-1}(v_{i+1}) = -1$.
}
\label{eq:fact}
\end{equation}
Indeed, (1) by A2, for every neighbour $u$ of $v_i$ other than $v_{i-1}$ and $v_{i+1}$, $\xi_{i-1}(u) = \xi_{t-1}(u)$, and (2) by A3, for exactly $k/2$ neighbours $u$ of $v_i$ other than $v_{i-1}$ and $v_{i+1}$, $\xi_{i-1}(u) = -1$. So, from (1) and (2) we conclude that, for exactly $k/2$ neighbours $u$ of $v_i$ other than $v_{i-1}$ and $v_{i+1}$, $\xi_{t-1}(u) = -1$, implying~\eqref{eq:fact}. 

Now, let us derive both the base of induction ($s=2$) and the induction step from~\eqref{eq:fact}. To prove the base, let us first apply~\eqref{eq:fact} with $t = 1$ and every odd $i \in \{3, \ldots, d-1\}$. Due to A1,  $\xi_0(v_{i-1}) = \xi_0(v_{i+1}) = 1$,  hence $\xi_1(v_i) = 1$. This allows us to apply~\eqref{eq:fact} with $t = 2$ and every even $i \in \{3, \ldots, d-1\}$ and get $\xi_2(v_i) = 1$, concluding the base of induction (we already showed $\xi_2(v_2) = -1$ and $\xi_2(v_d) = 1$). Finally, for the induction step, we assume that $s \in \{3, \ldots, d-1\}$ and that for smaller time steps the statement is true. We apply~\eqref{eq:fact} with $t = s$ and $i = s$ and get $\xi_{s}(v_s) = -1$, since $\xi_{s-1}(v_{s-1}) = -1$. Eventually, we observe that from the induction assumption it follows that $\xi_{s-1}(v_i)=1$ for all $i\in\{s+1,\ldots,d\}$ with the same parity as $s-1$. Thus we may
apply~\eqref{eq:fact} with $t = s$ and every $i \in \{t+2, \ldots, d-1\}$ with the same parity as $t$ and get $\xi_{s}(v_{i}) = 1$. Recalling $\xi_s(v_d)=1$ whenever $s$ is even, we complete the induction step. %, as $\xi_{s-1}(v_j)=1$ for all $j\in\{s+1,\ldots,d\}$ with the same parity as $s-1$ $%(v_{s+1}) = \xi_{s-1}(v_{s+3}) = \ldots = \xi_{s-1}(v_{d - ((s+1) \bmod 2)})$.

\paragraph{The existence of $R^*$.}

First, let us note that probabilities of the events A1 and A5 are $2^{-d/2}$ and $2^{-k^2}$ respectively. Next, let $U$ be the set of all children of vertices from the path $v_3\ldots v_d$, excluding the vertices of the path and $v_2$. 
%a set of all vertices $u$ that there exists $i \in \{3, \ldots, d\}$ such that $v_i$ is a parent of $u$ and $u$ is not $v_{i-1}$.
 Next, let $I: U \rightarrow \{2, \ldots , d-1\}$ be such that
$$
I(u) = i-1 \quad\text{ if and only if }\quad v_i \text{ is the parent of } u.
$$
Next, consider an arbitrary function $O: U \rightarrow \{-1, 1\}$ such that
\begin{itemize}
    \item $O(u) = 1$ for every $u$ with $I(u) = d-1$;
    \item for every $i \in \{2, \ldots, d-2\}$, the number of vertices $u \in U$ with $I(u) = i$ and $O(u) = -1$ equals $k/2$.
\end{itemize}
Note that such a function exists, since, for every $i \in \{2, \ldots, d-2\}$, the number of vertices $u \in U$ with $I(u) = i$ equals $k-1 > k/2$.

We note that A2, A3, and A4 follow immediately if every vertex $u\in U$ is $(\leq I(u))$-stable and has $\xi_{I(u)}(u) = O(u)$. Next, let us note, that events $\{u \text{ is } (\leq I(u))\text{-stable and } \xi_{I(u)}(u) = O(u)\}$ are independent over $u\in U$ since these events depend only on vectors of initial opinions $\xi_0|_{V(T_u)}$. Therefore, the events A1, A5, and $\{u \text{ is } (\leq I(u))\text{-stable and } \xi_{I(u)}(u) = O(u)\}$, $u \in U$, are independent, as they are defined by initial opinions on disjoint sets of vertices. Therefore, 
$$
\mathbb{P}(\xi_0^* \in \mathcal{F}) \geq 2^{-d/2 - k^2} \prod_{u \in U} \mathbb{P}\biggl(u \text{ is } (\leq I(u))\text{-stable and } \xi_{I(u)}(u) = O(u)\biggr).
$$
Due to Claim~\ref{cl:stable_until_probability},
$$
\mathbb{P}\biggl(u \text{ is } (\leq I(u))\text{-stable and } \xi_{I(u)}(u) = O(u)\biggr) \geq 2^{-CkI(u)}
$$
for every $u\in U$. Thus, we conclude
\begin{equation}
\mathbb{P}(\xi_0^* \in \mathcal{F}) \geq 2^{-d/2 - k^2} \prod_{u \in U} 2^{-CkI(u)} = 2^{-d/2 - k^2} \prod_{i\in\{2, \ldots, d-1\}} (2^{-Cki})^{k-1} \geq 2^{-(C+2)d^2k^2}.
%2^{-d/2 - k^2} \prod_{i\in[d-1]} (2^{-Cki})^{k-1}.
 \label{eq:sec_general_k_pre_final}
 \end{equation}
%The latter equals $2^{-d/2 - k^2 - Ck(k-1)d(d-1)/2} \geq 2^{-(C+2)d^2k^2}$.
