\section{Exel-Laca algebras and the generalized countable Markov shifts} \label{sec:Exel_Laca_GCMS}

Consider the alphabet $\mathbb{N}$ and a transition matrix $A = (A(i,j))_{(i,j)\in \mathbb{N}^2}$, with $A(i,j) \in \{0,1\}$. The (standard) \textit{countable Markov shift} is the set $\Sigma_A=\{x=(x_i)_{i \in\mathbb{N}_0} \in \mathbb{N}^{\mathbb{N}_0}: A(x_i,x_{i+1})=1 \ \text{for all} \ i\in\mathbb{N}_0\}$, where $\mathbb{N}_0 = \mathbb{N}\cup\{0\}$, equipped with the topology given by the metric $d(x,y) = 2^{-\min\{n\in\mathbb{N}_0:x_n\neq y_n\}}$ for $x\neq y$, and zero otherwise. Given a \textit{finite word} $\gamma \in \mathbb{N}^n$, $n \in \mathbb{N}$, $|\gamma| = n$ denotes its length, and its respective cylinder set is
$[\gamma] := \{x\in\Sigma_A : x_i=\gamma_i \text{ for all } 0 \leq i < n\}$. We say that $\gamma$ is \textit{admissible} when its respective cylinder is non-empty, and we recall that the topology generated by $d$ is the same one generated by the collection of the cylinder sets, which forms a basis of clopen sets. The dynamics is given by the \emph{shift map} $\sigma: \Sigma_A \to \Sigma_A$, defined by $\sigma(x)_i = x_{i+1}, \forall \ i \in \mathbb{N}_0$. In this paper, every matrix $A$ is \textit{irreducible}, that is, given $(i,j) \in \mathbb{N}^2$ there exists $\gamma = x_0 x_1 ... x_{n-1}$ admissible such that $x_0=i$ and $x_{n-1}=j$. Then, we have $[i]\neq \emptyset \ \forall \ i \in \mathbb{N}$, and the shift map is always topologically \textit{transitive}, which means that given $(i,j) \in \mathbb{N}^2$ there exists $N=N(i,j) \in \mathbb{N}$ such that $[i]\cap \sigma^{-N}([j]) \neq \emptyset$, we will also say that $\Sigma_A$ is transitive.

In the finite alphabet case, Markov shifts are intrinsically connected to their respective Cuntz-Krieger algebras $\mathcal{O}_A$ \cite{CK1980}, for instance, $\mathcal{O}_A$ contains a commutative C$^*$-subalgebra $\mathcal{D}_A$ whose Gelfand spectrum is homeomorphic to $\Sigma_A$, and hence $\mathcal{D}_A$ is isometrically $*$-isomorphic to $C(\Sigma_A)$. For a finite alphabet, $\Sigma_A$ is compact. However, it is well known that for infinite countable alphabets we have the following: $\Sigma_A$ is locally compact if and only if $A$ is row-finite, and the aforementioned C$^*$-subalgebra is isometrically $*$-isomorphic to $C_0(\Sigma_A)$. For infinite countable alphabet, the generalization of the Cuntz-Krieger algebras beyond row-finiteness is the Exel-Laca algebra \cite{EL1999}, which also contains the analog object to $\mathcal{D}_A$, which we keep the same notation as the compact case, also a commutative C$^*$-subalgebra. The spectrum of $\mathcal{D}_A$ is what we call the \textit{generalized Markov shift}, denoted by $X_A$. When $\Sigma_A$ is not locally compact, the space $X_A$ plays the role of $\Sigma_A$, and we have $X_A=\Sigma_A \cup Y_A$ with $\Sigma_A$ and  $Y_A$ dense subsets of $X_A$, for details see \cite{BEFR2018,EL1999,Raszeja2020}. As in literature, we also denote the Exel-Laca algebra by $\mathcal{O}_A$.

In the present manuscript, we use a faithful representation of the Exel-Laca algebra in the algebra of bounded operators $\mathfrak{B}(\ell^2(\Sigma_A))$ to define both $\mathcal{O}_A$ and $\mathcal{D}_A$ as it follows (for details, see \cite{BEFR2018}).

\begin{definition} Let $\Sigma_A$ be a transitive Markov shift. For each $s \in \mathbb{N}$, we consider the partial isometry $T_s \in \mathfrak{B}(\ell^2(\Sigma_A))$, and its adjoint $T_s^*$, given by
\begin{equation*}
    T_s(\delta_\omega)=\begin{cases}
        \delta_{s\omega},& \text{if }\omega \in \sigma([s]),\\
        0,& \text{otherwise};\\
    \end{cases} \quad \text{and} \quad
    T_s^*(\delta_\omega)=\begin{cases}
        \delta_{\sigma(\omega)},& \text{if }\omega\in[s],\\
        0,& \text{otherwise};\\
    \end{cases}
\end{equation*}
where $\{\delta_\omega\}_{\omega\in\Sigma_A}$ is the canonical basis of $\ell^2(\Sigma_A)$. In addition, we define the projections $P_s=T_sT_s^*$ and $Q_i=T_s^*T_s$.
\begin{equation*}
    P_s(\delta_\omega)=\begin{cases}
                            \delta_\omega \text{ if } \omega \in [s], \\
                            0 \text{ otherwise;} 
                        \end{cases}  \text{and} \quad
    Q_s(\delta_\omega)=\begin{cases}
                        \delta_\omega \text{ if } \omega \in \sigma([s]),\\
                            0 \text{ otherwise.}
                        \end{cases}
\end{equation*}
\end{definition}


\begin{definition} Let $A$ be irreducible. The \emph{Exel-Laca algebra} $\mathcal{O}_A$ is the C$^*$-algebra generated by the set $\{T_s: s\in \mathbb{N}\}$, and the \emph{unital Exel-Laca algebra} $\widetilde{\mathcal{O}}_A$ is C$^*$-algebra generated by $\{T_s: s\in \mathbb{N}\}\cup\{1\}$.
\end{definition}

\begin{remark}\label{rmk:properties_O_A} If $\mathcal{O}_A$ is unital, then $\mathcal{O}_A \simeq \widetilde{\mathcal{O}}_A$, otherwise $\widetilde{\mathcal{O}}_A$ is the canonical unitization of $\mathcal{O}_A$. In addition, the following are well-known properties of the operators $T_s$, $s \in \mathbb{N}$, \cite{EL1999}:
    \begin{enumerate}
        \item $T_s^*T_t=0$ and $P_sP_t=0$ if $s\neq t$;
        \item $Q_s$ and $Q_t$ commute for every $s,t$;
        \item $Q_sT_t=A(s,t)T_t$ and $T_t^*Q_s=A(s,t)T_t^*$;
    \end{enumerate}
\end{remark}

An alternative way of defining the Exel-Laca algebra in terms of the closure of the span of a family of generators of a vector space can be found in \cite[Proposition 13]{BEFR2022}, where we consider the free group $\mathbb{F}_\mathbb{N}$ generated by the alphabet $\mathbb{N}$, and the partial group representation
\begin{align*}
    T:\mathbb{F}_\mathbb{N} &\to \widetilde{\mathcal{O}}_A,\\
    s &\mapsto T_s, \\
    s^{-1} &\mapsto T_{s^{-1}}:= T_s^*,
\end{align*}
$T_e = 1$, where $e$ is the identity, and 
\begin{equation*}
    g \mapsto T_g:= T_{x_1} \cdots T_{x_n},
\end{equation*}
for every $g=x_1\dots x_n \in \mathbb{F}_\mathbb{N}$ in its reduced form. The positive cone $\mathbb{F}^+_\mathbb{N} \subseteq \mathbb{F}_\mathbb{N}$ is the unital subsemigroup of \emph{positive words} of the group, that is, the set of elements whose reduced forms do not contain inverses of elements of $\mathbb{N}$, and we use the notion of admissible word in $\mathbb{F}^+_\mathbb{N}$. In particular, $e$ is admissible. Here, we briefly do similar construction but focused on the C$^*$-subalgebra $\mathcal{D}_A \subseteq \mathcal{O}_A$, whose Gelfand spectrum is the generalized Markov shift.


\begin{definition}\label{I_A} Let be $A$ a transition matrix, and denote by $\mathbb{P}_F(\mathbb{N})$ the collection of finite subsets of $\mathbb{N}$. We define the set $I_A$ of $\emph{admissible pairs}$ by
\begin{equation*}
    I_A := \left\{(\beta,F) \in \mathbb{F}^+_\mathbb{N} \times \mathbb{P}_F(\mathbb{N}): \beta \text{ is admissible}, \text{ and } \beta \neq e \text{ or } F \neq \varnothing\right\}.
\end{equation*}
\end{definition}

\begin{lemma}\label{lemma propiedades de los operadores T, P y Q}
    Let $\gamma$ and $\gamma'$ be admissible words with length $n$ and $m$ respectively. We have the following properties:
    \begin{enumerate}
        \item if $n=m$, $T_\gamma^* T_{\gamma'}=\begin{cases}
            Q_{\gamma_{n-1}}, & \text{ if }\gamma=\gamma',\\
            0, & \text{ otherwise; }
                    \end{cases}$
        \item if $n>m$, $T_\gamma^* T_{\gamma'}=\begin{cases}
            T_x^*, & \text{ if }\gamma=\gamma'x,\\
            0, & \text{ otherwise; }
                    \end{cases}$
        \item if $n<m$, $T_\gamma^* T_{\gamma'}=\begin{cases}
            T_x, & \text{ if }\gamma x=\gamma',\\
            0, & \text{ otherwise; }
                    \end{cases}$
    \end{enumerate}
    where $x \in \mathbb{F}_\mathbb{N}^+$ is an admissible word.
\end{lemma}
\begin{proof} We prove (1) only, since (2) and (3) have similar proofs. We have 
    \begin{align*}
        T_\gamma^* T_{\gamma'}&=T_{\gamma_{n-1}}^*\cdots T_{\gamma_0}^*T_{\gamma'_0}\cdots T_{\gamma'_{n-1}}=T_{\gamma_{n-1}}^*\cdots T_{\gamma_1}^*\delta_{\gamma_0,\gamma'_0}Q_{\gamma_0}T_{\gamma'_1}\cdots T_{\gamma'_{n-1}} \\
        &\stackrel{\dagger}{=}T_{\gamma_{n-1}}^*\cdots T_{\gamma_2}^*A(\gamma_0,\gamma_1)\delta_{\gamma_0,\gamma'_0}T_{\gamma_1}^*T_{\gamma'_1}T_{\gamma'_2}\cdots T_{\gamma'_{n-1}} = \delta_{\gamma_0,\gamma'_0}\cdots \delta_{\gamma_{n-1},\gamma'_{n-1}}Q_{\gamma_{n-1}},
    \end{align*}
    where in $\delta_{a,b}$ is the Kronecker delta, and in $\dagger$ we used Remark \ref{rmk:properties_O_A} (3). Thus, $T_\gamma^* T_{\gamma'}=Q_{\gamma_{n-1}}$ if and only if $\gamma=\gamma'$. \newline
    \begin{comment}
        (2) Similarly to the previous case, we obtain 
    \begin{align*}
        T_\gamma^* T_{\gamma'}&=T_{\gamma_{n-1}}^*\cdots T_{\gamma_{m}}^*T_{\gamma_{m-1}}^*\cdots T_{\gamma_0}^*T_{\gamma'_0}\cdots T_{\gamma'_{m-1}}
        =\delta_{\gamma_0,\gamma'_0}\cdots \delta_{\gamma_{nm-1},\gamma'_{m-1}}T_{\gamma_{n-1}}^*\cdots T_{\gamma_{m}}^*.
    \end{align*}
    Hence, $T_\gamma^* T_{\gamma'}=T_x^*$ if $\gamma=\gamma'x$, and zero otherwise. \newline
    (3) It is analogous to the previous case.
    \end{comment}
\end{proof}

\begin{definition}\label{def:generators_D_A_indexed_by_pairs} Let be $A$ an irreducible transition matrix. We define $\mathcal{D}_A := \overline{\spann \, \mathcal{G}_A} \subseteq \mathcal{O}_A$, where
\begin{equation*}
    \mathcal{G}_A:=\left\{e_{\gamma,F} \in \mathfrak{B}(\ell^2(\Sigma_A)) : (\gamma,F) \in I_A\right\}
\end{equation*}
and $e_{\gamma,F} = T_\gamma \left(\prod_{j \in F}Q_j\right)T_\gamma^*$.
\end{definition}

\begin{remark}\label{Rem:How_act_operator_e_gamma,F}
Note that the operators $e_{\gamma,F} \in \mathcal{D}_A$ act on the elements $\delta_\omega$ in the following way:
    \begin{equation*}
        \begin{split}
            e_{\gamma,F}(\delta_\omega)=\begin{cases}
            \delta_\omega, & \text{ if }\omega\in[\gamma]\text{ and }A(i,\omega_{|\gamma|})=1 \text{ for all }i\in F; \\
                \,\,\,0, & \text{ otherwise.}
        \end{cases}
        \end{split}
    \end{equation*}
\end{remark}

\begin{remark}\label{rmk:trivial_terms_projections} Observe that the set of indices $I_A$ is merely used to avoid a class of trivial projections since for every pair $(\gamma,F) \in  \mathbb{F}^+_\mathbb{N} \times \mathbb{P}_F(\mathbb{N}) \setminus I_A$ we have $e_{\gamma,F} = 0 \in \mathcal{D}_A$.    
\end{remark}

\begin{proposition}\label{Proposition algebra D_A} The subspace $\mathcal{D}_A$ is a commutative C*-subalgebra of $\mathcal{O}_A$.
\end{proposition}
\begin{proof}
    We show that $\overline{\spann \, \mathcal{G}_A}$ is algebraically closed with respect to the product, the remaining algebraic properties are straightforward. Let $e_{\gamma,F}$ and $e_{\gamma',F'}$ with $|\gamma|=n$ and $|\gamma'|=m$. We have three cases to analyze:
    \begin{itemize}
        \item[$(a)$] If $n=m$, Lemma \ref{lemma propiedades de los operadores T, P y Q} (1) gives
        \begin{align*}
            e_{\gamma,F}e_{\gamma',F'}&=T_\gamma \prod_{i \in F}Q_i T_\gamma^*T_{\gamma'} \prod_{j \in F'}Q_i T_{\gamma'}^*=\delta_{(\gamma,\gamma')}T_\gamma \prod_{i \in F}Q_i Q_{\gamma_{n-1}} \prod_{j \in F'}Q_i T_{\gamma'}^* = \delta_{(\gamma,\gamma')} e_{\gamma,\widetilde{F}},
        \end{align*}
        where $\widetilde{F}=F\cup F'\cup\{\gamma_{\gamma_{n-1}}\}$.
        \item[$(b)$] If $n>m$, by lemma \ref{lemma propiedades de los operadores T, P y Q} (1) and (2), we have
        \begin{align*}
            e_{\gamma,F}e_{\gamma',F'}&=\delta_{(\gamma,\gamma' x)}T_\gamma \prod_{i \in F}Q_i \left(T^*_{x} \prod_{j \in F'}Q_i\right) T_{\gamma'}^* =\prod_{j\in F'} A(j,\gamma_m)\delta_{(\gamma,\gamma'x)}T_\gamma \prod_{i \in F}Q_i T^*_{x} T_{\gamma'}^* \\
            &=\prod_{j\in F'} A(j,\gamma_m)\delta_{(\gamma,\gamma'x)}e_{\gamma,F}.
        \end{align*}
        \item[$(c)$] If $n<m$, the proof similar to the previous case, by using Lemma \ref{lemma propiedades de los operadores T, P y Q} (1) and (3), where we obtain
        \begin{align*}
            e_{\gamma,F}e_{\gamma',F'}&=\prod_{i\in F} A(i,\gamma_m)\delta_{(\gamma x,\gamma')}e_{\gamma',F'}.
        \end{align*}
    \end{itemize}
    Hence $\overline{\spann \, \mathcal{G}_A}$ is a commutative C$^*$-subalgebra of $\mathfrak{B}(\ell^2(\Sigma_A))$, and by \cite[Proposition 13]{BEFR2018}, every element in $\mathcal{G}_A$ is contained in $\mathcal{O}_A$, and therefore $\mathcal{D}_A$ is a C$^*$-subalgebra of $\mathcal{O}_A$.
\end{proof}

