    \end{figure}
    \item[$(R4)$] given $g \in \mathbb{F}_{\mathbb{N}}$ and $k \in \mathbb{N}$ satisfying $\xi_g = \xi_{gk} = 1$, then
    \begin{equation*}
        \xi_{gj^{-1}} = 1 \iff A(j,k) = 1, \, j \in \mathbb{N}.
    \end{equation*}
