    e_{\gamma,\{j\}}&=T_{\gamma} Q_j T^*_{\gamma}=T_{\gamma} T^*_{j}T_{j} T^*_{\gamma} = T_{\gamma_0\cdots\gamma_{|\gamma|-2}} T_{j}T^*_{j}T_{j}T^*_{j} T^*_{\gamma_0\cdots\gamma_{|\gamma|-1}} =T_{\gamma_0\cdots\gamma_{|\gamma|-2}}e_{j}e_{j}T^*_{\gamma_0\cdots\gamma_{|\gamma|-1}}&\\
    &= T_{\gamma_0\cdots\gamma_{|\gamma|-2}} e_{j}T^*_{\gamma_0\cdots\gamma_{|\gamma|-1}} =T_{\gamma} T^*_{\gamma}=e_\gamma,
\end{align*}
where we used the fact that $e_j$ is a projection. In the second possibility, we use the fact that $e_\gamma T_{\gamma}=T_{\gamma}$ to obtain the following:
\begin{align*}
    e_{\gamma,\{j\}}&=T_{\gamma} Q_j T^*_{\gamma}=T_{\gamma} T^*_{j}T_{j} T^*_{\gamma} = e_\gamma T_{\gamma} T^*_{j}T_{j} T^*_{\gamma}&\\
    &=e_\gamma T_{\gamma} T_{i^{-1}}T^*_{i^{-1}} T^*_{\gamma} = e_\gamma T_{\gamma i^{-1}} T^*_{\gamma i^{-1}}=e_\gamma e_{\gamma i^{-1}}.
\end{align*}
Now, for the inductive step, suppose that \eqref{ecuacion relacion entre e_yf e e_g}
holds for $|F|=k$, $0\leq k\leq n-1$, $n>1$. Assume that $|F|=n$. For fixed $k\in F$, one gets
\begin{align*}
    e_{\gamma,F}&=T_{\gamma} \prod_{j\in F}Q_j T^*_{\gamma}=e_{\gamma}T_{\gamma} \prod_{j\in F}Q_j T^*_{\gamma}=T_{\gamma} Q_{\gamma} \prod_{j\in F}Q_j T^*_{\gamma} = T_{\gamma} Q_k Q_{\gamma} \prod_{j\in F-\{k\}}Q_j T^*_{\gamma}&\\
    &=T_{\gamma} Q_k T^*_{\gamma} T_{\gamma}  \prod_{j\in F-\{k\}}Q_j T^*_{\gamma} = e_\gamma e_{\gamma k^{-1}}e_\gamma\prod_{\substack{j\in F-\{k\} \\ j\neq \gamma_{|\gamma|-1}}} e_{\gamma j^{-1}} = e_\gamma^2 e_{\gamma  k^{-1}}\prod_{\substack{j\in F-\{k\} \\ i\neq \gamma_{|\gamma|-1}}} e_{\gamma j^{-1}} =e_\gamma \prod_{\substack{j\in F \\ j\neq \gamma_{|\gamma|-1}}} e_{\gamma j^{-1}},
\end{align*}
where we used that the projections $e_g$, $g\in \mathbb{F}_{\mathbb{N}}$, are pairwise commuting \cite[Proposition 3.2]{EL1999}.
\end{proof}
