\begin{lemma} \label{lemma:span_U_beta_F_star_algebra} The space
\begin{equation*}
    \mathscr{B}_A = \spann \, \{\mathbbm{1}_{V_{\beta,F}}: (\beta, F) \in I_A\}
\end{equation*}
is a $*$-subalgebra of $C_0(X_A)$.    
\end{lemma}

\begin{proof} The vector space properties and the closeness of the involution are straightforward. We prove that the product is also a closed operation. Let $(\beta, F),  (\gamma, G) \in I_A$, then
\begin{align*}
    U = \mathbbm{1}_{V_{\beta,F}} \mathbbm{1}_{V_{\gamma,G}} &= \mathbbm{1}_{C_\beta \cap C_\gamma} \mathbbm{1}_{\bigcap_{j \in F}C_{\beta j^{-1}}} \mathbbm{1}_{\bigcap_{k \in G}C_{\gamma k^{-1}}},
\end{align*}
and the product above is non-zero if and only if either $\gamma \in \llbracket \beta \rrbracket$ or $\beta \in \llbracket \gamma \rrbracket$. Without loss of generality, assume $\gamma \in \llbracket \beta \rrbracket$. We have
\begin{align*}
    \mathbbm{1}_{V_{\beta,F}} \mathbbm{1}_{V_{\gamma,G}} &= \mathbbm{1}_{C_\beta} \mathbbm{1}_{\bigcap_{j \in F}C_{\beta j^{-1}}} \mathbbm{1}_{\bigcap_{k \in G}C_{\gamma k^{-1}}}.
\end{align*}
We divide the proof by cases.
\begin{itemize}
    \item[\textbf{Case (a):}] $\beta = e$. We necessarily have $\gamma = e$, and $F,G \neq \varnothing$. One gets
    \begin{align*}
        U = \mathbbm{1}_{\bigcap_{j \in F}C_{j^{-1}}} \mathbbm{1}_{\bigcap_{k \in G}C_{k^{-1}}} = \mathbbm{1}_{\bigcap_{j \in F \cup G}C_{j^{-1}}} = \mathbbm{1}_{V_{e,F \cup G}} \in \mathscr{B}_A.
    \end{align*}
    \item[\textbf{Case (b):}] $\beta \neq e$. We have
    \begin{align*}
        W := C_\beta \cap C_\gamma \cap \bigcap_{j \in F}C_{\beta j^{-1}} \cap \bigcap_{k \in G}C_{\gamma k^{-1}} = C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}} \cap \bigcap_{k \in G}C_{\gamma k^{-1}}.
\end{align*}
    \begin{itemize}
        \item[\textit{Subcase (b1)}:] $\gamma = e$. We get 
        \begin{align*}
            W &= C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}} \cap \bigcap_{k \in G} C_{k^{-1}}.
        \end{align*}
        If there exists $k \in G$ such that $A(k,\beta_0) = 0$, then $W = \varnothing$ because (R1) and (R4), and hence $U = 0$. Otherwise, i.e., $A(k,\beta_0) = 1$ for every $k \in G$, one gets $C_{\beta_0} \subseteq C_{k^{-1}}$ and hence
        \begin{align*}
            W &= C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}},
        \end{align*}
        therefore $U = \mathbbm{1}_{V_{\beta,F}} \in \mathscr{B}_A$.
        \item[\textit{Subcase (b2)}:] $\gamma \notin \{e,\beta\}$. We have $\gamma = \beta_0 \dots \beta_{|\gamma|-1}$, and so 
        \begin{align*}
            W &= C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}} \cap \bigcap_{k \in G}C_{\beta_0 \dots  \beta_{|\gamma|-1} k^{-1}}.
        \end{align*}
        Similarly to the previous case, if there exists $k \in G$ such that $A(k, \beta_{|\gamma|}) = 0$, then $W = \varnothing$. Otherwise, $C_\beta \subseteq C_{\beta_0 \dots  \beta_{|\gamma|-1} k^{-1}}$ and hence
        \begin{align*}
            W &= C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}},
        \end{align*}
        where we obtain $U = \mathbbm{1}_{V_{\beta,F}}$.
        \item[\textit{Subcase (b3)}:] $\gamma = \beta$. One gets
        \begin{align*}
            W &= C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}} \cap \bigcap_{k \in G}C_{\beta k^{-1}} = C_\beta \cap \bigcap_{j \in F \cup G}C_{\beta j^{-1}},
        \end{align*}
        and we obtain $U = \mathbbm{1}_{V_{\beta,F \cup G}}$.
    \end{itemize}
\end{itemize}
\end{proof}


\begin{proposition} Let $\mathscr{B}_A$ as in the statement of Lemma \ref{lemma:span_U_beta_F_star_algebra}. Then $\overline{\mathscr{B}_A} = C_0(X_A)$.
\end{proposition}

\begin{proof} By Lemma \ref{lemma:span_U_beta_F_star_algebra}, $\mathscr{B}_A$ is a $*$-subalgebra of $C_0(X_A)$ and hence self-adjoint. We prove the following facts:
\begin{enumerate}
    \item for every $\xi \in X_A$, there exists $f \in \mathscr{B}_A$ s.t. $f(\xi) \neq 0$;
    \item $\mathscr{B}_A$ separates points in $X_A$.
\end{enumerate}
In fact, for every $\xi \in X_A$, there exists $i \in \mathbb{N}$ satisfying $\xi_{i^{-1}}=1$, and hence $\mathbbm{1}_{V_{e, \{i\}}}(\xi) = 1$ and (1) is proved. Now, to prove (2), let $\xi^1, \xi^2 \in X_A$, $\xi^1 \neq \xi^2$. We have the following cases:
\begin{itemize}
    \item[$(2.a)$] $\xi^1, \xi^2 \in \Sigma_A$. Since $\Sigma_A$ is Hausdorff, there exist two disjoint cylinders $[\alpha^1]$ and $[\alpha^2]$, containing respectively $\xi^1$ and $\xi^2$. It is straightforward that $C_{\alpha^1} \cap C_{\alpha^2} = \varnothing$ and then
    \begin{equation*}
        \mathbbm{1}_{V_{\alpha^1, \varnothing}}(\xi^1) = 1 \neq 0 = \mathbbm{1}_{V_{\alpha^1, \varnothing}}(\xi^2);
    \end{equation*}
    \item[$(2.b)$] $\xi^1, \xi^2 \in Y_A$. If $\kappa(\xi^1) \neq \kappa(\xi^2)$, we may assume without loss of generality that $|\kappa(\xi^1)| \geq |\kappa(\xi^2)|$, and hence
    \begin{equation*}
        \mathbbm{1}_{V_{\kappa(\xi^1), \varnothing}}(\xi^1) = 1 \neq 0 = \mathbbm{1}_{V_{\kappa(\xi^1), \varnothing}}(\xi^2),
    \end{equation*}
    because in this case we have either $|\kappa(\xi^1)| > |\kappa(\xi^2)|$ or $|\kappa(\xi^1)| = |\kappa(\xi^2)|$ with at least one different symbol on the same coordinate. Now, if $\kappa(\xi^1) = \kappa(\xi^2) = \alpha$, then w.l.o.g. we may assume that there exists $i \in \mathbb{N}$, $i \neq \alpha_{|\alpha|-1}$ when $\alpha \neq e$, satisfying $\xi^{1}_{\alpha i^{-1}} = 1$ and $\xi^{2}_{\alpha i^{-1}} = 0$, and hence
    \begin{equation*}
        \mathbbm{1}_{V_{\alpha, \{i\}}}(\xi^1) = 1 \neq 0 = \mathbbm{1}_{V_{\alpha, \{i\}}}(\xi^2);
    \end{equation*}
    \item[$(2.c)$] $\xi^1 \in \Sigma_A$ and $\xi^2 \in Y_A$. Take $\alpha = \kappa(\xi^1)_0 \dots \kappa(\xi^1)_{n-1}$, $n >  |\kappa(\xi^2)|+1$. We obtain
    \begin{equation*}
        \mathbbm{1}_{V_{\alpha, \varnothing}}(\xi^1) = 1 \neq 0 = \mathbbm{1}_{V_{\alpha, \varnothing}}(\xi^2).
    \end{equation*}
\end{itemize}
Then, the assertion (2) is proved. By the Stone-Weierstrass theorem, we conclude that $\mathscr{B}_A$ is dense in $C_0(X_A)$. 
\end{proof}



\begin{lemma}\label{lemma:products_D_A} For every $(\beta,F), (\gamma, G) \in I_A$. If $\gamma \in \llbracket \beta \rrbracket$, then
    \begin{align*}
        e_{\beta,F}e_{\gamma,G} &= 
        \begin{cases}
            e_{\beta,F\cup G}, \; \text{if } \beta = \gamma; \\
            e_{\beta,F}, \; \text{if } \beta \neq \gamma \text{ and } A(k,\beta_{|\gamma|}) = 1, \; k \in G;\\
            0,\; \text{otherwise.}
        \end{cases}.
    \end{align*}
If $\beta \in \llbracket \gamma \rrbracket$, the identity above holds in analogous way by exchanging $\beta$ with $\gamma$ an $F$ with $G$. The identity above is zero if $\gamma \notin \llbracket \beta \rrbracket$ and $\beta \notin \llbracket \gamma \rrbracket$.
\end{lemma}

\begin{proof} Let $(\beta,F), (\gamma, G) \in I_A$. We have
\begin{equation*}
    e_{\beta,F}e_{\gamma,G} = T_\beta \left(\prod_{j \in F}Q_j\right)T_\beta^* T_\gamma \left(\prod_{k \in G}Q_j\right)T_\gamma^*.
\end{equation*}
Note that $T_\beta^*T_\gamma \neq 0$ if and only if either $\gamma \in \llbracket \beta \rrbracket$ or $\beta \in \llbracket \gamma \rrbracket$, and w.l.o.g. we may assume $\gamma \in \llbracket \beta \rrbracket$ because $\mathcal{D}_A$ is commutative. We divide the proof in two cases.
\begin{itemize}
    \item[\textbf{Case (a):}] $\beta = e$. We necessarily have $\gamma = e$, and $F,G \neq \varnothing$. One gets,
    \begin{equation*}
        e_{\beta,F}e_{\gamma,G} = e_{e,F}e_{e,G} = \prod_{j \in F\cup G}Q_j = e_{e,F\cup G}  =e_{\beta,F\cup G}.
    \end{equation*}
    \item[\textbf{Case (b):}] $\beta \neq e$. We divide this case into three subcases as follows.

    \begin{itemize}
        \item[\textit{Subcase (b1)}:] $\gamma = e$. We obtain
        \begin{equation*}
            e_{\beta,F}e_{\gamma,G}  = T_\beta \left(\prod_{j \in F}Q_j\right)T_\beta^*  \left(\prod_{k\in G}Q_k \right)\stackrel{\dagger}{=}  \left(\prod_{k \in G}A(k,\beta_0)\right) e_{\beta,F},
        \end{equation*}
        where in $\dagger$ we used $T_q^*Q_p = A(p,q) T_q^*$, and hence
        \begin{equation*}
            e_{\beta,F}e_{\gamma,G} = \begin{cases}
                    e_{\beta,F}, \; \text{if } A(k,\beta_0) = 1 \text{ for every } k \in G;\\
                    0, \; \text{otherwise}.
            \end{cases}
        \end{equation*}

        \item[\textit{Subcase (b2)}:] $\gamma \notin \{e,\beta\}$. We have then $\gamma = \beta_0 \dots \beta_{|\gamma|-1}$, and
        \begin{align*}
            e_{\beta,F}e_{\gamma,G} &= T_\beta \left(\prod_{j \in F}Q_j\right)T_\beta^* T_\gamma \left( \prod_{k\in G}Q_k \right) T_\gamma^* \stackrel{\dagger}{=}  \left(\prod_{k \in G}A(k,\beta_{|\gamma|})\right) e_{\beta,F}\\
            &= \begin{cases}
                    e_{\beta,F}, \; \text{if } A(k,\beta_{|\gamma|}) = 1 \text{ for every } k \in G;\\
                    0, \; \text{otherwise}.
                \end{cases}
        \end{align*}


        \item[\textit{Subcase (b3)}:] $\gamma = \beta$. One gets
        \begin{align*}
             e_{\beta,F}e_{\gamma,G} &= T_\beta \left(\prod_{j \in F}Q_j\right)T_\beta^* T_\beta \left( \prod_{k\in G}Q_k \right) T_\beta^* \stackrel{\dagger}{=}  T_\beta \left(\prod_{j \in F}Q_j\right)Q_{\beta_{|\beta|-1}} \left( \prod_{k\in G}Q_k \right) T_\beta^* \stackrel{\ddagger}{=} e_{\beta,F \cup G},
        \end{align*}
        where in $\ddagger$ we used the comutativity between projections $Q_i$ and $Q_j$, and the identity $Q_{\beta_{|\beta|-1}}T_{\beta_{|\beta|-1}}^* = T_{\beta_{|\beta|-1}}^*$.
    \end{itemize}
\end{itemize}  
\end{proof}


It is not a general fact that, given two C$^*$-algebras $\mathfrak{A}_1$ and $\mathfrak{A}_2$, and $A_i \subseteq \mathfrak{A}_i$ dense $*$-subalgebras, and a $*$-homomorphism $\pi: A_1 \to A_2$, we can extend $\pi$ to a continuous $*$-homomorphism between $\mathfrak{A}_1$
and $\mathfrak{A}_2$. A discussion where it is presented a counterexample can be found here \cite{D2018}. Next, we present here the notion of core subalgebra, which was constructed in \cite{ExelGioGon2011}, and has properties that allow us to extend continuously $*$-isomorphisms between dense $*$-subalgebras to the whole C$^*$-algebras which contain them. We use these subalgebras to explicit an $*$-isomorphism between $C_0(X_A)$ and $\mathcal{D}_A$, as a generalization to what is already known for the case of the Cuntz-Krieger algebras.


\begin{definition} Let $\mathfrak{B}$ be a $*$-algebra. A \emph{representation of} $\mathfrak{B}$ is a $*$-homomorphism $\Theta: \mathfrak{B} \to \mathfrak{B} (\mathcal{H})$ for some Hilbert space $\mathcal{H}$.
\end{definition}

\begin{definition} Let $\mathfrak{A}$ be a C$^*$-algebra. A $*$-subalgebra $\mathfrak{B} \subseteq \mathfrak{A}$ is said to be a \emph{core subalgebra} of $\mathfrak{A}$ if every representation of $\mathfrak{B}$ is continuous with respect to the norm of $\mathfrak{A}$.
\end{definition}

\begin{proposition}[Proposition 4.4 of \cite{ExelGioGon2011}]\label{prop:isomorphism_of_C_star_algebras_via_isomorphism_between_core_subalgebras} Let $\mathfrak{A}_1$, $\mathfrak{A}_2$ C$^*$-algebras. Given $\mathfrak{B}_1$ a $\mathfrak{B}_2$ dense core subalgebras of $\mathfrak{A}_1$ and $\mathfrak{A}_2$ respectively, if $\mathfrak{B}_1$ and $\mathfrak{B}_2$ are $*$-isomorphic, then $\mathfrak{A}_1$ and $\mathfrak{A}_2$ are isometrically $*$-isomorphic.
\end{proposition}

As a consequence of Proposition \ref{prop:isomorphism_of_C_star_algebras_via_isomorphism_between_core_subalgebras}, a similar result for $*$-homomorphisms also holds, and it is presented next.

\begin{proposition}\label{prop:homomorphism_of_C_star_algebras_via_homomorphism_between_core_subalgebras} Given $\mathfrak{A}_1$, $\mathfrak{A}_2$ C$^*$-algebras and $\mathfrak{B}_1 \subseteq \mathfrak{A}_1$ a dense core subalgebra. Every $*$-homomorphism $\alpha_\mathfrak{B}: \mathfrak{B}_1 \to \alpha_\mathfrak{B}(\mathfrak{B}_1) \subseteq \mathfrak{A}_2$ such that $\alpha_\mathfrak{B}(\mathfrak{B}_1)$ is a core subalgebra of $\overline{\alpha_\mathfrak{B}(\mathfrak{B}_1)}$ (norm induced by $\mathfrak{A}_2$) admits an extension $\alpha: \mathfrak{A}_1 \to \mathfrak{A}_2$ which is a (continuous) $*$-homomorphism.
\end{proposition}

\begin{proof}
    The main idea of the proof is the following. The set $I = \overline{\ker \alpha_\mathfrak{B}}$ is a closed two-sided ideal of the C$^*$-algebra $\mathfrak{A}_1$, and hence $\mathfrak{A}_1/I$ is a C$^*$-algebra. Let $q: \mathfrak{A}_1 \to \mathfrak{A}_1/I$ be the quotient map, which is a (continuous) $*$-homomorphism. We have that $\mathfrak{B}_1/I := q(\mathfrak{B}_1)$ is a dense core subalgebra of $\mathfrak{A}_1/I$. Via the choice for $I$, one can observe that $\mathfrak{B}_1/I$ is $*$-isomorphic to the (dense) core subalgebra $\alpha_\mathfrak{B}(\mathfrak{B}_1)$ of the C$^*$-algebra $\overline{\alpha_\mathfrak{B}(\mathfrak{B}_1)} \subseteq \mathfrak{A}_2$ via the $*$-isomorphism $\alpha_{\mathfrak{B}/I}:\mathfrak{B}_1/I \to \alpha_\mathfrak{B}(\mathfrak{B}_1)$, given by $\alpha_{\mathfrak{B}/I}(a + I) := \alpha_\mathfrak{B}(a)$. By Proposition \ref{prop:isomorphism_of_C_star_algebras_via_isomorphism_between_core_subalgebras}, $\alpha_{\mathfrak{B}/I}$ admits an extension $\widetilde{\alpha}_{\mathfrak{B}/I}: \mathfrak{A}_1/I \to \overline{\alpha_\mathfrak{B}(\mathfrak{B}_1)}$, and therefore one can show that the function $\alpha: \mathfrak{A}_1 \to \mathfrak{A}_2$ given by $\alpha := \widetilde{\alpha}_{\mathfrak{B}/I} \circ q$, where $q:\mathfrak{A}_1 \to \mathfrak{A}_1/I$ is the quotient map, is a $*$-homomorphism that extends $\alpha_\mathfrak{B}$. Summarizing, we proved the existence of the $*$-homomorphism $\alpha$ by constructing it in such a way that the diagram below commutes, where $i_1$, $i_2$ and $i_3$ are canonical inclusion maps.

    {\Large
    \[
        \begin{tikzcd}
            \mathfrak{A}_1 \arrow[r, "q"] \arrow[drrr, bend left = 60, "\alpha"]
            & \mathfrak{A}_1/I  \arrow[r, "\widetilde{\alpha}_{\mathfrak{B}/I}"] & \overline{\alpha(\mathfrak{B}_1)} \arrow[dr, "i_2"] & \\
            & & &  \mathfrak{A}_2\\
            \mathfrak{B}_1 \arrow[r, "q"] \arrow[uu, "i_1"] \arrow[rr, bend right, "\alpha_{\mathfrak{B}}"]
            & \mathfrak{B}_1/I  \arrow[r, "\alpha_{\mathfrak{B}/I}"] \arrow[uu, "i_3"] & \alpha(\mathfrak{B}_1) \arrow[uu, "i_2"]  \arrow[ur, "i_2"] &
        \end{tikzcd}
    \]}
