        {\Large
    \[
        \begin{tikzcd}
            \mathfrak{A}_1 \arrow[r, "q"] \arrow[rrr, bend left, "\alpha"]
            & \mathfrak{A}_1/I  \arrow[r, "\widetilde{\alpha}_{\mathfrak{B}/I}"] & \overline{\alpha(\mathfrak{B}_1)} \arrow[r, "i_2"] & \mathfrak{A}_2 \\
            \mathfrak{B}_1 \arrow[r, "q"] \arrow[u, "i_1"] \arrow[rrr, bend right, "\alpha_{\mathfrak{B}}"]
            & \mathfrak{B}_1/I  \arrow[r, "\alpha_{\mathfrak{B}/I}"] \arrow[u, "i_3"] & \alpha(\mathfrak{B}_1) \arrow[r, "i_2"] \arrow[u, "i_2"] & \mathfrak{B}_2 \arrow[u, "i_2"]
