\end{proof}


\begin{lemma}[Lemma 3.11 of \cite{BoaCasGonWyk2023}] \label{lemma:commutative_star_algebra_generated_by_projections_is_core} A commutative $*$-algebra generated by projections of a C$^*$-algebra $\mathfrak{A}$ is a core subalgebra of $\mathfrak{A}$.    
\end{lemma}

Given an irreducible matrix $A$, it holds by definition that its respective generalized Markov shift space $X_A$ is the spectrum of the commutative C$^*$-algebra $\mathcal{D}_A$, and hence the Gelfand representation theorem for commutative C$^*$-algebras gives $\mathcal{D}_A \simeq C_0(X_A)$. The next result presents an explicit construction of the $*$-isomorphism between them, by using the generalized cylinder sets, as a similar construction of the one involving the standard cylinders for Cuntz-Krieger algebras (see for instance \cite{KessStadStrat2007}).

\begin{theorem}[Gelfand isomorphism]\label{thm:isomorphism_C_0_X_A_and_D_A} The map $\widetilde{\pi}: \mathscr{B}_A \to \spann \, \mathcal{G}_A$, defined as the linear extension of the rule
    \begin{equation}\label{eq:rule_representation_C_0_X_A}
        \mathbbm{1}_{V_{\beta, F}} \mapsto e_{\beta,F},
    \end{equation}
    is a $*$-isomorphism. Moreover, it extends uniquely to a $*$-isomorphism $\pi: C_0(X_A) \to \mathcal{D}_A$.
\end{theorem}


\begin{proof} First, observe that the rule \eqref{eq:rule_representation_C_0_X_A} is well-defined as a function. In fact, let $(\beta,F), (\gamma, G) \in I_A$ such that $e_{\beta,F} \neq e_{\gamma,G}$, then w.l.o.g. there exists $\omega \in \Sigma_A$ satisfying $e_{\beta,F} \delta_{\omega} = \delta_{\omega}$ and $e_{\gamma,G} \delta_{\omega} = 0$. So, by definition of these operators, we have for $\beta$ admissible and $j \in F$ that
\begin{equation*}
    \Sigma_A \cap C_{\beta j^{-1}} = \bigsqcup_{k: A(j,k)=1} [\beta k] = [\beta] \cap \bigsqcup_{k: A(j,k)=1} \sigma^{-|\beta|}([k]) = [\beta] \cap \sigma^{-|\beta|}(\sigma([j])),
\end{equation*}
and similarly to $\gamma$ and $j \in G$, hence
\begin{equation*}
    \omega \in [\beta] \cap \bigcap_{j \in F}\sigma^{-|\beta|}(\sigma([j])) \quad \text{and} \quad \omega \notin [\gamma] \cap \bigcap_{k \in G}\sigma^{-|\gamma|}(\sigma([k])).
\end{equation*}
Then, $\omega \in  C_\beta \cap \bigcap_{j \in F}C_{\beta j^{-1}}$, and since $\omega \in \Sigma_A$ and
\begin{equation*}
    [\gamma] \cap \bigcap_{k \in G}\sigma^{-|\gamma|}(\sigma([k])) = \Sigma_A \cap C_\gamma \cap \bigcap_{k \in G}C_{\gamma k^{-1}},
\end{equation*}
one gets $\omega \notin C_\gamma \cap \bigcap_{k \in G}C_{\gamma k^{-1}}$. Therefore, $\mathbbm{1}_{V_{\beta, F}} (\omega) = 1$ and $\mathbbm{1}_{V_{\gamma,G}} (\omega) = 0$,
that is, $\mathbbm{1}_{V_{\beta, F}} \neq \mathbbm{1}_{V_{\gamma,G}}$, and the map \eqref{eq:rule_representation_C_0_X_A} is well-defined. Now we prove this map is a bijection. Indeed, it is straightforward that it is surjective, so it remains to prove its injection. Suppose that $e_{\beta,F} = e_{\gamma,G}$. Hence,
\begin{equation}\label{eq:intersection_cylinder_sigma_cylinder_equality}
    [\beta] \cap \bigcap_{j \in F}\sigma^{-|\beta|}(\sigma([j])) = [\gamma] \cap \bigcap_{k \in G}\sigma^{-|\gamma|}(\sigma([k])).
\end{equation}
Observe that
\begin{align}\label{eq:identity_V_gamma_F_on_Sigma_A}
    [\beta] \cap \bigcap_{j \in F}\sigma^{-|\beta|}(\sigma([j])) &= \bigcap_{j \in F} \bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1 }} [\beta p]  =  \bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1, \\ \forall j \in F }} [\beta p],
\end{align}
where in the case $\beta = e$ we set $[ep] = [p]$, and an analogous result is obtained for the RHS of \eqref{eq:intersection_cylinder_sigma_cylinder_equality}, we get
\begin{equation*}
    \bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1, \\ \forall j \in F }} [\beta p] = \bigsqcup_{\substack{q \in \mathbb{N} \\ A(k,q) = 1, \\ \forall k \in G }} [\gamma q].
\end{equation*}
By taking the closure (topology of $X_A$) in both sides above and using $[\alpha] = C_\alpha \cap \Sigma_A$, and hence $\overline{[\alpha]} = C_\alpha$, for every positive word $\alpha$, we obtain as a consequence of Proposition 61 in \cite{BEFR2018} that
\begin{equation*}
    C_\beta \cap \bigcap_{j \in F} C_{\beta j^{-1}} = \overline{\bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1, \\ \forall j \in F }} C_{\beta p}} = \overline{\bigsqcup_{\substack{q \in \mathbb{N} \\ A(k,q) = 1, \\ \forall k \in G }} C_{\gamma q}} = C_\gamma \cap \bigcap_{k \in G} C_{\gamma k^{-1}},
\end{equation*}
\begin{comment}
\begin{equation*}
    G(\beta,F) \sqcup  \bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1, \\ \forall j \in F }} C_{\beta p} = \overline{\bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1, \\ \forall j \in F }} C_{\beta p}} = \overline{\bigsqcup_{\substack{q \in \mathbb{N} \\ A(k,q) = 1, \\ \forall k \in G }} C_{\gamma q}} = G(\gamma,G) \sqcup \bigsqcup_{\substack{q \in \mathbb{N} \\ A(k,q) = 1, \\ \forall k \in G }} C_{\gamma q},
\end{equation*}
\end{comment}
%where $G(\beta,F) = \{\xi \in X_A : \kappa(\xi) = \beta, \xi_{\beta j^{-1}} = 1, \forall j \in F\}$, and similarly for $G(\gamma,G). Note that
\begin{comment}
    \begin{equation*}
    G(\beta,F) \sqcup  \bigsqcup_{\substack{p \in \mathbb{N} \\ A(j,p) = 1, \\ \forall j \in F }} C_{\beta p} = C_\beta \cap \bigcap_{j \in F} C_{\beta j^{-1}} = C_\beta \cap \bigcap_{j \in F} C_{\beta j^{-1}},
\end{equation*}
and similar formula above holds also holds for $\gamma$ and $G$.
\end{comment}
 Then, $V_{\beta,F} = V_{\gamma,G}$, that is,
\begin{equation*}
    \mathbbm{1}_{V_{\beta,F}} = \mathbbm{1}_{V_{\gamma,G}}
\end{equation*}
and the injectivity of \eqref{eq:rule_representation_C_0_X_A} is proved. By each case and subcase of Lemma \ref{lemma:span_U_beta_F_star_algebra} to its respective case and subcase in Lemma \ref{lemma:products_D_A}, we have that $\widetilde{\pi}$ preserves the product, and it is straightforward that the involution is also preserved, so we conclude that $\widetilde{\pi}$ is a $*$-isomorphism between $*$-algebras. It remains to prove that it can be extended to a $*$-isomorphism between $C_0(X_A)$ and $\mathcal{D}_A$. Indeed, it is straightforward from the case \textbf{(a)} and subcase \textit{(b3)} in the proof of Lemma \ref{lemma:span_U_beta_F_star_algebra} that $\mathscr{B}_A$ is generated by projections. Analogously, the contents of the proof of Lemma \ref{lemma:products_D_A} show that the elements $e_{\beta,F}$ are projections as well. Hence, by Lemma \ref{lemma:commutative_star_algebra_generated_by_projections_is_core}, both $\mathscr{B}_A$ and $\spann \, \mathcal{G}_A$ are dense core subalgebras of $C_0(X_A)$ and $\mathcal{D}_A$ respectively, we conclude by the proof of Proposition \ref{prop:isomorphism_of_C_star_algebras_via_isomorphism_between_core_subalgebras} in \cite{ExelGioGon2011} that $\widetilde{\pi}$ can be extended to an isometric $*$-isomorphism $\pi: C_0(X_A) \to \mathcal{D}_A$.
\end{proof}

\begin{remark} In \cite{BoaCasGonWyk2023}, G. Boava, G. G. de Castro, D. Gon\c{c}alves, and D. W. van Wyk constructed a notion of C$^*$-algebra $\widetilde{\mathcal{O}}_X$ associated to a subshifts. In particular, they proved in Proposition 3.13 a similar result of the theorem above for the Ott-Tomforde-Willis (OTW) subshifts $X^{OTW}$ \cite{OttTomfordeWillis2014}. Although there are some cases where $X^{OTW}$ and $X_A$ may coincide, this is not general. In particular, if $X_A$ has two distinct elements $\xi^1,\xi^2 \in Y_A$ with same stem and different roots, its respective OTW-subshift contains only one element $x$ which is a finite sequence and coincides with the stem of $\xi^1$ and $\xi^2$. This occurs, for instance, when $A$ is the pair renewal shift transition matrix and finite words ending in $1$.
\end{remark}


Given a commutative C$^*$-algebra $\mathfrak{A}$, its Gelfand spectrum, denoted by $\widehat{\mathfrak{A}}$, and $a \in \mathfrak{A}$, we denote by $\widehat{a} \in C_0(\widehat{ \mathfrak{A}})$ the Gelfand transformation of $a$, that is, $\widehat{a}(\eta) = \eta(a)$, $\eta \in \widehat{\mathfrak{A}}$.

\begin{remark}\label{rmk:Gelfand_transform_D_A} Note that, for every $\omega \in \Sigma_A$ and $(\gamma,F) \in I_A$, we have by \eqref{eq:inclusion_Sigma_A_in_X_A} that, when $\gamma\neq e$,
\begin{equation*}
    \widehat{e_{\gamma, F}}(\varphi_{\omega}) = \varphi_{\omega}(e_{\gamma, F}) = \left\langle e_{\gamma, F}\delta_\omega, \delta_\omega\right\rangle  = \begin{cases}
        1, \, \text{if } \omega \in [\gamma] \cap \bigcap_{j \in F}\sigma^{-|\gamma|}(\sigma([j])),\\
        0, \, \text{otherwise,}
      \end{cases}
\end{equation*}
and in the case that $\gamma=e$,
\begin{equation*}
    \widehat{e_{e, F}}(\varphi_{\omega}) = \varphi_{\omega}(e_{e, F}) = \left\langle e_{e, F}\delta_\omega, \delta_\omega\right\rangle  = \begin{cases}
        1, \, \text{if } \omega \in \bigcap_{j \in F}\sigma([j]),\\
        0, \, \text{otherwise.}
      \end{cases}
\end{equation*}
Then, by \eqref{eq:identity_V_gamma_F_on_Sigma_A} and the continuity of the characters, we conclude that
\begin{equation}\label{eq:evaluating_e_on_varphi_omega_via_characteristic_functions}
    \widehat{e_{\gamma, F}} = \mathbbm{1}_{V_{\gamma,F}}.
\end{equation}
In other words, $\pi^{-1}$ is the Gelfand transform.
\end{remark}

The identity \eqref{eq:evaluating_e_on_varphi_omega_via_characteristic_functions} is very useful and will be applied several times in this work.

\section{Weighted endomorphisms} \label{sec:weighted_endomorphisms}\\

In this section we briefly present the notion of weighted endomorphism and its partial dual map, as it was studied by B. K. Kwa\'sniewski and A. Lebedev \cite{KwaLeb2020} and some of their results. These notions are our central object of study in this paper, in the context of generalized Markov shifts. We present a function $\alpha_0:\mathcal{G}_A \to \mathfrak{B}(\ell^2(\Sigma_A))$ that can be extended to a $*$-endomorphism of $C_0(X_A)$ whose partial map dual to it is the continuous extension shift map to $X_A$ precisely when this one exists. In general, the shift map is defined on the open subset of non-empty words, and it does not have a continuous extension on the whole space.
% Also, we present a class of examples, namely \emph{periodic renewal class}, where we have such an extension.

In order to briefly explain the notion of weighted endomorphism, we start from a proposition that we present next. It connects endomorphisms on commutative Banach algebras and dynamics partially defined on the algebra's spectrum, in the sense that with the domain of the dynamical map is a clopen subset of the spectrum. Such a result was proved by B. K. Kwa\'sniewski and A. V. Lebedev.

\begin{proposition}[{\cite[Proposition 1.1.]{KwaLeb2020}}]\label{proposicion partial map en A}
    Let endomorphisms be $\alpha:\mathfrak{A}\to \mathfrak{A}$ of a commutative Banach algebra $\mathfrak{A}$ with a unit. There is a uniquely determined partial continuous map $\varphi: \Delta \to X$ on algebra's spectrum $X$ defined on a clopen subset $\Delta\subseteq X$  such that
    \begin{equation}\label{ecuacion partial map dual de alpha A}
        \widehat{\alpha(a)}(x)=
        \left\{ \begin{array}{lcc}
             \widehat{a}(\varphi(x)), & x\in\Delta, \\
             0, & x\notin\Delta,
             \end{array}
   \right. \quad  a\in \mathfrak{A}.
    \end{equation}
    Moreover, $\Delta=X$ iff $\alpha$ preserves the unit of $\mathfrak{A}$.
\end{proposition}  

The result above establishes a notion of dynamical duality between the algebraic and analytic counterparts of the objects, algebra and topological space, of Proposition \ref{proposicion partial map en A}, which motivates the following definition. 

\begin{definition}\label{definicion partial map primero}
    We call the map $\varphi: \Delta \subseteq X \to X$ satisfying \eqref{ecuacion partial map dual de alpha A} the \textit{partial dynamics dual to the endomorphism} $\alpha$. In the global case, i.e., when $\Delta = X$, we refer to $\varphi: X \to X$ as the \textit{dynamics dual to the endomorphism} $\alpha$.






\end{definition}

We emphasize that under certain conditions, from a shift operator, we can obtain an endomorphism that can be expressed in terms of the operator (see Proposition \ref{Corollary alpha definida como T.S es un endomorfismo}). On the other hand, given a contractive endomorphism, we can construct a shift operator while maintaining the relationship (see Proposition \ref{proposicion creacion de los aT a partir del endomorfismo}).


\begin{definition}
Let $T$ be an operator on a Banach space $E$ and $\mathfrak{B}(E)$ the algebra of bounded operators on $E$.  We say that $T$ is a \emph{partial isometry} if it is a contraction and there is a contraction $S \in \mathfrak{B}(E)$ such that
\[ TST = T, \quad STS = S. \]
Contraction operators $T$ and $S$ satisfying the above relations are called \emph{mutually adjoint partial isometries}. For a subset $M\subseteq\mathfrak{B}(E)$ we denote by $M'$ its commutant, that is $M'=\{a\in\mathfrak{B}(E):ba=ab \text{ for each }b\in M\}$.
\end{definition}

\begin{proposition}[{\cite[Proposition 2.9. and Corollary 2.10.]{KwaLeb2020}}]\label{Corollary alpha definida como T.S es un endomorfismo}
Let $\mathfrak{A} \subseteq \mathfrak{B}(E)$ be an algebra, and $T$ and $S$ be mutually adjoint partial isometries such that
\[
T\mathfrak{A}S \subseteq \mathfrak{A}, \quad ST \in \mathfrak{A}'.
\]
Then the map $\alpha: \mathfrak{A} \to \mathfrak{A}$, defined as $\alpha(a):=TaS$ for every $a\in \mathfrak{A}$, is an endomorphism of $\mathfrak{A}$.
\end{proposition}

\begin{definition}
Let $E$ be a Banach space. Suppose that $\mathfrak{A} \subseteq \mathfrak{B}(E)$ is a unital algebra containing the same unit of $\mathfrak{B}(E)$, and let $T \in \mathfrak{B}(E)$ be a partial isometry which admits an adjoint partial isometry $S$ satisfying
\[
T\mathfrak{A}S \subseteq \mathfrak{A}, \quad ST \in \mathfrak{A}'.
\]
So that $\alpha: \mathfrak{A} \to \mathfrak{A}$ given by $\alpha(a):= TaS$, $a \in \mathfrak{A}$, is an endomorphism of $\mathfrak{A}$. We call operators of the form $aT$, $a \in \mathfrak{A}$, \emph{weighted shift operators} associated with the endomorphism $\alpha$.
\end{definition}
\begin{proposition}[{\cite[Proposition 2.17.]{KwaLeb2020}}]\label{proposicion creacion de los aT a partir del endomorfismo}
Let $\mathfrak{A}$ be a unital Banach algebra and $\alpha: \mathfrak{A} \to \mathfrak{A}$ be a contractive endomorphism. Then there is a Banach space $E$, a unital isometric homomorphism $\Upsilon : \mathfrak{A} \to \mathfrak{B}(E)$, and mutually adjoint partial isometries $S, T \in \mathfrak{B}(E)$ such that $\Upsilon(\alpha(a)) = T\Upsilon(a)S$ for $a \in \mathfrak{A}$ and $ST \in \Upsilon(\mathfrak{A})'$. Thus, for each $a \in \mathfrak{A}$, the operator $\Upsilon(a)T$ is an abstract weighted shift associated with the endomorphism (isometrically conjugated with) $\alpha$.
\end{proposition}

Next, we present a function $\alpha_0$ on the generators of $\mathcal{D}_A$ which, under appropriate circumstances, can be extended to an $*$-endomorphism on $\mathcal{D}_A$.

