In Section 6 of \cite{KwaLeb2020}, it was shown that in the case of a compact (standard) Markov shift $\Sigma_A$, when we consider the C$^*$-algebra $C(\Sigma_A)$, the $*$-endomorphism $\Psi :C(\Sigma_A) \to C(\Sigma_A)$ whose corresponding dual map is the shift dynamics consists of the rule $\Psi(f) = f \circ \sigma$, for every $f$ complex function on $\Sigma_A$. In a similar fashion, the same happens here when $\alpha$ extends $\alpha_0$ to a $*$-endomorphism on $\mathcal{D}_A$, or equivalently, via Theorem \ref{Theorem: alpha well-defined iff sigma extended}, when $\sigma$ can be continuously extended to the whole space $X_A$. This is realized via the Gelfand transformation $\pi^{-1}$ from Theorem \ref{thm:isomorphism_C_0_X_A_and_D_A}. The maps $\alpha$ and $\pi$ create another (unique) $*$-endomorphism $\Theta : C_0(X_A) \to C_0(X_A)$ which makes the diagram
\[
\begin{tikzcd}
\mathcal{D}_A \arrow[r, "\alpha"] 
& \mathcal{D}_A  \arrow[d, "\pi^{-1}"] \\
C_0(X_A) \arrow[u, "\pi"] \arrow[r, "\Theta"]
& C_0(X_A)
\end{tikzcd}
\]
commutes, that is, $\Theta = \pi^{-1} \circ \alpha \circ \pi$.

\begin{theorem}\label{Theorem:shift_dual_is_theta} Suppose that $\sigma$ is continuously extended to $X_A$. Then $\Theta(f) = f \circ \sigma$ for every $f \in C(X_A)$.    
\end{theorem}

\begin{proof} The proof that $(3)$ implies $(1)$ in Theorem \ref{Theorem: alpha well-defined iff sigma extended} shows that $\widehat{\alpha_0(e_{\gamma, F})}=\widehat{e_{\gamma, F}}\circ\sigma$ for every $(\gamma, F) \in I_A$. Then,
\begin{align*}
    \Theta(\mathbbm{1}_{V_{\gamma,F}}) &= \pi^{-1} \circ \alpha \circ \pi(\mathbbm{1}_{V_{\gamma,F}}) = \pi^{-1} \circ \alpha (e_{\gamma, F}) = \widehat{\alpha(e_{\gamma, F})} = \widehat{e_{\gamma, F}}\circ\sigma = \mathbbm{1}_{V_{\gamma,F}}\circ\sigma = \Phi_\sigma(\mathbbm{1}_{V_{\gamma,F}}),
\end{align*}
where $\Phi_\sigma$ is the $*$-endomorphism $\Phi_\sigma:  C(X_A) \to  C(X_A)$, $\Phi_\sigma(f) :=  f\circ \sigma$, $f \in  C(X_A)$. Since $\Phi_\sigma$ and $\Theta$ coincide in the same dense $*$-subalgebra $\spann \{\mathbbm{1}_{V_{\gamma,F}}: (\gamma,F) \in I_A\} \subseteq C(X_A)$, we conclude that they coincide, that is, $\Theta(f) = f \circ \sigma$ for every $f \in C(X_A)$. 
\end{proof}





