\begin{proposition}\label{thm:E_A_shift_invariant} Suppose that $A$ is irreducible and column-finite, and $X_A$ is compact. If the shift dynamics is extended continuously to the whole $X_A$, then $E_A$ an invariant set in the sense that $\sigma(E_A) \subseteq E_A$.
\end{proposition} 

\begin{proof} By Lemma \ref{lemma:exploding_first_coordinate_implies_limit_points_in_E_A}, if a sequence in $\Sigma_A \subseteq X_A\setminus E_A$ converges to an element $\xi \in E_A$, then $\kappa(\xi^n)_0 \to \infty$. Since $A$ is column finite, we have $\kappa(\xi^n)_1 \to \infty$. If the dynamics is a well-defined continuous function on $X_A$, we have $\kappa(\sigma(\xi^n))_0 = \kappa(\xi^n)_1$, and therefore $\sigma(\xi) \in E_A$.
\end{proof}


\begin{definition}\label{def:Single_Empty_Word_Class} A generalized countable Markov shift $X_A$ belongs to the \emph{single empty-word class} when the following holds:
\begin{itemize}
    \item[$(i)$] $A$ is irreducible and column-finite;
    \item[$(ii)$] $X_A$ is compact;
    \item[$(iii)$] $E_A$ is a singleton.
\end{itemize}
\end{definition}

Examples of single empty-word generalized countable Markov shifts are the renewal (Example \ref{exa:renewal_shift}) and lazy renewal (Example \ref{exa:lazy_renewal_shift}).

