    \caption{Typical matrix of a generalized Markov shift space that belongs to the periodic renewal class.\label{fig:Periodic_Renewal_Matrix_Class}}
\end{figure}


\begin{proposition}\label{prop:PRC_properties} For a matrices $A$ and $M$ as in Definition \ref{def:Periodic_Renewal_Class}, we always have the following:
\begin{enumerate}
    \item $M$ has not zero columns;
    \item $|E_A| = m \leq n_e <\infty$;
    \item $A$ is column-finite.
\end{enumerate}
\end{proposition}
\begin{proof} In fact, the compactness of $X_A$ implies that $\mathcal{D}_A$ is unital, and so is $\mathcal{O}_A$. By Proposition 8.5 of \cite{EL1999}, the vector zero cannot be a limit point of the sequence of columns of $A$ (product topology in $\{0,1\}^\mathbb{N}$), and since $\lim_{k \to \infty}(A(n,k))_{k \in \mathbb{N}} = 0$ for every $n > n_e$, we necessarily have that $(1)$ holds. On the other hand, Proposition 46 of \cite{BEFR2018} gives a bijection between the elements of $E_A$ and the non-zero limit points of the columns of $A$, and since the columns of $M$ are distinct each other, by Definition \ref{def:Periodic_Renewal_Class}, there are exactly $m$ limit points in $(A(\cdot,k))_{k \in \mathbb{N}}$, namely, the vectors consisting in a column of $M$ for the rows $1 \leq k \leq n_e$ and zero in the remaining entries. We conclude that $|E_A| = m$. Since for every limit of the columns of $A$ the entries that are $1$ correspond to rows whose the symbols are infinite emitters, we have that there is at least one infinite emitter for each non-zero limit of $(A(\cdot,k))_{k \in \mathbb{N}}$. We conclude that $(2)$ holds. Assertion $(3)$ is straightforward.    
\end{proof}

For the next lemma and theorem, for $X_A$ in the periodic renewal class with the matrix $M$ as in Definition \ref{def:Periodic_Renewal_Class}, $R_k$ will denote the $k$-th column of $M$, $1 \leq k \leq m$. We commit an abuse of notation by denoting the limit point of $A$ by $R_k$ being the vector that coincides with the $k$-th column of $M$ in the entries from 1 to $n_e$, and zero in the remaining entries.

\begin{lemma}\label{lemma:PRC_convergence_classes} Let $X_A$ be a generalized Markov shift space in the periodic renewal class. A sequence $(\xi^n)_{n \in \mathbb{N}}$ in $X_A\setminus E_A$ converges to $(e, R_p)$, $1 \leq p \leq m$, if and only if it eventually satisfies
\begin{equation}\label{eq:PRC_sequences}
    \kappa(\xi^n)_0 = (I + k_n m + p),
\end{equation}
where $(k_n)_{\mathbb{N}}$ is a sequence of natural numbers s.t. $\lim_n k_n = \infty$, and $I$ and $m$ are given as in Definition \ref{def:Periodic_Renewal_Class}.
\end{lemma}

\begin{proof} Supose that $\xi_n \to (e, R_p)$. By Proposition \ref{prop:PRC_properties}, there are exactly $m$ non-zero limit points of the columns of $A$, and hence for large enough $n$ we have $A(i,\kappa(\xi_n)_0) = (R_p)_i$, $1 \leq i \leq m$. Since the columns of $M$ are pairwise disjoint, we have that $\kappa(\xi_n)_0 = (I + k_n m + p)$, for some $k_n \in \mathbb{N}$, and $\lim_n k_n = \infty$ because compactness of $X_A$ and Lemma \ref{lemma:exploding_first_coordinate_implies_limit_points_in_E_A}. Conversely, suppose that \eqref{eq:PRC_sequences} holds for $(\xi^n)_{n \in \mathbb{N}}$. Then, for large enough $n$, $A(\cdot,\kappa(\xi^n)_0) = R_p$, and since $\kappa(\xi^n)_0 \to \infty$, we have that $\xi^n \to (e,R_p)$.
\end{proof}

\begin{remark}\label{rmk:renewal_decaying} By Definition \ref{def:Periodic_Renewal_Class} $(iii)$, the sequence $(\xi^n)_{n \in \mathbb{N}}$ in Lemma \ref{lemma:PRC_convergence_classes} has stem larger than $1$ and $\kappa(\xi^n)_1 = (I + k_n m + p - 1)$ for large enough $n$. 
\end{remark}

\begin{theorem}\label{thm:PRC_continuous_extension_dynamics} For $X_A$ a generalized Markov shift space in the periodic renewal class, the extension of $\sigma$ to $X_A$ given by
\begin{equation}\label{eq:PRC_continuous_extension_dynamics}
    \sigma((e,R_{p+1})) = (e,R_p) \; \text{ and } \; \sigma((e,R_1)) = (e,R_m)
\end{equation}
is continuous.
\end{theorem}

\begin{proof} Let $(\xi^n)_{n \in \mathbb{N}}$ be a sequence converging to $(e,R_{p+1})$. Without loss of generality, we may assume that the sequence does not contain terms that equals to $(e,R_{p+1})$. By Lemma \ref{lemma:PRC_convergence_classes} and Remark \ref{rmk:renewal_decaying} the first two terms of the stem of $\xi^n$ are given by
\begin{equation}\label{eq:exploding_sequence_to_R_p_plus_1}
    \kappa(\xi^n)_{0} = (I + k_n m + p + 1) \; \text{ and } \; \kappa(\xi^n)_{1} = (I + k_n m + p),
\end{equation}
for large enough $n$, and hence $\kappa(\sigma (\xi^n))_0 = \sigma(\kappa(\xi^n))_0 = \kappa(\xi^n)_{1}$, and again by Lemma \ref{lemma:PRC_convergence_classes} $\sigma(\xi^n) \to (e, R_p)$. The case $\xi^n \to (e,R_1)$ is proved similarly. We conclude that $\sigma$ is continuous.
\end{proof}

For understanding purposes, we illustrate the proof of Theorem \ref{thm:PRC_continuous_extension_dynamics}. For simplicity, take $k_n = n-1$ in \eqref{eq:exploding_sequence_to_R_p_plus_1}, and observe that the elements of the root of $\sigma(\xi^n)$ are precisely those that correspond to the entries $1$ in the column $j=I + p + (n-1)m$ of $A$. When we take the limit $n \to \infty$ for $\sigma(\xi^n)$, its root is precisely the limit of the columns of $A$ mentioned above, as shown in Figure~\ref{fig:Periodic_Renewal_Matrix_Class}, corresponding to the limit point corresponding to the column vector whose entries $1$ are the elements of $R_p$ (observe that the sequence of columns is constant inside the submatrices M). We conclude that the limit corresponds to the element $\lim_n \sigma(\xi^n) = (e, R_p)$.

