\section{Spectral Radius on renewal shift}\label{sec:Spectral Radios on renewal}


In the previous section, we showed that the existence of a weighted endomorphism $\alpha$ on $C(X_A)$ whose dual partial map is the shift map $\sigma$ is inherent to the existence of a continuous extension of $\sigma$ to the entire generalized shift space $X_A$. In particular, we presented examples of transition matrices which have such a continuous extension of the shift dynamics. Now, we study the spectral radius of $a\alpha$, $a\in A$, by applying the following theorem by Kwa\'sniewski and Lebedev, as stated below.




    \begin{proposition}[{\cite[Proposition 2.18.]{KwaLeb2020}}]\label{calculo radio espectral del aT y aalpha}
Suppose that $aT$, $a \in A$, is an abstract weighted shift operator and $\alpha: A \to A$ is the associated endomorphism. Then, for the spectral radius $r(aT)$ of the operator $aT$, we have
\[
r(aT) = r(a\alpha) = \lim_{n \to \infty} \left\|  \alpha(a)\alpha^2(a)\cdots\alpha^n(a) \right\|^{\frac{1}{n}}.
\]
Here, $r(a\alpha)$ is the spectral radius of the weighted endomorphism $a\alpha: A \to A$, treated as an element of $\mathfrak{B}(A)$. In particular, $r(aT) = r(\alpha^k(a)T) = r(\alpha^k(a)\alpha)$ for every $k \in \mathbb{N}$.
\end{proposition}




    \begin{theorem}[{\cite[Theorem 3.5.]{KwaLeb2020}}](Variational principle for $\limsup$ of empirical averages)\label{Variational principle for limsup of empirical averages}. 
Let $(X, \varphi)$ be a partial dynamical system and let $f: \Delta \to \mathbb{R}$ be a continuous and bounded from the above function where $\Delta$ is the domain of $\varphi$ (an open subset of $X$). We define the corresponding empirical averages to be functions $S_n(f) : \Delta_n \to \mathbb{R}$, $n > 0$, given by
\[
S_n(f)(x) = \frac{1}{n}(f(x) + f(\varphi(x)) + \ldots + f(\varphi^{n-1}(x))), \quad x \in \Delta_n.
\]
Then
\[
\lim_{n \to \infty} \sup_{x \in \Delta_n} S_n(f)(x) = \max_{\mu \in \text{Inv}(\Delta_\infty,\varphi)} \int_{\Delta_\infty} f \,d\mu = \max_{\mu \in \text{Erg}(\Delta_\infty,\varphi)} \int_{\Delta_\infty} f \,d\mu,
\]
if $\text{Erg}(\Delta_\infty, \varphi) \neq \emptyset$, and $\lim_{n \to \infty} \sup_{x \in \Delta_n} S_n(f)(x) = -\infty$ otherwise.

\end{theorem}



\begin{theorem}[{\cite[Theorem 5.1]{KwaLeb2020}}]\label{Teorema Formula radio espectral con algebra general A old version}
Let $\alpha: A \rightarrow A$ be an endomorphism of a unital commutative  C$^*$-algebra $A$. Let $(X, \varphi)$ be the partial dynamical system dual to $(A, \alpha)$ and let $\Delta_\infty\subseteq X$ be the set \textcolor{red}{in which the dynamic $(\Delta_\infty, \sigma)$ is defined and surjective everywhere}. Then, for any $a \in A$, the spectral radius of the weighted endomorphism $a\alpha : A \rightarrow A$ is given by
\begin{equation}
r(a\alpha) = \max_{\mu \in \text{Inv}(\Delta_\infty, \varphi)} \exp  \int_{\Delta_\infty} \ln |\hat{a}(x)| \, d\mu = \max_{\mu \in \text{Erg}(\Delta_\infty, \varphi)} \exp  \int_{\Delta_\infty} \ln |\hat{a}(x)| \, d\mu,
\end{equation}
where $\ln(0) = -\infty$, $\exp(-\infty) = 0$, and $r(a\alpha) = 0$ if $\Delta_{\infty} = \emptyset$. For a fixed $a \in A$, the set $\Delta_{\infty}$ above can be replaced by the essential domain of $\varphi : \{x \in \Delta : a(x) \neq 0\} \rightarrow X$.
\end{theorem}

In particular, Section 6 of \cite{KwaLeb2020} shows an explicit formula for the spectral radius on compact standard Markov shifts, i.e., when the alphabet is finite. Our main result is a step in the direction of generalizing their formula for the infinite alphabet case, where our central example is the generalized renewal shift, see Examples \ref{exa:renewal_shift} and \ref{exa:renewal_shift_2}.

Now, we present a proof of the continuity of the map $A \ni a \mapsto r(a \alpha) \in [0, \infty)$, which is true in general for weighted endomorphisms, and it will be used later in this section.


\begin{proposition}\label{Proposicion continuidad del radio espectral old version} Under the assumptions and notations of Theorem \ref{Teorema Formula radio espectral con algebra general A}, the map $A \ni a \mapsto r(a \alpha) \in [0, \infty)$ is continuous.
\end{proposition}

\begin{proof}
    To reduce writing, consider the following notation $J(a,\mu)=\int_{\Delta_\infty}\ln |\widehat{a}(x)| \, d\mu$, for $a\in A$ and $\mu$ a probability measure. Let $(a_n)_n$ be a sequence in $A$ that converges to $a$. For each $n \in \mathbb{N}$, let $\mu_n \in \text{Inv}(\Delta_\infty, \varphi)$ be a measure such that 
    \begin{equation*}
        r(a_n \alpha) = \max_{\mu \in \text{Inv}(\Delta_\infty, \varphi)} \exp J(a_n,\mu) = \exp J(a_n,\mu_n).
    \end{equation*}
    Since the space $\text{Inv}(\Delta_\infty, \varphi)$ is compact, let $\nu \in \text{Inv}(\Delta_\infty, \varphi)$ such that $\mu_{n_i} \to \nu$, where $\{\mu_{n_i}\}_i$ is a subsequence of $\{\mu_{n}\}_n$. By the inequality
    \begin{align*}
        \left|J(a_{n_i},\mu_{n_i}) - J(a,\nu)\right| 
        &\leq \left|J(a_{n_i},\mu_{n_i})-J(a,\mu_{n_i})\right| + \left|J(a,\mu_{n_i})-J(a,\nu)\right|,
    \end{align*}
    and using the continuity of the logarithmic and exponential functions along with the convergence of $a_{n_i}$ to $a$ and $\mu_{n_i}$ to $\nu$, we can conclude that
    \begin{equation*}
        \lim_{i \to \infty} r(a_{n_i} \alpha) = \exp J(a,\nu).
    \end{equation*}

    Let any $\{a_{n_j}\}_j$ be a subsequence of $\{a_{n}\}_n$ such that $\mu_{n_j}\to\nu'$, for some $\nu' \in \text{Inv}(\Delta_\infty, \varphi)$. We observe that
    \begin{equation}\label{equation: nu maximiza de la proposition radio continuo old version}
        J(a_{n_i},\nu') \leq J(a_{n_i},\mu_{n_i}) \to J(a,\nu), \quad \text{for all } n \in \mathbb{N},
    \end{equation}
    which implies $J(a,\nu')\leq J(a,\nu)$. Analogously, we obtain an inverse inequality and $J(a,\nu)= J(a,\nu')$. We have shown that any convergent subsequence of $\{r(a_n\alpha)\}_n$ has the same limit. Since $\{r(a_n\alpha)\}_n$ is a bounded sequence of real numbers, it is convergent. Taking the measure that maximizes $r(a\alpha)$ instead of $\nu'$ in the Equation \eqref{equation: nu maximiza de la proposition radio continuo old version}, we conclude that $\lim_{n\to\infty}r(a_n \alpha)=r(a \alpha)$.
\end{proof}


