Now, we will provide a formula for the spectral radius of elements in $ \operatorname{span} \mathcal{G}_A $. However, to do so, we introduce the following definitions and lemmas.



\begin{definition}
    Given $f:\Sigma_A\to\mathbb{R}\cup\{-\infty\}$ a function. We define
    \begin{equation*}
        \beta_f=\sup_{\mu\in \text{Inv}(\Sigma_A,\sigma)}\int f d\mu.
    \end{equation*}
    For $f:\Sigma_A\to\mathbb{R}$ the $j$-th variation of $f$ is 
    \begin{equation*}
        V_j(f)=\sup\{f(x)-f(y):\pi(\sigma^i(x))=\pi(\sigma^i(y)) \text{ for every }i\in\{0,1,2,\cdots,j-1\}\}.
    \end{equation*}
 We say that $f$ has summable variations when 
 \begin{equation}
     V(f)=\sum_{j=1}^{\infty} V_j(f)<\infty.
 \end{equation}

     Besides that, we say $f$ is coercive if
 \begin{equation}
     \lim_{i\to\infty} \sup f\vert_{[i]}=-\infty.
 \end{equation}

\end{definition}

\begin{remark}\label{Remark: Obtaining A_f if f is coercive and has summable variation old version}
    Theorem 1 of \cite{Bissacot2014} states that, for a coercive function $f:\Sigma_A\to \mathbb{R}$ with summable variations, there exists a subset $\mathcal{A}_f \subset \mathbb{N}$ such that
    \begin{equation*}
        \beta_f = \sup_{\mu \in \text{Inv}(\Sigma_A(\mathcal{A}_f))} \int f \, d\mu,
    \end{equation*}
    where $\Sigma_A(\mathcal{A}_f)$ is the subshift of the set of admissible sequences with respect to the matrix $A$, of finite alphabet $\mathcal{A}_f \subset \mathbb{N}$.
    To determine $\mathcal{A}_f$, we need to identify two numbers $I_2 \geq I_1 \geq 0$ that fulfill the following conditions:
    \begin{itemize}
        \item[\textbf{(C1)}] $\sup f \vert_{[j]} < \beta_f \,\, \forall j \geq I_1,$
        \item[\textbf{(C2)}] $\sup f \vert_{[j]} < C^f = \min\{C_1^f, C_2^f\} \,\, \forall j \geq I_2,$
    \end{itemize}
    where
    \begin{equation*}
        C_1^f = -(P_0 |\min f \vert_{\Sigma_A(\mathcal{A}_f')}| + (P_0 - 1)|\beta_f| + 2V(f)) 
        \quad \text{and} \quad 
        C_2^f = \beta_f - V(f).
    \end{equation*}
    Here, $\mathcal{A}_f'$ is the completion of the set $\mathcal{I}_1 = \{1, 2, \dots, I_1 - 1\}$ such that $A \vert_{\mathcal{A}_f' \times \mathcal{A}_f'}$ is irreducible, and $P_0$ is the largest length of the shortest finite words connecting any two elements of $\mathcal{I}_1$, while still being admissible words. 
    Take $\mathcal{A}_f$ as the completion of $\mathcal{I}_2 = \{1, 2, \dots, I_2 - 1\}$ such that the restriction of $A$ to $\mathcal{A}_f$ is irreducible; for more details, see Section 3 of \cite{Bissacot2014}. Note that, for any finite alphabet $\mathcal{A}_f=\mathcal{I}_i$, $i=1,2$, $A_{\mathcal{A}_f\times\mathcal{A}_f}$ is always irreducible for the renewal shift, $\mathcal{A}_f' = \mathcal{I}_1$, $\mathcal{A}_f = \mathcal{I}_2$, and $P_0 = I_1 - 1$.
\end{remark}




