    Let $f:\Sigma_A\to \mathbb{R}\cup\{-\infty\}$ be a function defined as $f=\ln(|\widehat{a}|){\vert}_{\Sigma_A}$, for some $a=\sum_{k=1}^{N_a}\lambda_ke_{\gamma^k,F_k}$ such that $\beta_f>-\infty$. Then, there exists a decreasing sequence of functions $f_n:\Sigma_A\to \mathbb{R}$, $n\in\mathbb{N}$, each with summable variations such that $f_n \searrow f$, and $\mathcal{A}_{f_n}=\mathcal{A}$, for every $n\in\mathbb{N}$. Moreover, 
    \begin{equation*}
        \beta_f=\max_{\mu\in\text{Inv}(\Sigma_A(\mathcal{A}),\sigma)}\int f d\mu.
    \end{equation*}
\end{lemma}
\begin{proof}
    Note that $\beta_f\in\mathbb{R}$ since $f(x)\leq \ln \sum_{k=1}^{N_a}|\lambda_k|$. Let $M=\min\{m\in\mathbb{N}: \supp \widehat{a}\subseteq \bigcup_{i=1}^m[i]\}$ be, and $L=\max_{1\leq k\leq N_a} |\gamma^k|$, the largest length among the words $\gamma^k$, $k=1,\dots,N_a$. Also, consider the sequences $\{v_n\}_n\subseteq \mathbb{R}^+$, which tends towards infinite, and  $\{a_n\}_n\subseteq\mathcal{D}_A$ defined as $v_n=L\ln (n\sum_{k=1}^{N_a}|\lambda_n|)$ and 
    $$a_n =b+ \sum_{\ell=1}^M \frac{1}{n}\mathbbm{1}_{[\ell]\cap(\supp \widehat{a})^c} +
    \sum_{\ell=M+1}^\infty  e^{C_n} \mathbbm{1}_{[\ell]}, \quad \text{for } \ n \in\mathbb{N},$$
    where $b\in\mathcal{D}_A$ such that $\widehat{b}=|\widehat{a}|$, and     $C_n=\min\{\beta_f-v_n,-(P_{0,M}\ln n+(P_{0,M}-1)\beta+2v_n)\}-1$ with $\beta=\max\{|\beta_f|,\ln(\sum_{k=1}^{N_a}|\lambda_k|)\}$ and $P_{0,M}$ is the longest length of the shortest finite words connecting any two elements of $\mathcal{A}_M$ that is the completion of the set $\{1,2,\dots, M\}$ such that $A\vert_{\mathcal{A}_M\times\mathcal{A}_M}$ is irreducible \textcolor{red}{Citar Mauldin e Urbanski}. Now, taking $f_n:\Sigma_A\to\mathbb{R}$ defined as $f_n=\ln(\widehat{a_n})\vert_{\Sigma_A}$, we can see that each one is a function with summable variation because it is a piecewise constant function. Moreover, for each $n\in\mathbb{N}$ note that $V_j(f_n)=0$ for all $j > L$ and $f_n(\omega)-f_n(\eta)=0$ for all $\omega,\eta\in[i]$ and for every $i>M$. Hence, we obtain for all $n\geq N$, for a sufficiently large $N$,
 \begin{align*}
     V(f_n)&=\sum_{j=1}^L V_j(f_n)\leq LV_1(f_n)=L \sup\{f_n(\omega)-f_n(\eta):\omega,\eta\in[i], 0<i\leq M\} &\\
     &\leq L\left(\sup\left\{f_n(\omega):\omega\in\bigcup_{i=1}^M[i])\right\}-\inf\left\{f_n(\eta):\eta\in\bigcup_{i=1}^M[i])\right\}\right)  &\\
     &= L\left(\ln\left(\sum_{k=1}^{N_a}|\lambda_k|\right)-\ln\frac{1}{n}\right)=L\ln\left(n\sum_{k=1}^{N_a}|\lambda_k|\right)=v_n.
 \end{align*}

 We aim to show that $I_2=I_1=M+1$ satisfy conditions $(C1)$ and $(C2)$ from Remark \ref{Remark: Obtaining A_f if f is coercive and has summable variation}, for each $f_n$, $n\geq N$ with $N$ sufficiently large, as we show next: 
 \begin{itemize}
    \item[(C1)] $\sup f_n \vert_{[j]}=\ln e^{C_n}=C_n<\beta_{f}\leq\beta_{f_n}, \quad \forall j\geq I_1$.

    \item[(C2)] Since we have
    $$C_n<\beta_f-v_n\leq \beta_{f_n}-V(f_n)=C_1^{f_n},$$
    and since $\beta_f\leq \beta_{f_n}\leq \ln\sum_{k=1}^{N_a}|\lambda_k|$, we obtain 
    \begin{align*}
        C_n&<-(P_{0,M}\ln n+(P_{0,M}-1)\beta+2v_n)&\\
        &\leq -(P_0|\min f_n\vert_{\Sigma_A(\mathcal{A}_f')}|+(P_0-1)|\beta_{f_n}|+2V(f_n))=C_2^{f_n},
    \end{align*} observe that $P_{0,M}=P_0$ and $\ln n=|\min f_n\vert_{\Sigma_A(\mathcal{A}_f')}|$.

    Then, $\sup f_n \vert_{[j]}\leq C^{f_n}=\min\{C^{f_n}_1,C^{f_n}_2\}, \quad \forall j\geq I_2$.
\end{itemize} 

Therefore, we have shown that $\mathcal{A}_{f_n}$ is constant for every $n\geq N$, which we shall denote by now as $\mathcal{A}$. To prove the final statement, we rely on the continuity of the spectral radius under the weighted endomorphism, see Proposition \ref{Proposicion continuidad del radio espectral}. Then,  
\begin{align*}
    \beta_f=\ln r(b\alpha)=\lim_{n\to\infty}\ln r(a_n\alpha)=\lim_{n\to\infty} \beta_f =\lim_{n\to\infty}\max_{\mu\in\text{Inv}(\Sigma_A(\mathcal{A}),\sigma)}\int f_n d\mu=\max_{\mu\in\text{Inv}(\Sigma_A(\mathcal{A}),\sigma)}\int f d\mu,
\end{align*}
By Theorem \ref{Teorema Formula radio espectral con algebra general A} we can note that $r(a\alpha)=r(b\alpha)$, and the last equality is guaranteed by the reasoning given in Proposition \ref{Proposicion continuidad del radio espectral}.
\end{proof}

