\begin{theorem}\label{Theorem formula spectrum radius of element in span D_A with finite alphabet}
    Given $a=\sum_{u \in U}\lambda_u e_u$ under the same conditions as in Proposition \ref{Proposition: formula spectrum radius of element in span D_A trasitive case} $(ii)$. Then, there exists a finite subset $\mathcal{A}\subseteq\mathbb{N}$ such that the restriction of $A$ to $\mathcal{A}$ is irreducible, and

    \begin{equation}\label{ecuacion de Ra. esp. de aalpha para a en span D_A y lambda cero con alfabeto finito}
         r(a\alpha)=\max_{\mu\in\text{Inv}(\Sigma_A(\mathcal{A}),\sigma)}\exp \int_{\Sigma_A} \ln |\widehat{a}| \, d\mu.
    \end{equation}
\end{theorem}

\begin{proof} 
Let $M=\min\{m\in\mathbb{N}: \supp \widehat{a}\cap\Sigma_A \subseteq \bigcup_{i=1}^m[i]\}$ be and let $\mathcal{A}\subseteq \mathbb{N}$ be a finite set such that $\{1,2,\dots, M\}\subseteq\mathcal{A}$ and $A_{\mathcal{A}\times\mathcal{A}}$ is irreducible. Taking the function $f:\Sigma_A\to\mathbb{R}\cup\{-\infty\}$ defined as $f=\ln|\widehat{a}|\vert_{\Sigma_A}$, we note that $f(\omega)=-\infty$ for every $\omega\in\bigcup_{i>M}[i]$. Then, if we consider $\mu \in \mathrm{Inv}(\Sigma_A, \sigma)$ such that $\mu\left(\bigcup_{i \in \mathcal{A}} [i]\right)\neq 1$, we obtain $\int_{\Sigma_A} f d\mu=-\infty$. Therefore, by Remark \ref{Remark: one-to one correspondance between small and large Markov shift} one gets
\begin{align*}
    r(a\alpha)&=\max_{\mu\in\text{Inv}(\Sigma_A,\sigma)}\exp \int_{\Sigma_A} \ln |\widehat{a}| \, d\mu &\\
    &=\max_{\substack{\mu\in\text{Inv}(\Sigma_A,\sigma) \\ \mu\left(\bigcup_{i \in \mathcal{A}} [i]\right)= 1}} \exp \int_{\Sigma_A} \ln |\widehat{a}| \, d\mu &\\
    &=\max_{\mu\in\text{Inv}(\Sigma_A(\mathcal{A}),\sigma)}\exp \int_{\Sigma_A} \ln |\widehat{a}| \, d\mu.
\end{align*}
\end{proof}

\begin{corollary}
Let $A$ be a column-finite transition matrix and suppose that $\sigma$ extends continuously to $X_A$ (and it is dual to the endomorphism $\Theta$, see Theorem \ref{Theorem:shift_dual_is_theta}). Given $f \in C(X_A)$, the spectral radius $r(f\Theta)$ satisfies
\begin{equation}\label{Equation: spectral radius of f in C(X)}
    r(f\Theta) = \max_{\mu \in \text{Inv}(\Sigma_A \cup E_A, \sigma)} \exp  \int_{\Sigma_A\cup E_A} \ln |f| \, d\mu.
\end{equation}
Moreover, if $\supp f\cap\Sigma_A$ can be expressed as a union of finitely many cylinders on which $f$ is constant on each cylinder, then there exists a finite subset $\mathcal{A} \subseteq\mathbb {N}$ such that the restriction of $A$ to $\mathcal{A}$ is irreducible and
\begin{equation}\label{Equation: spectral radius of f in C(X) constant in cylinders}
    r(f\Theta) = \max_{\mu \in \text{Inv}(\Sigma_A(\mathcal{A}), \sigma)} \exp \int_{\Sigma_A } \ln |f| \, d\mu.
\end{equation}
\end{corollary}

\begin{proof}
Let $a \in \mathcal{D}_A$ such that $\pi^{-1}(a) = \widehat{a} = f$. By Proposition \ref{Proposition: formula spectrum radius of element in span D_A trasitive case}, we obtain
\begin{align*}
    r(f\Theta) &= \lim_{n \to \infty} \|(f\Theta)^n\|_{\mathfrak{B}(C(X_A))}^{1/n} 
    = \lim_{n \to \infty} \|(f \pi^{-1} \circ \alpha \circ \pi)^n\|_{\mathfrak{B}(C(X_A))}^{1/n} \\
    &= \lim_{n \to \infty} \| \pi^{-1} \circ (a\alpha)^n \circ \pi \|_{\mathfrak{B}(C(X_A))}^{1/n} 
    = \lim_{n \to \infty} \| (a\alpha)^n \|_{\mathfrak{B}(\mathcal{D}_A)}^{1/n} \\
    &= r(a\alpha) 
    = \max_{\mu \in \text{Inv}(\Sigma_A \cup E_A, \sigma)} \exp  \int_{\Sigma_A \cup E_A} \ln |\widehat{a}| \, d\mu  \\
    &= \max_{\mu \in \text{Inv}(\Sigma_A \cup E_A, \sigma)} \exp \int_{\Sigma_A \cup E_A} \ln |f| \, d\mu .
\end{align*}
For the second statement, under the given assumptions, $a \in \operatorname{span} \mathcal{G}_A$ admits a linear combination that does not involve any terms of the form $e_{e, F}$, where $F$ has infinite common range. Consequently, by Theorem~\ref{Theorem formula spectrum radius of element in span D_A with finite alphabet}, Equation~\ref{Equation: spectral radius of f in C(X) constant in cylinders} applies.

\end{proof}





