To illustrate the results developed above, we now focus on the particular case of the renewal shift.

\begin{proposition}\label{prop:non_zero_generators_of_D_A_renewal} Let $A$ be the transition matrix of the renewal shift. The non-zero elements $e_{\gamma,F} \in \mathcal{G}_A$ are precisely those who satisfy one of the following conditions:
\begin{itemize}
    \item[$(a)$] $\gamma=e$ and $F=\{1\}$;
    \item[$(b)$] $\gamma\neq e$ and, $F=\{1\}$ or $F=\varnothing$;
    \item[$(c)$] $F=\{1,n\}$ or $F=\{n\}$, $n>1$, and $A(\gamma_{|\gamma|-1},n-1)=1$ when $\gamma \neq e$.
\end{itemize}    
\end{proposition}

\begin{proof} Let $e_{\gamma, F} \in \mathcal{G}_A$ (and hence $(\gamma, F) \in I_A$). We analyze each case of the statement as follows:
\begin{itemize}
    \item[$(a)$] it is straightforward that $e_{e,\{1\}} = Q_1 = 1$;
    \item[$(b)$] by \eqref{eq:evaluating_e_on_varphi_omega_via_characteristic_functions}, we have $\widehat{e_{\gamma,F}}(\varphi_\omega) = \mathbbm{1}_{V_{\gamma,1}}(\omega) = \mathbbm{1}_{C_\gamma} = \mathbbm{1}_{V_{\gamma,\varnothing}}(\omega)$, and hence $e_{\gamma,F}$ is non-zero since $\gamma$ is admissible; 
    \begin{comment}
        \begin{align*}
        \widehat{e_{\gamma,F}}(\varphi_\omega)&=\begin{cases}
     1, & \text{ if }\omega\in[\gamma], \\
     0, & \text{otherwise},
     \end{cases}
    \end{align*}
    \end{comment}


    \item[$(c)$] since $A$ is the transition matrix of the renewal shift, the statement for $\gamma = e$ is immediate because $Q_1 Q_n = Q_n \neq 0$. For the same reason, when $\gamma \neq e$, we necessarily have $\gamma_{|\gamma|-1}=n-2$ or $\gamma_{|\gamma|-1}=1$, where the first possibility only happens when $n>2$. In both cases, we have again by \eqref{eq:evaluating_e_on_varphi_omega_via_characteristic_functions} that $\widehat{e_{\gamma,F}}(\varphi_\omega) = \mathbbm{1}_{V_{\gamma,F}}(\omega) = \mathbbm{1}_{V_{\gamma,\{n\}}}(\omega) = \mathbbm{1}_{V_{\gamma(n-1),\varnothing}}(\omega)$. Then, $e_{\gamma,F} \neq 0$ because $\gamma(n-1)$ is an admissible word.
\end{itemize}   
Conversely, let $(\gamma,F) \in I_A$ such that does not satisfy any of the conditions in the cases above. We have only two possibilities:
\begin{itemize}
    \item[$\mathbf{i.}$] $\gamma \neq e$ and $n >1$, such that $(\gamma, F)$ satisfy the conditions of $(c)$, except that $A(\gamma_{|\gamma|-1},n-1)=0$. Then by the formulae in $(c)$, we have that $\gamma (n-1)$ is not admissible and hence $e_{\gamma,F} = 0$.

    \item[$\mathbf{ii.}$] $F$ contains two distinct elements $j, k\in\mathbb{N}\setminus\{1\}$. Then, there is no $n \in \mathbb{N}$ satisfying $A(j,m) = A(k,m) = 1$, and hence $Q_j Q_k = 0$, so by definition we have $e_{\gamma,F} = 0$.
\end{itemize}
\end{proof}


\begin{remark}\label{rmk:linearly_dependency_on_G_A} From the proof of Proposition \ref{prop:non_zero_generators_of_D_A_renewal} $(b)$ and $(c)$, we conclude that
\begin{itemize}
    \item[$(b')$] $e_{\gamma, \{1\}} = e_{\gamma, \varnothing}$ for every $\gamma \neq e$ admissible word;
    \item[$(c')$] $e_{\gamma, \{1,n\}} = e_{\gamma, \{n\}} = e_{\gamma(n-1), \varnothing}$, $n>1$ and $A(\gamma_{|\gamma|-1},n-1)=1$.
\end{itemize}
For general matrices, the elements of $\mathcal{G}_A$ are linearly dependent. In particular, for the renewal shift we have $e_{k,\varnothing} = e_{k (k-1)\dots 1, \varnothing}$ for every $k \in \mathbb{N}$.
