	\title{\bf Study of higher-order interactions in unweighted, undirected networks using persistent homology}
	%}
\author{Udit Raj$^{1}$, Slobodan Maleti\'{c}$^{2}$, Sudeepto Bhattacharya$^{1*}$}
\date{%
