%\end{equation}  }
Assuming   (\ref{ncov}) we rewrite $n_a$ in terms of $A$. Now, except for the variation with respect to $\phi$ which doesn't depend on the normal vector and giving the field equation \eqref{eqphi2}, we should vary with respect to $g_{ab}$ and $A$. 
Varying by $A$ the same way, as in \eqref{covform} we get
\begin{equation}\label{eqmA1}
    B^{an}\frac{-2 \partial_n A}{\partial_a A\partial_b A g^{ab}}+  B^{mn} \frac{2 \partial_m A \partial_n A \partial_b A g^{ab}}{(\partial_a A\partial_b A g^{ab})^2}=\frac{c^{a}}{\sqrt{-g}},
\end{equation}
where $c^{a}$ is a constant vector density and
\begin{equation}
    B^{mn} = {}^{(3)}R^{mn}(\xi \phi^2+ \eta \phi)-\frac{1}{N} (D^m D^n  -\gamma^{mn} D_c D^c )(N \xi \phi^2+ N \eta \phi),
\end{equation}where $N$ can be calculated as $\sqrt{\frac{-g}{\gamma}}$.
Varying (\ref{anothercouplag}) with respect to the metric like in subsection \ref{covform} we get
\begin{eqnarray}
\begin{array}{cccc}
      R^{a'b'}-\frac{1}{2} g^{a'b'} R+g^{a'b'} \Lambda  =\nabla^{a'} \phi \nabla^{b'} \phi - \frac{1}{2} g^{a'b'} \nabla_c \phi \nabla^c \phi - \frac{1}{2} g^{a'b'}  V(\phi)+  (\xi \phi^2+ \eta \phi) \left({}^{(3)} R^{a'b'}-\frac{1}{2} g^{a'b'} {}^{(3)} R\right)- \\-\frac{1}{N} (D^{a'} D^{b'} + \gamma^{a'b'} D_c D^c)(N\xi \phi^2+ N\eta \phi) +  \sqrt{-g}B^{mn}\frac{\partial_a A\partial_b A\partial_m A\partial_n A g^{aa'}g^{bb'}}{(\partial_a A\partial_b A g^{ab})^2}.
\end{array}
\end{eqnarray}
$  B^{mn}$ here has the same properties as in subsection \ref{covform}. So, applying the same logic to the equations, we get
\begin{equation}\label{covb01}
    B^{an}\frac{-2 \partial_n A}{\partial_a A\partial_b A g^{ab}}+  B^{mn} \frac{2 \partial_m A \partial_n A \partial_b A g^{ab}}{(\partial_a A\partial_b A g^{ab})^2}\equiv0
\end{equation}
for arbitrary $A$ and
\begin{eqnarray}
\begin{array}{cccc}
     R^{a'b'}-\frac{1}{2} g^{a'b'} R+g^{a'b'} \Lambda  =\nabla^{a'} \phi \nabla^{b'} \phi - \frac{1}{2} g^{a'b'} \nabla_c \phi \nabla^c \phi - \frac{1}{2} g^{a'b'} V(\phi)+  (\xi \phi^2+ \eta \phi) \left({}^{(3)} R^{a'b'}-\frac{1}{2} g^{a'b'} {}^{(3)} R\right)- \\-\frac{1}{N} (D^{a'} D^{b'} + \gamma^{a'b'} D_c D^c)(N\xi \phi^2+ N\eta \phi).
\end{array}
\end{eqnarray}

 The result is the following ---    in the covariant formalism the equations of motion for the metric are the same as in the usual ADM case. This means that this formalism allows us to choose any foliation, and that its equations are invariant under coordinate transformations. The fact that eq. (\ref{covb01}) is trivial  demonstrates that.



