\subsection{Lense-Thirring metric}
 The Lense-Thirring metric is an approximation of the Kerr metric in the weak-field and slow-rotation limit. We take it in the form \cite{Gray:2021roq}:
\begin{equation} \label{LTmet}
ds^2 = -f \, dt^2 + \frac{dr^2}{f} + 2a(f - 1)\sin^2\theta \, dt \, d\phi + r^2(\sin^2\theta \, d\phi^2 + d\theta^2),
\end{equation}
where $f=1-2M/r$. We take the foliation by the hypersurfaces of constant time --- static foliation.
Then the normal vector (\ref{normal}) is
\begin{equation}
   n_m= \left\{-\frac{{\sqrt{4 a^2 M^2 \sin ^2 \theta +r^3 (r-2 M)}}}{r^2},0,0,0\right\}.
\end{equation}
The induced metric (\ref{gamma}) is
\begin{equation}
    \gamma_{mn} =\left(
\begin{array}{cccc}
 \frac{2 M}{r}+\frac{(r-2 M) r^3+4 a^2 M^2 \sin ^2 \theta }{r^4}-1 & 0 & 0 & -\frac{2 a M \sin ^2 \theta }{r} \\
 0 & \frac{1}{1-\frac{2 M}{r}} & 0 & 0 \\
 0 & 0 & r^2 & 0 \\
 -\frac{2 a M \sin ^2 \theta }{r} & 0 & 0 & r^2 \sin ^2 \theta  \\
\end{array}
\right).
\end{equation}
The extrinsic curvature (\ref{Kab}) $K_{mn}$ is
\begin{equation}
    \begin{array}{cccc}
      K_{0 1} =K_{1 0} = -\frac{6 a^2 M^2 \sin ^2 \theta  }{r^3\sqrt{{4 a^2 M^2 \sin ^2 \theta -2 M r^3+r^4}}};

\\

K_{1 3} = K_{3 1} =  \frac{3 a M \sin ^2 \theta }{\sqrt{4 a^2 M^2 \sin ^2 \theta -2 M r^3+r^4}}.
    \end{array}
\end{equation}
The 3-curvature (\ref{R3}) calculated with (\ref{3Ricci}) is zero.
The field equations (\ref{fieldeq}) are satisfied in the linear order of $M$ and $a$ for every $\lambda$ including the case $\lambda=-1$ in \eqref{laglam} or $\phi=-\frac{\eta}{2\xi}$ and $\frac{\eta^2}{4\xi}=-1$ in \eqref{anothercouplag}. Hence, the Lense-Thirring solution is a solution for the theories (\ref{laglam}), (\ref{lagReq}) and (\ref{anothercouplag}) in a weak field limit. 
\section{Newman-Janis algorithm }\label{sec:njalg}\setcounter{equation}{0}
In this section, we apply the modified Newman-Janis algorithm developed in \cite{Chaturvedi:2023ctn} to obtain the rotating black hole for theories (\ref{laglam}) and (\ref{anothercouplag}). % The reason is that other attempts to obtain solutions that satisfy the constraint equation have been unsuccessful.
\subsection{Obtaining the metric}
According to \cite{Chaturvedi:2023ctn,Drake:1998gf}, the algorithm contains five steps. First, writing the Schwarzschild
metric (\ref{BHmet}), considered as a static spherically symmetric seed metric, in advanced
Eddington-Finkelstein coordinates $(u,r,\theta,\phi)$ (i.e., the $g_{rr}$ component is eliminated by a change
of coordinates and a cross-term is introduced):
\begin{equation} \label{seedmet}
    ds^2=-(1-\frac{2M}{r})du^2 - 2dudr + r^2 (d\theta^2 + \sin^2 \theta d\phi^2),
\end{equation}
where 
\begin{equation}
    du = dt - \frac{dr}{1-2M/r}.
\end{equation}
The second step of the algorithm involves expressing
the contravariant form of the seed metric (\ref{seedmet}) in terms of a
null tetrad, $e^m_a=(l^m, n^m, m^m, \bar{m}^m)$
 as:
\begin{equation}\label{defmetnj}
    g_{mn}=-l^m n^n-l^n n^m+m^m \bar{m}^n+m^n \bar{m}^m,
\end{equation}
where
\begin{equation}
    l_m l^m =  n_m n^m= m_m m^m = l_m m^m= n_m m^m=0,~~~ l_m n^m =- m_m \bar{m}^m=-1
\end{equation}
with $ \bar{m}_m$ being the complex conjugate of the $m_m$.
For the Schwarzschild spacetime (\ref{seedmet}), the \textit{null tetrad vectors} \( (l^{m}, n^{m}, m^{m}, \bar{m}^{m}) \) are
\begin{equation}
    \begin{array}{cccc}
         l^{m} = \delta^{m}_{1}, \\
         n^{m} = \delta^{m}_{0} - \frac{1}{2} \left( 1 - \frac{2M}{r} \right) \delta^{m}_{1}, \\
       m^{m} = \frac{1}{\sqrt{2} r} \left( \delta^{m}_{2} + \frac{i}{\sin \vartheta} \delta^{m}_{3} \right),  \\
    \bar{m}^{m} = \frac{1}{\sqrt{2} r} \left( \delta^{m}_{2} - \frac{i}{\sin \vartheta} \delta^{m}_{3} \right).
    \end{array}
\end{equation}
The third step, let the coordinate \( r \) take complex values so the complex conjugate of \( r \) appears
\begin{equation}
    \begin{array}{cccc}
        l^{m} = \delta^{m}_{1} , \\
        n^{m} = \delta^{m}_{0} - \frac{1}{2} \left( 1 - M \left[ \frac{1}{r} + \frac{1}{\bar{r}} \right] \right) \delta^{m}_{1},\\
        m^{m} = \frac{1}{\sqrt{2} r} \left( \delta^{m}_{2} + \frac{i}{\sin \vartheta} \delta^{m}_{3} \right),\\
        \bar{m}^{m} = \frac{1}{\sqrt{2} \bar{r}} \left( \delta^{m}_{2} - \frac{i}{\sin \vartheta} \delta^{m}_{3} \right).
    \end{array}
\end{equation}
Then for  the fourth step we perform the following complex coordinate transformation on
the null vectors
\begin{equation}\begin{array}{cccc}
 r'=r+i a R(\theta ),\\
    \theta'=\theta+i a P(\theta ),\\
     \phi'=\phi+i a Q(\theta ),\\
      \theta'=\theta.
      \end{array}
\end{equation}
After this transformation  the null vectors become
\begin{equation}\label{tetradaftertrans}
    \begin{array}{cccc}
        l^m=\{0,1,0,0\},\\
       n^m=\left\{1,\frac{M {r'}}{a^2 R(\theta )^2+{r'}^2}-\frac{1}{2},0,0\right\},\\
       m^m=\left\{\frac{a P'(\theta )}{\sqrt{2} (a R(\theta )-i {r'})},\frac{a R'(\theta )}{\sqrt{2} (a
   R(\theta )-i {r'})},\frac{1}{\sqrt{2} ({r'}+i a R(\theta ))},\frac{i \left(a Q'(\theta
   )+\csc \theta \right)}{\sqrt{2} ({r'}+i a R(\theta ))}\right\},\\
       \bar{m}^m=\left\{\frac{a P'(\theta )}{\sqrt{2} (a R(\theta )+i {r'})},\frac{a R'(\theta )}{\sqrt{2} (a
   R(\theta )+i {r'})},\frac{1}{\sqrt{2} ({r'}-i a R(\theta ))},-\frac{i \left(a Q'(\theta
   )+\csc \theta \right)}{\sqrt{2} ({r'}-i a R(\theta ))}\right\}.
    \end{array}
\end{equation}
Constructing the metric from (\ref{defmetnj}),(\ref{tetradaftertrans}),  and inverting the obtained metric, the nonzero components are:
\begin{equation}
\begin{array}{cccc}
   g_{00} =-\frac{a^2 R ^2+{r'} ({r'}-2 M)}{a^2 R ^2+{r'}^2} , \\ g_{03} =g_{30} =\frac{a
   \left(P'  \left(a^2 R ^2+{r'} ({r'}-2 M)\right)+R'  \left(a^2
   R ^2+{r'}^2\right)\right)}{\left(a^2 R ^2+{r'}^2\right) \left(a Q'(\theta
   )+\csc \theta \right)}, \\
g_{10} = g_{01} =-1   , \\ g_{13} = g_{31} = \frac{a P' }{a Q' +\csc \theta }, \\
  g_{22} =a^2 R ^2+{r'}^2  ,\\
 g_{33} = -\frac{-a^4 R^4+{r'} \left(a^2 ({r'}-2 M) P'(\theta)^2+2 a^2 {r'} P'(\theta) R' -{r'}^3\right)+R^2 \left(2 a^4 P' R' +a^4
  P'(\theta )^{2}-2 a^2 {r'}^2\right)}{\left(a^2 R^2+{r'}^2\right) \left(a Q' +\csc(\theta )\right)^2}.
\end{array}
\end{equation}
The fifth step is to get the  Boyer–Lindquist (BL) coordinates. For this we perform the following coordinate transformation:
\begin{equation}
    dt=du+\frac{-a^2 P'(\theta ) R'(\theta )+a^2 R(\theta )^2+{r'}^2}{a^2 R'(\theta )^2+a^2 R(\theta )^2-2 M {r'}+{r'}^2},~~
    d \phi = d \phi' -\frac{a R'(\theta
   ) \left(a Q'(\theta )+\csc \theta \right)}{a^2 R'(\theta )^2+a^2 R(\theta )^2-2 M{r'}+{r'}^2}
\end{equation}
and get the BL metric in the form
\begin{equation}\label{metnj}
\begin{array}{cccc}
 g_{00}=-\frac{a^2 R ^2+{r'} ({r'}-2 M)}{a^2 R ^2+{r'}^2}, \\ g_{03}= g_{30}=\frac{a \left(P'  \left(a^2 R ^2+{r'} ({r'}-2 M)\right)+R' 
   \left(a^2 R ^2+{r'}^2\right)\right)}{\left(a^2 R ^2+{r'}^2\right) \left(a
   Q' +\csc \theta \right)}, \\
  g_{11}= \frac{a^2 R^2+{r'^{2}}}{a^2 R^{'2}+a^2 R ^2+{r'} ({r'}-2 M)},
     \\
  g_{22}= a^2 R ^2+r'^{2},  \\
  g_{33}= -\frac{-a^4 R^4+{r'} \left(a^2
   ({r'}-2 M) P'^{2}+2 a^2 {r'} P'  R' -r'^{3}\right)+R(\theta
   )^2 \left(2 a^4 P'  R' +a^4 P'^2-2 a^2 r'^{2}\right)}{\left(a^2
   R^2+r'^{2}\right) \left(a Q' +\csc \theta \right)^2} .\\
\end{array}
\end{equation}
All other components vanish.
\subsection{Solving the field equations}
In this subsection we will solve the field equations (\ref{fieldeq}) with $\Lambda=0$ using the metric (\ref{metnj}) with $r' \goto r$.
As usual, we take the foliation defined by the hypersurfaces of constant time.
The normal vector (\ref{normal}) is
\begin{equation}
    n_m=\left\{-{\sqrt{\frac{\left(a^2 R(\theta )^2+r^2\right) \left(a^2
   R'(\theta )^2+a^2 R(\theta )^2+r (r-2 M)\right)}{a^4 R(\theta )^4+r \left(a^2 (2 M-r) P'(\theta )^2-2 a^2 r P'(\theta ) R'(\theta )+r^3\right)-R(\theta )^2 \left(2 a^4 P'(\theta ) R'(\theta )+a^4 P'(\theta )^2-2 a^2 r^2\right)}}},0,0,0\right\}.
\end{equation}
The nonzero components of the induced metric (\ref{gamma}) are
\begin{equation}
\begin{array}{cccc}

\gamma_{0 0} = \frac{\left(a^2 R(\theta )^2+r^2\right) \left(a^2 R'(\theta )^2+a^2 R(\theta )^2+r (r-2 M)\right)}{a^4 R(\theta )^4+r \left(a^2 (2 M-r) P'(\theta )^2-2 a^2 r P'(\theta ) R'(\theta )+r^3\right)-R(\theta )^2 \left(2 a^4 P'(\theta ) R'(\theta )+a^4 P'(\theta )^2-2 a^2 r^2\right)}-\frac{a^2 R(\theta )^2+r (r-2 M)}{a^2 R(\theta )^2+r^2};

\\

\gamma_{0 3} = \gamma_{3 0} = \frac{a \left(P'(\theta ) \left(a^2 R(\theta )^2+r (r-2 M)\right)+R'(\theta ) \left(a^2 R(\theta )^2+r^2\right)\right)}{\left(a^2 R(\theta )^2+r^2\right) \left(a Q'(\theta )+\csc \theta \right)};

\\

\gamma_{1 1} = \frac{a^2 R(\theta )^2+r^2}{a^2 R'(\theta )^2+a^2 R(\theta )^2+r (r-2 M)};

\\

\gamma_{2 2} = a^2 R(\theta )^2+r^2;

\\

\gamma_{3 3} = \frac{a^4 R(\theta )^4+r \left(a^2 (2 M-r) P'(\theta )^2-2 a^2 r P'(\theta ) R'(\theta )+r^3\right)-R(\theta )^2 \left(2 a^4 P'(\theta ) R'(\theta )+a^4 P'(\theta )^2-2 a^2 r^2\right)}{\left(a^2 R(\theta )^2+r^2\right) \left(a Q'(\theta )+\csc \theta \right)^2}.

\\
\end{array}
\end{equation}
