\section{Theory with  ${}^{(3)}R =g^{mn}{}^{(3)}R_{mn}$}\m{gR}
Considering the action \eqref{lagReq}
\begin{equation}\label{lagReq2}
    S=\frac{1}{16 \pi}\int d^4 x \sqrt{-g} (R -2 \Lambda+ \lambda {}^{(3)} R_{mn}g^{mn}) + S_{matter}.
\end{equation}
The variation of the new term gives
\begin{equation}
\begin{array}{cccc}
     \delta(\sqrt{-g} g^{mn} {}^{(3)}R_{mn}) =   \sqrt{-g} \delta g^{mn} {}^{(3)}R_{mn} -\frac{1}{2}  \sqrt{-g} g_{ab} \delta  g^{ab} g^{mn} {}^{(3)}R_{mn}+    \sqrt{-g} g^{mn} \delta({}^{(3)}R_{mn})=\\
       \delta(\sqrt{-g} g^{mn} {}^{(3)}R_{mn}) =   \sqrt{-g} \delta g^{mn} {}^{(3)}R_{mn} -\frac{1}{2}  \sqrt{-g} g_{ab} \delta  g^{ab} g^{mn} {}^{(3)}R_{mn}+    \sqrt{-g} (\gamma^{mn}-n^m n^n) \delta({}^{(3)}R_{mn}) .
\end{array}
\end{equation}
So, the only new term appears comparing to (\ref{laglam}) is $- \sqrt{-g} ~n^m n^n \delta{}^{(3)}R_{mn}$.
We will use the following expressions for variations derived in the Appendix \ref{gammadelR}:
\begin{equation}
\delta {}^{(3)}R_{ab} = D_c \delta {}^{(3)}\Gamma^c_{ab} - D_a \delta {}^{(3)}\Gamma^c_{cb},
\end{equation}
for 3-Ricci tensor variation and
\begin{equation}
\delta {}^{(3)}\Gamma^s_{mn} 
= \frac{1}{2} \gamma^{s t} \left( D_m \delta \gamma_{n t} + D_n \delta \gamma_{t m} - D_t \delta \gamma_{m n} \right)
\end{equation}
for the variation of the Christoffel symbols.
\begin{equation}
    \begin{array}{cccc}
- n^a n^b \delta^{(3)} R_{ab} = -n^a n^b \left( D_c \delta^{(3)} \Gamma^c_{ab} - D_a \delta^{(3)} \Gamma^c_{cb} \right)
\\
= - n^a n^b D_c \delta^{(3)} \Gamma^c_{ab} = - n^a n^b \frac{1}{2} \gamma^{cd} D_c \left( D_a \delta \gamma_{bd} + D_b \delta \gamma_{da} - D_d \delta \gamma_{ab} \right)
\\
= n^a n^b \frac{1}{2} D_c D^c \delta \gamma_{ab} = n^a n^b \frac{1}{2} D_c \left( \gamma^{cs} \gamma^{a'}_a \gamma^{b'}_b \nabla_s \delta \gamma_{a' b'} \right)
\\
= n^a n^b\frac{1}{2} \gamma^{c s} \gamma^{a'}_a \gamma^{b'}_b  D_c \nabla_s \delta \gamma_{a' b'} = 0,
    \end{array}
\end{equation}
where we used that $n^a D_a...=0,~~ D_a \gamma^{b}_c=0,~~ D_a\gamma^{c s}=0$.
This means that the equations of motion of this theory are the same as for (\ref{laglam}) --- (\ref{fieldeq}).

\section{Derivation of the energy-momentum tensor for the $4$-dimensional conformal coupling}\m{emt4d}
For simplicity, in derivations we will consider the case of $\eta=0$ in \eqref{4dconformallag}, but the result can be easily extended to the case $\eta \neq 0$. We need to compute:
\begin{equation}
\frac{\delta S}{\delta g^{ab}}=    \frac{\delta}{\delta g^{ab}} \left[ \int \left( \nabla_c \phi \nabla^c \phi + V(\phi) + \xi R \phi^2 \right) \sqrt{-g} \, d^4x \right]. \label{eq:variation_total}
\end{equation}
The kinetic term depends on the metric through the contraction of indices and the volume element. Its variation is:
\begin{equation}
    \frac{\delta}{\delta g^{ab}} \left[ g^{cd} \nabla_c \phi \nabla_d \phi \sqrt{-g} \right]
    = \nabla_a \phi \nabla_b \phi \sqrt{-g} - \frac{1}{2} g_{ab} g^{cd} \nabla_c \phi \nabla_d \phi \sqrt{-g},
\end{equation}
where we used:
\begin{equation}
    \frac{\delta \sqrt{-g}}{\delta g^{ab}} = -\frac{1}{2} \sqrt{-g} g_{ab}.
\end{equation}
The variation of the potential term is straightforward:
\begin{equation}
    \frac{\delta}{\delta g^{ab}} \left[ \int V(\phi) \sqrt{-g} \, d^4x \right] = V(\phi) \frac{\delta \sqrt{-g}}{\delta g^{ab}} = -\frac{1}{2} g_{ab} V(\phi) \sqrt{-g}.
\end{equation}
Finally, for the curvature coupling term, we compute:
\begin{equation}
    \frac{\delta}{\delta g^{ab}} \left[ \int \xi R \phi^2 \sqrt{-g} \, d^4x \right]
    = \xi \frac{\delta R_{cd}}{\delta g^{ab}} g^{cd} \phi^2 \sqrt{-g} 
    + \xi R_{cd} \frac{\delta g^{cd}}{\delta g^{ab}} \phi^2 \sqrt{-g} 
    + \xi R \phi^2 \frac{\delta \sqrt{-g}}{\delta g^{ab}}. \label{eq:curvature_coupling}
\end{equation}
Substituting the variation of the volume element and recognizing the Einstein tensor \( G_{ab} = R_{ab} - \frac{1}{2} g_{ab} R \), we write:
\begin{equation}
    \frac{\delta}{\delta g^{ab}} \left[ \int \xi R \phi^2 \sqrt{-g} \, d^4x \right] = \xi \frac{\delta R_{cd}}{\delta g^{ab}}g^{cd} \phi^2 \sqrt{-g} + \xi G_{ab} \phi^2 \sqrt{-g}.
\end{equation}
Thus, so far, the stress-energy tensor becomes:
\begin{equation}
    T_{ab} = \nabla_a \phi \nabla_b \phi - \frac{1}{2} g_{ab} \left( \nabla_c \phi \nabla^c \phi + V(\phi) \right)
    + \xi \phi^2 \left( G_{ab} + \frac{\delta R_{cd}}{\delta g^{ab}}g^{cd} \right). \label{eq:stress_energy_intermediate}
\end{equation}
The remaining term involving the Ricci tensor variation is best computed under an integral:
\begin{equation}
    \int \xi g^{cd} \delta R_{cd} \phi^2 \sqrt{-g} \, d^4x.
\end{equation}
From \cite{Wald:1984rg}, Eq. (3.4.5), we know that the Ricci tensor is expressed in terms of the connection coefficients as:
\begin{equation}
    R_{m n} = \partial_r \Gamma^r_{m n} - \partial_m \Gamma^r_{r n} 
    + \Gamma^s_{m n} \Gamma^r_{s r} - \Gamma^s_{r n} \Gamma^r_{s m}. \label{eq:ricci_tensor}
\end{equation}
When varying the Ricci tensor, we consider its dependence on the Christoffel symbols. In a locally inertial frame, the variation is given by:
\begin{equation}
    \delta R_{m n} = \partial_r \delta \Gamma^r_{m n} - \partial_m \delta \Gamma^r_{r n}, \label{eq:variation_ricci_tensor}
\end{equation}
where \( \delta \Gamma^r_{m n} \) represents the variation of the Christoffel symbols. This expression can be generalized to any coordinate system since \( \delta \Gamma^r_{m n} \) is a tensor (as it represents differences between Christoffel symbols in different metrics).
Rewriting Eq.~(\ref{eq:variation_ricci_tensor}) in terms of covariant derivatives, we have:
\begin{equation}
    \delta R_{m n} = \nabla_r \delta \Gamma^r_{m n} - \nabla_m \delta \Gamma^r_{r n}. \label{eq:variation_ricci_covariant}
\end{equation}
Contracting this with the metric \( g^{ab} \), we find:
\begin{equation}
    g^{ab} \delta R_{ab} = g^{ab} \nabla_c \delta \Gamma^c_{ab} - g^{ab} \nabla_a \delta \Gamma^c_{cb}= \nabla_c \left[ g^{ab} \delta \Gamma^c_{ab} - g^{bc} \delta \Gamma^a_{ab} \right]. \label{eq:ricci_variation_contracted}
\end{equation}


Next, we compute the variation of the Christoffel symbols. The Christoffel symbols are defined as:
\begin{equation}
    \Gamma^s_{m n} = \frac{1}{2} g^{s t} \left( \partial_m g_{n t} + \partial_n g_{t m} - \partial_t g_{m n} \right).
\end{equation}
The variation of \( \Gamma^s_{m n} \) with respect to the metric gives:
\begin{equation}
    \delta \Gamma^s_{m n} = \frac{1}{2} \delta g^{s t} 
    \left( \partial_m g_{n t} + \partial_n g_{t m} - \partial_t g_{m n} \right) 
    + \frac{1}{2} g^{s t} 
    \left( \partial_m \delta g_{n t} + \partial_n \delta g_{t m} - \partial_t \delta g_{m n} \right). \label{eq:variation_christoffel}
\end{equation}
Replacing partial derivatives by covariant and using that covariant derivative of metric is zero we have
\begin{equation}
    \delta \Gamma^s_{m n} = \frac{1}{2} g^{s t} 
    \left( \nabla_m \delta g_{n t} + \nabla_n \delta g_{t m} - \nabla_t \delta g_{m n} \right). \label{eq:variation_christoffel_simplified}
\end{equation}
We start with the variation of the first term:
\begin{equation}
    g^{ab} \delta \Gamma^c_{ab} = \frac{1}{2} g^{ab} g^{cd} \left( \nabla_a \delta g_{bd} + \nabla_b \delta g_{ad} - \nabla_d \delta g_{ab} \right). \label{eq:variation_gGamma}
\end{equation}
Using the symmetry of \( g^{ab} \) and \( \delta g_{ab} \), we combine terms:
\begin{equation}
    g^{ab} \delta \Gamma^c_{ab} = \frac{1}{2} g^{cd} g^{ab} \left( 2 \nabla_a \delta g_{bd} - \nabla_d \delta g_{ab} \right). \label{eq:variation_gGamma_simplified}
\end{equation}
For the second term, we calculate:
\begin{equation}
    g^{bc} \delta \Gamma^a_{ab} = \frac{1}{2} g^{bc} g^{ad} \left( \nabla_a \delta g_{bd} + \nabla_b \delta g_{ad} - \nabla_d \delta g_{ab} \right). \label{eq:variation_gGamma_2}
\end{equation}
This simplifies under the symmetries of \( g^{ab} \) and \( \delta g_{ab} \) to:
\begin{equation}
    g^{bc} \delta \Gamma^a_{ab} = \frac{1}{2} g^{ad} g^{bc}\nabla_b \delta g_{da}. \label{eq:variation_gGamma_2_simplified}
\end{equation}
Substituting the results from Eq.~(\ref{eq:variation_gGamma_simplified}) and Eq.~(\ref{eq:variation_gGamma_2_simplified}) into the contracted Ricci scalar variation, after simple calculations we have:
\begin{equation}
    g^{ab} \delta R_{ab} =  g^{cd}  g^{ab} \nabla_c\nabla_a \delta g_{bd} -g^{ab}\nabla_c\nabla^c \delta g_{ab}. \label{eq:ricci_combined_variation}
\end{equation}
We now simplify using \( \delta g^{ab} = -g^{ac} g^{bd} \delta g_{cd} \), which gives:
\begin{equation}
    g^{ab} \delta R_{ab} = \left( g_{ab} \nabla_c \nabla^c - \nabla_a \nabla_b \right) \delta g^{ab}. \label{eq:ricci_variation_final_form}
\end{equation}
This is the final expression for the variation of the Ricci scalar, expressed in terms of the metric variations \( \delta g_{ab} \).
So, we have the term:
\begin{equation}\label{eq:2.16a}
\begin{array}{cccc}
     \int \xi g^{cd} \delta R_{cd} \phi^2 \sqrt{-g} \, d^4x = 
    \int \xi \phi^2 \left( g_{ab} \nabla_c \nabla^c \delta g^{ab} - \nabla_a \nabla_b \delta g^{ab} \right) \sqrt{-g} \, d^4x \\= \int \xi \delta g^{ab} \left( g_{ab} \nabla_c \nabla^c - \nabla_a \nabla_b \right) \phi^2 \sqrt{-g} \, d^4x+ surface ~~terms. 
\end{array}
\end{equation}
Here, the surface terms arise from integration by parts, and we discard them assuming they vanish at the boundary. The final expression for the stress-energy tensor becomes:
\begin{equation}
    T_{ab} = \nabla_a \phi \nabla_b \phi - \frac{1}{2} g_{ab} \left( \nabla_c \phi \nabla^c \phi + V(\phi) \right) 
    + \xi \phi^2 G_{ab} + \xi \left( g_{ab} \nabla_c \nabla^c - \nabla_a \nabla_b \right) \phi^2. \label{eq:2.18}
\end{equation}
\section{Derivation of $\gamma^{cd} \delta {}^{(3)}R_{cd}$ }\m{gammadelR}
We start with
\begin{equation}\label{2.7}
\int \xi \gamma^{cd} \delta {}^{(3)}R_{cd} \phi^2 \sqrt{-g} , d^4x.
\end{equation}
Going to 3 dimensions we have
\begin{equation}\label{2.8}
{}^{(3)}R_{mn} = \partial_r {}^{(3)}\Gamma^r_{mn} - \partial_m {}^{(3)}\Gamma^r_{rn} + {}^{(3)}\Gamma^s_{mn} {}^{(3)}\Gamma^r_{sr} - {}^{(3)}\Gamma^s_{rn} {}^{(3)}\Gamma^r_{sm}.
\end{equation}
In a locally inertial reference frame, we find
\begin{equation}\label{2.9a}
\delta {}^{(3)}R_{mn} = \partial_r \delta {}^{(3)}\Gamma^r_{mn} - \partial_m \delta {}^{(3)}\Gamma^r_{rn},
\end{equation}
\begin{equation}\label{2.9b}
= D_r \delta {}^{(3)}\Gamma^r_{mn} - D_m \delta {}^{(3)}\Gamma^r_{rn}.
\end{equation}
Since this equation is tensorial (as $\delta {}^{(3)}\Gamma^r_{mn}$ is a 3D tensor), it holds in all coordinate systems, and we conclude:
\begin{equation}\label{2.10a}
\delta {}^{(3)}R_{ab} = D_c \delta {}^{(3)}\Gamma^c_{ab} - D_a \delta {}^{(3)}\Gamma^c_{cb},
\end{equation}
\begin{equation}\label{2.10b}
\gamma^{ab} \delta {}^{(3)}R_{ab} = \gamma^{ab} D_c \delta {}^{(3)}\Gamma^c_{ab} - \gamma^{ab} D_a \delta {}^{(3)}\Gamma^c_{cb}
\end{equation}
\begin{equation}\label{2.10c}
= \gamma^{ab} D_c \delta {}^{(3)}\Gamma^c_{ab} - \gamma^{cb} D_c \delta {}^{(3)}\Gamma^a_{ab}
\end{equation}
\begin{equation}\label{2.10d}
= D_c \left[ \gamma^{ab} \delta {}^{(3)}\Gamma^c_{ab} - \gamma^{cb} \delta {}^{(3)}\Gamma^a_{ab} \right].
\end{equation}
Next, we compute the variation of the Christoffel symbols:
\begin{equation}\label{2.11a}
\delta {}^{(3)}\Gamma^s_{mn} = \frac{1}{2} \delta \left( \gamma^{s t} \left( \partial_m \gamma_{n t} + \partial_n \gamma_{t m} - \partial_t \gamma_{m n} \right) \right)
\end{equation}
\begin{equation}\label{2.11b}
= \frac{1}{2} \delta \gamma^{s t} \left( \partial_m \gamma_{n t} + \partial_n \gamma_{t m} - \partial_t \gamma_{m n} \right) + \frac{1}{2} \gamma^{s t} \left( \partial_m \delta \gamma_{n t} + \partial_n \delta \gamma_{t m} - \partial_t \delta \gamma_{m n} \right)
\end{equation}
\begin{equation}\label{2.11c}
= \frac{1}{2} \gamma^{s t} \left( D_m \delta \gamma_{n t} + D_n \delta \gamma_{t m} - D_t \delta \gamma_{m n} \right).
\end{equation}
Where we replaced partial derivatives by covariant 3-derivatives and used that $D_a \gamma_{bc}=0$.
For the relevant 3-Christoffel symbol variation:
\begin{equation}\label{2.11e}
\delta {}^{(3)}\Gamma^c_{ab} = \frac{1}{2} \gamma^{cd} \left( D_a \delta \gamma_{bd} + D_b \delta \gamma_{da} - D_d \delta \gamma_{ab} \right).
\end{equation}
We now compute:
\begin{equation}\label{2.12b}
\gamma^{ab} \delta {}^{(3)}\Gamma^c_{ab} = \frac{1}{2} \gamma^{ab} \gamma^{cd} \left( 2 D_a \delta \gamma_{bd} - D_d \delta \gamma_{ab} \right),
\end{equation}
\begin{equation}\label{2.13b}
\gamma^{cb} \delta {}^{(3)}\Gamma^a_{ab} = \frac{1}{2} \gamma^{cb} \gamma^{ad} D_b \delta \gamma_{da}.
\end{equation}
Using these, we find:
\begin{equation}\label{2.14a}
\gamma^{ab} \delta {}^{(3)}R_{ab} = D_c 
\left[ \gamma^{ab} \delta {}^{(3)}\Gamma^c_{ab} - \gamma^{cb} \delta {}^{(3)}\Gamma^a_{ab} \right]
\end{equation}
\begin{equation}\label{2.14b}
= \frac{1}{2} D_c 
\left[ \gamma^{ab} \gamma^{cd} 
\left( 2 D_a \delta \gamma_{bd} - D_d \delta \gamma_{ab} \right) 
- \gamma^{cb} \gamma^{ad} D_b \delta \gamma_{da} \right]
\end{equation}
\begin{equation}\label{2.14c}
= \gamma^{ab} \gamma^{cd} D_c D_a \delta \gamma_{bd} - \frac{1}{2} \gamma^{ab} D_c D^c \delta \gamma_{ab} - \frac{1}{2} \gamma^{ad} D_c D^c \delta \gamma_{ad}
\end{equation}
\begin{equation}\label{2.14d}
= \gamma^{ab} \gamma^{cd} D_c D_a \delta \gamma_{bd} - \gamma^{ab} D_c D^c \delta \gamma_{ab}.
\end{equation}
Using the definition of the induced metric (\ref{gammagen}) we have
\begin{equation}
\gamma^{ab} \delta {}^{(3)}R_{ab}= \gamma^{ab} \gamma^{cd} D_c D_a \delta (g_{bd}+n_b n_d) - \gamma^{ab} D_c D^c \delta (g_{ab}+n_a n_b).
\end{equation}
Because $D_b\gamma^{ac}=0$ and all terms like $\gamma^{ab}n_b \delta n_d$ are zero, we have
\begin{equation}
\gamma^{ab} \delta {}^{(3)}R_{ab}= \gamma^{ab} \gamma^{cd} D_c D_a \delta g_{bd} - \gamma^{ab} D_c D^c \delta g_{ab}.
\end{equation}
Recalling now that
\begin{equation}
\delta g_{ab} = -g_{ac} g_{bd} \delta g^{cd},
\end{equation}
and using that $D_bg_{ac}=0$ we see that
\begin{equation}\label{2.15a}
\gamma^{ab} \delta {}^{(3)}R_{ab} = \gamma_{ab} D_c D^c \delta g^{ab} - \gamma^a_{b_1} \gamma^c_{d_1} D_a D_c  \delta g^{b_1 d_1} =  \gamma_{ab} D_c D^c \delta g^{ab} - (\delta^a_{b_1}+n^a n_{b_1} )( \delta^c_{d_1}+n^c n_{d_1}) D_a D_c  \delta g^{b_1 d_1} .
\end{equation}
Because $n^aD_a...=0 $ we have
\begin{equation}\label{2.15b}
\gamma^{ab} \delta {}^{(3)}R_{ab}= \left( \gamma_{ab} D_c D^c - D_a D_b \right) \delta g^{ab}.
\end{equation}
\section{Derivation of the scalar field energy-momentum tensor with coupling to $^{(3)}R$}\m{emt3d}

Let us derive the field equations for \eqref{anothercouplag}. Taking the variation of $S_m$ with respect to metric  we get
\begin{equation}
    T_{ab} = \nabla_a \phi \nabla_b \phi - \frac{1}{2} g_{ab} \nabla_c \phi \nabla^c \phi - \frac{1}{2} g_{ab} V(\phi) + \frac{\delta}{\sqrt{-g} \delta g^{ab}} \left( \int \xi {}^{(3)} R \phi^2 \sqrt{-g} \, d^4 x \right),
\end{equation}
where the variations of the kinetic and potential terms are derived in the Appendix \ref{emt4d}.
Writing the last term in detail we have
\begin{equation}
\frac{\delta}{\sqrt{-g} \delta g^{ab}} \left( \int \xi {}^{(3)} R \phi^2 \sqrt{-g} \, d^4 x \right) =   \xi \frac{ \delta {}^{(3)} R_{cd}}{\delta g^{ab}}  \, \gamma^{cd} \, \phi^2 + \xi^3 R_{cd} \,\frac{\delta \gamma^{cd}}{\delta g^{ab}} \, \phi^2 - \frac{1}{2} \xi {}^{(3)} R \, g_{ab} \, \phi^2 . \end{equation}
Then, rewriting the first term of the right hand side according to \cite{Jha:2022svf} (see derivation in Appendix \ref{gammadelR}) we get
\begin{equation}
\gamma^{ab} \delta {}^{(3)} R_{ab} = \left( \gamma_{ab} D_c D^c - D_a D_b \right) \delta g^{ab}. \end{equation}
Integrating it by parts twice we get
\begin{equation}
\int \gamma^{ab} \xi  \delta {}^{(3)} R_{ab} \phi^2 \sqrt{-g} \, d^4x = \int \xi \delta g^{ab} \left( \gamma_{ab} D_c D^c - D_a D_b \right) (N \phi^2)  \sqrt{\gamma} \, d^4 x + boundary~~terms .\end{equation}
So we have
\begin{equation}
 \frac{1}{\sqrt{-g}} \xi \frac{\delta^3 R_{cd}}{\delta g^{ab}} \, \gamma^{cd}  = \frac{\xi}{N} \left( \gamma_{ab} D_c D^c - D_a D_b \right) (N \phi^2).
\end{equation}
Rewriting the second term we have
\begin{equation}
    \xi^3 R_{cd} \,\delta \gamma^{cd} \, \phi^2 =  \xi^3 R_{cd} \,\delta (g^{cd}+n^c n^d) \, \phi^2 =  \xi^3 R_{cd} \,\delta g^{cd} \, \phi^2 ,
\end{equation}
where we use that the terms like $R_{cd} n^c$ vanish.
Thus, we get the energy-momentum tensor
\begin{equation}
T_{ab} = \nabla_a \phi \nabla_b \phi - \frac{1}{2} g_{ab} \nabla_c \phi \nabla^c \phi - \frac{1}{2} g_{ab} V(\phi) + \frac{\xi}{N}(\gamma_{a b} D_c D^c -D_{a} D_{b})(\phi^2 N) + \xi {}^{(3)} R_{ab} \phi^2   - \frac{1}{2} {}^{(3)} R g_{ab} \xi \phi^2.
\end{equation}





