\section{Edge Computing and IoT Integration for Real-Time Analytics}

\begin{figure*}[ht]
    \centering
    \includegraphics[width=0.8\linewidth]{Images/Embedded.pdf}
    \caption{\textbf{How optimization techniques help overcome resource limitations of IoT devices when deploying AI models.}}
