\section{Mathematical Background}
\label{sec:math}

\subsection{Problem Formulation}

We consider a univariate financial time series of daily log‐returns
\[
\{r_1, r_2, \dots, r_t\},\quad 
r_t = \log\bigl(P_t / P_{t-1}\bigr), \tag{1}
\]
where \(P_t\) is the price at time \(t\).  Our aim is to produce a prediction interval \([\ell_{t+1},u_{t+1}]\) for the \(\alpha\)-quantile of the next return,
\[
q_\alpha(t+1)
\quad\text{s.t.}\quad
\Pr\bigl(r_{t+1}\le q_\alpha(t+1)\bigr)\approx\alpha, \tag{2}
\]
with exact finite‐sample coverage even during extreme market moves.  Standard, parametric estimators often break down in the tails, motivating our distribution‐free approach.

\subsection{Classical Conformal Prediction}

Given i.i.d.\ observations \(\{(X_i,Y_i)\}_{i=1}^n\) from an unknown law \(P\), conformal prediction yields prediction sets with guaranteed coverage.

\begin{definition}[Conformity Score]
A mapping \(A\bigl((X_i,Y_i)\bigr)\mapsto\alpha_i\in\mathbb{R}\) quantifies how well each pair “conforms” to the training data.
\end{definition}

\begin{definition}[Conformal Prediction Set]
For level \(\alpha\in(0,1)\), the set for a new input \(X_{n+1}\) is
\[
\Gamma_\alpha(X_{n+1})
=\bigl\{y:
  \tfrac{1}{n+1}\#\{i\le n: \alpha_i \le A(X_{n+1},y)\}
  > \alpha
\bigr\}. \tag{3}
\]
\end{definition}

\begin{theorem}[Finite‐Sample Validity]
Under exchangeability,
\[
\Pr\bigl(Y_{n+1}\in \Gamma_\alpha(X_{n+1})\bigr)\;\ge\;1-\alpha. \tag{4}
\]
\end{theorem}

\noindent In practice we set 
\(\alpha_i = |Y_i - \widehat f(X_i)|\) 
for a fitted regressor \(\widehat f\).  See Appendix~\ref{app:Appendix A} for the full proof.

\subsection{Temporal Conformal Prediction (TCP)}

Financial returns exhibit volatility clustering and regime change, violating i.i.d. We relax exchangeability to sliding windows:

\begin{definition}[Temporal Exchangeability]
A series \(\{Z_t\}\) is exchangeable within any window of size \(w\) if permuting indices within that window leaves the joint law unchanged.
\end{definition}

\noindent\textbf{Algorithm 1: Temporal Conformal Prediction}

\begin{enumerate}
  \item \textbf{1. Input:} Returns \(\{r_1,\dots,r_t\}\), window \(w\), level \(\alpha\).
  \item \textbf{2. Forecasts:} For each \(i\), fit a quantile regression on \(\{r_{i-w},\dots,r_{i-1}\}\) to get 
    \(\widehat q_{\alpha/2}(i)\) and \(\widehat q_{1-\alpha/2}(i)\).
  \item \textbf{3. Residuals:} For \(\tau\in\{\alpha/2,1-\alpha/2\}\) and \(i=t-w+1,\dots,t\), compute 
    \(\varepsilon_i = |r_i - \widehat q_\tau(i)|\).
  \item \textbf{4. Thresholds (corrected):} 
    \[
    C_\tau = \mathrm{quantile}\!\bigl(\{\varepsilon_i\},\,1-\tfrac\alpha2\bigr),
    \]
    so each tail has exclusion probability \(\alpha/2\).
  \item \textbf{5. Interval:}  
    \[
      \ell_{t+1} = \widehat q_{\alpha/2}(t+1) - C_{\alpha/2}, 
      \quad
      u_{t+1} = \widehat q_{1-\alpha/2}(t+1) + C_{1-\alpha/2}.
    \]
  \item \textbf{6. Output:} \([\ell_{t+1},u_{t+1}]\).
\end{enumerate}

\subsection{Adaptive Calibration}

To correct systematic miscoverage, we update thresholds online:

\begin{definition}[Coverage Error]
At time \(t\),
\[
e_t = \mathbf{1}\bigl(r_t\notin[\ell_t,u_t]\bigr) - \alpha.
\]
\end{definition}

\noindent We then adjust
\[
C_{t+1} = C_t + \gamma_t\,e_t,
\quad
\gamma_t = \frac{\gamma_0}{(1+\lambda\,t)^\beta},
\tag{5}
\]
with \(\gamma_0>0,\;\lambda>0,\;\beta\in(0.5,1)\) chosen so that
\(\sum_t\gamma_t=\infty\) and \(\sum_t\gamma_t^2<\infty\) (\href{https://doi.org/10.1214/aoms/1177729586}{Robbins \& Monro, 1951}; Kushner \& Yin, 2003).

\begin{theorem}[Asymptotic Coverage]
Under the update in (5), with \(\beta\in(0.5,1)\) and ergodicity,
\[
\lim_{T\to\infty}\frac{1}{T}\sum_{t=1}^T\mathbf{1}(r_t\in[\ell_t,u_t])
\;=\;1-\alpha.
\tag{6}
\]
\end{theorem}

\noindent See Appendix~\ref{app:Appendix A} for the proof.


