\section{Methodology}
\label{sec:methodology}

\subsection{Data Structure}
We analyze high-frequency financial returns across three asset classes namely \textbf{Equities: S\&P 500}, \textbf{Cryptocurrencies: Bitcoin (BTC)} and \textbf{Commodities: Gold}.The dataset contains daily log-returns $r_t = \log(P_t/P_{t-1})$ from November 2017 to May 2025. 

\subsection{Feature Space Construction}
For each asset, we engineer:

\begin{equation}
\begin{aligned}
\text{Lagged Returns:} \quad & \{r_{t-k}\}_{k=1}^{5} \\
\text{Realized Volatility:} \quad & \sigma_t = \sqrt{\frac{1}{20} \sum_{k=1}^{20} r_{t-k}^2} \\
\text{Nonlinear Transformations:} \quad & r_{t-1}^2,\quad \mathrm{sign}(r_{t-1})
\end{aligned} \tag{7}
\end{equation}


\subsection{Model Architecture}
Four competing specifications are implemented:

\subsubsection{Temporal Conformal Prediction (TCP)}

\begin{enumerate}
    \item \textbf{1. Estimate conditional quantiles via gradient-boosted trees:}
    \begin{equation}
        \widehat{q}_\tau(t) = \mathcal{F}_\tau\big( \{r_{t-k}\}_{k=1}^5,\; \sigma_t,\; r_{t-1}^2,\; \mathrm{sign}(r_{t-1}) \big) \tag{8}
    \end{equation}

    \item \textbf{2. Compute absolute residuals over a rolling window of size \( w = 252 \):}
    \begin{equation}
        \varepsilon_\tau(t) = \left| r_t - \widehat{q}_\tau(t) \right| \tag{9}
    \end{equation}

    \item \textbf{3. Calibrate thresholds using empirical quantiles:}
    \begin{equation}
        C_\tau = Q_{1 - \alpha/2} \left( \left\{ \varepsilon_\tau(i) \right\}_{i = t - w + 1}^{t} \right) \tag{10}
    \end{equation}

    \item \textbf{4. Adapt thresholds with decayed learning rate:}
    \begin{equation}
        C_\tau^{(t+1)} = C_\tau^{(t)} + \frac{0.01}{(1 + 0.1 t)^{0.7}} \left( \mathbb{1} \{ r_t \notin \mathcal{I}_t \} - \alpha \right) \tag{11}
    \end{equation}
\end{enumerate}

\subsubsection{Benchmark Models}
\begin{enumerate}
    \item \textbf{1. Quantile Regression (QR)}: Global version of $\mathcal{F}_\tau$ without temporal adaptation
    \item \textbf{2. GARCH(1,1)}: Parametric volatility model with conditional normality
    \begin{equation}
        \sigma_t^2 = \begin{cases} 
\frac{1}{50}\sum_{k=1}^{50} r_k^2 & t \leq 50 \\
10^{-6} + 0.05r_{t-1}^2 + 0.9\sigma_{t-1}^2 & t > 50 
\end{cases} \tag{12}
    \end{equation}
    \item \textbf{3. Historical Simulation}: Empirical quantiles from rolling 252-day window
\end{enumerate}

\subsection{Training Protocol}
\begin{itemize}
    \item Warmup periods: 252 days (TCP/Historical), 50 days (GARCH)
    \item Daily retraining: TCP thresholds updated sequentially
    \item Static fits: QR and GARCH parameters estimated once
\end{itemize}

\subsection{Evaluation Framework}

We evaluate each method using the following metrics:

\begin{equation}
\begin{aligned}
\text{Coverage:} \quad & \frac{1}{T} \sum_{t=1}^T \mathbb{1}\{ r_t \in [\ell_t, u_t] \} \\
\text{Sharpness:} \quad & \frac{1}{T} \sum_{t=1}^T (u_t - \ell_t) \\
\text{Calibration:} \quad & \sup_{0 < \gamma < 1} \left| \frac{1}{T} \sum_{t=1}^T \mathbb{1}\{ r_t \leq \hat{q}_\gamma(t) \} - \gamma \right|
\end{aligned} \tag{13}
\end{equation}
\noindent
Here, \textbf{Coverage} measures the proportion of times the true return falls within the predicted interval; \textbf{Sharpness} reflects the average width of the interval, favoring tighter bounds; and \textbf{Calibration} quantifies the worst-case deviation between predicted and empirical quantiles, capturing quantile miscalibration.


\subsection{Reproducibility}

All code was implemented in Python (v3.11). The dataset and the full pipeline is publicly available at \href{https://github.com/agnivibes/tcp}{github.com/agnivibes/tcp}.

