\section{Appendix: Mathematical Proofs}
\label{app:Appendix A}

\subsection*{A.1 Proof of Finite‐Sample Validity (Theorem 3.1)}

\textbf{Theorem Statement.}  
Under exchangeability of \(\{(X_i,Y_i)\}_{i=1}^{n+1}\),
\[
\Pr\bigl(Y_{n+1}\in\Gamma_\alpha(X_{n+1})\bigr)\;\ge\;1-\alpha.
\]

\noindent \begin{proof}
Let 
\[
\alpha_i \;=\; A\bigl(X_i,Y_i\bigr),\quad i=1,\dots,n+1
\]
be the conformity scores.  By exchangeability, all \((n+1)!\) orderings of \((\alpha_1,\dots,\alpha_{n+1})\) are equally likely.

\smallskip
\noindent Let us define
\[
R \;=\;\#\{\,i\le n : \alpha_i \le \alpha_{n+1}\},
\quad
\frac{R}{n+1} = \frac{\#\{i\le n:\alpha_i\le \alpha_{n+1}\}}{n+1}.
\]
Symmetry implies \(\Pr(R = k)=1/(n+1)\) for \(k=0,\dots,n\).  The event \(Y_{n+1}\notin\Gamma_\alpha\) occurs if 
\(\tfrac{R}{n+1}\le\alpha\), i.e.\ \(R\le\lfloor\alpha(n+1)\rfloor\).  

\smallskip
\noindent Hence
\[
\Pr\bigl(Y_{n+1}\notin\Gamma_\alpha\bigr)
=\Pr\bigl(R\le\lfloor\alpha(n+1)\rfloor\bigr)
\le\frac{\lfloor\alpha(n+1)\rfloor+1}{n+1}
\le\alpha,
\]
and hence \(\Pr(Y_{n+1}\in\Gamma_\alpha)\ge1-\alpha\).
\end{proof}


\subsection*{A.2 Proof of Asymptotic Coverage (Theorem 3.2)}

\textbf{Theorem Statement.}  
Under the online update
\[
C_{t+1} = C_t + \gamma_t\,e_t,
\quad
e_t = \mathbf{1}(r_t\notin[\ell_t,u_t]) - \alpha,
\]
with step‐sizes 
\(\gamma_t = \gamma_0/(1+\lambda t)^\beta\),
\(\gamma_0>0,\;\lambda>0,\;\beta\in(0.5,1)\),
satisfying
\(\sum_{t=1}^\infty \gamma_t = \infty\) and 
\(\sum_{t=1}^\infty \gamma_t^2 < \infty\),
and assuming ergodicity, then almost surely
\[
\lim_{T\to\infty}\frac{1}{T}\sum_{t=1}^T \mathbf{1}(r_t\in[\ell_t,u_t])
= 1-\alpha.
\]

\noindent \begin{proof}
Let \(\mathcal{F}_t\) be the filtration generated by \(\{r_s,\ell_s,u_s\}_{s\le t}\), and define the coverage‐error
\[
e_t = \mathbf{1}(r_t\notin[\ell_t,u_t]) - \alpha,
\]
which is \(\mathcal{F}_t\)-measurable and bounded.  The update
\[
C_{t+1}-C_t = \gamma_t\,e_t
\]
is a \href{https://doi.org/10.1214/aoms/1177729586}{Robbins–Monro} stochastic approximation, targeting the root of \(\E[e_t\mid\mathcal{F}_{t-1}]=0\).

\paragraph{(i) Martingale Decomposition.}  
Write
\[
\Delta_t = e_t - \E[e_t\mid\mathcal{F}_{t-1}],
\]
so \(\{\Delta_t\}\) is a martingale‐difference sequence (Hall \& Heyde, 1980).  Then
\[
C_{t+1}-C_t
= \gamma_t\,\E[e_t\mid\mathcal{F}_{t-1}]
+ \gamma_t\,\Delta_t.
\]
By ergodicity and continuity of the quantile mapping, there is a unique \(C^*\) solving \(\E[e_t\mid C_t=C^*]=0\).

\paragraph{(ii) Almost Sure Convergence.}  
Since \(\sum\gamma_t=\infty\), \(\sum\gamma_t^2<\infty\), boundedness of \(e_t\), and standard stochastic‐approximation theory (Kushner \& Yin, 2003) guarantee \(C_t\to C^*\) almost surely.

\paragraph{(iii) Coverage Fraction.}  
As \(C_t\to C^*\), the long‐run average of \(e_t\) tends to zero almost surely:
\(\tfrac1T\sum_{t=1}^T e_t\to0\).  Thus
\[
\frac1T\sum_{t=1}^T\mathbf{1}(r_t\in[\ell_t,u_t]) - \alpha \;\to\;0
\quad\Longrightarrow\quad
\frac1T\sum_{t=1}^T\mathbf{1}(r_t\in[\ell_t,u_t]) \to 1-\alpha.
\]
This completes the proof.
\end{proof}

