\section{Preliminaries}
\label{sec:prelim}

% \begin{definition}
% \textbf{Heterogeneous Graph.}
% A hypergraph graph is defined as: $\mathcal{G} = (\mathcal{V}, \mathcal{E}, \mathcal{A}, \mathcal{R}, \phi, \psi)$, where $\mathcal{V}$ is the set of nodes, $\mathcal{E}$ is the set of edges, $\phi$ : $\mathcal{V} \to \mathcal{A}$ and $\psi$ : $\mathcal{E} \to \mathcal{R}$ are respectively the node type mapping function and the edge type mapping function, $\mathcal{A}$ denotes the set of object types, and $\mathcal{R}$ denotes the set of relations (link types), where $|\mathcal{A}|+|\mathcal{R}|>2$. $\mathbf{A}^R$ is the adjacency matrix under relation $R \in \mathcal{R}$.
% \end{definition}

\begin{definition}
\textbf{Heterogeneous Graph.}
A heterogeneous graph is defined as: $\mathcal{G} = (\mathcal{V}, \mathcal{E}, \mathcal{X}, \mathcal{Z}, \mathcal{A}, \mathcal{R})$, where $\mathcal{V}$ is the set of nodes, $\mathcal{E}$ is the set of edges, $\mathcal{X}$ denotes the set containing all the feature matrices associated with each type of nodes. $\phi$ : $\mathcal{V} \to \mathcal{A}$ and $\psi$ : $\mathcal{E} \to \mathcal{R}$ are respectively the node type mapping function and the edge type mapping function, $\mathcal{A}$ denotes the set of node types, and $\mathcal{R}$ denotes the set of relations (edge types), where $|\mathcal{A}|+|\mathcal{R}|>2$. $\mathcal{X} = \{\mathbf{X}^{1}, ..., \mathbf{X}^{A}, ..., \mathbf{X}^{|\mathcal{A}|}\}$ denotes the features of all types of nodes. $\mathcal{Z} = \{\mathbf{Z}^{1}, ..., \mathbf{Z}^{R}, ..., \mathbf{Z}^{|\mathcal{R}|}\}$ denotes the features of all types of edges.  $\mathbf{A}^R$ is the adjacency matrix under relation $r \in \mathcal{R}$. We can also have $\mathcal{E} = \{\mathbf{A}^{1}, ..., \mathbf{A}^{r}, ..., \mathbf{A}^{|\mathcal{R}|}\}$.
\end{definition}



\section{Methodology}
\label{sec:method}
In this section, we introduce RASH, aiming to separate homophily and heterophily from a heterogeneity perspective. As illustrated in Figure ~\ref{Fig.model}, RASH consists of four main modules: (1) heterogeneous graph encoder to extract node heterogeneity information, (2) relation-aware edge higher-order semantic learning, (3) dynamic homophily-heterophily separation, and (4) multi-relations contrastive learning.

\subsection{Heterogeneous Graph Encoding}
We utilize a heterogeneous graph neural network (HGNN) to extract node representations. Similar to previous work ~\cite{ie-hgcn,shgn}, we divide the representation learning process of the heterogeneous graph into node aggregation and type aggregation. Specifically, in the node aggregation process, the original heterogeneous graph is decomposed into multiple bipartite subgraphs based on the edge type $r$. Each bipartite subgraph contains two different types of nodes. Then, we aggregate each subgraph separately, and for node $i$, the information of different kinds of one-hop neighbors is aggregated based on the edge type $r$ to obtain the relation representation.

\begin{equation}
\mathbf{h}_{i}^{r} = \delta \Big(\mathbf{W}_{s} \mathbf{h}_{i} + \text{Node-Agg} \big(\{\mathbf{W}_{r} \mathbf{h}_{j} | j \in \mathcal{N}_{i}^{r}\}\big) \Big)
\end{equation}
where $\mathcal{N}_{i}^{r} = \{j | (i,j) \in \mathcal{E}, r \in \mathcal{R} \}$ denotes the set of one-hop neighbors of node $i$ under edge type $r$. $W_s, W_r$ are trainable parameters used to project node $i$ and node $j$ of different j types into the same space. \text{Node-Agg} denotes the method of node aggregation and $\delta$ represents the activation function. In the type aggregation process, we fuse the relation representation under multiple bipartite subgraphs corresponding to node $i$ to obtain a heterogeneous node representation.

\begin{equation}
\mathbf{h}_{i}^{\prime} = \text{Type-Agg} \big(\{\mathbf{h}_{i}^{r} | r \in \mathcal{R}, \mathcal{N}_{i}^{r} \neq \varnothing \}\big)
\end{equation}
where \text{Type-Agg} represents the fusion of multiple relation representation. It can be implemented in various ways: mean, sum, concat, and attention. $\mathbf{h}_{i}^{\prime}$ captures the heterogeneity of the heterogeneous graph by aggregating the heterogeneous neighborhood.


\subsection{Relation-Aware Higher-Order Semantic Learning}
The direct splicing of neighboring nodes as edge representations ignores the interaction of heterogeneous edges, and the inability to model higher-order relationships leads to weaker edge-type information, and to capture the relational importance of heterogeneous edges. We first transform a heterogeneous graph into a dual heterogeneous graph and then utilize a hypergraph neural network to extract node representations, i.e., edge representations in the original graph.

\subsubsection{Constructing Dual Heterogeneous Hypergraph}
\begin{definition}
\textbf{Dual Heterogeneous Hypergraph.}
A dual hypergraph ~\cite{dht} is defined as: $\mathcal{G}' = (\mathcal{V}', \mathcal{E}', \mathcal{X}', \mathcal{Z}')$, where $\mathcal{V}$ is the set of nodes, $\mathcal{E}$ is the set of hyperedges. $\mathcal{V}' = \mathcal{E}$.
$\mathcal{X}' = \mathcal{Z}$. $\mathcal{Z}' = \mathcal{X}$.
\end{definition}

A heterogeneous $\mathcal{G}$ can be split into multiple bipartite graphs without losing any structural information. Here, instead of using a bipartite adjacency matrix to describe a bipartite graph, following~\cite{dht}, we define an incidence matrix to describe the structural information contained in the bipartite graph.

Each relation $r \in \mathcal{R}$ corresponds to a bipartite graph contained in the original heterogeneous graph $\mathcal{G}$. Let us assume that relation $r$ involves two node types $A_1$, and $A_2$. That is, the node set $\mathcal{V}^{A_1}$ and the node set $\mathcal{V}^{A_2}$ exist edges $\mathcal{E}^{r}$ between them. We define the incidence matrix as $\mathbf{M}^{r} \in \{0,1\}^{(|\mathcal{V}^{A_1}| + |\mathcal{V}^{A_2}|) \times |\mathcal{E}^{r}|}$. If node $i \in \mathcal{V}^{A_1}$ and node $j \in $ are connected by edge $e \in $ in the original graph, then we have:
\begin{equation}
\mathbf{M}^{r}_{i,e} = 1 \text{ \& } \mathbf{M}^{r}_{j,e} = 1, \text{iff } \mathbf{A}^{r}_{i,j} = 1, <i, j> = e
\end{equation}

% Please see Figure~\ref{} for the illustration of incidence matrix $\mathbf{M}$.
Then, the dual heterogeneous hypergraph can be denoted as follows:

\begin{equation}
\mathcal{E}' = \{\overline{\mathbf{M}}^{1}, ..., \overline{\mathbf{M}}^{r}, ..., \overline{\mathbf{M}}^{|\mathcal{R}|}\}
\end{equation}
where $\overline{\mathbf{M}}^{r}$ denote the transpose matrix of $\mathbf{M}^{r}$

\subsubsection{Heterogeneous Hypergraph Convolution}
For the initial input of the dual heterogeneous hypergraph, we obtain different types of node representations through a heterogeneous graph neural network with the same architecture as the encoder but no shared parameters. Let $\overline{\mathbf{h}}$ denote the output of the encoder and concatenate the node representations based on the edge type $r$ to obtain the initial features.
\begin{equation}
    \mathbf{x}_{ij}^{r} =  \overline{\mathbf{h}}_i^{'}||\overline{\mathbf{h}}_j^{'},\psi{(i,j)} \in r
\end{equation}
Then, we execute hypergraph convolution ~\cite{hypergnn, hypergcn} for the heterogeneous dual hypergraph corresponding to each edge type $r$, using two-stage message passing:$(1)$Node-to-Hyperedge Aggregation: nodes within the hyperedge aggregate to obtain the hyperedge representation; $(2)$Hyperedge-to-Node Aggregation: node-involved hyperedge aggregation updating the node representation. The hypergraph encoder is defined as follows:
\begin{equation}
    \mathbf{H}^{r(l)} = \mathbf{\sigma} \left( \mathbf{D}^{r{-1}} \overline{\mathbf{M}}^r \mathbf{W}^r \mathbf{B}^{r{-1}}  \overline{\mathbf{M}}^{r\top} \mathbf{H^r}^{(l-1)} \mathbf{\Theta}^{r(l)} \right)
\end{equation}
where $\mathbf{\Theta}^{r(l)} \in \mathcal{R}^{d \times d'}$ is the projection matrix of layer $l$. $\mathbf{W}^r$ is the weight matrix of the hyperedge. $\mathbf{D}^{r-1}$ and $\mathbf{B}^{r-1}$ denote the diagonal matrices of the node degree and hyperedge degree, respectively. The $\mathbf{H^r}^{(0)}$ is equal to $\mathbf{X^r}$. The activation function $\mathbf{\sigma}()$ is set to PReLU. Edge importance is captured by performing hypergraph convolution on the dual hypergraph, explicitly modeling the higher-order semantic and contextual information of different types of edges. To sample edges that are highly important in constructing potential homophilic graphs and heterophilic graphs, we utilize a scoring function to get the sampling probability of each edge under edge type $r$.
\begin{equation}
    \mathbf{s}^r_{ij} = \text{Score}(\mathbf{h}^r_{ij}) %+ MLP(e_{ij})%局部和全局
\end{equation}
where $\text{Score()}$ is implemented as a simple linear layer. Due to the nontrivial nature of the Bernoulli distribution, the model is not well-trained to capture the importance of different edges, and we introduce the Gumbel-Max~\cite{discrete, gumbel-softmax} reparameterization method to transform the discrete binary distribution into a continuous distribution of soft weights. For a  bipartite subgraph under edge type $r$, the weight of each edge is defined as follows:
\begin{equation}
 w^r_{ij} = \text{Sigmoid} ((\mathbf{s}^r_{ij} +log \delta -log(1-\delta ))/ \tau)
\end{equation}
where $\delta \sim Uniform(0, 1)$ is the sampled Gumbel random variate. $\tau$ is a temperature constant used to control the degree of sharpening of the weight distribution; the closer $\tau$ is to $0$, the more  $w^r_{ij}$ tends to be binary distribution. Then we separated the heterogeneous graph dynamics into homophilic and heterophilic graphs based on the relational importance scores of the obtained bipartite subgraphs.

\subsection{Dynamic Homophily-Heterophily Separation}
To capture the homophily and heterophily of specific types of nodes, we use the relational importance of bipartite subgraphs to construct the potential homophilic and heterophilic graphs, considering the directionality of bipartite subgraphs, in bipartite graphs $G^r$, if $k$ has a higher importance to node $i$, and in bipartite subgraph $G^{r^{-1}}$, $j$ has a higher importance to $k$. This implies that there are deeper latent connections between $(i,j)$, such as movies of the same genre or papers on the same topic. Therefore, they are more likely to belong to the homophilic node pairs, and on the contrary, it is more likely to belong to the heterophilic node pairs. Based on the relation importance, we compute the weights of the homophilic and heterophilic graphs guided by the edge type $r$:
\begin{equation}
    a^{r,ho}_{i,j} = \sum_{k \in \mathcal{N}_{j}^{r}}w^r_{i,k}w^{r^{-1}}_{k,j}
\end{equation}

\begin{equation}
    a^{r,he}_{i,j} = \sum_{k \in \mathcal{N}_{j}^{r}}(1-w^r_{i,k})(1-w^{r^{-1}}_{k,j})
\end{equation}
where $a^{r,ho}_{i,j}$ and $a^{r,he}_{i,j}$ are the node pair weights of the homophilic and heterophilic graphs consisting of specific types of nodes, and $r^{-1}$ denotes the inverse relationship of r. Unlike latGRL~\cite{latgrl} which needs to pre-process the similarity matrix $topk$ sampling to get the refined multiplex graph before training, we adopt an end-to-end approach to train the potential homophilic and heterophilic graphs, which reduces the dependence on hyperparameters. Also based on relational importance, we can get homogeneous graphs under any type of node without retraining for different types of nodes. This implies that our method provides better scalability.

After the above operations, we obtain multiple homophilic graphs and heterophilic graphs corresponding to the relation $r$. We perform low-pass filtering on the homophilic graphs to preserve the common information between similar nodes, and high-pass filtering on the heterophilic graph to preserve the unique information between different classes of nodes, to avoid feature confusion of the nodes of different classes. We adopt the same encoding method as SGC~\cite{sgc}, the coding process is as follows:
\begin{equation}
    \mathbf{homo}_i^{r,(l)} = \frac{1}{| \mathcal{N}_{i} |} \sum_{j \in \mathcal{N}_{i}}a^{r,ho}_{i,j}x_j^{(l-1)},\mathbf{h}_i^{r,ho} = \mathbf{W}^{r,ho}\mathbf{homo}_i^{r,(l)}
\end{equation}

\begin{equation}
    \mathbf{hete}_i^{r,(l)} = \frac{1}{| \mathcal{N}_{i} |} \sum_{j \in \mathcal{N}_{i}}(x_i-a^{r,he}_{i,j}x_j^{(l-1)}),\mathbf{h}_i^{r,he} = \mathbf{W}^{r,he}\mathbf{hete}_i^{r,(l)}
\end{equation}
where $\mathbf{W}^{r,ho}$ and $\mathbf{W}^{r,he}$ are learned weight
 matrix. $\mathcal{N}_i$ is the set of neighbours of node $i$ in the homogeneous graph. The $\mathbf{h}_i^{r,ho}$ captures the shared information(homophily) between nodes of the homogeneous graph synthesized under the guidance of the heterogeneous relation $r$, while $\mathbf{h}_i^{r,he}$ captures the discrepancy information(heterophily).
% projection layer
%  \begin{equation}
%      \mathbf{z}_i = \text{projection}(\mathbf{h}_i),
%     \mathbf{z}^{r,ho}_{i}= \text{projection}^{r}_{ho}(\mathbf{h}_i^{r,ho}),
%     \mathbf{z}^{r,he}_{i}=\text{projection}^{r}_{he}(\mathbf{h}_i^{r,he})
%  \end{equation}

\subsection{Multi-Relation Contrastive Loss}
Then, we maximize the mutual information of the heterogeneous representations based on the network scheme and the homophilic and heterophilic representations under multiple edge types $r$. Specifically, we regard the heterogeneous representation as anchor points, project the different view representations to the potential space using the learnable MLP, and maximize the consistent information of the other representations using the InfoNCE contrastive loss~\cite{infonce}:
\begin{equation}
    \mathcal{L}(\mathbf{z}_i,\mathbf{z}^{r,ho}_{i}) = -  \frac{1}{|\mathcal{N}_{i}|}\left(\log \frac{\sum_{{v_j} \in \mathcal{P}^{r,ho}_{i}} e^{{\langle}\mathbf{z}_{i}, \mathbf{z}_{j}^{r,ho}\rangle/\tau_{c}}}{\sum_{v_{k} \in \mathcal{V} \setminus \mathcal{P}^{r,ho}_{i}} e^{\langle \mathbf{z}_{i}, \mathbf{z}_{k}^{r,ho}\rangle/\tau_{c}}} \right)
\end{equation}
where $\mathbf{z}_i$ and $\mathbf{z}^{r,ho}_{i}$ denote the projected representation, $\tau_c$ is the temperature constant, $\langle,\rangle $ is the cosine similarity, and $\mathcal{P}^{r,ho}_{i}$ denotes the set of positive samples of node $i$. We utilize the product of the cosine similarity of the obtained homogeneous representation and the edge weights under the corresponding view as the sampling weights: $\mathbf{p}^{r,ho}_{i,j} = a^{r,ho}_{i,j}\langle \mathbf{h}^{r,ho}_{i}, \mathbf{h}^{r,ho}_{j}\rangle $. We choose the top $k$ nodes with the highest similarity to node $i$ as their positive samples. 

To learn the shared information between the nodes in the homophilic view and the discriminative information of the nodes themselves in the heterophilic view, we contrast the anchored representations to learn them separately, and the loss of the complete view under a single relationship $r$ has a composition of homophilic and heterophilic perspectives, expressed as follows:
\begin{equation}
    \mathcal{L}_r^{ho} = \mathcal{L}(\mathbf{z}_i,\mathbf{z}^{r,ho}_{i}) + \mathcal{L}(\mathbf{z}^{r,ho}_{i},\mathbf{z}_i)
\end{equation}
\begin{equation}
    \mathcal{L}_r^{he} = \mathcal{L}(\mathbf{z}_i,\mathbf{z}^{r,he}_{i}) + \mathcal{L}(\mathbf{z}^{r,he}_{i},\mathbf{z}_i)
\end{equation}
The overall loss consists of all the relations $\mathcal{R}$ corresponding under the current node type.
\begin{equation}
    \mathcal{L}_{c} = \sum_{r \in \mathcal{R}}(\mathcal{L}_r^{ho} + \mathcal{L}_r^{he})
\end{equation}
By optimizing the above loss, we use relational importance to bootstrap the synthetic graph to learn the homophilic and heterophilic information under different semantic views while preserving the structural heterogeneity of the heterogeneous graph. In contrast, the method based on multiple meta-path views preserves semantic heterogeneity, but the heterogeneity of nodes is discarded for a single node type. However, the RASH introduces a new approach to learning relational importance through higher-order information of heterogeneous edges, by which we can consider both homophilic and heterophilic information of multiple types of nodes.

