Recall that $s$-bands cannot cross themselves or one another. Hence when we produce such homotopies for each such pair of $s$-edges, we can complete a null homotopy for $\alpha$ in $X-C$ by finding homotopies for the loops of Figure \ref{FigR} comprised of segements of $\alpha$ with no $s$-edges and $\delta_i$ type segments. Each of these loops belongs to $k\Gamma(\mathcal Q_2)-D$ for some $k\in S$. By ($\ast$) these loops are homotopically trivial in $X-C$. Combining these homotopies with the $H_{(e,\bar e)}$ homotopies (see Figure \ref{FigR}) creates a null homotopy for $\alpha$ in $X-C$. 
\end{proof}

Suppose $v$ is a vertex of $\Gamma_1$ (the Cayley 2-complex of the group $F(a,b)\times F(c,d)$ with respect to $\{a,b,c,d\}$) then there is a unique geodesic edge path $(\alpha, \beta)$ in $\Gamma_1$ from the identity vertex $\ast$ to $v$ where the labeling of $\alpha$ and $\beta$ are geodesics in $F(a,b)$ and $F(c,d)$ respectively. Call this path {\it the $F(a,b)-F(c,d)$ geodesic}.  Note that the (unique) edge path $(\beta', \alpha')$ at $\ast$ where $\beta'$ and $\alpha'$ have the same labeling as $\beta$ and $\alpha$ respectively also defines a geodesic in $\Gamma_1$ to $v$. Call this path {\it the $F(c,d)-F(a,b)$ geodesic}. For $v\in \Gamma_1$ and integer $n\geq 0$, let $N(v,n)$ be the ball of radius $n$ about $v$ in $\Gamma_1$ so $N(v,n)$ is the full subgraph of $\Gamma$ with vertices the set of all vertices $w$ such that there is a geodesic edge path of length $\leq n$ from $v$ to $w$. Call an edge path in $\Gamma_1$ with all edge labels $t\in Q\subset \{a,b,c,d\}^{\pm 1}$ a $Q$-path. Call an even length path in $\Gamma_1$ with alternating $\pm 1$ exponents a {\it $K$-path}. Suppose $\tau$ is an $\{a,b\}^{\pm 1}$ path at the vertex $v\in\Gamma_1$ and $\gamma$ is a $\{c,d\}^{\pm 1}$ path at $v$. Let $\gamma'$ ($\tau'$)  be the path at the end point of $\tau$ ($\gamma$) with the same labeling as $ \gamma$ ($\tau)$. There is a {\it product homotopy} between $(\tau, \gamma)$ and $(\gamma',\tau')$ (built from the commutation 2-cells of the relations $[a,b:c,d]$) in $v\Gamma(\mathcal Q_1)\subset X$. Each part of Lemma \ref {Ptrade} is clear. 

\noindent {\bf Note.} The exponents of the letters in $\tau$ are opposite to those of $\gamma$ in part (3), determining the $K$-path $\psi$.

\begin{lemma} \label{Ptrade} %{\bf (Ptrade)} 
Suppose $v$ is a vertex of $\Gamma_1$ and $(\alpha,\beta)$ is the $F(a,b)-F(c,d)$ geodesic from $\ast$ to $v$. 

\noindent (1) If $(\hat\alpha,\hat\beta)$ is the $F(a,b)-F(c,d)$ geodesic to a point of $vF(a,b)$ then $\hat \beta$ has the same labeling as $\beta$. The $F(c,d)-F(a,b)$ geodesic to any point of $vF(c,d)$ has the form $(\alpha, \bar\beta)$. 

\medskip

\noindent (2) If the last edge label of $\alpha$ is $a$ and $\gamma$ is a geodesic $t$-path at $v$ for $t\in \{a,b,b^{-1}\}$ then $(\alpha, \beta,\gamma)$ is geodesic so that $((\alpha,\gamma'),\beta')$ is the $F(a,b)-F(c,d)$-geodesic from $\ast$ to the end point of $\gamma$, where $\gamma'$ (respectively $\beta'$) has the same labeling as does $\gamma$ (respectively $\beta$). In particular, if $v\not \in N(\ast, n)$ then no point of $\gamma$ is in $N(\ast, n)$ (in fact, $\gamma$ moves geodesically away from $\ast$).  Similarly if the last letter of $\alpha$ is $a^{-1}$, $b$ or $b^{-1}$ or the last letter of $\beta$ is $c$, $c^{-1}$, $d$ or $d^{-1}$. 
In particular, for any vertex $v$ in $\Gamma_1$ either every $a$-path at $v$  or every $b$-path at $v$ moves geodesically away from $\ast$. Similarly for $c$ and $d$ paths, $a^{-1}$ and $b^{-1}$-paths, and $c^{-1}$ and $d^{-1}$ paths at $v$.  

\medskip

\noindent (3) Suppose $\tau$ is an $\{a,b\}$-path of length $k$ in $\Gamma_1-N(\ast, m)$ from $v$ to $w$. Say the last letter of $\beta$ is $c$ or $c^{-1}$ (respectively $d$ or $d^{-1}$). If $\gamma$ is a $d^{-1}$ (respectively $c^{-1}$) path at $w$ (see the above Note), then $(\tau, \gamma)$ is homotopic to $(\gamma',\tau')$ (a path at $v$ where $\tau'$ and $\gamma'$ have the same labeling as $\tau$ and $\gamma$ respectively)  by a (product) homotopy in $\Gamma(\mathcal Q_1)-N(\ast,n)$ (statement (2) implies that each vertex of the product homotopy is in $\Gamma(\mathcal Q_1)-N(\ast,n)$). Furthermore, if $\gamma$ has length equal to the length of $\tau$ then the $K$-path $\psi$ at $v$ obtained by alternating letters of $\tau$ and $\gamma$ is homotopic to $(\tau,\gamma)$ by a homotopy with image in $\Gamma(\mathcal Q_1)-N(\ast,n)$. (Figure \ref{FigP}).

Similarly, if $\tau$ is an $\{a^{-1},b^{-1}\}$, $\{c,d\}$ or $\{c^{-1},d^{-1}\}$-path then there is a corresponding $(c)$ or $(d)$, $(a^{-1})$ or $(b^{-1})$, $(a)$ or $(b)$-path $\gamma$ respectively. $\square$
\end{lemma}

\begin{lemma} \label{F2P}% {\bf (F2P)}
Suppose $\tau$ is an edge path in $\Gamma(\mathcal Q_1) -N(\ast, m)$ with exponent sum equal to $0$. Then $\tau$ is homotopic to a $K$-path by a homotopy in $\Gamma(\mathcal Q_1)-N(\ast, m)$. 
\end{lemma}


