\subsection{Disk cotangent bundle of 3-dimensional  ellipsoids $\mathcal{E}(1,1,c,c)$}
\begin{proof}[Proof of Theorem \ref{thm: highellips}]


Let's consider $ D^*\mathcal{E}(1,1,c,c) \subset \mathbb{C}^4$ given by:

\begin{equation}\label{eq11cc}
D^*\mathcal{E}(1,1,c,c):= \left\{
  \xi +i \eta \in \mathbb{C}^4 \;\middle|\;
  \begin{aligned}
  & \xi_1^2+\xi_2^2+ \frac{\xi_3^2}{c^2}+\frac{\xi_4^2}{c^2}=1 \\
  & \xi_1\eta_1+\xi_2\eta_2+ \frac{\xi_3\eta_3}{c^2}+\frac{\xi_4\eta_4}{c^2}=0\\
  & |\eta|^2<1
  \end{aligned}
\right\},
\end{equation}
with the symplectic form: $\omega=\sum d\xi_j \wedge d\eta_j$. Define the $T^2$-action in $D^*\mathcal{E}(1,1,c,c)$ given by:
\[
\scalebox{0.95}{$
\begin{pmatrix}
	\xi_1\\
	\xi_2\\
	\xi_3\\
	\xi_4\\
	\eta_1\\
	\eta_2\\
	\eta_3\\
	\eta_4
\end{pmatrix} \longmapsto
\begin{pmatrix}
	\cos 2\pi \theta_1 & -\sin 2\pi\theta_1 & 0 & 0 & 0 & 0& 0 & 0 \\
	\sin 2\pi\theta_1 & \cos 2\pi\theta_1 & 0 & 0 & 0 & 0& 0 & 0\\
	0&0&\cos 2\pi\theta_2 & -\sin 2\pi\theta_2&0&0&0& 0\\
	0&0&\sin 2\pi\theta_2 & \cos 2\pi\theta_2&0&0&0& 0\\
	0&0&0&0& \cos2\pi\theta_1 & -\sin 2\pi\theta_1 & 0&0 \\
	0&0&0&0& \sin 2\pi\theta_1 & \cos 2\pi\theta_1 & 0&0 \\
	0&0&0&0&0&0&\cos2\pi\theta_2 & -\sin 2\pi\theta_2\\
	0&0&0&0&0&0&\sin2\pi\theta_2 & \cos 2\pi\theta_2\\
\end{pmatrix}
\begin{pmatrix}
	\xi_1\\
	\xi_2\\
	\xi_3\\
	\xi_4\\
	\eta_1\\
	\eta_2\\
	\eta_3\\
	\eta_4
\end{pmatrix}
$}
\]

This action has moment map $\mu = (\mu_1, \mu_2) := 2\pi (\xi_1 \eta_2 - \xi_2 \eta_1, \xi_3 \eta_4 - \xi_4 \eta_3)$. To avoid overwhelming the reader with notation, we will omit the factor of $2\pi$ for now and instead rescale the final moment map by this factor at the end. Using these definitions, the Cauchy-Schwarz inequality and \eqref{eq11cc}, we have that:
\[
\left| \mu_1 \pm \frac{\mu_2}{c} \right| = \left| \xi_1 \eta_2 - \xi_2 \eta_1 \pm \frac{\xi_3 \eta_4 - \xi_4 \eta_3}{c} \right| \leq |\eta| \sqrt{\xi_1^2 + \xi_2^2 + \frac{\xi_3^2}{c^2} + \frac{\xi_4^2}{c^2}} = |\eta|,
\]
and therefore:
\begin{equation}\label{maxeta_he}
	|\eta| \geq \max \left\{ \left| \mu_1 + \frac{\mu_2}{c} \right|, \left| \mu_1 - \frac{\mu_2}{c} \right| \right\}.
\end{equation}


This inequality will be useful later. We consider the map defined by:
\begin{align*}
	f: D^*\mathcal{E}(1,1,c,c) &\longrightarrow \mathbb{R}^3,\\
	(\xi, \eta) &\longmapsto (t_1,t_2,|\eta|^2):=((\xi_1^2 + \xi_2^2) - (\eta_1^2 + \eta_2^2) , 2 (\xi_1 \eta_1 + \xi_2 \eta_2), |\eta|^2).
\end{align*}

We define $f_\lambda:=f|_{\mu^{-1}(\lambda)}$. To use Proposition \ref{generalmeth2}, we need to prove that $f(D^*\mathcal{E}(1,1,c,c) \cap \mu^{-1}(\lambda))$ is simply connected for every $\lambda$, and that the induced map $\widetilde{f}_{\lambda}$ is a bijection. In the following claim, we prove that $f(D^*\mathcal{E}(1,1,c,c) \cap \mu^{-1}(\lambda))$ is indeed simply connected and provide a foliation of this set given by the norm of the cotangent fibres. By abuse of notation, we refer to fixed values of the moment maps and a fixed value of the norm of the cotangent fibres as $\mu_1, \mu_2$, and $|\eta|$, respectively.

\begin{clm} \label{clm: highellips}
\begin{enumerate}[label=(\roman*)]
    \item \label{claim_he: i} The following relation holds:
    \begin{equation} \label{eq: highellips}
        \left(2\mu_1^2 - 2\frac{\mu_2^2}{c^2} + 2|\eta|^2 + t_1(1 - |\eta|^2) + \frac{(1 - c^2)t_2^2}{2}\right)^2 = (1 + |\eta|^2)^2 \left(t_1^2 + t_2^2 + 4\mu_1^2\right).
    \end{equation}

    \item \label{claim_he: ii} For fixed $\mu_1, \mu_2$ and $|\eta| \neq 0$, the locus in the plane $(t_1, t_2)$ defined by equation \eqref{eq: highellips} is a closed curve or a point. For $|\eta| = 0$, we have $\mu_1 = \mu_2 = 0$, and the locus is $[0, 1] \times \{0\}$, i.e., the interval $[0, 1]$ along the $t_1$-axis.

    \item \label{claim_he: iii} The image $f(D^*\mathcal{E}(1,1,c,c) \cap \mu^{-1}(\lambda))$ is simply connected and can be foliated using the norm of the cotangent fibers.

    \item \label{claim_he: iv} The induced map $\widetilde{f}_\lambda$ is a bijection onto its image.
\end{enumerate}
\end{clm}

\begin{proof}[Proof of Claim \ref{clm: highellips}]

\noindent\textbf{(i)} To prove the relation \eqref{eq: highellips}, consider the following equations derived from the system:
\begin{align}
    \mu_1^2 + \frac{t_2^2}{4} &= (\xi_1^2 + \xi_2^2)(\eta_1^2 + \eta_2^2), \label{eq_he:eta1eta2p1} \\
    \xi_1^2 + \xi_2^2 &= t_1 + (\eta_1^2 + \eta_2^2), \label{eq_he:eta1eta2p2} \\
    \frac{\mu_2^2}{c^4} + \frac{t_2^2}{4} &= \frac{(\xi_3^2 + \xi_4^2)(\eta_3^2 + \eta_4^2)}{c^4}, \label{eq_he:eta3eta4p1} \\
    \frac{\xi_3^2 + \xi_4^2}{c^2} &= (\eta_3^2 + \eta_4^2) + 1 - |\eta|^2 - t_1. \label{eq_he:eta3eta4p2}
\end{align}

Solving the system for $\eta_1^2 + \eta_2^2$ and $\eta_3^2 + \eta_4^2$ yields:
\begin{align}
    \eta_1^2 + \eta_2^2 &= \frac{-t_1 + \sqrt{t_1^2 + 4\mu_1^2 + t_2^2}}{2}, \label{eq_he:normeta1} \\
    \eta_3^2 + \eta_4^2 &= \frac{t_1 + |\eta|^2 - 1 + \sqrt{(t_1 + |\eta|^2 - 1)^2 + 4\frac{\mu_2^2}{c^2} + c^2 t_2^2}}{2}. \label{eq_he:normeta2}
\end{align}

Adding \eqref{eq_he:normeta1} and \eqref{eq_he:normeta2}, and performing algebraic simplifications, gives equation \eqref{eq: highellips}.

\vspace{1em}
\noindent\textbf{(ii)} For $|\eta| = 0$, it follows that $\mu_1 = \mu_2 = t_2 = 0$ and $t_1 \in [0, 1]$, hence the locus is $[0,1] \times \{0\}$.

For $|\eta| \neq 0$, equation \eqref{eq: highellips} can be rewritten as:
\begin{equation} \label{eq:closed_curve}
\begin{aligned}
    \frac{1}{1 + |\eta|^2} \left(2|\eta|^2 t_1 - (1 - |\eta|^2)\left(\mu_1^2 - \frac{\mu_2^2}{c^2} + |\eta|^2 + \frac{(1 - c^2)t_2^2}{4}\right)\right)^2 \\
    = \left(\mu_1^2 - \frac{\mu_2^2}{c^2} + |\eta|^2 + \frac{(1 - c^2)t_2^2}{4}\right)^2 - |\eta|^2(t_2^2 + 4\mu_1^2).
\end{aligned}
\end{equation}

When $c = 1$, this is the equation of an ellipse. For $c \neq 1$, the right-hand side of \eqref{eq:closed_curve} is a quartic polynomial in $t_2$ that tends to $+\infty$ as $t_2 \to \pm\infty$. Due to its structure, it has at most four real roots, and the region where it is non-negative consists of a compact set (containing $t_2 = 0$) and two unbounded components. In our analysis, we focus on the compact set around $t_2 = 0$ where the polynomial is non-negative and the corresponding solution set is well-defined:

\begin{equation} \label{eq:intervalt2}
|t_2| \leq 2 \sqrt{ \frac{
\left(\frac{\mu_2^2}{c^2} - \mu_1^2\right)(1 - c^2) 
+ |\eta|\left( |\eta|(1 + c^2) 
- 2 \sqrt{ \left(\left(\frac{\mu_2^2}{c^2} - \mu_1^2 c^2\right)(1 - c^2) + c^2 |\eta|^2\right) }
\right)
}{(1 - c^2)^2}}.
\end{equation}
This interval degenerates to zero whenever
\[
|\eta| = \left|\mu_1 \pm \frac{\mu_2}{c}\right|.
\]
By \eqref{maxeta_he},
\[
|\eta| \in \left[\max\left\{ \left|\mu_1 + \frac{\mu_2}{c}\right|, \left|\mu_1 - \frac{\mu_2}{c}\right| \right\}, 1\right),
\]
so the interval defined by the inequality in  \eqref{eq:intervalt2}, collapses to a point whenever
\[
|\eta| = \max\left\{ \left|\mu_1 + \frac{\mu_2}{c}\right|, \left|\mu_1 - \frac{\mu_2}{c}\right|\right\}.
\]


For each $t_2$ in the interior of the interval given by  \eqref{eq:intervalt2}, where the right-hand side of \eqref{eq:closed_curve} is strictly positive, there are exactly two corresponding values of $t_1$ satisfying the equation. At the endpoints of the interval, where the polynomial vanishes, there is exactly one solution for $t_1$. Since the right-hand side depends continuously on $t_2$, and the solutions change continuously, the full set of solutions to \eqref{eq:closed_curve} for $t_2$ in the interval \eqref{eq:intervalt2} form a simple closed curve in the $(t_1, t_2)$ plane. We denote these simple closed curves by $\gamma_{\mu, |\eta|}$.

\vspace{1em}
\noindent\textbf{(iii)} This follows directly from (ii). The sets $\gamma_{\mu, |\eta|}$ defined by equation \eqref{eq:closed_curve} form a family of closed curves. As $|\eta|$ becomes smaller, these closed curves retract to a line if $\mu_1 = \mu_2 = 0$, or to a point otherwise. This gives a foliation of the image by level sets of the norm in the cotangent fiber.

\vspace{1em}
\noindent\textbf{(iv)} To prove the injectivity of $\widetilde{f}_\lambda$, we show that the preimage of each point consists of exactly one $T^2$-orbit.

From equations \eqref{eq_he:normeta1}, \eqref{eq_he:normeta2}, \eqref{eq_he:eta1eta2p2}, and \eqref{eq_he:eta3eta4p2}, we see that the quantities $\xi_1^2 + \xi_2^2$, $\eta_1^2 + \eta_2^2$, $\xi_3^2 + \xi_4^2$, and $\eta_3^2 + \eta_4^2$ are uniquely determined by $t_1$, $t_2$, and $|\eta|$.

Consider first the $S^1$-action associated to $\mu_1$. If $\xi_1^2 + \xi_2^2 = 0$, then the base component vanishes, and the fiber norm $\eta_1^2 + \eta_2^2$ is fixed; thus, the orbit is determined by rotations in the plane $(\eta_1, \eta_2)$, yielding a unique $S^1$-orbit. If instead $\xi_1^2 + \xi_2^2 \neq 0$, we may use the $S^1$-action to set $\xi_1 = 0$. In this case, the conditions
\[
\eta_1 = -\frac{\mu_1}{\xi_2}, \qquad \eta_2 = \frac{t_2}{\xi_2}
\]
determine the fiber coordinates uniquely, so again, the orbit is uniquely specified. A completely analogous argument applies to the $S^1$-action associated to $\mu_2$.

We conclude that each point in the image has a unique $T^2$-orbit in its preimage, establishing that $\widetilde{f}_\lambda$ is injective.
\end{proof}

To construct an almost toric fibration on \( D^*\mathcal{E}(1,1,c,c) \), we start by examining the foliation induced by the norm of the cotangent fibers. This foliation collapses the zero section to a point in the base diagram, similarly to the case of \( D^*S \). However, for the level set \( \mu_1 = \mu_2 = 0 \), we have the freedom to choose a different foliation. In particular, we may select a foliation consisting of simple closed curves that retract to a point, which gives us flexibility in shaping the base diagram and controlling the singularities.

According to the final part of the proof of Proposition~\ref{generalmeth2}, the singular fibers of the Lagrangian torus fibration correspond to those values of \( p \) for which \( f^{-1}(p) \cap \mu^{-1}(\lambda) \) is not homeomorphic to \( T^2 \). These singularities are associated with fixed points of the circle actions generating \( \mu_1 \) and \( \mu_2 \). 

The fixed points of the circle action associated with \( \mu_1 \) occur where \( \xi_1 = \xi_2 = \eta_1 = \eta_2 = 0 \). From the defining equations~\eqref{eq11cc}, this implies \( \mu_1 = t_1 = t_2 = 0 \), while \( \mu_2 \) varies in the interval \( (-1, 1) \). On the other hand, the fixed points of the circle action associated with \( \mu_2 \) satisfy \( \xi_3 = \xi_4 = \eta_3 = \eta_4 = 0 \), which implies \( \mu_2 = t_2 = 0 \), \( t_1 = 1 \), and \( \mu_1 \in (-1,1) \).

To ensure the base diagram contains only nodal singularities, we choose a foliation on \( f(D^*\mathcal{E}(1,1,c,c) \cap \mu^{-1}(0)) \) consisting of simple closed curves that retract to a point, and such that no curve intersects both \( (0,0,0) \) and \( (1,0,0) \). Note that in this case, the \( T^2 \)-action does not collapse to a point, since \( |\xi| = 0 \) is never attained on this space.

We now proceed to determine the shape of the base diagram, following the construction in~\cite[Section 2]{achigandrango2024singular}. For this purpose, we return to using the foliation induced by the norm of the cotangent fibers. It is important to observe that the boundary of the base diagram remains unchanged under different choices of foliation; indeed, it is determined by the image of the hypersurface \( |\eta| = 1 \).

Now we compute, for $|\eta|$ fixed, the symplectic area $\mathcal{A}_c(\mu, |\eta|)$ of a disk inside $D^*\mathcal{E}(1,1,c,c)$ with boundary on the Lagrangian $L_{\mu,|\eta|}$ that projects to the curve $\gamma_{\mu, |\eta|}$ in \ref{claim_he: iii}. Notice that we can act with the $T^2$-action on  $f^{-1}(p) \cap \mu^{-1}(\lambda)$ and assume $\xi_1=\xi_3 = 0$. There is only one loop inside $f^{-1}(\gamma_{\mu, |\eta|}) \cap \mu^{-1}(\lambda)$ satisfying \eqref{eq11cc} with $\xi_1=\xi_3 = 0$. We will use this loop to compute the area of the disk.

\begin{align*}
	\mathcal{A}_c(\mu, |\eta|)= \int_D \omega &= \int_{\partial D} (\xi_1 d\eta_1+ \xi_2 d\eta_2+ \xi_3 d\eta_3+\xi_4d\eta_4), \\
	&= \int_{\partial D} (\xi_2 d\eta_2+ \xi_4 d\eta_4), \quad \text{since $\xi_1=\xi_3=0$}.
\end{align*}
By using the defining equations for the case $\xi_1=\xi_3=0$, we get:
\[\eta_4=-\sqrt{\frac{(|\eta|^2c^2\xi_4^2-\mu_2^2c^2)(c^2-\xi_4^2)-c^4\mu_1^2\xi_4^2}{\xi_4^2(\xi_4^2+c^2(c^2-\xi_4^2))}},\]
\[\xi_2=\sqrt{1-\frac{\xi_4^2}{c^2}},\]
\[\eta_2=-\frac{\xi_4\eta_4}{c^2\xi_2}.\]
From this, we can get an integral over an interval inside the possible values of $\xi_4$. The interval that we are going to use is $(\xi_4^{min},\xi_4^{max})$, where $$\xi_4^{min}=\frac{1}{|\eta|}\sqrt{\frac{\mu_2^2 +c^2(|\eta|^2- \mu_1^2) - \sqrt{-4 \mu_2^2 c^2 |\eta|^2 + (\mu_2^2 + c^2 (|\eta|^2-\mu_1^2))^2}}{2}},$$ and $$\xi_4^{max}=\frac{1}{|\eta|}\sqrt{\frac{\mu_2^2 +c^2(|\eta|^2- \mu_1^2) + \sqrt{-4 \mu_2^2 c^2 |\eta|^2 + (\mu_2^2 + c^2 (|\eta|^2-\mu_1^2))^2}}{2}}.$$ Let $$A:=A(\mu_1,\mu_2,|\eta|,c):=-4 \mu_2^2|\eta|^2 c^2  + (\mu_2^2 + c^2 (|\eta|^2-\mu_1^2))^2,$$ and  $$B:=B(\mu_1,\mu_2,|\eta|,c):=\mu_2^2-\mu_1^2c^2+\sqrt{A} + c^2 |\eta|^2.$$ 

After relentless computations, we get:
\begin{equation}\label{eq: boundary_11cc}
\begin{aligned}
    \mathcal{A}_c(\mu, |\eta|) &=2 \int_{\xi_4^{\min}}^{\xi_4^{\max}} \left(\frac{1}{c\xi_4(c^2-\xi_4^2)}\sqrt{((|\eta|^2\xi_4^2-\mu_2^2)(c^2-\xi_4^2)-c^2\mu_1^2\xi_4^2)(\xi_4^2+c^2(c^2-\xi_4^2))} \right) d\xi_4 \\
    &=\frac{\sqrt{2}}{c} \sqrt{
    \frac{1}{
        (1 - c^2)B+ 2c^4 |\eta|^2 
    }
}  \left(
    \left(
            (1 - c^2)B+ 2c^4 |\eta|^2 
    \right) E\left(
        \frac{
            2  (1 - c^2)\sqrt{
                A
            }
        }{
            (1 - c^2)B+ 2c^4 |\eta|^2 
        }
    \right) \right. \\
    &- 
        2 (1 - c^2) (\mu_2^2 - \mu_1^2 c^2)
     F\left(
        \frac{
            2(1 - c^2) \sqrt{
                A
            }
        }{
            (1 - c^2)B+ 2c^4 |\eta|^2 
        }
    \right) -\frac{
        4c^4|\eta|^2\mu_2^2
    }{
        B
    } \Pi\left(
            \frac{
                2 \sqrt{
                    A
                }
            }{
                B
            },
            \frac{
            2 (1 - c^2)\sqrt{
                A
            }
        }{
            (1 - c^2)B+ 2c^4 |\eta|^2
        }
        \right)
 \\
    &\left.
        +\frac{
        4c^4|\eta|^2\mu_1^2
    }{
       B- 2c^2  |\eta|^2 
    }\Pi\left(
            \frac{
                2 \sqrt{
                    A
                }
            }{
                B- 2c^2 |\eta|^2
            },
            \frac{
            2 (1 - c^2)\sqrt{
                A
            }
        }{
            (1 - c^2)B+ 2c^4 |\eta|^2
        }
        \right) \right).
\end{aligned}
\end{equation}
\end{proof}


The image of the base diagram \( (\mu_1, \mu_2, \mathcal{A}_c(\mu, |\eta|)) \) for \( |\eta| \leq 1 \) was generated using \textsc{Matlab} and is displayed in Figure~\ref{fig: convex_base_11cc}.





\subsection{The Lagrangian bidisk}
\begin{proof}[Proof of Theorem \ref{thm: lagbid}]

Recall that we define the Lagrangian bidisk as
\[
P_L = \{(p_1, p_2, q_1, q_2) \in \mathbb{R}^4 \mid p_1^2 + p_2^2 \leq 1,\ q_1^2 + q_2^2 \leq 1\},
\]
equipped with the standard symplectic form \( \omega = \sum dp_j \wedge dq_j \).

Define the circle action in $P_L$, given by:
\[ \begin{pmatrix}
	p_1\\
	p_2\\
	q_1\\
	q_2
\end{pmatrix} \longmapsto \begin{pmatrix}
	\cos2\pi\theta & -\sin 2\pi\theta & 0 & 0  \\
	\sin 2\pi\theta & \cos 2\pi\theta & 0 & 0 \\
	0&0&\cos2\pi\theta & -\sin 2\pi\theta\\
	0&0& \sin 2\pi\theta & \cos 2\pi\theta\\
\end{pmatrix} \begin{pmatrix}
	p_1\\
	p_2\\
	q_1\\
	q_2
\end{pmatrix}.\] 
This action has moment map $\mu = 2\pi( p_1 q _2 - p_2 q_1)$. Consider the fibration:
\begin{align*}
	f:P_L&\longrightarrow \mathbb{R}^2,\\
	(p,q)& \longmapsto (t_1,t_2),
\end{align*} where
\begin{align*}
t_1&=p_1q_1+p_2q_2,\\
	t_2&=p_1^2+p_2^2-q_1^2-q_2^2=|p|^2-|q|^2.
\end{align*}
Note that the fibres of this map are preserved by the circle action described above.

To use Proposition \ref{generalmeth2}, we need to prove that $f(P_L \cap \mu^{-1}(\lambda))$ is simply connected for every $\lambda\in [-2\pi,2\pi]$, and that $\widetilde{f}_\lambda$ is injective. With the following claim, we prove the necessary conditions. By abuse of notation, we refer to fixed values of the moment map and the norms of $p$ and $q$ as $\mu$, $|p|$, and $|q|$, respectively.

\begin{clm} \label{clm: lagbi}
\begin{enumerate}[label=(\roman*)]
    \item \label{claim_lagbi: i} The following relation holds:
    \begin{equation} \label{eq: lagbi}
        \mu^2 + 4\pi^2 t_1^2 = 4\pi^2 |p|^2 |q|^2.
    \end{equation}

    \item \label{claim_lagbi: ii} For fixed $\mu$ and $|p| > 0$, in the case $|p| \geq |q|$, the locus in the $(t_1, t_2)$-plane defined by equation \eqref{eq: lagbi} is a concave parabola contained in the half-plane $t_2 \geq 0$. For fixed $\mu$ and $|q| > 0$, in the case $|q| \geq |p|$, the locus is a convex parabola contained in the half-plane $t_2 \leq 0$. When $|p| = |q| = 0$, we obtain $\mu = t_1 = t_2 = 0$, corresponding to the single point $(0,0)$.

    \item \label{claim_lagbi: iii} The set $f(P_L \cap \mu^{-1}(\lambda))$ is simply connected.

    \item \label{claim_lagbi: iv} The induced map $\widetilde{f}_\lambda$ is injective.
\end{enumerate}
\end{clm}

\begin{proof}[Proof of Claim \ref{clm: lagbi}]
\noindent\textbf{(i)} The relation \eqref{eq: lagbi} follows by adding the following equations, obtained from the definition of the system:
\begin{align}
    \mu^2 &= 4\pi^2(p_1^2 q_2^2 - 2p_1 p_2 q_1 q_2 + p_2^2 q_1^2), \label{mulagbi} \\
    4\pi^2 t_1^2 &= 4\pi^2(p_1^2 q_1^2 + 2p_1 p_2 q_1 q_2 + p_2^2 q_2^2). \label{ylagbi}
\end{align}

\vspace{1em}
\noindent\textbf{(ii)} Fix $\mu$ and assume $|p| > 0$. In the case $|p| \geq |q|$, we have $t_2 \geq 0$. Substituting $|q|^2 = |p|^2 - t_2$ into \eqref{eq: lagbi}, we obtain:
\begin{equation} \label{eq: par+}
    |p|^2 t_2 = |p|^4 - \frac{\mu^2}{4\pi^2} - t_1^2,
\end{equation}
which describes a concave parabola in the half-plane $t_2 \geq 0$.

Similarly, when $|q| \geq |p|$, we have $t_2 \leq 0$. Replacing $|p|^2 = |q|^2 - t_2$ into \eqref{eq: lagbi} gives:
\begin{equation} \label{eq: par-}
    |q|^2 t_2 = -|q|^4 + \frac{\mu^2}{4\pi^2} + t_1^2,
\end{equation}
which is a convex parabola in the half-plane $t_2 \leq 0$.

In the case $|p| = |q| = 0$, equation \eqref{eq: lagbi} implies $\mu = t_1 = 0$, and $t_2 = 0$ by definition, so the solution is the single point $(0, 0)$.

\vspace{1em}
\noindent\textbf{(iii)} The set $f(P_L \cap \mu^{-1}(\lambda)) \cap \{t_2 \geq 0\}$ is foliated by the parabolas described in \eqref{eq: par+}, for $|p|^2 \in \left[\left|\frac{\lambda}{2\pi}\right|, 1\right)$. Similarly, the set $f(P_L \cap \mu^{-1}(\lambda)) \cap \{t_2 \leq 0\}$ is foliated by the parabolas in \eqref{eq: par-}, for $|q|^2 \in \left[\left|\frac{\lambda}{2\pi}\right|, 1\right)$. When \( |p|^2 = |q|^2 = \left|\frac{\lambda}{2\pi}\right| \), it follows from \ref{claim: i} that \( t_1 = 0 \), and clearly \( t_2 = 0 \) as well. Therefore, the image reduces to the single point \( (0, 0) \). Therefore, the full image $f(P_L \cap \mu^{-1}(\lambda))$ is simply connected.

\vspace{1em}
\noindent\textbf{(iv)} To show that $\widetilde{f}_\lambda$ is injective, we first note that equations \eqref{eq: par+} and \eqref{eq: par-} determine $|p|$ and $|q|$ uniquely for each point $(t_1, t_2)$. We now show that each fiber of $\widetilde{f}_\lambda$ consists of exactly one $S^1$-orbit.

If $|p| = 0$, then the unique orbit is given by rotating the coordinates $(q_1, q_2)$ with fixed $|q|$. If $|p| \neq 0$, we may use the $S^1$-action to set $p_1 = 0$, and the values of $q_1$ and $q_2$ are then uniquely determined by:
\[
q_1 = -\frac{\mu}{2\pi p_2}, \qquad q_2 = \frac{t_1}{p_2}.
\]
Thus, the orbit is uniquely specified in all cases.

This concludes the proof.
\end{proof}

In this case, we do not immediately get a foliation by simple closed curves of $f(P_L \cap \mu^{-1}(\lambda))$, but since it is simply connected, we can obtain one. By the last part of the proof of Proposition \ref{generalmeth2}, we know that the singular fibres of our Lagrangian torus fibration are determined by the cases where $f^{-1}(p) \cap \mu^{-1}(\lambda) \ncong S^1$. The set of fixed points of the  circle action related to $\mu$ only retracts when $p_1 = p_2 = q_1 = q_2 = 0$, and by the defining equations, this implies that $\mu = t_1 = t_2 = 0$. We can choose a foliation of $f(P_L \cap \mu^{-1}(0))$ given by simple closed curves that retract to a point different from $(0,0)$. 

Now we are going to obtain the shape of the base diagram as in \cite[Section 2]{achigandrango2024singular}. For this, note that the boundary of the base diagram does not change by changing the foliation; in fact, it is given by the limit when $\{|p|=1\} \cup \{|q|=1\}$. 

We now compute, for the boundary components \( \{|p| = 1\} \cup \{|q| = 1\} \), the symplectic area \( \mathcal{A}(\mu) \) of a disk inside \( P_L \) whose boundary lies in the limit Lagrangian projecting to the union of the curves defined by equations~\eqref{eq: par+} (for \( |p| = 1 \)) and~\eqref{eq: par-} (for \( |q| = 1 \)). These two curves join to form a closed, piecewise-smooth curve \( \gamma_\mu \).

Note that we may act with the \( S^1 \)-action on \( f^{-1}(p) \cap \mu^{-1}(\lambda) \) to fix \( q_1 = 0 \). There are exactly two loops in \( f^{-1}(\gamma_\mu) \cap \mu^{-1}(\lambda) \) satisfying \( q_1 = 0 \). We select one of them to compute the area of the corresponding disk.

For the part that projects to equation \eqref{eq: par+} with $|p|=1$, we obtain the parametrization given by $t$:
\begin{align*}
p_1&=\frac{\mu}{\sqrt{\mu^2+4\pi^2t^2}},\\
	p_2&=\frac{2\pi t}{\sqrt{\mu^2+4\pi^2t^2}},\\
	q_2&=\sqrt{\frac{\mu^2}{4\pi^2}+t^2},
\end{align*}
for $t\in \left[-\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2},\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2}\right]$.\\

For the part that projects to equation \eqref{eq: par-} with $|q|=1$, we obtain the parametrization given by $t$:
\begin{align*}
p_1&=\frac{\mu}{2\pi},\\
	p_2&=t,\\
	q_2&=1,
\end{align*}
	for $t\in \left[-\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2},\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2}\right]$.\\

	Now we calculate the symplectic area of the disc $D$ that has the cycle defined above as the boundary. The symplectic area is:
\begin{equation}\label{eq: bound_lagbi}
	\begin{aligned}
		\mathcal{A}(\mu)=\int_D \omega &=\int_{\partial D} p_1dq_1+p_2dq_2\\
		&=\int_{|p|=1} p_1dq_1+p_2dq_2+\int_{|q|=1} p_1dq_1+p_2dq_2\\
		&=\int_{|p|=1} p_2dq_2\\
		&=\int_{-\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2}}^{\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2}} \frac{4\pi^2t^2}{\mu^2+4\pi^2t^2}dt\\
		&=\left[t - \frac{\mu \cdot \arctan\left(\frac{2\pi \cdot t}{\mu}\right)}{2\pi}\right]_{-\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2}}^{\sqrt{1 - \left(\frac{\mu}{2\pi}\right)^2}}\\
		&=\frac{\sqrt{-\mu^2 + 4 \pi^2} - \mu \arctan \left(\frac{\sqrt{-\mu^2 + 4 \pi^2}}{\mu} \right)}{\pi}
	\end{aligned}
	\end{equation}
\end{proof}

\begin{rmk}
	To recover the result from \cite{ramos2017symplectic}, we perform the substitution $\mu = 2\pi \cos(\alpha/2)$ with $\alpha \in [0, 2\pi]$, and then apply the mutations as indicated in Figure~\ref{fig:convex_base_lagbi_2}. 
\end{rmk}





\section{Embedding results} \label{sec: per}

\subsection{Proof of Proposition \ref{prop: capacity_S^3}}

The idea to find embedded balls into $D^*S^3$ is by making use of Traynor's trick, introduced in \cite{Traynor1995SymplecticPC}, in the fibration obtained in Theorem \ref{thm: highellips}. The same approach could be used for the case of $D^*\mathcal{E}(1,1,c,c)$ as explained in Section \ref{sec: embres}. 

As remarked in \cite{Traynor1995SymplecticPC}, a weaker version of the Traynor trick holds in any dimension. In what follows we make a precise statement of such version and give a proof, for the sake of completeness.

\begin{definition}
Let 
\begin{align*}
D(r):&=\{(x,y)\in \mathbb{R}^2\mid x^2+y^2\leq r\},\\
SD(r):&=D(r)-\{x\geq 0,y=0\},\\
SD(r_1,\ldots,r_n):&=SD(r_1)\times\ldots\times SD(r_n),\\
\Delta^n(r):&=\{(x_1,\ldots,x_n)\in \mathbb{R}_{>0}^n\mid 0<x_1+\ldots+x_n<r\},\\
C^n(r):&=\{(y_1,\ldots,y_n)\in \mathbb{R}^n\mid 0<y_1,\ldots,y_n<r\}.
\end{align*}
\end{definition}

Notice that, the Lagrangian product $\Delta ^n(r)\times_L C^n(\pi)\subset \mathbb{C}^n$  has the same volume as the ball $B^{2n}(r)$ of radius $\sqrt{r}$.

The next lemma is due to McDuff, Polterovich and Traynor; and it is usually refered to as the Traynor trick.

\begin{lemma}\label{lem: traynor}
For every $\rho<r$, there exists a symplectic embedding $B^{2n}(\rho)\hookrightarrow \Delta^n(r)\times_L C^n(\pi)$.
\end{lemma}
\begin{proof}
Consider the map $\psi:\Delta^n(r)\times_L C^n(\pi)\rightarrow \textup{Int }B^{2n}(r)$ given by 
$$\psi(x_1,\ldots,x_n,y_1,\ldots,y_n)=(\sqrt{x_1}\cos(2y_1),-\sqrt{x_1}\sin(2y_1),\ldots,\sqrt{x_n}\cos(2y_n),-\sqrt{x_n}\sin(2y_n)).$$
It is not hard to see that this is a symplectic embedding and that 
$$\psi(\Delta^n(r)\times_L C^n(\pi))=\textup{Int }B^{2n}(r)\cap SD(r,\ldots,r).$$
Given $\rho<r$, choose an area-preserving diffeomorphism 
$$\sigma_{\rho}:D(\rho)\rightarrow SD(r),$$
such that, if $x^2+y^2\leq \alpha$ then $|\sigma_{\rho}(x,y)|^2\leq \alpha+(r-\rho)$. Hence, the map $\Psi_{\rho}:D(\rho)\times\cdots\times D(\rho)\rightarrow SD(r,\ldots,r)$ defined by
$$\Psi_{\rho}(x_1,y_1,\ldots,x_n,y_n)=(\sigma_{\rho}(x_1,y_1),\ldots,\sigma_{\rho}(x_n,y_n)),$$
is a symplectic embedding and $\Psi_{\rho}(B^{2n}(\rho))\subset \textup{Int }B^{2n}(r)\cap SD(r,\ldots,r)$. Therefore the map $\psi^{-1}\circ\Psi_{\rho}$ restricted to $B^{2n}(\rho)$ is a symplectic embedding into $\Delta^n(r)\times_L C^n(\pi)$. 
\end{proof}



\begin{lemma}\label{lem: embedding ball D*S^n}
For any $\varepsilon >0$ small enough, there exists a symplectic embedding $B^{6}(2\pi-\varepsilon)\hookrightarrow D^*S^3$.
\end{lemma}
\begin{proof}
Consider the pyramid $P_{\varepsilon} \subset \mathbb{R}^3$ defined as the convex hull of the following set of points:
\[
\left\{
\left(2\pi - \varepsilon, \frac{\varepsilon}{2}, \frac{\varepsilon}{4}\right),
\left(-2\pi + \varepsilon, \frac{\varepsilon}{2}, \frac{\varepsilon}{4}\right),
\left(0, 2\pi - \frac{\varepsilon}{2}, \frac{\varepsilon}{4}\right),
\left(0, \frac{\varepsilon}{2}, \pi - \frac{\varepsilon}{4}\right)
\right\}.
\]
Note that $P_{\varepsilon}$ is contained in the image of the moment map of the fibration described in Theorem~\ref{thm: highellips} for $c = 1$.

We now perform the transferring the cut operations as in \cite[Section 6.3]{achigandrango2024singular}. First, we apply the matrix
\[
\begin{pmatrix}
1 & 0 & 0 \\
0 & 1 & 0 \\
-1 & 0 & 1
\end{pmatrix}
\]
to the region defined by $\mu_1 < 0$. Then, we apply the matrix
\[
\begin{pmatrix}
1 & 0 & 0 \\
0 & 1 & 0 \\
0 & -1 & 1
\end{pmatrix}
\]
to the region defined by $\mu_2 < 0$. Finally, we apply the matrix
\[
\begin{pmatrix}
1 & 0 & 1 \\
0 & 1 & 0 \\
0 & 0 & 1
\end{pmatrix}
\]
to the entire image of the moment map.

As a result, the pyramid $P_{\varepsilon}$ is transformed into a new pyramid $\overline{P}_{\varepsilon}$, defined as the convex hull of the points:
\[
\left\{
\left(\frac{\varepsilon}{4}, \frac{\varepsilon}{2}, \frac{\varepsilon}{4}\right),
\left(2\pi - \frac{3\varepsilon}{4}, \frac{\varepsilon}{2}, \frac{\varepsilon}{4}\right),
\left(\frac{\varepsilon}{4}, 2\pi - \frac{\varepsilon}{2}, \frac{\varepsilon}{4}\right),
\left(\frac{\varepsilon}{4}, \frac{\varepsilon}{2}, 2\pi - \frac{3\varepsilon}{4}\right)
\right\}.
\]

By Lemma~\ref{lem: traynor}, for every $\delta > 0$ sufficiently small, there exists a symplectic embedding of the ball $B^6(2\pi - \varepsilon - \delta)$ into $\overline{P}_{\varepsilon} \times_L C^3(\pi)$. The claim then follows directly from the Symplectic Isotopy Extension Theorem due to Buhovsky and exposed in \cite{Schlenk2017SymplecticEP}, see their Lemma 8.1.
\end{proof}

We now prove the upper bound in Proposition \ref{prop: capacity_S^3}. For this, we define the Fermat quadric $Q^n$ in $\mathbb{C}P^{n+1}$ as 
$$Q^n=\{[z_0:\ldots:z_{n+1}]\in \mathbb{C}P^{n+1}\mid z_0^2+\ldots+z_{n+1}^2=0\}.$$
We also refer to $H_i\subset \mathbb{C}P^{n+1}$ as the hyperplane with vanishing $i$-th coordinate. It is not hard to see that the intersection $Q^n\cap H_{n+1}$ is naturally symplectomorphic to $Q^{n-1}$, and therefore, we decide to abuse the notation and denote this intersection as such. We next show how to identify $D^*S^{n}$ with $Q^n$, in a symplectic manner. The following proposition is folklore, we follow \cite{Oakley2013OnCL} and \cite{Adaloglou2022UniquenessOL}.

\begin{prop}\label{prop: embedding D*S^n into Q^n}
There exists a symplectomorphism $D^*S^n\hookrightarrow Q^n-Q^{n-1}$, where $Q^n-Q^{n-1}$ is considered with the restriction of the symplectic form $2\omega_{FS}$ induced by inclusion in $\mathbb{C}P^{n+1}$.
\end{prop}
\begin{proof}
We first claim there exists a symplectictomorphism from $B^{2n+2}(r)\subset (\mathbb{C}^{n+1},\omega_{std})$ to $(\mathbb{C}P^{n+1}-H_{n+1},r^2\omega_{FS})$. To see this, consider the map $\phi:B^{2n+2}(r)\rightarrow \mathbb{C}P^{n+1}-H_{n+1}$ given by 
$$\phi(z_0,\ldots,z_n)=\bigg[z_0:\ldots:z_n:i\sqrt{r^2-\sum|z_i|^2}\bigg].$$
The map $\phi$ factorizes trough maps $\widetilde{\phi}:B^{2n+2}(r)\hookrightarrow S^{2n+3}(r)\subset \mathbb{C}^{n+2}$ and $\pi_r:S^{2n+3}\rightarrow \mathbb{C}P^{n+1}$, where $\widetilde{\phi}$ is the map
$$\widetilde{\phi}(z_0,\ldots,z_n)=\bigg(z_0,\ldots,z_n,i\sqrt{r^2-\sum|z_i|^2}\bigg),$$
and $\pi_r$ the standard quotient by the scalar action. Notice that the natural inclusion $i_r:S^{2n+3}(r)\hookrightarrow \mathbb{C}^{n+2}$ satisfies
$$r^2\pi_r^*\omega_{FS}=i_r^*\omega_{std}.$$
From this we have that
$$\phi^*\omega_{FS}=\widetilde{\phi}^*\pi_r\omega_{FS}=\frac{1}{r^2}\widetilde{\pi}^*i_r^*\omega_{std}=\frac{1}{r^2}\omega_{std}.$$
The reason for the last equality to hold is given to the fact that the coordinate $z_{n+1}$ in the image of $\widetilde{\phi}$ is purely imaginary. The claim follows.

Note now that $D^*S^n$ is a subset of $B^{2n+2}(\sqrt{2})$. We show next that $\phi$ maps $D^*S^n$, seen as a subset of $B^{2n+2}(\sqrt{2})$, bijectively to $Q^n-Q^{n-1}$. To see this, let $[z_0:\ldots:z_n:z_{n+1}]\in \mathbb{C}P^{n+1}-H_{n+1}$, as $[z_0:\ldots:z_n:z_{n+1}]\in \phi(B^{2n+2}(\sqrt{2}))$, we have that
\begin{align*}
z_0^2+\ldots+z_n^2+z_{n+1}^2&=z_0^2+\ldots+z_n^2-2+\sum_{k=0}^n|z_k|^2,\\
&=\sum_{k=0}^n(x_k^2-y_k^2)+2i\sum_{k=0}^nx_ky_k-2+\sum_{k=0}^n(x_k^2+y_k^2),\\
&=2\bigg(\sum_{k=0}^nx_k^2-1\bigg)+2i\sum_{k=0}^nx_ky_k,
\end{align*}
and the result follows.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop: capacity_S^3}]
It follows from Lemma \ref{lem: embedding ball D*S^n} that $c_{Gr}(D^*S^3) \geq 2\pi$. On the other hand, by Proposition \ref{prop: embedding D*S^n into Q^n}, $D^*S^n$ embedds into $Q^n$ and given that $Q^n$ is a Hermitian symmetric space of compact type, we have by the main result in \cite{Loi2013SymplecticCO} that $c_{Gr}(Q^n) = 2\pi$. Then by monotonicity of symplectic capacities we have that $c_{Gr}(D^*S^n) \leq 2\pi$, and the result follows. 
\end{proof}

\begin{rmk}
It follows trivially from Proposition \ref{prop: ellipsoids}, and this was already observed in \cite{Ferreira2021SymplecticEI}, that there is a full packing of $D^*S^2$ by two symplectic balls of equal size. This, together with results in \cite{Gromov1985PseudoHC}, \cite{Mcduff1994SymplecticPA} and \cite{Biran1996SymplecticPI}, imply there is also a full packing of $D^*S^2$ by 8 or $2n$ balls of equal size, for $n\geq 9$. We can also see there are very full packings of $D^*S^2$ by 2, 5 and $n$ balls for $n\geq 7$.
\end{rmk}




