\section{Miscellaneous results}
\label{sec:appendix1}
Let $\a\in\R$ and $\ell^2_\a$ be a Hilbert of complex sesuences
with a norm $\|x\|_{\ell^2_\a}=(\sum_{n\in\Z}e^{2\a n}|x_n|^2)^{1/2}$
for $x=\{x_n\}_{n\in\Z}$.
The operators $e^{\pm\pd}-1$ have bounded inverse on $\ell^2_\a$
if $\a\ne0$. Indeed, we have the following.
\begin{lemma}
  \label{lem:pd-1}
Let $\a$ be a positive constant. Then
\begin{gather}
  \label{eq:pd-1a}
    \|e^{\pm\pd} f\|_{\ell^2_\a}=e^{\mp\a}\|f\|_{\ell^2_\a}\,,\\
  \label{eq:pd-1b}
    \|(e^\pd-1)^{-1}f\|_{\ell^2_\a}\le \frac{1}{1-e^{-\a}}\|f\|_{\ell^2_\a}\,,
    \quad
    \|(1-e^{-\pd})^{-1}f\|_{\ell^2_\a}\le \frac{1}{e^\a-1}\|f\|_{\ell^2_\a}\,.
  \end{gather}
\end{lemma}
\begin{proof}
 Eq.~\eqref{eq:pd-1a} follows immediately from the definitions.
 Since
 \begin{equation*}
(e^\pd-1)^{-1}=-\sum_{k\ge0}e^{k\pd}\,,\quad
(1-e^{-\pd})^{-1}=-\sum_{k\ge1}e^{k\pd}\quad\text{on $\ell^2_\a$,}
 \end{equation*}
 we have \eqref{eq:pd-1b} from \eqref{eq:pd-1a}.
\end{proof}

To estimate the $\ell^2_\a$-norm of Jost functions, we use the
 following.
 \begin{claim}
   \label{cl:H1-bound}
   For every $f\in H^1(\R)$,
   $\sum_{n\in\Z}|f(n)|^2\le 2\|f\|_{H^1(\R)}^2$.
 \end{claim}
 \begin{proof}
We may assume that $f$ is real-valued and
$f\in C^\infty_0(\R)$.
  For $x\in[n,n+1]$,
   \begin{align*}
     f(n)^2=& f(x)^2+2\int_x^n f(y)f'(y)\,dy
              \\ \le & f(x)^2+\int_n^x\{f'(y)^2+f(y)^2\}\,dy\,.
   \end{align*}
   Integrating the above over $[n,n+1]$ and adding the resulting equation
for each $n\in\Z$, we have
   \begin{align*}
 \sum_{n\in\Z} f(n)^2\le & \sum_{n\in\Z} \int_n^{n+1}\{f'(x)^2+2f(x)^2\}\,dx
\le 2\|f\|_{H^1(\R)}^2\,.
   \end{align*}
   Thus we complete the proof.
 \end{proof}


Let $\beta_+$ and $\beta_-$ be complex constants
satisfying $|\beta_+|<1<|\beta_-|$.
We will show that for any $f=\{f_n\}_{n\in\Z}\in \ell^p$, there exists
$a=\{a_n\}_{n\in\Z}\in \ell^p$ such that
\begin{equation*}
  a_{n+1}-(\beta_++\beta_-)a_n+\beta_+\beta_-a_{n-1}=f_n\quad\text{for
    $n\in\Z$.}
\end{equation*}
For a complex sequence $f=\{f_n\}_{n\in\Z}$, let
\begin{equation*}
 k*f(n):=\sum_{m\in\Z} k_mf_{n-m}\,.
\end{equation*}
Then, we have the following.
\begin{lemma}
  \label{lem:fundsol-seq}
Let $1\le p\le\infty$ and $k=\{k_n\}_{n\in\Z}$,
$k_n=\beta_+^n/(\beta_+-\beta_-)$ for $n\ge0$ and
$k_n=\beta_-^n/(\beta_+-\beta_-)$ for $n\le-1$. 
If $|\beta_+|<1<|\beta_-|$ and $f\in\ell^p$,
\begin{equation*}
  \|k*f\|_{\ell^p}\le \frac{1}{|\beta_+-\beta_-|}
  \left(\frac{1}{1-|\beta_+|}
    +\frac{1}{|\beta_-|-1}\right)\|f\|_{\ell^p}\,,
\end{equation*}
and $\mathbf{a}=k*f$ is a solution of
\begin{equation}
  \label{eq:sol-f}
  (e^\pd-\beta_+-\beta_-+\beta_+\beta_-e^{-\pd})\mathbf{a}=f\,.
\end{equation}
  \end{lemma}
  \begin{proof}
By the definition,
    \begin{equation}
 \label{eq:fund-sol}
k_{n+1}-(\beta_++\beta_-)k_n+\beta_+\beta_-k_{n-1}=\delta_{0n}\,,
\end{equation}
and  \eqref{eq:sol-f} follows from \eqref{eq:fund-sol}.
\par
Moreover,
\begin{equation*}
  \|k\|_{\ell^1}=\frac{1}{|\beta_+-\beta_-|}
  \left(\frac{1}{1-|\beta_+|}+\frac{1}{|\beta_-|-1}\right)\,,
\end{equation*}
and $\|\mathbf{a}\|_{\ell^p}\le \|k\|_{\ell^1}\|f\|_{\ell^p}$
by Young's inequality.
Thus we complete the proof.
\end{proof}


\begin{lemma}
  \label{lem:qJ-1q*}
Let $\a>0$, $\eta\in\R$ and $V'_n(t)\in C(\R;\ell^\infty)$.
Let $q(t)\in C^2(\R,\ell^2_\a)$ and $q^*(t)\in C^2(\R;\ell^2_{-\a})$ be solutions of
 \begin{equation}
    \label{eq:1}
(\pd_t^2+\eta^2)Q=(1-e^{-\pd})(1+V')(e^\pd-1)Q\,.
  \end{equation}
Then $\la q(t),\pd_tq^*(t)\ra-\la \pd_tq(t),q^*(t)\ra$
does not depend on $t$.
\end{lemma}
\begin{proof}
  Let $\mathbf{q}={}^t\!(q,\pd_tq)$ and $\mathbf{q^*}={}^t\!(q^*,\pd_tq^*)$.
  Let $H_1=\eta^2-(1-e^{-\pd})(1+V')(e^\pd-1)$ and
  \begin{gather*}
    J= \begin{pmatrix}   O & I \\ -I & O  \end{pmatrix}\,,
    \quad
    H=
    \begin{pmatrix} H_1 & O \\ O & I  \end{pmatrix}\,.
  \end{gather*}
Then $d\mathbf{q}/dt=JH\mathbf{q}$ and $d\mathbf{q^*}/dt=JH\mathbf{q^*}$
Since $J^*=-J$ and $H^*=H$,
\begin{align*}
\frac{d}{dt}\la \mathbf{q},J^{-1}\mathbf{q^*}\ra
 =& \la JH\mathbf{q}, J^{-1}\mathbf{q^*}\ra + \la \mathbf{q}, H\mathbf{q^*}\ra
\\ = & 0\,,
\end{align*}
and
\begin{equation*}
  \la \mathbf{q},J^{-1}\mathbf{q^*}\ra
  =\sum_{n\in\Z}(\pd_tq_nq^*_n-q_n\pd_tq^*_n)
\end{equation*}
does not depend on $t$.
\end{proof}


By the definitions \eqref{def:Phi0}--\eqref{eq:dualJost}, we have the following.
