\section{Orthogonality relation of $g^\pm(\eta)$ and $g^{\pm,*}(\eta)$}
\label{sec:appendix2}
To prove Claim~\ref{cl:pd-t,AB} and Lemma~\ref{lem:orth-relation},
we need the following.
\begin{claim}
  \label{cl:t,y-JdJ}
Let $L_1$ and $L_2$ be as \eqref{eq:Laxpair}.
If  $L_1\Phi=L_2\Phi=0$ and $L_1^*\Phi^*=L_2^*\Phi^*=0$,  then
\begin{gather*}
  2\pd_t(\Phi\Phi^*)=
  (e^\pd-1)\{\Phi(e^{-\pd}\Phi^*)+(1+V)(e^{-\pd}\Phi)\Phi^*\}\,,
  \\
    2\pd_y(\Phi\Phi^*)=
  (e^\pd-1)\{\Phi(e^{-\pd}\Phi^*)-(1+V)(e^{-\pd}\Phi)\Phi^*\}\,.
\end{gather*}
\end{claim}
Claim~\ref{cl:t,y-JdJ} follows from
\eqref{eq:v-change}, \eqref{eq:Jost-sol} and \eqref{eq:dualJost-sol}.

\par
Now we will prove Claim~\ref{cl:pd-t,AB}.
\begin{proof}[Proof of Claim~\ref{cl:pd-t,AB}]
 Suppose that $Q=e^{-\pd}\left(\Phi(\beta_1)\Phi^*(\beta_2)\right)$
 for $\beta_1$, $\beta_2\in\C$  and that $\pd_yQ=i\eta Q$.
Note that $\pd_yg^\pm(\eta)=i\eta g^\pm(\eta)$ and 
$\pd_yg^{\pm,*}(\eta)=i\eta\tg^{\pm,*}(\eta)$ by Lemma~\ref{lem:tgform}.
\par

By Claims~\ref{cl:t,y-JdJ} and \ref{cl:Phi-updown},
 \begin{align*}
e^\pd B'(i\eta)Q+\pd_tQ=& (\pd_t+\pd_y)Q-(e^\pd-1)vQ
   \\=& (1-e^{-\pd})\{\Phi(\beta_1)e^{-\pd}\Phi^*(\beta_2)
        -(e^{\pd}v)\Phi(\beta_1)\Phi^*(\beta_2)\}
   \\=&
        (1-e^{-\pd})\{\Phi(\beta_1)\Phi^{0,*}(\beta_2)\}\,.
 \end{align*}
 By the definitions, $A'(-i\eta)-B'(i\eta)+C'(\eta)=(e^\pd-1)B'(i\eta)$.
 Hence it follows that
 \begin{align}
   \label{eq:5}
& \{A'(-i\eta)-B'(i\eta)+C'(\eta)\}Q+(1-e^{-\pd})\pd_tQ
\\ = & \notag
(1-e^{-\pd})\{e^\pd B'(i\eta)Q+\pd_tQ\}
\\=&  \notag
   (1-e^{-\pd})^2\Phi(\beta_1)\{\Phi^{0,*}(\beta_2)\}\,.   
 \end{align}
Let  $\beta_1=\beta_+(-\eta)$ and 
calculate the residue of \eqref{eq:5} at $\beta_2=a$.
Since $\operatorname{Res}_{\beta=a}\Phi^*(\beta)=1/(e^\pd\tau')$,
$g^+=e^{-\pd}\Phi(\beta_1)/\tau'$ and 
$C'(\eta)g^+(\eta)=0$ by  Lemma~\ref{lem:kerC-C'},
we have \eqref{eq:clpd-t,AB-1}.
\par
Substituting $\beta_1=a$ and $\beta_2=\beta_-(\eta)$ into \eqref{eq:5},
we have
\begin{align}
  \label{eq:clpd-t,AB-3'}
&  \left\{A'(-i\eta)-B'(i\eta)+C'(\eta)\right\}g^-(\eta)
  +(1-e^{-\pd})\pd_tg^-(\eta) \\
  \\ =& \notag
(1-e^{-\pd})^2\left\{\Phi(a)\Phi^{0,*}(\beta_-(\eta))\right\}\,.  
\end{align}
By Lemma~\ref{lem:Darboux}, Claim~\ref{cl:Phi-updown},
\eqref{def:gpm} and \eqref{def:tgpm*},
\begin{align*}
&  -C'(\eta)g^-(\eta)+(1-e^{-\pd})^2\left(\Phi(a)\Phi^{0,*}(\beta_-(\eta))\right)
\\ =&
(A'-e^{\pd}B')e^{-\pd}\left\{\Phi(a)\Phi(\beta_-(\eta))\right\}
+(1-e^{-\pd})^2\left(\Phi(a)\Phi^{0,*}(\beta_-(\eta))\right)
\\ =& -2i\eta(1-e^{-2\pd})\tg^-(\eta)\,.
\end{align*}
Combining the above with \eqref{eq:clpd-t,AB-3'}, we have
\eqref{eq:clpd-t,AB-3}.
\par

Since $C(\eta)=A(-i\eta)-B(i\eta)$, it follows from
Claim~\ref{cl:A,B,dual} that
 \begin{align*}
   \{A'(-i\eta)-B'(i\eta)-C(\eta)\}^*(e^\pd-1)^{-1}=
   i\eta+(1-e^{-\pd})u\,.
 \end{align*}
Since $(i\eta-\pd_t)Q=(\pd_y-\pd_t)Q=-\pd_sQ$,
 it follows from Lemma~\ref{lem:Darboux} that
 \begin{align}
   \label{eq:18}
& \{A'(-i\eta)-B'(i\eta)-C(\eta)\}^*(e^\pd-1)^{-1}Q-\pd_tQ
=  -A'Q
\\ =& \notag
 (1-e^{-\pd})\left\{u\left(e^{-\pd}\Phi(\beta_1)\right)
       \Phi^{0,*}(\beta_2)\right\}\,.
\end{align}
Letting $\beta_1=\beta_-(-\eta)$ and
calculating the residue of the equation above at $\beta_2=a$, we have
\eqref{eq:clpd-t,AB-2} from \eqref{def:g*pm}, \eqref{eq:g-tg} and
the fact that $C(\eta)^*e^{-\pd}\tg^{+,*}(\eta)=0$.
\par
Substituting $\beta_1=a$ and $\beta_2=\beta_+(\eta)$ into \eqref{eq:18}
and using \eqref{def:g*pm}, \eqref{def:tgpm*} and \eqref{eq:g-tg}, we have
\begin{align}
 \label{eq:clpd-t,AB-4'}
&  \left\{A'(-i\eta)-B'(i\eta)-C(\eta)\right\}^*e^{-\pd}\tg^{-,*}(\eta)
  -\pd_tg^{-,*}(\eta)
  \\ = & \notag
2i\eta(1-e^{-\pd})\tg^{-,*}(\eta)\,.
\end{align}
By the definitions, $C(\eta)^*(e^\pd-1)^{-1}=e^\pd B'-A'$ and
it follows from Lemma~\ref{lem:Darboux} that
\begin{align*}
C(\eta)^*e^{-\pd}\tg^{-,*}(\eta)=&
(e^\pd-1)^{-1}(e^\pd B'-A')e^{-\pd}\left(\Phi(a)\Phi^*(\beta_+(\eta))\right)
  \\=& 2e^{-\pd}\left(\Phi(a)\Phi^*(\beta_+(\eta))\right)
= 4i\eta e^{-\pd}\tg^{-,*}(\eta) \,.
\end{align*}
Substituting the above into \eqref{eq:clpd-t,AB-4'},
we have \eqref{eq:clpd-t,AB-4}.  
Thus we complete the proof.
\end{proof}
Finally, we will prove Lemma~\ref{lem:orth-relation}.
\begin{proof}[Proof of Lemma~\ref{lem:orth-relation}]
Since $g^{+,*}(\eta)=(1-e^{-\pd})\tg^{+,*}(\eta)$, it follows from  
\eqref{eq:clpd-t,AB-1} and \eqref{eq:clpd-t,AB-2} that
  \begin{align*}
& \la g^+(\eta),\pd_tg^{+,*}(\eta)\ra-\la \pd_tg^+(\eta),g^{+,*}(\eta)\ra
  \\=&
\la g^+(\eta),\{A'(-i\eta)-B'(i\eta)\}^*e^{-\pd}\tg^{+,*}(\eta)\ra
\\ & +\la (1-e^{-\pd})^{-1}\{A'(-i\eta)-B'(i\eta)\}g^+(\eta),g^{+,*}(\eta)\ra  
\\=& 0\,.
\end{align*}
\par
By \eqref{eq:g-tg}, \eqref{eq:clpd-t,AB-3} and \eqref{eq:clpd-t,AB-4},
\begin{align*}
& \la g^-(\eta),\pd_tg^{-,*}(\eta)\ra-\la \pd_tg^-(\eta),g^{-,*}(\eta)\ra  
\\=&
2i\eta\left\{
 \left\la g^-(\eta), (1+e^{-\pd})\tg^{-,*}(\eta)\right\ra 
 +\left\la (1+e^{-\pd})\tg^-(\eta), g^{-,*}(\eta)\right\ra
       \right\}
  \\=& -2i\eta\left\{
 \left\la \tg^-(\eta), (e^\pd-e^{-\pd})\tg^{-,*}(\eta)\right\ra 
 +\left\la (e^\pd-e^{-\pd})\tg^-(\eta), \tg^{-,*}(\eta)\right\ra
       \right\}
\\= & 0\,.
\end{align*}
\par
By \eqref{eq:clpd-t,AB-2}, \eqref{eq:clpd-t,AB-3} and \eqref{eq:g-tg},
\begin{align}
 \label{eq:20} 
\la g^-(\eta),\pd_tg^{+,*}(\eta)\ra
    -\la \pd_tg^-(\eta),g^{+,*}(\eta)\ra
=&  -2i\eta\la (e^\pd-e^{-\pd})\tg^-(\eta),\tg^{+,*}(\eta)\ra\,.
\end{align}
Since $\Phi^0(a)\Phi^{0,*}(\beta_\pm(\eta))=a^n\beta_\mp(\eta)^n
e^{iy\eta-t\{\sinh\k\pm\mu(\eta)\}}$,
\begin{equation*}
\pd_y\{\Phi^0(a)\Phi^{0,*}(\beta_\pm(\eta))\}=i\eta
\Phi^0(a)\Phi^{0,*}(\beta_\pm(\eta))\,.  
\end{equation*}
Hence it follows from Lemma~\ref{lem:Darboux} and Claim~\ref{cl:Phi-updown}
that
\begin{align*}
e^\pd C(\eta)e^{-\pd}\left\{\Phi^0(a)\Phi^{0,*}(\beta_\pm(\eta))\right\}
=& e^\pd(A-B)e^{-\pd}\left\{\Phi^0(a)\Phi^{0,*}(\beta_\pm(\eta))\right\}
\\=& -(e^\pd-e^{-\pd})\left\{\Phi(a)\Phi^{0,*}(\beta_\pm(\eta))\right\}\,.
\end{align*}
Combining the above with \eqref{def:tgpm} and \eqref{def:tgpm*}, we have
\begin{gather}
\label{eq:21a}
e^\pd C(\eta)e^{-\pd}\left\{\Phi^0(a)\Phi^{0,*}(\beta_-(\eta))\right\}  
=-2i\eta(e^\pd-e^{-\pd})\tg^-(\eta)\,,
\\ \label{eq:21b}
e^\pd C(\eta)e^{-\pd}\left\{\Phi^0(a)\Phi^{0,*}(\beta_+(\eta))\right\}  
=-2i\eta(e^\pd-e^{-\pd})\tg^{-,*}(\eta)\,.
\end{gather}
\par
By \eqref{eq:20} and \eqref{eq:21a},
\begin{align*}
& \la g^-(\eta),\pd_tg^{+,*}(\eta)\ra
    -\la \pd_tg^-(\eta),g^{+,*}(\eta)\ra
\\ =&
\left\la e^\pd C(\eta)e^{-\pd}\left\{\Phi^0(a)\Phi^{0,*}(\beta_-(\eta))\right\},
\tg^{+,*}(\eta)\right\ra\,.
\end{align*}
By Lemma~\ref{lem:kerC-C'},
\begin{equation*}
\left\{e^\pd C(\eta)e^{-\pd}\right\}^*\tg^{+,*}(\eta)
=e^\pd C(\eta)^*e^{-\pd}\tg^{+,*}=0\,.
\end{equation*}
Since $e^\pd C(\eta)e^{-\pd}=-2i\eta+u+(e^\pd v)-e^\pd u-ve^{-\pd}$,
\begin{equation}
    \label{eq:9}
  (e^\pd Ce^{-\pd}f)\overline{g}-f\overline{e^\pd C^*e^{-\pd}g}
  =(e^\pd-1)\{v(e^{-\pd}f)\bar{g}-ufe^{-\pd}\bar{g}\}\,.
\end{equation}
By Claim~\ref{cl:Phi-updown} and \eqref{def:taun'},
\begin{equation*}
\Phi^0_n(a)\Phi^{0,*}_n(\beta_-(\eta))
\overline{\Phi^0_n(\beta_-(-\eta))}/\tau'_n
=O(e^{-2\k|n|})\quad\text{as $n\to-\infty$.}
\end{equation*}
Hence it follows from \eqref{def:tgpm*} and \eqref{eq:9}  that
\begin{align*}
  & \left\la e^\pd C(\eta)e^{-\pd}
    \left\{\Phi^0(a)\Phi^{0,*}(\beta_-(\eta))\right\},
\tg^{+,*}(\eta)\right\ra
  \\ =& \lim_{n\to\infty}
\biggl\{v_{n+1}\Phi^0_n(a)\Phi^{0,*}_n(\beta_-(\eta))
\Phi^0_{n+1}(\beta_-(\eta))(\tau'_{n+1})^{-1}
  \\ & \qquad\qquad 
  -u_{n+1}\Phi^0_{n+1}(a)\Phi^{0,*}_{n+1}(\beta_-(\eta))
\Phi^0_n(\beta_-(\eta))(\tau'_n)^{-1}\biggr\}\,.
\end{align*}
By the definitions,
\begin{gather*}
\Phi^0_j(\beta)\Phi^{0,*}_k(\beta)=\beta^{j-k}
 \quad\text{for every $j$, $k\in\Z$,}  
\\
\lim_{n\to\infty}\frac{v_{n+1}\Phi^0_n(a)}{\tau'_{n+1}}
=\lim_{n\to\infty}\frac{\Phi^0_n(a)}{\tau'_n}=1\,,
  \\
\lim_{n\to\infty}\frac{u_{n+1}\Phi^0_{n+1}(a)}{\tau'_n}
=\lim_{n\to\infty}\frac{\Phi^0_{n+1}(a)}{\tau'_{n+1}}=1\,.
\end{gather*}
Combining the above, we have,
\begin{align*}
\la g^-(\eta),\pd_tg^{+,*}(\eta)\ra-\la \pd_tg^-(\eta),g^{+,*}(\eta)\ra  
=&\beta_-(\eta)-\beta_-(\eta)^{-1}
\\=& -2\mu(\eta)\,.
\end{align*}
\par
By \eqref{eq:clpd-t,AB-1}, \eqref{eq:clpd-t,AB-4}, \eqref{eq:21b}
and \eqref{eq:9},
\begin{align*}
& \la g^+(\eta),\pd_tg^{-,*}(\eta)\ra-\la \pd_tg^+(\eta),g^{-,*}(\eta)\ra  
  \\=& -\left\la \tg^+(\eta)), e^\pd C(\eta)e^{-\pd}
\left\{\Phi^0(a)\Phi^{0,*}(\beta_+(\eta))\right\}\right\ra       
  \\=& \lim_{n\to\infty}       
\Bigl\{-v_{n+1}\Phi^0_{n+1}(\beta_+(-\eta))(\tau'_{n+1})^{-1}
       \Phi^0_n(a)\Phi^{0,*}_n(-\beta_+(\eta))
  \\ &
       +u_{n+1}\Phi^0_n(\beta_+(-\eta))(\tau'_n)^{-1}
       \Phi^0_{n+1}(a)\Phi^{0,*}_{n+1}(\beta_+(-\eta))\Bigr\}
  \\=& -\beta_+(-\eta)+\beta_+(-\eta)^{-1}
 =-2\mu(-\eta)\,.
\end{align*}
Thus we complete the proof.
\end{proof}

