  \coordinate (abot) at (#1,\frzBot-\frzExtra);  
  \foreach \ver/\pos/\val in {a2/4/{#2}, a4/2/{#3}, a6/0/{#4}}
    \draw ({#1},\pos) node(\ver) {\val}; }
\perEdge{0.5}; \perEdge{4.5};
\evenlayerDE{0}{$y_2$}{\vdots}{$y_{n-2}$}
\oddlayerDE{1}{$x_1$}{$y_3$}{$x_{n-3}$}{$x_{+}$}{$x_{-}$} \connect
\evenlayerDE{2}{$x_2$}{\vdots}{$x_{n-2}$} \connect 
\oddlayerDE{3}{$y_1$}{$x_3$}{$y_{n-3}$}{$y_{+}$}{$y_{-}$} \connect 
\evenlayerDE{4}{$y_2$}{\vdots}{$y_{n-2}$} \connect 
\oddlayerDE{5}{$x_1$}{$y_3$}{$x_{n-3}$}{$x_{+}$}{$x_{-}$} \connect
\end{tikzpicture}
\] %\end{figure}
The frieze equations are
\begin{equation}\label{eq:DEfrzeq}
\begin{aligned}
x_1y_1 &= x_2+ 1 = y_2 + 1 \\
x_2y_2 &= x_1y_3 + 1 = y_1x_3 + 1 \\
x_3y_3 &= x_2y_4 + 1 = y_2x_4 + 1 \\
& \;\;\vdots \\ % \nonumber
x_{n-3}y_{n-3} &= x_{n-2}y_{n-4}+1 = y_{n-2}x_{n-4}+1 \\
x_{n-2}y_{n-2} &= x_{+}x_{-}x_{n-3} + 1 = y_{+}y_{-}y_{n-3} + 1 \\ 
x_{+}y_{+}  = x_{-}y_{-} &= x_{n-2} + 1 = y_{n-2} + 1
\end{aligned}
\end{equation}
These equations imply $x_{2k}= y_{2k}(=c_{2k})$, for $k = 1,\dots,m$.
We then get the following equations for the $c_{2k}$, including the effective initial value $c_0=1$,
\begin{equation}\label{eq:c2k}
\begin{aligned}
(c_{2m}^2-1)^2 &= (x_{+}x_{-}x_{2m-1})(y_{+}y_{-}y_{2m-1}) = (c_{2m}+1)^2(c_{2m}c_{2m-2}+1)\\
(c_{2k}^2-1)^2 &= (x_{2k+1}y_{2k-1})(y_{2k+1}x_{2k-1}) = (c_{2k+2}c_{2k}+1)(c_{2k}c_{2k-2}+1)
\end{aligned}
\end{equation}
for $k=1,\dots,m-1$.
From these, starting from $k=m$, we get $c_{2k-2}=c_{2k}-2$.
Then, starting from $c_0=1$, we conclude that $c_{2k}=2k+1$.
Putting this back into \eqref{eq:DEfrzeq} gives
\begin{equation}\label{eq:xyodd}
\begin{aligned}
  x_{2k-1}y_{2k-1} &= (2k-1)(2k+1)+1 =4k^2, \\
   x_{2k-1}y_{2k+1} = x_{2k+1}y_{2k-1} &= (2k+1)^2-1 = 4k(k+1)
\end{aligned}
\end{equation}
and hence, inductively, $x_{2k-1}=kx_1$, $y_{2k-1}=ky_1$.
Thus we have reduced the frieze equations \eqref{eq:DEfrzeq} to 
\begin{equation}\label{eq:DEfrz-final}
 x_1y_1=4,\quad x_{+}y_{+}  = x_{-}y_{-} = n,\quad  x_{1}x_{+}x_{-} = y_{1}y_{+}y_{-} (=2n),
\end{equation}
where the equation in parentheses follows because
$(x_{1}x_{+}x_{-})(y_{1}y_{+}y_{-})=4n^2$ from the first three equations.
%This shows that we have two free parameters, just as in the $D_4$ case.
As shown above, the other values in the frieze are
\begin{equation}\label{eq:DEfrz-other}
 x_{2k}=y_{2k}=2k+1,\quad x_{2k-1}=kx_1,\quad y_{2k-1}=ky_1.
\end{equation}
Thus there are two free parameters, e.g.~given by $\{(x_+,y_+)\in(\RRp)^2 : x_+y_+=n\}$
and $\{(x_-,y_-)\in(\RRp)^2 : x_-y_-=n\}$,
Setting $x=2n/(x_+x_-)$ and $y=2n/(y_+y_-)$
 the frieze is
