  \draw [edge] (atop)--(a1)--(a3)--(a5)--(a7)--(abot); }
%\newcommand{\evenEdge}{
%  \draw [edge] (atop)--(a2)--(a4)--(a6)--(a8)--(abot); }
\newcommand{\oddlayerES}[5]{
  \coordinate (atop) at (#1,\frzTop+\frzExtra);
  \coordinate (abot) at (#1,\frzBot-\frzExtra);  
  \foreach \ver/\pos/\val in {a1/3/{#2}, a3/1/{#3}, a5/0/{#4}, a7/-1/{#5}}
    \draw ({#1},\pos) node(\ver) {\val};
}
\newcommand{\evenlayerES}[4]{
  \coordinate (atop) at (#1,\frzTop+\frzExtra);
  \coordinate (abot) at (#1,\frzBot-\frzExtra);  
  \foreach \ver/\pos/\val in {a2/2/{#2}, a4/0/{#3}, a6/-2/{#4}}
    \draw ({#1},\pos) node(\ver) {\val}; 
}
\perEdge{0.5}; \perEdge{4.5};
\oddlayerES{0}{$x_1$}{$y_3$}{$y_7$}{$c_5$}
\evenlayerES{1}{$c_2$}{$c_4$}{$c_6$} \connect
\oddlayerES{2}{$y_1$}{$x_3$}{$x_7$}{$c_5$} \connect
\evenlayerES{3}{$c_2$}{$c_4$}{$c_6$} \connect
\oddlayerES{4}{$x_1$}{$y_3$}{$y_7$}{$c_5$} \connect
\evenlayerES{5}{$c_2$}{$c_4$}{$c_6$} \connect
\coordinate (bb) at (0,0);
\end{tikzpicture}
\end{equation}
The frieze equations are
\begin{equation}\label{eq:E7frzeq1}
\begin{aligned}
x_1y_1 &= c_2+ 1 \\
x_1y_3 = y_1x_3 &= c_2^2 - 1 \\
x_3y_3 &= c_2c_4 + 1 \\
x_7y_7 &= c_4+ 1 \\
x_3x_7 = y_3y_7 &= (c_4^2 -1)/c_5  \\
c_5^2 &= c_4c_6 + 1\\
c_6^2 &= c_5 + 1
\end{aligned}
\end{equation}
Setting $c_2=a+1$, we can solve the second (pair) to get $x_3=ax_1$ and $y_3=ay_1$,
so the first half of the equations reduce to
\begin{equation}\label{eq:E7frzeq2}
\begin{aligned}
x_1y_1 &= a+ 2 \\
c_4 &=  (x_3y_3-1)/c_2 = (a^2(a+2)-1)/(a+1) = a^2+a-1\\
x_7y_7 &= a(a+1) \\
x_1x_7 &= y_1y_7 \bigl(=\sqrt{a(a+1)(a+2)}\bigr)\\
\end{aligned}
\end{equation}
In particular, $a=x_3/x_1>0$ and $a^2+a-1=c_4>0$, so $a> \phi^{-1}$.
If the value of $a$ is determined, then there is one free parameter.
For the second half of the equations, we set $c_6=c$, giving
$c_5=c^2-1$ and $c_4=c(c^2-2)$,
and thus the constraint that $c>\sqrt{2}$.
Then, for consistency, we need that
\begin{equation}\label{eq:concy1}
\begin{aligned}
  a^2+a-1 &= c_4 = c(c^2-2), \\
  a\sqrt{a(a+1)(a+2)} &= x_3x_7= (c_4^2 -1)/c_5 = c^4-3c^2+1.
\end{aligned}
\end{equation}
Setting $x_1=y_1=\sqrt{a+2}$ will give a constant $\RRp$-frieze, 
for any value of $a$ satisfyiing the consistency conditions above.
Since we know from \S\ref{sec:const} that such a frieze is unique, we know that $a$ and $c$ must be given
by their values in that case, 
namely $a=2\phi$, $c=1+\phi$,
which one can check do satisfy \eqref{eq:concy1}.

Thus we end up with the following equations
\begin{equation}\label{eq:last-E7}
  x_1y_1 = 2\phi^2 = 2(1+\phi),  \quad
  x_7y_7 = 2\phi^4 = 2(2+3\phi), \quad
  x_1x_7 = y_1y_7 (= 2\phi^3)
\end{equation}
and we do indeed have one free parameter, similar to the case of $D_n$ ($n$ odd).
The remaining variables in \eqref{eq:E7frz} are given by
\begin{equation}\label{eq:last-E7-rest}
\begin{aligned}
  x_3 &= 2\phi x_1, \quad 
  y_3 = 2\phi y_1, \quad 
  c_6 = \phi^2 = 1+\phi, \quad 
  c_5 = 1+3\phi, \\
  c_2 &= \phi^3 = 1+2\phi, \quad 
  c_4 = 3\phi^3 = 3(1+2\phi).
\end{aligned}
\end{equation}

