\section{Topological Reconstruction from Mean-Fields}\label{trc-section}

The failure of unique reconstruction from mean-field measurements stems from the non-injective nature of the measurement matrices. One approach to obtain uniqueness is to ensure injectivity within the subspace of sparse state vectors. Roughly speaking, a vector is sparse when many of its entries are zero. Consider the support of a vector, defined as
\begin{equation}
    \supp(x):=\{i\mid x_i\neq 0\}, \quad \text{and} \quad 
\|x \|_0 := \#\{i   \mid x_i \neq 0\}.
\end{equation}

We say that a vector is $s$-sparse when \(\| x\|_0 \le s\). 
Using sparsity we can overcome the lack of injectivity. This is captured in the concept of spark.

\begin{definition}
The spark of a matrix $\phi\in \mathbb{R}^{P\times N}$ where $P<N$, is defined as the size of the smallest linearly dependent subset of its columns, which is given by
\begin{equation}
    \spark(\phi)= \min\{\|x\|_0: \phi x= 0, x\neq 0\}.
\end{equation}
If $\spark(\phi)=P+1$, it is called full-spark \cite{alexeev2012full}.
\end{definition} 
If $x\in \mathbb{R}^N$ is $s$-sparse, then  the inverse problem \(\phi x = y\) has a unique $s$-sparse solution provided that every set of $2s$ columns of $\phi$ is linearly independent. 
Thus, if $2\|x\|_0<\spark(\phi)$, then $x$ can be uniquely recovered (see Lemma \ref{spark_sparsest}).
We will show that, using these concepts, we can uniquely recover the states from mean-field measurements and the network topology.  We define the topological reconstruction as follows:  

\begin{definition} Recovering the adjacency matrix \(A\) of the underlying graph of the network $\mathcal{G}$ is called the topological reconstruction. 
\end{definition}
\begin{remark}\label{trc}
Notice that \(\{L_1(q)\}_{q=1}^N\) uniquely determines the adjacency matrix \(A\) of the underlying graph of the network $\mathcal{G}$ since \(L_1(q)\) consists of non-zero elements of the \(q\)th column of the adjacency matrix, i.e.,
\begin{equation}
    A_{ij}=\begin{cases}
        1 \text{ if } i\in L_1(j),\\0 \text{ if } i\not\in L_1(j),
    \end{cases} \text{ for all }i,j\in [N] .
\end{equation}
\end{remark}


We present two topological reconstruction conditions, referred to as the strong and weak conditions. This nomenclature reflects the distinction that the weak condition is derived from an abstract argument for unique existence, while the strong condition is computationally tractable through convex optimization. 

\subsection{Weak Topological Reconstruction Condition (wTRC)} \label{wtrc}



\begin{theorem}\label{topologicalcondition}(wTRC)
Let $\mathcal{G}=(G,f,h)$ be a network dynamical system of size $N$ with maximum out-degree $\Delta(G)$, satisfying Assumptions \ref{isolated_ass} and \ref{assumption_about_coupling}. Let $P>2\Delta(G)+1$, and let $\phi_q\in \mathbb{R}^{P\times N}$ be full-spark measurement matrices for each $q\in [N]$. Assume that mean-fields
\begin{equation}
    y^q(1)=\phi_q x^q(1)
\end{equation}        
 are known for all $q\in[N]$. Then, the network is uniquely topologically reconstructible from mean-field measurements. That is,
 given $\{y^q(1)\}_{q=1}^N$, for each $q\in [N]$, there exists a unique solution $x_*^q(1)$ to 
\begin{equation}\label{P0}
 \min\|\tilde{x}^q\|_0 \text{  subject to } y^q(1) = \phi_q \tilde{x}^q(1),
\end{equation}
such that 
\begin{equation}
    x_*^q(1) =x^q(1).
\end{equation}
Moreover, there exists a one-to-one correspondence between $\supp(x^q(1))$ and $L_1(q)$.
\end{theorem}


This result investigates whether topological reconstruction from mean-field measurements is possible, providing an affirmative answer to this question and showing that 
%We identify a bijection between the first-level sets and the support set of state vectors, 
%proving that 
the network topology can be reconstructed from the support of these vectors. 
%We show that the number of required mean-field measurements depends only on the maximum out-degree of the underlying graph.
Moreover, from an applied perspective, our result provides a framework for determining the minimum number of mean-field measurements needed for unique reconstruction, offering guidelines for experimental design and data collection.
\begin{remark}
    Since $\phi\in \mathbb{R}^{P\times N}$ is full-spark, the existence of solutions follows from the fact that full-spark implies full row rank and the column space $\mathrm{Col}(\phi)$ spans all of  $\mathbb{R}^P$, ensuring that at least one solution exists for any  $y \in\mathbb{R}^P$.
\end{remark}
\begin{corollary} \label{first_corol} (wTRC)
Let \(\{\phi_q\}_{q=1}^N\) be measurement matrices where each $\phi_q \in \mathbb{R}^{P \times N}$ is a Gaussian random matrix whose entries are i.i.d. Gaussian with mean zero and variance \(1/P\).
Then, with probability one, the matrices \(\{\phi_q\}_{q=1}^N\) 
satisfy the full-spark property. Consequently, for any network dynamical system satisfying the assumptions of Theorem \ref{topologicalcondition}, the network is uniquely topologically reconstructible from mean-field measurements almost surely.
\end{corollary}

We illustrate our result for Erd\H{o}s-Rényi (ER) graphs. We denote by \( G(N, p) \) an undirected Erd\H{o}s-Rényi random graph with \( N \) vertices, where each edge is included independently with probability \( p \). The expected degree \( \mathbb{E}[d] \) of such a graph is  \( (N - 1)p \). 
We show that for the Erd\H{o}s-Rényi model, the minimum number of required mean-field measurements scales logarithmically with the network size \( N \). 

%{\color{blue}
\begin{corollary}\label{er_theorem}
Let \(\mathcal{G} = (G, f, h)\) be a network dynamical system of size \(N\) satisfying Assumptions \ref{isolated_ass} and \ref{assumption_about_coupling}, where \(G(N, p)\) is an Erd\H{o}s-Rényi random graph, and $N$ is sufficiently large. Let \(\phi_q \in \mathbb{R}^{P \times N}\) be full-spark measurement matrices for each \(q \in [N]\), with \(P(N)\) specified in each regime below. Assume that the mean-fields
\begin{equation}
    y^q(1) = \phi_q x^q(1)
\end{equation}
are known for all \(q \in [N]\). Fix $\epsilon \in (0,1)$.  
\begin{enumerate}
    \item (Supercritical)
    Suppose $p = \frac{\log N}{N}(1 - \epsilon)$.  
    If there is $c_1>0$ such that 
    \begin{equation}
        P(N) \ge c_1 \log N, \nonumber
    \end{equation}
    then asymptotically almost surely the networks in G(N,p) are uniquely topologically reconstructible from mean-field measurements.
    %with high probability (i.e., with probability tending to 1 as $N\rightarrow\infty$).

    \item (Connected)
    Suppose $p = \frac{\log N}{N}(1 + \epsilon)$.
    %for $\epsilon \in (0,1)$.  
    If there is $c_1>0$ such that 
\begin{equation}
     P(N)  \ge c_1 \log^2 N, \nonumber
\end{equation}
    then asymptotically almost surely the networks in G(N,p) are uniquely topologically reconstructible from mean-field measurements.
\end{enumerate}
\end{corollary}
%}

These cases demonstrate that the number of required mean-field measurements grows only logarithmically with the network size \( N \). For sparse and large-scale networks, a small fraction of measurements may suffice to ensure unique topological reconstruction with high probability, provided that the wTRC condition is satisfied.




\subsection{Strong Topological Reconstruction Condition (sTRC)}

In Section \ref{wtrc}, we showed the weak topological reconstruction. The maximum degree ensuring the topological reconstruction condition is deterministic and applies to mean-field measurements that are the full-spark. However, finding the solution to Eq. (\ref{P0})  is known to be NP-hard  \cite{natarajan1995sparse}. 
%
The sTRC pursues two main objectives: (1) reformulating the uniqueness condition into a computationally tractable framework, and (2) reducing the number of required mean-field measurements. 
%We introduce key definitions that are essential in achieving these goals.
%
%We assume familiarity with standard notions such as the $\ell_1$ and $\ell_2$ norms, the $(P1)$ minimization problem. For completeness, precise definitions are provided in Section \ref{prelim}.
%
The restricted isometry property plays a key role:
\begin{definition}\label{RIPdef}
 The isometry constant \(\delta_s(\phi)\) is the smallest number such that 
\begin{equation}\label{RIP}
    (1-\delta_s(\phi)) \|x\|_2^2\leq\|\phi x\|_2^2 \leq (1+\delta_s(\phi))\|x\|_2^2
\end{equation}
    holds for all \(s\)-sparse vectors \(x\), \cite{candes2008restricted}. It is called \(\phi\) has restricted isometry property (RIP) when the inequality (\ref{RIP}) holds for given \(s\) and $\delta_s(\phi)\in (0,1).$ 
\end{definition}



Our main result is as follows: 



\begin{theorem}\label{P1-main} (sTRC) Let $\mathcal{G}=(G,f,h)$ be a network dynamical system of size $N$ with maximum out-degree $\Delta(G)$, satisfying Assumptions \ref{isolated_ass} and \ref{assumption_about_coupling}. Let $\phi_q\in \mathbb{R}^{P\times N}$ be measurement matrices for each $q\in [N]$ such that $ \delta_{2(\Delta(G)+1)}(\phi_q)<\sqrt{2}-1$. Assume that mean-fields
\begin{equation}
    y^q(1)=\phi_q x^q(1)
\end{equation}        
 are known for all $q\in[N]$. Then, the network $\mathcal{G}$ is uniquely topologically reconstructible. That is, given $\{y^q(1)\}_{q=1}^N$, for each $q\in [N]$, there exists a unique solution $x_*^q(1)$ to 
\begin{equation}\label{P1}
 \min\|\tilde{x}^q(1)\|_1 \text{  subject to }  y^q(1) = \phi_q \tilde{x}^q(1),
\end{equation}
such that 
\begin{equation}
    x_*^q(1) =x^q(1).
\end{equation}
Moreover, there exists a one-to-one correspondence between $\supp(x^q(1))$ and $L_1(q)$.
\end{theorem}


The sTRC derived under exact (noiseless \(y^q(1) = \phi_q \tilde{x}^q(1)\)) conditions is robust under small perturbations \cite{donoho2006most2, candes2008restricted}, thereby supporting the practical relevance of the sTRC\footnote{We investigate this robustness by evaluating performance under varying the recovery thresholds.}.

\begin{remark}
Let $y^q(1)=\phi_q x^q(1) +z^q(1) $, where $z^q(1)$ is an unknown noise term satisfying $\|z^q(1)\|_2\leq \xi$. Suppose the measurement matrix $\phi_q$ satisfies the restricted isometry condition $\delta_{2(\Delta(G)+1)}(\phi_q)<\sqrt{2}-1$. Then, the solution $x_*^q(1)$ to:
\begin{equation}
    \min\|\tilde{x}^q(1)\|_1 \text{ subject to } \|y^q(1)-\phi_q \tilde{x}^q(1)\|_2\leq \xi,
\end{equation}
satisfies the stability bound:
\begin{equation}
    \|x^q(1)-x_*^q(1)\|_2\leq K\xi,
\end{equation}
for some positive constant $K$ \cite{candes2008restricted}. This implies that all feasible minimizers lie within an $\ell_2$ ball of radius $K\xi$ centered at the ground truth $x^q(1)$; in this sense, the solution is unique up to a precision threshold dictated by the noise level. Moreover, the one-to-one correspondence between $\supp(x^q(1))$ and $L_1(q)$ persists.
\end{remark}

Even though sTRC is deterministic, finding deterministic RIP-satisfying matrices remains an open problem~\cite{tao}. We focus our attention on the case where the measurement matrices are Gaussian random matrices. This case is relevant in many applications. The following remark together with Theorem \ref{P1-main} implies Corollary \ref{gaussian}. A formal proof of this corollary is omitted for brevity.

\begin{remark}
    E. Cand\`es et al. showed that  for Gaussian matrices whose entries are i.i.d. Gaussian with zero and the variance $1/P$, if
\begin{equation}
    s\leq \frac{c_1P}{\log(N/P)},
\end{equation}
where $c_1$ is a positive constant, $s$ is the sparsity level, then the $(P_0)\sim (P_1)$ equivalence (see Definition \ref{P0-P1-eq}) holds with overwhelming probability, as shown in \cite{candes2006stable}. 
\end{remark}




\begin{corollary}\label{gaussian}
Let $\mathcal{G}=(G,f,h)$ be a network dynamical system of size $N$ with maximum out-degree $\Delta(G)$, satisfying Assumptions \ref{isolated_ass} and \ref{assumption_about_coupling}. Let $\phi_q\in \mathbb{R}^{P\times N}$ be Gaussian random matrices whose entries are i.i.d. Gaussian with the mean zero and the variance $1/P$ where $P<N$, for each $q\in [N]$, such that $\Delta(G)+1 \leq  \frac{c_1P}{\log(N/P)}$ where $c_1>0$ is some positive constant. Assume that mean-fields
\begin{equation}
    y^q(1)=\phi_q x^q(1)
\end{equation}        
 are known for all $q\in[N]$. Then, the network $\mathcal{G}$ is uniquely topologically reconstructible with overwhelming probability via $(P1)$ minimization.
\end{corollary}

We establish bounds that allow one to determine the minimal number of mean-field measurements required, given the network's maximum degree.


\begin{corollary}
We summarize our findings as follows:
\begin{equation}
    \begin{split}
        &P > 2\Delta(G) + 1, \quad \text{(sTRC with full-spark matrices)};\\
        &\frac{c_1 P}{\log(N/P)} \geq \Delta(G) + 1, \quad \text{(wTRC w.h.p. with random Gaussian matrices)},
    \end{split}
\end{equation}
where $c_1$ is a positive constant, $P$ is the number of mean-field measurements, $N$ is the network size, and $\Delta(G)$ is the maximum out-degree of the underlying graph.
\end{corollary}


\begin{remark}
Analogous to Corollary~\ref{er_theorem}, we can obtain a sufficient condition for the Erd\H{o}s-Rényi graph \( G(N, p) \) when the mean-fields are generated with Gaussian random matrices as in Corollary \ref{gaussian}. In both the supercritical and connected regimes, the maximum degree \( \Delta(G) \) satisfies with high probability
\[
\Delta(G) < Np + \sqrt{2Np \log N}.
\]
Hence, the strong Topological Reconstruction Condition (sTRC) yields the bound:
\begin{equation}\label{P_theoretical}
Np + \sqrt{2Np \log N} + 1 < \frac{c_1P}{\log(N/P)}.
\end{equation}
This inequality provides a practical criterion for selecting the number of mean-field measurements \( P \) in terms of the network size \( N \) and edge probability \( p \). 
\end{remark}

\section{Full Network Reconstruction from Mean-Fields}\label{full-rec-sect}
We propose a two-stage method to reconstruct the network \( \mathcal{G} = (G, f, h) \) from mean-field observations. 
%
First, 
%building on our earlier topological reconstruction result, 
we uniquely recover the full state trajectory \( x^q(t) \).
%assuming that the observed outputs are linear projections of the true state via matrices \( \phi_q \in \mathbb{R}^{P \times N} \) with \( P < N \). These projections define the mean-field measurements observed at each node \( q \in [N] \), and are assumed to satisfy suitable restricted isometry properties.
%
Second, we infer the local dynamics at each vertex by fitting a linear combination of features derived from the recovered state trajectory. These features, referred to as the oracle dictionary, encode the exact functional form of each node’s evolution and will be introduced below. Although this stage resembles a model selection problem, it is constrained to operate on approximations of states recovered from mean-field observations.

\begin{definition}
Let \( x(t) \in \mathbb{R}^N \) denote the system state at time \( t \). The oracle dictionary for vertex \( i \in [N] \) is a set of spanning functions \( \{ \psi_i^l \}_{l=1}^{s_i} \), such that the local dynamics at node \( i \) are exactly described by
\begin{equation}
x_i(t+1) = \sum_{l=1}^{s_i} c_{i,l} \, \psi_i^l(x(t)),
\end{equation}
where \( c_{i,l} \in \mathbb{R} \) are nonzero coefficients. That is, the oracle dictionary provides an exact functional representation of the evolution of \( x_i \) in terms of the current system state. Let \( s_{\max} := \max_{i \in [N]} s_i \) denote the maximum number of terms across all vertices.
\end{definition}
\begin{assumption}\label{ass:oracle_rank}
For each vertex \( i \in [N] \), define the dictionary matrix \( \Psi_i \in \mathbb{R}^{N s_{\max} \times s_i} \) as
\begin{equation}
\Psi_i := 
\begin{bmatrix}
\psi_i^1(x^1(0)) & \cdots & \psi_i^{s_i}(x^1(0)) \\
\psi_i^1(x^1(1)) & \cdots & \psi_i^{s_i}(x^1(1)) \\
\vdots & \ddots & \vdots \\
\psi_i^1(x^q(t)) & \cdots & \psi_i^{s_i}(x^q(t)) \\
\vdots & \ddots & \vdots \\
\psi_i^1(x^N(s_{\max}{-}1)) & \cdots & \psi_i^{s_i}(x^N(s_{\max}{-}1)) \\
\end{bmatrix},
\end{equation}
where each row corresponds to a specific pair \( (q, t) \), with \( q \in [N] \) indexing the perturbed initial conditions and \( t \in \{0, \dots, s_{\max} - 1\} \) indexing time.

We assume that this matrix has full column rank, i.e.,
\begin{equation} 
\mathrm{rank}(\Psi_i) = s_i,
\end{equation}
which ensures that the dictionary functions \( \{ \psi_i^l \}_{l=1}^{s_i} \) are linearly independent when evaluated across all trajectories and time steps.
\end{assumption}

\begin{theorem}\label{two-stage}
Let \( \mathcal{G} = (G, f, h) \) be a network dynamical system of size \( N \), with maximum out-degree \( \Delta(G) \), satisfying Assumptions~\ref{isolated_ass} and~\ref{assumption_about_coupling}.
%
Assume that for each node \( i \in [N] \), a set of basis functions \( \{ \psi_i^l \}_{l=1}^{s_i} \) is given which exactly represent the local dynamics, and that Assumption~\ref{ass:oracle_rank} holds. Let \( \phi_q \in \mathbb{R}^{P \times N} \) be measurement matrices for each \( q \in [N] \), satisfying
\begin{equation}
\delta_{2([\Delta(G)+1]^{s_{\max}})}(\phi_q) < \sqrt{2} - 1.
\end{equation}
Let the number of time steps be \( T = s_{\max} \), and assume access to mean-field measurements
\begin{equation}
\{ y^q(t) = \phi_q x^q(t) \}_{t = 1}^{s_{\max}}, \quad \text{for each } q \in [N].
\end{equation}
Then for each \( q \in [N] \), the state trajectory \( \{ x^q(t) \}_{t = 1}^{s_{\max}} \) is uniquely recoverable via the sequence of convex optimizations:
\begin{equation}\label{P11}
\min_{\tilde{x}^q(t)} \| \tilde{x}^q(t) \|_1 
\quad \text{subject to } \phi_q \tilde{x}^q(t) = y^q(t), 
\quad \text{for } t = 1, \dots, s_{\max}.
\end{equation}

Moreover:
\begin{enumerate}
    \item[(i)] The network topology is exactly reconstructible from \( \ \{supp(x^q(1))\}_{q=1}^N \), via the correspondence between \( L_1(q) \) and \( \supp(x^q(1)) \).
    \item[(ii)] The exact local dynamics at each vertex \( i \in [N] \) are recovered by solving 
    \begin{equation}
    x_i^{(q)}(1,\cdots,  s_{\max}) = \Psi_i \, c_i,
    \end{equation}
    where \( \Psi_i \in \mathbb{R}^{N s_{\max} \times s_i} \) is the oracle dictionary matrix, and the unique coefficients satisfy
    \begin{equation}
    \hat{c}_i = \Psi_i^\dagger x_i^{(q)}(1,\cdots,  s_{\max}), 
    \end{equation}
    where $ \Psi_i^\dagger$  denotes the Moore–Penrose pseudoinverse of \( \Psi_i \).
\end{enumerate}
\end{theorem}

We note that the assumption of access to an exact oracle dictionary is idealized. However, since we recover the level sets $L_1(q)$ uniquely, we can pinpoint the contribution of each term in the basis when the coupling $h$ and dynamics $f$ is provided. 



\section{Numerical Experiments} \label{numerics-sec}

We present two topological reconstruction experiments to illustrate the Strong Topological Reconstruction Condition (sTRC). Afterwards, we present a full network reconstruction experiment.
%
To evaluate reconstruction performance, we use two metrics: the Matthews Correlation Coefficient (MCC) and the Mean Squared Error (MSE), defined below.

\begin{definition}
The \emph{Matthews Correlation Coefficient} (MCC) is a measure of the quality of binary classifications. It is defined as:

\begin{equation}
\mathrm{MCC} = \frac{ TP \cdot TN - FP \cdot FN }{ \sqrt{ (TP + FP)(TP + FN)(TN + FP)(TN + FN) } }
\end{equation}
where \( TP \), \( TN \), \( FP \), and \( FN \) denote the number of true positives, true negatives, false positives, and false negatives, respectively. The MCC ranges from \(-1\) to \(+1\), where \(+1\) indicates perfect prediction, \(0\) indicates performance no better than random guessing, and \(-1\) indicates total disagreement between prediction and ground truth.
\end{definition}

We also consider the following:

\begin{definition}
The \emph{Mean Squared Error} (MSE) quantifies the average squared difference between estimated values and ground truth values. It is defined as:

\begin{equation}
\mathrm{MSE} = \frac{1}{n} \sum_{i=1}^{n} (y_i - \hat{y}_i)^2
\end{equation}

where \( y_i \) denotes the true value, \( \hat{y}_i \) the predicted value, and \( n \) the number of samples. A lower MSE indicates more accurate predictions.
\end{definition}



\subsection{Topological Reconstruction From Mean-Field Measurements}

Our procedure consists of three stages: (1) generation of network states, (2) computation of mean-field measurements, and (3) solution of the inverse problem. 
%In the inverse problem, we assume that the mean-field measurements are available while the network states remain hidden. 
The goal is to reconstruct the underlying network topology based on the mean-field measurements.

To evaluate performance, we apply this procedure across a range of graph sparsities and reconstruction thresholds, and compare the supports of the reconstructed vectors to the ground truth using the Matthews correlation coefficient (MCC). This provides a quantitative measure of reconstruction accuracy and robustness under varying conditions. The implementation details of the methodology are described below.


Using the setup of Section~\ref{setting-sec} our steps are:

\begin{enumerate}[label=(\roman*)]
    \item Each isolated dynamics $f_i : \mathbb{R} \rightarrow \mathbb{R}$ is chosen from the quadratic family:
    \begin{equation}
        f_i(x_i(t)) = r_i x_i(t)(1 - x_i(t)), \quad \forall i \in [N],
    \end{equation}
    where each $r_i$ is sampled uniformly at random from the set $\{1.2, 2.6, 3, 3.8\}$.

    \item The coupling function $h_{ij}: \mathbb{R} \times \mathbb{R} \rightarrow \mathbb{R}$ is given by
    \begin{equation}
        h_{ij}(x_i(t), x_j(t)) = \alpha_{ij} (x_i(t) - x_j(t)), \quad \forall i, j \in [N],
    \end{equation}
    where the matrix $\alpha = [\alpha_{ij}]$ is symmetric, and its upper triangular entries are sampled uniformly at random from $[0,1)$.

\item We generate undirected Erd\H{o}s-Rényi (ER) random graphs
%\footnote{We choose this graph model because additional theoretical results are available for Erd\H{o}s-Rényi networks in our context.}
$G_i(N, p_i)$ with $N = 1000$, where the edge probabilities $p_i$ are specified below.


    \item For each $G_i$, we generate  $\{x^q(1)\}_{q=1}^N$ by $q$-pinching the state $x^q(0)$, where perturbation size $\epsilon_q$ is sampled uniformly at random from $[0.5, 1)$.

    \item We generate $y^q(1) = \phi x^q(1)$, where $\phi$ is a $P \times N$ Gaussian random matrix with entries i.i.d. from $\mathcal{N}(0, \frac{1}{P})$, used uniformly across all $q \in [N]$.

    \item We solve Eq. (\ref{P1}) to reconstruct the topology.

    \item A threshold is applied to the reconstructed vectors obtained from Eq. (\ref{P1}), setting entries below the threshold to zero to isolate significant components.

    \item We extract the support set of each state vector and concatenate them. We concatenate the support sets obtained from Eq. (\ref{P1}).

\item After reconstruction, we use the Matthews Correlation Coefficient (MCC) between the true and reconstructed support sets.

\item Define \( P_c \) as the smallest value of \( P \) for which the MCC score exceeds 0.99.



\end{enumerate}
\subsubsection{Experiment 1: Supercritical Regime}

We investigate the transition behavior of the critical number of mean-field measurements $P_c$ required for successful topological reconstruction in the supercritical Erd\H{o}s-Rényi regime. We determine \( P_c \) by using a support recovery threshold of \(10^{-9}\). Our objective is to observe how the transition from reconstruction failure to success unfolds.

