\section{Proofs} \label{proof-sec}
\subsection{Preliminaries}\label{prelim}
\begin{definition}
The support of the state vector $x \in \mathbb{R}^N $ is 
%the index set of its nonzero entries, i.e.,
\begin{equation}
    \supp(x):=\{i:x_i\neq 0\}, 
\end{equation}
and the size of the support set is called $\ell_0$ norm (by abuse of notation), 
\begin{equation}
    \|x\|_0=\# \{i:x_i\neq 0\}.
\end{equation}
Moreover, a vector \(x\) is called \(s\)-sparse if $\|x\|_0\leq s$ for an integer \(s\).
\end{definition}
To define the unique reconstructability, we introduce the following optimization problem:


%{\color{blue}
\begin{definition}\label{uniquely_reconstructable}
The following optimization problem
\begin{equation}
    x_* = \argmin_{x \in \mathbb{R}^N}  \|\tilde{x}\|_0 \quad \text{subject to}\quad \phi \tilde{x}=\phi x,
\end{equation}
is called the $(P0)$ problem. 
The set of all solutions is denoted by $X_*$. A  vector $x$ is said to be $(P0)$ uniquely reconstructible if  $X_* = \{x\}$.
\end{definition} 
\begin{definition} 
We define $\ell_p$ norm of \(x\in \mathbb{R}^N\) as
\begin{equation}
    \|x\|_{p}= \big( \sum_{i=1}^N |x_i|^p\big)^{\frac{1}{p}}, \quad  1\leq p<\infty.
\end{equation}
\end{definition}

\begin{definition}
The following optimization problem
\begin{equation}
    \begin{split} &\min \|\tilde{x}\|_1 \\
&\text{subject to } \phi \tilde{x}=y, \end{split}
\end{equation}
is called the $(P1)$ problem and its solution is denoted by $x_*$.
\end{definition}





\subsection{Preparatory Results}

The Theorem \ref{topologicalcondition} and Theorem \ref{P1-main} will be obtained as a sequence of observations.
We use the notation $x^q(1)$ to represent the iterated state vector of the $q$-pinching initial condition $x^q(0)$. We denote the mean-fields as $y^q(1)$, where $y^q(1) = \phi_q x^q(1)$, and $\phi_q$ is the measurement matrix. 
   \begin{lemma}
    \label{pinch} {
$x^q_i(1)\neq 0$ when $i\neq q$ if and only if $i\in L_1(q)$.}
\end{lemma}
\begin{proof}
 First, we show that $i\in L_1(q)$ implies $x^q_i(1)\neq 0$.
Let $i \in L_1(q)$, then
\begin{equation}\begin{split}
    x^q_i(1)&= f_i(x^q_i(0)) + \sum_{j=1}^N A_{ij}h_{ij}(x^q_i(0), x^q_j(0))\\
    &=f_i(\delta_{iq}\epsilon_q)+ \sum_{j=1}^N A_{ij}h_{ij}(\delta_{iq}\epsilon_q, \delta_{jq}\epsilon_q), \; 
    %( \delta_{iq}=0\text{ since } i\neq q \text{ and }\delta_{jq}\epsilon_q = 0 \text{ for all } j\neq q )
    \\
    &= 0+ A_{iq}h_{iq}(0,\epsilon_q),\\ 
    %(f_i(0)=0 \text{ by  \ref{isolated_ass}}, \, h_{ij}(0,0)=0 
    %\text{ by  \ref{assumption_about_coupling})}\\
    &= A_{iq}h_{iq}(0,\epsilon_q)\\
    & \neq 0. \nonumber
\end{split}    
\end{equation}
Observe that, the assumption $i \in L_1(q)$ means $A_{iq} \neq 0$ by Remark \ref{trc}, and $h_{iq}(0,\epsilon_q) \neq 0$  by Assumption \ref{assumption_about_coupling}. Thus, $x^q_i(1) \neq 0.$ For the other side of the implication, we want to show $x^q_i(1)\neq 0$ implies $i\in L_1(q)$. We use contraposition. Assume $i \notin  L_1(q).$ Then $A_{iq}=0$ and by the evolution law $x_i^q(1)=0.$ 
\end{proof}

\begin{lemma}\label{theta1}
    Let $D = \{ A \subseteq [N] \mid q \in A \}$ be the set of all subsets of $[N]$ that contain the element $q$, and let $C = \mathcal{P}([N] \setminus \{q\})$ be the power set of $[N] \setminus \{q\}$. Define  $\Theta_1^q : D \to C$ by
    \begin{equation}
        \Theta_1^q(A) = A \setminus \{q\}.
    \end{equation}
    Then, $\Theta_1^q$ is a one-to-one correspondence.
\end{lemma}

\begin{proof}
    We first show that $\Theta_1^q$ is injective. Suppose that for some $A, B \in D$, we have 
    \[\Theta_1^q(A) = \Theta_1^q(B).\]
    By the definition of $\Theta_1^q$, this means 
    \[ A \setminus \{q\} = B \setminus \{q\}. \]
    Since both $A$ and $B$ belong to $D$, they contain $q$, so we can conclude that $A = B$. Thus, $\Theta_1^q$ is injective.

    Next, we prove that $\Theta_1^q$ is surjective. Let $B \in C$, meaning $B$ is a subset of $[N] \setminus \{q\}$. Define $A = B \cup \{q\}$. Clearly, $A$ contains $q$, so $A \in D$, and we have
    \[ \Theta_1^q(A) = A \setminus \{q\} = B. \]
    Since $B$ was an arbitrary element of $C$, this shows that $\Theta_1^q$ is surjective.

    Since $\Theta_1^q$ is both injective and surjective, it is bijective (one-to-one correspondence).
\end{proof}

\begin{lemma}\label{havingL1} Let $x^q(1)$ be given for known $q \in [N]$. Then, there exists a one-to-one correspondence between $\supp(x^q(1))$ and $L_1(q)$:
    \begin{itemize}
    \item If \( x^q_q(1) \neq 0 \), the correspondence is given by the bijection $ \Theta_1^q: D\rightarrow C$ where $D=\{A\subseteq [N] \mid q\in A\}$ and  $C= \mathcal{P}([N]\setminus\{q\})$.
    \item If \( x^q_q(1) = 0 \), the correspondence is given by the identity map $ \mathrm{id}: \mathcal{P}([N]\setminus\{q\}) \to  \mathcal{P}([N]\setminus\{q\})$.
\end{itemize}
Furthermore, $|\supp(x^q(1))|\leq d_q+1$ where $d_q $ is the out-degree of the vertex $q$ of the underlying graph.
\end{lemma}


\begin{proof}
We have the state vector $x^q(1)$ for known $q\in[N]$.
We consider two  cases:

(a) The case \( x^q_q(1) \neq 0 \):

By Lemma \ref{pinch}, if $i \neq q$ and $x_i^q(1) \neq 0$, then $i \in L_1(q)$. By assumption, $x^q_q(1) \neq 0$, so we conclude that
\begin{equation}
    \supp(x^q(1)) = L_1(q) \cup \{q\}.
\end{equation}
Since $\supp(x^q(1)) \in D$ and $L_1(q) \in C$, where  $D=\{A\subseteq [N] \mid q\in A\}$ and  $C= \mathcal{P}([N]\setminus\{q\})$, the map $ \Theta_1^q: D\rightarrow C$ from Lemma (\ref{theta1}) is well-defined.

Applying \( \Theta_1^q \) to both sides, we compute:
\begin{equation}
\begin{split}
    \Theta_1^q (\supp(x^q(1)))
    &= (L_1(q)\cup \{q\})\setminus \{q\} \\
    &= L_1(q).
    \end{split}
\end{equation}
Since \( \Theta_1^q \) is a bijection, it establishes a one-to-one correspondence between $\supp(x^q(1))$ and $L_1(q)$ in this case.

(b) The case \( x^q_q(1) = 0 \):

In this case, $ q \notin \supp(x^q(1)) $, so we directly have
\begin{equation}
    \supp(x^q(1)) = L_1(q).
\end{equation}
Here, the identity map $ \mathrm{id}: \mathcal{P}([N]\setminus\{q\}) \to \mathcal{P}([N]\setminus\{q\})$ is a bijection.

Thus, for every $q$, we establish a one-to-one correspondence between $\supp(x^q(1))$ and $L_1(q)$, either via the bijection $\Theta_1^q$ in Case (a) or the identity map in Case (b). Furthermore, in both cases,  taking the cardinality of both sides gives
\begin{equation}
|\supp(x^q(1))|\leq |L_1(q)|+1.
\end{equation}
Since $|L_1(q)|=d_q$, by definition, we have
\begin{equation}
    |\supp(x^q(1))|\leq d_q+1.
\end{equation}
\end{proof}
Notably, there is no single bijection that applies to all $x^q(1)$ simultaneously. Instead, the reconstruction process is case-dependent.

\begin{corollary}    \label{corollary_reconstructable}
    If the state vector $x^q(1)$ is uniquely $(P0)$ reconstructible, then $L_1(q)$ can be uniquely determined via $(P0)$ problem. If $x^q(1)$ is uniquely $(P0)$ reconstructible for every $q\in [N]$,then the network $\mathcal{G}$ is topologically reconstructible. 
\end{corollary}
\begin{proof}
    This result follows from Lemma \ref{havingL1}. If the state vector \(x^q(1)\) is $(P0)$ uniquely reconstructible for a given $q\in [N]$, we can determine $L_1(q)$. Since \(\{L_1(q)\}_{q=1}^N\) uniquely determines the adjacency matrix \(A\) of the underlying graph of the network $\mathcal{G}$ (see Remark \ref{trc}), it follows that if the state vector \(x^q(1)\) is $(P0)$ uniquely reconstructible for every $q\in [N]$, then $\mathcal{G}$ is topologically reconstructible from mean-fields.
\end{proof}


\subsection{Proof of Theorem \ref{topologicalcondition}}
First, we need the following:
 \begin{lemma} \label{spark_sparsest}
    If the solution $x_*$ to $(P0)$ problem satisfies $\|x_*\|_0< \frac{\spark(\phi)}{2}$, then the solution is unique, and $x_*=x$.
    \end{lemma}
    \begin{proof}
    By contradiction, let  $x_1, x_2$ be distinct solutions. Then, $h=x_1-x_2$ is in the  null-space of $\phi$, meaning $\|h\|_0\geq \spark(\phi)$. Since $\|x_1\|_0, \|x_2\|_0< \frac{\spark(\phi)}{2}$, we get $\|h\|_0<\spark(\phi)$. 
\end{proof}

\noindent
{\bf Proof of Theorem \ref{topologicalcondition}}
The mean-field measurements are given by
\begin{equation}
    y^q(1) = \phi_q x^q(1),
\end{equation}
for each $q\in [N]$.

First, by Lemma \ref{spark_sparsest}, the optimization problem,
\begin{equation}
     \min\|\tilde{x}^q(1)\|_0 \text{  subject to } y^q(1) = \phi_q \tilde{x}^q(1),
\end{equation}
admits a unique solution $x^q_*(1)$ if
\begin{equation}
    \|x^q(1)\|_0<\frac{\spark(\phi_q)}{2}.
\end{equation}

Next, we apply the assumption that the measurement matrices $\{\phi_q(1)\}_{q=1}^N$ are full-spark $\spark(\phi_q)=P+1$. Also, by assumption, $P>2\Delta(G)+1$. Thus,
\begin{equation}
    \spark(\phi_q)> 2(\Delta(G)+1), \text{ for all }q\in [N].
\end{equation}
Then, the sufficient condition for $(P0)$ unique reconstructibility simplifies to 
\begin{equation}\label{reco_simple}
    \|x^q(1)\|_0<\Delta(G)+1, \text{ for all }q\in [N].
\end{equation}

Since Lemma \ref{havingL1} establishes that $\|x^q(1)\|_0\leq d_q+1$ for any $q\in [N]$, and by definition, the maximum out-degree of the network is
\begin{equation}
    \Delta(G) = \max_{q\in[N]}d_q,
\end{equation}
it follows that
\begin{equation}
    |\supp(x^q(1))|\leq \Delta(G)+1, \text{ for all }q\in [N].
\end{equation}
Consequently, by Corollary \ref{corollary_reconstructable}, the network $\mathcal{G}$ is topologically reconstructible.  $\square$

   \subsection{Proof of Corollary \ref{first_corol}}


A matrix \(\phi\) is full-spark if and only if every set of $P$ columns of $\phi$ is linearly independent, which is equivalent to every $P\times P $ submatrix of $\phi$ being invertible.

The set of matrices with $P$ linearly dependent columns (i.e., matrices where the determinant is zero) forms a lower-dimensional subset in the space of all matrices. Since the determinant is a continuous function of the matrix entries, the set of matrices where the determinant is zero has Lebesgue measure zero in the space of all possible matrices. Furthermore, a finite union of these determinant-zero sets remains a measure zero set.

Gaussian measure is absolutely continuous with respect to Lebesgue measure. This implies that the probability of selecting a matrix from any set of measure zero (such as the set where the determinant is zero) is zero. Therefore, the union of the  $\det^{-1}(0)$ sets, which corresponds to matrices with linearly dependent columns, has Gaussian measure zero.

Thus, with probability one, each $\phi_q$ is full-spark, and the corollary follows.  $\square$

\subsection{Proof of Corollary \ref{er_theorem}}

To formalize the scaling relationships used in the proof of Corollary \ref{er_theorem}, we introduce the following asymptotic notation:

\begin{definition}
Let \( f(P) \) and \( g(P) \) be functions from the integers to the positive real numbers. We define their asymptotic relations as follows:

\begin{itemize}
    \item \( f(P) = \mathcal{O}(g(P)) \) if there exist constants \( C > 0 \) and \( P^0 \in \mathbb{N} \) such that \( |f(P)| \leq C g(P) \) for all \( P > P^0 \).

    \item \( f(P) = \Theta(g(P)) \) if there exist constants \( C_1, C_2 > 0 \) and \( P^0 \in \mathbb{N} \) such that \( C_1 g(P) \leq |f(P)| \leq C_2 g(P) \) for all \( P > P^0 \).

\item \( f(P) = \Omega(g(P)) \) if there exist constants \( C_1 > 0 \) and \( P^0 \in \mathbb{N} \) such that \( |f(P)| \geq C_1 g(P) \) for all \( P > P^0 \).

    \item \( f(P) = o(g(P)) \) if for every \( \varepsilon > 0 \), there exists \( P^0 \in \mathbb{N} \) such that \( |f(P)| < \varepsilon g(P) \) for all \( P > P^0 \).
\end{itemize}
\end{definition}

\subsubsection{Proof of Corollary \ref{er_theorem}}
Let the maximum degree \( \Delta(G) \) deviate from the expected degree by a perturbation \( \xi(N) \), i.e.,
\begin{equation}
        \Delta(G) = Np + \xi(N).
\end{equation}
In the large \( N \) limit, the weak Topological Reconstruction Condition (wTRC) from Theorem \ref{topologicalcondition} becomes
\begin{equation}
    \begin{split}
    2Np + 2\xi(N) + 1 &< P(N), \\
    p &< \frac{P(N)}{2N} \left( 1 - \frac{1}{P(N)} - \frac{2\xi(N)}{P(N)} \right).
\end{split}
\end{equation}
Thus, to satisfy the bound asymptotically, the deviation must satisfy
\begin{equation}
    \xi(N) = o(P(N)).
\end{equation}

We now analyze this requirement in two classical regimes of the Erd\H{o}s-Rényi graph:

Case 1: (Supercritical regime) Suppose \( p = \frac{\log N}{N}(1 - \epsilon) \) for some fixed \( \epsilon \in (0,1) \). It is known that in this regime, the maximum degree satisfies
\begin{equation}
     \Delta(G) = \mathcal{O}\left( \frac{\log N}{\log\log N} \right)
\end{equation}
with high probability \cite{frieze2015introduction}. Hence, taking \( \xi(N) = \mathcal{O}\left( \frac{\log N}{\log\log N} \right) \), we find that if \( P(N) = \Omega(\log N) \), then
\begin{equation}
     \xi(N) = o(P(N)).
\end{equation}
Therefore, wTRC is satisfied with high probability, ensuring unique topological reconstruction.

Case 2: (Connected regime) Suppose \( p = \frac{\log N}{N}(1 + \epsilon) \) for some fixed \( \epsilon \in (0,1) \). Then the graph is connected with high probability, and it is well known (e.g., \cite{frieze2015introduction}) that:
\begin{equation}
        \mathbb{P}\left(\Delta(G) \leq \mathbb{E}[d] + \mathcal{O}(\sqrt{Np\log N}) \right) \to 1.
\end{equation}
In this case, since \( p = \Theta\left( \frac{\log N}{N} \right) \), we find
\begin{equation}
      \xi(N) = \mathcal{O}(\sqrt{\log^2 N}) = \mathcal{O}(\log N).
\end{equation}
Thus, if \( P(N) = \Omega(\log^2 N) \), we again have
\begin{equation}
     \xi(N) = o(P(N)).
\end{equation}
and wTRC holds with high probability.  $\square$

\subsection{Proof of Theorem \ref{P1-main}} 

We define  $(P0) \sim (P1)$ regime as follows: 
\begin{definition}\label{P0-P1-eq}
    The region in which the solution of the $(P1)$ problem is unique and it is identical to the solution to $(P0)$ problem is called the
$(P0)\sim (P1)$ equivalence regime.
\end{definition}

In the $(P0)\sim (P1)$ equivalence regime, the unique solution to $(P1)$ problem is determined, and it is shown to coincide with the unique solution of the $(P0)$ problem \cite{candes2005decoding}. This equivalence regime not only expands the region where the $(P0)$ problem admits a unique solution, but also makes this region computationally tractable.



To establish the Theorem \ref{P1-main}, we invoke the following lemma: 
\begin{lemma}\label{noiseless}
    Assume \(\delta_{2s}(\phi)<\sqrt{2}-1.\) Then the solution \(x_*\) to \( P_1\) problem obeys
    \begin{equation}
        \|x-x_*\|_2 \leq c_0 s^{-1/2}  \|x-x_s\|_1
    \end{equation}
for some constant \(c_0\) where \(x_s\) is the vector x with all but the \(s\)-largest entries set to zero. The recovery is exact if \(x\) is \(s\)-sparse \cite{candes2008restricted}.
\end{lemma}
\subsubsection{Proof of Theorem \ref{P1-main}}
The mean-field measurements are given by
\begin{equation}
    y^q(1) = \phi_q x^q(1),
\end{equation}
for each $q\in [N]$.
First, by Lemma \ref{noiseless}, the optimization problem,
\begin{equation}
     \min\|\tilde{x}^q(1)\|_1 \text{  subject to } y^q(1) = \phi_q \tilde{x}^q(1),
\end{equation}
admits a unique solution $x^q_*(1)$ if
\begin{equation}
    \|x^q(1)\|_0\leq s,
\end{equation}
where $s =\Delta(G)+1$.

Then, the sufficient condition for $(P1)$ unique reconstructibility simplifies to 
\begin{equation}\label{reco_simple}
    \|x^q(1)\|_0\leq \Delta(G)+1, \text{ for all }q\in [N].
\end{equation}

Since Lemma \ref{havingL1} establishes that $\|x^q(1)\|_0\leq d_q+1$ for any $q\in [N]$, and by definition, the maximum out-degree of the network is
\begin{equation}
    \Delta(G) = \max_{q\in[N]}d_q,
\end{equation}
it follows that
\begin{equation}
    |\supp(x^q(1))|\leq \Delta(G)+1, \text{ for all }q\in [N].
\end{equation}
Consequently, by Corollary \ref{corollary_reconstructable}, the network $\mathcal{G}$ is topologically reconstructible. 
 $\square$
\subsection{Proof of Theorem \ref{two-stage}}

The mean-field measurements are given by
\begin{equation}
    y^q(t) = \phi_q x^q(t),
\end{equation}
for each $q\in [N]$ and each $t\in [T]$.

First, by Lemma \ref{noiseless}, the optimization problem,
\begin{equation}
     \min\|\tilde{x}^q(t)\|_1 \text{  subject to } y^q(t) = \phi_q \tilde{x}^q(t),
\end{equation}
admits a unique solution $x^q_*(t)$ if
\begin{equation}
    \|x^q(t)\|_0\leq s,
\end{equation}
where $s =[\Delta(G)+1]^{s_{\max}}$.

Lemma \ref{havingL1} establishes that $\|x^q(1)\|_0 \leq d_q+1$ for any $q \in [N]$. Since the maximum out-degree is defined as
\begin{equation}
    \Delta(G) = \max_{q \in [N]} d_q,
\end{equation}
it follows that
\begin{equation}
    |\supp(x^q(1))| \leq \Delta(G)+1, \quad \text{for all } q \in [N].
\end{equation}
Since at each time step the support of $x^q(t)$ may grow by at most $\Delta(G)+1$, we conclude by induction that
\begin{equation}
    |\supp(x^q(t))| \leq [\Delta(G)+1]^t, \quad \text{for all } q \in [N], \, t \in [T].
\end{equation}
By assumption, $T = s_{\max}$, and so we obtain
\begin{equation}
    |\supp(x^q(t))| \leq [\Delta(G)+1]^{s_{\max}}, \quad \text{for all } q \in [N], \, t \in [T].
\end{equation}


 Thus, the recovered state vectors $x^q(t)$ are unique for every $q \in [N]$, and $t\in [T]$. 

The system evolves according to the oracle dictionary:
\begin{equation}
    x_i(t+1) = \sum_{l=1}^{s_i} c_{i,l} \, \psi_i^l(x(t)).
\end{equation}

Stacking the system over time, we obtain:
\begin{equation}
    \begin{pmatrix}
        x_i(1)\\
        x_i(2)\\
        \vdots\\
        x_i(T)
    \end{pmatrix} =
    \underbrace{
    \begin{pmatrix}
        \psi_i^1(x(1)) & \cdots & \psi_i^{s_i}(x(1)) \\
        \psi_i^1(x(2)) & \cdots & \psi_i^{s_i}(x(2)) \\
        \vdots         & \ddots & \vdots \\
        \psi_i^1(x(T)) & \cdots & \psi_i^{s_i}(x(T))
    \end{pmatrix}}_{\psi_i \in \mathbb{R}^{T \times s_i}}
    \begin{pmatrix}
        c_{i,1}\\
        \vdots\\
        c_{i,s_i}
    \end{pmatrix}.
\end{equation}

The coefficients $c_{i,l}$ are assumed to be non-zero by the definition of the oracle dictionary. For the coefficient vector to be uniquely identifiable, it is necessary that the matrix $\psi_i$ has full column rank. The necessary condition is that
\begin{equation}
    T \geq s_i, \quad \text{for each } i \in [N].
\end{equation}
Since $T = s_{\max}$ and $s_i \leq s_{\max}$, this condition is satisfied. Therefore, the coefficient vector $c_i = (c_{i,1}, \ldots, c_{i,s_i})^T$ is uniquely determined.

Thus, the maximum time step is the minimum value assuring the existence of the unique coefficients.

Observe that this is for any state vector, but we only have access to pinching states. So, we will use an enlarged dictionary matrix to suffice the unique coefficients.

 Item (i) follows from the correspondence in Theorem \ref{P1-main}.

Item (ii):
Given that each $\psi_i$ has full column rank and $Ns_{\max}>s_i$ for each $i\in[N]$, the pseudoinverse $\Psi_i^\dagger$ simplifies to the left inverse: 
\begin{equation}
    \Psi_i^\dagger = (\Psi_i^T\Psi_i)^{-1}\Psi_i^T.
\end{equation}
Since the quadratic loss in the associated least-squares problem is strictly convex (due to full rank), the solution
\begin{equation}
    \hat{c}_i = (\Psi_i^T\Psi_i)^{-1}\Psi_i^Tx_i^{(q)}(1,\cdots,s_{\max}),
\end{equation}
is unique.
 $\square$









