 \subsection{Functional settings.}
\noindent We begin with the notation that will be used throughout. \\
$(\cdot, \cdot) \equiv ( \cdot, \cdot)_{L_2(\Omega)} $, $||u||_s \equiv ||u||_{H^s(\Omega) } $, where $H^s(\Omega) $ is a standard Sobolev space of order $s\in R $.

Following \cite{BGLW22}, we  introduce the  space:  $H^2_\ast = \left\{ u\in H^2(\Omega);~ u=0~\mbox{on}~\{0,\pi\}\times[-l,l] \right\}$, endowed with topology $\|u\|_{2,\ast}^2 = a(u,u)$, for $u\in H^2_\ast$ (equivalent to the usual Sobolev norm  $\|.\|_2$, where the scalar product $a(\cdot,\cdot)$ is given by
\begin{equation}
    \label{bifa} a(u,v) = \int_\Omega\left[ \Delta{u}\Delta{v} - (1-\sigma)\left(u_{xx}v_{yy} + u_{yy}v_{xx} - 2u_{xy}v_{xy} \right) \right] dx dy,\quad\mbox{for}~u,v\in H^2_\ast.
\end{equation}

Using this notation, we define a positive, self-adjoint operator $A: \cD(A) \subset L^2(\Omega) \to L^2(\Omega)$  equipped with {\it free/hinged}  boundary conditions: 
\begin{equation*}\begin{aligned}
    &A{u} = \Delta^2{u},  ~for~ u\in \cD(A) \mbox{ where}\\
    &\cD(A):= \!\left\{u \in  H^2_\ast, \Delta^2u\in L_2(\Omega) 
    \left|\begin{array}{cl} 
      \Delta   u = 0 & \mbox{on $ \Gamma_1 $ } \\
        u_{yy} + \sigma u_{xx}=0 = u_{yyy} + (2-\sigma)u_{xxy} & \mbox{on $ \Gamma_0 $}
    \end{array}\right.\!
    \right\}
\end{aligned}\end{equation*}
Due to specific configuration of the boundary conditions, one has $\cD(A) \subset H^4(\Omega)$, \cite{BGLW22,Gazzola15}.

The operator $A$ can be extended to a closed, positive self-adjoint operator as \newline $A:H^2_\ast\to(H^2_\ast)'$ by means of the following characterization
$a(u,v)=\dual{Au}{v},\mbox{ for}~u,v\in H^2_\ast.$\\
one also obtains $||u||_{\cD(A^{1/2} )}^2 = a(u,u) , u \in H^2_\ast $.\\
The nonlocal damping $g(||v||) v $  leads to a nonlinear operator  $D: \cD(A^{1/2}) \to L^2(\Omega)$, which is monotone and   expressed as $D{v}=g(\|v\|_0)v$ for every $v\in L^2(\Omega)$. Finally, the source operator is denoted by $F:H^2_\ast\to L^2(\Omega)$ with the following action
        \begin{equation}\label{F}
              F{u}=-\left[ (\alpha-\delta\|u_x\|_0^2)u_{xx} + f(u) + \beta u_y\right],\quad \mbox{for every } u\in H^2_\ast.
        \end{equation}
Note that $F$ has the form $F(u):=-\Pi^{\prime}(u)+N(u)$, with  non-conservative part $N(u) =-\beta u_y$ and conservative part  $\Pi(u)$, where 
 $\Pi'$  stands for Frechet derivative of the energy functional $\Pi:H^2_\ast\to\R$  given by:
        \begin{equation}\label{pi}
               \Pi(u) = \frac{\kappa}{2}\|u^+\|_0^2 - \frac{\alpha}{2}\|u_x\|_0^2+\frac{\delta}{4}\|u_x\|_0^4  + \int_\Omega \tilde{f_0}(u(x))dx \quad\mbox{for}~u\in H^2_\ast,
        \end{equation}
%where $\tilde{f}$ denotes an antiderivative of $f$. 
%In the case of  our bridge model, the energy relation will take the form given in (\ref{nrg_id0}).
    With  the \textit{phase space} $\cH \equiv H^2_\ast\times L^2(\Omega)$ under  the norm 
$$\|\{u,v\}\|_\cH^2 = \|u\|_{2,\ast}^2 + \|v\|_0^2\mbox{ for }\{u,v\}\in\cH,$$ 
for each $\mbf{u}=\{u,v\}\in\cH$ the \textit{energy functional} $\cE:\cH\to\R$ associated with \eqref{sbe} is given by
        \begin{align}
              \cE(\mbf{u}) =\frac{1}{2}\left[\|u\|_{2,\ast}^2 + \|v\|_0^2 \right]+\Pi(u)= \frac{1}{2}\|\mbf{u}\|_{\cH}^2+\Pi(u). \label{nrg}
        \end{align}
%The operator $\Pi$ is  given by the expression \eqref{pi}.
 By {\it formal} calculations one obtains the following  {\it energy equality}, 
 \begin{align}
        \cE(\mbf{u}(t)) + \int_s^t g(\|u_t\|_0)\|u_t\|_0^2
        = \cE(\mbf{u}(s)) 
        - \beta\int_s^t\!\!\int_\Omega u_y u_t,\quad\mbox{for}~s\leq t. \label{nrg_id0}
    \end{align}
which displays  the presence of the non-conservative feedback force and the lack of dissipativity,

We shall show next that the system under consideration \eqref{sbe}-\eqref{IC} can be embedded into a class of more general 
abstract second order [in time]  {\it non-conservative and  non-dissipative } form.
With  $A$ described as before, $D: \cD(A^{1/2} ) \rightarrow \cD(A^{1/2})' $ monotone increasing, hemicontinuous  nonlinear operator,  $\Pi:\cD(A^{1/2} ) \rightarrow R $, a  $C^1$  functional and  nonconservative term $N : \cD(A^{1/2} )\rightarrow L_2(\Omega)$.
%\\ With $\mbf{u}(t) \in \cH \equiv  D(A^{1/2}) \times L_2(\Omega) $ 
consider
        \begin{align}\label{sbe_abs} 
         \begin{cases}
               &u_{tt}(t) + A{u(t)} + D(u_t(t)) = F(u(t))=-\Pi^{\prime}(u)+N(u),\quad t>0, \\
               &\{u(0),u_t(0)\} = \{u_0,u_1\} \in \cH  \equiv  \cD(A^{1/2}) \times L_2(\Omega) 
         \end{cases}
        \end{align}    
