\section{Main Results.}\label{mainresults}
The main results of this study focus on long time behavior of the dynamics, which can be characterized by attracting sets and their properties. The very first step toward this goal is to guarantee  global existence of {\it bounded in time }solutions for the associated dynamical system.
As we shall see, this will turn possible due to the nonlinearity of potential energy.
\subsection{Formulation of the results.}
\begin{definition}
    Let $T>0$. We say that $u:[0,T]\to L^2(\Omega)$ is a \textbf{strong solution} of \eqref{sbe}-\eqref{IC} on $[0,T)$ if $\mbf{u}=\{u,u_t\}\in C([0,T);\cH) \cap W^{1,1}_{loc}(0,T;\cH)$ with values $\mbf{u}(t)\in \cD(A)\times H^2_\ast$ for almost every $t \in [0,T]$, equation $\eqref{sbe_abs}$ is verified in $L^2(\Omega)$ for almost every $t\in[0,T]$ and the initial data in $\eqref{sbe_abs}$ hold.
    We say that $u$ is a \textbf{generalized solution} of \eqref{sbe}-\eqref{IC} on $[0,T]$ if $\mbf{u}=\{u,u_t\}\in C(0,T;\cH)$, the initial data in $\eqref{sbe_abs}$ hold and there exists $\{{u}^n\}_{n\in\N}$ sequence of strong solutions of \eqref{sbe}-\eqref{IC} on $[0,T)$ such that 
         \begin{equation}
                \lim_{n\to\infty}\max_{t\in[0,T]}\|\mbf{u}^n(t) - \mbf{u}(t)\|_\cH = 0.
        \end{equation}
\end{definition}

\begin{remark}
    Notice that, $\cD(A) \subset H^4(\Omega) $ \cite{BGLW22,Gazzola15}, thus if $u$ is a strong solution of \eqref{sbe}-\eqref{IC} on $[0,T)$ then $u(t)\in H^4(\Omega)\cap H^2_\ast$ for almost every $t\in[0,T]$.
\end{remark}

\noindent The wellposedness of generalised and strong solutions to \eqref{sbe}-\eqref{IC} is given below. 



\begin{theorem}{\bf Wellposedness.}\label{thm:EU}
    Let $T>0$ and assume that $f_0$ satisfies \eqref{aspf-1} and $g(s) $ is monotone increasing, continuous on $\R_+$. Then, for each $\{u_0,u_1\}\in \cD(A)\times H^2_\ast$, there exists a unique \textbf{strong solution} $u$  of (\ref{sbe}) on the interval $[0,T]$ such that $\mbf{u}=\{u,u_t\}\in C(0,T;\cH)$ and $t\mapsto\mbf{u}_t(t)=\{u_t(t),u_{tt}(t)\}$ is weakly continuous in $\cH$. Moreover, 
    \begin{align}
        \mbf{u} \in L^\infty(0,T;\cD(A)\times H^2_\ast)\cap W^{1,\infty}(0,T;\cH); ~~ \cD(A) \subset H^4(\Omega)  \label{reg}
        % \\ u\in L^\infty(0,T;D(A))\cap W^{1,\infty}(0,T;H^2_\ast)\cap W^{2,\infty}(0,T;L^2(\Omega)).
    \end{align}
    In addition, the following \textbf{energy identity}
    holds:
    \begin{align}
        \dfrac{d}{dt}\cE(\mbf{u}) + g(\|u_t\|_0)\|u_t\|_0^2
        = - \beta\int_\Omega u_y u_t,\quad\mbox{for}~t>0.
    \end{align}      
    If $\{u_0,u_1\}\in\cH$, then there exists a unique \textbf{generalized solution} $u$ to \eqref{sbe}-\eqref{IC} such that $\mbf{u}=\{u,u_t\}\in C(0,T;\cH)$ which  verifies the  integral form of the {\bf energy identity} 
    \begin{align}
        \cE(\mbf{u}(t)) + \int_s^t g(\|u_t\|_0)\|u_t\|_0^2
        = \cE(\mbf{u}(s)) 
        - \beta\int_s^t\!\!\int_\Omega u_y u_t,\quad\mbox{for}~s\leq t. \label{nrg_id}
    \end{align}
    In addition, each generalised solution is  a {\it weak} solution satisfying standard variational form of equation with test functions in $H^2_\ast$.
\end{theorem}

Theorem \ref{thm:EU} asserts  Hadamard wellposedness, hence an existence of the dynamical system $\{\cH,S_t\}$, where $S_t:\cH\to\cH$ and $t\geq0$, is given by $S_t\mbf{u}_0\equiv\mbf{u}(t)=\{u(t),u_t(t)\}$ the corresponding weak solution of \eqref{sbe}-\eqref{IC} with initial data $\mbf{u}_0\in\cH$. The proof is based on monotone operator theory \cite{Bar76,SHO97}, after  the bound from below of potential energy is asserted. The details are in Section \ref{wellposedness}. Of particular relevance is the fact that generalized solutions do satisfy energy {\it identity} and also weak variational form. \\

Long time behavior of the said dynamical system $(\cH,S_t) $ is discussed nest. 
