\begin{lemma}\label{lem:op_F}
    Assume that $f_0\in C^1(\R)$. Then, $F:H^2_\ast\to L^2(\Omega)$ is locally Lipschitz.
\end{lemma}
\begin{proof}
    Let $R>0$ and $u,v\in H^2_\ast$ such that $\|u\|_{2,\ast},\|v\|_{2,\ast}\leq R$. Hence, using the representation of   $F$
    %(see Section \ref{ssct:Not}),
    we have
    \begin{align}
        \|Fu-Fv\|_0
        &\leq \kappa\|u^+-v^+\|_0
        + \alpha\|u_{xx}-v_{xx}\|_0
        + \delta\|\|u_x\|_0^2u_{xx} - \|v_x\|_0^2v_{xx}\|_0
        + \|f_0(u)-f_0(v)\|_0 \notag\\
        &+ |\beta|\|u_y-v_y\|_0 \notag\\
        &\leq
        \kappa \|u-v\|_0
        + \alpha\|u_{xx}-v_{xx}\|_0
        + \delta\|u_x\|_0^2\|u_{xx}-v_{xx}\|_0
        + \delta\|v_{xx}\|_0\abs{\|u_x\|_0^2 - \|v_x\|_0^2} \notag\\
       & + \left\{\max_{|s|\leq2R}|f_0'(s)|^2\right\}^{1/2}\|u-v\|_0
        + |\beta|\|u_y-v_y\|_0 \notag\\
        &\hspace*{3pt} \leq \underbrace{\left[\kappa+|\alpha|+\delta R(1+2R)+ \left\{\max_{|s|\leq2R}|f'_0(s)|^2\right\}^{1/2} + |\beta|\right]}_{L_{f,R}}\|u-v\|_{2,\ast}
    \end{align}
    and consequently $\|Fu-Fv\|_0\leq L_{f,R}\|u-v\|_{2,\ast}$, for every $u,v\in H^2_\ast$. This shows that $F$ is locally Lipschitz from $H^2_\ast$ to $L^2(\Omega)$. 
\end{proof}

