                         \left(N(u),u_t\right)
                         &\leq \|\beta u_y\|_0 \|u_t\|_0
                          \leq C_{\tilde{\eta}} \|\beta u_y\|_0^{\frac{q+2}{q+1}}+ \tilde{\eta} \|u_t\|^{q+2}_0\leq C_{\tilde{\eta}} \|\beta u_y\|_0^{\frac{q+2}{q+1}}+ \tilde{\eta}(Du_t,u_t)
