             & \int_\Omega |z_t|^2 
             \leq 
             \mathcal{K}\left( D(u_t) -D(v_t),z_t\right)_{\Omega},\notag \\
             \intertext{\mbox{by integrating  in time and applying Jensen's inequality to obtain,}}
       % &\leq \!C_{ \Omega}\! \!\left[\mathcal{K}\left( 
            %\frac{1}{ m_\Omega}
            % \int_\Omega \!
             %(Du_t- Dv_t,z_t) \!\right)\!\right]
            % \mbox{By Jensen's 
            % inequality for } \mathcal{\!K} \text{ where, } m_\Omega=meas(\Omega)
    &\int_0^T \|z_t\|^2 dt \leq 
             \int_0^T \mathcal{K} \left[( D(u_t) -D(v_t),z_t)_{\Omega}
