   \begin{lemma}\label{Dutu.}
       For some $2 \geq \eta>0, t \in [0, T]$  and  $\mbf{u}, \mbf{v}$ as described in \eqref{damping1} one obtains:
       \begin{equation*}
           \int_0^T |(D(u_t)-D(v_t),z)_\Omega| \leq \int_0^T ||z_t||^2_0   + C_{\cB} T \sup_{t \in [0, T]} \|z\|_{2-\eta, \Omega}^2.
       \end{equation*}
   \end{lemma}
    \begin{proof}
    Using the same strategy as before in \eqref{lem:EE-06}, one obtains,
    \begin{align}
        \int_0^T|(D(u_t)-D(v_t),z)_\Omega|\leq \!
            &\int_0^T\!\!\|z_t\|_0^2 
               \!+C_{\cB, q} T \sup_{t \in [0, T]} \|z\|_0^2. 
            \notag
    \end{align}
    Thus, the lemma is proved for $\eta=2$.
    \end{proof}

    \begin{lemma}\label{fz}
     For some $\gamma>0, t \in [0, T]$ and $\mbf{u}, \mbf{v}$ as described in \eqref{damping1} we have,
     \begin{equation}\label{1fz}
         \int_0^T |(F(u)-F(v),z)| \leq \gamma \int_0^T \tilde{E}(\mbf{z})+C_{\cB, \gamma}\int_0^T\|z\|_0^2. 
     \end{equation}
    \end{lemma}
    \begin{proof}
    Since $F$ is locally Lipschitz from $H^2_\ast$ (by \eqref{lem:op_F}) to $L^2(\Omega)$, we have
    \begin{align*}
        \abs{\int_0^T(F(u)-F(v),z)_\Omega}
        \leq L_{\cB}\int_0^T\!\!\|z\|_{2,\ast}\|z\|_0
        \leq \gamma\int_0^T\!\!\tilde{E}(\mbf{z})
        + \frac{L_{\cB}^2}{4\gamma}\int_0^T\|z\|_0^2,
    \end{align*}
    for every $\gamma>0$ (arbitrarily small), where $L_B>0$ is the Lipschitz constant of $F$ on $B$.   
     \end{proof}

     {\bf Step 3: Verification of  the assumptions postulated by  Proposition \ref{thm:C17}.}
    % \begin{proof}
     Observe that for strong solutions $\mbf{u}, \mbf{v} $ and $\mbf{z}=\mbf{u}-\mbf{v}$ the relation \eqref{1lem:EE-01} and existence of absorbing ball ($\cB$) gives us $\tilde{E}(\mbf{z}(t)) \leq C_{\cB}$ for any $t \geq 0$, hence
     \begin{align}\label{12lem:EE-01}
         \int_s^t(D(u_t)-D(v_t),z_t)_\Omega- \int_s^t(F(u)-F(v),z_t)_\Omega
        \leq \abs{ \tilde{E}(\mbf{z}(s))-\tilde{E}(\mbf{z}(t))}\leq 2 C_{\cB} ,\quad s\leq t.
     \end{align}
     Using the Lemmas \ref{damping1}, \ref{Dutu.} and \ref{fz} in \eqref{13lem:EE-03}, we obtain with any $\gamma >0$,
     \begin{align}
         \frac{T}{2}\tilde{E}(\mbf{z}(T)) 
              &\!+\! \int_0^T 
              \tilde{E}(\mbf{z}) \!\leq \!4T C_{\Omega}\left[\mathcal{K}\left(\frac{1}{ T  }\int_0^T(Du_t- Dv_t,z_t)_{\Omega)})dt\right)\right]  \notag \\
              &  +\! \int_0^T \!(D(u_t)-D(v_t),z_t)_\Omega \!+\!C_{\cB, q} T 
                  \sup_{t \in [0, T]} \|z\|_0^2+ \gamma \int_0^T \tilde{E}(\mbf{z})+C_{\cB, \gamma}\int_0^T\|z\|^2 \notag \\
              &  -\int_0^T(F(u)-F(v),z_t)_\Omega
                        + \int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega\notag \\
   % &\mbox{finally, using} \eqref{12lem:EE-01}\notag  \\
              &   \leq \!4T C_{\Omega}\left[\mathcal{K}\left(\frac{1}{ T  
                  }\int_0^T(D(u_t)- D(v_t),z_t)_{\Omega} dt\right)\right]+2C_{\cB} \notag \\
              \hspace{-1pt}&  +\!\left(C_{\cB, q}+C_{\cB, \gamma}\right) T 
                  \sup_{t \in [0, T]} \|z\|_0^2+ \gamma \int_0^T \tilde{E} 
                 (\mbf{z})+ \abs{\int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega}\notag \\
                &\intertext{\mbox{here we used \eqref{12lem:EE-01}, finally for  $\gamma<1,$ we have, }}
                    \frac{T}{2}\tilde{E}(\mbf{z}(T)) 
              &   \leq \!4T C_{\Omega}\left[\mathcal{K}\left(\frac{1}{ T  
                  }\int_0^T(D(u_t) -D(v_t),z_t)_{\Omega}dt\right)\right]+2C_{\cB} \notag \\
              &  \hspace{1cm}+\!C_{\cB, q} T 
                  \sup_{t \in [0, T]} \|z\|_0^2+ \abs{\int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega}, \\
             \intertext{\mbox{however, energy relation for  $z$ variable which eliminates the damping reduces this to, } }
              &\hspace{-1.5cm}\tilde{E}(\mbf{z}(T)) \leq 
                  4 C_{\Omega}\mathcal{K}\left(\frac{1}{ T } 
                   C_B\right)+\mathcal{K}\left( \abs{\frac{1}{T}  \int_0^T ( F(u) - F(v), z_t)_{\Omega}}\right)+\frac{2C_{\cB}}{T}\notag \\
              &  +\!C_{\cB, q}
                  \sup_{t \in [0, T]} \|z\|_0^2+ \frac{1}{T}\abs{\int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega,}\label{id2}
     \end{align}

     We have used the estimate resulting from energy relation and concavity as well as monotone property of $\mathcal{K}$ as stated in the following inequality,  
     $$\mathcal{K}\left( \frac{1}{T} \int_0^T (D(u_t) - D(v_t),z_t)_{\Omega}\right) \leq \mathcal{K} 
               \left(\frac{1}{T} C_B\right) + \mathcal{K}\left( \abs{\frac{1}{T}  \int_0^T ( F(u) - F(v), z_t)_{\Omega}}\right). $$
Recall that the function $\mathcal{K}$ is monotone increasing and concave, thus we have for any $\epsilon_0>0$ the estimate
 \begin{equation}\label{K_2}
     \mathcal{K}\left( \abs{\frac{1}{T}  \int_0^T ( F(u) - F(v), z_t)_{\Omega}}\right) \leq \epsilon_0+C_{\epsilon_0} \abs{\frac{1}{T}  \int_0^T ( F(u) - F(v), z_t)_{\Omega}}.
 \end{equation}
Using this relation we get from \eqref{id2},
 \begin{align}
     \tilde{E}(\mbf{z}(T)) \leq 
                  \frac{2C_{\cB}}{T}
            &+4      C_{\Omega}\mathcal{K}\left(\frac{1}{ T } 
                   C_B\right)+ \epsilon_0+C_{\epsilon_0} \abs{\frac{1}{T}  \int_0^T ( F(u) - F(v), z_t)_{\Omega}}\notag \\
            &+\!C_{\cB, q}
                  \sup_{t \in [0, T]} \|z\|_0^2+ \frac{1}{T}\abs{\int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega}.\label{Ene}
 \end{align}
 %%%%PROOF OF THE ABOVE for a concave function f(x)<epsilon+C_\epsilon . x
We call the function $\Psi$ as the following:
 \begin{align}
     &\Psi_{T, \cB}={\Psi^1}_{T,\cB}\left(\mbf{y}_1,\mbf{y}_2\right) + C_{\epsilon_0}\abs{\frac{1}{T}  \int_0^T ( F(u)- F(v), z_t)_{\Omega}},\label{Psi03} \\
     & \mbox{where, } {\Psi^1}_{T,\cB}=\!C_{\cB, q}\sup_{t \in [0, T]} \|z\|_0^2+ \frac{1}{T}\abs{\int_0^T\!\!\int_t^T(Fu-Fv,z_t)_\Omega}.
 \end{align}
 Note that it is sufficient to prove the {\it lim inf} condition for $\Psi^1$ function because the second term of $\Psi$ in \eqref{Psi03} will satisfy the {\it lim inf} condition by using the same argument that we will be using for $\Psi^1$. The $\epsilon$ in the formulation of the Proposition  \ref{thm:C17} 
 will be obtained by taking  $T$ large enough so that $\epsilon \equiv \epsilon_0 + \frac{2C_B}{T} $ 
 can be made arbitrarily small. 
 The reminder of the the proof will be concentrated on prove the liminf condition $\Psi^1_{T,B}.$

 \noindent Recall from Section \ref{sec:Pre} that, the nonlinear operator $F$ has the form,
   $$Fu =-\left[\kappa u^+ + (\alpha-\delta\|u_x\|_0^2)u_{xx} + f_0(u) + \beta u_y\right].$$
 We consider a sequence of initial data $\{y_n\} \in \cB$. Since  the energy is uniformly  bounded, the corresponding solution $w_n(t)$ of the initial data $y_n$ satisfy the following on a subsequence:
     \begin{align}
     & w^n \to w \mbox{ weakly star in } L^{\infty}(0,T; H^2_\ast(\Omega)),\label{weakast1}\\
     &(w^n)_t \to w_t \mbox{ weakly star in } L^{\infty}(0,T; L^2(\Omega)).\label{weakast2}
     \end{align}
However tracing back in time, from these solutions $w^n(t)$ we can reconstruct the corresponding subsequence of initial data. On the other hand, the relation \eqref{psinm} holds if there exists a subsequence $\{y_{n_k}\}_k \subset \{{y_n}_n\}$ such that,
      $$\lim_{k \to \infty}\lim_{l \to \infty}{\Psi^1}_{T, \cB}(y_{n_l}, y_{n_k})=0.$$ 
Thus it is sufficient to prove that for $\mbf{y}_n=\{w^n, w^n_t\}$ and  $\mbf{y}_m=\{w^m, w^m_t\}$,
     \begin{align}
          &\hspace{2cm}\liminf_{n \to \infty} \liminf_{m \to \infty}{\Psi^1}_{\epsilon,T, \cB}\left({\mbf{y}_{n},\mbf{y}_{m}}\right)=0, \label{psi1}
    \end{align}
   for every fixed $T$ and for any sequence satisfying the properties \eqref{weakast1}, \eqref{weakast2}, where
    \begin{align}
        {\Psi^1}_{\epsilon,T, 
\cB}\left({\mbf{y}_{n},\mbf{y}_{m}}\right) = C_{\cB, q}\sup_{t \in [0, T]} \|w^n-w^m\|_0^2+\frac{1}{T}\abs{\int_0^T\!\!\int_t^T\kappa((w^n)^+-(w^m)^+,w^n_t-w^m_t)_\Omega}, \notag \\
          \quad +\frac{1}{T}\abs{ 
  \int_0^T\!\!\int_t^T\left((\alpha -\delta \|w^n_x\|^2)w^n_{xx}-(\alpha-\delta\|w_x^m\|^2w_{xx}^m),w^n_t-w^m_t\right)} \notag \\
          \quad +\frac{1}{T}\abs{\int_0^T\!\!\int_t^T(f_0(w^n)-f_0(w^m),w^n_t-w^m_t)_\Omega} +\frac{1}{T}\abs{\int_0^T\!\!\int_t^T\beta(w_y^n-w_y^m,w^n_t-w^m_t)_\Omega}. \label{subseq}
     \end{align}
Note that the first factor in the RHS of \eqref{subseq} is
a ``lower order term'', for which the liminf-condition is automatically verified. This follows from Aubin-Lions compactness result.

\noindent For the second term, we essentially deal with the product of weakly and strongly convergent sequences. The details are below.
\begin{align}
&\int_t^T\int_\Omega  \kappa ((w^n)^+-(w^m)^+)\cdot (w^n_t-w^m_t)\notag \\
&=\kappa \frac{1}{2} \left[\|(w^n)^+\|^2+\|(w^m)^+\|^2\right]_t^T-\kappa \int_\Omega \int_t^T ((w^n)^+ , w^m_t)+((w^m)^+ ,w^n_t)
\end{align}
the compactness of $H^2_\ast$ in $L^2$ gives us,
               \begin{equation}\label{same}
                      \left . \left . \lim_{n \to \infty} \|(w^n)^+\|^2\right|_t^T=\|w^+\|^2\right|_t^T \mbox{ and }\left . \left . \lim_{m \to \infty} \|(w^n)^+\|^2 \right|_t^T=\|w^+\|^2\right|_t^T.
                \end{equation}
Due to the energy bounds, the solution $w_n(t)$ satisfies (on a subsequence):
                 \begin{align}
                       w_{t}^n \to w_t \mbox{ weakly star in } L_\infty(0, T; L^2(\Omega)),\notag
                 \end{align}
                   \begin{equation}\label{diff}
                        \mbox{hence, }\lim_{n \to \infty} \lim_{m \to \infty} \int_\Omega \int_t^T ((w^n)^+ \cdot w^m_t+(w^m)^+ \cdot w^n_t)=\left .\|w^+\|^2\right|_t^T,
                   \end{equation}
combining \eqref{same} and \eqref{diff} we conclude that,
 \begin{equation}\label{kappa}
     \liminf_{n \to \infty} \liminf_{m \to \infty}\int_t^T\int_\Omega  \kappa ((w^n)^+-(w^m)^+)\cdot (w^n_t-w^m_t)=0.
 \end{equation}
 For the third term in the expression of ${\Psi^1}$ note that
 $\mbf{y}_n=(w^n,w^n_t)$ is a strong solution thus for $w_t\in \cH_2^*$ integration by parts yields,

 \begin{align}
      & \int_t^T \int_\Omega(\alpha - 
          \delta \|w^n_x\|^2)w^n_{xx}w^n_t= -\left .\frac{\alpha}{2}\|w^n_x\|_0^2\right|_t^T + \left .\frac{\delta}{4}\|w^n_x\|_0^4\right |_t^T,\notag \\
   \intertext{\mbox{therefore by compactness $\|w^n_x\|^2 \to \|w_x\|^2$ and $\|w^n_x\|^4 \to \|w_x\|^4$, we have,}}
        & \lim_{n \to \infty} \lim_{m \to \infty} \int_t^T \int_\Omega(\alpha - 
          \delta \|w^n_x\|^2)w^n_{xx}w^n_t=\left .-\frac{\alpha}{2}\|w_x\|_0^2\right|_t^T + \left .\frac{\delta}{4}\|w_x\|_0^4\right |_t^T, \notag \\
\intertext{\mbox{by the similar argument we conclude}}
            &   \lim_{n \to \infty} \lim_{m \to \infty}\! \int_t^T \!\!\int_\Omega\!\!\left[(\alpha\! -\! 
              \delta \|w^n_x\|^2)w^n_{xx}w^n_t\!+\!(\alpha \!-\! 
          \delta \|w^m_x\|^2)w^m_{xx}w^m_t\right]\!=\!\left .\!- \!
              {\alpha}\|w_x\|_0^2\right|_t^T \!+\! \left .\frac{\delta}{2}\|w_x\|_0^4\right |_t^T. \label{alphadel2}
  \end{align}

\noindent For the mixed [both $n$ an $m$] terms in the third term, the iterated limits give, 
                \begin{align}
                      &\lim_{n \to \infty} 
                          \lim_{m \to \infty}\int_t^T \int_\Omega(\alpha - 
                         \delta \|w^n_x\|^2)w^n_{xx}w^m_t=-\lim_{n \to \infty} 
                         \lim_{m \to \infty} \int_t^T \int_\Omega(\alpha - 
                           \delta \|w^n_x\|^2)w^n_{x}w_{xt}^m\notag \\
                         &=-\lim_{m \to \infty} \int_t^T(\alpha - 
                            \delta \|w_x\|^2)\int_\Omega  w_{x}w^m_{xt} =  -\left.\frac{\alpha}{2}\|w_x\|^2+\frac{\delta}{4} \|w_x\|^4 \right |_t^T.\notag
                        \end{align}
 By similar argument we achieve,
 \begin{align}\label{alpha6}
     \lim_{n \to \infty} 
         \lim_{m \to \infty} \!\int_t^T\!\!\int_\Omega\!\big[(\alpha\! -\! 
                         \delta \|w^n_x\|^2)w^n_{xx}w^m_t\!+\!(\alpha\! -\! 
          \delta \|w^m_x\|^2)w^m_{x}w_{xt}^n\big]=- \left.\alpha\|w_x\|^2+\frac{\delta}{2} \|w_x\|^4 \right |_t^T.
 \end{align}
 Combining \eqref{alphadel2} with \eqref{alpha6} we conclude  that,
 \begin{align}\label{adf}
     \liminf_{n \to \infty} 
         \liminf_{m \to \infty} \int_t^T\int_\Omega \left((\alpha -\delta \|w^n_x\|^2)w^n_{xx}-(\alpha-\delta\|w_x^m\|^2)w_{xx}^m)\cdot (w^n_t-w^m_t\right)=0.
 \end{align}
 Next we focus on the fourth term of $\Psi^1$, we claim, 
 \begin{equation}\label{flim}
     \liminf_{n \to \infty} \liminf_{m \to \infty}\int_0^T\int_t^T(f_0(w^n)-f_0(w^m),w^n_t-w^m_t)_\Omega=0.
 \end{equation}
The proof will be similar to how we have handled the second term in ${\Psi^1}$ i.e; by grouping the mixed items together, let $\tilde{f}$ is the antiderivative of $f$ then
           \begin{align}\label{lipf}
                      \int_t^T\! \!\int_\Omega\!(f_0(w^n)\!-\!f_0 (w^m))(w_t^n-w_t^m)  = \int_{\Omega} [ \tilde{f}_0 (w^m) + \tilde{f}_0(w^m) ]|_t^T \!-\!\! \int_t^T\!\!\int_\Omega \left[f_0(w^n) w_t^m\!+\!f_0(w^m) w_t^n\right].
           \end{align}
For the first two terms using MVT and Young's inequality, we have,
\begin{align}\label{wsc-f1-2}
			&\abs{\int_\Omega\tilde{f}(w^n) - 
                  \int_\Omega\tilde{f}(w)} 
                  \leq C_{T,\mathcal{B}}|\Omega|^{1/2} \int_\Omega |w^n-w|
                  \leq C_{T,\mathcal{B}}|\Omega|^{1/2} \|w^n-w\|_0,
	\end{align}
	where $C_{T,\cB}>0$.
	It follows from the compact embedding and inequality \eqref{wsc-f1-2} that
	\vskip-.15in
	\begin{align}
		&\lim_{n\to\infty}\left.\int_\Omega\tilde{f_0}(w^n)\right|_0^T
		= \left.\int_\Omega\tilde{f}_0(w)\right|_0^T \quad \mbox{and }\notag \\
		&\lim_{n\to\infty}\liminf_{m\to\infty}\left\{
		\left.\int_\Omega \tilde{f_0}(w^n)\right|_0^T
		+ \left.\int_\Omega \tilde{f_0}(w^m)\right|_0^T
		\right\}
		= 2\left.\int_\Gamma\tilde{f_0}(w)\right|_0^T, \label{wsc-f1-3}
	\end{align}
for the mixed terms in the RHS of \eqref{lipf}, we have $w^m_t\to w_t$ weakly in $L^2(Q_0^T)$, on the other hand, since $w^n\to w$ almost everywhere in $Q_0^T$, it follows from the continuity of $f_0$ that $f_0(w^n)\to f(w)$ almost everywhere in $Q_0^T$. Therefore, we must have
	$f(w^n)\to f(w)$ weakly in $L^2(Q_0^T)$. Thus after taking the iterated limits,
	we have,
	\vskip-.15in
	\begin{equation}\label{wsc-f0-4}
		\liminf_{n\to\infty}\liminf_{m\to\infty}
		\int_{\Omega}\int_0^T\left[f_0(w^n)w^m_t+f_0(w^m)w^n_t\right]
		= 2\left.\int_\Omega\tilde{f_0}(w)\right|_0^T,
	\end{equation}
 thus we get \eqref{flim} by combining \eqref{wsc-f0-4} and \eqref{wsc-f1-3}.\\
For the last term, in ${\Psi^1}$ we deal  again with the product of weak and strong convergence. 
 This can be seen directly  from the calculations below. 
 \begin{align}
    &\int_t^T \int_\Omega\beta(w_y^n-w_y^m) \cdot (w^n_t-w^m_t)=\beta \int_t^T\int_\Omega(w^n_y w_t^n+w_y^mw_t^m)-\beta \int_t^T\int_\Omega (w^n_y w^m_t+w_y^mw_t^n)\notag \\
  &\lim_{n \to 
       \infty}\lim_{m \to 
       \infty}\int_t^T\int_\Omega (w^n_y w_t^n+w_y^m w_t^m)= 2 \int_t^T\int_\Omega w_y w_t, \notag \\
  \intertext{\mbox{for the mixed terms we use the 
         weak convergence of $w_t$ in $L^2$ and strong convergence, }}
  &     
 \mbox{ of $w_y$ in $L^2$ to conclude }\lim_{n\to\infty}\lim_{m\to\infty}
		\int_{\Omega}\int_0^T \! \!(w^n_y w^m_t+w_y^m w_t^n)=2 \int_\Omega \int_0^T w_y w_t. \notag
 \end{align}
The above equalities then give us,
\begin{equation}\label{5}
   \lim_{n\to\infty}\lim_{m\to\infty} \int_t^T \int_\Omega\beta(w_y^n-w_y^m) \cdot (w^n_t-w^m_t)=0.
\end{equation}
Therefore we have shown that all the items \eqref{kappa} \eqref{adf}, \eqref{flim}, \eqref{5} on the right hand side of \eqref{subseq} goes to $0$ individually when taking the limits on the subsequences. This proves \eqref{subseq}.
Now for any given $\epsilon>0$, choosing sufficiently large $T$ in \eqref{id2} and choosing $\epsilon_0< \epsilon$ we have the Proposition \ref{thm:C17}  proved since the function $\mathcal{K}$ is continuous and zero at the origin. Thus we have, for any $\epsilon>0$
\begin{equation}\label{psinnm}
			\mbox{dist}_\cH(S_T\mbf{y}_1,S_T\mbf{y}_2) 
			\leq \epsilon + \Psi_{\epsilon,\cB,T}(\mbf{y}_1,\mbf{y}_2), \quad \mbf{y}_i \in \cB.
		\end{equation}
%\end{proof}
The proof of Theorem \ref{Asym-sm1} is completed by evoking Proposition \ref{thm:C17}. 
\end{proof}
%\end{proof}

\noindent We are now in a position to establish the existence of global attractors in both degenerate and non-degenerate cases-as stated in {\bf the first part of Theorem \ref{thm:Att}}. Indeed, this follows by combining the results of Theorem \ref{Asym-sm1} with Corollary \ref{ball} and the following known result:  

\begin{corollary}{[see \cite{Memoir}, page 18]}
    Let $(\cH, S_t)$ be an ultimately dissipative dynamical system in a complete metric space $\cH$. Then $(\cH, S_t)$ possesses a compact global $\mathfrak{A}$ if and only if $(\cH, S_t)$ is asymptotically smooth.  
\end{corollary}
\subsection{Proof of Theorem \ref{thm:Att}--Part II}\label{attractor11}
The next step is to prove {the second part of Theorem \ref{thm:Att}} under the stronger assumption $ g(0) =  b_0 >0$. In that case, we will be able to establish a stronger ``squeezing'': type of property referred to as {\it quasistability.} Quasi-stability is a powerful tool  used for characterization of   additional properties of attractors such as smoothness, dimensionality and  exponential attraction \cite{Memoir,LasMaMo}.



%\noindent{\Large \bf Quasistability.}\label{Quasistability} 

When $g(0)$ is positive i.e., $b_0>0$ in \eqref{aspg}, we have additional information regarding the geometry of the attractor $\mathfrak{A}$ which will be discussed in the next section.

