{\bf Step 1:} [Energy recovery Estimate.] 
We look at the difference of trajectories of two solutions. The following estimate holds. 
\begin{lemma}\label{lem:EE}
    Let $T>0$ arbitrarily fixed. Let also $\mbf{u}=\{u,u_t\}$ and $\mbf{v}=\{v,v_t\}$ be strong solutions of \eqref{sbe}-\eqref{IC} uniformly bounded in time, i.e. $\|\mbf{u}(t)\|_\cH,\|\mbf{v}(t)\|_\cH\leq R$ for every $t\geq0$ and for some $R>0$. Therefore, if $\mbf{z}=\mbf{u}-\mbf{v}$ then there are positive constants $C$ [independent on T]  and $C_{R,T}$ such that
    \begin{align}
        T\tilde{E}(\mbf{z}(T)) 
        + \int_0^T\!\!\tilde{E}(\mbf{z})
        \leq 
        C\left[\tilde{E}(\mbf{z}(0)) 
        + \int_0^T\!\!(F(u)-F(v),z)_\Omega
        + \int_0^T\!\!(F(u)-F(v),z_t)_\Omega \right. \notag\\ \left.
        + \int_0^T\!\!\int_t^T\!\!(F(u)-F(v),z_t)_\Omega \right]
        + C_{R,T}\lot{[0,T]}{z}, \label{lem:EE-ineq}
    \end{align}

    \begin{equation*}\label{lem:EE-lot}
       \mbox{where, }\quad \lot{[0,T]}{z} = \sup_{t\in[0,T]}\left\{\|z(t)\|_{2-\eta}^2:\eta\in(0,2]\right\}.
    \end{equation*}
\end{lemma}

\begin{proof}
    Let $z=u-v$ be the (strong) solution of the following  problem
    \begin{align}\label{abs-z}
        z_{tt} + Az + D(u_t)-D(v_t )= F(u)-F(v),
    \end{align}
    with the  initial data $\mbf{z}_0=\mbf{u}_0-\mbf{v}_0$.
    In addition, $\mbf{z}=\{z,z_t\}$ satisfies the energy identity
    \begin{equation}\label{lem:EE-01}
        \tilde{E}(\mbf{z}(t)) + \int_s^t(D(u_t)-D(v_t),z_t)_\Omega
        = \tilde{E}(\mbf{z}(s)) + \int_s^t(F(u)-F(v),z_t)_\Omega,\quad s\leq t.
    \end{equation}
    Let $T>0$ arbitrary. Applying \eqref{lem:EE-01} for $\{s,t\}=\{t,T\}$ and integrating over $[0,T]$, we obtain
    \begin{align}\label{lem:EE-02}
        T\tilde{E}(\mbf{z}(T)) + \int_0^T\!\!\int_t^T(D(u_t)-D(v_t),z_t)_\Omega
        = \int_0^T\tilde{E}(\mbf{z})
        + \int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega .
    \end{align}
    Multiplying \eqref{abs-z} by $z$ and integrating by parts over $(0,T)\times\Omega$, we obtain
    \begin{align}\label{lem:EE-04}
        2\int_0^T \tilde{E}(\mbf{z})
        = - \left.(z_t,z)_\Omega\right|_0^T
        + \int_0^T\left[ 2\|z_t\|_0^2
        - (D(u_t)-D(v_t),z)_\Omega \right]
        + \int_0^T(F(u)-F(v),z)_\Omega.
    \end{align}
    Combining \eqref{lem:EE-02} and \eqref{lem:EE-04} we have
    \begin{align}
        T\tilde{E}(\mbf{z}(T)) + \int_0^T \tilde{E}(\mbf{z})
        \leq
        - \left.(z_t,z)_\Omega\right|_0^T
        + \int_0^T\left[ 2\|z_t\|_0^2
        + |(D(u_t)-D(v_t),z)_\Omega| \right] \notag\\
        + \int_0^T(F(u)-F(v),z)_\Omega
        + \int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega. \label{lem:EE-03}
    \end{align}

    \noindent\textit{Pointwise energy terms:}
    The pointwise energy terms in the RHS of \eqref{lem:EE-03} are handle as follows
    \begin{equation}\label{lem:EE-PWT}
        |\left.-(z,z_t)_\Omega\right|_0^T|
        \leq 2\tilde{E}(\mbf{z}(0)) + \int_0^T\!\!(Fu-Fv,z_t)_\Omega,
    \end{equation}
    where we have used the ``energy identity'' \eqref{lem:EE-01} for $\{s,t\}=\{0,T\}$.

    \noindent\textit{Damping terms:}
    The damping terms in the RHS of \eqref{lem:EE-03} are handled next. Since $b_0 >0 $, the assumption (\ref{aspg} )  
    \begin{align}
        \quad  b_0\|z_t\|_0^2
        \leq(D(u_t)-D(v_t),z_t)_\Omega \quad \text{and} \label{lem:EE-05}
    \end{align}
    \hspace{1pt}
    \begin{align}
        &|(D(u_t)-D(v_t),z)_\Omega|
        =
        |(g(\|u_t\|_0)u_t - g(\|v_t\|_0)v_t,z)_\Omega| \notag\\
        &\leq
        b_0|(z_t, z)|
        +\sum_{j=1}^{q}b_j|(\|u_t\|_0^ju_t-\|v_t\|_0^jv_t,z)_\Omega| \notag\\
        &\leq
        \|z_t\|_0^2 + \frac{b_0^2}{4}\|z\|_0^2
        +\sum_{j=1}^{q}b_j
        \left[
            \|u_t\|_0^j|(z_t,z)_\Omega|
            +|(\|u_t\|_0^j-\|v_t\|_0^j)||(v_t,z)_\Omega|
        \right] \notag\\
        &\leq
        \|z_t\|_0^2 + \frac{b_0^2}{4}\|z\|_0^2
        +\sum_{j=1}^{q}b_j
        \left[
            \|u_t\|_0^j\|z_t\|_0\|z\|_0
            +\|z_t\|_0\left(\sum_{l=0}^{j-1}\|u_t\|_0^{j-1-l}\|v_t\|_0^{l}\right)\|v_t\|_0\|z\|_0
        \right] \notag\\
        &\leq 
        2\|z_t\|_0^2 + \frac{b_0^2}{4}\|z\|_0^2
        + \frac{1}{2}\left(\sum_{j=1}^{q}b_j\|u_t\|_0^j\right)^2\|z\|_0^2
        + \frac{1}{2}\left[\sum_{j=1}^{q}b_j\sum_{l=0}^{j-1}\|u_t\|_0^{j-1-l}\|v_t\|_0^{l+1}\right]^2\|z\|_0^2 \notag\\
        &\leq 
        2\|z_t\|_0^2 
        +\frac{1}{2}\left\{\frac{b_0^2}{2}+\left(\sum_{j=1}^{q}b_j\|u_t\|_0^j\right)^2
        + \left[\sum_{j=1}^{q}b_j\sum_{l=0}^{j-1}\|u_t\|_0^{j-1-l}\|v_t\|_0^{l+1}\right]^2
        \right\}\|z\|_0^2. \label{lem:EE-06}
    \end{align}
    Since $B$ is bounded forward invariant, we have
    \begin{equation}\label{lem:EE-07}
        \left\{\left(\sum_{j=1}^{q}b_j\|u_t\|_0^j\right)^2
        + \left[\sum_{j=1}^{q}b_j\sum_{l=0}^{j-1}\|u_t\|_0^{j-1-l}\|v_t\|_0^{l+1}\right]^2
        \right\}
        \leq C_{B,q},\quad\mbox{for}~t\geq0,
    \end{equation}
    for some positive constant $C_{B,q}$.
    Using \eqref{lem:EE-05} and \eqref{lem:EE-07}, it follows from \eqref{lem:EE-06} that
    \begin{align}\label{lem:EE-DT}
        \int_0^T\left[2\|z_t\|_0^2+|(D(u_t)-D(v_t),z)_\Omega|\right]
        &\leq 4\int_0^T\!\!(D(u_t)-D(v_t),z_t)_\Omega
        + C_{B,q}\int_{Q^T}|z|^2.
    \end{align}
    Combining \eqref{lem:EE-03} with \eqref{lem:EE-PWT} and \eqref{lem:EE-DT}, and using the ``energy identity'' \eqref{lem:EE-01}  in order to estimate $\int_0^T ( D(u_t) - D( v_t), z_t) dt $ we obtain
    \begin{align}
        T\tilde{E}(\mbf{z}(T)) + \int_0^T \tilde{E}(\mbf{z})
        %&\leq
        %E(\mbf{z}(T))+E(\mbf{z}(0)) + \frac{4}{b_0}\int_0^T\!\!(Du_t-Dv_t,z_t)_\Omega \notag\\
        %&\quad
        %+ \int_0^T(Fu-Fv,z)_\Omega
        %+ \int_0^T\!\!\int_t^T(Fu-Fv,z_t)_\Omega
        %+ C_{B,\varepsilon,q}\int_{Q^T}|z|^2 \notag\\
        \leq
        6\left[E(\mbf{z}(0))
        + \int_0^T(F(u)-F(v),z)_\Omega
        + \int_0^T(F(u)-F(v),z_t)_\Omega \right. \notag\\ \left.
        + \int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega \right]
        + C_{B,\varepsilon,q}\int_{Q^T}|z|^2. \label{lem:EE-08}
    \end{align}
    Inequality \eqref{lem:EE-ineq} thus follows from \eqref{lem:EE-08} by  adjusting the constants $C$ and $C_{R,T}$.
\end{proof}

\begin{remark}
    It is important to notice that the positive constant $C$ in Lemma \ref{lem:EE} above does not depend on time.
\end{remark}

The above Lemma provides an estimate for the energy of the difference of trajectories that are uniformly bounded in time. The above estimate  can  be  extended by density to all  generalized solution. This is done by  using density of $D(A)\times H^2_\ast$ in $\cH$.
We are now in position to prove Proposition \ref{pro:QS}.\\

{\bf Step 2: }[Completion of the Proof of Proposition \ref{pro:QS}.]
%\begin{proof}
    Let $B\subset\cH$ be a bounded forward invariant set. As observed before, it is sufficient to show that $\{\cH,S_t\}$ is asymptotically quasi-stable on $B$. If $\mbf{u}_0,\mbf{v}_0\in B$ and $\mbf{u}=\{u,u_t\}$ and $\mbf{v}=\{v,v_t\}$ are the corresponding (generalized) solutions of \eqref{sbe}-\eqref{IC}, we set $\mbf{z}=\mbf{u}-\mbf{v}$, solution to the problem \eqref{abs-z}, that verifies the following ``energy identity''
    \begin{align} \label{pro:QS-01}
        \tilde{E}(\mbf{z}(t)) + \int_0^t(D(u_t)-D(v_t),z_t)_\Omega
        = \tilde{E}(\mbf{z}(0)) + \int_0^t(F(u)-F(v),z_t)_\Omega,\quad t>0.
    \end{align}
    Since the damping operator $D$ is monotone and the operator $F$ is locally Lipschitz from $H^2_\ast$ to $L^2(\Omega)$ (see Lemmas \ref{lem:op_D} and \ref{lem:op_F}, respectively), inequality \eqref{pro:QS-01} implies
    \begin{align*}
        \tilde{E}(\mbf{z}(t))
        \leq \tilde{E}(\mbf{z}(0))
        + L_B\int_0^t \tilde{E}(\mbf{z}), \quad\mbox{for}~t>0,
    \end{align*}
    where $L_B>0$ is the Lipschitz constant of $F$ on $B$.
    Applying Gronwall's inequality and setting $h(t)=e^{tL_R}$, we conclude
    \begin{equation}\label{def:AQS-01}
        \|S_t\mbf{u}_0-S_t\mbf{v}_0\|_\cH^2
        \leq h(t)\|\mbf{u}_0-\mbf{v}_0\|_\cH^2,\quad\mbox{for}~t>0.
    \end{equation}
    Note that $h(t)$ is locally bounded in $[0,\infty)$. Next, by applying Lemma \ref{lem:EE}, we have
    \begin{align}
        T\tilde{E}(\mbf{z}(T))
        + \int_0^T\!\!\tilde{E}(\mbf{z})
        \leq C\left[\tilde{E}(\mbf{z}(0))
        + \int_0^T\!\!(F(u)-F(v),z)_\Omega
        + \int_0^T\!\!(F(u)-F(v),z_t)_\Omega \right. \notag\\ \left.
        + \int_0^T\!\!\int_t^T(F(u)-F(v),z_t)_\Omega \right]
        + C_{B,T}\lot{[0,T]}{z} \label{pro:QS-02}
        ,
    \end{align}
    for every $T\!>\!0$ and for some constant $C_{B,T}\!>\!0$, where lower order terms are given in \eqref{lem:EE-lot}.

    \noindent\textit{Source Terms.}
   For the source $F(u) - F(v)  $   we have 
   %Since $F$ is locally Lipschitz from $H^2_\ast$ to $L^2(\Omega)$, we have
    \begin{align} \label{pro:QS-02a}
        \abs{\int_0^T(F(u)-F(v),z)_\Omega}
        \leq L_B\int_0^T\!\!\|z\|_{2,\ast}\|z\|_0
        \leq \gamma\int_0^T\!\!\tilde{E}(\mbf{z})
        + \frac{L_B^2T}{4\gamma}\lot{[0,T]}{z},
    \end{align}
    for every $\gamma>0$ (arbitrarily small) , where $L_B>0$ is the Lipschitz constant of $F$ on $B$.
    And,
    \begin{align}
        (Fu-Fv,z_t)_\Omega
       \! =\! -\!\kappa(u^+\!-\!v^+,z_t)_\Omega
        \!+\! (\Lambda{u} \!-\! \Lambda{v},z_t)_\Omega
        - (f(u)-f(v),z_t)_\Omega
        - \beta(z_y,z_t)_\Omega, \label{pro:AC-08}
    \end{align}
    where $\Lambda u=(\alpha-\delta\|u_x\|_0^2)u_{xx}$ and similar expression holds for $\Lambda{v}$. Note
    \begin{align}
        \abs{-\kappa(u^+-v^+,z_t)_\Omega}
        \leq \gamma \tilde{E}(\mbf{z}) + \frac{\kappa^2}{2\gamma}\|z\|_0^2, \label{pro:AC-08_1}
    \end{align}
    for any $\gamma>0$. Also,
    \begin{align}
        \abs{\beta(z_y,z_t)_\Omega}
        \leq \gamma \tilde{E}(\mbf{z})
        + \frac{\beta^2}{2\gamma}\|z\|_{2-\eta}^2, \label{pro:AC-08_2}
    \end{align}
    for any $\gamma>0$ and some $\eta\in(0,2]$.
    Finally, calculations involving the $\Lambda$ operator  [terms of critical regularity] will follow the steps in \cite{BGLW22}. Integrating by parts in $\Omega$, and having in mind that the solutions $\mbf{u}=\{u,u_t\}$ and $\mbf{v}=\{v,v_t\}$ are strong, we have
    \begin{align}
        (\Lambda{u}-&\Lambda{v},z_t)_\Omega
        = \alpha(z_{xx},z_t)_\Omega
        + \delta(\|u_x\|_0^2u_{xx} - \|v_x\|_0^2v_{xx},z_t)_\Omega \notag\\
        %&= - \dfrac{d}{dt}\frac{\alpha}{2}\|z_x\|_0^2
        %-\delta(\|u_x\|_0^2z_{xx},z_t)_\Omega
        %-\delta([\|u_x\|_0^2-\|v_x\|_0^2]v_{xx},z_t)_\Omega \notag\\
        %&= - \dfrac{d}{dt}\frac{\alpha}{2}\|z_x\|_0^2
