        %&\quad
        %- \delta[\|u_x\|_0^2-\|v_x\|_0^2](v_{xx},z_t)_\Omega \notag\\
        &= \!- \dfrac{d}{dt}\left\{\frac{1}{2}\left[\alpha \!
        +\!\delta\|u_x\|_0^2\right]\|z_x\|_0^2\right\}
        \!-\! \delta\|z_x\|_0^2(u_{xx},u_t)_\Omega 
        + \delta[\|u_x\|_0^2\!-\!\|v_x\|_0^2](v_{xx},z_t)_\Omega  \label{pro:AC-08_3}
    \end{align}
    Integrating \eqref{pro:AC-08} over $[s,t]$, for $0\leq s < t\leq T$, and using \eqref{pro:AC-08_1}, \eqref{pro:AC-08_2} and \eqref{pro:AC-08_3} we obtain
    \begin{align*}
        \int_s^t\!\!(Fu-Fv,z_t)_\Omega
        &\leq 
        2\gamma\int_{\textcolor{black}{s/0}}^{\textcolor{black}{t/T}}\!\!\tilde{E}(\mbf{z})
        + \int_s^t\!\!(\Lambda{u}-\Lambda{v},z_t)_\Omega \notag\\
        &\quad
        \textcolor{black}{- or +} \int_s^t\!\!(fu-fv,z_t)_\Omega
        + \left(\frac{\kappa^2+\beta^2}{2\gamma}\right)(t-s)\sup_{[0,T]}\|z\|_{2-\eta}^2 \notag\\
        &\leq
        2\gamma\int_{0}^T\!\!\tilde{E}(\mbf{z})
        + \abs{\left.\frac{1}{2}[\alpha-\delta\|u_x\|_0^2]\|z_x\|_0^2\right|_s^t}
        + \delta\int_s^t\|z_x\|_0^2\|u_{xx}\|_0\|u_t\|_0 \notag\\
        &\quad
        + \delta\int_s^t\!\!\|z_x\|_0[\|u_x\|_0+\|v_x\|_0]\|v_{xx}\|_0\|z_t\|_0 \notag\\
        &\quad
        + \int_s^t\!\!(f(u)-f(v),z_t)_\Omega
        + \left(\frac{\kappa^2+\beta^2}{2\gamma}\right)(t-s)\sup_{[0,T]}\|z\|_{2-\eta}^2.
    \end{align*}
    Using once again the fact that solutions $\mbf{u}=\{u,u_t\}$ and $\mbf{v}=\{v,v_t\}$ belong to $B$ and, consequently, are uniformly bounded in $\cH$, we conclude
    \begin{align}
        \int_s^t\!\!(F(u)-F(v),z_t)_\Omega
        %&\leq 3\gamma\int_s^t\!\!E(\mbf{z})
        %+ C_B\sup_{[0,T]}\|z\|_{2-\eta}^2
        %+ C_B\delta T\sup_{[0,T]}\|z\|_{2-\eta}^2 \notag\\
        %&\quad
        %+ \int_s^t\!\!(fu-fv,z_t)_\Omega
        %+ \left(\frac{\kappa^2+\beta^2}{2\gamma}\right)T\sup_{[0,T]}\|z\|_{2-\eta}^2 \notag\\
        &\leq 3\gamma\int_s^t\!\!\tilde{E}(\mbf{z})
        + \int_s^t\!\!(f(u)-f(v),z_t)_\Omega
        + C_{B,T,\gamma}\sup_{[0,T]}\|z\|_{2-\eta}^2 \label{pro:QS-02b}
    \end{align}
    for $s\leq t$, every $\gamma>0$ and for some positive constant $C_{T,B,\gamma}$.
    Returning to \eqref{pro:QS-02} and using \eqref{pro:QS-02a} and \eqref{pro:QS-02b}, we obtain
    \begin{align}
        T\tilde{E}(\mbf{z}(T))
        + \int_0^T\!\!\tilde{E}(\mbf{z})
        \leq C\left[\tilde{E}(\mbf{z}(0))
        + \gamma(4+3T)\int_0^T\!\!\tilde{E}(\mbf{z}) 
        + (1+T)\int_0^T\abs{(f(u)-f(v),z_t)_\Omega} \right]
        \notag\\
        + \left[C_{B,T} + C\left(\frac{L_B^2T}{4\gamma} + (1+T)C_{B,T,\gamma}\right)\right]\lot{[0,T]}{z}. \label{pro:QS-03}
    \end{align}
    The last source term in the RHS of \eqref{pro:QS-03} is handled using the $C^1(\R)$ property of $f$ and the embedding $H^2_\ast\subset L^\infty(\Omega)$, as follows.
               \begin{align}
                          (1+T)\int_0^T&\abs{(f(u)-f(v),z_t)_\Omega}
                         \leq (1+T)\int_0^T\max_{|s|\leq\|u\|_{L^\infty(\Omega)}+\|v\|_{L^\infty(\Omega)}}|f'(s)| \|z\|_0\|z_t\|_0 \notag\\
                        &\leq \underbrace{(1+T)\max_{|s|\leq R_B}|f'(s)|}_{C_{f,T,B}}\int_0^T\|z\|_0\|z_t\|_0 \leq \gamma\int_0^T\!\!\tilde{E}(\mbf{z})
                          + \frac{T[C_{f,T,B}]^2}{4\gamma}\lot{[0,T]}{z}. \label{pro:QS-03a}
                \end{align}
    Combining \eqref{pro:QS-03} and \eqref{pro:QS-03a}, we conclude
                  \begin{align*}
                           T\tilde{E}(\mbf{z}(T)) + &(1-\gamma(5+3T)C)\int_0^T\!\!\tilde{E}(\mbf{z}) \notag\\
                          &\leq C\tilde{E}(\mbf{z}(0))
                           + \left[C_{B,T} + C\left(\frac{L_B^2T}{4\gamma} + (1+T)C_{B,T,\gamma} \frac{T[C_{f,T,B}]^2}{4\gamma}\right)\right]\lot{[0,T]}{z}.
                 \end{align*}
    Finally, choosing $\gamma=\gamma(T)>0$ small enough and $T>0$ sufficiently large, we arrive at
