        \tilde{E}(\mbf{z}(T))
        \leq &\underbrace{\frac{C}{T}}_{\theta}\tilde{E}(\mbf{z}(0))
        + \underbrace{\frac{1}{T}\left[C_{B,T} + C\left(\frac{L_B^2T}{4\gamma} + (1+T)C_{B,T,\gamma} + \frac{T[C_{f,T,B}]^2}{4\gamma}\right)\right]}_{C_{0,T,B}}\lot{[0,T]}{z} \notag\\
       &\leq \theta \tilde{E}(\mbf{z}(0)) + C_{0,T,B}\lot{[0,T]}{z},
    \end{align}
    where $0<\theta<1$ and $C_{0,T,B}>0$ is constant. Let us consider $m\in\N$. By standard iteration via semigroup property, the above inequality \eqref{pro:QS-04} implies
    \begin{align*}
        \tilde{E}(\mbf{z}(mT)) 
        %\leq \sigma E((m-1)T) + C_{0,T,B}\lot{[mT,(m-1)T]}{z} \notag\\
        \leq \theta^m \tilde{E}(\mbf{z}(0)) + C_{0,T,B}\sum_{j=0}^{m-1}\lot{[(m-j)T,(m-j-1)T]}{z}.
    \end{align*}
    Therefore, if $t>0$ then there exists $m\in\N$ such that $t=mT+r$, where $r\in[0,1]$ and, consequently,
    \begin{align*}
        \tilde{E}(\mbf{z}(t)) = C_A\tilde{E}(\mbf{z}(mT))
        %\leq C_A\theta^m E(\mbf{z}(0)) + C_AC_{0,T,B}\lot{[0,t]}{z} \notag\\
        %\leq C_Ae^{\ln \theta^m}E(\mbf{z}(0)) + C_AC_{0,T,B}\lot{[0,t]}{z} \notag\\
        \leq C_Ae^{-r\ln\theta/T}e^{\frac{\ln\theta}{T}t}\tilde{E}(\mbf{z}(0)) + C_AC_{0,T,B}\lot{[0,t]}{z},
    \end{align*}
    where $C_A>0$ is constant that depend on the linear semigroup generated by the plate operator $A$, and do not depend on $t$. Finally, the above inequality can be rewritten as follows
    \begin{equation}\label{def:AQS-02}
        \|S_t\mbf{u}_0-S_t\mbf{v}_0\|_\cH^2
        \leq \underbrace{C_Ae^{\frac{|\ln\theta|}{T}}}_{C_{A,T}}e^{\frac{\ln\theta}{T}t}\|\mbf{u}_0-\mbf{v}_0\|_\cH^2
        + \underbrace{2C_AC_{0,T,B}}_{d(t)} \lot{[0,t]}{z}.
    \end{equation}
    Set $g_0(t) = C_{A,T}e^{\frac{\ln\theta}{T}t}$, $d(t)=2C_AC_{0,T,B}$ and $\mu_{H^2_\ast}(u(s)-v(s))=\|u(s)-v(s)\|_{2-\eta}^2$, for $s\in[0,t]$ and for any $\eta\in(0,2]$. Notice that $l(t)$ is constant and, therefore, locally Lipschitz in $[0,\infty)$. Also $g_0(t)\in L^1(\R)$ with property $g_0(t)\to0$ as $t\to\infty$ ($0<\theta<1$). Finally, $\mu_{H^2_\ast}$ is a compact seminorm in $H^2_\ast$. 

    Inequalities \eqref{def:AQS-01} and \eqref{def:AQS-02} implies that $\{\cH,S_t\}$ is asymptotically quasi-stable on $B$ and, consequently, quasi-stable on $B$. Since $B$ is an arbitrary bounded forward invariant set on $\cH$, the proof is complete.
\end{proof}
%\end{proof}

\subsubsection[Dimension and regularity]{Fractal Dimension and Regularity of the Attractor -Completion of the Proof od Part II, Theorem \ref{thm:Att} }
The following geometrical properties of the attractor are a direct consequence of the asymptotic quasi-stability property proved in the previous section.

\begin{corollary}[Finite Fractal Dimension]\label{cor:FFD}
    $\mathfrak{A}$ has finite fractal dimension in $\cH$.    
\end{corollary}
\begin{proof}
    Under the assumption that $b_0 >0 $, the finite dimension of $\mathfrak{A}$ follows from Theorem 3.4.5 on \cite{Chu15} page 131.
\end{proof}

Since $\{\cH,S_t\}$ is quasi-stable on $\mathfrak{A}$ (see Definition \ref{def:QS}) for every $T>0$, an estimate for the fractal dimension of the attractor is also provided by Theorem 3.4.5 in \cite{Chu15}, namely
\begin{equation*}
    \textrm{dim}_f\mathfrak{A} \leq \left[\ln\frac{2}{1+p}\right]^{-1}\cdot\ln \textrm{m}_Z\left(\frac{4L_K}{1-p}\right)
\end{equation*}
where $0<p<1$ (depending on $T$),
$$Z=W_1(0,T)\equiv\left\{z\in L^2(0,T;H^2_\ast):\|z\|_Z^2\equiv \|z\|_{L^2(0,T;H^2_\ast)}^2+\|z_t\|_{L^2(0,T;L^2(\Omega))}^2<\infty\right\}$$
and $L_K$ is the Lipschitz constant of $K:\cH\to Z$ given by $K\mbf{y}_0 = y$ where $\{y(t),y_t(t)\}=S_t\mbf{y}_0$ is the corresponding (generalized) solution of \eqref{sbe}-\eqref{IC}, and $\textrm{m}_Z(R)$ is the maximum number of elements $z_i$ in the ball $\{z\in Z:\|z\|_Z\leq R\}$ possessing the property $$1<\textrm{n}_Z(z_i-z_j)\equiv C_T\sup_{s\in[0,T]}\|z_i(s)-z_j\|_0$$ 
for $i\neq j$, where $C_T>0$ is constant.
%\end{proof}

\begin{corollary}[Regularity]\label{cor:Reg}
 Under the assumption that $b_0>0$, any full trajectory \\ \(\gamma=\left\{\mbf{u}(t)=(u(t),u_t(t)):t\in\R\right\}\) that belongs to $\mathfrak{A}$ enjoys the  following regularity properties:
    \begin{equation*}
        u_t\in L^\infty(\R,H^2_\ast)\cap C(\R,L^2(\Omega))\quad\mbox{and}\quad u_{tt}\in L^\infty(\R,L^2(\Omega)).
    \end{equation*}
    Moreover, there exists $R>0$ such that
    \begin{equation*}
        \|u_t(t)\|_{2,\ast}^2 + \|u_{tt}(t)\|_0^2 \leq R,\quad t\in\R.
    \end{equation*}
\end{corollary}
\begin{proof}
    As in the proof of Proposition \ref{pro:QS}, the dynamical system $\{\cH,S_t\}$ is asymptotically quasi-stable on $\mathfrak{A}$, with \textit{stabilizability inequality}
    \begin{align}
        \|S_t\mbf{u}_0-S_t\mbf{v}_0\|_\cH^2
        \leq g_0(t)\|\mbf{u}_0-\mbf{v}_0\|_\cH^2
        + l(t)\sup_{0\leq s\leq t}\left[\mu_{H^2_\ast}(u(s)-v(s))\right]^2,\notag
    \end{align}
    for $\mbf{u}_0,\mbf{v}_0\in\mathfrak{A}$, 
    where $u$ and $v$ are the corresponding (generalized) solutions, and 
    $g_0(t) = ce^{-\omega t}$, for some constants $c>0$ and $\omega>0$, $l(t)>0$ is constant for every $t$, and $\mu_{H^2_\ast}(z)=\|z\|_{2-\eta}$, for $\eta\in(0,2]$ is a compact seminorm in $H^2_\ast$. Therefore, the conclusion follows from Theorem 3.4.19 in \cite{Chu15} page 140.
\end{proof}

\section{Proof of  Abstract Theorem \ref{0.5.1}}\label{ultdisabs}
\textbf{ Ultimate dissipativity for a model with non-conservative forces:}
In this section we provide a proof of the ultimate dissipativity property for a general abstract model with non-conservative force $ N(u)$.  Thus, the resulting model is non-dissipative where  classical Lyapunov's function approaches fail, as recognized in \cite{Memoir,BGLW22,pata} where various scenarios of  non-dissipative models were studied.  Particularly challenging is the case when {\it nonlinear damping }is also present in the system. This is the case under consideration below. The main idea of the proof is based nn the so called ``barrier's method'' inspired by works of \cite{haraux} where questions of ultimate boundedness of nonlinearly damped  abstract ``harmonic oscillator'' with non-autonomous forcing has been considered. 

With reference to the system $(\cH,S_t)$, under the assumptions formulated in Theorem  \ref{0.5.1},  the positive energy, the total energy  and the energy relation associated  with \eqref{model2} have the following form:
            \begin{align}
                  &E(u(t),u_t(t))\!=\!\frac{1}{2}\left(|\cA^{1/2}(u)|^2+ | u_t|^2\right)\!+\!\Pi_0(u), \quad \cE(u(t),u_t(t))\!=\!E(u(t),u_t(t))\!+\!\Pi_1(u),
                  \label{en1} \\ 
                 &\cE(u(t),u_t(t))+k\int_0^t(Du_t(s),u_t(s))ds= \cE(u_0,u_1)+\int_0^t(N(u(s)),u_t(s))ds.\label{en2}
            \end{align}
We also have the following inequality on energy which follows from the assumption \eqref{1.5} for $\eta=\frac{1}{4}$ and $c=c_\eta=c_{1/4}$;
     \begin{equation}\label{EnergyIn}
         \frac{1}{2}E(u,u_t)-c \leq \cE(u,u_t) \leq 2E(u,u_t)+c.
    \end{equation}

\begin{proof}{Proof of Theorem \ref{0.5.1}:}
   The proof is based on the barrier's method as discussed before. \\

   %In what follows we shall take  mass operator  $M\equiv \cI $, as an extension to more  general  mass operators is  relatively straightforward.  
   {\bf Step 1:} [Preliminaries.]
To begin with, consider the following   family of functionals
     \begin{equation}\label{lya}
         V_\varepsilon(u,u_t)= \cE(u,u_t)+\varepsilon (u_t,u), \quad \text{$\varepsilon >0$ .%will be chosen later.
         }
     \end{equation}
     Since $\cD(\cA^{\frac{1}{2}})$ is continuously embedded in $L_2(\Omega) $  we have that 
     \begin{equation}\label{eniq}
        (\cI u_t,u) \leq \frac{1}{2}\left(|u_t|^2+\lambda |\cA^{\frac{1}{2}}u|^2\right)\leq max\{1,\lambda\}E(u,u_t),
     \end{equation} where $\lambda> 0$ is the (embedding) constant. 
     Combining above inequality with \eqref{EnergyIn}, we deduce for some constants $C_1, C_2, c$,
     \begin{align}\label{V-E}
         C_1\cdot E(u,u_t)-c \leq V_\varepsilon(u, u_t) \leq C_2 \cdot E(u,u_t)+c.
     \end{align}
  Differentiating the function \eqref{lya} [justified for strong solutions], and replacing $\cE$ using $\eqref{eniq}$ yields, 
           \begin{align}
              \frac{d}{dt}V_\varepsilon&(u,u_t)
         = -\kappa(Du_t, u_t)+(N(u),u_t)+\varepsilon \cdot \left((u_t,u_t)+ (u_{tt},u) \right)\notag\\
         &=-\kappa(Du_t, u_t)\!+\!(N(u),u_t)+\varepsilon [c_0+c_1(Du_t, u_t)]+ \varepsilon \! \cdot \! \left(-\cA u-\kappa Du_t-\Pi^\prime(u)\!+\!N(u),u\right)\notag\\
               \intertext{\text{ using \eqref{A3b} and then assumption \eqref{A2}, \eqref{A3a} on the non-conservative term, we have}}
          & \quad \quad \quad +\varepsilon \left( \eta |\cA^{1/2} u|^2-c_2 \Pi_0(u)+c_3+c_4\left[1+E(u,u_t)\right]^\gamma (Du_t, u_t)\right) +\varepsilon c_0 \notag \\ 
          & \leq (-\kappa+\eta \kappa+\varepsilon c_1)(Du_t,u_t)+\delta E(u,u_t)-\varepsilon((1-\eta) |\cA^{1/2} u|^2-c_2 \Pi_0(u)) \notag \\
          & \quad \quad \quad +b(1/\delta)+\varepsilon c_4\left[1+E(u,u_t)\right]^\gamma (Du_t, u_t)+\varepsilon (c_0+c_3)\notag \\ 
            \intertext{\mbox{since $\!\varepsilon \!\left(\!-\!(1\!-\!\eta)|\cA^{1/2}u|^2\!-\!c_2\Pi_0(u) \!\right)\!\leq\! -\! 2d^\prime \varepsilon E(u,u_t)\!+\!d^\prime \varepsilon(u_t,u_t), d^\prime\!=\!min\{\!(1\!-\eta),c_2\}$}}
               & \quad  \text{using \eqref{A2}, }(u_t,u_t)\! \leq \! c_0+c_1(Du_t,u_t)] \text{and therefore}\notag \\
          & \leq (-\kappa+\eta \kappa+2\varepsilon c_1) (Du_t,u_t)+(\delta-2d^\prime \varepsilon) E(u,u_t) \notag \\
          & \quad \quad \quad +b(1/\delta)+\varepsilon \left(c_4\left[1+E(u,u_t)\right]^\gamma \right)(Du_t, u_t)+\varepsilon (2c_0+c_3) \notag \\
              \text{ since  }\eta<1,& \mbox{ suitable choice of } \varepsilon \mbox{ gives us } d_3'>0, \mbox{ where } d_3'=\kappa(1-\eta)-2\varepsilon c_1 \notag \\
            \intertext{\mbox{ as well as choose appropriate  $\delta $ proportional to $\varepsilon$  so that  $\delta< d^{\prime}\varepsilon$, for $d_0'=2c_0+c_3$ }}
          & \leq -\varepsilon E(u,u_t)+\varepsilon d_0'+b(1/\delta)+\big(-d_3'+\varepsilon \cdot c_4 \left[1+E(u,u_t)\right]^\gamma \big)(Du_t, u_t). \notag
    \end{align}
   Using the relation obtained in \eqref{V-E} in between the positive energy and the Lyapunov functional we get ($V_\varepsilon(t)$ should be understood as $V_\varepsilon(u(t),u_t(t))$),
\begin{equation*}
    \frac{d}{dt}V_\varepsilon(t) \leq -\frac{\varepsilon}{C_2}(V_\varepsilon(t)-c)+\varepsilon d_0'+b(1/\delta)+\big(\!\varepsilon \cdot c_4\left[1+E(t)\right]^\gamma -d_3'\big)(Du_t(t), u_t(t)),
   \end{equation*}
   once again by rescaling $\varepsilon:=\varepsilon/C_2$, 
   \begin{equation*}
       \frac{d}{dt}V_\varepsilon (t)\leq -\varepsilon V_\varepsilon(t)+\varepsilon c +\varepsilon d_0'+b(1/\delta)+\big(\varepsilon \cdot c_4 \left[1+E(u,u_t)\right]^\gamma -d_3' \big)(Du_t(t), u_t(t)).
   \end{equation*}
 For $d_0=c+d_0', d_2=c_4,  d_3=d_3'/d_2$ \mbox{ and }$ d_1$,\mbox{ satisfies } $b(d_1/\delta)\geq \frac{1}{d_0}b(1/\delta),$ \hfill \break
 rewriting the above inequality in terms of the new constants,
\begin{align}
 \frac{d}{dt}&V_\varepsilon(t) +\varepsilon V_\varepsilon(t) \leq d_0\!\left\{\varepsilon+ b\left(\frac{d_1}{\varepsilon}\right)\!\right\}+d_2\left\{\varepsilon \left[ 1+E(t)\right]^{\gamma} -d_3 \right\}\cdot(Du_t(t),u_t(t)), \notag \\
                      \intertext{\text{ multiplying by $e^{\varepsilon t}$ and integrating on $t\geq s \geq 0$ we get,}}
  %\frac{d}{dt}&\left(e^{\varepsilon\cdot t}V_\varepsilon(u,u_t)\right)  \leq e^{\varepsilon \! \cdot t} \! \! \cdot d_0\!\! \left\{\!\varepsilon+ b\left(\frac{d_1}{\varepsilon}\right)\!\!\right\}+e^{\varepsilon \cdot t} \cdot d_2\left\{\varepsilon \left[ 1+E(u,u_t)\right]^{\gamma} -d_3 \right\}\cdot(Du_t,u_t) \notag \\
                % &\text{integrating both side on $(s,t)$ we get,}\notag \\
       % &V_\varepsilon(u(t),u_t(t) \leq e^{-\varepsilon(t-s)}V_\varepsilon(u(s),u_t(s))+  \left(1-e^{-\varepsilon\cdot(t-s)}\right) \frac{d_0}{\varepsilon}\left\{\varepsilon+ b\left(\frac{d_1}{\varepsilon}\right)\!\right\}\notag \\
       %  &\hspace{2cm}+\int_s^te^{-\varepsilon\cdot(t-\tau)\!} \cdot d_2\left\{\varepsilon \left[ 1+E(u,u_t)\right]^{\gamma} -d_3 \right\}\cdot(Du_t,u_t) d\tau
    & V_\varepsilon(t) \leq e^{-\varepsilon(t-s)}V_\varepsilon(s)\!+ \! d_0\! \left\{\!\!1\!+\! \frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\!\!\right\}\notag \\
        &\quad \quad \quad \quad +\!d_2\int_s^t \!\!e^{-\varepsilon(t\!-\!\tau)}\left\{\varepsilon \left[\! 1\!+\!E(\tau)\right]^{\gamma}\! -\!d_3 \right\}\!\cdot\!(Du_t(\tau),u_t(\tau)\!) d\tau \label{55a}\\
                 % &\text{using the relation between kinetic energy and Lyapunov functional on \ref{V-E}, } \notag \\
       % V_\varepsilon&(t) \leq V_\varepsilon(s)+  d_0 \left\{1+ \frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\!\right\}+\int_s^t \!d_2\left\{\varepsilon \left[ 1+V_\varepsilon(\tau)\right]^{\gamma} -d_3 \right\}\cdot(Du_t(\tau),u_t(\tau)) d\tau  \\ 
             % & \mbox{ where }d_2=d_2 \cdot max\{1+\frac{c}{C_1},\frac{1}{C_1}\}, \quad d_3=d_2 d_3/d_2\text{} \notag
   & \mbox{or, }C_1 \cdot E \left(t \right)-c \leq e^{-\varepsilon(t-s)}\left(C_2 E(s)+c\right)+d_0\left\{1+\frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\right\}\notag \\
         &\hspace{2cm}+d_2 \int_s^te^{-\varepsilon(t-\tau)}\left\{\varepsilon \left[ 1+E(\tau)\right]^{\gamma} -d_3 \right\}(Du_t(\tau),u_t(\tau) )d\tau \notag\\
               \intertext{\text{using property of exponential function and rescaling of $d_i$  after dividing by $C_1$, we obtain}}
                 % &\text{ on both sides and let, $c_0=2c/C_1$  and rescaling $d_0$ again}\notag \\
       & E \left(t \right) \leq (C_2/C_1) \cdot E(u(s),u_t(s))+{\frac{2c}{C_1}}+d_0\left\{1+\frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\right\}\notag \\
       &\hspace{2cm}+d_2 \int_s^t e^{-\varepsilon\cdot(t-\tau)}\left\{\varepsilon \left[ 1+E(\tau)\right]^{\gamma} -d_3 \right\}(Du_t(\tau),u_t(\tau)) d\tau. \label{55b}
\end{align} 
 Note that achieving dissipativity from the above relation is straightforward when $\gamma=0$ by simply selecting $\varepsilon<d_3$. However, when $\gamma>0$, the integrand grows significantly. Trying to control  it by choosing a small $\varepsilon$ results in losing control over the third term, as its growth is impacted by $\frac{1}{\varepsilon}$. To address this second case, we continue the proof  in three distinct steps. Step 1 precisely shows that for a particular choice of $\varepsilon$ the integrand in the third term can be controlled.
 \paragraph{Step  2.} 
   We are now in position to apply barrier's method. The goal is to prove \eqref{55a} without the integral term. Let $\sigma:\mathbb{R}^+ \to \mathbb{R}^+\!-\!\{0\}$ is a map defined by $ E(t) \mapsto \sigma(E(t)) $  where $\sigma(E(t))$ is the solution of the following equation [we denote $\sigma(E(t))$ by $\sigma(t)$]

 \begin{equation}\label{sigma}
     \left[1+\frac{C_2}{C_1}E(t)+\frac{2c}{C_1}+d_0\left\{1+\sigma(t) \cdot b(d_1\sigma(t))\right\}\right]^\gamma=\frac{d_3\sigma(t)}{2}.
 \end{equation}
It is clear that the solution of the above equation not only exists but also unique  due to (\ref{balance}) and  as the left side is a continuous increasing function which exhibits slower growth rate than the right side due to $\gamma <1$. 
   We claim that $\mbox{for } \varepsilon_s:=\left[\sigma(s)\right]^{-1} $(the inverse function) the integrand 
 \begin{equation}\label{claim}
     \varepsilon_s \left[ 1+E(t)\right]^{\gamma} -d_3 \leq 0 \quad \mbox{ for all } t\geq s. 
 \end{equation} 
\begin{align*}\label{t=s}
      \mbox{at }t=s,\quad\varepsilon_s \left[ 1+E(s)\right]^{\gamma} -d_3 &\leq \varepsilon_s \left[1+\frac{C_2}{C_1}E(s)+\frac{2c}{C_1}+d_0\left\{1+\sigma(s) \cdot b(d_1\sigma(s))\right\}\right]^\gamma-d_3\notag \\
      &\leq \varepsilon_s \cdot \frac{d_3 \cdot \sigma(s)}{2}-d_3\leq\frac{-d_3}{2}<0,
  \end{align*}
  and the function $\varepsilon_s \left[ 1+E(t)\right]^{\gamma} -d_3$ is continuous hence there is an interval $[s,s+T)$ where \eqref{claim} holds. If $T$ is infinite then we are done. In the case of $T \!<\! \infty$ there must exists $T^\ast\!>\!s$ so that         \begin{equation}\label{Tast}
               \begin{cases}
                      \varepsilon_s \left[ 1+E(t)\right]^{\gamma} -d_3 < 0;\text{  for } t \in [s, s+T^\ast), \\
                     \varepsilon_s \left[ 1+E(t)\right]^{\gamma} -d_3 = 0;\text{  for } t=T^\ast
               \end{cases}
             \end{equation}
             \begin{equation}\label{Tast2}
                \mbox{applying \eqref{Tast} on \eqref{55a} we get, }\quad E \left(t \right) \leq \frac{C_2}{C_1} \cdot E(s)+{\frac{2c}{C_1}}+d_0\left\{1+\frac{1}{\varepsilon_s} b\left(\frac{d_1}{\varepsilon_s}\right)\right\}.
            \end{equation}
However, by \eqref{sigma} and \eqref{Tast2} give us, for $t \in [s, s+T^\ast)$
                   \begin{align}
                              \varepsilon_s \! \left[ 1\!+\!E(t)\right]^{\gamma} \!-\!d_3 \!\leq \!\varepsilon_s \left[ 1\!+\!\frac{C_2}{C_1} \cdot E(s)\!+\!{\frac{2c}{C_1}}\!+\!d_0\left\{1\!+\!\frac{1}{\varepsilon_s} b\left(\frac{d_1}{\varepsilon_s}\right)\right\}\right]^{\gamma} \!\!-\!d_3 \!\leq\! \varepsilon_s \frac{d_3\sigma(s)}{2}\!-\!d_3\!=\!\frac{-d_3}{2}.\notag
                      \end{align}

This is a contradiction to the fact that the function $\varepsilon \left[ 1+E(t)\right]^{\gamma} -d_3 $ is continuous at $T^\ast$.
 Which concludes that $\varepsilon \left[ 1+E(u(t),u_t(t))\right]^{\gamma} -d_3 \leq 0; \hspace{.4cm} \forall t\geq s$ when $\varepsilon=\sigma\left[E(u(s),u_t(s))\right]^{-1}.$
 \\
According to \eqref{claim}, we have
           \begin{equation}\label{21}
                      V_\varepsilon(t) \leq e^{-\varepsilon(t-s)}V_\varepsilon(s)+  d_0\left\{1+\frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\right\}\text{for }  t\geq s \geq 0,
           \end{equation}
  where,  $\varepsilon=\sigma(E(s))^{-1}$ and $\sigma$ satisfies \eqref{sigma}. In particular for $s=0, \varepsilon=\sigma(E(0))^{-1}$
              \begin{align}\label{22}
                      &V_\varepsilon(t) \leq e^{-\varepsilon t}V_\varepsilon(0)+  d_0\left\{1+\frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\right\}\text{for }  t \geq 0 \notag \\
                       \text{hence, }&V_\varepsilon(t) \leq V_\varepsilon(0)+  d_0\left\{1+\frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\right\}\text{for }  t \geq 0.
                \end{align}
\paragraph{Step 3.}  In this step we will prove that $V_\varepsilon(t)$ is uniformly bounded for all $t>0$ when $V_\varepsilon(u_0,u_1)\leq R$ for some $R>0$. From \eqref{22} we have,
        \begin{align}\label{23}
                &V_\varepsilon(t) \leq R+  d_0\left\{1+\frac{1}{\varepsilon_R} b\left(\frac{d_1}{\varepsilon_R}\right)\right\}=K_R(say)  \text{ for }t \geq 0 \quad \mbox{ implies }\sigma(V_\varepsilon(t))<\sigma(K_R) \notag\\
             &\mbox{or,  }\varepsilon(V_\varepsilon(s))>\varepsilon(K_R)= \varepsilon_R(say) \text{ for }s \geq 0,  \notag\\
                   &\text{which implies, } V_\varepsilon(t)\leq e^{-\varepsilon(V_\varepsilon(s)) (t-s)}V_\varepsilon(s)+d_0\left\{1+\frac{1}{\varepsilon} b\left(\frac{d_1}{\varepsilon}\right)\right\}\notag\\
                &\text{hence, }V_\varepsilon(t)\leq e^{-\varepsilon_R (t-s)}V_\varepsilon(s)+d_0\left\{1+\frac{1}{\varepsilon(V_\varepsilon(s))} b\left(\frac{d_1}{\varepsilon(V_\varepsilon(s))}\right)\right\} \text{ for }  t\geq s \geq 0.
           \end{align}
Define, $W_R(t)=\sup_{V_\varepsilon(0)\leq R}V_\varepsilon(t)$. Then from \eqref{23} we have, 
         \begin{align}\label{31}
                 &W_R(t)\leq e^{-\varepsilon_R (t-s)}W_R(s)+d_0\left\{1+\frac{1}{\varepsilon(W_R(s))} b\left(\frac{d_1}{\varepsilon(W_R(s))}\right)\right\} \text{ for }  t\geq s \geq 0 \notag \\
              & \text{ when } t\to \infty, \quad  W_R(\infty)\leq d_0\left\{1+\frac{1}{\varepsilon(W_R(s))} b\left(\frac{d_1}{\varepsilon(W_R(s))}\right)\right\} \text{ for }  s \geq 0 \notag \\
              & \text{ since } \varepsilon=\sigma^{-1},\quad W_R(\infty)\leq d_0\left\{1+\sigma(W_R(s)) b\left(\sigma(W_R(s))\right)\right\} \text{ for }  s \geq 0 \notag \\
               &\implies 1 \leq \frac{d_0}{W_R(\infty)}+\frac{d_0 \cdot \sigma(s) b\left(\sigma(s)\right) }{W_R(\infty)}, \quad \text{where } \sigma(s)=\sigma(W_R(s)).
             \end{align}
Note that it is sufficient to prove that $W_R (\infty)$ is bounded uniformly [does NOT depend on $R$] in order to claim the uniform bound on $V_\epsilon$.\\
 We prove this by contradiction. If our claim is not true then $W_R(\infty)\to\infty$, and we consider the following two cases:
\begin{itemize}
    \item Case 1: When $\sigma(s) b\left(\sigma(s)\right) \leq M$ for some $M>0; \forall s>0$, then \eqref{31} implies $1 \leq 0$!! Hence $W_R(\infty)$ is uniformly bounded from above.
    \item Case 2: When $\sigma(s) b\left(\sigma(s)\right)$ is not uniformly bounded, we observe the following:
    {\allowdisplaybreaks
                  \begin{align}\label{32}
                       &[1+C\cdot E+c_0+d_0\left(1+\sigma \cdot b(d_1\sigma)\right)]^\gamma=\frac{d_3\sigma}{2} \notag \\
                            &  \implies \frac{(1+c_0+d_0)}{\sigma^{1/\gamma}}+\frac{C \cdot E}{\sigma^{1/\gamma}}+d_0\frac{\sigma \cdot b(d_1\sigma)}{\sigma^{1/\gamma}}=\left[\frac{d_3}{2}\right]^{\frac{1}{\gamma}}, \notag \\
                                 \intertext{\text{taking limit $\sigma \to \infty,  \quad \lim_{\sigma \to \infty}\frac{C \cdot E}{\sigma^{1/\gamma}}+d_0 \cdot \lim_{\sigma \to \infty}\sigma^{1-1/{\gamma}}b(d_1\sigma)=\left[\frac{d_3}{2}\right]^{\frac{1}{\gamma}}$, }}
                            \text{using \eqref{A3a} we }\text{conclude that,}   \lim_{\sigma \to \infty}&\frac{C \cdot E}{\sigma^{1/\gamma}}=\left[\frac{d_3}{2}\right]^{\frac{1}{\gamma}}.
                 \end{align}}
     Since $V_\varepsilon$ is bounded by $E$ from below by \eqref{V-E}, using the above limit in \eqref{32} we obtain, $\lim_{\sigma \to \infty}\frac{V_\varepsilon}{\sigma^{1/\gamma}}\geq d_\gamma$ for some $d_\gamma(=C_1\left[\frac{d_3}{2}\right]^{\frac{1}{\gamma}}-c)$. On the other hand we have from \eqref{31} that, when $W_R(\infty) \to \infty$, 
    \begin{equation}\label{33}
        1 \leq 0+\lim_{W_R(\infty) \to \infty}\frac{d_0 \cdot \sigma(s) b\left(\sigma(s)\right) }{W_R(\infty)}\leq \lim_{W_R(\infty) \to \infty}\frac{d_0 \cdot \left( \sigma(s)\textcolor{black}{/ \sigma(s)^{\frac{1}{\gamma}}}\right) b\left(\sigma(s)\right) }{W_R(\infty)/\textcolor{black}{\sigma(s)^{\frac{1}{\gamma}}}}\leq \frac{d_0 \cdot 0}{d_\gamma}=0.
    \end{equation}
  We used the increasing properties of the function $\sigma$ and \eqref{32}.
    This contradicts  $W_R(\infty)\to \infty$. 
    \end{itemize}
    Hence, $W_R(\infty)$ is uniformly bounded i.e., there exists $V^\ast$(independent of $R$) so that, $W_R(\infty)<V^\ast$ and dissipativity follows from \eqref{V-E}. 
    We construct the forward invariant absorbing set $\cB_0$ by $\cB_0 := \bigcup_{t \geq t_{\cB}}S_t \cB$, where $\cB=\{(u,v) \in \cH: \|(u,v)\|_{\cH}^2 \leq R\}$ is absorbing set i.e., $S_t\cB \subset \cB$. This completes the proof of  abstract Theorem \ref{0.5.1}.
 \end{proof}
