\section{Appendix}
In this section, we prove the inequality that we have been using throughout the paper.
\begin{lemma}
Let $u\!=\!u(x, y, t)\! \in\! \cH^1(\Omega)$, where $\Omega\!=\![0, \pi] \times [-l, l]$  such that,
$u=0$ on $\{0, \pi \}\times [-l, l]$, there exists a constant $C>0$ such that $\int_\Omega |u|^2 \leq C\cdot \int _\Omega |u_x|^2$.
\end{lemma}
\begin{proof}
By the fundamental theorem of calculus, 
\begin{align}
    &  \text{since, } u(0,y)=0, \quad\int_0^x u_x(z,y)dz=u(x,y) \quad
     \mbox{implies,} \quad |u(x,y)| \leq  \int_0^x |u_x(z,y)|dz \notag \\
    & \text{applying Holder's Inequality, one can get,}\quad |u(x,y)| \leq  \left( \int_0^x |u_x(z,y)|^2dz \right)^\frac{1}{2} \cdot \left( \int_0^x |1|^2dz \right)^\frac{1}{2} \notag \\
    & \mbox{hence,} \quad |u(x,y)|^2 \!\leq\! \pi \cdot \int_0^\pi |u_x(z,y)|^2dz.\quad \text{Integrating on both sides with respect to $y$ we get,} \notag \\
    & \int_{-l}^{l} |u(x,y)|^2 dy \leq {\pi} \cdot \int_{-l}^{l}\int_0^\pi |u_x(z,y)|^2dz dy={\pi}\cdot \int_\Omega |u_x|^2 d\Omega. \quad \text{Once again integrating both }\notag \\
    &\mbox{the sides with respect to $x$,} \int_{\Omega} |u(x,y)|^2 dy dx \leq \left( {\pi}\cdot  \int_\Omega |u_x|^2 d\Omega \right)\int_0^\pi dx = C \cdot \int_\Omega |u_x|^2 d\Omega \notag
    \end{align}
    Hence, the theorem is proved with $C=\pi^{2}$.
\end{proof}

